/* Functional group: 01_MASTER_SETUP; referenced grouped tables: none detected */
/****** Object:  StoredProcedure [dbo].[CalculateAge]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- CalculateAge '2010-Sep-12'
CREATE PROCEDURE [dbo].[CalculateAge]
    @DateOfBirth DATE
AS
BEGIN
    DECLARE @Age INT;
    DECLARE @CurrentDate DATE;

    SET @CurrentDate = GETDATE();
    SET @Age = DATEDIFF(YEAR, @DateOfBirth, @CurrentDate);

    IF @Age > 14
    BEGIN
        SELECT @Age AS Age;
    END
    ELSE
    BEGIN
        SELECT 'Age must be greater than 14 years' AS Error;
    END
END;

GO



