/* Functional group: 01_MASTER_SETUP; referenced grouped tables: none detected */
/****** Object:  StoredProcedure [dbo].[Proc_GETYEAR]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Proc_GETYEAR]

AS
BEGIN
WITH RecursiveYears AS (
    SELECT 2019 AS Year
    UNION ALL
    SELECT Year + 1
    FROM RecursiveYears
    WHERE Year + 1 <= YEAR(GETDATE()) 
)
SELECT Year
FROM RecursiveYears
ORDER BY Year
END
GO



