/****** Object:  StoredProcedure [dbo].[procgetage]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[procgetage] 

(@dob datetime)

as
BEGIN
 DECLARE @years INT
 DECLARE @MONTH INT
 DECLARE @DAYS int
 --set @years=DATEDIFF(yy, @dob, Getdate())
 SELECT @years=YEAR,@MONTH=MONTH,@DAYS=DAYS FROM dbo.GetDateDifferenceInYearsMonthsDays(@dob,GETDATE())

 IF @MONTH>5  
 SELECT (@years+1)age
 ELSE IF
 @MONTH=5 AND @DAYS>29
 SELECT (@years+1)age
 ELSE 
 SELECT @years age
 
--SELECT @years age
end
GO



