/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: Company, trecruitappliedpost, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[GeneratelinkConfidential]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[GeneratelinkConfidential]    
@locid bigint,    
@deptid bigint,    
@companyid int,    
@postid varchar(100) ,  
@confidentiallink nvarchar(MAX)  
AS    
BEGIN     
UPDATE A    
SET A.Confidentialpostlink = @confidentiallink    
FROM trecruitpostlocationmap A    
INNER JOIN trecruitappliedpost B ON A.postid = B.postid    
INNER JOIN Company C ON B.IDCompany = C.companyPK    
WHERE A.locid = @locid AND B.Deptid = @deptid AND C.companyPK = @companyid AND A.postid = @postId     
    
    
    
END
GO



