/****** Object:  StoredProcedure [dbo].[GetAllconfidentialRecords]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/****** Script for SelectTopNRows command from SSMS  ******/                 
                
-- GetAllconfidentialRecords 1,10,'01/02/2023','15/05/2023',4               
                
                
CREATE PROCEDURE [dbo].[GetAllconfidentialRecords]                        
                       
       @PageIndex INT =null                          
      ,@PageSize INT = 10,                          
    @startdate varchar(50)=null,                          
       @enddate varchar(50)=null                          
      ,@RecordCount INT =null OUTPUT       
                        
   AS                        
BEGIN                        
      SET NOCOUNT ON;                        
                        
SELECT                         
      ROW_NUMBER() OVER                        
      (                        
            ORDER BY A.[registrationnumber] desc                         
      )AS RowNumber,                        
       A.[registrationnumber]                     
      --,Isnull([backgroundcheck],'SELECT')backgroundcheck                
   ,[backgroundcheck]                
      ,A.[aplicationdate]                        
      ,A.[username]                        
      ,A.[rscandidateid]                         
      ,A.[rscandidatename] candidatename                        
      ,A.[resumefile]                        
      ,A.[applicationstatus]                        
      ,A.[rspostname] postname                        
      ,A.[rspostid]                        
      ,A.[rslocid]                        
      ,A.[location]                        
      ,A.[deptdivision]                        
      ,A.[referredus]        
   ,A.[ReferredOthertext]        
      ,A.[trakerid]                        
      ,A.[referenceno]                        
      ,A.[departmentdivision]                        
      ,A.[departmentdivisonname]                        
      ,A.[rtpostid]                        
      ,A.[rtpostname]                        
      ,A.[rtlocid]                        
      ,A.[headq]                        
      ,A.[rtcandidateid]                        
      ,A.[rtcandidatename]                        
      ,A.[source]                        
      ,A.[STARTDATE]                        
      ,A.[cvselected]                        
      ,A.[manualupdate]                        
      ,A.[roneinterviewdate]                        
      ,A.[roneinterviewernameone]                        
      ,A.[roneinterviewernametwo]                        
      ,A.[roneselect]               
   ,A.[roneinterviewenddate]            
      ,A.[rtwointerviewdate]                        
      ,A.[rtwointerviewernameone]                        
      ,A.[rtwointerviewernametwo]                        
      ,A.[rtwoselect]             
   ,A.[rtwointerviewenddate]            
      ,A.[rthreeinterviewdate]                        
      ,A.[rthreeinterviewernameone]                        
      ,A.[rthreeinterviewernametwo]                        
      ,A.[rthreeselect]               
   ,A.[rthreeinterviewenddate]            
      ,A.[frinterviewdate]                        
      ,A.[frinterviewernameone]                        
      ,A.[frinterviewernametwo]                        
      ,A.[frselect]               
   ,A.[Frinterviewenddate]            
      ,A.[doo]                        
      ,A.[doj]                        
      ,A.[empcode]                        
      ,A.[completionstatus]                        
      ,A.[timetaken]                        
      ,A.[remarks]                        
      ,A.[createdby]                        
      ,A.[modifiedby]                        
      ,A.[modifiedtime]                        
      ,A.[rofileid]                        
      ,A.[rocandidateid]                        
      ,A.[rofname]                        
      ,A.[rofcontenttype]                        
      ,A.[rofresumefile]                        
      ,A.[ronerone]                        
      ,A.[rosname]         
      ,A.[roscontenttype]                        
      ,A.[rosresumefile]                        
      ,A.[ronertwo]                        
      ,A.[rtwfileid]           
      ,A.[rtwcandidateid]                        
      ,A.[rtwfname]                        
      ,A.[rtwfcontenttype]                        
      ,A.[rtwfresumefile]                        
     ,A.[rtworone]                        
      ,A.[rtwsname]                        
      ,A.[rtwscontenttype]                        
      ,A.[rtwsresumefile]                        
      ,A.[rtwortwo]                        
      ,A.[rthfileid]                        
      ,A.[rthcandidateid]                        
      ,A.[rthfname]                        
      ,A.[rthfcontenttype]                   
      ,A.[rthfresumefile]                        
      ,A.[rthworone]                        
      ,A.[rthsname]                        
      ,A.[rthscontenttype]                        
      ,A.[rthsresumefile]                        
      ,A.[rthwortwo]                       
      ,A.[fileid]                        
      ,A.[rfcandidateid]                        
      ,A.[fname]                        
      ,A.[fcontenttype]                        
      ,A.[fresumefile]                        
      ,A.[rfworone]                        
      ,A.[sname]                       
      ,A.[scontenttype]                        
      ,A.[sresumefile]                        
      ,A.[rfwortwo]                        
      ,A.[createdtime]                      
   ,[docsubmissionallow]                        
      INTO #Results                
  FROM [dbo].[vw_rcalldata] A       
  left join trecruitpostlocationmap B on A.rspostid=B.postid and A.rslocid=B.locid      
                      
  where convert(datetime,(convert(varchar, convert(datetime, [aplicationdate], 103), 101)),111)                             
    between                              
    convert(datetime,(convert(varchar, convert(datetime, @startdate, 103), 101)),111)                              
    and                               
    convert(datetime,(convert(varchar, convert(datetime, @enddate, 103), 101)),111)               
    and (B.Confidentialpost = '1' OR  A.rspostname  like 'ASSOCIATE%')      
                            
         
       SELECT @RecordCount = COUNT(*)                          
      FROM #Results                          
                         
               
                       
 SELECT * FROM #Results                          
      WHERE RowNumber BETWEEN(@PageIndex -1) * @PageSize + 1 AND(((@PageIndex -1) * @PageSize + 1) + @PageSize) - 1                          
   order by convert(datetime,(convert(varchar, convert(datetime, [aplicationdate], 103), 101)),111) desc                          
                           
      DROP TABLE #Results                
                      
                        
  end
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[GetCustomersPageWisetest_Mobile]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- GetCustomersPageWisetest_Mobile 1, 10, '01/05/2024', '01/07/2024'
CREATE PROCEDURE [dbo].[GetCustomersPageWisetest_Mobile]  
    @PageIndex INT = NULL, -- Ensure PageIndex starts at 1  
    @PageSize INT = NULL, -- Default page size  
    @startdate VARCHAR(50) = NULL,  
    @enddate VARCHAR(50) = NULL,  
    @RecordCount INT = NULL OUTPUT  
AS  
BEGIN  
    SET NOCOUNT ON;  
  
    -- Temporary results table  
    SELECT  
        ROW_NUMBER() OVER (ORDER BY A.[registrationnumber] DESC) AS RowNumber,  
        A.[registrationnumber],  
        A.[backgroundcheck],  
        A.[aplicationdate],  
        A.[username],  
        A.[rscandidateid],  
        A.[rscandidatename] AS candidatename,  
        --A.[resumefile],  
        A.[applicationstatus],  
        A.[rspostname] AS postname,  
        A.[rspostid],  
        A.[rslocid],  
        A.[location],  
        A.[deptdivision],  
        A.[referredus],  
        A.[ReferredOthertext],  
        A.[trakerid],  
        A.[referenceno],  
        A.[departmentdivision],  
        A.[departmentdivisonname],  
        A.[rtpostid],  
        A.[rtpostname],  
        A.[rtlocid],  
        A.[headq],  
        A.[rtcandidateid],  
        A.[rtcandidatename],  
        A.[source],  
        A.[STARTDATE],  
        A.[cvselected],  
        A.[manualupdate],  
        A.[roneinterviewdate],  
        A.[roneinterviewernameone],  
        A.[roneinterviewernametwo],  
        A.[roneselect],  
        A.[roneinterviewenddate],  
        A.[rtwointerviewdate],  
        A.[rtwointerviewernameone],  
        A.[rtwointerviewernametwo],  
        A.[rtwoselect],  
        A.[rtwointerviewenddate],  
        A.[rthreeinterviewdate],  
        A.[rthreeinterviewernameone],  
        A.[rthreeinterviewernametwo],  
        A.[rthreeselect],  
        A.[rthreeinterviewenddate],  
        A.[frinterviewdate],  
        A.[frinterviewernameone],  
        A.[frinterviewernametwo],  
        A.[frselect],  
        A.[Frinterviewenddate],  
        A.[doo],  
        A.[doj],  
        A.[empcode],  
        A.[completionstatus],  
        A.[timetaken],  
        A.[remarks],  
        A.[createdby],  
        A.[modifiedby],  
        A.[modifiedtime],  
        A.[rofileid],  
        A.[rocandidateid],  
        A.[rofname],  
        A.[rofcontenttype],  
        A.[rofresumefile],  
        A.[ronerone],  
        A.[rosname],  
        A.[roscontenttype],  
        A.[rosresumefile],  
        A.[ronertwo],  
        A.[rtwfileid],  
        A.[rtwcandidateid],  
        A.[rtwfname],  
        A.[rtwfcontenttype],  
        A.[rtwfresumefile],  
        A.[rtworone],  
        A.[rtwsname],  
        A.[rtwscontenttype],  
        A.[rtwsresumefile],  
        A.[rtwortwo],  
        A.[rthfileid],  
        A.[rthcandidateid],  
        A.[rthfname],  
        A.[rthfcontenttype],  
        A.[rthfresumefile],  
        A.[rthworone],  
        A.[rthsname],  
        A.[rthscontenttype],  
        A.[rthsresumefile],  
        A.[rthwortwo],  
        A.[fileid],  
        A.[rfcandidateid],  
        A.[fname],  
        A.[fcontenttype],  
        A.[fresumefile],  
        A.[rfworone],  
        A.[sname],  
        A.[scontenttype],  
        A.[sresumefile],  
        A.[rfwortwo],  
        A.[createdtime],  
        A.[docsubmissionallow]  
    INTO #Results  
    FROM [dbo].[vw_rcalldata] A  
    LEFT JOIN trecruitpostlocationmap C ON A.rspostid = C.postid AND A.rslocid = C.locid  
    WHERE CONVERT(DATETIME, (CONVERT(VARCHAR, CONVERT(DATETIME, [aplicationdate], 103), 101)), 111) BETWEEN  
          CONVERT(DATETIME, (CONVERT(VARCHAR, CONVERT(DATETIME, @startdate, 103), 101)), 111) AND  
          CONVERT(DATETIME, (CONVERT(VARCHAR, CONVERT(DATETIME, @enddate, 103), 101)), 111)  
      AND A.rspostname NOT LIKE 'ASSOCIATE%';  
  
    -- Get the total record count  
    SELECT @RecordCount = COUNT(*) FROM #Results;  
  
    -- Select paginated results  
    SELECT *  
    FROM #Results  
    WHERE RowNumber BETWEEN ((@PageIndex - 1) * @PageSize + 1) AND (@PageIndex * @PageSize)  
    ORDER BY CONVERT(DATETIME, (CONVERT(VARCHAR, CONVERT(DATETIME, [aplicationdate], 103), 101)), 111) DESC;  
  
    DROP TABLE #Results;  
END
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: Company, trecruitappliedpost, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[GETpostidlocwise]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- GETpostidlocwise 12,3,1
CREATE PROCEDURE [dbo].[GETpostidlocwise]      
@locationid int,      
@deptid bigint,      
@companyid int      
AS      
BEGIN       

SELECT TOP 1 A.postid
FROM trecruitpostlocationmap A
INNER JOIN trecruitappliedpost B ON A.postid = B.postid
INNER JOIN Company C ON B.IDCompany = C.companyPK
WHERE locid = @locationid AND Deptid = @deptid AND C.companyPK = @companyid
  AND A.Confidentialpost = 1
ORDER BY A.postid DESC;

      
END
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: tbl_postActivePermission, tbl_RecruiterHR_Details, tbl_recruitPostActiveInactivStatus, trecruitappliedpost, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[porc_GetApprovablePost]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO



CREATE PROC [dbo].[porc_GetApprovablePost]             
@empNo VARCHAR(100)=null,        
@deptIdPost varchar(100)=null,       
@ActualPostID varchar(100)=null,      
@locationID varchar(100)=null,      
@deptID varchar(100)=null,      
@reason varchar(max)=Null,        
@plmapid varchar(100) =NULL,        
@approvableID varchar(100) =NULL,        
@permissionStatus varchar(100)=NULL,        
@action nvarchar(100)        
AS             
  BEGIN         
    DECLARE @MdEmpNo bigint=dbo.GetCompanyMDEmpNo()    
    DECLARE @HodAndMdEmpNo bigint        
 --SELECT @HodAndMdEmpNo=empno FROM [abcinfotechpvtltdESSP].dbo.Employee_DepartmentHODMap where empno=@empNo --and DepartmentID =@deptID        
  SELECT @HodAndMdEmpNo=EmpId FROM tbl_postActivePermission where EmpId=@empNo --and DepartmentID =@deptID   
 if @empNo=@MdEmpNo        
 BEGIN        
  SET @HodAndMdEmpNo=@MdEmpNo        
 END        
 if @action='SELECT'        
 BEGIN        
   --Select  C.ID,B.plmapid,C.ID AS approvableID,D.postname ,(A.empfirstname + ' ' + A.empmiddlename + ' ' + A.emplastname)CreatedBy,FORMAT(B.Createdtime,'dd-MM-yyyy')AS Createdtime,        
   --CASE         
   --  WHEN C.Status = 0 THEN 'Request'        
   --  WHEN C.Status = 1 THEN 'Approved'        
   --  WHEN C.Status = 2 THEN 'Reject'        
   --  ELSE 'Unknown'        
   -- END AS Status,        
   --C.Reason         
   --from [abcinfotechpvtltdESSP].dbo.Empbasic A        
   --INNER JOIN [trecruitpostlocationmap] B ON A.empemail COLLATE Latin1_General_CI_AI = B.createdby COLLATE Latin1_General_CI_AI        
   --INNER JOIN tbl_postActivePermission C ON A.empno=C.EmpId        
   --Inner JOIN vw_Recruitment_AllPost D ON D.plmapid =B.plmapid         
   --where B.plmapid in (Select Plmapid from tbl_postActivePermission where EmpId=@HodAndMdEmpNo)       
   --AND (@deptIdPost IS NULL OR D.DeptId =@deptIdPost)          
   --AND (@ActualPostID IS NULL OR D.postid IN (Select CAST(postid AS INT)AS PostId from trecruitappliedpost where ActualPostID =@ActualPostID))       
   --AND (@LocationId IS NULL OR D.locid =@locationID)       
   --Order by B.Createdtime desc    
   Select  A.ID,B.plmapid,A.ID AS approvableID,B.postname ,(C.empfirstname + ' ' + C.empmiddlename + ' ' + C.emplastname)CreatedBy,FORMAT(B.Createdtime,'dd-MM-yyyy')AS Createdtime,        
   CASE         
     WHEN A.Status = 0 THEN 'Request'        
     WHEN A.Status = 1 THEN 'Approved'        
     WHEN A.Status = 2 THEN 'Reject'        
     ELSE 'Unknown'        
    END AS Status,        
   A.Reason      
  from   tbl_postActivePermission A    
  INNER JOIN vw_Recruitment_AllPost B on B.plmapid=A.PlmapId    
  INNER JOIN [ESSP].dbo.Empbasic C on A.CreatedBy=C.Empno    
  Where A.EmpId=@HodAndMdEmpNo   
  AND (@deptIdPost IS NULL OR B.DeptId =@deptIdPost)
  AND (@ActualPostID IS NULL OR B.postid IN (Select CAST(postid AS INT)AS PostId from trecruitappliedpost where ActualPostID =@ActualPostID)) 
  AND (@LocationId IS NULL OR B.locid =@locationID)     
  Order by B.Createdtime    

  
 END        
 ELSE IF @action='PostPermission'        
   BEGIN        
    BEGIN TRY                                  
    BEGIN TRANSACTION;         
     UPDATE tbl_postActivePermission SET Status=@permissionStatus,StatusDate=GETDATE(),Reason=@reason        
     WHERE  ID=@approvableID AND PlmapId=@plmapid        
     --When Full Approve HOD AND MD and send the mail       
     if  (Select Status from tbl_postActivePermission WHERE PlmapId =@plmapid AND EmpId <> @HodAndMdEmpNo AND ID <> @approvableID)=1        
      BEGIN      
      IF @permissionStatus=1        
      BEGIN     
	  
	  UPDATE trecruitpostlocationmap 
	  SET FullApprove=1,      
		   Activeflag='Y'				
      WHERE  plmapid=@plmapId 


		 INSERT tbl_recruitPostActiveInactivStatus        
		 (plmapid,ActiveInactiveDate,Activeflag)        
		 VALUES(@plmapid,GETDATE(),'Y')        
		  END      
      
    --Mail send end      
    DECLARE @RecruiterHRM nvarchar(max)      
       SELECT @RecruiterHRM = STRING_AGG(A.empemail, ';')         
    from ESSP.dbo.Empbasic A      
    INNER JOIN tbl_RecruiterHR_Details B ON A.empno=B.Empno      
      
    DECLARE @tableHTML NVARCHAR(MAX);          
    DECLARE @departmentNameMail NVARCHAR(MAX);         
    DECLARE @subjectMail NVARCHAR(MAX);         
    DECLARE @postNameMail NVARCHAR(MAX);         
    DECLARE @locationMail NVARCHAR(MAX);      
      
    SELECT         
     @postNameMail = B.postname,        
@departmentNameMail = A.deptname,        
     @locationMail = A.location        
    FROM vw_Recruitment_AllPost A        
    INNER JOIN trecruitappliedpost B ON B.postid = A.postid        
    WHERE A.plmapid = @plmapid;        
    set @subjectMail='Post Creation Request: ' + @postNameMail + '-' + @departmentNameMail + ' - ' + @locationMail;       
      SET @tableHTML='<html>        
     <body style="font-family:Tahoma;font-size:14px;">        
      <p>Dear Sir/Madam,</p>        
      <p>The requisition for the following position has been approved by both the Department Head and the Managing Director.</p>        
      <br/>        
       <table border="1" cellpadding="8" cellspacing="0" style="border-collapse:collapse;font-size:14px;">        
        <tr style="background-color:#f2f2f2;">        
         <th>Post Name</th>        
         <th>Department</th>        
         <th>Location</th>        
        </tr>        
        <tr>        
         <td>' + @postNameMail + '</td>        
         <td>' + @departmentNameMail + '</td>        
         <td>' + @locationMail + '</td>        
        </tr>        
       </table>        
       <br/>         
      <p>Kindly note the following instructions:</p>      
      <br/>      
      <p><b>1.Review the attached JD thoroughly.</b></p>      
      <p><b>2.Initiate the recruitment process for the position.</b></p>      
      <p><b>3.Please  set the deadline.</b></p>      
       <br/>      
                         <p>Thank You.</p>      
      </body>        
    </html>'      
    -- Send Email using Database Mail        
    EXEC msdb.dbo.sp_send_dbmail                                                            
    @profile_name = 'Mendine_Recruitment_Profile'                                               
      ,@recipients = @RecruiterHRM                                                    
      ,@subject = @subjectMail                                                    
      ,@body =                    
    @tableHTML                                                    
      ,@importance ='HIGH'                  
      ,@body_format = 'HTML'       
   --Mail send end      
     --When Full Approve HOD AND MD and send the mail end      
      END        
           
               
          
            COMMIT TRANSACTION;                                         
        END TRY                                  
        BEGIN CATCH                                  
         ROLLBACK TRANSACTION;                                  
        END CATCH        
   END        
  end        
GO



