if (@SearchValue !='' OR @ColumnName !='')-- Search Call on List Page                    
Begin                    
 if (@ColumnName='RSCANDIDATENAME')                    
 Begin                    
   Insert into @TB                    
   (SRL,registrationnumber, [backgroundcheck],                 
