/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: tbl_recruitPostActiveInactivStatus, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[PRC_APTIVE_POST_UPDATE]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[PRC_APTIVE_POST_UPDATE]        
@id bigint,          
@status bit          
AS          
BEGIN          
DECLARE @status_sp varchar(10)
   BEGIN TRY              
            BEGIN TRANSACTION;
				if @status=1          
				BEGIN          
				set @status_sp='Y'       
				 Insert tbl_recruitPostActiveInactivStatus(plmapid,ActiveInactiveDate,Activeflag)      
				   values(@id,getdate(),'Y');      
				END              
				ELSE          
				BEGIN          
				 SET @status_sp='N'      
				   Insert tbl_recruitPostActiveInactivStatus(plmapid,ActiveInactiveDate,Activeflag)      
				   values(@id,getdate(),'N');      
				END              
				UPDATE trecruitpostlocationmap set Activeflag=@status_sp where plmapid=@id         
				COMMIT TRANSACTION;                     
        END TRY              
        BEGIN CATCH              
            ROLLBACK TRANSACTION;               
        END CATCH;    
END      
GO



