@postName varchar(500),      
@postID varchar(500)=null,  
@actualPostID varchar(500)=null,  
@locid bigint,                                    
@username varchar(50) ,                          
@jobdescription nvarchar(MAX),                                      
@qualification nvarchar(MAX),                                      
@experience nvarchar(MAX),                                      
@age nvarchar(MAX),                                      
@responsibility nvarchar(MAX),                                      
@vacancy nvarchar(MAX),                                      
@jobnature nvarchar(MAX),                                      
@technicalscope nvarchar(MAX),                                      
@administrativescope nvarchar(MAX),                                      
@reporttopost nvarchar(MAX),                                      
@compensate nvarchar(MAX),                                      
