	@Exam_Id int =NULL

--@status VARCHAR(MAX) = NULL OUTPUT 
            
            
AS                                      
BEGIN                                      
DECLARE @Deptname varchar(max)                                      
     
DECLARE @plmapid bigint      
DECLARE @location varchar(max)      
DECLARE @createDate Datetime      
set @createDate=getdate();      
                          
 if exists(select Company from [dbo].[Company] where companypk=@companyid)                                  
 begin                                
 print 'This Company already exists!'                                
 end                                
else                                
begin                                       
                          
INSERT INTO [dbo].[Company]                                    
               ([companyPK])                                    
        VALUES                                    
     (upper(@companyid))                                                                      
end                                 
            
      
SELECT @Deptname=[Deptname]                                      
  FROM [dbo].[trecruitdepartment]                                      
  WHERE id= @deptid                                    
  IF @postID IS NULL OR LTRIM(RTRIM(@postID)) = ''     OR @actualPostID IS NULL OR LTRIM(RTRIM(@actualPostID)) = ''   BEGIN    --Get ActualPostID Start    
   Declare @ActualPostIDTbl Int    
   if exists (Select * From trecruitappliedpost   where ltrim(rtrim(postname)) = ltrim(rtrim( upper(@postName))))    
    BEGIN    
     Select @ActualPostIDTbl=ActualPostID From trecruitappliedpost   where ltrim(rtrim( postname)) = ltrim(rtrim(upper(@postName)))    
    END    
    ELSE    
    BEGIN    
    SELECT Top 1  @ActualPostIDTbl=ActualPostID+1  FROM [Recruitment].dbo.trecruitappliedpost GROUP BY ActualPostID Order by ActualPostID desc    
      END    
  --Get ActualPostID End   
   INSERT INTO [dbo].[trecruitappliedpost]                                      
    ([postname],                                      
     status ,                                    
     [Deptid],                          
     IDCompany,                          
     CreatedBy,                                      
     Createdtime,    
     ActualPostID    
      )                                      
    VALUES                                      
       (upper(@postName),                                      
     0,                                      
     @deptid,                          
           @companyid,                          
              @username,                          
        @createDate,    
              @ActualPostIDTbl)   
  
  SELECT @postid= @@IDENTITY              
  End  
ELSE  
  BEGIN   
  Update trecruitappliedpost set  Deptid=@deptid ,IDCompany=@companyid  
  where postid=@postID  and ActualPostID=@actualPostID  
  END  
  
   
     
SELECT @location=location                                   
  FROM [dbo].[trecruitpostlocation]                                      
  WHERE  [locid]=@locid                                      
   
   
  BEGIN TRY                        
     BEGIN TRANSACTION;   
  


   ---------------------------------------------------------  
    -- Exam Tagging Update  
    ---------------------------------------------------------  
  
    

   INSERT INTO [dbo].[trecruitpostlocationmap]                                      
				([postid],                                      
				[locid],                                      
				[Activeflag] ,                             
			  JobDescription,                                      
			  Qualifications ,          
			   Experience   ,                                   
			   Age ,                                   
			  Jobresponsibility ,                                     
			  Jobvacancy  ,                                   
			  Jobnature  ,                                   
			  TechnicalScope ,                                    
				AdministrativeScope ,                                  
				Reporttopost ,                                     
			   Compensate ,                                    
			   Others   ,                         
			 DeadLine,             
			 [Confidentialpost],                  
			 [createdby] ,                                     
		   [Createdtime],            
		   [TypeFresher],            
		   [TypeExperienced],            
		   [TypeSalesExperienced],   
		   [ATS_HEAD_RATING_ID],
		   [Objectives],
		   [JobTitle],
		   [JobDescriptionFilePath],
		   [JobDescriptionFileExtension]
   )                                      
     VALUES                                      
        (@postID,                                      
        @locid,                                      
      'Y',                   
      @jobdescription,                                      
      @qualification,                                      
      @experience,                                      
      @age,                                      
      @responsibility,                                      
      @vacancy,                                      
      @jobnature,                                      
      @technicalscope,                                      
      @administrativescope,                                               
      @reporttopost,                                      
      @compensate,                                      
      @other,                             
      @deadline,                
      @Isconfidential,                
      @username ,                                     
        @createDate,            
      @TypeFresher,            
      @TypeExperienced ,            
      @TypeSalesExperienced,  
      @Ats_Head_Rating_ID,
	  @objectives ,--  
	  @jobTitle , --
      @jobDescriptionFilePath, --
      @jobDescriptionFileExtension  --
        )                                       
    SELECT @plmapid=@@IDENTITY      
    Insert tbl_recruitPostActiveInactivStatus(plmapid,ActiveInactiveDate,Activeflag)      
      values(@plmapid,getdate(),'Y');  
	       
	--Lms exam taging start
	UPDATE trecruitappliedpost    
	SET ExamTaggingID = @Exam_Id
	where postid=@postID  
	--Lms exam taging end
   COMMIT TRANSACTION;                               
   END TRY                        
   BEGIN CATCH                        
      ROLLBACK TRANSACTION;                        
                        
   END CATCH;     
END
