GO
CREATE PROC [dbo].[PRC_CREATE_ACTIVE_POST]                               
@companyid int,                                   
@deptid bigint,                                          
@postName varchar(500),              
@postID varchar(500)=null,          
@actualPostID varchar(500)=null,          
@locid bigint,                                            
@username varchar(50) ,                                  
@jobdescription nvarchar(MAX),                                              
@qualification nvarchar(MAX),                                              
@experience nvarchar(MAX),                                              
@age nvarchar(MAX),                                              
@responsibility nvarchar(MAX),                                              
@vacancy nvarchar(MAX),                                              
@jobnature nvarchar(MAX),                                              
@technicalscope nvarchar(MAX),                                              
@administrativescope nvarchar(MAX),                                              
@reporttopost nvarchar(MAX),                                              
@compensate nvarchar(MAX),                                              
@other nvarchar(MAX),                                              
@deadline nvarchar(MAX),                        
@Isconfidential varchar(10),                    
@TypeFresher varchar(max) =null,                    
@TypeExperienced varchar(max)=null,                    
@TypeSalesExperienced varchar(max)=null,      
@EmpDeptId varchar(50),  
@status varchar(max)=null output          
                    
                    
AS                                              
BEGIN                                
      
DECLARE @HodId int =NULL          
DECLARE @MdId  int =100003      
      
      
DECLARE @Deptname varchar(max)                                              
             
DECLARE @plmapid bigint              
DECLARE @location varchar(max)              
DECLARE @createDate Datetime              
set @createDate=getdate();              
 
 
  if exists (Select empno  from essp.dbo.Employee_DepartmentHODMap Where       
       Activeflag=1      
       and DepartmentID=@EmpDeptId)  
  BEGIN   

 if exists(select Company from [dbo].[Company] where companypk=@companyid)                                          
 begin                                        
		print 'This Company already exists!'                                        
 end                                        
else                                        
begin                                               
                                  
	INSERT INTO [dbo].[Company]                                            
               ([companyPK])                                            
        VALUES                                            
     (upper(@companyid))                                                                              
	end                                         
                    
              
SELECT @Deptname=[Deptname]                                              
  FROM [dbo].[trecruitdepartment]                                              
  WHERE id= @deptid      
        
 IF @postID IS NULL OR LTRIM(RTRIM(@postID)) = ''     OR @actualPostID IS NULL OR LTRIM(RTRIM(@actualPostID)) = ''    
 BEGIN    --Get ActualPostID Start            
      Declare @ActualPostIDTbl Int            
     if exists (Select * From trecruitappliedpost   where ltrim(rtrim(postname)) = ltrim(rtrim( upper(@postName))))            
   BEGIN            
    Select @ActualPostIDTbl=ActualPostID From trecruitappliedpost   where ltrim(rtrim( postname)) = ltrim(rtrim(upper(@postName)))            
   END            
   ELSE            
   BEGIN            
          SELECT Top 1  @ActualPostIDTbl=ActualPostID+1  FROM [Recruitment].dbo.trecruitappliedpost GROUP BY ActualPostID Order by ActualPostID desc            
    END      
    --New Access parmision      
        
  --if @HodId <> null  
  
    Select @HodId=empno  from essp.dbo.Employee_DepartmentHODMap Where       
     Activeflag=1      
     and DepartmentID=@EmpDeptId
          --Get ActualPostID End           
           INSERT INTO [dbo].[trecruitappliedpost]                                              
         ([postname],                                              
          status ,                                            
          [Deptid],                                  
          IDCompany,                                  
          CreatedBy,                                              
           Createdtime,            
          ActualPostID            
           )                                              
         VALUES                                              
        (upper(@postName),                                              
          0,                                              
          @deptid,                                  
             @companyid,                                  
             @username,                                  
          @createDate,            
             @ActualPostIDTbl)       
          SELECT @postid= @@IDENTITY                      
          End          
        ELSE          
          BEGIN           
          Update trecruitappliedpost set  Deptid=@deptid ,IDCompany=@companyid          
          where postid=@postID  and ActualPostID=@actualPostID          
          END          
             
        SELECT @location=location                                           
          FROM [dbo].[trecruitpostlocation]                                              
          WHERE  [locid]=@locid                                              
           
          BEGIN TRY                                
          BEGIN TRANSACTION;           
          INSERT INTO [dbo].[trecruitpostlocationmap]                                              
            ([postid],                                              
            [locid],                                              
            [Activeflag] ,                                     
          JobDescription,                                              
          Qualifications ,                  
           Experience   ,                                           
           Age ,                                           
          Jobresponsibility ,                                             
          Jobvacancy  ,                                           
          Jobnature  ,                                           
          TechnicalScope ,                                            
            AdministrativeScope ,                                          
            Reporttopost ,                                             
           Compensate ,                                            
           Others   ,                                 
            DeadLine,                     
            [Confidentialpost],                          
            [createdby] ,                                             
          [Createdtime],                    
          [TypeFresher],                    
          [TypeExperienced],                    
          [TypeSalesExperienced]                            
            )                                              
            VALUES                                              
            (@postID,                                              
            @locid,                                              
          'N',                           
          @jobdescription,                                              
          @qualification,                                              
          @experience,                                              
          @age,                                              
          @responsibility,                                              
          @vacancy,                                              
          @jobnature,                                           
          @technicalscope,                                              
          @administrativescope,                                                       
          @reporttopost,                                              
          @compensate,                                              
          @other,                                     
          @deadline,                        
          @Isconfidential,                        
          @username ,                                             
            @createDate,                    
          @TypeFresher,                    
          @TypeExperienced ,                    
          @TypeSalesExperienced                     
            )                                               
         SELECT @plmapid=@@IDENTITY         
     
      
    
          Insert tbl_postActivePermission      
          (PlmapId,EmpId,Status,StatusDate)      
          values(@plmapid,@HodId,0,getdate());      
         
           Insert tbl_postActivePermission      
            (PlmapId,EmpId,Status,StatusDate)      
           values(@plmapid,@MdId,0,getdate());    
             
           --Mail Fiend  
           --DECLARE @MailId NVARCHAR(MAX)='tapumondal5g@gmail.com;saikatmca2022@gmail.com';   
           DECLARE @MailId NVARCHAR(MAX);    
           SELECT @MailId = STRING_AGG(empemail, ';')     
           FROM essp.dbo.empbasic   
           WHERE empno IN (@HodId);  
          -- WHERE empno IN ('100003','101343')  
           PRINT @MailId  
            
           --NAME Notifaction Fiend  
           DECLARE @NotifayPersion NVARCHAR(MAX);    
          SELECT @NotifayPersion = STRING_AGG(dbo.Employee_FullName(A.empfirstname, A.empmiddlename, A.emplastname), ', ')  
          FROM essp.dbo.empbasic A  
          WHERE empno IN (@MdId, @HodId);  
            
         -- Select * from essp.dbo.empbasic  
  
          --dbo.Employee_FullName(A.empfirstname,A.empmiddlename,A.emplastname) EmployeeName   
  
    
        DECLARE @tableHTML NVARCHAR(MAX);      
        DECLARE @departmentNameMail NVARCHAR(MAX);     
        DECLARE @subjectMail NVARCHAR(MAX);     
        DECLARE @postNameMail NVARCHAR(MAX);     
        DECLARE @locationMail NVARCHAR(MAX);    
    
        -- Fetch Post, Department, and Location details    
        SELECT     
         @postNameMail = B.postname,    
         @departmentNameMail = A.deptname,    
         @locationMail = A.location    
        FROM vw_Recruitment_AllPost A    
        INNER JOIN trecruitappliedpost B ON B.postid = A.postid    
        WHERE A.plmapid = @plmapid;    
        set @subjectMail='Post Creation Request: ' + @postNameMail + '-' + @departmentNameMail + ' - ' + @locationMail;    
        -- Construct the HTML email body    
        SET @tableHTML =     
        '<html>    
         <body style="font-family:Tahoma;font-size:14px;">    
          <p>Dear Sir/Madam,</p>    
          <p>This is a system-generated email to notify you that a request for creating a new post has been initiated.</p>    
          <br/>    
          <table border="1" cellpadding="8" cellspacing="0" style="border-collapse:collapse;font-size:14px;">    
           <tr style="background-color:#f2f2f2;">    
            <th>Post Name</th>    
            <th>Department</th>    
            <th>Location</th>    
           </tr>    
           <tr>    
            <td>' + @postNameMail + '</td>    
            <td>' + @departmentNameMail + '</td>    
            <td>' + @locationMail + '</td>    
           </tr>    
          </table>    
          <br/>    
          <p>Thank You.</p>    
         </body>    
        </html>';    
        -- Send Email using Database Mail    
         EXEC msdb.dbo.sp_send_dbmail                                                        
         @profile_name = 'Mendine_Recruitment_Profile'                                           
           ,@recipients = @MailId                                                
           ,@subject = @subjectMail                                                
           ,@body =                
         @tableHTML                                                
           ,@importance ='HIGH'              
           ,@body_format = 'HTML'   
             COMMIT TRANSACTION;                                       
           END TRY                                
           BEGIN CATCH                                
           ROLLBACK TRANSACTION;                                       
           END CATCH;    
   SET @status='This post send to Request for  approval by'+@NotifayPersion  
   END  
 ELSE  
    BEGIN  
       SET @status='Your Department HOD is not specify. at first specify the HOD'          
    END  
END   

GO



