CREATE PROCEDURE [dbo].[PRC_GetLocationsByPostName]      
    @DeptId nvarchar(max),  
 @PostID VARCHAR(MAX)   
   
   
AS      
BEGIN      
    SET NOCOUNT ON;      
      
    SELECT DISTINCT locid, location      
    FROM vw_Recruitment_AllPost      
    --WHERE postid IN (SELECT name FROM dbo.splitstring(@PostID))      
  WHERE postid IN (Select postid from [trecruitappliedpost] where ActualPostID IN (SELECT name FROM dbo.splitstring(@PostID)))      
        and DeptId IN (SELECT name FROM dbo.splitstring(@DeptId))  
 ORDER BY location ASC;      
END;
