/****** Object:  StoredProcedure [dbo].[PRC_Receruitment_ConfidentialDeptList]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[PRC_Receruitment_ConfidentialDeptList]            
As            
Begin            
     
WITH CTE AS (      
   SELECT ID, DeptName,  ROW_NUMBER() OVER (PARTITION BY  DeptName  ORDER BY (SELECT 0)) AS rn      
   FROM  [trecruitdepartment]          
  
)      
SELECT ID, DeptName       
FROM CTE      
WHERE rn = 1     
            
End       
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: test, trecruitdepartment */
/****** Object:  StoredProcedure [dbo].[PRC_Receruitment_Department_List]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[PRC_Receruitment_Department_List]              
As              
Begin              
--Select ID, DeptName from [trecruitdepartment]            
--union           
--select '' ID , 'OTHER' Deptname from [trecruitdepartment]         
WITH CTE AS (        
   SELECT ID, DeptName,ActiveFlag,  ROW_NUMBER() OVER (PARTITION BY  DeptName  ORDER BY (SELECT 0)) AS rn        
   FROM  [trecruitdepartment]            
   union        
   select '' ID , 'OTHER' Deptname,ActiveFlag,ROW_NUMBER() OVER (PARTITION BY  DeptName  ORDER BY (SELECT 0)) AS rn from [trecruitdepartment]           
        
)        
SELECT ID, DeptName         
FROM CTE        
WHERE rn = 1 and Deptname !='' and Deptname is not null and  ActiveFlag !='N' 
AND (DeptName NOT LIKE '%DEMO%' AND DeptName NOT LIKE '%TEST%') 
Order by DeptName  
End 
