/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: trecruitappliedpost, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[PRC_Receruitment_PostList]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
   
CREATE   PROCEDURE [dbo].[PRC_Receruitment_PostList]   
    @CompanyID INT = NULL,  
    @DepartmentID INT = NULL  
AS  
BEGIN  
    SET NOCOUNT ON;  
  
    IF @CompanyID = 0 SET @CompanyID = NULL;  
    IF @DepartmentID = 0 SET @DepartmentID = NULL;  
  
    SELECT  
        TD.PostID ActualPostID,  
        LTRIM(RTRIM(postname)) AS PostName,  
        IDCompany AS CompanyID,  
        Deptid AS DepartmentID  
    FROM trecruitappliedpost TD INNER JOIN trecruitpostlocationmap LC ON LC.PostID=TD.postid  
    WHERE  
        IDCompany IS NOT NULL  
        AND Deptid IS NOT NULL  
        AND (@CompanyID IS NULL OR IDCompany = @CompanyID)  
        AND (@DepartmentID IS NULL OR Deptid = @DepartmentID)  
        AND LC.Activeflag='Y'  
    GROUP BY  
        TD.postid,  
        LTRIM(RTRIM(postname)),  
        IDCompany,  
        Deptid  
    ORDER BY PostName ASC;  
END  
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: Company, test, trecruitappliedpost, trecruitdepartment, trecruitdivision, trecruitpostlocation, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[PRC_Recruitment_Post_Select_With_Status]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- PRC_Recruitment_Post_Select_With_Status 1              
CREATE Proc [dbo].[PRC_Recruitment_Post_Select_With_Status]                  
@Status bit                  
AS                  
BEGIN                  
                   
                  
                    
declare @Status_bit varchar(10)                
declare @Status_sp varchar(50)                  
                  
if(@Status=1)                
begin                
set @Status_bit='Y'                
end                
else                
begin                
set @Status_bit='N'                
end                
if(@Status_bit='Y')                  
Begin                  
set @Status_sp='Active'                  
End                  
                  
else                  
Begin                  
set @Status_sp='Inactive'                  
End                  
                    
                  
                    
                    
--if(@Status_bit=1)                    
--Begin                    
--set @Status_sp='Active'                    
--End                    
                    
--else                    
--Begin                    
--set @Status_sp='Inactive'                    
--End                    
                    
                    
SELECT *,ROW_NUMBER() Over (Order BY M.postname) SRL FROM(                  
SELECT pl.plmapid,cm.Company, po.postid,de.deptname,l.locid,[postname] +' - '+ [Deptname]+'('+divname+')'+' - '+l.location postname ,@Status [status], po.IDCompany,po.JobDescription,po.Qualifications,                  
po.Experience ,po.Age , po.Jobresponsibility,po.Jobvacancy , po.Jobnature,po.TechnicalScope,po.AdministrativeScope ,                  
po.Reporttopost ,po.Compensate , po.Others , po.DeadLine ,pl.Confidentialpostlink                       
FROM [trecruitappliedpost] po,                      
trecruitdepartment de,                      
trecruitdivision di ,                      
[trecruitpostlocationmap] pl,                      
[trecruitpostlocation]l,        
[Company] cm         
where po.[Deptid]=de.id                      
and de.id=di.deptid                      
and po.postid=pl.postid                      
and pl.locid=l.locid                    
And pl.Activeflag=@Status_bit         
and po.IDCompany = cm.companyPK          
union                      
SELECT pl.plmapid,cm.Company, po.postid,de.deptname,l.locid,[postname] +' - '+ [Deptname]+' - '+ l.location postname ,@Status [status] , po.IDCompany,po.JobDescription,po.Qualifications,                  
po.Experience ,po.Age , po.Jobresponsibility,po.Jobvacancy , po.Jobnature,po.TechnicalScope,po.AdministrativeScope ,                  
po.Reporttopost ,po.Compensate , po.Others , po.DeadLine ,pl.Confidentialpostlink                         
FROM [trecruitappliedpost] po,                      
trecruitdepartment de ,                      
[trecruitpostlocationmap] pl,                      
[trecruitpostlocation]l ,        
[Company] cm         
where po.[Deptid]=de.id         
and po.IDCompany = cm.companyPK          
and po.postid not in (SELECT [postid]                      
FROM [trecruitappliedpost] po,trecruitdepartment de,trecruitdivision di where po.[Deptid]=de.id                      
and de.id=di.deptid)                      
and po.postid=pl.postid                      
and pl.locid=l.locid                    
And pl.Activeflag=@Status_bit   
AND (de.deptname NOT LIKE '%DEMO%' AND de.deptname NOT LIKE '%TEST%')
AND (postname NOT LIKE '%DEMO%' AND postname NOT LIKE '%TEST%')
)M          
end
GO



