/****** Object:  StoredProcedure [dbo].[PRC_UPDATE_ACTIVE_POST]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[PRC_UPDATE_ACTIVE_POST]                                                                                  
@postname bigint,                
@username varchar(max)=null,                
@jobdescription nvarchar(MAX)=null,                              
@qualification nvarchar(MAX)=null,                              
@experience nvarchar(MAX)=null,                              
@age nvarchar(MAX)=null,                              
@responsibility nvarchar(MAX)=null,                              
@vacancy nvarchar(MAX)=null,                              
@jobnature nvarchar(MAX)=null,                              
@technicalscope nvarchar(MAX)=null,                              
@administrativescope nvarchar(MAX)=null,                              
@reporttopost nvarchar(MAX)=null,                              
@compensate nvarchar(MAX)=null,                              
@other nvarchar(MAX)=null,                              
@deadline nvarchar(MAX)=null,        
@TypeFresher varchar(max) =null,          
@TypeExperienced varchar(max)=null,          
@TypeSalesExperienced varchar(max)=null,    
    
@jobTitle varchar(max)=null,    
@objectives varchar(max)=null,    
@jobDescriptionFilePath varchar(max)=null,    
@jobDescriptionFileExtension varchar(max)=null,  
@ATS_HEAD_RATING_ID  nvarchar(max)=null                             
AS                 
BEGIN                  
UPDATE [trecruitpostlocationmap] SET                 
JobDescription=@jobdescription,                              
Qualifications=@qualification,                              
Experience=@experience,                              
Age=@age,                              
Jobresponsibility=@responsibility,                              
Jobvacancy=@vacancy,                              
Jobnature=@jobnature,                              
TechnicalScope=@technicalscope,                              
AdministrativeScope=@administrativescope,                              
Reporttopost=@reporttopost,                              
Compensate=@compensate,                              
Others=@other,                              
DeadLine=@deadline,                
createdby =@username,                
Createdtime=GETDATE(),        
[TypeFresher]=@TypeFresher,          
[TypeExperienced]=@TypeExperienced,          
[TypeSalesExperienced]=@TypeSalesExperienced,    
[JobTitle]=@jobTitle,    
[Objectives]=@objectives,   
[ATS_HEAD_RATING_ID]=@ATS_HEAD_RATING_ID,  
JobDescriptionFilePath = CASE     
            WHEN @jobDescriptionFilePath IS NULL THEN JobDescriptionFilePath     
            ELSE @jobDescriptionFilePath     
        END,    
        JobDescriptionFileExtension = CASE     
            WHEN @jobDescriptionFilePath IS NULL THEN JobDescriptionFileExtension     
            ELSE @jobDescriptionFileExtension     
        END    
where plmapid=@postname                 
END    
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: trecruitappliedpost, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[PRC_UPDATE_POST_Exam_Tagging]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[PRC_UPDATE_POST_Exam_Tagging]
    @plmapid bigint,
    @username varchar(max)=null,
    @jobdescription nvarchar(MAX)=null,
    @qualification nvarchar(MAX)=null,
    @experience nvarchar(MAX)=null,
    @age nvarchar(MAX)=null,
    @responsibility nvarchar(MAX)=null,
    @vacancy nvarchar(MAX)=null,
    @jobnature nvarchar(MAX)=null,
    @technicalscope nvarchar(MAX)=null,
    @administrativescope nvarchar(MAX)=null,
    @reporttopost nvarchar(MAX)=null,
    @compensate nvarchar(MAX)=null,
    @other nvarchar(MAX)=null,
    @deadline nvarchar(MAX)=null,
    @TypeFresher varchar(max)=null,
    @TypeExperienced varchar(max)=null,
    @TypeSalesExperienced varchar(max)=null,
    @jobTitle varchar(max)=null,
    @objectives varchar(max)=null,
    @jobDescriptionFilePath varchar(max)=null,
    @jobDescriptionFileExtension varchar(max)=null,
    @ATS_HEAD_RATING_ID nvarchar(max)=null,
    @ExamTaggingType nvarchar(max),
    @Exam_Id int 
AS
BEGIN

    -- Existing Update
    UPDATE trecruitpostlocationmap
    SET
        JobDescription=@jobdescription,
        Qualifications=@qualification,
        Experience=@experience,
        Age=@age,
        Jobresponsibility=@responsibility,
        Jobvacancy=@vacancy,
        Jobnature=@jobnature,
        TechnicalScope=@technicalscope,
        AdministrativeScope=@administrativescope,
        Reporttopost=@reporttopost,
        Compensate=@compensate,
        Others=@other,
        DeadLine=@deadline,
        createdby=@username,
        Createdtime=GETDATE(),
        TypeFresher=@TypeFresher,
        TypeExperienced=@TypeExperienced,
        TypeSalesExperienced=@TypeSalesExperienced,
        JobTitle=@jobTitle,
        Objectives=@objectives,
        ATS_HEAD_RATING_ID=@ATS_HEAD_RATING_ID,
        JobDescriptionFilePath =
            CASE
                WHEN @jobDescriptionFilePath IS NULL
                THEN JobDescriptionFilePath
                ELSE @jobDescriptionFilePath
            END,
        JobDescriptionFileExtension =
            CASE
                WHEN @jobDescriptionFilePath IS NULL
                THEN JobDescriptionFileExtension
                ELSE @jobDescriptionFileExtension
            END
    WHERE plmapid=@plmapid;


    ---------------------------------------------------------
    -- Exam Tagging Update
    ---------------------------------------------------------

    IF (@ExamTaggingType = 'All Location')
    BEGIN
        UPDATE A
        SET A.ExamTaggingID = @Exam_Id
        FROM trecruitappliedpost A
        WHERE A.ActualPostID =
        (
            SELECT TOP 1 ActualPostID
            FROM trecruitappliedpost tp
			INNER JOIN trecruitpostlocationmap tm ON tp.postid=tm.postid
            where tm.plmapid=@plmapid
        );
    END
    ELSE IF (@ExamTaggingType = 'Only this location')
    BEGIN
        UPDATE tp  
        SET ExamTaggingID = @Exam_Id
		from trecruitappliedpost tp
			INNER JOIN trecruitpostlocationmap tm ON tp.postid=tm.postid
            where tm.plmapid=@plmapid
    END

END
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: trecruitProfile, TrecruitProfileDetail */
/****** Object:  StoredProcedure [dbo].[PRCJobProfileAddEdit]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[PRCJobProfileAddEdit]          
@IDProfile  Bigint,               
@IDDepartment Bigint,          
@IDPost Bigint,     
@IDLocation Bigint,    
@IDCompany Bigint,  
@CreationDate Varchar(11),  
@JobDescription Varchar(max),    
@User  Varchar(100),          
@TB   Type_Job_Profile_Detail Readonly           
As          
Begin          
Declare @Result  Varchar(1000)=''          
Declare @ID   Bigint=0          
            
Begin Tran           
Begin Try           
 if (@IDProfile=0)-- Add Mode           
 Begin          
  insert into trecruitProfile          
  (   [IDDepartment], [IDPost],  
      [IDLocation], [IDCompany], [ProfileDate],   
   [JobDescription], [EntryUser],[ENtryDate],  
   [Active]  
  )          
  Values          
  ( @IDDepartment, @IDPost, @IDLocation,           
    @IDCompany, @CreationDate, @JobDescription,           
    @User, GetDate(),1    
  )          
  Set @ID=@@Identity          
 End          
 -- Detail Part           
 Delete from TrecruitProfileDetail Where IDProfile = @ID     
 Insert into TrecruitProfileDetail          
 ( IDProfile, FirstName, MiddleName, LastName, Email )          
 Select @ID, FirstName, MiddleName, LastName,  Email    
 From @TB           
 Commit Tran           
 Set @Result=''          
End Try           
Begin Catch           
 Rollback Tran           
 Set @Result=dbo.fnErrors()          
End Catch           
 Select @Result          
End 
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: trecruitProfileMap */
/****** Object:  StoredProcedure [dbo].[Proc_addandeditcandidatedocname]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[Proc_addandeditcandidatedocname]
@Id	int=0,
@Type	nvarchar(max)=null,
--@TypeName	nvarchar(max)=null,
@Doc	nvarchar(max)=null,
--@DocName	nvarchar(max)=null,
@Category	nvarchar(max)=null,
--@CategoryName	nvarchar(max)=null,
@outputstatus varchar(max)=null output          
          
AS          
Declare @errorcode nvarchar(Max) 
DECLARE @DocId	int
BEGIN          
begin try  

select @DocId=max(Docid)+1 from trecruitProfileMap


If exists (select * from trecruitProfileMap where Id=@Id)
begin

Update trecruitProfileMap set 
Type=LOWER(@Type),
TypeName=UPPER(@Type),
Doc=LOWER(@Doc),
DocName=UPPER(@Doc),
Category=LOWER(@Category),
CategoryName=UPPER(@Category)
where Id=@Id
Set @outputstatus='Record Updated Successfully' 

END

ELSE
BEGIN
Insert into trecruitProfileMap
(
Type,
TypeName,
Doc,
DocName,
Category,
CategoryName,
DocId
)
Values 
(
LOWER(@Type),
UPPER(@Type),
LOWER(@Doc),
UPPER(@Doc),
LOWER(@Category),
UPPER(@Category),
@DocId
)

Set @outputstatus='Record Saved Successfully'  
END

end try                
begin catch                
 Select @errorcode=ERROR_NUMBER();                
 Set @outputstatus='CREATION FAILD!!.ERROR CODE:'+@errorcode                
end catch           
END 
GO



