GO
CREATE PROCEDURE [dbo].[Proc_ALL_ACTIVE_POST_IECSL]            
            
AS            
BEGIN            
            
            
SELECT pl.plmapid,cm.Company,po.postid,de.deptname,l.locid,[postname] +' - '+ [Deptname]+'('+divname+')'+' - '+l.location postname,l.location, po.IDCompany,pl.JobDescription,pl.Qualifications,                      
pl.Experience ,pl.Age , pl.Jobresponsibility,pl.Jobvacancy , pl.Jobnature,pl.TechnicalScope,pl.AdministrativeScope ,                      
pl.Reporttopost ,pl.Compensate , pl.Others , pl.DeadLine ,po.[status]                  
FROM [dbo].[trecruitappliedpost] po,                  
trecruitdepartment de,                  
trecruitdivision di ,                  
[trecruitpostlocationmap] pl,                  
[trecruitpostlocation]l ,              
[Company] cm              
where po.[Deptid]=de.id                  
