/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[Proc_candidtenamelist]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
CREATE PROCEDURE [dbo].[Proc_candidtenamelist]                      
--@candidatename Nvarchar(max),  
@deptname varchar(max)=null,  
@postname  varchar(max)=null,  
@StartDate Varchar(12)=null,                    
@EndDate Varchar(12)                    
AS                      
BEGIN         
  
select  upper(A.rscandidatename) as rscandidatename , A.rscandidateid                      
from vw_rcalldata    A                  
LEFT JOIN trecruitpostlocationmap B ON A.rspostid=B.postid and A.rslocid=B.locid                    
where convert(datetime,A.aplicationdate,103)                    
between convert(datetime,@StartDate,103) AND convert(datetime,@EndDate,103)     
--AND                    
--A.rscandidatename like @candidatename+'%'                   
                
and A.rspostname not like 'ASSOCIATE%'  
and  A.deptdivision= Case When @deptname= 'SELECT DEPARTMENT' Then A.deptdivision Else @deptname  End         
and  A.rspostname= Case When @postname= 'SELECT POST' Then A.rspostname Else @postname  End   
   
Group By A.rscandidatename, A.rscandidateid        
Order By A.rscandidatename    
END  
 
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[Proc_canpostnamelist]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--Proc_canpostnamelist 'SELECT DEPARTMENT','01-01-2024','27-08-2025'
CREATE PROCEDURE [dbo].[Proc_canpostnamelist]                        
@deptname Nvarchar(max),                      
@StartDate Varchar(12),                      
@EndDate Varchar(12)                      
AS                        
BEGIN         
    
if (@deptname = 'SELECT DEPARTMENT')    
BEGIN     
select DISTINCT A.rspostname , A.rspostid                        
from vw_rcalldata  A                
LEFT JOIN trecruitpostlocationmap B ON A.rspostid=B.postid and A.rslocid=B.locid                  
where convert(datetime,A.aplicationdate,103)                      
between convert(datetime,@StartDate,103) AND convert(datetime,@EndDate,103)     
--AND                      
--rspostname like @postname+'%'                
              
and A.rspostname not like 'ASSOCIATE%'      
    ORDER BY A.rspostname

END    
    
ELSE    
BEGIN     
select DISTINCT A.rspostname , A.rspostid                        
from vw_rcalldata  A                
LEFT JOIN trecruitpostlocationmap B ON A.rspostid=B.postid and A.rslocid=B.locid                  
where convert(datetime,A.aplicationdate,103)                      
between convert(datetime,@StartDate,103) AND convert(datetime,@EndDate,103)                      
--AND                      
--rspostname like @postname+'%'                
              
and A.rspostname not like 'ASSOCIATE%'  And A.deptdivision=@deptname    
ORDER BY A.rspostname
END    
END 
GO



