SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[PROC_COMPANYWISEDEPT_POSTCREATION]  
@companyId INT  
AS  
BEGIN  
SELECT DISTINCT DeptName,ID FROM trecruitdepartment DEPT INNER JOIN trecruitappliedpost POST ON POST.Deptid=DEPT.id AND ActiveFlag='Y' 
AND (deptname NOT LIKE '%DEMO%' AND deptname NOT LIKE '%TEST%')
and Deptname !='' and Deptname is not null AND ISNULL(IDCompany,1)=@companyId  
END
GO



