/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: trecruitdepartment */
/****** Object:  StoredProcedure [dbo].[proc_CreateDepartment]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[proc_CreateDepartment]    
@Deptname varchar(100),       
@createdby nvarchar(MAX),    
@outputstatus varchar(max)=null output      
    
AS    
Declare @errorcode nvarchar(Max)       
BEGIN    
    
 begin try        
    
if exists(select Deptname from [dbo].[trecruitdepartment] where Deptname=@Deptname)      
begin      
set @outputstatus = 'Department Name Already Exists'      
end      
else      
begin      
INSERT INTO [dbo].[trecruitdepartment]                        
           ([Deptname],    
			CreatedTime,    
			CreatedBy,
			ActiveFlag
			)                        
     VALUES                        
           (upper(@Deptname),    
     GETDATE(),    
      @createdby,
	  'Y'
	  )    
                            
       Set @outputstatus='Department Created Successfully'                  
 end      
             
end try                
begin catch                
 Select @errorcode=ERROR_NUMBER();                
 Set @outputstatus='DEPARTMENT CREATION FAILD!!.ERROR CODE:'+@errorcode                
end catch     
END
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: trecruitpostlocation */
/****** Object:  StoredProcedure [dbo].[proc_CreateLocation]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[proc_CreateLocation]
@locname varchar(100),   
@createdby nvarchar(MAX),
@outputstatus varchar(max)=null output    

AS
Declare @errorcode nvarchar(Max)   
BEGIN

 begin try    

if exists(select location from [dbo].[trecruitpostlocation] where location=@locname)  
begin  
set @outputstatus = 'Location Name Already Exists'  
end  
else  
begin  
INSERT INTO [dbo].[trecruitpostlocation]                    
           ([location],
		   CreatedBy,
		   CreatedTime)
		                      
     VALUES                    
           (upper(@locname),
		    @createdby,
		   GETDATE())
		   
		                      
    Set @outputstatus='Location Created Successfully'                          
 end  

end try            
begin catch            
 Select @errorcode=ERROR_NUMBER();            
 Set @outputstatus='LOCATION CREATION FAILD!!.ERROR CODE:'+@errorcode            
end catch 
END
GO



