GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE  [dbo].[Proc_DeptWiseGetActiveallemployee]      
@deptIds nvarchar(max)=NULL    
AS        
BEGIN        
        
 Select  A.empid IDEmployee, A.empno,A.empdept,          
    essp.dbo.Employee_FullName(A.EmpFirstName, A.EmpMiddleName,A.emplastname) EmpName           
 From essp.dbo.Empbasic  A  Where A.empstatus='ACTIVE'     
 AND A.empdept IN(SELECT Name FROM dbo.splitstring(@deptIds))    
 order by A.EmpFirstName       
 END 
GO



