SET QUOTED_IDENTIFIER ON
GO
CREATE procedure  [dbo].[proc_fetchlocationname] 
@locationname varchar(200)  
as  
begin  
 
Select a.location,a.locid
from trecruitpostlocation  a
where a.location like @locationname+'%'  
 
end
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: trecruitappliedpost */
/****** Object:  StoredProcedure [dbo].[proc_fetchpostname]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE procedure  [dbo].[proc_fetchpostname]     
@postname varchar(200)      
as      
begin      
     
	 WITH CTE AS (      
   SELECT postid ,postname,    ROW_NUMBER() OVER (PARTITION BY  postname  ORDER BY (SELECT 0)) AS rn      
   FROM  trecruitappliedpost          
       
)      
SELECT postid, postname       
FROM CTE      
WHERE rn = 1  and  postname like @postname+'%'      

--Select DISTINCT a.postname,a.postid    
--from trecruitappliedpost  a    
--where a.postname like @postname+'%'      
     
end



GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: none detected */
/****** Object:  StoredProcedure [dbo].[proc_GetActiveEmployeesByDepartment]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[proc_GetActiveEmployeesByDepartment]  
@deptIds nvarchar(max)=NULL ,  
@Action VARCHAR(20),  
@TenantID NVARCHAR(MAX)  
  
AS  
BEGIN  
SET NOCOUNT ON;  
  
IF @Action = 'DepartmentName'  
BEGIN  
SELECT distinct  
dpt.Department,  
dpt.DepartmentId  
-- emp.empfirstname + ' ' + ISNULL(emp.empmiddlename + ' ', '') + emp.emplastname AS EmployeeName,  
--emp.empid  
FROM  
essp.dbo.Department AS dpt  
INNER JOIN  
essp.dbo.Empbasic AS emp  
ON  
dpt.DepartmentId = emp.empdept  
WHERE  
emp.empstatus = 'ACTIVE'  
and emp. TenantID =@TenantID  
END  
ELSE IF @Action = 'GetEmpname'  
BEGIN  
  
Select A.empid IDEmployee, A.empno,A.empdept,  
essp.dbo.Employee_FullName(A.EmpFirstName, A.EmpMiddleName,A.emplastname) EmpName  
From essp.dbo.Empbasic A Where A.empstatus='ACTIVE'  
AND A. TenantID =@TenantID  
AND A.empdept IN(SELECT Name FROM dbo.splitstring(@deptIds))  
order by A.EmpFirstName  
END  
END;  
  
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: none detected */
/****** Object:  StoredProcedure [dbo].[proc_GetActiveEmployeesByDepartmentId]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[proc_GetActiveEmployeesByDepartmentId]          
    @DeptID VARCHAR(MAX) = NULL                    
AS          
BEGIN          
    SET NOCOUNT ON;          
          
         SELECT distinct          
            dpt.Department,          
            dpt.DepartmentId,          
            emp.empfirstname + ' ' + ISNULL(emp.empmiddlename + ' ', '') + emp.emplastname AS EmployeeName,          
            emp.empid          
        FROM           
            essp.dbo.Department AS dpt          
        INNER JOIN           
            essp.dbo.Empbasic AS emp           
        ON           
            dpt.DepartmentId = emp.empdept          
        WHERE           
            emp.empstatus = 'ACTIVE'          
            AND dpt.DepartmentId = @DeptID;                    
END; 
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: Company, trecruitappliedpost, trecruitdepartment, trecruitdivision, trecruitpostlocation, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[Proc_GetAllPost_Recruitment]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Proc_GetAllPost_Recruitment 'MANAGEMENT INFORMATION SYSTEM'
CREATE PROCEDURE [dbo].[Proc_GetAllPost_Recruitment]                     
@deptname varchar(max)                    
AS                      
BEGIN                      
                      
                      
SELECT po.postid,cm.Company,de.deptname,l.locid,[postname] +' - '+ [Deptname]+'('+divname+')'+' - '+l.location postname ,po.[status]                    
FROM [dbo].[trecruitappliedpost] po,                    
trecruitdepartment de,                    
trecruitdivision di ,                    
[trecruitpostlocationmap] pl,                    
[trecruitpostlocation]l ,                  
[Company] cm                    
where po.[Deptid]=de.id                    
and de.id=di.deptid                    
and po.postid=pl.postid                    
and pl.locid=l.locid                  
and po.IDCompany = cm.companyPK                  
               
--and pl.Activeflag ='Y'            
and pl.Confidentialpost ='0'          
and de.deptname= Case When @deptname= '-SELECT-' Then de.deptname Else @deptname  End        
union                    
SELECT po.postid,cm.Company,de.deptname,l.locid,[postname] +' - '+ [Deptname]+' - '+ l.location postname ,po.[status]                    
FROM [dbo].[trecruitappliedpost] po,                    
trecruitdepartment de ,                    
[trecruitpostlocationmap] pl,                    
[trecruitpostlocation]l ,                  
[Company] cm                    
where po.[Deptid]=de.id                    
and po.postid not in (SELECT [postid]                    
FROM [dbo].[trecruitappliedpost] po,trecruitdepartment de,trecruitdivision di where po.[Deptid]=de.id                    
and de.id=di.deptid)                    
and po.postid=pl.postid                    
and pl.locid=l.locid                  
and po.IDCompany = cm.companyPK                  
          
--and pl.Activeflag ='Y'           
and pl.Confidentialpost ='0'          
and de.deptname= Case When @deptname= '-SELECT-' Then de.deptname Else @deptname  End        
      
  UNION      
      
-- Static 'EDUCYTE TRAINEE' row      
SELECT       
    0 AS postid,      
    'EDUCYTE COMPANY' AS Company,      
    'EDUCATION' AS deptname,      
    0 AS locid,      
    'EDUCYTE TRAINEE' AS postname,      
    '0' AS [status]      
--Order by postname      
 end 
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[Proc_GetConfidentialcandidatedata]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
    
-- Proc_GetConfidentialcandidatedata '-SELECT-','-SELECT-','-SELECT-','','','-SELECT-'    
CREATE PROCEDURE [dbo].[Proc_GetConfidentialcandidatedata]    
@Deptname varchar(max),    
@postname varchar(max),    
@candidatename varchar(max),    
@FromDate varchar(100)=null,    
@ToDate varchar(100)=null,    
@Frselected varchar(100)    
AS    
BEGIN    
    
    
SELECT A.candidateid, A.CandidateName, Case When A.deptname= '' Then 'OTHERS' Else A.deptname  End as deptname , A.postname  FROM vw_essp_RecruitCanProfile  A  
 left join trecruitpostlocationmap B on A.postid=B.postid and A.locid=B.locid
    
WHERE  A.deptname= Case When @Deptname= '-SELECT-' Then A.deptname Else @Deptname  End     
    
AND A.postname= Case When @postname= '-SELECT-' Then A.postname Else @postname  End     
    
AND  CandidateName= Case When @candidatename= '-SELECT-' Then CandidateName Else @candidatename  End    
AND (B.Confidentialpost = '1' OR  A.postname  like '%ASSOCIATE%')     
OR  convert(datetime,(convert(varchar, convert(datetime, A.aplicationdate, 103), 101)),111)                            
   BETWEEN convert(datetime,(convert(varchar, convert(datetime, @FromDate, 103), 101)),111) AND                             
   convert(datetime,(convert(varchar, convert(datetime, @ToDate, 103), 101)),111)    
       
AND A.Frselect= Case When @Frselected= '-SELECT-' Then A.Frselect Else @Frselected  End   
  
 --  
 --AND B.Confidentialpost='1'  
    
    
END    
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: trecruitcanappnum, trecruitcanbasicdtls, trecruitcandidatesignup, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[proc_GetConfidentialcandtls]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[proc_GetConfidentialcandtls]        
AS        
BEGIN        
--select candidateid,CandidateName from vw_RecruitCanProfile        
        
--order by CandidateName        
      
--WITH CTE AS (        
--   SELECT candidateid,CandidateName ,  ROW_NUMBER() OVER (PARTITION BY  CandidateName  ORDER BY (SELECT 0)) AS rn        
--   FROM  vw_RecruitCanProfile  A    
--   Left Join trecruitpostlocationmap B ON A.postid=B.postid and A.locid=B.locid     
--   where B.Confidentialpost='1'    
--)       
--SELECT candidateid,CandidateName         
--FROM CTE        
--WHERE rn = 1        

WITH CTE AS (    
   SELECT A.candidateid, dbo.Candidate_FullName(A.[firstname],A.[middlename],A.[lastname]) CandidateName ,  ROW_NUMBER() OVER (PARTITION BY  CandidateName  ORDER BY (SELECT 0)) AS rn    
   FROM  trecruitcanbasicdtls A 
   LEFT JOIN trecruitcandidatesignup B ON A.candidateid = B.CandidateID
   LEFT JOIN trecruitcanappnum C ON  B.username = C.username
   LEFT JOIN trecruitpostlocationmap D ON C.postid=D.postid and C.locid=D.locid     
   where  A.[applicationstatus] IN ( 'NEW' )  
   and D.Confidentialpost='1'   
)    
SELECT candidateid,CandidateName    
FROM CTE 

order by CandidateName  
        
END
GO



