SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[Proc_GetDepartment]          
AS      
BEGIN       
select Deptname, id from [dbo].[trecruitdepartment] where ActiveFlag ='Y' AND (deptname NOT LIKE '%DEMO%' AND deptname NOT LIKE '%TEST%')
order by CreatedTime desc       
END
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: tbl_recruitmentEsspDepartmentID, trecruitdepartment */
/****** Object:  StoredProcedure [dbo].[Proc_GetDepartment_ByUsername]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[Proc_GetDepartment_ByUsername] 
@empDeptID VARCHAR(50)
AS      
BEGIN       
	select A.Deptname, A.id from [dbo].[trecruitdepartment] A
	INNER JOIN tbl_recruitmentEsspDepartmentID B ON B.RecruitmentDepartmentID=A.id
	where B.EsspDepartmentID=@empDeptID and A.ActiveFlag ='Y' order by A.CreatedTime desc  
END
GO



