/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: Company, trecruitappliedpost, trecruitdepartment, trecruitdivision, trecruitpostlocation, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[PROC_Job_DescriptionData_NEW]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE procedure [dbo].[PROC_Job_DescriptionData_NEW]                   
@plmapid bigint                  
as                                  
begin                                  
                                
declare @Status_bit varchar(10)                              
declare @Status bit                               
                                
 SELECT @Status_bit=pl.Activeflag                                 
FROM [trecruitappliedpost] po,                                  
trecruitdepartment de,                                  
trecruitdivision di ,                                  
[trecruitpostlocationmap] pl,                                  
[trecruitpostlocation]l                                  
where po.[Deptid]=de.id                                  
and de.id=di.deptid                                  
and po.postid=pl.postid                                  
and pl.locid=l.locid                                  
                      
SELECT *,ROW_NUMBER() Over (Order BY M.postname) SRL FROM(                      
SELECT pl.plmapid, cm.Company, po.postid,de.deptname,l.locid,[postname] +' - '+ [Deptname]+'('+divname+')'+' - '+l.location postname , po.IDCompany,      
pl.JobTitle,    
l.location,    
pl.JobDescription,pl.Qualifications,                            
pl.Experience ,pl.Age , pl.Jobresponsibility,pl.Jobvacancy , pl.Jobnature,pl.TechnicalScope,pl.AdministrativeScope ,                            
pl.Reporttopost ,pl.Compensate , pl.Others , pl.DeadLine ,po.postname as post,                          
--Saikat             
pl.TypeFresher,            
pl.[TypeExperienced],            
pl.[TypeSalesExperienced],       
pl.[ATS_HEAD_RATING_ID],    
CASE                          
WHEN pl.Activeflag='Y'                          
THEN cast(1 as bit)                          
WHEN pl.Activeflag='N'                          
THEN cast(0 as bit)                          
END                                        
AS [status],              
pl.[Objectives],        
pl.[JobDescriptionFilePath],        
pl.[JobDescriptionFileExtension],
po.[ExamTaggingID]
FROM [trecruitpostlocationmap] pl,                                 
[trecruitappliedpost] po,                                  
trecruitdepartment de,                                  
trecruitdivision di ,                                  
                           
[trecruitpostlocation]l  ,                    
[Company] cm                    
where po.[Deptid]=de.id                                  
and de.id=di.deptid                                  
and po.postid=pl.postid                                  
and pl.locid=l.locid                    
and po.IDCompany = cm.companyPK                    
and pl.plmapid=@plmapid                  
union                                  
SELECT pl.plmapid,cm.Company, po.postid,de.deptname,l.locid,[postname] +' - '+ [Deptname]+' - '+ l.location postname ,po.IDCompany,      
pl.JobTitle,     
l.location,    
pl.JobDescription,pl.Qualifications,                            
pl.Experience ,pl.Age , pl.Jobresponsibility,pl.Jobvacancy , pl.Jobnature,pl.TechnicalScope,pl.AdministrativeScope ,                            
pl.Reporttopost ,pl.Compensate , pl.Others , pl.DeadLine , po.postname as post ,             
--saikat            
pl.TypeFresher,            
pl.TypeExperienced,            
pl.TypeSalesExperienced,     
pl.[ATS_HEAD_RATING_ID],    
CASE                          
WHEN pl.Activeflag='Y'                          
THEN 1                          
WHEN pl.Activeflag='N'                          
THEN 0                          
END                
AS [status],        
pl.[Objectives],        
pl.[JobDescriptionFilePath],        
pl.[JobDescriptionFileExtension]
,po.[ExamTaggingID]
FROM                           
[trecruitpostlocationmap] pl,[trecruitappliedpost] po,                                  
trecruitdepartment de ,                                                           
[trecruitpostlocation]l ,                    
[Company] cm                    
where po.[Deptid]=de.id    
and  po.IDCompany = cm.companyPK                    
and po.postid not in (SELECT [postid]                                  
FROM [trecruitappliedpost] po,trecruitdepartment de,trecruitdivision di where po.[Deptid]=de.id                                  
and de.id=di.deptid)                                  
and po.postid=pl.postid                                  
and pl.locid=l.locid                   
and pl.plmapid=@plmapid                  
)M                      
Order By M.postname                                             
 end             
  

GO



