SET QUOTED_IDENTIFIER ON
GO
create procedure [dbo].[proccountpostlocation]
@postid varchar(10),
@status varchar(10)=null output
as
begin
declare @count int
 select @count=count([postid]) from [trecruitpostlocationmap] where [postid]=@postid
if @count>0
begin
delete from  [trecruitpostlocationmap]  where [postid]=@postid
end
select @status=@count
end
GO



