/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: trecruitProfile */
/****** Object:  StoredProcedure [dbo].[ProcJobProfileActiveYN]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[ProcJobProfileActiveYN]            
@IDProfile  Bigint  ,          
@Active  bit          
As            
Begin            
Declare @Result Varchar(1000)=''   
    
  Begin Tran           
  Begin Try           
   Update TrecruitProfile Set           
   Active=@Active          
   Where IDProfile = @IDProfile     
  Commit Tran       
   Set @Result =''     
  End Try           
  Begin Catch           
  Rollback Tran           
   Set @Result =dbo.fnErrors()          
  End Catch        
  Select @Result        
End  
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: Company, trecruitappliedpost, trecruitdepartment, trecruitpostlocation, trecruitProfile */
/****** Object:  StoredProcedure [dbo].[ProcJobProfileList]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--SP_HelpText ProcJobProfileList
--  ProcJobProfileList 1,'',''  
CREATE proc [dbo].[ProcJobProfileList]               
@PageNo   Bigint ,      
@SearchValue Varchar(100),      
@ColumnName  Varchar(100)      
As                    
Begin                    
            
Declare @RowsInPage Bigint=25            
Declare @TotalRows Bigint=0               
Declare @TotalPage Bigint=0              
Declare @StartNo Bigint=0               
Declare @TB Table       
(      
SRL   Bigint,  
IDProfile Bigint,  
CreationDate varchar(11),  
IDDepartment Bigint,  
DepartmentName varchar(200),  
IDPost Bigint,      
PostName Varchar(200),      
IDLocation Bigint,      
LocationName Varchar(100),      
IDCompany Bigint,      
CompanyName Varchar(200),  
Active Bit  
)    
  
  
  
  
      
if (@SearchValue !='' Or @ColumnName !='')-- Search Call on List Page      
Begin      
 if (@ColumnName='FIRSTNAME')      
 Begin      
   Insert into @TB      
   (SRL,IDProfile,CreationDate,IDDepartment,DepartmentName,IDPost,  
   PostName,IDLocation,LocationName,IDCompany,CompanyName,Active)   
   Select   ROW_NUMBER() Over (Order BY A.IDProfile) SRL,A.IDProfile,                      
   A.ProfileDate,A.IDDepartment,B.Deptname DepartmentName,  
   A.IDPost,C.postname PostName,  
   A.IDLocation,D.location LocationNAme,  
   A.IDCompany,E.Company  CompanyName, A.Active  
   From trecruitProfile     A  
   Inner Join trecruitdepartment  B  
   On A.IDDepartment = B.id  
   Inner Join trecruitappliedpost  C  
   On A.IDPost = C.postid  
   Inner Join trecruitpostlocation  D  
   On A.IDLocation = D.locid  
   Inner Join company     E  
   On A.IDCompany = E.companypk  
   Where  B.Deptname Like @SearchValue +'%'      
 End   
  
 Else      
 Begin      
   Insert into @TB       
   (SRL,IDProfile,CreationDate,IDDepartment,DepartmentName,IDPost,  
   PostName,IDLocation,LocationName,IDCompany,CompanyName,Active)   
   Select   ROW_NUMBER() Over (Order BY A.IDProfile) SRL,A.IDProfile,                      
   A.ProfileDate,A.IDDepartment,B.Deptname DepartmentName,  
   A.IDPost,C.postname PostName,  
   A.IDLocation,D.location LocationNAme,  
   A.IDCompany,E.Company  CompanyName,A.Active  
   From trecruitProfile     A  
   Inner Join trecruitdepartment  B  
   On A.IDDepartment = B.id  
   Inner Join trecruitappliedpost  C  
   On A.IDPost = C.postid  
   Inner Join trecruitpostlocation  D  
   On A.IDLocation = D.locid  
   Inner Join company     E  
   On A.IDCompany = E.companypk  
   Where  C.postname Like @SearchValue +'%'      
 End      
End      
Else      
Begin -- List Page Call      
  Insert into @TB       
   (SRL,IDProfile,CreationDate,IDDepartment,DepartmentName,IDPost,  
   PostName,IDLocation,LocationName,IDCompany,CompanyName,Active)   
   Select   ROW_NUMBER() Over (Order BY A.IDProfile) SRL,A.IDProfile,                      
   A.ProfileDate,A.IDDepartment,B.Deptname DepartmentName,  
   A.IDPost,C.postname PostName,  
   A.IDLocation,D.location LocationNAme,  
   A.IDCompany,E.Company  CompanyName,A.Active  
   From trecruitProfile     A  
   Inner Join trecruitdepartment  B  
   On A.IDDepartment = B.id  
   Inner Join trecruitappliedpost  C  
   On A.IDPost = C.postid  
   Inner Join trecruitpostlocation  D  
   On A.IDLocation = D.locid  
   Inner Join company     E  
   On A.IDCompany = E.companypk        
End      
      
      
 -- Total Row              
 Select @TotalRows=Isnull(Count(A.IDProfile),0) from @TB  A            
           
 -- Total Page           
 Set  @TotalPage = ((@TotalRows/@RowsInPage)+1)          
          
 -- Start Row No           
 Set @StartNo =((@Pageno-1) * @RowsInPage)          
      
 -- Data           
 Select  A.* , @TotalPage TotalPage      
 from  @TB   A      
 Order By A.IDProfile      
 Offset @StartNo Rows  Fetch Next @RowsInPage Rows Only           
           
              
End   
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: trecruitcanbasicdtls, trecruitcandidatesignup, tRecruitcanotherdtls, trecruitotherpost, trecruituploadresume */
/****** Object:  StoredProcedure [dbo].[procotpostdtls]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[procotpostdtls] as    
    
begin    
SELECT             bac.[registrationnumber],     
                   su.username,              
       convert(varchar(10),bac.aplicationdate,103) as aplicationdate,    
                   otp.otpostname,    
                   Upper(bac.[firstname] + ' ' + bac.[middlename] + ' '+ bac.[lastname]) CandidateName,     
                   --rs.resumefile,     
                   bac.[applicationstatus],    
       ot.referredus    
            FROM   [dbo].[trecruitcanbasicdtls] bac,     
                   trecruitotherpost otp,    
                   [trecruitcandidatesignup] su,     
                   [dbo].[trecruituploadresume] rs ,    
                   [dbo].[tRecruitcanotherdtls]ot    
            WHERE  bac.candidateid = su.candidateid     
                   AND rs.candidateid = bac.candidateid     
                   AND bac.[applicationstatus] IN ( 'NEW' )     
       and bac.candidateid=ot.candidateid    
       and bac.candidateid=otp.candidateid                     
       order by aplicationdate     
    
       end
GO



