/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: trecruitappliedpost, trecruitdepartment, trecruitdivision, trecruitpostlocation, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[procselectappost]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
    
/****** Script for SelectTopNRows command from SSMS  ******/     
CREATE PROCEDURE [dbo].[procselectappost] @username VARCHAR(100)     
AS     
  BEGIN     
      DECLARE @usercount INT     
    
      SELECT @usercount = Count(username)     
      FROM   [dbo].[vw_appost]     
      WHERE  username = @username     
    
      IF @usercount > 0     
        BEGIN     
            SELECT [postid],     
                   [locid],     
                   [postname],     
                   [status]     
            FROM   [dbo].[vw_apppost]     
            WHERE  username = @username     
            UNION     
            SELECT [postid],     
                   [locid],     
                   [postname],     
                   '0' [status]     
            FROM   [dbo].[vw_totalpost]     
            WHERE  [postname] NOT IN (SELECT [postname]     
                                      FROM   [dbo].[vw_apppost]     
                                      WHERE  username = @username)     
        END     
      ELSE     
        BEGIN     
            SELECT po.postid,     
                   de.deptname,     
                   l.locid,     
                   [postname] + ' - ' + [deptname] + '(' + divname + ')'     
                   + ' - ' + l.location postname,     
                   po.[status]     
            FROM   [dbo].[trecruitappliedpost] po,     
                   trecruitdepartment de,     
                   trecruitdivision di,     
                   [trecruitpostlocationmap] pl,     
                   [trecruitpostlocation]l     
            WHERE  po.[deptid] = de.id     
                   AND de.id = di.deptid     
                   AND po.postid = pl.postid     
                   AND pl.locid = l.locid     
            UNION     
            SELECT po.postid,     
                   de.deptname,     
                   l.locid,     
                   [postname] + ' - ' + [deptname] + ' - ' + l.location postname     
                   ,     
                   po.[status]     
            FROM   [dbo].[trecruitappliedpost] po,     
                   trecruitdepartment de,     
                   [trecruitpostlocationmap] pl,     
                   [trecruitpostlocation]l     
            WHERE  po.[deptid] = de.id     
                   AND po.postid NOT IN (SELECT [postid]     
                                         FROM     
                       [dbo].[trecruitappliedpost] po     
                       ,     
                       trecruitdepartment de,     
                       trecruitdivision di     
                                         WHERE  po.[deptid] = de.id     
                                                AND de.id = di.deptid)     
                   AND po.postid = pl.postid     
                   AND pl.locid = l.locid     
        END     
  END 
GO



