  */      
Create Proc [dbo].[procupdatepostloc]      
@UserName Varchar(100),      
@PostID  Bigint,      
@LocationName Varchar(100)      
As      
Begin      
Declare @Result Varchar(1000)=''      
Declare @IDLocation  Bigint =0      
      
-- Location ID       
Select @IDLocation  =Isnull(locid,0)       
from trecruitpostlocation      
Where Upper(location)=upper(@LocationName)      
Begin Try       
 update trecruitcanappnum    set postid=@PostID,locid=@IDLocation,createdtime=getdate() where username=@UserName    
     
      
 Set @Result =''      
End Try       
Begin Catch       
 Set @Result=@@ERROR      
End Catch       
 Select @Result        
      
End 
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: none detected */
/****** Object:  StoredProcedure [dbo].[Sp_Get_PostNameByPassDept]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[Sp_Get_PostNameByPassDept]  
    @Date VARCHAR(MAX) = 'Jan-24'  
AS  
BEGIN  

-- sELECT POST Name base on @Date (Before the @Date all record is showing)
    SELECT   
        postname,   
        postid,   
        Createdtime 
    FROM   
        vw_Recruitment_AllPost  allPost
       
	 WHERE
             (@Date IS NOT NULL AND 
        LEFT(DATENAME(MONTH, CONVERT(DATETIME, allPost.Createdtime, 103)), 3) + '-' + CAST(YEAR(CONVERT(DATETIME, allPost.Createdtime, 103)) AS VARCHAR(4)) <=@Date)
        
		order by Createdtime desc

END;  
  
  
  
  
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: none detected */
/****** Object:  StoredProcedure [dbo].[Sp_GetActiveEmployeesByDepartment]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Sp_GetActiveEmployeesByDepartment]        
    @DeptID VARCHAR(MAX) = NULL,        
    @Action VARCHAR(20)        
AS        
BEGIN        
    SET NOCOUNT ON;        
        
    IF @Action = 'DepartmentName'        
    BEGIN        
        SELECT distinct        
            dpt.Department,        
            dpt.DepartmentId      
           -- emp.empfirstname + ' ' + ISNULL(emp.empmiddlename + ' ', '') + emp.emplastname AS EmployeeName,        
            --emp.empid        
        FROM         
            abcinfotechpvtltdESSP.dbo.Department AS dpt        
        INNER JOIN         
            abcinfotechpvtltdESSP.dbo.Empbasic AS emp         
        ON         
            dpt.DepartmentId = emp.empdept        
        WHERE         
            emp.empstatus = 'ACTIVE';        
    END        
    ELSE IF @Action = 'GetEmpname'        
    BEGIN        
        SELECT distinct        
            dpt.Department,        
            dpt.DepartmentId,        
            emp.empfirstname + ' ' + ISNULL(emp.empmiddlename + ' ', '') + emp.emplastname AS EmployeeName,        
            emp.empid        
        FROM         
            abcinfotechpvtltdESSP.dbo.Department AS dpt        
        INNER JOIN         
            abcinfotechpvtltdESSP.dbo.Empbasic AS emp         
        ON         
            dpt.DepartmentId = emp.empdept        
        WHERE         
            emp.empstatus = 'ACTIVE'        
            AND dpt.DepartmentId = @DeptID;        
    END        
END; 
GO



