      ,A.[trakerid]                                                
      ,A.[referenceno]                                                
      ,A.[departmentdivision]                                                
      ,A.[departmentdivisonname]                                                
      ,A.[rtpostid]                                                
      ,A.[rtpostname]                                                
      ,A.[rtlocid]                                                
      ,A.[headq]                                                
      ,A.[rtcandidateid]                                                
      ,A.[rtcandidatename]                                                
      ,A.[source]                                                
      ,A.[STARTDATE]                                                
      ,A.[cvselected]                                                
      ,A.[manualupdate]                                                
      ,A.[roneinterviewdate]                                                
      ,A.[roneinterviewernameone]                                                
      ,A.[roneinterviewernametwo]                                                
      ,A.[roneselect]                                       
      ,A.[roneinterviewenddate]                                    
      ,A.[rtwointerviewdate]                                                
      ,A.[rtwointerviewernameone]                                                
      ,A.[rtwointerviewernametwo]                                                
      ,A.[rtwoselect]                                     
  ,A.[rtwointerviewenddate]                                    
      ,A.[rthreeinterviewdate]                               
      ,A.[rthreeinterviewernameone]                                              
      ,A.[rthreeinterviewernametwo]                                                
      ,A.[rthreeselect]                                       
      ,A.[rthreeinterviewenddate]                                    
      ,A.[frinterviewdate]                                                
      ,A.[frinterviewernameone]                                                
      ,A.[frinterviewernametwo]                                                
      ,A.[frselect]                    
      ,A.[Frinterviewenddate]                                    
      ,A.[doo]                                                
      ,A.[doj]                           
      ,A.[empcode]                                                
      ,A.[completionstatus]                                                
      ,A.[timetaken]                                          
      ,A.[remarks]                                                
      ,A.[createdby]                                                
      ,A.[modifiedby]                                       
      ,A.[modifiedtime]                                                
      ,A.[rofileid]                                                
      ,A.[rocandidateid]                              
      ,A.[rofname]                                                
      ,A.[rofcontenttype]                                                
      ,A.[rofresumefile]                                                
      ,A.[ronerone]                                                
   ,A.[rosname]                                                
      ,A.[roscontenttype]                                                
      ,A.[rosresumefile]                                                
      ,A.[ronertwo]                                                
