/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: tbl_recruitPostActiveInactivStatus, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[PRC_APTIVE_POST_UPDATE_temp]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[PRC_APTIVE_POST_UPDATE_temp]    
@id bigint,    
@status bit    
AS    
BEGIN    
DECLARE @status_sp varchar(10)    
if @status=1    
BEGIN    
set @status_sp='Y' 
	Insert tbl_recruitPostActiveInactivStatus(plmapid,ActiveInactiveDate,Activeflag)
	  values(@id,getdate(),'Y');
END        
ELSE    
BEGIN    
	SET @status_sp='N'
	  Insert tbl_recruitPostActiveInactivStatus(plmapid,ActiveInactiveDate,Activeflag)
	  values(@id,getdate(),'N');
END        
UPDATE trecruitpostlocationmap set Activeflag=@status_sp where plmapid=@id    
END
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: Company, tbl_recruitPostActiveInactivStatus, trecruitappliedpost, trecruitdepartment, trecruitpostlocation, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[PRC_CREATE_ACTIVE_POST_NEW_Demo]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[PRC_CREATE_ACTIVE_POST_NEW_Demo]                     
@companyid int,                         
@deptid bigint,                                
@postName varchar(500),    
@postID varchar(500)=null,
@actualPostID varchar(500)=null,
@locid bigint,                                  
@username varchar(50) ,                        
@jobdescription nvarchar(MAX),                                    
@qualification nvarchar(MAX),                                    
@experience nvarchar(MAX),                                    
@age nvarchar(MAX),                                    
@responsibility nvarchar(MAX),                                    
@vacancy nvarchar(MAX),                                    
@jobnature nvarchar(MAX),                                    
@technicalscope nvarchar(MAX),                                    
@administrativescope nvarchar(MAX),                                    
@reporttopost nvarchar(MAX),                                    
@compensate nvarchar(MAX),                                    
@other nvarchar(MAX),                                    
@deadline nvarchar(MAX),              
@Isconfidential varchar(10),          
@TypeFresher varchar(max) =null,          
@TypeExperienced varchar(max)=null,          
@TypeSalesExperienced varchar(max)=null          
          
          
AS                                    
BEGIN                                    
DECLARE @Deptname varchar(max)                                    
   
DECLARE @plmapid bigint    
DECLARE @location varchar(max)    
DECLARE @createDate Datetime    
set @createDate=getdate();    
                        
 if exists(select Company from [dbo].[Company] where companypk=@companyid)                                
 begin                              
 print 'This Company already exists!'                              
 end                              
else                              
begin                                     
                        
INSERT INTO [dbo].[Company]                                  
               ([companyPK])                                  
        VALUES                                  
     (upper(@companyid))                                                                    
end                               
          
		  
SELECT @Deptname=[Deptname]                                    
  FROM [dbo].[trecruitdepartment]                                    
  WHERE id= @deptid                                  
  IF @postID IS NULL OR LTRIM(RTRIM(@postID)) = ''
    OR @actualPostID IS NULL OR LTRIM(RTRIM(@actualPostID)) = ''
  BEGIN
		 --Get ActualPostID Start  
		 Declare @ActualPostIDTbl Int  
		 if exists (Select * From trecruitappliedpost   where ltrim(rtrim(postname)) = ltrim(rtrim( upper(@postName))))  
		  BEGIN  
		   Select @ActualPostIDTbl=ActualPostID From trecruitappliedpost   where ltrim(rtrim( postname)) = ltrim(rtrim(upper(@postName)))  
		  END  
		  ELSE  
			 BEGIN  
				SELECT Top 1  @ActualPostIDTbl=ActualPostID+1  FROM [Recruitment].dbo.trecruitappliedpost GROUP BY ActualPostID Order by ActualPostID desc  
		    END  
		--Get ActualPostID End 
			INSERT INTO [dbo].[trecruitappliedpost]                                    
				([postname],                                    
				 status ,                                  
				 [Deptid],                        
				 IDCompany,                        
				 CreatedBy,                                    
				 Createdtime,  
				 ActualPostID  
				  )                                    
			 VALUES                                    
				   (upper(@postName),                                    
					0,                                    
					@deptid,                        
			        @companyid,                        
		            @username,                        
				    @createDate,  
		            @ActualPostIDTbl) 

		SELECT @postid= @@IDENTITY            
  End
ELSE
  BEGIN 
	 Update trecruitappliedpost set  Deptid=@deptid ,IDCompany=@companyid
	 where postid=@postID	 and ActualPostID=@actualPostID
  END

 
		 
SELECT @location=location                                 
  FROM [dbo].[trecruitpostlocation]                                    
  WHERE  [locid]=@locid                                    
 
 
		BEGIN TRY                      
				 BEGIN TRANSACTION; 

			INSERT INTO [dbo].[trecruitpostlocationmap]                                    
					   ([postid],                                    
					   [locid],                                    
					   [Activeflag] ,                           
				  JobDescription,                                    
						Qualifications ,        
						 Experience   ,                                 
						 Age ,                                 
						Jobresponsibility ,                                   
						Jobvacancy  ,                                 
						Jobnature  ,                                 
						TechnicalScope ,                                  
					   AdministrativeScope ,                                
					   Reporttopost ,                                   
					  Compensate ,                                  
					  Others   ,                       
					DeadLine,           
			  [Confidentialpost],                
			  [createdby] ,                                   
			[Createdtime],          
			[TypeFresher],          
			[TypeExperienced],          
			[TypeSalesExperienced], 
			[ATS_HEAD_RATING_ID]
					   )                                    
				 VALUES                                    
					   (@postID,                                    
					   @locid,                                    
						'Y',                 
				  @jobdescription,                                    
						@qualification,                                    
						@experience,                                    
						@age,                                    
					 @responsibility,                                    
						@vacancy,                                    
						@jobnature,                                    
						@technicalscope,                                    
						@administrativescope,                                             
			   @reporttopost,                                    
						@compensate,                                    
						@other,                           
						@deadline,              
			   @Isconfidential,              
						@username ,                                   
					   @createDate,          
			   @TypeFresher,          
			   @TypeExperienced ,          
			   @TypeSalesExperienced,
			   1
					   )                                     
			 SELECT @plmapid=@@IDENTITY    
			 Insert tbl_recruitPostActiveInactivStatus(plmapid,ActiveInactiveDate,Activeflag)    
			   values(@plmapid,getdate(),'Y');    
	  COMMIT TRANSACTION;                             
			END TRY                      
			BEGIN CATCH                      
		    ROLLBACK TRANSACTION;                      
                      
			END CATCH;   
END     
GO



