SELECT @location=location                               
  FROM [dbo].[trecruitpostlocation]                                  
  WHERE  [locid]=@locid                                  
                                  
INSERT INTO [dbo].[trecruitpostlocationmap]                                  
           ([postid],                                  
           [locid],                                  
           [Activeflag] ,                         
      JobDescription,                                  
            Qualifications ,      
             Experience   ,                               
             Age ,                               
            Jobresponsibility ,                                 
            Jobvacancy  ,                               
            Jobnature  ,                               
            TechnicalScope ,                                
           AdministrativeScope ,                              
           Reporttopost ,                                 
          Compensate ,                                
