        DeadLine,         
  [Confidentialpost],              
  [createdby] ,                                 
[Createdtime],        
[TypeFresher],        
[TypeExperienced],        
[TypeSalesExperienced]                
           )                                  
     VALUES                                  
           (@postid,                                  
           @locid,                                  
            'Y',               
      @jobdescription,                                  
            @qualification,                                  
            @experience,                                  
            @age,                                  
         @responsibility,                                  
            @vacancy,                                  
            @jobnature,                                  
            @technicalscope,                                  
            @administrativescope,                                           
   @reporttopost,                                  
            @compensate,                                  
            @other,                         
            @deadline,            
   @Isconfidential,            
            @username ,                                 
           @createDate,        
   @TypeFresher,        
   @TypeExperienced ,        
   @TypeSalesExperienced         
           )                                   
 SELECT @plmapid=@@IDENTITY  
    
 Insert tbl_recruitPostActiveInactivStatus(plmapid,ActiveInactiveDate,Activeflag)  
   values(@plmapid,getdate(),'Y');  
END   


