/****** Object:  StoredProcedure [dbo].[PRC_CREATE_ACTIVE_POST_TEMP]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create PROCEDURE [dbo].[PRC_CREATE_ACTIVE_POST_TEMP]
    @createdBy varchar(max),
    @companyid INT,
    @deptid BIGINT,
    @postName VARCHAR(500),
    @postID VARCHAR(500) = NULL,
    @actualPostID VARCHAR(500) = NULL,
    @locid BIGINT,
    @username VARCHAR(50),
    @jobdescription NVARCHAR(MAX),
    @qualification NVARCHAR(MAX),
    @experience NVARCHAR(MAX),
    @age NVARCHAR(MAX) = NULL,
    @responsibility NVARCHAR(MAX),
    @vacancy NVARCHAR(MAX),
    @jobnature NVARCHAR(MAX),
    @technicalscope NVARCHAR(MAX),
    @administrativescope NVARCHAR(MAX),
    @reporttopost NVARCHAR(MAX),
    @compensate NVARCHAR(MAX),
    @other NVARCHAR(MAX),
    @deadline NVARCHAR(MAX) = NULL,
    @Isconfidential VARCHAR(10),
    @objectives NVARCHAR(MAX) = NULL,
    @jobTitle NVARCHAR(MAX) = NULL,
    @jobDescriptionFilePath NVARCHAR(MAX) = NULL,
    @jobDescriptionFileExtension NVARCHAR(MAX) = NULL,
    @TypeFresher VARCHAR(MAX) = NULL,
    @TypeExperienced VARCHAR(MAX) = NULL,
    @TypeSalesExperienced VARCHAR(MAX) = NULL,
    @EmpDeptId VARCHAR(50),
    @Ats_Head_Rating_ID VARCHAR(50) = NULL,
    @status VARCHAR(MAX) = NULL OUTPUT
AS
BEGIN
    DECLARE @HodId INT = NULL
    DECLARE @MdId INT = dbo.GetCompanyMDEmpNo()
    DECLARE @Deptname VARCHAR(MAX)
    DECLARE @plmapid BIGINT
    DECLARE @location VARCHAR(MAX)
    DECLARE @createDate DATETIME = GETDATE()

    -- Fetch HOD ID
    SELECT @HodId = empno
    FROM ESSP.dbo.Employee_DepartmentHODMap
    WHERE Activeflag = 1 AND DepartmentID = @EmpDeptId

    -- Restrict if HOD does not exist
    IF @HodId IS NULL
    BEGIN
        SET @status = 'Your Department HOD is not specified. Please specify the HOD first.'
        RETURN
    END

    -- Ensure company exists or insert
    IF NOT EXISTS (SELECT 1 FROM [dbo].[Company] WHERE companypk = @companyid)
    BEGIN
        INSERT INTO [dbo].[Company] ([companyPK])
        VALUES (UPPER(@companyid))
    END

    SELECT @Deptname = [Deptname] FROM [dbo].[trecruitdepartment] WHERE id = @deptid

    -- Generate ActualPostID if needed
    IF (ISNULL(LTRIM(RTRIM(@postID)), '') = '' OR ISNULL(LTRIM(RTRIM(@actualPostID)), '') = '')
    BEGIN
        DECLARE @ActualPostIDTbl INT

        SELECT @ActualPostIDTbl = ActualPostID
        FROM trecruitappliedpost
        WHERE LTRIM(RTRIM(postname)) = LTRIM(RTRIM(UPPER(@postName)))

        IF @ActualPostIDTbl IS NULL
        BEGIN
            SELECT TOP 1 @ActualPostIDTbl = ActualPostID + 1
            FROM trecruitappliedpost
            GROUP BY ActualPostID
            ORDER BY ActualPostID DESC
        END

        -- Insert new post
        INSERT INTO [dbo].[trecruitappliedpost]
        (
            [postname], status, [Deptid], IDCompany, CreatedBy,
            Createdtime, ActualPostID
        )
        VALUES
        (
            UPPER(@postName), 0, @deptid, @companyid,
            @username, @createDate, @ActualPostIDTbl
        )
        SELECT @postid = SCOPE_IDENTITY()
    END
    ELSE
    BEGIN
        UPDATE trecruitappliedpost
        SET Deptid = @deptid, IDCompany = @companyid
        WHERE postid = @postID AND ActualPostID = @actualPostID
    END

    -- Get location name
    SELECT @location = location FROM [dbo].[trecruitpostlocation] WHERE locid = @locid

    BEGIN TRY
        BEGIN TRANSACTION;

        -- Insert location mapping and post details

        INSERT INTO [dbo].[trecruitpostlocationmap]
        (
            [postid], [locid], [Activeflag], [JobDescription], [Qualifications],
            [Experience], Age, Jobresponsibility, Jobvacancy, Jobnature,
            TechnicalScope, AdministrativeScope, Reporttopost, Compensate,
            Others, DeadLine, [Confidentialpost], [createdby],[CreatedByEmpno], [Createdtime],
            [TypeFresher], [TypeExperienced], [TypeSalesExperienced],
            [JobTitle], [Objectives], [JobDescriptionFilePath],
            [JobDescriptionFileExtension], [ATS_HEAD_RATING_ID], [FullApprove]
        )
        VALUES
        (
            @postID, @locid, 'N', @jobdescription, @qualification,
            @experience, @age, @responsibility, @vacancy, @jobnature,
            @technicalscope, @administrativescope, @reporttopost, @compensate,
            @other, @deadline, @Isconfidential, @username,@createdBy, @createDate,
            @TypeFresher, @TypeExperienced, @TypeSalesExperienced,
            @jobTitle, @objectives, @jobDescriptionFilePath,
            @jobDescriptionFileExtension, @Ats_Head_Rating_ID, 0
        )


        SELECT @plmapid = SCOPE_IDENTITY()
        -- Insert Approval Permissions
        INSERT INTO tbl_postActivePermission (PlmapId, EmpId, Status, StatusDate,CreatedBy)
        VALUES (@plmapid, @HodId, 0, GETDATE(),@createdBy), (@plmapid, @MdId, 0, GETDATE(),@createdBy)

		--Select * from tbl_postActivePermission


        DECLARE @MailId NVARCHAR(MAX)
        SELECT @MailId = STRING_AGG(empemail, ';')
        FROM ESSP.dbo.empbasic
        WHERE empno IN (@HodId, @MdId)

        DECLARE @NotifayPersion NVARCHAR(MAX)
        SELECT @NotifayPersion = STRING_AGG(dbo.Employee_FullName(empfirstname, empmiddlename, emplastname), ', ')
        FROM ESSP.dbo.empbasic
        WHERE empno IN (@MdId, @HodId)

        DECLARE @tableHTML NVARCHAR(MAX)
        DECLARE @departmentNameMail NVARCHAR(MAX)
        DECLARE @subjectMail NVARCHAR(MAX)
        DECLARE @postNameMail NVARCHAR(MAX)
        DECLARE @locationMail NVARCHAR(MAX)

        SELECT @postNameMail = B.postname,
               @departmentNameMail = A.deptname,
               @locationMail = A.location
        FROM vw_Recruitment_AllPost A
        INNER JOIN trecruitappliedpost B ON B.postid = A.postid
        WHERE A.plmapid = @plmapid

        SET @subjectMail = 'Post Creation Request: ' + @postNameMail + ' - ' + @departmentNameMail + ' - ' + @locationMail

        SET @tableHTML =
        '<html><body style="font-family:Tahoma;font-size:14px;">' +
        '<p>Dear Sir/Madam,</p>' +
        '<p>This is a system-generated email to notify you that a request for creating a new post has been initiated.</p><br/>' +
        '<table border="1" cellpadding="8" cellspacing="0" style="border-collapse:collapse;font-size:14px;">' +
        '<tr style="background-color:#f2f2f2;"><th>Post Name</th><th>Department</th><th>Location</th></tr>' +
        '<tr><td>' + @postNameMail + '</td><td>' + @departmentNameMail + '</td><td>' + @locationMail + '</td></tr>' +
        '</table><br/><p>Thank You.</p></body></html>'

        EXEC msdb.dbo.sp_send_dbmail
            @profile_name = 'Mendine_Recruitment_Profile',
            @recipients = @MailId,
            @subject = @subjectMail,
            @body = @tableHTML,
            @importance = 'HIGH',
            @body_format = 'HTML'

        COMMIT TRANSACTION

        SET @status = 'This post has been sent for approval by ' + @NotifayPersion
    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION
        SET @status = 'An error occurred: ' + ERROR_MESSAGE()
    END CATCH
END
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: trecruitappliedpost */
/****** Object:  StoredProcedure [dbo].[PRC_GetLocationsByPostName_temp]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PRC_GetLocationsByPostName_temp]      
    @DeptId nvarchar(max),  
  @PostID VARCHAR(MAX)   
   
AS      
BEGIN      
    SET NOCOUNT ON;      
      
    SELECT DISTINCT locid, location      
    FROM vw_Recruitment_AllPost      
    --WHERE postid IN (SELECT name FROM dbo.splitstring(@PostID))      
  WHERE postid IN (Select postid from [trecruitappliedpost] where ActualPostID IN (SELECT name FROM dbo.splitstring(@PostID)))      
        and DeptId IN (SELECT name FROM dbo.splitstring(@DeptId))  
 ORDER BY location ASC;      
END;
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: Company, trecruitappliedpost, trecruitdepartment */
/****** Object:  StoredProcedure [dbo].[PRC_Receruitment_Department_List_temp]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[PRC_Receruitment_Department_List_temp]    
@companyId varchar(500)  
As                
Begin                
--Select ID, DeptName from [trecruitdepartment]              
--union             
--select '' ID , 'OTHER' Deptname from [trecruitdepartment]           
WITH CTE AS (          
   --SELECT ID, DeptName,ActiveFlag,  ROW_NUMBER() OVER (PARTITION BY  DeptName  ORDER BY (SELECT 0)) AS rn          
   --FROM  [trecruitdepartment]    
   select B.id,B.Deptname,B.ActiveFlag,C.companyPK,  
   ROW_NUMBER() OVER (PARTITION BY  B.DeptName  ORDER BY (SELECT 0)) AS rn  
   from trecruitappliedpost A  
  Inner Join  trecruitdepartment B on A.Deptid= B.id  
  Inner join  Company C  on A.IDCompany=C.companyPK  
   union    
   -- select '' ID,'OTHER' Deptname,B.ActiveFlag, 1 companyPK,  
   --ROW_NUMBER() OVER (PARTITION BY  B.DeptName  ORDER BY (SELECT 0)) AS rn  
   -- from trecruitappliedpost A  
   --Inner Join  trecruitdepartment B on A.Deptid= B.id  
   --Inner join  Company C  on A.IDCompany=C.companyPK  
   select '' ID , 'OTHER' Deptname,ActiveFlag,1 companyPK,ROW_NUMBER() OVER (PARTITION BY  DeptName  ORDER BY (SELECT 0)) AS rn from [trecruitdepartment]             
          
)          
SELECT ID, DeptName,companyPK           
FROM CTE          
WHERE rn = 1 and Deptname !='' and Deptname is not null and  ActiveFlag !='N'  
     and companyPK=@companyId  AND Deptname not like '%DEMO%'
Order by DeptName    
End   

select * from Company

select * from trecruitdepartment
select * from trecruitappliedpost
GO



/* Functional group: 02_JOB_REQUISITION; referenced grouped tables: trecruitappliedpost, trecruitdepartment, trecruitdivision, trecruitpostlocation, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[PRC_Receruitment_DepartmentwisePost_List_Temp]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--Sp_helptext PRC_Receruitment_DepartmentwisePost_List
-- PRC_Receruitment_DepartmentwisePost_List  'Sales'        
CREATE Proc [dbo].[PRC_Receruitment_DepartmentwisePost_List_Temp]            
          
@departmentId INT          
As            
Begin           
          
  SELECT po.postid, de.id,de.deptname,l.locid,[postname] +' - '+ [Deptname]+'('+divname+')'+' - '+l.location postname ,po.[status]                
FROM [dbo].[trecruitappliedpost] po,                
trecruitdepartment de,                
trecruitdivision di ,                
[trecruitpostlocationmap] pl,                
[trecruitpostlocation]l                
where po.[Deptid]=de.id                
and de.id=di.deptid                
and po.postid=pl.postid                
and pl.locid=l.locid        
and de.id = @departmentId           
union                
SELECT po.postid, de.id,de.deptname,l.locid,[postname] +' - '+ [Deptname]+' - '+ l.location postname ,po.[status]                
FROM [dbo].[trecruitappliedpost] po,                
trecruitdepartment de ,                
[trecruitpostlocationmap] pl,                
[trecruitpostlocation]l                
where po.[Deptid]=de.id                
and po.postid not in (SELECT [postid]                
FROM [dbo].[trecruitappliedpost] po,trecruitdepartment de,trecruitdivision di where po.[Deptid]=de.id                
and de.id=di.deptid)                
and po.postid=pl.postid                
and pl.locid=l.locid         
and de.id = @departmentId        
Order by postname  
--SELECT postname,postid FROM [vw_hrselectpost] where deptname=@department          
          
END
GO



