CREATE PROC [dbo].[PRC_UPDATE_ACTIVE_POST_temp]                                      
                                          
@postname bigint,            
@username varchar(max),            
@jobdescription nvarchar(MAX),                          
@qualification nvarchar(MAX),                          
@experience nvarchar(MAX),                          
@age nvarchar(MAX),                          
@responsibility nvarchar(MAX),                          
@vacancy nvarchar(MAX),                          
@jobnature nvarchar(MAX),                          
@technicalscope nvarchar(MAX),                          
@administrativescope nvarchar(MAX),                          
@reporttopost nvarchar(MAX),                          
@compensate nvarchar(MAX),                          
@other nvarchar(MAX),                          
@deadline nvarchar(MAX),    
@TypeFresher varchar(max) =null,      
@TypeExperienced varchar(max)=null,      
@TypeSalesExperienced varchar(max)=null     
                          
AS             
BEGIN              
UPDATE [trecruitpostlocationmap] SET             
JobDescription=@jobdescription,                          
Qualifications=@qualification,                          
Experience=@experience,                          
Age=@age,                          
Jobresponsibility=@responsibility,                          
Jobvacancy=@vacancy,                          
Jobnature=@jobnature,                          
TechnicalScope=@technicalscope,                          
AdministrativeScope=@administrativescope,                          
Reporttopost=@reporttopost,                          
Compensate=@compensate,                          
Others=@other,                          
DeadLine=@deadline,            
createdby =@username,            
Createdtime=GETDATE(),    
[TypeFresher]=@TypeFresher,      
[TypeExperienced]=@TypeExperienced,      
[TypeSalesExperienced]=@TypeSalesExperienced    
where plmapid=@postname             
END
GO



