-- Proc_CompanyWisePost_NEW_Sample  2 , 36
CREATE PROCEDURE [dbo].[Proc_CompanyWisePost_NEW_Sample]            
@companyid int  ,  
@locid int 
AS            
BEGIN            
            
            
SELECT po.postid,cm.Company,de.deptname,l.locid,[postname] +' - '+ [Deptname]+'('+divname+')'+' - '+l.location postname ,po.[status]          
FROM [dbo].[trecruitappliedpost] po,          
trecruitdepartment de,          
trecruitdivision di ,          
[trecruitpostlocationmap] pl,          
[trecruitpostlocation]l ,        
[Company] cm          
where po.[Deptid]=de.id          
and de.id=di.deptid          
and po.postid=pl.postid          
and pl.locid=l.locid        
and po.IDCompany = cm.companyPK        
and companyPK=@companyid   
and pl.locid = @locid 
and pl.Activeflag ='Y'      
union          
SELECT po.postid,cm.Company,de.deptname,l.locid,[postname] +' - '+ [Deptname]+' - '+ l.location postname ,po.[status]          
FROM [dbo].[trecruitappliedpost] po,          
trecruitdepartment de ,          
[trecruitpostlocationmap] pl,          
[trecruitpostlocation]l ,        
[Company] cm          
where po.[Deptid]=de.id          
and po.postid not in (SELECT [postid]          
FROM [dbo].[trecruitappliedpost] po,trecruitdepartment de,trecruitdivision di where po.[Deptid]=de.id          
and de.id=di.deptid)          
and po.postid=pl.postid          
and pl.locid=l.locid        
and po.IDCompany = cm.companyPK        
and companyPK=@companyid  
and pl.locid = @locid 
and pl.Activeflag ='Y'      
 end 
