SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/****** Script for SelectTopNRows command from SSMS  ******/ 
CREATE PROCEDURE [dbo].[procselectappostest] @username VARCHAR(100) 
AS 
  BEGIN 
      DECLARE @usercount INT 

      SELECT @usercount = Count(username) 
      FROM   [dbo].[vw_appost] 
      WHERE  username = @username 

      IF @usercount > 0 
        BEGIN 
            SELECT  
                   [postid], 
                   [locid], 
                   [postname], 
                   [status]
            FROM   [dbo].[vw_apppost] 
            WHERE  username = @username 
            UNION 
            SELECT [postid],                   
                   [locid], 
                   [postname], 
                   '0'[status] 
            FROM   [dbo].[vw_totalpost] 
            WHERE  [postname] NOT IN (SELECT [postname] 
                                      FROM   [dbo].[vw_apppost] 
                                      WHERE  username = @username) 
        END 
      ELSE 
        BEGIN 
            SELECT [postid],                   
                   [locid], 
                   [postname], 
                   '0'[status]  
            FROM   [dbo].[vw_totalpost] 
        END 
  END 
GO



