SET QUOTED_IDENTIFIER ON
GO

CREATE procedure [dbo].[procselectpost_NEW_temp]                    
as                    
begin                    
                  
declare @Status_bit varchar(10)                
declare @Status bit                 
                  
 SELECT @Status_bit=pl.Activeflag                   
FROM [trecruitappliedpost] po,                    
trecruitdepartment de,                    
trecruitdivision di ,                    
[trecruitpostlocationmap] pl,                    
[trecruitpostlocation]l                    
where po.[Deptid]=de.id                    
and de.id=di.deptid                    
and po.postid=pl.postid                    
and pl.locid=l.locid                    
                  
                  
--if(@Status_bit='Y')                  
--Begin                  
--set @Status=1                 
--End                  
                  
--if(@Status_bit='N')                
--Begin                  
--set @Status=0                 
--End                  
		SELECT *,ROW_NUMBER() Over (Order BY M.postname) SRL FROM(    
				SELECT pl.plmapid, cm.Company, po.postid, de.deptname, l.locid, 
				   [postname] + ' - ' + [Deptname] + '(' + divname + ')' + ' - ' + l.location AS postname, 
				   po.IDCompany, pl.JobDescription, pl.Qualifications,              
				   pl.Experience, pl.Age, pl.Jobresponsibility, pl.Jobvacancy, 
				   pl.Jobnature, pl.TechnicalScope, pl.AdministrativeScope,              
				   pl.Reporttopost, pl.Compensate, pl.Others, pl.DeadLine, 
				   pl.Confidentialpostlink,           
				   CASE            
					   WHEN pl.Activeflag = 'Y' THEN CAST(1 AS BIT)            
					   WHEN pl.Activeflag = 'N' THEN CAST(0 AS BIT)            
				   END AS [status]                   
			FROM trecruitpostlocationmap pl
			JOIN trecruitappliedpost po ON po.postid = pl.postid                    
			JOIN trecruitdepartment de ON po.Deptid = de.id                    
			JOIN trecruitdivision di ON de.id = di.deptid                    
			JOIN trecruitpostlocation l ON pl.locid = l.locid      
			JOIN Company cm ON po.IDCompany = cm.companyPK
			WHERE 
			(pl.FullApprove=1 or pl.FullApprove IS NULL)
			--	-- Condition 1: If PlmapId exists in tbl_postActivePermission, then Status must be 1
			--	EXISTS (
			--		SELECT 1 
			--		FROM tbl_postActivePermission pa 
			--		WHERE pa.PlmapId = pl.plmapid 
			--		AND pa.Status = 1
			--	)
			--	-- Condition 2: If PlmapId does NOT exist in tbl_postActivePermission, select it
			--	OR NOT EXISTS (
			--		SELECT 1 
			--		FROM tbl_postActivePermission pa 
			--		WHERE pa.PlmapId = pl.plmapid
			--	)
--33
		    
	union          
			SELECT pl.plmapid, cm.Company, po.postid, de.deptname, l.locid, 
				   [postname] + ' - ' + [Deptname] + ' - ' + l.location AS postname, 
				   po.IDCompany, pl.JobDescription, pl.Qualifications,              
				   pl.Experience, pl.Age, pl.Jobresponsibility, pl.Jobvacancy, 
				   pl.Jobnature, pl.TechnicalScope, pl.AdministrativeScope,              
				   pl.Reporttopost, pl.Compensate, pl.Others, pl.DeadLine, 
				   pl.Confidentialpostlink,                       
				   CASE            
					   WHEN pl.Activeflag = 'Y' THEN 1            
					   WHEN pl.Activeflag = 'N' THEN 0            
				   END AS status
			FROM trecruitpostlocationmap pl
			JOIN trecruitappliedpost po ON po.postid = pl.postid                    
			JOIN trecruitdepartment de ON po.Deptid = de.id                    
			JOIN trecruitpostlocation l ON pl.locid = l.locid      
			JOIN Company cm ON po.IDCompany = cm.companyPK
			WHERE 
				-- Exclude posts that are in a certain department-division mapping
				po.postid NOT IN (
					SELECT po.postid                    
					FROM trecruitappliedpost po
					JOIN trecruitdepartment de ON po.Deptid = de.id
					JOIN trecruitdivision di ON de.id = di.deptid
				)
				AND (pl.FullApprove=1 or pl.FullApprove IS NULL)
				-- Condition 1: If PlmapId exists in tbl_postActivePermission, then Status must be 1
				--AND (
				--	EXISTS (
				--		SELECT 1 
				--		FROM tbl_postActivePermission pa 
				--		WHERE pa.PlmapId = pl.plmapid 
				--		AND pa.Status = 1
				--	)
				--	-- Condition 2: If PlmapId does NOT exist in tbl_postActivePermission, select it
				--	OR NOT EXISTS (
				--		SELECT 1 
				--		FROM tbl_postActivePermission pa 
				--		WHERE pa.PlmapId = pl.plmapid
				--	)
				--)
			--344	
)M        
Order By M.postname       
 end 
GO



