/****** Object:  StoredProcedure [dbo].[Sp_GetActiveEmployeesByDepartment_temp]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Sp_GetActiveEmployeesByDepartment_temp]        
    @DeptID VARCHAR(MAX) = NULL,        
    @Action VARCHAR(20)        
AS        
BEGIN        
    SET NOCOUNT ON;        
        
    IF @Action = 'DepartmentName'        
    BEGIN        
        SELECT distinct        
            dpt.Department,        
            dpt.DepartmentId ,     
            emp.empfirstname + ' ' + ISNULL(emp.empmiddlename + ' ', '') + emp.emplastname AS EmployeeName,        
            emp.empid        
        FROM         
            abcinfotechpvtltdESSP.dbo.Department AS dpt        
        INNER JOIN         
            abcinfotechpvtltdESSP.dbo.Empbasic AS emp         
        ON         
            dpt.DepartmentId = emp.empdept        
        WHERE         
            emp.empstatus = 'ACTIVE';        
    END        
    ELSE IF @Action = 'GetEmpname'        
    BEGIN        
        SELECT distinct        
            dpt.Department,        
            dpt.DepartmentId,        
            emp.empfirstname + ' ' + ISNULL(emp.empmiddlename + ' ', '') + emp.emplastname AS EmployeeName,        
            emp.empid        
        FROM         
            abcinfotechpvtltdESSP.dbo.Department AS dpt        
        INNER JOIN         
            abcinfotechpvtltdESSP.dbo.Empbasic AS emp         
        ON         
            dpt.DepartmentId = emp.empdept        
        WHERE         
            emp.empstatus = 'ACTIVE'        
            AND dpt.DepartmentId = @DeptID;        
    END        
END; 
GO





