CREATE   PROCEDURE [dbo].[PRC_CHECK_RECRUIT_CANDIDATE_SIGNUP_BY_ID]
    @CandidateID BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT TOP 1
        CandidateID,
        FirstName,
        Middlename,
        Lastname,
