/* Functional group: 03_CANDIDATE_REGISTRATION_AND_APPLY; referenced grouped tables: trecruitappliedpost, trecruitcandidateresgisterdtls, trecruitdepartment, trecruitpostlocation, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[PRC_GetLMS_CandidateDtls]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 CREATE PROC [dbo].[PRC_GetLMS_CandidateDtls]
  @userName nvarchar(max)
 AS                                                      
BEGIN  
  Declare @CandidatePostName nvarchar(max)
  Declare @CandidateDeparttName nvarchar(max)
  Declare @CandidateLocationName nvarchar(max)

 Declare @AppliedPostDtls nvarchar(max)
 Declare @AppliedPosId bigint
 Declare @AppliedPosCompId int

 select 
@AppliedPostDtls =Appliedpost,
@AppliedPosId= IDPost,
@AppliedPosCompId=IDCompany
from Recruitment.dbo.trecruitcandidateresgisterdtls WHERE username=@userName
	



	--DECLARE @str NVARCHAR(MAX) = 'SENIOR WEB DEVELOPER - MANAGEMENT INFORMATION SYSTEM - KOLKATA';

-- Replace ' - ' with a unique delimiter
SET @AppliedPostDtls = REPLACE(@AppliedPostDtls, ' - ', '|');

-- Convert to XML and extract values
WITH Parsed AS (
    SELECT CAST('<x>' + REPLACE(@AppliedPostDtls, '|', '</x><x>') + '</x>' AS XML) AS Data
)
SELECT  
   @CandidatePostName=TRIM(Data.value('/x[1]', 'NVARCHAR(MAX)')) ,
   @CandidateDeparttName=TRIM(Data.value('/x[2]', 'NVARCHAR(MAX)')) ,
   @CandidateLocationName=TRIM(Data.value('/x[3]', 'NVARCHAR(MAX)')) 
FROM Parsed;
  --print @CandidatePostName +' '+@CandidateDeparttName+''+@CandidateLocationName
  SELECT C.postname,C.ActualPostID,D.Deptname,D.id,B.location,B.locid  from Recruitment.dbo.trecruitpostlocationmap A
  Inner join Recruitment.dbo.trecruitpostlocation B on B.locid =A.locid
  Inner join  Recruitment.dbo.trecruitappliedpost C on C.postid = A.postid
  INNER join  Recruitment.dbo.trecruitdepartment D on D.id =C.Deptid
  where C.postid=@AppliedPosId  and D.Deptname=@CandidateDeparttName
END
GO



