/* Functional group: 03_CANDIDATE_REGISTRATION_AND_APPLY; referenced grouped tables: Company, trecruitcandidateresgisterdtls, trecruitcandidatesignup */
/****** Object:  StoredProcedure [dbo].[SP_CANDIDATE_ACCOUNT_CREATED]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_CANDIDATE_ACCOUNT_CREATED]  
(  
@Username      VARCHAR(200) = NULL,  
@MailID        VARCHAR(200) = NULL,  
@Company       VARCHAR(500) = NULL,  
@SelectPost    VARCHAR(500) = NULL,  
@IDCompany     BIGINT = NULL,  
@IDPost        BIGINT = NULL,  
@CandidateID   BIGINT OUTPUT  
)  
AS  
BEGIN  
SET NOCOUNT ON;  
  
  
-- Check if candidate already exists  
IF EXISTS  
(  
    SELECT 1  
    FROM trecruitcandidatesignup  
    WHERE MailId = @MailID  
       OR UserName = @Username  
)  
BEGIN  
    SET @CandidateID = 0;  
    RETURN;  
END  
  
BEGIN TRY  
    BEGIN TRANSACTION;  
  
    SET @CandidateID = NEXT VALUE FOR s_candidate_signup;  
  
    INSERT INTO trecruitcandidatesignup  
    (  
        CandidateID,  
        UserName,  
        MailId,  
        CreatedTime,  
        ModifiedTime  
    )  
    VALUES  
    (  
        @CandidateID,  
        @Username,  
        @MailID,  
        GETDATE(),  
        GETDATE()  
    );  
  
    INSERT INTO trecruitcandidateresgisterdtls  
    (  
        Id,  
        UserName,  
        MailId,  
        CompanyName,  
        AppliedPost,  
        IDCompany,  
        IDPost,  
        CreatedTime  
    )  
    VALUES  
    (  
        @CandidateID,  
        @Username,  
        @MailID,  
        @Company,  
        @SelectPost,  
        @IDCompany,  
        @IDPost,  
        GETDATE()  
    );  
  
    COMMIT TRANSACTION;  
END TRY  
BEGIN CATCH  
    IF @@TRANCOUNT > 0  
        ROLLBACK TRANSACTION;  
  
    SET @CandidateID = -1;  
    THROW;  
END CATCH  
  
  
END
GO





