  CREATE PROCEDURE [dbo].[GetCandidateBasicDetails]
    @CandidateId nvarchar(max)
AS
BEGIN
    SET NOCOUNT ON;

    SELECT *
    FROM trecruitcanbasicdtls
    WHERE candidateid = @CandidateId;
END;
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: temployeehistory_sales, tEmploymentHistory, trecruitcanbasicdtls, trecruitcandidateresgisterdtls, trecruitcandidatesignup, tRecruitcanotherdtls, tRecruitEduQualification, trecruitotpverify, trecruitProfessionalExpGap, trecruitProfessionalSalesExpGap */
/****** Object:  StoredProcedure [dbo].[PRC_CANDIDATE_DTLS_DELATE]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[PRC_CANDIDATE_DTLS_DELATE]        
@userName nvarchar(max)    
As
BEGIN
 DECLARE @candidateId BIGINT
 SELECT @candidateId = [candidateid]       
          FROM   [dbo].[trecruitcandidatesignup]       
          WHERE  [username] =@userName

	DELETE from trecruitcanbasicdtls where candidateid=@candidateId
	--Qulafaction
	DELETE from tRecruitEduQualification where candidateid=@candidateId
	DELETE from trecruitProfessionalExpGap where candidateid=@candidateId

	--Employment Hist
	DELETE from tRecruitcanotherdtls where candidateid=@candidateId
	--Only Exp
	DELETE from tEmploymentHistory where candidateid=@candidateId
	DELETE from trecruitProfessionalExpGap where candidateid=@candidateId
	--Only Sales 
	DELETE from temployeehistory_sales where candidateid=@candidateId
	DELETE from trecruitProfessionalSalesExpGap where candidateid=@candidateId

	--SING UP DTLS
    DELETE from trecruitcandidateresgisterdtls where username=@userName
	DELETE FROM trecruitotpverify WHERE username=@userName
	DELETE FROM [trecruitcandidatesignup] WHERE username=@userName

END
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: aspnet_Membership, aspnet_Users, Company, trecruitappliedpost, trecruitdepartment, trecruitpostlocation, trecruitProfile, TrecruitProfileDetail */
/****** Object:  StoredProcedure [dbo].[PRC_Candidate_Profile]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- PRC_Candidate_Profile 'pallab2021'  
CREATE Proc [dbo].[PRC_Candidate_Profile]    
@UserName   Varchar(100)    
As    
Begin    
Declare @UserID  Varchar(100)=''  
Declare @UserMail Varchar(200)=''  
  
Select @UserID= Convert(Varchar(100), A.UserID)  
from aspnet_Users A  
Where A.UserName=@UserName  
  
  
Select @UserMail= A.Email   
from aspnet_Membership A  
Where A.UserId= @UserID  
  
  
  
  
 Select  A.IDProfile,A.IDDepartment, B.Deptname Department,    
    A.IDPost , C.postname Post,     
    A.IDLocation , D.location,    
    A.IDCompany, E.Company,    
    F.FirstName,Isnull(F.MiddleName,'') MiddleName,F.LastName,    
     F.Email    
 from  trecruitProfile   A    
 Left Join trecruitdepartment  B on A.IDDepartment= B.id    
 Left Join trecruitappliedpost  C on A.IDPost=C.postid    
 Left Join trecruitpostlocation D on A.IDLocation = D.locid    
 Left Join Company     E on A.IDCompany=E.companyPK    
 Left Join trecruitProfileDetail F on A.IDProfile=F.IDProfile    
 Where  F.Email = @UserMail     
    
    
End    

GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: test, trecruitcandidateresgisterdtls, trecruitpostlocation, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[PRC_Candidate_Profile_Details]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- PRC_Candidate_Profile_Details   'test@recruitment'          
CREATE Proc [dbo].[PRC_Candidate_Profile_Details]                          
@UserName   Varchar(100)         
        
As                          
Begin                          
                  
 --Select  A.username,A.mailId,A.CompanyName,          
 --  A.Appliedpost,A.IDCompany,A.IDPost           
 --from  trecruitcandidateresgisterdtls A          
 --Where  UserName =@UserName          
          
         
 --Select A.username,A.mailId,A.CompanyName,          
 --  A.Appliedpost,A.IDCompany,A.IDPost ,B.locid , C.location    
 --from  trecruitcandidateresgisterdtls   A                          
 --Left Join trecruitpostlocationmap  B ON A.IDPost = B.postid  
 --Left Join trecruitpostlocation C ON  B.locid = C.locid  
 --Where  A.username= @UserName              
              
   select M.Appliedpost, M.CompanyName , M.IDCompany,M.IDPost,M.Location as location , M.username,M.mailId , C.locid from          
 (Select distinct A.username,A.mailId,A.CompanyName,            
   A.Appliedpost,A.IDCompany,A.IDPost ,
 LTRIM(RTRIM(PARSENAME(REPLACE(A.Appliedpost, '-', '.'), 1))) AS Location
 from  trecruitcandidateresgisterdtls   A ) as  M                            
 Left Join trecruitpostlocationmap  B ON M.IDPost = B.postid    
 Left Join trecruitpostlocation C ON  M.Location = C.location  
 Where  M.username= @UserName                          
                          
End 
GO



