/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitappliedpost, trecruitcanbasicdtls, tRecruitEduQualification, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[PRC_Get_DeptWiseCandidate_NEW]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- PRC_Get_DeptWiseCandidate_NEW '-SELECT-','-SELECT-'             

CREATE PROCEDURE [dbo].[PRC_Get_DeptWiseCandidate_NEW]             
@Dept VARCHAR(100),      
@collegename VARCHAR(MAX)      
AS              
BEGIN  
    SET NOCOUNT ON; -- Prevents extra result sets for performance improvement

    -- Step 1: Get Candidate Recruitment Details
    WITH CTE_CandidateDetails AS (
        SELECT 
            R.RegistrationID,
            R.RegistrationNumber,
            R.Candidateid,
            R.CandidateName,
            R.aplicationdate,
            R.DeptName,
            R.PostName,
            R.Location
        FROM vw_essp_RecruitCanProfile R
        LEFT JOIN trecruitpostlocationmap PLM ON R.postid = PLM.postid
        LEFT JOIN trecruitappliedpost AP ON PLM.postid = AP.postid
        WHERE AP.postname LIKE '%INTERN%' OR R.PostName LIKE '%INTERN%'
    ),

    -- Step 2: Get Latest Education Qualification Per Candidate
    CTE_CandidateEducation AS (
        SELECT 
            EQ.candidateid,
            CB.gender,
            CB.mobile,
            EQ.degreename,
            EQ.Educationid,
            EQ.yearmonthpassing,
            UPPER(EQ.institute) AS institute,
            ROW_NUMBER() OVER (PARTITION BY EQ.candidateid ORDER BY EQ.Educationid DESC) AS rn
        FROM tRecruitEduQualification EQ
        INNER JOIN trecruitcanbasicdtls CB ON EQ.candidateid = CB.candidateid
        WHERE EQ.institute NOT LIKE '%--------%'
    )

    SELECT DISTINCT 
        CE.Candidateid,
        CD.CandidateName
    FROM CTE_CandidateEducation CE
    INNER JOIN CTE_CandidateDetails CD ON CE.Candidateid = CD.Candidateid
    WHERE CE.rn = 1 -- Ensures latest education qualification is selected
        AND (CD.DeptName = CASE WHEN @Dept = '-SELECT-' THEN CD.DeptName ELSE @Dept END)
        AND (CE.Institute = CASE WHEN @collegename = '-SELECT-' THEN CE.Institute ELSE @collegename END)
    ORDER BY CD.CandidateName ASC;
END
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitcandidatesignup, trecruiteducation, tRecruitEduQualification */
/****** Object:  StoredProcedure [dbo].[PRC_Get_Education_Count]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
CREATE Proc [dbo].[PRC_Get_Education_Count]   
@UserName Varchar(200)  
AS  
Begin  
 Declare @CandidateID bigint  
 select @CandidateID = CandidateID from trecruitcandidatesignup Where username = @UserName  
 Select Count(*) CountEducation From trecruiteducation Where eduname != 'Diploma' AND edulevel <  
 (  
  Select Min(B.edulevel) From tRecruitEduQualification A  
  Inner Join trecruiteducation   B  
  On a.Educationid = B.eduid  
  Where A.candidateid = @CandidateID and Educationid <= (Select Max(Educationid) From tRecruitEduQualification Where candidateid = @CandidateID)  
 )  
End  
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: Hobbies, trecruitboards, trecruitcanbasicdtls, trecruitcandidatesignup, tRecruitEduQualification, tRecruitquaotherdtls */
/****** Object:  StoredProcedure [dbo].[PRC_Receruitment_Resubmit_updatequaotherdtls]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE procedure [dbo].[PRC_Receruitment_Resubmit_updatequaotherdtls]       
@Username varchar(50),           
@Membership varchar(500),          
@Otqualification varchar(500),         
@cmputerProficiency varchar(500),      
@Othertraining varchar(500),         
@ExtraCurricular varchar(500),        
@Hobbies varchar(50),           
@Action VARCHAR(10),          
@status varchar(500) output,         
@euduStatus varchar(500)='0' output      
as        
begin         
declare @canid varchar(10)          
SELECT @canid = [candidateid]                   
FROM   [dbo].[trecruitcandidatesignup]                  
WHERE  [username] = @username                    
  
Update [trecruitcanbasicdtls]   
   set   
   Applicationstatus='SUBMITTED',  
   PersonalDtlsResubmitStatus=NULL   
   ,LanguageDtlsResubmitStatus=NULL  
   ,EducationDtlsResubmitStatus=NULL  
   ,EmploymentHistoryDtlsResubmitStatus=NULL  
   ,AllFormOpenResubmitStatus=NULL  
   WHERE candidateid =@canid  
  
  
If EXISTS( select B.bdname from tRecruitEduQualification AS A    
INNER JOIN [trecruitboards] as B on B.bdid=A.boardid       
where B.bdname<>'Not applicable' and A.candidateid=@canid)    
BEGIN         
SET @euduStatus='1'        
END        
ELSE        
BEGIN         
SET @euduStatus='0'    
END             
IF @Action = 'UPDATE'    
begin         
update [dbo].[tRecruitquaotherdtls]     
set Membership= @Membership ,    
Otqualification= @Otqualification,       
cmputerProficiency=@cmputerProficiency ,       
Othertraining= @Othertraining ,       
ExtraCurricular= @ExtraCurricular ,      
Hobbies =@Hobbies             
where [candidateid]=@canid      
end     
set @status='Data Updated Successfully'       
end
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitcanaddress, trecruitcanappnum, trecruitcanbasicdtls, trecruitcandidatesignup, trecruitotherpost, trecruituploadimage, trecruituploadresume */
/****** Object:  StoredProcedure [dbo].[PRC_Resubmit_canbasicdtlsupdate]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
  
CREATE PROCEDURE [dbo].[PRC_Resubmit_canbasicdtlsupdate] @username      VARCHAR(100)=NULL,               
                                               @Name          VARCHAR(50)=NULL,               
                                               @ContentType   NVARCHAR(200)=NULL,               
                                               @Data          VARBINARY(max)= NULL,               
                                               @iName         VARCHAR(50)=NULL,               
                                               @iContentType  VARCHAR(50)=NULL,               
                                               @iData         IMAGE=NULL,               
                                               @firstname     VARCHAR(100)=NULL,               
                                               @middlename    VARCHAR(100)=NULL,               
                                               @lastname      VARCHAR(100)=NULL,               
                                               @dateofbirth   DATETIME=NULL,               
                                               @gender        VARCHAR(10)=NULL,               
                                               @maritalstatus VARCHAR(10)=NULL,               
                                               @nationality   VARCHAR(10)=NULL,               
                                               @Religion      VARCHAR(max)=NULL,               
                                               @caddresstype  VARCHAR(10)=NULL,               
                                               @caddressline  VARCHAR(max)=NULL,               
                                               @csaddressline VARCHAR(max)=NULL,               
                                               @cvillagecity  VARCHAR(100)=NULL,               
                                               @cpostoffice   VARCHAR(100)=NULL,               
                                               @cpincode      VARCHAR(100)=NULL,            
              --            
              @CurCountry    varchar(100)=NULL,            
                                               --            
              @cstate        INT=NULL,               
                                               @cdistrict     INT=NULL,               
                                               @paddresstype  VARCHAR(10)=NULL,               
                                               @paddressline  VARCHAR(max)=NULL,               
                                               @psaddressline VARCHAR(max)=NULL,               
                                               @pvillagecity  VARCHAR(100)=NULL,               
                                               @ppostoffice   VARCHAR(100)=NULL,               
                                               @ppincode      VARCHAR(100)=NULL,             
              --            
             @PCountry      VARCHAR(100)=NULL,              
                                               --            
              @pstate        INT=NULL,               
                                               @pdistrict     INT=NULL,               
                                               @age           VARCHAR(10)=NULL,               
                                               @countrycode   VARCHAR(10)=NULL,               
                                               @mobile        VARCHAR(50) =NULL,               
                                               @voterid       VARCHAR(50) =NULL,               
                                               @otpostname    VARCHAR(100)=NULL,               
                                               @status        VARCHAR(200) =NULL   output  ,            
              @spousename   VARCHAR(500) =NULL            
AS               
  BEGIN               
      DECLARE @value VARCHAR(200)               
      DECLARE @canid VARCHAR(200)               
              
      SELECT @canid = [candidateid]               
      FROM   [dbo].[trecruitcandidatesignup]               
      WHERE  [username] = @username               
              
  -- Resubmit  
   Update [trecruitcanbasicdtls]   
   set   
   Applicationstatus='SUBMITTED',  
   PersonalDtlsResubmitStatus=NULL   
   ,LanguageDtlsResubmitStatus=NULL  
   ,EducationDtlsResubmitStatus=NULL  
   ,EmploymentHistoryDtlsResubmitStatus=NULL  
   ,AllFormOpenResubmitStatus=NULL  
   WHERE candidateid =@canid  
  --Resubmit  
  
  
  
      IF @iContentType IS NULL               
        BEGIN               
            PRINT 's'               
        END               
      ELSE               
        BEGIN               
            UPDATE trecruituploadimage               
            SET    NAME = @iName,             
                   contenttype = @iContentType,               
                   data = @iData               
            WHERE  candidateid = @canid               
        END               
              
      IF @ContentType IS NULL               
        BEGIN             
            PRINT 's'               
        END             
      ELSE               
        BEGIN               
            UPDATE trecruituploadresume               
            SET    NAME = @Name,               
                   contenttype = @ContentType,               
                   resumefile = @Data               
            WHERE  candidateid = @canid               
        END               
              
      UPDATE [dbo].[trecruitcanbasicdtls]               
      SET    firstname = upper(trim(@firstname)),               
             middlename = upper(trim(@middlename)),               
             lastname = upper(trim(@lastname)),               
             dateofbirth = @dateofbirth,               
             age = @age,               
             gender = @gender,               
             maritalstatus = @maritalstatus,               
             nationality = @nationality,               
             religion = @Religion,               
             countrycode = @countrycode,               
             mobile = @mobile,               
             voterid = @voterid ,            
    SpouseName= @spousename            
      WHERE  candidateid = @canid               
              
      IF @cstate = ''               
          OR @cdistrict = ''               
        BEGIN               
            SELECT @status = 'Not Null'               
              
            RETURN               
        END;               
              
      IF @otpostname <> ''               
        BEGIN               
            DELETE FROM [dbo].[trecruitcanappnum]               
            WHERE  username = @username               
              
            DELETE FROM [dbo].[trecruitotherpost]               
            WHERE  candidateid = @canid               
   Select @otpostname=Replace(@otpostname,'&','and')              
            INSERT INTO [dbo].[trecruitotherpost]               
                        ([candidateid],               
                         [otpostname],               
                         [createdtime])               
            VALUES      ( @canid,               
                          @otpostname,               
                          Getdate() )               
        END               
              
      else              
        BEGIN               
            DELETE FROM [dbo].[trecruitotherpost]               
            WHERE  candidateid = @canid               
        END               
              
      UPDATE [dbo].[trecruitcanaddress]               
      SET    addressline = @caddressline,               
             saddressline = @csaddressline,               
             villagecity = @cvillagecity,               
             postoffice = @cpostoffice,               
             pincode = @cpincode,            
    CountryId=@CurCountry,            
             state = @cstate,               
             district = @cdistrict               
      WHERE  candidateid = @canid               
             AND addresstype = 'c'               
              
      UPDATE [dbo].[trecruitcanaddress]               
      SET    addressline = @paddressline,               
             saddressline = @psaddressline,               
             villagecity = @pvillagecity,               
             postoffice = @ppostoffice,               
             pincode = @ppincode,             
    CountryId=@PCountry,            
             state = @pstate,               
             district = @pdistrict               
      WHERE  candidateid = @canid               
             AND addresstype = 'p'               
              
      SET @status ='Record Updated Successfully'               
  END 
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: Company, trecruitappliedpost, trecruitcanbasicdtls, trecruitcandidateresgisterdtls, trecruitcandidatesignup */
/****** Object:  StoredProcedure [dbo].[PRC_SEND_CANDIDATE_EXAM_LINK]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 CREATE PROCEDURE [dbo].[PRC_SEND_CANDIDATE_EXAM_LINK]        
(        
    @CandidateID INT        
)        
AS        
BEGIN        
    SET NOCOUNT ON;        
        
    DECLARE        
        @MailId NVARCHAR(500),        
        @CandidateName NVARCHAR(200),        
        @CompanyName NVARCHAR(500),        
        @AppliedPost NVARCHAR(500),        
        @ExamTaggingID INT,        
        @ExamLink NVARCHAR(MAX),        
        @MailSubject NVARCHAR(500),        
        @TableHTML NVARCHAR(MAX);        
        
    --------------------------------------------------------        
    -- Candidate Information        
    --------------------------------------------------------        
    SELECT        
        @CandidateName = dbo.Employee_FullName        
        (        
            firstname,        
            middlename,        
            lastname        
        )        
    FROM trecruitcanbasicdtls        
    WHERE candidateid = @CandidateID;        
        
    --------------------------------------------------------        
    -- Registration & Post Information        
    --------------------------------------------------------        
    SELECT TOP (1)        
        @MailId        ='saikat.mondal@iecsl.co.in',   --A.MailId,        
        @CompanyName   = B.CompanyName,        
        @AppliedPost   = B.AppliedPost,        
        @ExamTaggingID = C.ExamTaggingID        
    FROM trecruitcandidatesignup A        
    INNER JOIN trecruitcandidateresgisterdtls B        
        ON B.UserName = A.UserName        
    INNER JOIN trecruitappliedpost C        
        ON C.PostID = B.IDPost        
    WHERE A.CandidateID = @CandidateID;        
        
           
    -- UPDATE EXAM TAGING       
      
    UPDATE B      
     SET B.ExamTaggingID=C.ExamTaggingID      
    FROM trecruitcandidatesignup A        
    INNER JOIN trecruitcandidateresgisterdtls B        
        ON B.UserName = A.UserName        
    INNER JOIN trecruitappliedpost C        
        ON C.PostID = B.IDPost        
    WHERE A.CandidateID = @CandidateID;      
      
      
           
    --------------------------------------------------------        
    -- Validation        
    --------------------------------------------------------        
    IF ISNULL(@ExamTaggingID, 0) = 0        
    BEGIN        
        RAISERROR('No Exam Tagging found for this candidate.',16,1);        
        RETURN;        
    END        
        
    --------------------------------------------------------        
    -- Exam Link        
    --------------------------------------------------------        
   SET @ExamLink =
    'https://lms.iecsl.in/t/mendinepharmaceuticalspvtltd/Login?UserName='
    + @MailId
    + '&UserID=' + CAST(@CandidateID AS VARCHAR(20))
    + '&UserEmail=' + @MailId
    + '&PortalID=2'
    + '&TenantID=B16FABB4-953D-4BFF-9841-C9ECD0A04826'
    + '&tenantUrl=mendinepharmaceuticalspvtltd'
    + '&vSource=ExternalExam'
    + '&IDExam=' + CAST(@ExamTaggingID AS VARCHAR(20));
  
    SET @MailSubject =        
        'Online Assessment Invitation - '        
        + ISNULL(@AppliedPost,'');        
        
    --------------------------------------------------------        
    -- Mail Body        
    --------------------------------------------------------        
    SET @TableHTML =        
    N'        
    <html>        
    <body style="font-family:Calibri;font-size:14px">        
        
    Dear <b>' + ISNULL(@CandidateName,'Candidate') + N'</b>,        
    <br/><br/>        
        
    Greetings from <b>' + ISNULL(@CompanyName,'') + N'</b>.        
    <br/><br/>        
        
    We are pleased to inform you that your application for the position of        
    <b>' + ISNULL(@AppliedPost,'') + N'</b>        
    has been shortlisted for the next stage of the recruitment process.        
        
    <br/><br/>        
        
    <b>Assessment Details</b>        
        
    <table border="1" cellpadding="5" cellspacing="0">        
        <tr>        
            <td><b>Candidate Name</b></td>        
            <td>' + ISNULL(@CandidateName,'') + N'</td>        
        </tr>        
  <tr>        
            <td><b>Company</b></td>        
            <td>' + ISNULL(@CompanyName,'') + N'</td>        
        </tr>        
        <tr>        
            <td><b>Applied Position</b></td>        
            <td>' + ISNULL(@AppliedPost,'') + N'</td>        
        </tr>     
    </table>        
        
    <br/>        
        
    Please click the link below to start your online examination:        
        
    <br/><br/>        
        
    <a href="' + @ExamLink + N'" target="_blank">        
        Start Online Examination        
    </a>        
        
    <br/><br/>        
        
    <br/><br/>        
        
    Kindly complete the assessment within the allotted time.        
        
    <br/><br/>        
        
    Best Regards,<br/>        
    Recruitment Team<br/>        
    ' + ISNULL(@CompanyName,'') + N'        
        
    </body>        
    </html>';        
        
    --------------------------------------------------------        
    -- Return Data for ASP.NET Core        
    --------------------------------------------------------        
    SELECT        
 @MailId      AS MailTo,        
        @MailSubject AS Subject,        
        @TableHTML   AS MailBody;        
        
END 
GO



