/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: none detected */
/****** Object:  StoredProcedure [dbo].[Proc_Getcandidateprofiledata_smple]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Proc_Getcandidateprofiledata_smple]   
@Deptname varchar(max),    
@postname varchar(max),    
@candidatename varchar(max),    
@FromDate varchar(100),    
@ToDate varchar(100),    
@Frselected varchar(100)    
AS    
BEGIN    
    
--set  @postname  = CASE WHEN CHARINDEX('-', @postname) > 0 THEN SUBSTRING(@postname, 1, CHARINDEX('-', @postname) - 1) ELSE @postname END     



     
SELECT 
        candidateid, 
        CandidateName, 
        CASE 
            WHEN deptname = '' THEN 'OTHERS' 
            ELSE deptname  
        END AS deptname,
 
        postname  ,
		aplicationdate,
		Frselect
    FROM vw_essp_RecruitCanProfile     
    WHERE 
        deptname = @Deptname 
		-- Only show data for the specified department
        AND (postname = CASE WHEN @postname = '-SELECT-' THEN postname ELSE @postname END)    
        AND (CandidateName = CASE WHEN @candidatename = '-SELECT-' THEN CandidateName ELSE @candidatename END)   
      --  AND (postname NOT LIKE '%ASSOCIATE%')  
        AND (
            -- Check if @FromDate and @ToDate are empty, if so, ignore date filtering
            (
                @FromDate = '' AND @ToDate = '' 
                OR 
                (
                    convert(date, (convert(varchar, convert(datetime, aplicationdate, 103), 101)), 101)  
                    BETWEEN 
                    convert(date, (convert(varchar, convert(datetime, @FromDate, 103), 101)), 101) 
                    AND 
                    convert(date, (convert(varchar, convert(datetime, @ToDate, 103), 101)), 101)
                )
      
      )
        )      
        AND (ISNULL(Frselect,'') = CASE WHEN @Frselected = '-SELECT-' THEN ISNULL(Frselect,'') ELSE @Frselected END); 
    

END
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitappliedpost, trecruitcanbasicdtls, tRecruitEduQualification, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[Proc_GetInstitutename]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--sp_helptext Proc_GetInstitutename

-- Proc_GetInstitutename 'MANAGEMENT INFORMATION SYSTEM'   
CREATE PROCEDURE [dbo].[Proc_GetInstitutename]    
@dept varchar(100)  
  
AS    
BEGIN     
  
 Declare @Temp_CanInst_Degree Table                          
  (                          
   Candidateid int,                          
   YearMonthPassing Varchar(25),                          
   Institute Varchar(Max)                           
  )   
  
  Declare @Temp_CanDetails Table                          
  (                          
   RegistrationID int,                          
   RegistrationNumber Varchar(100),                          
   Candidateid int,                          
   CandidateName Varchar(Max),                          
   Applicationdate Varchar(11),                          
   DeptName  Varchar(Max),                          
   PostName Varchar(Max) ,                          
   Location Varchar(200)      
       
  )  
  
 Insert Into @Temp_CanInst_Degree  
Select  C.candidateid,D.yearmonthpassing,UPPER(D.institute) as institute From                          
  (                          
  Select candidateid,gender,mobile From trecruitcanbasicdtls                           
  ) C                          
  Inner Join                          
  (                          
   Select A.candidateid,A.Educationid,A.degreename,A.yearmonthpassing,A.institute From(                          
   (                          
    Select candidateid,Educationid,degreename,yearmonthpassing,institute From tRecruitEduQualification                           
   ) A                          
   Inner Join                           
   (                          
   Select candidateid,MAX(Educationid) Educationid From tRecruitEduQualification                          
   Group By candidateid                           
   ) B                          
   On A.candidateid = B.candidateid And A.Educationid = B.Educationid                          
  )) D                          
  On C.candidateid = D.candidateid    
  where D.institute not like '%--------%'  
  order by D.institute asc  
  
  Insert Into @Temp_CanDetails        
  --Select RegistrationID,RegistrationNumber,Candidateid,CandidateName,aplicationdate,DeptName,PostName,Location                           
  --From vw_essp_RecruitCanProfile Where postid in(                          
  -- select postid from trecruitpostlocationmap Where postid IN (Select postid from trecruitappliedpost Where postname like '%INTERN%')                          
  --) OR postname like '%INTERN%'  
  SELECT 
    R.RegistrationID,
    R.RegistrationNumber,
    R.Candidateid,
    R.CandidateName,
    R.aplicationdate,
    R.DeptName,
    R.PostName,
    R.Location
FROM vw_essp_RecruitCanProfile R
LEFT JOIN trecruitpostlocationmap PLM ON R.postid = PLM.postid
LEFT JOIN trecruitappliedpost AP ON PLM.postid = AP.postid
WHERE AP.postname LIKE '%INTERN%'
   OR R.PostName LIKE '%INTERN%'

  
 --select DISTINCT trim(A.Institute) as Institute,A.Candidateid as id from @Temp_CanInst_Degree A  
 --LEFT JOIN @Temp_CanDetails B ON A.Candidateid=B.Candidateid  
 --where  B.DeptName= Case When @Dept= '-SELECT-' Then B.DeptName Else @Dept  End         
       
 ;WITH CTE AS (   
 select DISTINCT trim(A.Institute) as Institute,A.Candidateid as id,ROW_NUMBER() OVER (PARTITION BY  A.Institute  ORDER BY (SELECT 0)) AS rn    
 from @Temp_CanInst_Degree A  
 LEFT JOIN @Temp_CanDetails B ON A.Candidateid=B.Candidateid  
 where  B.DeptName= Case When @Dept= '-SELECT-' Then B.DeptName Else @Dept  End  
 )  
 SELECT id, Institute         
FROM CTE        
WHERE rn = 1      
  
      
  --Select  DISTINCT UPPER(A.institute) as institute, A.id, A.candidateid From tRecruitEduQualification A    
  --INNER JOIN vw_essp_RecruitCanProfile B ON A.candidateid=B.candidateid    
  --where B.postname like '%INTERN%'   
  --and B.CandidateName like '%rimpa das%'  
  --and   B.DeptName= Case When @Dept= '-SELECT-' Then B.DeptName Else @Dept  End               
  
  
 -- order by A.institute asc  
  -- Where B.postid in(                          
  -- select postid from trecruitpostlocationmap Where postid IN (Select postid from trecruitappliedpost Where postname like '%INTERN%')                          
  --)       
    
 END 
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitappliedpost, trecruitcanbasicdtls, tRecruitEduQualification, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[Proc_GetInstitutename_NEW]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

-- Proc_GetInstitutename_NEW 'MANAGEMENT INFORMATION SYSTEM'   

CREATE PROCEDURE [dbo].[Proc_GetInstitutename_NEW]
@dept VARCHAR(100)  
AS    
BEGIN  
    SET NOCOUNT ON; -- Improves performance by preventing extra result sets

    -- Step 1: Get Candidate Education Details
    WITH CTE_CandidateEducation AS (
        SELECT 
    C.candidateid,
    D.yearmonthpassing,
    UPPER(D.institute) AS institute
FROM trecruitcanbasicdtls C
INNER JOIN (
    -- Select the latest EducationID for each candidate
    SELECT 
        EQ.candidateid,
        EQ.yearmonthpassing,
        UPPER(EQ.institute) AS institute
    FROM tRecruitEduQualification EQ
    INNER JOIN (
        SELECT candidateid, MAX(Educationid) AS Educationid
        FROM tRecruitEduQualification
        GROUP BY candidateid
    ) LatestEdu ON EQ.candidateid = LatestEdu.candidateid 
                AND EQ.Educationid = LatestEdu.Educationid
    WHERE EQ.institute NOT LIKE '%--------%'
) D ON C.candidateid = D.candidateid
--ORDER BY D.institute ASC

    )

    -- Step 2: Get Recruitment Details (Using Joins instead of IN)
    , CTE_CandidateDetails AS (
        SELECT 
            R.RegistrationID,
            R.RegistrationNumber,
            R.Candidateid,
            R.CandidateName,
            R.aplicationdate,
            R.DeptName,
            R.PostName,
            R.Location
        FROM vw_essp_RecruitCanProfile R
        LEFT JOIN trecruitpostlocationmap PLM ON R.postid = PLM.postid
        LEFT JOIN trecruitappliedpost AP ON PLM.postid = AP.postid
        WHERE AP.postname LIKE '%INTERN%' OR R.PostName LIKE '%INTERN%'
    )

    -- Step 3: Filtered Institute List
    , CTE_FinalInstitute AS (
        SELECT DISTINCT 
            TRIM(CE.Institute) AS Institute,
            CE.candidateid AS id,
            ROW_NUMBER() OVER (PARTITION BY CE.Institute ORDER BY (SELECT NULL)) AS rn
        FROM CTE_CandidateEducation CE
        LEFT JOIN CTE_CandidateDetails CD ON CE.candidateid = CD.Candidateid
        WHERE (CD.DeptName = CASE WHEN @Dept = '-SELECT-' THEN CD.DeptName ELSE @Dept END)
    )

    -- Step 4: Return Unique Institutes
    SELECT id, Institute FROM CTE_FinalInstitute WHERE rn = 1;  
END
GO



