          LBEXIT: 

          IF @trancount = 0 
            COMMIT; 
      END try 

      BEGIN catch 
          DECLARE @error   INT, 
                  @message VARCHAR(4000), 
                  @xstate  INT; 

          SELECT @error = Error_number(), 
                 @message = Error_message(), 
                 @xstate = Xact_state(); 

          IF @xstate = -1 
            ROLLBACK; 

          IF @xstate = 1 
             AND @trancount = 0 
            ROLLBACK 

          IF @xstate = 1 
             AND @trancount > 0 
            ROLLBACK TRANSACTION proccanbasicdtls; 

          RAISERROR ('proccanbasicdtls: %d: %s',16,1,@error,@message); 
      END catch 
  END 
