/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: tdocumentmaster, trecruitcanbasicdtls, trecruiteducation, tuploadeddocuments */
/****** Object:  StoredProcedure [dbo].[proccandidateuploaddocview]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[proccandidateuploaddocview] @registrationno VARCHAR(max), 
                                              @Action         VARCHAR(max) ,
											  @outcanname varchar(Max) output,
											  @outpendindoc int output
AS 
    DECLARE @candidateid INT 

  BEGIN 
      SELECT @candidateid = candidateid ,@outcanname= firstname+' '+middlename+' '+lastname
      FROM   [dbo].[trecruitcanbasicdtls] 
      WHERE  registrationnumber = @registrationno 
	  Select @outpendindoc=COUNT(docid) from [dbo].[tuploadeddocuments]
	  where candidateid=@candidateid
	  and varifactionstatus='Pending'
	  and deleteflag='No'

      IF @Action = 'EduDoc' 
        BEGIN 
            SELECT [candidateid], 
                   a.[docid], 
                   b.[documentname], 
                   c.eduname, 
                   [uploadedfilename], 
                   [uploadedfiletype], 
                   [uploadedfile],
				   a.varifactionstatus
				  
				    
            FROM   [dbo].[tuploadeddocuments]a, 
                   [dbo].[tdocumentmaster]b, 
                   [dbo].[trecruiteducation]c 
            WHERE  a.candidateid = @candidateid 
                   AND a.deleteflag = 'No' 
                   AND a.docid = b.docid 
                   AND b.edulevel = c.edulevel 
            ORDER  BY a.docid 
        END 

      IF @Action = 'OtherDoc' 
        BEGIN 
            SELECT [candidateid], 
                   a.[docid], 
                   b.[documentname], 
                   [uploadedfilename], 
                   [uploadedfiletype], 
                   [uploadedfile],
				   a.varifactionstatus 
            FROM   [dbo].[tuploadeddocuments]a, 
                   [dbo].[tdocumentmaster]b 
            WHERE  a.candidateid = @candidateid 
                   AND a.deleteflag = 'No' 
                   AND a.docid = b.docid 
                   AND b.documenttype = 'Other' 
            ORDER  BY a.docid 
        END 
  END 
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitboards, trecruitcandidatesignup, trecruiteducation, tRecruitEduQualification */
/****** Object:  StoredProcedure [dbo].[proccanedureport]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE procedure [dbo].[proccanedureport]            
@username varchar(50)        
as        
begin        
DECLARE @canid VARCHAR(200)        
SELECT @canid = [candidateid]         
         FROM   [dbo].[trecruitcandidatesignup]         
          WHERE  [username] = @username         
          
                 insert tRecruitEduQualification(candidateid,Educationid,boardid,degreename,SubjectCombination,yearmonthpassing,institute,UniversityName,marks)     
    select @canid,eduid,196,'Na','Na','Na','Na','Na',0 from  trecruiteducation where eduid not in (7,8) and eduid not in    
    (select Educationid from tRecruitEduQualification where candidateid=@canid)    
    
     
    
SELECT eduname        
      ,bdname        
      ,[degreename]    
   ,ISNULL([SubjectCombination],'Na')SubjectCombination  
  ,startingYear  
      ,[yearmonthpassing]        
      ,[institute]       
       ,ISNULL([UniversityName], 'Na') UniversityName    
      ,[marks]              
  FROM [dbo].[tRecruitEduQualification] qua,[dbo].[trecruitboards] bo,[trecruiteducation] edu        
        
  where candidateid=@canid        
  and edu.eduid=qua.[Educationid]        
 -- and edu.eduid=bo.eduid        
  and qua.[boardid]=bo.bdid        
  order by edulevel desc        
  end
GO



