/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: Company, Hobbies, trecruitcanbasicdtls, trecruitcandidateresgisterdtls, trecruitcandidatesignup, tRecruitcanotherdtls, trecruitcountrycode, trecruitEduBetweenProfessionalExpGap, trecruitotherpost, tRecruitquaotherdtls, trecruituploadimage */
/****** Object:  StoredProcedure [dbo].[proccanreportdtls]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[proccanreportdtls]            
 @username VARCHAR(50)                       
AS                       
  BEGIN                       

      DECLARE @canid VARCHAR(200)       
           
     
   declare @canotid int                      
                      
      SELECT @canid = [candidateid]                       
      FROM   [dbo].[trecruitcandidatesignup]                       
      WHERE  [username] = @username      


                
                      
    select @canotid=candidateid  from trecruitotherpost where candidateid=@canid                      
   if @canotid is null                      
       begin                      
        SELECT [registrationnumber],                      
             mailid,                       
             [position],                       
             data,                       
             CONVERT(VARCHAR(10), [aplicationdate], 103) AS [aplicationdate],                 


      
      bdtls.[firstname] + ' ' + bdtls.[middlename]                       
             + ' ' + bdtls.[lastname] firstname,                       
    bdtls.[firstname] + '' + bdtls.[middlename]                       
             + '' + bdtls.[lastname] fullname,                       
             CONVERT(VARCHAR(10), [dateofbirth], 103)AS [dateofbirth],                       
             [age],                       
             [gender],                       
             [maritalstatus],    


       
             cc.code,                       
             cc.code + '' + [mobile] mobile,                       
             [nationality],                       
             [religion],                       
             [voterid],       
    


         cadd.[ccandidateid],                       
             cadd.[caddresstype],                       
             cadd.[caddressline],                       
             cadd.[csaddressline],                       
    cadd.[cvillagecity],      


                 
             cadd.[cpostoffice],                       
             cadd.[cpincode],            
    cadd.[CurCountryName],            
             cadd.[cstate],                       
             cadd.[cdistrict],                   


    
             cadd.[paddresstype],                       
             cadd.[paddressline],                       
             cadd.[psaddressline],                       
             cadd.[pvillagecity],                
             cadd.[ppostoffice],                       
             cadd.[ppincode],              
             cadd.[PerCountryName],            
             cadd.[pstatename],                       
             cadd.[pdisname],              
             [membership],          


             
             [otqualification],                       
             [cmputerproficiency],                       
             [othertraining],                       
             [extracurricular],                       
             [hobbies],                       
             [considerposition],                       
             [referredus],  
			 ReferredOthertext,  
             [engagedbusiness],                       
             [indicatebusiness],                       
       


			[premenemp],                       
             [menrelative],                       
             [physicaldisability],                       
             [dischargedservice],                       
             [convictedcourt],                 
      
             [timerequire],                       
             [timerequire] requiredtime,                    
             [SpouseName],
			
   ISNULL((select CompanyName from trecruitcandidateresgisterdtls where username=@username),       
   (select Company from Company where Company='MENDINE PHARMACEUTICALS PVT. LTD.')) as CompanyName,      
   ISNULL((SELECT (Address1+','+Address2+' '+Pincode) FROM Company       
   where Company =(select CompanyName from trecruitcandidateresgisterdtls

 where username=@username)),       
   (SELECT (Address1+','+Address2+' '+Pincode) FROM Company where Company='MENDINE PHARMACEUTICALS PVT. LTD.')) as CompanyLocation,       
   ISNULL((SELECT CompanyLogoFilePath FROM Company       
   where Company =(select CompanyName from trecruitcandidateresgisterdtls where username=@username)),      
   (SELECT CompanyLogoFilePath FROM Company where Company='MENDINE PHARMACEUTICALS PVT. LTD.')) as CompanyLogoFilePath,   
   Trim([professionalExperience]) professionalExperience,
	--	--Add number of Gap
	(select TOP 1 (Cast(NumberOfYear as varchar)+' Year '+cast(NumberOfMonth as varchar)+' Month'+cast(NumberOfDay as varchar)+' Day')NumberOfGap
			   from trecruitEduBetweenProfessionalExpGap WHERE candidateid=@canid)NumberOfGap,
	------Add gap reason
	 (select TOP 1 GapReason from trecruitEduBetweenProfessionalExpGap WHERE candidateid=@canid )GapReason

   FROM   [dbo].[trecruitcanbasicdtls] bdtls,                       
             trecruitcountrycode cc,             
          
 
            [dbo].[trecruitcandidatesignup] csign,                       

    
         vw_canapppost apost,                       
             trecruituploadimage img,                       
             vw_canaddress cadd,                       
     


        trecruitquaotherdtls qot,                       
             trecruitcanotherdtls otd 

                  
                  
      WHERE  bdtls.countrycode = cc.codeid                       
             AND bdtls.candidateid = @canid           


  
     
             AND bdtls.candidateid = apost.candidateid                       
             AND bdtls.candidateid = img.candidateid                       
             AND bdtls.candidateid = cadd.ccandidateid                       
             AND bdtls.candidateid = csign.candidateid                       
             AND bdtls.candidateid = qot.candidateid                       
             AND bdtls.candidateid = otd.candidateid 
			
       end
  
                    
else            
     


     
 begin                      
    SELECT [registrationnumber],                       
            mailid,                       
             otpostname position,                       
             data,                       
             CONVERT(VARCHAR(10), [aplicationdate], 103) AS [aplicationdate],                       
             bdtls.[firstname] + ' ' + bdtls.[middlename]                      
             + ' ' + bdtls.[lastname] firstname,                       
			bdtls.[firstname] +



			 '' + bdtls.[middlename]                       
             + '' + bdtls.[lastname] fullname,                       
             CONVERT(VARCHAR(10), [dateofbirth], 103)AS [dateofbirth],                       
             [age],                   
             [gender],                       
			 [maritalstatus],                       
             cc.code,                       
             cc.code + '' + [mobile] mobile,                       
             [nationality],                  
			 [religion],                       
             voterid,                       
             cadd.[ccandidateid],                       
             cadd.[caddresstype],                       
             cadd.[caddressline],            
			 cadd.[csaddressline],                       
             cadd.[cvillagecity],                       
             cadd.[cpostoffice],                       
             cadd.[cpincode],            
			 cadd.[CurCountryName],       
             cadd
.[cstate],                       
             cadd.[cdistrict],                       
             cadd.[paddresstype],                       
             cadd.[paddressline],                       
             cadd.[psaddressline],                   
   
         cadd.[pvillagecity],                       
             cadd.[ppostoffice],          
             cadd.[ppincode],            
    cadd.[PerCountryName],            
             cadd.[pstatename],

                       
             
			cadd.[pdisname],                       
             [membership],                       
             [otqualification],                       
             [cmputerproficiency],    
             [othertraining],     


                  
           



  [extracurricular],                       
             [hobbies],                       
             [considerposition],                       
             [referredus],   
             otd.ReferredOthertext,  
             [engagedbusiness],         

         
   
             [indicatebusiness],                       
             [premenemp],                       
             [menrelative],                       
             [physicaldisability],
			 [dischargedservice],        
             [convictedcourt], 

                      
             [timerequire],                       
             [timerequire]requiredtime,
    ISNULL((select CompanyName from trecruitcandidateresgisterdtls where username=@username), 
      
   (select Company from Company where Company='MENDINE PHARMACEUTICALS PVT. LTD.')) as CompanyName,             
   ISNULL((SELECT (Address1+','+Address2+' '+Pincode) FROM Company       
   where Company =(select CompanyName from trecruitcandidateresgisterdtls where username=@username)),       
   (SELECT (Address1+','+Address2+' '+Pincode) FROM Company where Company='MENDINE PHARMACEUTICALS PVT. LTD.')) as CompanyLocation,       
   ISNULL((SELECT CompanyLogoFilePath
						 FROM Company       
			
			   where Company =(select CompanyName from trecruitcandidateresgisterdtls where username=@username)),(SELECT CompanyLogoFilePath FROM Company where Company='MENDINE PHARMACEUTICALS PVT. LTD.')) as CompanyLogoFilePath,
    Trim([professionalExperience])
 professionalExperience 

	----Add number of Gap
	--(Cast(Eduexpgap.NumberOfYear as varchar)+' Year '+cast(Eduexpgap.NumberOfMonth as varchar)+' Month'+cast(Eduexpgap.NumberOfDay as varchar)+' Day')NumberOfGap,
	
	---Add gap reason
	-- Eduexpgap.GapReason

	--Add number of Gap
	,(select (Cast(NumberOfYear as varchar)+' Year '+cast(NumberOfMonth as varchar)+' Month'+cast(NumberOfDay as varchar)+' Day')NumberOfGap
			   from trecruitEduBetweenProfessionalExpGap WHERE candidateid=@canid)NumberOfGap,
	------Add gap reason
	 (select GapReason from trecruitEduBetweenProfessionalExpGap WHERE candidateid=@canid )GapReason

    FROM   [dbo].[trecruitcanbasicdtls] bdtls,                       
             trecruitcountrycode cc,                       
             [trecruitcandidatesignup] csign,           
            
                                  
            

 trecruituploadimage img,                       
     vw_canaddress cadd,                       
             trecruitquaotherdtls qot,                       
             trecruitcanotherdtls otd ,                      
   trecruitotherpost otp 
   --trecruitEduBetweenProfessionalExpGap  Eduexpgap

      WHERE  bdtls.countrycode = cc.codeid                       
             AND bdtls.candidateid = @canid                      
             and bdtls.candidateid=otp.candidateid
                      
   


             AND bdtls.candidateid = img.candidateid                       
             AND bdtls.candidateid = cadd.ccandidateid                       
             AND bdtls.candidateid = csign.candidateid                       



             AND bdtls.candidateid = qot.candidateid                       
             AND bdtls.candidateid = otd.candidateid  
			 --and bdtls.candidateid = Eduexpgap.candidateid
  END                       
  END
GO



