CREATE procedure [dbo].[proccanresume_CandidateID]      
@candidateID varchar(max)      
as      
      
begin        
  SELECT Name,ContentType,[resumefile],[ResumeFilePath]      
  FROM [dbo].[trecruituploadresume] a,[dbo].[trecruitcanbasicdtls] b      
  where a.candidateid=b.candidateid      
   and a.candidateid in (SELECT CAST(Name AS INT) FROM dbo.splitstring(@candidateID))       
 end 
