GO
CREATE proc [dbo].[procdownloaduploadeddocuments]
@username varchar(max)=null,
@registrationno varchar(Max)=null,
@docid int
as
Declare @canid int
begin
if(@username is not null or @username <> ' ')
begin
Select @canid=Candidateid from trecruitcandidatesignup where username=@username
end
if(@registrationno is not null or @registrationno <> ' ')
begin
SELECT @canid = candidateid 
      FROM   [dbo].[trecruitcanbasicdtls] 
      WHERE  registrationnumber = @registrationno 
end

	Select uploadedfilename,
	       uploadedfiletype,
		   uploadedfile
		   from tuploadeddocuments
		   where candidateid=@canid
		   and docid=@docid
		   and deleteflag='No'
end
