	--or durationto=@durationto and employername=@employername)
	--begin
	--set @status='Data Already Exists'
	--return
	--end
	--else
	--begin
	-- if  @durationform>=@durationto
	--   begin
		INSERT INTO [tEmploymentHistory] ([candidateid]
      ,[employername]
      ,[durationform]
      ,[durationto]
      ,[designation]
      ,[grosssalary]) 
		VALUES (@canid,@employername, @durationform,@durationto,@designation,@yctc)
		--end
		--else
		--begin
		--set @status=''
		--end
		--end
END
-------------UPDATE------------------------
IF @Action = 'UPDATE'
BEGIN

if  CONVERT( VARCHAR(30), @durationform ,105)<=CONVERT( VARCHAR(30),@durationto,105)
