/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: temployeehistory_sales, temployeer_stkrel, trecruitcandidatesignup */
/****** Object:  StoredProcedure [dbo].[procemphistory_sales]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
      
CREATE PROC [dbo].[procemphistory_sales] @Action VARCHAR(10)      
 ,@id INT = NULL      
 ,@employername VARCHAR(Max) = NULL      
 ,@employeeridparam int=null      
 ,@durationform VARCHAR(50) = NULL      
 ,@durationto VARCHAR(50) = NULL      
 ,@designation VARCHAR(MAX) = NULL      
 ,@yctc VARCHAR(50) = NULL      
 ,@drivinglicenseno NVARCHAR(MAX) = NULL    
 ,@username VARCHAR(100) = NULL      
 ,@areacovered NVARCHAR(Max) = NULL      
 ,@reasonforchange VARCHAR(Max) = NULL      
 ,@refname VARCHAR(Max) = NULL      
 ,@refdesignation VARCHAR(Max) = NULL      
 ,@refcontactno VARCHAR(Max) = NULL      
 ,@stkname1 NVARCHAR(max) = NULL      
 ,@stklocation1 NVARCHAR(Max) = NULL      
 ,@stkcontact1 VARCHAR(Max) = NULL      
 ,@stkname2 NVARCHAR(max) = NULL      
 ,@stklocation2 NVARCHAR(Max) = NULL      
 ,@stkcontact2 VARCHAR(Max) = NULL      
 ,@stkname3 NVARCHAR(max) = NULL      
 ,@stklocation3 NVARCHAR(Max) = NULL      
 ,@stkcontact3 VARCHAR(Max) = NULL      
 ,@status VARCHAR(100) = NULL OUTPUT      
AS      
DECLARE @canid VARCHAR(200)      
DECLARE @employeerid INT      
DECLARE @maxemployeerid INT      
      
      
BEGIN      
 SELECT @canid = [candidateid]      
 FROM [dbo].[trecruitcandidatesignup]      
 WHERE [username] = @username      
       
      
 IF @Action = 'Insert'      
 BEGIN      
  SELECT @maxemployeerid = Max([employeerid])      
  FROM [dbo].[temployeehistory_sales]      
  WHERE [candidateid] = @canid      
      
  IF (@maxemployeerid IS NULL)      
  BEGIN      
   SET @employeerid = 1;      
  END      
  ELSE      
  BEGIN      
   SET @employeerid = @maxemployeerid + 1      
  END      
      
  INSERT INTO [dbo].[temployeehistory_sales] (      
   [candidateid]      
   ,[employeerid]      
   ,[employername]      
   ,[designation]      
   ,[durationform]      
   ,[durationto]      
   ,[grosssalary]      
   ,[areacovered]      
   ,[reasonforChange]      
   ,[referencename]      
   ,[referenceContactNo]      
   ,[referencedesignation]    
   ,[drivinglicense]    
   ,[createdtime]      
   ,[modificationtime]      
   )      
  VALUES (      
   @canid      
   ,@employeerid      
   ,@employername      
   ,@designation      
   ,@durationform      
   ,@durationto      
   ,@yctc      
   ,@areacovered      
   ,@reasonforchange      
   ,@refname      
   ,@refcontactno      
   ,@refdesignation    
   ,@drivinglicenseno    
   ,getdate()      
   ,NULL      
   )      
      
  IF (@stkname1 <> '')      
  BEGIN      
   INSERT INTO [dbo].[temployeer_stkrel] (      
    [candidateid]      
    ,[employeerid]      
    ,[stkname]      
    ,[stklocation]      
    ,[stkcontactno]      
    ,[createdtime]      
    ,[updatedtime]      
    )      
   VALUES (      
    @canid      
    ,@employeerid      
    ,@stkname1      
    ,@stklocation1      
    ,@stkcontact1      
    ,getdate()      
    ,NULL      
    )      
  END      
      
  IF (@stkname2 <> '')      
  BEGIN      
   INSERT INTO [dbo].[temployeer_stkrel] (      
    [candidateid]      
    ,[employeerid]      
    ,[stkname]      
    ,[stklocation]      
    ,[stkcontactno]      
    ,[createdtime]      
    ,[updatedtime]      
    )      
   VALUES (      
    @canid      
    ,@employeerid      
    ,@stkname2      
    ,@stklocation2      
    ,@stkcontact2      
    ,getdate()      
    ,NULL      
    )      
  END      
      
  IF (@stkname3 <> '')      
  BEGIN      
   INSERT INTO [dbo].[temployeer_stkrel] (      
    [candidateid]      
    ,[employeerid]      
    ,[stkname]      
    ,[stklocation]      
    ,[stkcontactno]      
    ,[createdtime]      
    ,[updatedtime]      
    )      
   VALUES (      
    @canid      
    ,@employeerid      
    ,@stkname3      
    ,@stklocation3      
    ,@stkcontact3      
    ,getdate()      
    ,NULL      
    )      
  END      
      
  SET @status = 'Data Inserted Successfully'      
 END      
      
 IF @action = 'Select'      
 BEGIN      
  WITH RankedData AS (      
    SELECT *, RN = ROW_NUMBER() OVER(PARTITION BY employeerid ORDER BY id)      
    FROM temployeer_stkrel      
 where candidateid= @canid      
)      
select       
    b.candidateid,      
 b.employeerid,       
    [designation]      
    ,[durationform]      
    ,[durationto]      
    ,[grosssalary]      
    ,[areacovered]      
    ,[reasonforChange]      
    ,[referencename]      
    ,[referenceContactNo]      
    ,[referencedesignation]    
 ,[drivinglicense],    
      [employername],       
    stkname1,      
    stklocation1 ,      
 stkcontactno1 ,      
    stkname2,      
 stklocation2 ,      
 stkcontactno2 ,      
 stkname3 ,      
 stklocation3 ,      
 stkcontactno3      
 from (SELECT employeerid, candidateid,      
    stkname1 = MAX(CASE WHEN RN = 1 THEN stkname ELSE '' END),      
 stklocation1 = MAX(CASE WHEN RN = 1 THEN stklocation ELSE '' END),      
 stkcontactno1 = MAX(CASE WHEN RN = 1 THEN stkcontactno ELSE '' END),      
    stkname2 = MAX(CASE WHEN RN = 2 THEN stkname ELSE '' END),      
 stklocation2 = MAX(CASE WHEN RN = 2 THEN stklocation ELSE '' END),      
 stkcontactno2 = MAX(CASE WHEN RN = 2 THEN stkcontactno ELSE '' END),      
 stkname3 =  MAX(CASE WHEN RN = 3 THEN stkname ELSE '' END),      
 stklocation3 = MAX(CASE WHEN RN = 3 THEN stklocation ELSE '' END),      
 stkcontactno3 = MAX(CASE WHEN RN = 3 THEN stkcontactno ELSE '' END)      
FROM RankedData      
GROUP BY employeerid,candidateid    
) a Inner Join    
[temployeehistory_sales] b      
On a.candidateid=b.candidateid      
and a.employeerid=b.employeerid      
      
 END      
 IF @action='Delete'      
 begin      
 Delete from [dbo].[temployeehistory_sales]      
 where [candidateid]=@canid and [employeerid]=@employeeridparam      
      
 Delete from [dbo].[temployeer_stkrel]      
 where [candidateid]=@canid and [employeerid]=@employeeridparam      
      
 end      
 IF @Action='Update'      
 begin      
      
 Update [dbo].[temployeehistory_sales]       
  set       
         
   [employername]=@employername      
   ,[designation]=@designation      
   ,[durationform]=@durationform      
   ,[durationto]=@durationto      
   ,[grosssalary]=@yctc      
   ,[areacovered]=@areacovered      
   ,[reasonforChange]=@reasonforchange      
   ,[referencename]=@refname      
   ,[referenceContactNo]=@refcontactno      
   ,[referencedesignation]=@refdesignation    
   ,[drivinglicense]=@drivinglicenseno    
         
   ,[modificationtime]=getdate()      
  where [candidateid]=@canid and [employeerid]=@employeeridparam      
 Delete from [dbo].[temployeer_stkrel]      
 where [candidateid]=@canid and [employeerid]=@employeeridparam      
 IF (@stkname1 <> '')      
  BEGIN      
   INSERT INTO [dbo].[temployeer_stkrel] (      
    [candidateid]      
    ,[employeerid]      
    ,[stkname]      
    ,[stklocation]      
    ,[stkcontactno]      
    ,[createdtime]      
    ,[updatedtime]      
    )      
   VALUES (      
    @canid      
    ,@employeeridparam      
    ,@stkname1      
    ,@stklocation1      
    ,@stkcontact1      
    ,getdate()      
    ,NULL      
    )      
  END      
      
  IF (@stkname2 <> '')      
  BEGIN      
   INSERT INTO [dbo].[temployeer_stkrel] (      
    [candidateid]      
    ,[employeerid]      
    ,[stkname]      
    ,[stklocation]      
    ,[stkcontactno]      
    ,[createdtime]      
    ,[updatedtime]      
    )      
   VALUES (      
    @canid      
    ,@employeeridparam      
    ,@stkname2      
    ,@stklocation2      
    ,@stkcontact2      
    ,getdate()      
    ,NULL      
    )      
  END      
      
  IF (@stkname3 <> '')      
  BEGIN      
   INSERT INTO [dbo].[temployeer_stkrel] (      
    [candidateid]      
    ,[employeerid]      
    ,[stkname]      
    ,[stklocation]      
    ,[stkcontactno]      
    ,[createdtime]      
    ,[updatedtime]      
    )      
   VALUES (      
    @canid      
    ,@employeeridparam      
    ,@stkname3      
    ,@stklocation3      
    ,@stkcontact3      
    ,getdate()      
    ,NULL      
    )      
  END      
         
 end      
END
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: tEmploymentHistory, trecruitcandidatesignup */
/****** Object:  StoredProcedure [dbo].[procemphistoryreport]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[procemphistoryreport]
    @username VARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @canid VARCHAR(200);

    SELECT @canid = [candidateid]
    FROM [dbo].[trecruitcandidatesignup]
    WHERE [username] = @username;

    SELECT
        [employername],
        [durationform],
        [durationto],
        [designation],
        [grosssalary],
        [AboveFourLakhSalary]
    FROM [dbo].[tEmploymentHistory]
    WHERE candidateid = @canid
    ORDER BY
        TRY_CONVERT(DATE, [durationto], 105) DESC,
        TRY_CONVERT(DATE, [durationform], 105) DESC;
END
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitcanbasicdtls, trecruitcandidatesignup, tRecruitcanlevel, tRecruitcanotherdtls, trecruitcanrelative, trecruitEduBetweenProfessionalExpGap */
/****** Object:  StoredProcedure [dbo].[procemployotherdtls]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE procedure [dbo].[procemployotherdtls]
@username varchar(50) ,
@considerposition varchar(500),
@referredus varchar(100),
@engagedbusiness varchar(10) =null,
@indicatebusiness varchar(100)=null,
@premenemp varchar(10),
@physicaldisability varchar(10),
@dischargedservice varchar(10),
@convictedcourt varchar(10),
@Timerequire varchar(50),
@flevel varchar(100),
@slevel varchar(100),
@canlevel varchar(100),
@tlevel varchar(100),
@menrelative varchar(10),
@relativename varchar(100)=null,
@relativedesignation varchar(100)=null,
@relation varchar(100)=null,
@isuanavaliable varchar(100)=null,
@uan nvarchar(MAX)=null,
@isesicnoavaliable varchar(10)=null,
@esicno nvarchar(MAX)=null,
@adharno nvarchar(12) = null,
@pancardno nvarchar(10) = null,
@refferedothertext varchar(100) = null,
@professionalExperience nvarchar(max)=null,
@numberOfExperience nvarchar(max)=null,
@numberOfSalesExperience nvarchar(max)=null,

--Gap Professional Experience between edu gap
@gpaNumberOfDay nvarchar(max)=null,
@gapNumberOfMon nvarchar(max)=null,
@gapNumberOfYear nvarchar(max)=null,
@gapReason nvarchar(max)=null,

@emergencyContactRelationship nvarchar(50)=null,
@emergencyContactNo nvarchar(10)=null,

@Status varchar(50)= null output

as
begin

DECLARE @canid VARCHAR(200)

SELECT @canid = [candidateid]
FROM [dbo].[trecruitcandidatesignup]
WHERE [username] = @username

if not exists (select candidateid from tRecruitcanotherdtls where candidateid=@canid )
begin
insert into tRecruitcanotherdtls
( [id],
[candidateid],
[considerposition],
[referredus],
premenemp,
menrelative,
[engagedbusiness],
[indicatebusiness],
[physicaldisability],
[dischargedservice],
[convictedcourt],
[Timerequire],
agree,
[createtime],
[modifiedtime],
[isuanavaliable],
[uan],
[isesicnoavaliable],
[esicno],
[aadhaarno],
[panno],
[ReferredOthertext],
[NumberOfExperience],
[NumberOfSalesExperience],
[EmergencyContactRelationship],
[EmergencyContactNo]
)
values
( next value for seemployotherdtls,
@canid,
@considerposition,
@referredus,
@premenemp,
@menrelative,
@engagedbusiness,
@indicatebusiness,
@physicaldisability,
@dischargedservice,
@convictedcourt,
@Timerequire,
'True',
getdate(),
getdate(),
@isuanavaliable,
@uan,
@isesicnoavaliable,
@esicno ,
@adharno,
@pancardno,
@refferedothertext,
@numberOfExperience,
@numberOfSalesExperience,
@emergencyContactRelationship ,
@emergencyContactNo
)

Insert into tRecruitcanlevel
(
[id],
[candidateid],
[flevel],
[slevel],
[canlevel],
[tlevel],
[createtime],
[modifiedtime]
)values
(
next value for Secanlevel,
@canid,
@flevel,
@slevel,
@canlevel,
@tlevel,
getdate(),
getdate()
)



insert into trecruitcanrelative
([candidateid]
,[Name]
,[designation]
,[relation])
values
(
@canid,
@relativename,
@relativedesignation,
@relation
)

if (@gapReason IS Not NULL or @gapReason='')
BEGIN
insert into trecruitEduBetweenProfessionalExpGap
(candidateid,GapReason,NumberOfYear,NumberOfMonth,NumberOfDay,createdtime)
values(@canid,@gapReason,@gapNumberOfYear,@gapNumberOfMon,@gpaNumberOfDay,getdate())
END
update [dbo].[trecruitcanbasicdtls] set
professionalExperience=@professionalExperience
WHERE candidateid=@canid

set @status='Data Insert Successfully'
end
else
begin
set @status='Duplicate Data'

end
end
GO



