/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: tdocumentmaster, trecruitcandidatesignup, tuploadeddocuments */
/****** Object:  StoredProcedure [dbo].[procgetdocumentsnames]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/****** Script for SelectTopNRows command from SSMS  ******/
CREATE proc [dbo].[procgetdocumentsnames]
@username varchar(Max),
@Action varchar(Max)
as
declare @candidateid int
begin
       SELECT @candidateid = [candidateid] 
          FROM  [dbo].[trecruitcandidatesignup] 
          WHERE  [username] = @username 
if(@Action='Secondary')
begin
	SELECT 
      docid ,documentname
      FROM [dbo].[tdocumentmaster]
      where [edulevel]=1
	  and docid not in(Select docid FROM [dbo].[tuploadeddocuments] where candidateid=@candidateid and deleteflag='No')
      and deleteflag='No'
      and [documenttype]='Educational'
end
if(@Action='HigherSecondary')
begin
	SELECT 
      docid ,documentname
      FROM [dbo].[tdocumentmaster]
      where [edulevel]=3
	  and docid not in(Select docid FROM [dbo].[tuploadeddocuments] where candidateid=@candidateid and deleteflag='No')
      and deleteflag='No'
      and [documenttype]='Educational'
end
if(@Action='Diploma')
begin
	SELECT 
      docid ,documentname
      FROM [dbo].[tdocumentmaster]
      where [edulevel]=2
	  and docid not in(Select docid FROM [dbo].[tuploadeddocuments] where candidateid=@candidateid and deleteflag='No')
      and deleteflag='No'
      and [documenttype]='Educational'
end
if(@Action='Graduation')
begin
	SELECT 
      docid ,documentname
      FROM [dbo].[tdocumentmaster]
      where [edulevel]=4
	  and docid not in(Select docid FROM [dbo].[tuploadeddocuments] where candidateid=@candidateid and deleteflag='No')
      and deleteflag='No'
      and [documenttype]='Educational'
end
if(@Action='PostGraduation')
begin
	SELECT 
      docid ,documentname
      FROM [dbo].[tdocumentmaster]
      where [edulevel]=5
	  and docid not in(Select docid FROM [dbo].[tuploadeddocuments] where candidateid=@candidateid and deleteflag='No')
      and deleteflag='No'
      and [documenttype]='Educational'
end
if(@Action='Phd')
begin
	SELECT 
      docid ,documentname
      FROM [dbo].[tdocumentmaster]
      where [edulevel]=6
	  and docid not in(Select docid FROM [dbo].[tuploadeddocuments] where candidateid=@candidateid and deleteflag='No')
      and deleteflag='No'
      and [documenttype]='Educational'
end
if(@Action='OtherDoc')
begin
	SELECT 
      docid ,documentname
      FROM [dbo].[tdocumentmaster]
      where documenttype='Other'
	  and docid not in(Select docid FROM [dbo].[tuploadeddocuments] where candidateid=@candidateid and deleteflag='No')
      and deleteflag='No'
	  order by documentname
      
end


end
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitcandidatesignup, tRecruitEduQualification */
/****** Object:  StoredProcedure [dbo].[procGetHighestQualificationYear]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[procGetHighestQualificationYear]          
  @username      VARCHAR(100)=null   
AS         
BEGIN                 
 DECLARE @canid VARCHAR(200)          
 SELECT @canid = [candidateid]           
          FROM   [dbo].[trecruitcandidatesignup]           
          WHERE  [username] = @username      
      
    select top 1 yearmonthpassing from tRecruitEduQualification where candidateid=@canid and NOT yearmonthpassing = 'Na'    
     ORDER BY TRY_CONVERT(DATE, '01-' + yearmonthpassing, 105) DESC; 
End
GO



