/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: test, trecruitcanbasicdtls, trecruitcandidateresgisterdtls, trecruitcandidatesignup, trecruitotherpost */
/****** Object:  StoredProcedure [dbo].[Procgetsubmitstatus]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[Procgetsubmitstatus] 
@username VARCHAR(1000)  
 ,@action VARCHAR(100)  
 ,@status VARCHAR(10) = NULL OUTPUT  
AS  
DECLARE @canid INT  
DECLARE @submitstatus VARCHAR(1000)  
DECLARE @canname VARCHAR(2000)  
DECLARE @canpost VARCHAR(Max)  
DECLARE @companyName nvarchar(max)
 DECLARE @applyPost   nvarchar(max)

BEGIN  
 SELECT @canid = [candidateid]  
 FROM [dbo].[trecruitcandidatesignup]  
 WHERE [username] = @username  
  
 SELECT @submitstatus = submitstatus,@canname=[firstname]+' '+[middlename]+' '+[lastname]  
 FROM [dbo].[trecruitcanbasicdtls]  
 WHERE candidateid = @canid  

  select @companyName=CompanyName,@applyPost=Appliedpost 
  from trecruitcandidateresgisterdtls where username=@username
  
 select @canpost=a.position from   
(select candidateid,position from vw_canapppost apost  
union all  
select candidateid,otpostname position from trecruitotherpost) a  
where candidateid=@canid  
  
 IF @action = 'Select'  
 BEGIN  
  IF @submitstatus = 'No'  
  BEGIN  
   SELECT submitstatus  
   FROM [dbo].[trecruitcanbasicdtls]  
   WHERE candidateid = @canid  
  END  
  ELSE  
  BEGIN  
   SELECT submitstatus  
   FROM [dbo].[trecruitcanbasicdtls]  
   WHERE candidateid = @canid  
  END  
 END  
  
 IF @action = 'Changestatus'  
 BEGIN  
  UPDATE [dbo].[trecruitcanbasicdtls]  
  SET submitstatus = 'Yes' ,
  CanNotifyStatus ='On application submission'
  
  WHERE candidateid = @canid  
  
  declare @MailId varchar(200)  
 DECLARE @tableHTML NVARCHAR(MAX);  

 SET @tableHTML = '<table style="font-size:20px; font-family:Tahoma">                  
    <tr>                  
        <td>Dear ' + @canname + ',</td>                  
    </tr>
	 <tr>                  
        <td style="height: 20px;"></td>  
    </tr>  
    <tr>                  
        <td>
            Thank you for applying for the ' + @applyPost + ' position at ' + @companyName + '. 
            We have received your application and appreciate your interest in joining our team.
            Our recruitment team will review your profile and qualifications. If your application is shortlisted, 
            we will reach out to you to discuss the next steps in the selection process. 
            We appreciate your patience and understanding. 
            Thank you once again for considering Mendine as your potential employer.
        </td>                  
    </tr>                  
    <tr>                  
        <td>If you have already given both the tests, then please ignore this mail.</td>                  
    </tr>                  
    <tr>                  
        <td style="height: 40px;"></td>  
    </tr>                  
    <tr>                  
        <td>Thanks & Regards,<br/><i>Mendine HR Team</i></td>                  
    </tr>                  
    <tr>                  
        <td><p><a href="http://recruitment.mendine.co.in">Click Here for Recruitment Portal</a></p></td>                 
    </tr>                  
</table>';
  
-- SET @tableHTML = '<table style=" font-size:20px; font-family:Tahoma ">  
  
--        <tr>  
  
--               <td>Dear '+ @canname +'</td>  
--        </tr>  
  
--        <tr>  
  
--               <td>  This mail is to congratulate you about your successful completion of the Application Process for the post ('+ @canpost +') in Mendine Pharmaceuticals Pvt. Ltd.</td>  
--  <br/>  
                
  
  
--        </tr>  
-- <tr>  
--  <td>You have succesfully filled up the Registration form and given both the Psychometric test. Our Recruitment team will shortly get in touch with you.  
--</td>  
  
-- </tr>  
  
--        <tr>  
--    <br/><br/>  
--               <td>Thanks & Regards <br/><i>Mendine HR Team</i></td>  
  
--        </tr>  
--<br/>   
--<td><p><a href="http://recruitment.mendine.co.in">Click Here for Recruitment Portal</a></p></td>  
--</tr>  
  
--</table>';  
  
   SELECT @MailId=[MailId]        
  FROM [dbo].[trecruitcandidatesignup]  
  where candidateid=@canid  
  
 EXEC msdb.dbo.sp_send_dbmail  
    @profile_name = 'Mendine_Recruitment_Profile'  
   ,@recipients = @MailId  
   ,@subject = 'Application Submitted Successfully'  
   ,@body = @tableHTML  
   ,@importance ='HIGH'  
   ,@body_format = 'HTML'  
  
 END  
END
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: tdocumentmaster, trecruitcandidatesignup, tuploadeddocuments */
/****** Object:  StoredProcedure [dbo].[procgetuploadeddocuments]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[procgetuploadeddocuments]
@username varchar(Max)=null,
@Action varchar(Max)
as
declare @candidateid int
begin

 SELECT @candidateid = [candidateid] 
          FROM  [dbo].[trecruitcandidatesignup] 
          WHERE  [username] = @username 
 if(@Action ='SecondaryDocSelect')
 begin
     Select 
     [candidateid],
     a.[docid],
     b.documentname,
     [uploadedfilename],
	 a.varifactionstatus
     from [dbo].[tuploadeddocuments]a,[dbo].[tdocumentmaster]b
     where a.deleteflag='No'
     and [candidateid]=@candidateid
     and a.[docid] in(Select [docid] from  [dbo].[tdocumentmaster] where [edulevel]=1 and deleteflag='No')
     and a.[docid]=b.[docid]
     and b.deleteflag='No'
 end
 if(@Action ='HSecondaryDocSelect')
 begin
     Select 
     [candidateid],
     a.[docid],
     b.documentname,
     [uploadedfilename],
	 a.varifactionstatus
     from [dbo].[tuploadeddocuments]a,[dbo].[tdocumentmaster]b
     where a.deleteflag='No'
     and [candidateid]=@candidateid
     and a.[docid] in(Select [docid] from  [dbo].[tdocumentmaster] where [edulevel]=3 and deleteflag='No')
     and a.[docid]=b.[docid]
     and b.deleteflag='No'
 end
 if(@Action ='DiplomaDocSelect')
 begin
     Select 
     [candidateid],
     a.[docid],
     b.documentname,
     [uploadedfilename],
	 a.varifactionstatus
     from [dbo].[tuploadeddocuments]a,[dbo].[tdocumentmaster]b
     where a.deleteflag='No'
     and [candidateid]=@candidateid
     and a.[docid] in(Select [docid] from  [dbo].[tdocumentmaster] where [edulevel]=2 and deleteflag='No')
     and a.[docid]=b.[docid]
     and b.deleteflag='No'
 end
 if(@Action ='GraduationDocSelect')
 begin
     Select 
     [candidateid],
     a.[docid],
     b.documentname,
     [uploadedfilename],
	 a.varifactionstatus

     from [dbo].[tuploadeddocuments]a,[dbo].[tdocumentmaster]b
     where a.deleteflag='No'
     and [candidateid]=@candidateid
     and a.[docid] in(Select [docid] from  [dbo].[tdocumentmaster] where [edulevel]=4 and deleteflag='No')
     and a.[docid]=b.[docid]
     and b.deleteflag='No'
 end
 if(@Action ='PostGraduationDocSelect')
 begin
     Select 
     [candidateid],
     a.[docid],
     b.documentname,
     [uploadedfilename],
	 a.varifactionstatus
     from [dbo].[tuploadeddocuments]a,[dbo].[tdocumentmaster]b
     where a.deleteflag='No'
     and [candidateid]=@candidateid
     and a.[docid] in(Select [docid] from  [dbo].[tdocumentmaster] where [edulevel]=5 and deleteflag='No')
     and a.[docid]=b.[docid]
     and b.deleteflag='No'
 end
 if(@Action ='OtherDocSelect')
 begin
     Select 
     [candidateid],
     a.[docid],
     b.documentname,
     [uploadedfilename],
	 a.varifactionstatus
     from [dbo].[tuploadeddocuments]a,[dbo].[tdocumentmaster]b
     where a.deleteflag='No'
     and [candidateid]=@candidateid
     and a.[docid] in(Select [docid] from  [dbo].[tdocumentmaster] where documenttype='Other' and deleteflag='No')
     and a.[docid]=b.[docid]
     and b.deleteflag='No'
 end
 

end
GO



