/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitcandidatesignup, tRecruitCanrefer */
/****** Object:  StoredProcedure [dbo].[procinsCanreferel]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[procinsCanreferel]
	 @Action VARCHAR(10)
	,@id INT = NULL
	,@name VARCHAR(100) = NULL
	,@Address VARCHAR(MAX) = NULL
	,@mobileno VARCHAR(100) = NULL
	,@username      VARCHAR(100)=null
	 ,@refrelation varchar(100)=null
	,@status varchar(100)=null output
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @canid VARCHAR(200)
	DECLARE @mcount VARCHAR(200)

	SELECT @canid = [candidateid] 
          FROM   [dbo].[trecruitcandidatesignup] 
          WHERE  [username] = @username 

	--SELECT
    IF @Action = 'SELECT'
	BEGIN
		SELECT [id]      
      ,[name]
	  ,relation
      ,[Address]
      ,[mobileno]
     
  FROM [Recruitment].[dbo].[tRecruitCanrefer] where candidateid=@canid
	END

	--INSERT
    IF @Action = 'INSERT'
	BEGIN
	
	select @mcount=count(mobileno) from tRecruitCanrefer where mobileno=@mobileno and candidateid=@canid
	if @mcount=0
	begin
		INSERT INTO tRecruitCanrefer (candidateid,[name],relation
      ,[Address]
      ,[mobileno]) 
		VALUES (@canid,@Name, @refrelation,@Address,@mobileno)
		end

    else
	begin 
	set @status='duplicate'
	select @status 
	end
	END

	--UPDATE

    IF @Action = 'UPDATE'
	BEGIN	

	if exists ( select mobileno from tRecruitCanrefer where candidateid=@canid and mobileno=@mobileno)
	begin
	UPDATE tRecruitCanrefer 
		SET 
		[name]=@name
		 ,relation=@refrelation 
      ,[Address]=@Address
      
		WHERE  id = @id and candidateid=@canid
	
	end
	else
	begin
		UPDATE tRecruitCanrefer 
		SET 
		[name]=@name
		 ,relation=@refrelation 
      ,[Address]=@Address
      ,[mobileno]=@mobileno
		WHERE id = @id and candidateid=@canid
	end
	END

	--DELETE
    IF @Action = 'DELETE'
	BEGIN
		DELETE FROM tRecruitCanrefer 
		WHERE id = @id and candidateid=@canid
	END
END
GO



