/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitcanbasicdtls, trecruitcandidatesignup, trecruitcanfamilydtls */
/****** Object:  StoredProcedure [dbo].[procinsfamilyCheckMarriedOrNot]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
CREATE PROCEDURE [dbo].[procinsfamilyCheckMarriedOrNot]         
 @username      VARCHAR(100)=null      
 ,@status varchar(100)=null output      
AS      
BEGIN      
 DECLARE @canid VARCHAR(200)      
 DECLARE @maritalstatus VARCHAR(200)    
    
 --Get Canid    
 SELECT @canid = [candidateid]       
          FROM   [dbo].[trecruitcandidatesignup]       
          WHERE  [username] = @username     
--Get maritalstatus    
select @maritalstatus=maritalstatus     
 from trecruitcanbasicdtls     
 where candidateid=@canid    
    
   if  @maritalstatus='Married'      
   begin      
           --Husband/Wife    
            if not exists (SELECT * FROM trecruitcanfamilydtls WHERE candidateid=@canid AND relationship='Husband/Wife')     
       BEGIN    
      set @status='0'    
       END    
           ELSE  
            BEGIN  
        set @status='1'  
      END  
  
  
   END      
END
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: Customers */
/****** Object:  StoredProcedure [dbo].[procinsfamilylan]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create PROCEDURE [dbo].[procinsfamilylan]
	@Action VARCHAR(10)
	,@CustomerId INT = NULL
	,@Name VARCHAR(100) = NULL
	,@Country VARCHAR(100) = NULL
AS
BEGIN
	SET NOCOUNT ON;

	--SELECT
    IF @Action = 'SELECT'
	BEGIN
		SELECT CustomerId, Name, Country 
		FROM Customers
	END

	--INSERT
    IF @Action = 'INSERT'
	BEGIN
		INSERT INTO Customers (Name, Country) 
		VALUES (@Name, @Country)
	END

	--UPDATE
    IF @Action = 'UPDATE'
	BEGIN
		UPDATE Customers 
		SET Name = @Name, Country = @Country 
		WHERE CustomerId = @CustomerId
	END

	--DELETE
    IF @Action = 'DELETE'
	BEGIN
		DELETE FROM Customers 
		WHERE CustomerId = @CustomerId
	END
END
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitcandidatesignup, trecruitcanfamilydtls */
/****** Object:  StoredProcedure [dbo].[procinsfamilylanguage]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[procinsfamilylanguage]
	 @Action VARCHAR(10)
	,@memberid INT = NULL
	,@rmemberid INT = NULL
	,@Name VARCHAR(100) = NULL
	,@relationship VARCHAR(100) = NULL
	,@occupation VARCHAR(100) = NULL,
	@username      VARCHAR(100)=null
	,@status varchar(100)=null output
AS
BEGIN
	SET NOCOUNT ON;
	DECLARE @canid VARCHAR(200)
	declare @relac int

	SELECT @canid = [candidateid] 
          FROM   [dbo].[trecruitcandidatesignup] 
          WHERE  [username] = @username 

	--SELECT
    IF @Action = 'SELECT'
	BEGIN
		SELECT memberid,membername, relationship, occupation 
		FROM [trecruitcanfamilydtls] where candidateid=@canid
	END

	--INSERT
    IF @Action = 'INSERT'
	BEGIN
	if @Name=''or @relationship=''or @occupation=''
	begin
	set @status='Please give a valid input'
	return
	end

	
	if not exists (select relationship from trecruitcanfamilydtls where relationship= @relationship and candidateid=@canid)
	begin
		INSERT INTO trecruitcanfamilydtls (candidateid,membername, relationship,occupation) 
		VALUES (@canid,@Name, @relationship,@occupation)
		set @status='Data inserted successfully'
		end

    else
	begin 
	set @status='Same Relationship is already present'
	end
	END

	--UPDATE

    IF @Action = 'UPDATE'
	

	BEGIN	
	if @relationship='' or @Name='' or @occupation=''
	begin
	set @status='Please entry valid input'
	return
	end

	select @relac=count(relationship) from trecruitcanfamilydtls where relationship= @relationship and candidateid=@canid


	

	if  exists (select relationship from trecruitcanfamilydtls where relationship= @relationship and candidateid=@canid)
	begin
		
		UPDATE trecruitcanfamilydtls 
		SET membername = @Name, occupation=@occupation
		WHERE memberid = @memberid and candidateid=@canid
		set @status='Data updated successfully'
	end

	if  not exists (select relationship from trecruitcanfamilydtls where relationship= @relationship and candidateid=@canid)
	begin
		
		UPDATE trecruitcanfamilydtls 
		SET membername = @Name,relationship= @relationship, occupation=@occupation
		WHERE memberid = @memberid and candidateid=@canid
		set @status='Data updated successfully'
	end
		
END

	--DELETE
    IF @Action = 'DELETE'
	BEGIN
		DELETE FROM trecruitcanfamilydtls 
		WHERE memberid = @memberid and candidateid=@canid
		set @status='Data deleted successfully'
	END
END
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitcandidatesignup, trecruitcanlanguage */
/****** Object:  StoredProcedure [dbo].[procinslanguage]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[procinslanguage]
	@Action VARCHAR(10)
	,@languageid int=null
	,@language VARCHAR(10) = NULL
	,@read VARCHAR(10) = NULL
	,@write VARCHAR(10) = NULL
	,@speak VARCHAR(10) = NULL,
	@username      VARCHAR(100)=null
	,@status varchar(100) output
AS
BEGIN
	SET NOCOUNT ON;

	DECLARE @canid VARCHAR(200)

	SELECT @canid = [candidateid] 
          FROM   [dbo].[trecruitcandidatesignup] 
          WHERE  [username] = @username

	--SELECT
    IF @Action = 'SELECT'
	BEGIN
		SELECT [languageid],[languagename], [lread], [lwrite],[lspeak] 
		FROM [trecruitcanlanguage] where candidateid=@canid
	END

	--INSERT
    IF @Action = 'INSERT'
	BEGIN
	if @read='No'and @write='No' and @speak='No'
	begin
	set @status='Atlist one parameter should be Yes'
	return
	end

	if not exists (select [languagename] from [trecruitcanlanguage] where [languagename]= @language and candidateid=@canid)
	begin
		INSERT INTO [trecruitcanlanguage] (candidateid,[languagename], [lread],[lwrite],[lspeak]) 
		VALUES (@canid,@language, @read,@write,@speak)
		set @status='Data inserted successfully'
		end

    else
	begin 
	set @status='Language already present'
	
	end
	END

	--UPDATE

    IF @Action = 'UPDATE'
	BEGIN
	if @language='' or @read='' or @write='' or @speak=''
	begin
	set @status='Atlist one parameter should be Yes'
	return
	end
	if @read='No'and @write='No' and @speak='No'
	begin
	set @status='Atlist one parameter should be Yes'
	return
	end
	if  exists (select [languagename] from [trecruitcanlanguage] where [languagename]= @language and candidateid=@canid)
	begin
		UPDATE [trecruitcanlanguage] 
		SET  [lread] = @read,[lwrite]=@write,[lspeak]=@speak
		WHERE [languageid] = @languageid and candidateid=@canid
		set @status='Data Updated Successfully'
		end
		else
	begin 
	UPDATE [trecruitcanlanguage] 
		SET  [languagename]= @language,[lread] = @read,[lwrite]=@write,[lspeak]=@speak
		WHERE [languageid] = @languageid and candidateid=@canid
	end
	END

	--DELETE
    IF @Action = 'DELETE'
	BEGIN
		DELETE FROM [trecruitcanlanguage] 
		WHERE [languageid] = @languageid and candidateid=@canid
		set @status='Data deleted successfully'
	END
END
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitboards, trecruitcandidatesignup, trecruitcanfamilydtls, trecruiteducation, tRecruitEduQualification */
/****** Object:  StoredProcedure [dbo].[procinsQualificationdtls]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
     CREATE PROCEDURE [dbo].[procinsQualificationdtls]    
  @Action VARCHAR(10),    
  @id INT = NULL,    
  @Educationid int=null,    
  @boardid int=null,    
  @degreename VARCHAR(100) = NULL,    
  @yearmonthpassing VARCHAR(100) = NULL,    
  @institute VARCHAR(100) = NULL,    
  @marks VARCHAR(100)=null,    
  @username      VARCHAR(100)=null,    
  @status varchar(100)=null output    
AS    
BEGIN    
 SET NOCOUNT ON;    
 DECLARE @canid VARCHAR(200)    
    
 SELECT @canid = [candidateid]     
          FROM   [dbo].[trecruitcandidatesignup]     
          WHERE  [username] = @username     
    
 --SELECT    
    IF @Action = 'SELECT'    
 BEGIN     
    
  SELECT        a.id, c.eduname, d.bdname, a.degreename, a.yearmonthpassing, a.institute, a.marks, c.eduid, d.bdid    
FROM            tRecruitEduQualification AS a INNER JOIN    
                         trecruiteducation AS c ON a.Educationid = c.eduid INNER JOIN    
                         trecruitboards AS d ON c.eduid = d.eduid AND a.boardid = d.bdid    
WHERE        (a.candidateid = @canid) order by c.eduname desc
 END    
    
 --INSERT    
    IF @Action = 'INSERT'    
 BEGIN    
    
    
    
  if not exists (select Educationid,yearmonthpassing from tRecruitEduQualification     
 where Educationid= @Educationid and yearmonthpassing=@yearmonthpassing and candidateid=@canid)    
    
 begin    
  INSERT INTO tRecruitEduQualification     
  (candidateid,    
   Educationid,    
     boardid,     
  degreename,     
  yearmonthpassing,    
     institute,    
     marks)     
  VALUES     
  (@canid,    
   @Educationid,    
      @boardid,    
      @degreename,     
      @yearmonthpassing,    
      @institute,    
   @marks)    
  end    
    
   else    
 begin     
 set @status='duplicate'    
 select @status     
 end    
 END    
    
 --UPDATE    
    
    IF @Action = 'UPDATE'    
 BEGIN     
 --if @relationship='' or @Name='' or @occupation=''    
 --begin    
 --set @status='not null'    
 --return    
 --end    
    
    --if  exists (select relationship from trecruitcanfamilydtls where relationship= @relationship and candidateid=@canid)    
 --begin    
  UPDATE tRecruitEduQualification     
  SET Educationid=@Educationid,    
    boardid=@boardid,[degreename] = @degreename, [yearmonthpassing]=@yearmonthpassing,    
    [institute]=@institute,[marks]=@marks    
  WHERE id = @id and candidateid=@canid    
  --end    
 -- else    
 --begin     
 --UPDATE trecruitcanfamilydtls     
 -- SET relationship=@relationship,membername = @Name, occupation=@occupation    
 -- WHERE memberid = @memberid and candidateid=@canid    
 --end    
 END    
    
 --DELETE    
    IF @Action = 'DELETE'    
 BEGIN    
  DELETE FROM tRecruitEduQualification     
  WHERE id = @id and candidateid=@canid    
 END    
END
GO



