CREATE PROCEDURE [dbo].[procProfessionalExpGapYearGap]          
  @Action VARCHAR(100),          
  @id INT = NULL,          
  @username      VARCHAR(100)=null,  
  @employerName  nvarchar(max)=null,  
  @gapReason nvarchar(max)=null,  
  @numberOfYear nvarchar(max)=null,  
  @numberOfMonth nvarchar(max)=null,  
  @numberOfDay nvarchar(max)=null,  
  @status varchar(100)=null output   
AS         
BEGIN   
   DECLARE @canid VARCHAR(200)                  
  SELECT @canid = [candidateid]           
     FROM   [dbo].[trecruitcandidatesignup]           
     WHERE  [username] = @username     

IF @Action='Delete_by_Company'  
 BEGIN  
     DELETE FROM [trecruitProfessionalExpGap]           
     WHERE    candidateid= @canid and EmployerName=@employerName	 
 END  

  IF @Action = 'SELECT'          
 BEGIN     
    --(Cast(A.NumberOfYear as varchar)+' Year '+cast(A.NumberOfMonth as varchar)+' Month')NumberOfGap  
    --,A.NumberOfYear,A.NumberOfMonth,A.NumberOfDay  
   select A.Id,A.EmployerName,A.GapReason,A.NumberOfYear,A.NumberOfMonth,A.NumberOfDay,(Cast(A.NumberOfYear as varchar)+' Year '+cast(A.NumberOfMonth as varchar)+' Month '+cast(A.NumberOfDay as varchar)+' Day')NumberOfGap from  trecruitProfessionalExpGap 
A  
 Where A.candidateid=@canid   
 End  
 IF @Action = 'UPDATE'          
 BEGIN          
   UPDATE [trecruitProfessionalExpGap]   
       SET  
        GapReason=@gapReason  
      Where candidateid=@canid and  Id=@id  
    
end  
  
 IF @Action = 'DELETE'          
 BEGIN      
  DELETE FROM [trecruitProfessionalExpGap]           
  WHERE id = @id and candidateid=@canid          
 END  
  

end  

GO



