/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitcandidatesignup, trecruiteducation, trecruitEduGap */
/****** Object:  StoredProcedure [dbo].[procQualificationYearGap]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 CREATE PROCEDURE [dbo].[procQualificationYearGap]        
  @Action VARCHAR(10),        
  @id INT = NULL, 
  @education nvarchar(max)=null,
  @username      VARCHAR(100)=null,
  @TRecruitEduGap   RecruitEduGapTableType READONLY,
  @status varchar(100)=null output 
AS       
BEGIN
 
   DECLARE @canid VARCHAR(200)                
	 SELECT @canid = [candidateid]         
			  FROM   [dbo].[trecruitcandidatesignup]         
			  WHERE  [username] = @username   
  IF @Action = 'SELECT'        
 BEGIN    
	Select A.Id,A.Educationid,B.eduname,(Cast(A.NumberOfYear as varchar)+' Year '+cast(A.NumberOfMonth as varchar)+' Month')NumberOfGap,A.GapReason,
	A.NumberOfYear,A.NumberOfMonth
	from [trecruitEduGap]A
	INNER JOIN trecruiteducation AS B ON B.eduid=A.Educationid
	Where A.candidateid=@canid
 End
 IF @Action = 'UPDATE'        
 BEGIN 							
			UPDATE [trecruitEduGap] 
			    SET
				    GapReason=T.GapReason
				 FROM @TRecruitEduGap T 
				  Where [trecruitEduGap].candidateid=@canid and  [trecruitEduGap].Id=@id
		
end
 IF @Action = 'DELETE'        
 BEGIN    
  DELETE FROM [trecruitEduGap]         
  WHERE id = @id and candidateid=@canid        
 END

 IF @Action = 'DELETE_ByEduId'        
 BEGIN    
  DELETE FROM [trecruitEduGap]         
  WHERE Educationid=@education and candidateid=@canid        
 END
 IF @Action = 'DELETE_ALL'        
 BEGIN    
  DELETE FROM [trecruitEduGap]                 
 END

end
GO



