      @cmputerProficiency varchar(500),  
      @Othertraining varchar(500),  
      @ExtraCurricular varchar(500),  
      @Hobbies varchar(500),  
   @status varchar(500)=null output  
   as  
begin  
     
   DECLARE @canid VARCHAR(200)  
  
   SELECT @canid = [candidateid]   
          FROM   [dbo].[trecruitcandidatesignup]   
          WHERE  [username] = @username   
  
if exists ( select candidateid from tRecruitquaotherdtls where candidateid=@canid)  
   begin  
 --   set @status='Data inseted Successfully' 
   set @status='Already Exists'  
   return  
   end  
   else  
   begin  
   Insert into tRecruitquaotherdtls     
   (   [id]  
      ,[candidateid]  
      ,[Membership]  
      ,[Otqualification]  
      ,[cmputerProficiency]  
      ,[Othertraining]  
      ,[ExtraCurricular]  
      ,[Hobbies]  
      ,[createdtime]  
      ,[modifiedtime]) values  
  
   (next value for sequaotherdtls,  
    @canid ,  
