       @Otqualification,  
       @cmputerProficiency,  
       @Othertraining,  
       @ExtraCurricular,  
       @Hobbies,  
    getdate(),  
    getdate())  
  
   set @status='Data inserted Successfully'   
   end  
     
end  
  
  
GO



