CREATE proc [dbo].[procrecruitmenttestdocuments]  
@action varchar(100),  
@docid int=null,  
@docfilename varchar(max)=null,  
@docfiletype nvarchar(max)=null,  
@docfiledata varbinary(max)=null,  
@candidateid int 
as  
begin  
	if (@action = 'CREATEDDOCUMENT')  
		begin  
		if exists(Select candidateid from  [dbo].[trecuitOfficialDocument] where candidateid=@candidateid and [docid]=@docid)  
		begin  
		  update [dbo].[trecuitOfficialDocument]  
		  set [Name]=@docfilename,  
			  [ContentType]=@docfiletype,  
		   [FileData]=@docfiledata,  
		   [createdtime]=getdate()  
		  where candidateid=@candidateid and [docid]=@docid   
		end  
		else  
		begin  
		  insert into [dbo].[trecuitOfficialDocument]  
		  (  
			   [candidateid]  
			  ,[docid]  
			  ,[Name]  
			  ,[ContentType]  
			  ,[FileData]  
			  ,[username]  
			  ,[createdtime]  
			  ,[modifiedtime]  
			  ,[varifactionstatus]  
		  )  
		  values  
		  (  
			@candidateid,  
		 @docid,  
		 @docfilename,  
		 @docfiletype,  
		 @docfiledata,  
		 'Admin',  
		 getdate(),  
		 getdate(),  
		 'UPLOADED'  
		  )  
		end  
	end    
end
GO



