/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitcanbasicdtls, trecruitcandidatesignup, tuploadeddocuments */
/****** Object:  StoredProcedure [dbo].[procuploaddocuments]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[procuploaddocuments] @username       VARCHAR(max),
                                       @uploadfilename NVARCHAR(max)=null,
                                       @uploadfiletype NVARCHAR(max)=null,
                                       @uploadfile     VARBINARY(max)=null,
                                       @docid          INT=null,
									   @action         VARCHAR(100)
AS
    DECLARE @candidateid INT

  BEGIN
      SELECT @candidateid = [candidateid]
      FROM   [dbo].[trecruitcandidatesignup]
      WHERE  [username] = @username

	IF(@action='UPLOAD')
	BEGIN
	IF EXISTS (SELECT 1
                 FROM   [dbo].[tuploadeddocuments]
                 WHERE  candidateid = @candidateid
                        AND docid = @docid
                        AND deleteflag = 'Yes')
        BEGIN
            DELETE FROM [dbo].[tuploadeddocuments]
            WHERE  candidateid = @candidateid
                   AND docid = @docid
                   AND deleteflag = 'Yes'

            INSERT INTO [dbo].[tuploadeddocuments]
                        ([candidateid],
                         [docid],
                         [uploadedfilename],
                         [uploadedfiletype],
                         [uploadedfile],
                         [deleteflag],
                         [uploadedby],
                         [uploadedon],
						 [varifactionstatus])
            VALUES      ( @candidateid,
                          @docid,
                          @uploadfilename,
                          @uploadfiletype,
                          @uploadfile,
                          'No',
                          @candidateid,
                          Getdate(),
						  'Pending' )
        END
      ELSE
        BEGIN
            INSERT INTO [dbo].[tuploadeddocuments]
                        ([candidateid],
                         [docid],
                         [uploadedfilename],
                         [uploadedfiletype],
                         [uploadedfile],
                         [deleteflag],
                         [uploadedby],
                         [uploadedon],
						 [varifactionstatus])
            VALUES      ( @candidateid,
                          @docid,
                          @uploadfilename,
                          @uploadfiletype,
                          @uploadfile,
                          'No',
                          @candidateid,
                          Getdate(),
						  'Pending' )
        END
	END
	IF(@action='DELETE')
	BEGIN
		UPDATE [dbo].[tuploadeddocuments]
		SET deleteflag='Yes'
		WHERE candidateid=@candidateid
		AND docid=@docid
		AND deleteflag='No'
	END
	IF(@action='SUBMIT')
	begin
		IF EXISTS (SELECT 1
                 FROM   [dbo].[tuploadeddocuments]
                 WHERE  candidateid = @candidateid
                        AND deleteflag = 'No')
		begin
		if EXISTS(Select docid from [dbo].[tuploadeddocuments]
		          where candidateid = @candidateid
                        AND deleteflag = 'No'
						And varifactionstatus='Rejected')
						begin
						 Select 2 --for doc submission faliure because of rejected doc
						end
						else
						begin
						 Update  [dbo].[trecruitcanbasicdtls]
		                 set docsubmissionallow='Completed',
		                 docsubmissionon=getdate()
			             where candidateid=@candidateid
                          Select 1 --for successful doc submission
						end
		
		end
		else
		begin
		 Select 0 --for doc submission faliure
		end
	end
	IF(@action='ISALLOW')
	begin
		Select docsubmissionallow from [dbo].[trecruitcanbasicdtls] where candidateid=@candidateid
	end
	IF(@action='STARTUPLOADING')
	begin
		UPDATE [dbo].[trecruitcanbasicdtls] 
		SET docsubmissionallow='Uploading'
		where candidateid=@candidateid
	end

      
  END 
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: tdocumentmaster, trecruitcanbasicdtls, trecruitcandidatesignup, trecruiteducation, tuploadeddocuments */
/****** Object:  StoredProcedure [dbo].[procverifycanndidateuploadeddocuments]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[procverifycanndidateuploadeddocuments]
@username varchar(max),
@candidateregno varchar(Max),
@acceptids varchar(Max)=null,
@rejectids varchar(Max)=null

as
Declare @canidateid int
Declare @countpendinguploaddoc int=0
Declare @countrejectdoc int=0
Declare @countacceptdoc int=0
Declare @rejectdocquery varchar(Max)
Declare @candidatename varchar(Max)
Declare @candidateemail varchar(Max)
begin
Select @canidateid=candidateid,@candidatename=firstname+' '+middlename+' '+lastname from [dbo].[trecruitcanbasicdtls] where registrationnumber=@candidateregno
Select @candidateemail= MailId from [dbo].[trecruitcandidatesignup] where CandidateID=@canidateid
Select @countpendinguploaddoc=count(docid) from [dbo].[tuploadeddocuments] where candidateid=@canidateid and deleteflag='No' 
Select @countpendinguploaddoc=count(docid) from [dbo].[tuploadeddocuments] where candidateid=@canidateid and deleteflag='No' and (varifactionstatus='Pending' or varifactionstatus='Rejected') 
if(len(@rejectids) is not null)
begin
create table #temprejectdoc
(
	docid varchar(10)
);
insert into  #temprejectdoc
 select items
 FROM [dbo].[Split] (@rejectids, ',')
 Select @countrejectdoc=COUNT(docid) from #temprejectdoc
 print @countrejectdoc
end
if(len(@acceptids) is not null)
begin
create table #tempacceptdoc
(
	docid varchar(10)
);
insert into  #tempacceptdoc
 select items
 FROM [dbo].[Split] (@acceptids, ',')
 Select @countacceptdoc=COUNT(docid) from #tempacceptdoc
end
if(@countpendinguploaddoc= @countacceptdoc + @countrejectdoc)
begin
 if(@countrejectdoc > 0)
 begin
 
 update [dbo].[tuploadeddocuments]
 set varifactionstatus='Rejected' ,
     varifactionstatuschangeby=@username,
	 varifactionstatuschangeon=getdate()
      where candidateid=@canidateid
       and deleteflag='No'
	   and docid in(Select convert(int,docid) from #temprejectdoc)

	   	update [dbo].[trecruitcanbasicdtls] set docsubmissionallow='Uploading' where candidateid=@canidateid
		--Declare @of varchar(5),@other varchar(10)
		--set @of=' Of '
		--set @other='Other'
		
	
   --Select documentname from 
   -- (select a.docid,a.documentname +'''+ @of +'''+ b.eduname documentname from tdocumentmaster a, trecruiteducation b
   -- where a.edulevel=b.edulevel
   -- union
   --  select docid,documentname from tdocumentmaster where documenttype= ''' + @Other +''')ab
   --  where docid in(Select convert(int,docid) from #temprejectdoc)
	 
	
	 
	 
	 Declare @mbody nvarchar(Max)
	 SELECT @mbody=(STUFF((
        Select documentname +'<br/>' from 
    (select a.docid,a.documentname +' of '+ b.eduname documentname from tdocumentmaster a, trecruiteducation b
    where a.edulevel=b.edulevel
    union
     select docid,documentname from tdocumentmaster where documenttype= 'Other')ab
     where docid in(Select convert(int,docid) from #temprejectdoc)
       
        FOR XML PATH('')
        ), 1, 0, '')
    ) 
   Set @mbody= Replace(@mbody,'&lt;','<')
   Set @mbody=Replace(@mbody,'&gt;','>')
	--------mail settings-----------------
	 DECLARE @tableHTML  NVARCHAR(MAX) ; 
	 Declare @name varchar(Max)
	 
	  begin
		set @name='Dear'+' '+@candidatename
	  end
     SET @tableHTML =  
    ' <table style=" font-size:20px; font-family:Tahoma ">

        <tr>

               <td>'+@name+'</td>

        </tr>

        <tr>

        <td>
			This mail is to inform you that the below mentioned Documents has been rejected by the Recruitment Authority:  </br>

        </td>

        </tr>
		<tr>
		<td>
		  ' +@mbody+'
		</td>
		
		</tr>
		
		
		
		<tr>
		<td>Please upload the proper Document.</td>
		</tr>
		</tr>
		<tr>
		<td><p><a href="http://recruitment.mendine.co.in/Account/Login.aspx">Go to the Recruitment Portal</a></p>
		
		</td>
        <tr>
				<br/><br/>
               <td>Thanks & Regards <br/><i>Mendine Recruitment Team</i></td>

        </tr>

   </table>

   ' ; 
   --Set @mbody=@tableHTML + @rejectdocquery

    EXEC msdb.dbo.sp_send_dbmail
    @profile_name = 'Mendine_Recruitment_Profile'
	--,@recipients = 'soumendu.patra@mendine.com'
    ,@recipients = @candidateemail
   ,@subject = 'Document Verification Faild'
   ,@body = @tableHTML
   --,@execute_query_database='Recruitment'
   --,@query=@rejectdocquery
   ,@importance ='HIGH'
   ,@body_format = 'HTML'
 
	--------End of mail settings-----------------
	drop table #temprejectdoc
 end	 
 if(@countacceptdoc > 0)
 begin  
 update [dbo].[tuploadeddocuments]
 set varifactionstatus='Accepted' ,
     varifactionstatuschangeby=@username,
	 varifactionstatuschangeon=getdate()
      where candidateid=@canidateid
       and deleteflag='No'
	   and docid in(Select convert(int,docid) from #tempacceptdoc)

	Drop table #tempacceptdoc
 end	   
      

 Select 1 as outmsg -- for successful submission of response
end
else
begin
 Select 0 as outmsg -- for not submission of response
end

end
GO



