/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitcanbasicdtls */
/****** Object:  StoredProcedure [dbo].[sp_CheckTestReportAvailability]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 CREATE PROCEDURE [dbo].[sp_CheckTestReportAvailability]   
    @registrationid Nvarchar(max),  
    @action NVARCHAR(50)  -- expected values: 'driscolallow', 'eqallow', 'iqallow', 'conflictallow'  
AS  
BEGIN  
    SET NOCOUNT ON;  
  
    -- Declare variable to hold the result  
    DECLARE @status NVARCHAR(20);  
  
    -- Check if the column is Completed (case-insensitive) for that registration ID  
    SELECT @status =   
        CASE   
            WHEN @action = 'discrol' AND LOWER(discrolallow) = 'completed' THEN 'Available'  
            WHEN @action = 'eq' AND LOWER(eqallow) = 'completed' THEN 'Available'  
            WHEN @action = 'iq' AND LOWER(iqallow) = 'completed' THEN 'Available'  
            WHEN @action = 'conflict' AND LOWER(conflictallow) = 'completed' THEN 'Available'  
            ELSE 'Not Available'  
        END  
    FROM trecruitcanbasicdtls  
    WHERE candidateid = @registrationid;  
  
    -- Return the result  
    SELECT @status AS AvailabilityStatus;  
END;  
GO



