/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: Company, temployeehistory_sales, temployeer_stkrel, tEmploymentHistory, trecruitboards, trecruitcanbasicdtls, trecruitcandidateresgisterdtls, trecruitcandidatesignup, trecruitcanfamilydtls, trecruitcanlanguage, tRecruitcanlevel, tRecruitcanotherdtls, tRecruitCanrefer, trecruitcanrelative, trecruitcountrycode, trecruiteducation, trecruitEduGap, tRecruitEduQualification, trecruitProfessionalExpGap, trecruitProfessionalSalesExpGap */
/****** Object:  StoredProcedure [dbo].[SP_Recruit_GetCandidateFullDump]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[SP_Recruit_GetCandidateFullDump]  
(  
    @CandidateId BIGINT,  
    @IncludeFileBlobs BIT = 1  -- 0 = skip big binary columns (faster), 1 = include resumefile/Data  
)  
AS  
BEGIN  
    SET NOCOUNT ON;  
    SET XACT_ABORT ON;  
    SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;  
  
    -------------------------------------------------------------------------  
    -- Resolve schema-qualified object names  
    -------------------------------------------------------------------------  
    DECLARE @Obj TABLE  
    (  
        KeyName SYSNAME PRIMARY KEY,  
        ObjName SYSNAME NOT NULL,  
        FullName NVARCHAR(300) NULL  
    );  
  
    INSERT INTO @Obj(KeyName, ObjName) VALUES  
    ('Basic',          'trecruitcanbasicdtls'),  
    ('Signup',         'trecruitcandidatesignup'),          -- ✅ NEW (to get username)  
    ('Register',       'trecruitcandidateresgisterdtls'),  
    ('Company',        'Company'),  
    ('UploadImage',    'trecruituploadimage'),  
    ('UploadResume',   'trecruituploadresume'),  
    ('AddressView',    'vw_canaddress'),  
    ('AppPostView',    'vw_canapppost'),  
    ('QuaOther',       'trecruitquaotherdtls'),  
    ('CanOther',       'trecruitcanotherdtls'),  
    ('Family',         'trecruitcanfamilydtls'),  
    ('Language',       'trecruitcanlanguage'),  
    ('EduQual',        'tRecruitEduQualification'),  
    ('Boards',         'trecruitboards'),  
    ('Education',      'trecruiteducation'),  
    ('EmpHistory',     'tEmploymentHistory'),  
    ('CanLevel',       'tRecruitcanlevel'),  
    ('CanRefer',       'tRecruitCanrefer'),  
    ('CanRelative',    'trecruitcanrelative'),  
    ('EmpHistorySales','temployeehistory_sales'),  
    ('EmpStkRel',      'temployeer_stkrel'),  
    ('EduGap',         'trecruitEduGap'),  
    ('ProfExpGap',     'trecruitProfessionalExpGap'),  
    ('ProfSalesGap',   'trecruitProfessionalSalesExpGap'),  
    ('ProjectDetails', 'trecruitProjectDetails'),  
    ('CountryCode',    'trecruitcountrycode');  
  
    UPDATE o  
    SET FullName = QUOTENAME(SCHEMA_NAME(x.schema_id)) + N'.' + QUOTENAME(o.ObjName)  
    FROM @Obj o  
    JOIN sys.objects x ON x.name = o.ObjName  
    WHERE x.type IN ('U','V');  
  
    -------------------------------------------------------------------------  
    -- Detect columns we need (robust to schema differences)  
    -------------------------------------------------------------------------  
    DECLARE  
        @DialCol SYSNAME = NULL,  
        @CountryKeyCol SYSNAME = NULL,  
        @BasicCountryCol SYSNAME = NULL,  
        @BasicRegIdCol SYSNAME = NULL,  
        @BasicEmailCol SYSNAME = NULL,  
        @BasicPostIdCol SYSNAME = NULL,  
  
        @SignupCandCol SYSNAME = NULL,  
        @SignupUserCol SYSNAME = NULL,  
        @SignupMailCol SYSNAME = NULL,  
  
        @CompanyKeyCol SYSNAME = NULL,  
        @CompanyLogoCol SYSNAME = NULL;  
  
    /* ---------------- Country table ---------------- */  
    /* ---------------- Country table ---------------- */  
IF EXISTS (SELECT 1 FROM @Obj WHERE KeyName='CountryCode' AND FullName IS NOT NULL)  
BEGIN  
    DECLARE @CountryObjId INT = OBJECT_ID((SELECT FullName FROM @Obj WHERE KeyName='CountryCode'));  
  
    -- Dial code column (stores +91) -> prefer "code"  
    SELECT TOP (1) @DialCol = c.name  
    FROM sys.columns c  
    WHERE c.object_id = @CountryObjId  
      AND c.name IN (N'code', N'Code', N'DialCode', N'dialcode', N'PhoneCode', N'phonecode')  
    ORDER BY CASE c.name  
                WHEN N'code' THEN 0  
                WHEN N'Code' THEN 1  
                WHEN N'DialCode' THEN 2  
                WHEN N'dialcode' THEN 3  
                WHEN N'PhoneCode' THEN 4  
                WHEN N'phonecode' THEN 5  
                ELSE 99  
             END;  
  
    -- Join key column -> prefer "codeid"  
    SELECT TOP (1) @CountryKeyCol = c.name  
    FROM sys.columns c  
    WHERE c.object_id = @CountryObjId  
      AND c.name IN (N'codeid', N'CodeId', N'CodeID', N'countrycodeid', N'CountryCodeId',  
       N'countrycode', N'CountryCode')  
    ORDER BY CASE c.name  
                WHEN N'codeid' THEN 0  
                WHEN N'CodeId' THEN 1  
                WHEN N'CodeID' THEN 2  
                WHEN N'countrycodeid' THEN 3  
                WHEN N'CountryCodeId' THEN 4  
                WHEN N'countrycode' THEN 5  
                WHEN N'CountryCode' THEN 6  
                ELSE 99  
             END;  
END  
    /* ---------------- Basic table ---------------- */  
    IF EXISTS (SELECT 1 FROM @Obj WHERE KeyName='Basic' AND FullName IS NOT NULL)  
    BEGIN  
        DECLARE @BasicObjId INT = OBJECT_ID((SELECT FullName FROM @Obj WHERE KeyName='Basic'));  
  
        SELECT TOP (1) @BasicCountryCol = c.name  
        FROM sys.columns c  
        WHERE c.object_id = @BasicObjId  
          AND c.name IN (N'countrycode', N'CountryCode', N'code', N'Code')  
        ORDER BY CASE c.name  
                    WHEN N'countrycode' THEN 1  
                    WHEN N'CountryCode' THEN 2  
                    WHEN N'code' THEN 3  
                    WHEN N'Code' THEN 4  
                    ELSE 99  
                 END;  
  
        SELECT TOP (1) @BasicRegIdCol = c.name  
        FROM sys.columns c  
        WHERE c.object_id = @BasicObjId  
          AND c.name IN (N'registrationid', N'RegistrationId', N'registrationId')  
        ORDER BY CASE c.name  
                    WHEN N'registrationid' THEN 1  
                    WHEN N'RegistrationId' THEN 2  
                    WHEN N'registrationId' THEN 3  
                    ELSE 99  
                 END;  
  
        SELECT TOP (1) @BasicEmailCol = c.name  
        FROM sys.columns c  
        WHERE c.object_id = @BasicObjId  
          AND c.name IN (N'mailid', N'MailId', N'mailID', N'MailID',  
                        N'email', N'Email', N'emailid', N'EmailId')  
        ORDER BY CASE c.name  
                    WHEN N'mailid' THEN 1  
                    WHEN N'mailID' THEN 2  
                    WHEN N'email' THEN 3  
                    WHEN N'emailid' THEN 4  
                    ELSE 99  
                 END;  
  
        SELECT TOP (1) @BasicPostIdCol = c.name  
        FROM sys.columns c  
        WHERE c.object_id = @BasicObjId  
          AND c.name IN (N'postid', N'PostId', N'IDPost', N'idpost')  
        ORDER BY CASE c.name  
                    WHEN N'postid' THEN 1  
                    WHEN N'PostId' THEN 2  
                    WHEN N'IDPost' THEN 3  
                    WHEN N'idpost' THEN 4  
                    ELSE 99  
                 END;  
    END  
  
    /* ---------------- Signup table (CandidateId -> Username) ---------------- */  
    IF EXISTS (SELECT 1 FROM @Obj WHERE KeyName='Signup' AND FullName IS NOT NULL)  
    BEGIN  
        DECLARE @SignupObjId INT = OBJECT_ID((SELECT FullName FROM @Obj WHERE KeyName='Signup'));  
  
        SELECT TOP (1) @SignupCandCol = c.name  
        FROM sys.columns c  
        WHERE c.object_id = @SignupObjId  
          AND c.name IN (N'candidateid', N'CandidateID', N'CandidateId')  
        ORDER BY CASE c.name  
                    WHEN N'candidateid' THEN 1  
                    WHEN N'CandidateID' THEN 2  
                    WHEN N'CandidateId' THEN 3  
                    ELSE 99  
                 END;  
  
        SELECT TOP (1) @SignupUserCol = c.name  
        FROM sys.columns c  
        WHERE c.object_id = @SignupObjId  
          AND c.name IN (N'username', N'UserName', N'User')  
        ORDER BY CASE c.name  
                    WHEN N'username' THEN 1  
                    WHEN N'UserName' THEN 2  
                    ELSE 99  
                 END;  
  
        SELECT TOP (1) @SignupMailCol = c.name  
        FROM sys.columns c  
        WHERE c.object_id = @SignupObjId  
          AND c.name IN (N'mailid', N'MailId', N'mailID', N'MailID', N'email', N'Email')  
        ORDER BY CASE c.name  
                    WHEN N'MailId' THEN 1  
                    WHEN N'mailid' THEN 2  
                    WHEN N'mailID' THEN 3  
                    WHEN N'email' THEN 4  
   ELSE 99  
                 END;  
    END  
  
    /* ---------------- Company table (logo) ---------------- */  
    IF EXISTS (SELECT 1 FROM @Obj WHERE KeyName='Company' AND FullName IS NOT NULL)  
    BEGIN  
        DECLARE @CompanyObjId INT = OBJECT_ID((SELECT FullName FROM @Obj WHERE KeyName='Company'));  
  
        SELECT TOP (1) @CompanyKeyCol = c.name  
        FROM sys.columns c  
        WHERE c.object_id = @CompanyObjId  
          AND c.name IN (N'companyPK', N'CompanyPK', N'IDCompany', N'CompanyId', N'Id', N'ID')  
        ORDER BY CASE c.name  
                    WHEN N'companyPK' THEN 0  
                    WHEN N'CompanyPK' THEN 1  
                    WHEN N'IDCompany' THEN 2  
                    WHEN N'CompanyId' THEN 3  
                    WHEN N'Id' THEN 4  
                    WHEN N'ID' THEN 5  
                    ELSE 99  
                 END;  
  
        SELECT TOP (1) @CompanyLogoCol = c.name  
        FROM sys.columns c  
        WHERE c.object_id = @CompanyObjId  
          AND (c.name LIKE '%logo%' OR c.name LIKE '%Logo%' OR c.name LIKE '%LOGO%')  
        ORDER BY CASE WHEN c.name LIKE '%path%' OR c.name LIKE '%Path%' THEN 0 ELSE 1 END;  
  
        IF @CompanyLogoCol IS NULL  
           AND EXISTS (SELECT 1 FROM sys.columns WHERE object_id=@CompanyObjId AND name=N'CompanyLogoFilePath')  
            SET @CompanyLogoCol = N'CompanyLogoFilePath';  
  
          -- Company Address fields  
        DECLARE  
            @CompanyAddr1Col SYSNAME = NULL,  
            @CompanyAddr2Col SYSNAME = NULL,  
            @CompanyStateCol SYSNAME = NULL,  
            @CompanyPinCol   SYSNAME = NULL;  
  
        SELECT @CompanyAddr1Col = c.name  
        FROM sys.columns c  
        WHERE c.object_id = @CompanyObjId  
          AND c.name IN (N'Address1', N'address1', N'Addr1');  
  
        SELECT @CompanyAddr2Col = c.name  
        FROM sys.columns c  
        WHERE c.object_id = @CompanyObjId  
          AND c.name IN (N'Address2', N'address2', N'Addr2');  
  
        SELECT @CompanyStateCol = c.name  
        FROM sys.columns c  
        WHERE c.object_id = @CompanyObjId  
          AND c.name IN (N'State', N'state', N'StateName');  
  
        SELECT @CompanyPinCol = c.name  
        FROM sys.columns c  
        WHERE c.object_id = @CompanyObjId  
          AND c.name IN (N'Pincode', N'PinCode', N'PostalCode', N'Zip');  
  
    END  
  
    -------------------------------------------------------------------------  
    -- 1) BASIC result set:  
    --    - MobileWithCountryCode  
    --    - Applied info from Register (found primarily via Signup.username)  
    --    - Company logo joined via Company.companyPK = Register.IDCompany  
    -------------------------------------------------------------------------  
    DECLARE @sql NVARCHAR(MAX);  
  
    IF EXISTS (SELECT 1 FROM @Obj WHERE KeyName='Basic' AND FullName IS NOT NULL)  
    BEGIN  
        DECLARE @BasicFull NVARCHAR(300)   = (SELECT FullName FROM @Obj WHERE KeyName='Basic');  
        DECLARE @SignupFull NVARCHAR(300)  = (SELECT FullName FROM @Obj WHERE KeyName='Signup');  
        DECLARE @RegFull   NVARCHAR(300)   = (SELECT FullName FROM @Obj WHERE KeyName='Register');  
        DECLARE @CtryFull  NVARCHAR(300)   = (SELECT FullName FROM @Obj WHERE KeyName='CountryCode');  
        DECLARE @CompFull  NVARCHAR(300)   = (SELECT FullName FROM @Obj WHERE KeyName='Company');  
  
        /* ---- Mobile expression ---- */  
        DECLARE @MobileExpr NVARCHAR(MAX) =  
N'CASE  
    WHEN b.mobile IS NULL OR LTRIM(RTRIM(CONVERT(NVARCHAR(50), b.mobile))) = N'''' THEN NULL  
    ELSE CONVERT(NVARCHAR(50), b.mobile)  
END';  
  
        IF @DialCol IS NOT NULL AND @CountryKeyCol IS NOT NULL AND @BasicCountryCol IS NOT NULL  
        BEGIN  
            SET @MobileExpr =  
N'CASE  
    WHEN b.mobile IS NULL OR LTRIM(RTRIM(CONVERT(NVARCHAR(50), b.mobile))) = N'''' THEN NULL  
    ELSE  
        COALESCE(  
            CASE  
                WHEN cc.' + QUOTENAME(@DialCol) + N' IS NULL THEN N''''  
                WHEN LEFT(CONVERT(NVARCHAR(20), cc.' + QUOTENAME(@DialCol) + N'), 1) = N''+'' THEN CONVERT(NVARCHAR(20), cc.' + QUOTENAME(@DialCol) + N')  
                ELSE N''+'' + CONVERT(NVARCHAR(20), cc.' + QUOTENAME(@DialCol) + N')  
            END,  
        N'''')  
        + CONVERT(NVARCHAR(50), b.mobile)  
END';  
        END  
  
        /* ---- Company logo select ---- */  
        DECLARE @CompanyLogoSelect NVARCHAR(MAX) = N'NULL';  
        IF @CompanyLogoCol IS NOT NULL  
            SET @CompanyLogoSelect = N'c.' + QUOTENAME(@CompanyLogoCol);  
          -- Company address selects  
        DECLARE @CompanyAddr1Select NVARCHAR(MAX) = N'NULL';  
        DECLARE @CompanyAddr2Select NVARCHAR(MAX) = N'NULL';  
        DECLARE @CompanyStateSelect NVARCHAR(MAX) = N'NULL';  
        DECLARE @CompanyPinSelect   NVARCHAR(MAX) = N'NULL';  
  
        IF @CompanyAddr1Col IS NOT NULL  
            SET @CompanyAddr1Select = N'c.' + QUOTENAME(@CompanyAddr1Col);  
  
        IF @CompanyAddr2Col IS NOT NULL  
            SET @CompanyAddr2Select = N'c.' + QUOTENAME(@CompanyAddr2Col);  
  
        IF @CompanyStateCol IS NOT NULL  
            SET @CompanyStateSelect = N'c.' + QUOTENAME(@CompanyStateCol);  
  
        IF @CompanyPinCol IS NOT NULL  
            SET @CompanyPinSelect = N'c.' + QUOTENAME(@CompanyPinCol);  
  
  
        /* ---- Signup APPLY (CandidateId -> Username/MailId) ---- */  
        DECLARE @SignupApply NVARCHAR(MAX) = N'OUTER APPLY (SELECT CAST(NULL AS NVARCHAR(200)) AS username, CAST(NULL AS NVARCHAR(300)) AS mailid) s';  
        IF @SignupFull IS NOT NULL AND @SignupCandCol IS NOT NULL  
        BEGIN  
            DECLARE @SignupUserSel NVARCHAR(MAX) = N'NULL';  
            DECLARE @SignupMailSel NVARCHAR(MAX) = N'NULL';  
  
            IF @SignupUserCol IS NOT NULL SET @SignupUserSel = N's.' + QUOTENAME(@SignupUserCol);  
            IF @SignupMailCol IS NOT NULL SET @SignupMailSel = N's.' + QUOTENAME(@SignupMailCol);  
  
            SET @SignupApply = N'  
OUTER APPLY  
(  
    SELECT TOP (1)  
        username = CONVERT(NVARCHAR(200), ' + @SignupUserSel + N'),  
        mailid   = CONVERT(NVARCHAR(300), ' + @SignupMailSel + N')  
    FROM ' + @SignupFull + N' s WITH (NOLOCK)  
    WHERE s.' + QUOTENAME(@SignupCandCol) + N' = b.candidateid  
    ORDER BY ISNULL(s.modifiedtime, s.createdtime) DESC  
) s';  
        END  
  
        /* ---- Register match priority: Signup.username first, then fallbacks ---- */  
        DECLARE @JoinRegisterWhere NVARCHAR(MAX) = N'1=0';  
  
        -- Preferred: Register.username = Signup.username  
        SET @JoinRegisterWhere = @JoinRegisterWhere + N' OR (s.username IS NOT NULL AND r.username = s.username)';  
  
        -- Optional: Register.mailID = Signup.mailid  
        SET @JoinRegisterWhere = @JoinRegisterWhere + N' OR (s.mailid IS NOT NULL AND r.mailID = s.mailid)';  
  
        -- Fallbacks (if your Basic has those columns)  
        IF @BasicRegIdCol IS NOT NULL  
            SET @JoinRegisterWhere = @JoinRegisterWhere + N' OR (r.Id = b.' + QUOTENAME(@BasicRegIdCol) + N')';  
  
        IF @BasicEmailCol IS NOT NULL  
            SET @JoinRegisterWhere = @JoinRegisterWhere + N' OR (r.mailID = b.' + QUOTENAME(@BasicEmailCol) + N')';  
  
        IF @BasicPostIdCol IS NOT NULL AND @BasicEmailCol IS NOT NULL  
            SET @JoinRegisterWhere = @JoinRegisterWhere + N' OR (r.IDPost = b.' + QUOTENAME(@BasicPostIdCol) + N' AND r.mailID = b.' + QUOTENAME(@BasicEmailCol) + N')';  
  
        /* ---- Final BASIC dynamic SQL ---- */  
        SET @sql = N'  
SELECT  
    b.*,  
    MobileWithCountryCode = ' + @MobileExpr + N',  
MobileDisplay =  
    CASE  
        WHEN b.mobile IS NULL OR LTRIM(RTRIM(CONVERT(NVARCHAR(50), b.mobile))) = N'''' THEN NULL  
        ELSE CONVERT(NVARCHAR(50), b.mobile) + N'' ('' + ' + @MobileExpr + N' + N'')''  
    END,  
  
    SignUpUserName        = s.username,  
    SignUpMailId          = s.mailid,  
  
    AppliedUserName       = r.username,  
    AppliedMailID         = r.mailID,  
    AppliedCompanyId      = r.IDCompany,  
    AppliedCompanyName    = r.CompanyName,  
    AppliedPostId         = r.IDPost,  
    AppliedPost           = r.Appliedpost,  
  
        CompanyLogo           = ' + @CompanyLogoSelect + N',  
  
    CompanyAddress1       = ' + @CompanyAddr1Select + N',  
    CompanyAddress2       = ' + @CompanyAddr2Select + N',  
    CompanyState          = ' + @CompanyStateSelect + N',  
    CompanyPincode        = ' + @CompanyPinSelect + N'  
FROM ' + @BasicFull + N' b WITH (NOLOCK)  
  
' + @SignupApply + N'  
  
OUTER APPLY  
(  
    SELECT TOP (1) r.*  
    FROM ' + @RegFull + N' r WITH (NOLOCK)  
    WHERE ' + @JoinRegisterWhere + N'  
    ORDER BY r.Id DESC  
) r  
  
' + CASE  
        WHEN @DialCol IS NOT NULL AND @CountryKeyCol IS NOT NULL AND @BasicCountryCol IS NOT NULL AND @CtryFull IS NOT NULL  
        THEN N'  
LEFT JOIN ' + @CtryFull + N' cc WITH (NOLOCK)  
       ON cc.' + QUOTENAME(@CountryKeyCol) + N' = b.' + QUOTENAME(@BasicCountryCol)  
        ELSE N''  
     END + N'  
  
' + CASE  
        WHEN @CompFull IS NOT NULL AND @CompanyKeyCol IS NOT NULL  
        THEN N'  
LEFT JOIN ' + @CompFull + N' c WITH (NOLOCK)  
       ON c.' + QUOTENAME(@CompanyKeyCol) + N' = r.IDCompany'  
        ELSE N''  
     END + N'  
WHERE b.candidateid = @CandidateId  
OPTION (RECOMPILE);';  
  
        EXEC sys.sp_executesql @sql, N'@CandidateId BIGINT', @CandidateId=@CandidateId;  
    END  
    ELSE  
        SELECT CAST(NULL AS INT) AS __Missing_Basic WHERE 1=0;  
  
    -------------------------------------------------------------------------  
    -- 2) UPLOAD IMAGE  
    -------------------------------------------------------------------------  
    IF EXISTS (SELECT 1 FROM @Obj WHERE KeyName='UploadImage' AND FullName IS NOT NULL)  
    BEGIN  
        IF @IncludeFileBlobs = 1  
            SET @sql = N'SELECT * FROM ' + (SELECT FullName FROM @Obj WHERE KeyName='UploadImage') +  
                       N' WITH (NOLOCK) WHERE candidateid=@CandidateId OPTION (RECOMPILE);';  
        ELSE  
            SET @sql = N'SELECT imageid, candidateid, name, ContentType, username, createdtime, modifiedtime  
                        FROM ' + (SELECT FullName FROM @Obj WHERE KeyName='UploadImage') +  
                       N' WITH (NOLOCK) WHERE candidateid=@CandidateId OPTION (RECOMPILE);';  
  
        EXEC sys.sp_executesql @sql, N'@CandidateId BIGINT', @CandidateId=@CandidateId;  
    END  
    ELSE  
        SELECT CAST(NULL AS INT) AS __Missing_UploadImage WHERE 1=0;  
  
    -------------------------------------------------------------------------  
    -- 3) UPLOAD RESUME  
    -------------------------------------------------------------------------  
    IF EXISTS (SELECT 1 FROM @Obj WHERE KeyName='UploadResume' AND FullName IS NOT NULL)  
    BEGIN  
        IF @IncludeFileBlobs = 1  
            SET @sql = N'SELECT * FROM ' + (SELECT FullName FROM @Obj WHERE KeyName='UploadResume') +  
                       N' WITH (NOLOCK) WHERE candidateid=@CandidateId OPTION (RECOMPILE);';  
        ELSE  
            SET @sql = N'SELECT id, candidateid, name, ContentType, username, createdtime, modifiedtime  
                        FROM ' + (SELECT FullName FROM @Obj WHERE KeyName='UploadResume') +  
                       N' WITH (NOLOCK) WHERE candidateid=@CandidateId OPTION (RECOMPILE);';  
  
        EXEC sys.sp_executesql @sql, N'@CandidateId BIGINT', @CandidateId=@CandidateId;  
    END  
    ELSE  
        SELECT CAST(NULL AS INT) AS __Missing_UploadResume WHERE 1=0;  
  
    -------------------------------------------------------------------------  
    -- 4) ADDRESS VIEW  
    -------------------------------------------------------------------------  
    IF EXISTS (SELECT 1 FROM @Obj WHERE KeyName='AddressView' AND FullName IS NOT NULL)  
    BEGIN  
        SET @sql = N'SELECT * FROM ' + (SELECT FullName FROM @Obj WHERE KeyName='AddressView') +  
                   N' WITH (NOLOCK) WHERE ccandidateid=@CandidateId OPTION (RECOMPILE);';  
        EXEC sys.sp_executesql @sql, N'@CandidateId BIGINT', @CandidateId=@CandidateId;  
    END  
   ELSE  
        SELECT CAST(NULL AS INT) AS __Missing_AddressView WHERE 1=0;  
  
    -------------------------------------------------------------------------  
    -- 5) APP POST VIEW  
    -------------------------------------------------------------------------  
    IF EXISTS (SELECT 1 FROM @Obj WHERE KeyName='AppPostView' AND FullName IS NOT NULL)  
    BEGIN  
        SET @sql = N'SELECT * FROM ' + (SELECT FullName FROM @Obj WHERE KeyName='AppPostView') +  
                   N' WITH (NOLOCK) WHERE candidateid=@CandidateId OPTION (RECOMPILE);';  
        EXEC sys.sp_executesql @sql, N'@CandidateId BIGINT', @CandidateId=@CandidateId;  
    END  
    ELSE  
        SELECT CAST(NULL AS INT) AS __Missing_AppPostView WHERE 1=0;  
  
    -------------------------------------------------------------------------  
    -- 6) EDU QUALIFICATIONS joined with BOARDS + EDUCATION  
    -------------------------------------------------------------------------  
    IF EXISTS (SELECT 1 FROM @Obj WHERE KeyName='EduQual' AND FullName IS NOT NULL)  
    BEGIN  
        DECLARE @EduFull NVARCHAR(300) = (SELECT FullName FROM @Obj WHERE KeyName='EduQual');  
        DECLARE @BoardFull NVARCHAR(300) = (SELECT FullName FROM @Obj WHERE KeyName='Boards');  
        DECLARE @EducationFull NVARCHAR(300) = (SELECT FullName FROM @Obj WHERE KeyName='Education');  
  
        IF @BoardFull IS NOT NULL AND @EducationFull IS NOT NULL  
        BEGIN  
            SET @sql = N'  
            SELECT q.*, b.*, e.*  
            FROM ' + @EduFull + N' q WITH (NOLOCK)  
            LEFT JOIN ' + @BoardFull + N' b WITH (NOLOCK) ON b.bdid = q.boardid  
            LEFT JOIN ' + @EducationFull + N' e WITH (NOLOCK) ON e.eduid = q.Educationid  
            WHERE q.candidateid = @CandidateId  
            OPTION (RECOMPILE);';  
        END  
        ELSE  
        BEGIN  
            SET @sql = N'  
            SELECT q.*  
            FROM ' + @EduFull + N' q WITH (NOLOCK)  
            WHERE q.candidateid = @CandidateId  
            OPTION (RECOMPILE);';  
        END  
  
        EXEC sys.sp_executesql @sql, N'@CandidateId BIGINT', @CandidateId=@CandidateId;  
    END  
    ELSE  
        SELECT CAST(NULL AS INT) AS __Missing_EduQual WHERE 1=0;  
  
    -------------------------------------------------------------------------  
    -- Remaining candidateid tables  
    -------------------------------------------------------------------------  
    DECLARE @keys TABLE(k SYSNAME);  
    INSERT INTO @keys(k) VALUES  
    ('QuaOther'),('CanOther'),('Family'),('Language'),  
    ('EmpHistory'),('CanLevel'),('CanRefer'),('CanRelative'),  
    ('EmpHistorySales'),('EmpStkRel'),('EduGap'),  
    ('ProfExpGap'),('ProfSalesGap'),('ProjectDetails');  
  
    DECLARE @k SYSNAME;  
    DECLARE cur CURSOR LOCAL FAST_FORWARD FOR SELECT k FROM @keys;  
    OPEN cur;  
    FETCH NEXT FROM cur INTO @k;  
  
    WHILE @@FETCH_STATUS = 0  
    BEGIN  
        IF EXISTS (SELECT 1 FROM @Obj WHERE KeyName=@k AND FullName IS NOT NULL)  
        BEGIN  
            SET @sql = N'SELECT * FROM ' + (SELECT FullName FROM @Obj WHERE KeyName=@k) +  
                       N' WITH (NOLOCK) WHERE candidateid=@CandidateId OPTION (RECOMPILE);';  
            EXEC sys.sp_executesql @sql, N'@CandidateId BIGINT', @CandidateId=@CandidateId;  
        END  
        ELSE  
            SELECT CAST(NULL AS INT) AS __Missing_Object WHERE 1=0;  
  
        FETCH NEXT FROM cur INTO @k;  
    END  
  
    CLOSE cur;  
    DEALLOCATE cur;  
END  
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruituploadresume */
/****** Object:  StoredProcedure [dbo].[SP_SAVE_RESUMEURL]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[SP_SAVE_RESUMEURL]
    @CandidateId INT,
    @FileUrl VARCHAR(250)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        UPDATE trecruituploadresume 
        SET ResumeFilePath = @FileUrl 
        WHERE candidateid = @CandidateId;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0
            ROLLBACK TRANSACTION;

        -- Optional: log or raise the error
        DECLARE @ErrorMessage NVARCHAR(4000) = ERROR_MESSAGE();
        RAISERROR (@ErrorMessage, 16, 1);
    END CATCH
END
GO



