/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitcandidatesignup, trecruiteducation, tRecruitEduQualification */
/****** Object:  StoredProcedure [dbo].[PRC_Get_Education_Count_temp]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[PRC_Get_Education_Count_temp]   
@UserName Varchar(200)  
AS  
Begin  
 Declare @CandidateID bigint  
 select @CandidateID = CandidateID from trecruitcandidatesignup Where username = @UserName  
 Select Count(*) CountEducation From trecruiteducation Where eduname != 'Diploma' AND edulevel <  
 (  
  Select Min(B.edulevel) From tRecruitEduQualification A  
  Inner Join trecruiteducation   B  
  On a.Educationid = B.eduid  
  Where A.candidateid = @CandidateID and Educationid <= (Select Max(Educationid) From tRecruitEduQualification Where candidateid = @CandidateID)  
 )  
End  
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruiteducation */
/****** Object:  StoredProcedure [dbo].[Proc_EducationDetails_temp]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[Proc_EducationDetails_temp]          
AS       
BEGIN         
SELECT [eduid], [eduname] FROM [trecruiteducation]     
WHERE [eduid] <>  7 and [eduid] <>  8 ORDER BY     
CASE     WHEN [eduname] = 'Select' THEN '1'         
ELSE [edulevel] END dESC;                
End 
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: none detected */
/****** Object:  StoredProcedure [dbo].[Proc_Getcandidateprofiledata_Test]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Proc_Getcandidateprofiledata_Test]       
@Deptname varchar(max),        
@postname varchar(max),        
@candidatename varchar(max),        
@FromDate varchar(100)=null,        
@ToDate varchar(100)=null,        
@Frselected varchar(100)        
AS        
BEGIN        
        
--set  @postname  = CASE WHEN CHARINDEX('-', @postname) > 0 THEN SUBSTRING(@postname, 1, CHARINDEX('-', @postname) - 1) ELSE @postname END         
    
IF (@postname = '-SELECT-' AND @candidatename='-SELECT-')    
BEGIN    
    
SELECT     
candidateid,     
CandidateName,     
CASE     
WHEN deptname = '' THEN 'OTHERS'     
ELSE deptname      
END AS deptname,     
postname  ,    
aplicationdate,    
Frselect    
FROM vw_essp_RecruitCanProfile         
WHERE     
--deptname = @Deptname     
(deptname = CASE WHEN @Deptname = '-SELECT-' THEN deptname ELSE @Deptname END)      
-- Only show data for the specified department    
AND (postname = CASE WHEN @postname = '-SELECT-' THEN postname ELSE @postname END)        
AND (CandidateName = CASE WHEN @candidatename = '-SELECT-' THEN CandidateName ELSE @candidatename END)       
AND (postname NOT LIKE '%ASSOCIATE%')      
OR (    
-- Check if @FromDate and @ToDate are empty, if so, ignore date filtering    
(    
    @FromDate = '' AND @ToDate = ''     
    OR     
    (    
        convert(date, (convert(varchar, convert(datetime, aplicationdate, 103), 101)), 101)      
        BETWEEN     
        convert(date, (convert(varchar, convert(datetime, @FromDate, 103), 101)), 101)     
        AND     
        convert(date, (convert(varchar, convert(datetime, @ToDate, 103), 101)), 101)    
    )    
)    
)          
AND (ISNULL(Frselect,'') = CASE WHEN @Frselected = '-SELECT-' THEN ISNULL(Frselect,'') ELSE @Frselected END)    
Order by CandidateName 
  --Order by aplicationdate DESC
END    
    
ELSE    
BEGIN    
    
         
SELECT     
        candidateid,     
        CandidateName,     
        CASE     
            WHEN deptname = '' THEN 'OTHERS'     
            ELSE deptname      
        END AS deptname,    
    
     
        postname  ,    
  aplicationdate,    
  Frselect    
    FROM vw_essp_RecruitCanProfile         
    WHERE     
      --  deptname = @Deptname     
    
  -- Only show data for the specified department    
    (deptname = CASE WHEN @Deptname = '-SELECT-' THEN deptname ELSE @Deptname END)      
    
        AND (postname = CASE WHEN @postname = '-SELECT-' THEN postname ELSE @postname END)        
        AND (CandidateName = CASE WHEN @candidatename = '-SELECT-' THEN CandidateName ELSE @candidatename END)       
        AND (postname NOT LIKE '%ASSOCIATE%')      
        AND (    
            -- Check if @FromDate and @ToDate are empty, if so, ignore date filtering    
            (    
                @FromDate = '' AND @ToDate = ''     
                OR     
                (    
                    convert(date, (convert(varchar, convert(datetime, aplicationdate, 103), 101)), 101)      
                        
BETWEEN     
                    convert(date, (convert(varchar, convert(datetime, @FromDate, 103), 101)), 101)     
                    AND     
                    convert(date, (convert(varchar, convert(datetime, @ToDate, 103), 101)), 101)    
                )    
          
    
      )    
        )          
        AND (ISNULL(Frselect,'') = CASE WHEN @Frselected = '-SELECT-' THEN ISNULL(Frselect,'') ELSE @Frselected END)     
      Order by CandidateName
	  --Order by aplicationdate DESC
END     
END 
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: tbl_All_Countries, trecruitcanaddress, trecruitstate, trecrutdistrict */
/****** Object:  StoredProcedure [dbo].[Proc_Recruit_GetAllCountryStateandDistrict_temp]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[Proc_Recruit_GetAllCountryStateandDistrict_temp]            
@countryid int=null,            
@stateid int = null,          
@action varchar(max)=null            
AS            
BEGIN        
      
            
IF (@action = 'COUNTRY')            
BEGIN            
select CountryId,CountryName from tbl_All_Countries            
END            
            
IF (@action = 'STATE')            
BEGIN            
select stateid,statename from trecruitstate             
where stateid not in (37) and           
CountryId=@countryid            
END          
          
IF (@action = 'ALLSTATE')            
BEGIN            
select stateid,statename from trecruitstate             
where stateid not in (37)           
END          
            
IF (@action = 'DISTRICT')            
BEGIN            
select disid,disname from trecrutdistrict             
where stateid=@stateid  AND disid not in (719)          
END            
          
IF(@action = 'DISTRICT_BY_ID')  
BEGIN  
  select disid,disname from trecrutdistrict             
  where stateid=@stateid AND CountryId=@countryid  AND disid not in (719)  
END  
  
  
IF (@action = 'ALLDISTRICT')            
BEGIN            
select DISTINCT A.disname,A.disid      
from trecrutdistrict A      
Where A.disid  in (select district from trecruitcanaddress)          
END           
            
END
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitcanaddress, trecruitcanbasicdtls, trecruitcandidatesignup, trecruitotherpost, trecruitstate, trecruituploadimage, trecruituploadresume, trecrutdistrict */
/****** Object:  StoredProcedure [dbo].[proccanbasicdtlsselect_temp]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
create PROCEDURE [dbo].[proccanbasicdtlsselect_temp]               
  @username      VARCHAR(100)=null,        
  @id int=null      
        
          
AS       
  BEGIN                   
      SET nocount ON;           
      DECLARE @value VARCHAR(200)       
      DECLARE @status VARCHAR(200)       
      DECLARE @canid VARCHAR(200)       
  DECLARE @cancount int      
   DECLARE @cancountot int      
      
      
          SELECT @canid = [candidateid]       
          FROM   [dbo].[trecruitcandidatesignup]       
          WHERE  [username] = @username       
      
  select @cancountot=count([candidateid]) from [dbo].[trecruitotherpost]      
  where [candidateid]=@canid      
      
  if @cancountot>0      
   begin      
   SELECT       
       [registrationnumber]         
      ,convert(varchar(10),[aplicationdate],103) as [aplicationdate]      
   ,id      
   ,f.[Name] rName      
   ,[imageid],       
    g.[Name],      
    [Data]      
      ,[firstname]      
      ,[middlename]      
      ,[lastname]      
      ,convert(varchar(10),[dateofbirth],103) as [dateofbirth]      
   ,otp.otpostname      
      ,[age]      
      ,[gender]      
      ,[maritalstatus]      
      ,[countrycode]      
      ,a.[mobile] mobile      
      ,[nationality]      
      ,[religion]      
   ,b.[addressline]       
      ,b.[saddressline]       
      ,b.[villagecity]       
      ,b.[postoffice]       
      ,b.[pincode]  
   ,b.[CountryId]  
      ,b.state      
      ,b.district      
   ,e.[addressline] paddressline      
      ,e.[saddressline] psaddressline      
      ,e.[villagecity] pvillagecity      
      ,e.[postoffice] ppostoffice      
      ,e.[pincode] ppincode   
   ,e.[CountryId]PCountryId  
      ,e.state pstate      
      ,e.district pdistrict      
            
  FROM [dbo].[trecruitcanbasicdtls] a      
  left outer join [dbo].[trecruitotherpost] otp      
 on  a.candidateid=otp.candidateid,      
  trecruitcanaddress b,      
  [dbo].[trecruitstate]c ,      
  [dbo].[trecrutdistrict] d,      
  trecruitcanaddress e,      
  [dbo].[trecruituploadresume] f,      
  [dbo].[trecruituploadimage] g      
        
   where a.candidateid=@canid      
    and a.candidateid=b.candidateid      
 and b.addresstype='c'      
 and b.[state]=c.stateid      
    and b.[district]=d.disid      
    and c.stateid=d.stateid      
 and a.candidateid=e.candidateid      
 and e.addresstype='p'      
 and a.candidateid=f.candidateid      
 and a.candidateid=g.candidateid      
    and a.candidateid=otp.candidateid                     
 end      
      
 else       
      
 begin      
 SELECT       
       [registrationnumber]         
      ,convert(varchar(10),[aplicationdate],103) as [aplicationdate]      
   ,id      
   ,f.[Name] rName      
   ,[imageid],       
    g.[Name],      
    [Data]      
      ,[firstname]      
      ,[middlename]      
      ,[lastname]      
      ,convert(varchar(10),[dateofbirth],103) as [dateofbirth]      
   ,''otpostname      
      ,[age]      
      ,[gender]      
      ,[maritalstatus]      
      ,[countrycode]      
      ,a.[mobile] mobile      
      ,[nationality]      
      ,[religion]      
   ,b.[addressline]       
      ,b.[saddressline]       
      ,b.[villagecity]       
      ,b.[postoffice]       
      ,b.[pincode]  
   ,b.[CountryId]  
      ,b.state      
      ,b.district      
   ,e.[addressline] paddressline      
      ,e.[saddressline] psaddressline      
      ,e.[villagecity] pvillagecity      
      ,e.[postoffice] ppostoffice      
      ,e.[pincode] ppincode   
   ,e.[CountryId]PCountryId  
      ,e.state pstate      
      ,e.district pdistrict    
   ,a.SpouseName spousename    
            
  FROM [dbo].[trecruitcanbasicdtls] a,      
        
  trecruitcanaddress b,      
  [dbo].[trecruitstate]c ,      
  [dbo].[trecrutdistrict] d,      
  trecruitcanaddress e,      
  [dbo].[trecruituploadresume] f,      
  [dbo].[trecruituploadimage] g      
        
   where a.candidateid=@canid      
    and a.candidateid=b.candidateid      
 and b.addresstype='c'      
 and b.[state]=c.stateid      
    and b.[district]=d.disid      
    and c.stateid=d.stateid      
 and a.candidateid=e.candidateid      
 and e.addresstype='p'      
 and a.candidateid=f.candidateid      
 and a.candidateid=g.candidateid      
         
  end      
 END   
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitcanaddress, trecruitcanappnum, trecruitcanbasicdtls, trecruitcandidatesignup, trecruitotherpost, trecruituploadimage, trecruituploadresume */
/****** Object:  StoredProcedure [dbo].[proccanbasicdtlsupdate_temp]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[proccanbasicdtlsupdate_temp] @username      VARCHAR(100)=NULL,         
                                               @Name          VARCHAR(50)=NULL,         
                                               @ContentType   NVARCHAR(200)=NULL,         
                                               @Data          VARBINARY(max)= NULL,         
                                               @iName         VARCHAR(50)=NULL,         
                                               @iContentType  VARCHAR(50)=NULL,         
                                               @iData         IMAGE=NULL,         
                                               @firstname     VARCHAR(100)=NULL,         
                                               @middlename    VARCHAR(100)=NULL,         
                                               @lastname      VARCHAR(100)=NULL,         
                                               @dateofbirth   DATETIME=NULL,         
                                               @gender        VARCHAR(10)=NULL,         
                                               @maritalstatus VARCHAR(10)=NULL,         
                                               @nationality   VARCHAR(10)=NULL,         
                                               @Religion      VARCHAR(max)=NULL,         
                                               @caddresstype  VARCHAR(10)=NULL,         
                                               @caddressline  VARCHAR(max)=NULL,         
                                               @csaddressline VARCHAR(max)=NULL,         
                                               @cvillagecity  VARCHAR(100)=NULL,         
                                               @cpostoffice   VARCHAR(100)=NULL,         
                                               @cpincode      VARCHAR(100)=NULL,      
              --      
              @CurCountry    varchar(100)=NULL,      
                                               --      
              @cstate        INT=NULL,         
                                               @cdistrict     INT=NULL,         
                                               @paddresstype  VARCHAR(10)=NULL,         
                                               @paddressline  VARCHAR(max)=NULL,         
                                               @psaddressline VARCHAR(max)=NULL,         
                                               @pvillagecity  VARCHAR(100)=NULL,         
                                               @ppostoffice   VARCHAR(100)=NULL,         
                                               @ppincode      VARCHAR(100)=NULL,       
              --      
             @PCountry      VARCHAR(100)=NULL,        
                                               --      
              @pstate        INT=NULL,         
                                               @pdistrict     INT=NULL,         
                                               @age           VARCHAR(10)=NULL,         
                                               @countrycode   VARCHAR(10)=NULL,         
                                               @mobile        VARCHAR(50) =NULL,         
                                               @voterid       VARCHAR(50) =NULL,         
                                               @otpostname    VARCHAR(100)=NULL,         
                                               @status        VARCHAR(200) =NULL   output  ,      
              @spousename   VARCHAR(500) =NULL      
AS         
  BEGIN         
      DECLARE @value VARCHAR(200)         
      DECLARE @canid VARCHAR(200)         
        
      SELECT @canid = [candidateid]         
      FROM   [dbo].[trecruitcandidatesignup]         
      WHERE  [username] = @username         
        
      IF @iContentType IS NULL         
        BEGIN         
            PRINT 's'         
        END         
      ELSE         
        BEGIN         
            UPDATE trecruituploadimage         
            SET    NAME = @iName,       
                   contenttype = @iContentType,         
                   data = @iData         
            WHERE  candidateid = @canid         
        END         
        
      IF @ContentType IS NULL         
        BEGIN       
            PRINT 's'         
        END       
      ELSE         
        BEGIN         
            UPDATE trecruituploadresume         
            SET    NAME = @Name,         
                   contenttype = @ContentType,         
                   resumefile = @Data         
            WHERE  candidateid = @canid         
        END         
        
      UPDATE [dbo].[trecruitcanbasicdtls]         
      SET    firstname = upper(trim(@firstname)),         
             middlename = upper(trim(@middlename)),         
             lastname = upper(trim(@lastname)),         
             dateofbirth = @dateofbirth,         
             age = @age,         
             gender = @gender,         
             maritalstatus = @maritalstatus,         
             nationality = @nationality,         
             religion = @Religion,         
             countrycode = @countrycode,         
             mobile = @mobile,         
             voterid = @voterid ,      
    SpouseName= @spousename      
      WHERE  candidateid = @canid         
        
      IF @cstate = ''         
          OR @cdistrict = ''         
        BEGIN         
            SELECT @status = 'Not Null'         
        
            RETURN         
        END;         
        
      IF @otpostname <> ''         
        BEGIN         
            DELETE FROM [dbo].[trecruitcanappnum]         
            WHERE  username = @username         
        
            DELETE FROM [dbo].[trecruitotherpost]         
            WHERE  candidateid = @canid         
   Select @otpostname=Replace(@otpostname,'&','and')        
            INSERT INTO [dbo].[trecruitotherpost]         
                        ([candidateid],         
                         [otpostname],         
                         [createdtime])         
            VALUES      ( @canid,         
                          @otpostname,         
                          Getdate() )         
        END         
        
      else        
        BEGIN         
            DELETE FROM [dbo].[trecruitotherpost]         
            WHERE  candidateid = @canid         
        END         
        
      UPDATE [dbo].[trecruitcanaddress]         
      SET    addressline = @caddressline,         
             saddressline = @csaddressline,         
             villagecity = @cvillagecity,         
             postoffice = @cpostoffice,         
             pincode = @cpincode,      
    CountryId=@CurCountry,      
             state = @cstate,         
             district = @cdistrict         
      WHERE  candidateid = @canid         
             AND addresstype = 'c'         
        
      UPDATE [dbo].[trecruitcanaddress]         
      SET    addressline = @paddressline,         
             saddressline = @psaddressline,         
             villagecity = @pvillagecity,         
             postoffice = @ppostoffice,         
             pincode = @ppincode,       
    CountryId=@PCountry,      
             state = @pstate,         
             district = @pdistrict         
      WHERE  candidateid = @canid         
             AND addresstype = 'p'         
        
      SET @status ='Record Updated Successfully'         
  END 
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitboards, trecruitcandidatesignup, trecruiteducation, tRecruitEduQualification */
/****** Object:  StoredProcedure [dbo].[proccanedureport_sample]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE procedure [dbo].[proccanedureport_sample]            
@username varchar(50)        
as        
begin        
DECLARE @canid VARCHAR(200)        
SELECT @canid = [candidateid]         
         FROM   [dbo].[trecruitcandidatesignup]         
          WHERE  [username] = @username         
          
                 insert tRecruitEduQualification(candidateid,Educationid,boardid,degreename,SubjectCombination,yearmonthpassing,institute,UniversityName,marks)     
    select @canid,eduid,196,'Na','Na','Na','Na','Na',0 from  trecruiteducation where eduid not in (7,8) and eduid not in    
    (select Educationid from tRecruitEduQualification where candidateid=@canid)    
    
     
    
SELECT eduname        
      ,bdname        
      ,[degreename]    
   ,ISNULL([SubjectCombination],'Na')SubjectCombination  
  ,startingYear  
      ,[yearmonthpassing]        
      ,[institute]       
       ,ISNULL([UniversityName], 'Na') UniversityName    
      ,[marks]              
  FROM [dbo].[tRecruitEduQualification] qua,[dbo].[trecruitboards] bo,[trecruiteducation] edu        
        
  where candidateid=@canid        
  and edu.eduid=qua.[Educationid]        
 -- and edu.eduid=bo.eduid        
  and qua.[boardid]=bo.bdid        
  order by edulevel desc        
  end
GO



