/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitcanbasicdtls, trecruitcandidatesignup, trecruitcanfamilydtls, trecruitcanlanguage, tRecruitCanrefer, tRecruitEduQualification, tRecruitquaotherdtls */
/****** Object:  StoredProcedure [dbo].[Proccheckreport_backup]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
CREATE PROCEDURE [dbo].[Proccheckreport_backup] @username VARCHAR(100),   
                                        @status   VARCHAR(100) output   
AS   
  BEGIN   
      DECLARE @canid VARCHAR(200)   
  
      SELECT @canid = [candidateid]   
      FROM   [dbo].[trecruitcandidatesignup]   
      WHERE  [username] = @username   
  
      IF NOT EXISTS(SELECT candidateid   
                    FROM   trecruitcanbasicdtls bdtls   
                    WHERE  candidateid = @canid)   
        BEGIN   
            SET @status=1   
  
            RETURN   
        END   
      ELSE IF NOT EXISTS(SELECT candidateid   
                    FROM   trecruitcanfamilydtls fam   
                    WHERE  candidateid = @canid)   
        BEGIN   
            --set @status='Please fillup family details'   
            SET @status=2   
  
            RETURN   
        END   
      ELSE IF NOT EXISTS(SELECT candidateid   
                    FROM   trecruitcanlanguage lan   
                    WHERE  candidateid = @canid)   
        BEGIN   
            --set @status='Please fillup language details'   
            SET @status=2   
  
            RETURN   
        END   
      ELSE IF NOT EXISTS(SELECT candidateid   
                    FROM   trecruiteduqualification qua   
                    WHERE  candidateid = @canid)   
        BEGIN   
            --set @status='Please fillup Education details'   
            SET @status=3   
  
            RETURN   
        END   
      ELSE IF NOT EXISTS(SELECT candidateid   
                    FROM   trecruitquaotherdtls qot   
                    WHERE  candidateid = @canid)   
        BEGIN   
            --set @status='Please fillup Others details'   
            SET @status=3   
  
            RETURN   
        END   
      ELSE IF NOT EXISTS(SELECT candidateid   
                    FROM   trecruitcanrefer ref   
                    WHERE  candidateid = @canid)   
        BEGIN   
            --set @status='Please fillup reference details'   
            SET @status=4   
  
            RETURN   
        END   
      ELSE   
        BEGIN   
            SET @status=5   
  
            RETURN   
        END   
  END 
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: Languages, trecruitboards, trecruitcanbasicdtls, trecruitcandidatesignup, trecruitcanfamilydtls, trecruitcanlanguage, tRecruitCanrefer, tRecruitEduQualification, tRecruitquaotherdtls */
/****** Object:  StoredProcedure [dbo].[Proccheckreport_sample]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Proccheckreport_sample] @username VARCHAR(100),     
                                        @status   VARCHAR(100) output     
AS     
  BEGIN  
      DECLARE @maritalstatus VARCHAR(200)
      DECLARE @canid VARCHAR(200)     
	 
 DECLARE @languageCount INT;

      SELECT @canid = [candidateid]     
      FROM   [dbo].[trecruitcandidatesignup]     
      WHERE  [username] = @username    
	  
	  select @maritalstatus=maritalstatus     
  	  from trecruitcanbasicdtls     
	  where candidateid=@canid

	  -- Count the number of languages selected by the candidate
		SELECT @languageCount = COUNT(*)
		FROM trecruitcanlanguage
		WHERE candidateid = @canid;
      IF NOT EXISTS(SELECT candidateid     
                    FROM   trecruitcanbasicdtls bdtls     
                    WHERE  candidateid = @canid)     
        BEGIN     
            SET @status=1     
    
            RETURN     
        END     
      ELSE IF NOT EXISTS(SELECT candidateid     
              FROM trecruitcanfamilydtls     
              WHERE candidateid = @canid)
			OR (@maritalstatus = 'Married' AND 
                 NOT EXISTS(SELECT * FROM trecruitcanfamilydtls 
                 WHERE candidateid = @canid 
                 AND relationship = 'Husband/Wife'))    
        BEGIN     
            --set @status='Please fillup family details'     
            SET @status=2       
            RETURN     
       END  	  
      ELSE IF @languageCount < 2     
        BEGIN     
            --set @status='Please fillup language details'     
            SET @status=2     
    
     
       RETURN     
        END     
      ELSE IF NOT EXISTS(SELECT candidateid     
                    FROM   trecruiteduqualification qua     
                    WHERE  candidateid = @canid)     
        BEGIN     
            --set @status='Please fi\llup Education details'     
            SET @status=3     
    
            RETURN     
        END     
      ELSE IF NOT EXISTS(SELECT candidateid     
                    FROM   trecruitquaotherdtls qot     
                    WHERE  candidateid = @canid) OR  
   NOT EXISTS(select B.bdname from tRecruitEduQualification AS A  
    INNER JOIN [trecruitboards] as B on B.bdid=A.boardid  
    where B.bdname<>'Not applicable' and A.candidateid=@canid)   
        BEGIN     
            --set @status='Pleasefillup Others details'     
            SET @status=3     
            RETURN     
        END     
      ELSE IF NOT EXISTS(SELECT candidateid     
                    FROM   trecruitcanrefer ref     
                    WHERE  candidateid = @canid)    



 
        BEGIN     
            --set @status='Please fillup reference details'     
            SET @status=4     
            RETURN     
        END   	 
		  ELSE     
			BEGIN     
				SET @status=5     
    
				RETURN     
			END     
  END
GO



