/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: Company, temployeehistory_sales, temployeer_stkrel, trecruitcandidatesignup */
/****** Object:  StoredProcedure [dbo].[procemphistory_sales_sample]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE  PROC [dbo].[procemphistory_sales_sample]          
@Action VARCHAR(10)                  
 ,@id INT = NULL                  
 ,@employername VARCHAR(Max) = NULL                  
 ,@employeeridparam int=null                  
 ,@durationform VARCHAR(50) = NULL                  
 ,@durationto VARCHAR(50) = NULL                  
 ,@designation VARCHAR(MAX) = NULL                  
 ,@yctc VARCHAR(50) = NULL         
 ,@aboveFourLakhSalary varchar(100)=NULL      
 ,@drivinglicenseno NVARCHAR(MAX) = NULL                
 ,@username VARCHAR(100) = NULL                  
 ,@areacovered NVARCHAR(Max) = NULL                  
 ,@reasonforchange VARCHAR(Max) = NULL                  
 ,@refname VARCHAR(Max) = NULL                  
 ,@refdesignation VARCHAR(Max) = NULL                  
 ,@refcontactno VARCHAR(Max) = NULL                  
 ,@stkname1 NVARCHAR(max) = NULL                  
 ,@stklocation1 NVARCHAR(Max) = NULL                  
 ,@stkcontact1 VARCHAR(Max) = NULL                  
 ,@stkname2 NVARCHAR(max) = NULL                  
 ,@stklocation2 NVARCHAR(Max) = NULL                  
 ,@stkcontact2 VARCHAR(Max) = NULL                  
 ,@stkname3 NVARCHAR(max) = NULL                  
 ,@stklocation3 NVARCHAR(Max) = NULL                  
 ,@stkcontact3 VARCHAR(Max) = NULL                  
 ,@status VARCHAR(100) = NULL OUTPUT                  
AS                  
DECLARE @canid VARCHAR(200)                  
DECLARE @employeerid INT                  
DECLARE @maxemployeerid INT                   
 DECLARE @EndDate DATE          
 DECLARE @StartDate DATE              
         
BEGIN                  
 SELECT @canid = [candidateid]                  
 FROM [dbo].[trecruitcandidatesignup]                  
 WHERE [username] = @username                  
             
             
                  
 IF @Action = 'Insert'                  
 BEGIN                  
 --Saikat Code          
  --DECLARE @StartDate DATE = TRY_PARSE(@durationform AS DATE USING 'en-US');          
   SET @StartDate  =TRY_CONVERT(DATE, SUBSTRING(@durationform, 7, 4) + '-' + SUBSTRING(@durationform, 4, 2) + '-' + SUBSTRING(@durationform, 1, 2), 120);     
        if(@durationto='Currently Working')          
    begin          
    SET @EndDate=GETDATE()          
    end          
  ELSE     
  BEGIN         
 --SET @EndDate  = TRY_PARSE(@durationto AS DATE USING 'en-US');       
 SET @EndDate  =TRY_CONVERT(DATE, SUBSTRING(@durationto, 7, 4) + '-' + SUBSTRING(@durationto, 4, 2) + '-' + SUBSTRING(@durationto, 1, 2), 120);    
 END        
IF NOT EXISTS (SELECT 1 FROM temployeehistory_sales WHERE candidateid=@canid  and(( TRY_CONVERT(DATE, SUBSTRING(durationform, 7, 4) + '-' + SUBSTRING(durationform, 4, 2) + '-' + SUBSTRING(durationform, 1, 2), 120)<=@EndDate     
   AND CASE When durationto = 'Currently Working' THEN GETDATE() ELSE TRY_CONVERT(DATE, SUBSTRING(durationto, 7, 4) + '-' + SUBSTRING(durationto, 4, 2) + '-' + SUBSTRING(durationto, 1, 2), 120)END >= @StartDate)) )      
BEGIN             
          
     SELECT @maxemployeerid = Max([employeerid])                  
     FROM [dbo].[temployeehistory_sales]                  
     WHERE [candidateid] = @canid                  
                  
     IF (@maxemployeerid IS NULL)                  
     BEGIN                  
      SET @employeerid = 1;                  
     END                  
     ELSE                  
     BEGIN                  
      SET @employeerid = @maxemployeerid + 1                  
     END                  
                  
     INSERT INTO [dbo].[temployeehistory_sales] (                  
      [candidateid]                  
      ,[employeerid]                  
      ,[employername]                  
      ,[designation]                  
      ,[durationform]                  
      ,[durationto]                  
      ,[grosssalary]                  
      ,[areacovered]                  
      ,[reasonforChange]                  
      ,[referencename]                  
      ,[referenceContactNo]                  
 ,[referencedesignation]                
      ,[drivinglicense]                
      ,[createdtime]                  
      ,[modificationtime]      
   ,[AboveFourLakhSalary]      
      )                  
     VALUES (                  
      @canid                  
      ,@employeerid                  
      ,@employername                  
      ,@designation                  
      ,@durationform                  
      ,@durationto                  
      ,@yctc                  
      ,@areacovered                  
      ,@reasonforchange                  
      ,@refname                  
      ,@refcontactno                  
      ,@refdesignation                
      ,@drivinglicenseno                
      ,getdate()                  
      ,NULL      
   ,@aboveFourLakhSalary      
      )                  
                  
     IF (@stkname1 <> '')                  
     BEGIN                  
      INSERT INTO [dbo].[temployeer_stkrel] (                  
    [candidateid]                  
    ,[employeerid]                  
    ,[stkname]                  
    ,[stklocation]                  
    ,[stkcontactno]                  
    ,[createdtime]                  
    ,[updatedtime]                  
    )                  
      VALUES (                  
    @canid                  
    ,@employeerid                  
    ,@stkname1                  
    ,@stklocation1                  
    ,@stkcontact1                  
    ,getdate()                  
    ,NULL                  
    )                  
     END                  
                  
     IF (@stkname2 <> '')                  
     BEGIN                  
      INSERT INTO [dbo].[temployeer_stkrel] (                  
    [candidateid]                  
    ,[employeerid]                  
    ,[stkname]                  
    ,[stklocation]                  
    ,[stkcontactno]                  
    ,[createdtime]                  
    ,[updatedtime]                  
    )                  
      VALUES (                  
    @canid                  
    ,@employeerid                  
    ,@stkname2                  
    ,@stklocation2                  
    ,@stkcontact2                  
    ,getdate()                  
    ,NULL                  
    )                  
     END                  
                  
     IF (@stkname3 <> '')                  
     BEGIN                  
      INSERT INTO [dbo].[temployeer_stkrel] (                  
    [candidateid]                  
    ,[employeerid]                  
    ,[stkname]                  
    ,[stklocation]                  
    ,[stkcontactno]                  
    ,[createdtime]                  
    ,[updatedtime]                  
    )                  
      VALUES (                  
    @canid                  
    ,@employeerid                  
    ,@stkname3                  
    ,@stklocation3                  
    ,@stkcontact3                  
    ,getdate()                  
      ,NULL                  
    )                  
     END                  
        SET @status = 'Data Inserted Successfully'                  
  END          
     ELSE          
  BEGIN          
      SET @status = 'This time duration spent on another company'          
  END          
 END                  
                  
 IF @action = 'Select'                  
 BEGIN                  
  WITH RankedData AS (                  
    SELECT *, RN = ROW_NUMBER() OVER(PARTITION BY employeerid ORDER BY id)                  
    FROM temployeer_stkrel                  
 where candidateid= @canid                  
)                  
select    
    b.id,    
    b.candidateid,                  
 b.employeerid,                   
    [designation]                  
    ,[durationform]                  
    ,[durationto]                  
    ,[grosssalary]       
 ,[AboveFourLakhSalary]      
    ,[areacovered]                  
    ,[reasonforChange]                  
    ,[referencename]                  
    ,[referenceContactNo]                  
    ,[referencedesignation]          
 ,[drivinglicense],                
      [employername],                   
    stkname1,                  
    stklocation1 ,                  
 stkcontactno1 ,                  
    stkname2,                  
 stklocation2 ,                  
 stkcontactno2 ,                  
 stkname3 ,                  
 stklocation3 ,                  
 stkcontactno3                  
 from (SELECT employeerid, candidateid,                  
stkname1 = MAX(CASE WHEN RN = 1 THEN stkname ELSE '' END),                  
 stklocation1 = MAX(CASE WHEN RN = 1 THEN stklocation ELSE '' END),                  
 stkcontactno1 = MAX(CASE WHEN RN = 1 THEN stkcontactno ELSE '' END),                  
    stkname2 = MAX(CASE WHEN RN = 2 THEN stkname ELSE '' END),                  
 stklocation2 = MAX(CASE WHEN RN = 2 THEN stklocation ELSE '' END),                  
 stkcontactno2 = MAX(CASE WHEN RN = 2 THEN stkcontactno ELSE '' END),                  
 stkname3 =  MAX(CASE WHEN RN = 3 THEN stkname ELSE '' END),                  
 stklocation3 = MAX(CASE WHEN RN = 3 THEN stklocation ELSE '' END),                  
 stkcontactno3 = MAX(CASE WHEN RN = 3 THEN stkcontactno ELSE '' END)                  
FROM RankedData                  
GROUP BY employeerid,candidateid                
) a Inner Join                
[temployeehistory_sales] b                  
On a.candidateid=b.candidateid                  
and a.employeerid=b.employeerid                  
                  
 END                  
 IF @action='Delete'                  
 begin                  
 Delete from [dbo].[temployeehistory_sales]                  
 where [candidateid]=@canid and [employeerid]=@employeeridparam                  
                  
 Delete from [dbo].[temployeer_stkrel]                  
 where [candidateid]=@canid and [employeerid]=@employeeridparam                  
                  
 end                  
 IF @Action='Update'               
 begin                  
   SET @StartDate   = TRY_CONVERT(DATE, SUBSTRING(@durationform, 7, 4) + '-' + SUBSTRING(@durationform, 4, 2) + '-' + SUBSTRING(@durationform, 1, 2), 120);        
   IF @durationto = 'Currently Working'                 
   BEGIN                     
     SET @EndDate = GETDATE();    
   END     
 ELSE      
	 BEGIN                   
		 SET @EndDate =TRY_CONVERT(DATE, SUBSTRING(@durationto, 7, 4) + '-' + SUBSTRING(@durationto, 4, 2) + '-' + SUBSTRING(@durationto, 1, 2), 120);                           
	   END     
IF @StartDate IS NOT NULL AND @EndDate IS NOT NULL AND @StartDate <= @EndDate  
BEGIN  
   IF NOT EXISTS (SELECT 1 FROM temployeehistory_sales WHERE candidateid=@canid AND id<>@id  and(( TRY_CONVERT(DATE, SUBSTRING(durationform, 7, 4) + '-' + SUBSTRING(durationform, 4, 2) + '-' + SUBSTRING(durationform, 1, 2), 120)<=@EndDate     
   AND CASE When durationto = 'Currently Working' THEN GETDATE() ELSE TRY_CONVERT(DATE, SUBSTRING(durationto, 7, 4) + '-' + SUBSTRING(durationto, 4, 2) + '-' + SUBSTRING(durationto, 1, 2), 120)END >= @StartDate)) )    
   BEGIN  
   
     Update [dbo].[temployeehistory_sales]                   
      set                                    
       [employername]=@employername                  
       ,[designation]=@designation                  
       ,[durationform]=@durationform                  
       ,[durationto]=@durationto                  
       ,[grosssalary]=@yctc        
       ,[AboveFourLakhSalary]=@aboveFourLakhSalary      
       ,[areacovered]=@areacovered                  
       ,[reasonforChange]=@reasonforchange                  
       ,[referencename]=@refname                  
       ,[referenceContactNo]=@refcontactno                  
       ,[referencedesignation]=@refdesignation                
       ,[drivinglicense]=@drivinglicenseno                                 
       ,[modificationtime]=getdate()                  
      where [candidateid]=@canid and [employeerid]=@employeeridparam                  
    set @status='Tested'	
	Delete from [dbo].[temployeer_stkrel]                  
      where [candidateid]=@canid and [employeerid]=@employeeridparam                  
     IF (@stkname1 <> '')                  
      BEGIN                  
       INSERT INTO [dbo].[temployeer_stkrel] (                  
     [candidateid]                  
     ,[employeerid]                  
     ,[stkname]                  
     ,[stklocation]                  
     ,[stkcontactno]                  
     ,[createdtime]                  
     ,[updatedtime]                  
     )                  
       VALUES (                  
     @canid                  
     ,@employeeridparam                  
     ,@stkname1                  
     ,@stklocation1                  
     ,@stkcontact1                  
     ,getdate()                  
     ,NULL                  
     )                  
      END                  
                  
      IF (@stkname2 <> '')                  
      BEGIN                  
       INSERT INTO [dbo].[temployeer_stkrel] (                  
     [candidateid]                  
     ,[employeerid]                  
     ,[stkname]                  
     ,[stklocation]                  
     ,[stkcontactno]                  
     ,[createdtime]                  
     ,[updatedtime]                  
     )                  
       VALUES (                  
     @canid                  
     ,@employeeridparam                  
     ,@stkname2                  
     ,@stklocation2                  
     ,@stkcontact2                  
     ,getdate()                  
     ,NULL                  
     )                  
      END                  
                  
      IF (@stkname3 <> '')                  
      BEGIN                  
       INSERT INTO [dbo].[temployeer_stkrel] (                  
     [candidateid]                  
     ,[employeerid]                  
     ,[stkname]                  
     ,[stklocation]                  
     ,[stkcontactno]                  
     ,[createdtime]                  
     ,[updatedtime]                  
     )                  
       VALUES (                  
     @canid                  
     ,@employeeridparam                  
     ,@stkname3                  
     ,@stklocation3                  
     ,@stkcontact3                  
     ,getdate()                  
     ,NULL                  
     )                  
       END                                     
 END   
   ELSE    
     BEGIN    
        SET @status = 'This time duration spent on another company'          
     END    
  END  
 end                  
END 
GO



