     ,@stklocation3                        
     ,@stkcontact3                        
     ,getdate()                        
     ,NULL                        
     )                        
       END                         
  --Sales Exp gap1          
  if @employernameFristGap IS Not NULL or @employernameFristGap=''          
  BEGIN          
     Delete FROM [trecruitProfessionalSalesExpGap] Where candidateid=@canid and EmployerName=@employernameFristGap          
     Delete FROM [trecruitProfessionalSalesExpGap] Where candidateid=@canid and EmployerName=@updatedEmployerNameExpFirst    
  INSERT INTO [trecruitProfessionalSalesExpGap]          
     (candidateid,          
     EmployerName,          
     GapReason,          
     NumberOfYear,          
     NumberOfMonth,          
     NumberOfDay,          
     createdtime)          
     VALUES(@canid,@employernameFristGap,@gapReason,@numberOfYear,@numberOfMonth,@numberOfDay, GETDATE())          
