  END          
  --Sales Exp gap2          
   if @employernameLastGap IS Not NULL or @employernameLastGap=''          
   BEGIN          
       Delete FROM [trecruitProfessionalSalesExpGap] Where candidateid=@canid and EmployerName=@employernameLastGap      
       Delete FROM [trecruitProfessionalSalesExpGap] Where candidateid=@canid and EmployerName=@updatedEmployerNameExpLast              
    
    
    INSERT INTO [trecruitProfessionalSalesExpGap]          
       (candidateid,          
       EmployerName,          
