/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: Company, tEmploymentHistory, trecruitcandidatesignup */
/****** Object:  StoredProcedure [dbo].[procemphistory_temp]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create procedure [dbo].[procemphistory_temp]        
@Action varchar(10),        
@id INT=null,        
@employername varchar(50)=null,        
@durationform varchar(50)=null,        
@durationto varchar(500)=null,        
@designation varchar(50)=null,  
@AboveFourLakhSalary varchar(500)=null,  
@yctc varchar(50)=null,        
@username varchar(100),        
@status varchar(100)=null output        
as        
begin        
SET NOCOUNT ON;        
 DECLARE @canid VARCHAR(200)        
   DECLARE @EndDate DATE;      DECLARE @StartDate DATE;      
      
 SELECT @canid = [candidateid]         
          FROM   [dbo].[trecruitcandidatesignup]         
          WHERE  [username] = @username         
  ------SELECT-----        
    IF @Action = 'SELECT'        
 BEGIN        
 SELECT [candidateid],        
    [id],        
      [employername]        
      ,[durationform]        
      ,[durationto]        
      ,[designation]        
      ,[grosssalary]  
   ,[AboveFourLakhSalary]  
  FROM [tEmploymentHistory] where candidateid=@canid        
 END        
 ------INSERT------------        
 IF @Action = 'INSERT'        
 BEGIN        
  SET @StartDate  =TRY_CONVERT(DATE, SUBSTRING(@durationform, 7, 4) + '-' + SUBSTRING(@durationform, 4, 2) + '-' + SUBSTRING(@durationform, 1, 2), 120);    
           if(@durationto='Currently Working')      
  begin      
     SET @EndDate=GETDATE()      
  end      
  ELSE         
  BEGIN         
    SET @EndDate  =TRY_CONVERT(DATE, SUBSTRING(@durationto, 7, 4) + '-' + SUBSTRING(@durationto, 4, 2) + '-' + SUBSTRING(@durationto, 1, 2), 120);              
  END       
    
IF NOT EXISTS (SELECT 1     FROM  tEmploymentHistory     WHERE candidateid=@canid and(( TRY_CONVERT(DATE, SUBSTRING(durationform, 7, 4) + '-' + SUBSTRING(durationform, 4, 2) + '-' + SUBSTRING(durationform, 1, 2), 120)<=@EndDate     
      AND    CASE When durationto = 'Currently Working' THEN GETDATE()ELSE TRY_CONVERT(DATE, SUBSTRING(durationto, 7, 4) + '-' + SUBSTRING(durationto, 4, 2) + '-' + SUBSTRING(durationto, 1, 2), 120)END >= @StartDate)))     
     BEGIN     
      INSERT INTO [tEmploymentHistory] ([candidateid]        
     ,[employername]        
     ,[durationform]        
     ,[durationto]        
     ,[designation]        
     ,[grosssalary]  
     ,[AboveFourLakhSalary])         
    VALUES (@canid,@employername, @durationform,@durationto,@designation,@yctc,@AboveFourLakhSalary)    
     SET @status=''    
      END    
   ELSE    
      BEGIN    
     SET @status='This time duration spent on another company'    
   END         
  --end        
  --else        
  --begin        
  --set @status=''        
  --end        
  --end        
END        
-------------UPDATE------------------------        
IF @Action = 'UPDATE'        
BEGIN      
    SET @StartDate  = TRY_CONVERT(DATE, SUBSTRING(@durationform, 7, 4) + '-' + SUBSTRING(@durationform, 4, 2) + '-' + SUBSTRING(@durationform, 1, 2), 120);    
   IF @durationto = 'Currently Working'             BEGIN                 SET @EndDate = GETDATE();             END           ELSE              BEGIN                SET @EndDate =TRY_CONVERT(DATE, SUBSTRING(@durationto, 7, 4) + '-' + SUBSTRING(@durationto
  
, 4, 2) + '-' + SUBSTRING(@durationto, 1, 2), 120);                    END           
  -- Convert @durationform to a valid date format     
  --SET @StartDate = TRY_PARSE(@durationform AS DATE USING 'en-US');          
 IF @StartDate IS NOT NULL AND @EndDate IS NOT NULL AND @StartDate <= @EndDate           BEGIN        IF NOT EXISTS (SELECT 1     
FROM  tEmploymentHistory     WHERE candidateid=@canid AND id<>@id and(( TRY_CONVERT(DATE, SUBSTRING(durationform, 7, 4) + '-' + SUBSTRING(durationform, 4, 2) + '-' + SUBSTRING(durationform, 1, 2), 120)<=@EndDate     
      AND    CASE When durationto = 'Currently Working' THEN GETDATE()ELSE TRY_CONVERT(DATE, SUBSTRING(durationto, 7, 4) + '-' + SUBSTRING(durationto, 4, 2) + '-' + SUBSTRING(durationto, 1, 2), 120) END >= @StartDate)))       
   BEGIN   
   UPDATE [tEmploymentHistory] SET [employername] = @employername,[durationform] = @durationform,[durationto] = @durationto,[designation] = @designation, [grosssalary] = @yctc,[AboveFourLakhSalary]=@AboveFourLakhSalary                  
        WHERE id = @id AND candidateid = @canid;                     
 END   
 ELSE   
 BEGIN          
  SET @status='This time duration spent on another company'        
 END          
END             
 ELSE           
  BEGIN                
   SET @status = '';           
  END      
        
END        
--DELETE        
    IF @Action = 'DELETE'        
 BEGIN        
  DELETE FROM [tEmploymentHistory]         
  WHERE id = @id and candidateid=@canid        
 END        
        
end  

GO



