   IF @durationto = 'Currently Working'             BEGIN                 SET @EndDate = GETDATE();             END           ELSE              BEGIN                SET @EndDate =TRY_CONVERT(DATE, SUBSTRING(@durationto, 7, 4) + '-' + SUBSTRING(@durationto
  
    
      
        
          
, 4, 2) + '-' + SUBSTRING(@durationto, 1, 2), 120);                    END                   
