CREATE PROCEDURE [dbo].[procinsfamilylanguage_temp]    
  @Action VARCHAR(10)    
 ,@memberid INT = NULL    
 ,@rmemberid INT = NULL    
 ,@Name VARCHAR(100) = NULL    
 ,@relationship VARCHAR(100) = NULL    
 ,@occupation VARCHAR(100) = NULL,    
 @username      VARCHAR(100)=null    
 ,@status varchar(100)=null output    
AS    
BEGIN    
 SET NOCOUNT ON;    
 DECLARE @canid VARCHAR(200)    
 declare @relac int    
    
 SELECT @canid = [candidateid]     
          FROM   [dbo].[trecruitcandidatesignup]     
          WHERE  [username] = @username     
    
 --SELECT    
    IF @Action = 'SELECT'    
 BEGIN    
  SELECT memberid,membername, relationship, occupation     
  FROM [trecruitcanfamilydtls] where candidateid=@canid    
 END    
    
 --INSERT    
    IF @Action = 'INSERT'    
 BEGIN    
 if @Name=''or @relationship=''or @occupation=''    
 begin    
 set @status='Please give a valid input'    
 return    
 end    
    
     
 --if not exists (select relationship from trecruitcanfamilydtls where relationship= @relationship and candidateid=@canid)    
 if ( not exists (select relationship from trecruitcanfamilydtls where relationship= @relationship and candidateid=@canid))  
   or(@relationship='Brother/Sister' or  @relationship='Children')  
 begin    
  INSERT INTO trecruitcanfamilydtls (candidateid,membername, relationship,occupation)     
  VALUES (@canid,@Name, @relationship,@occupation)    
  set @status='Data inserted successfully'    
  end    
    
    else    
 begin     
 set @status='Same Relationship is already present'    
 end    
 END    
    
 --UPDATE    
    
    IF @Action = 'UPDATE'    
     
    
 BEGIN     
 if @relationship='' or @Name='' or @occupation=''    
 begin    
 set @status='Please entry valid input'    
 return    
 end    
    
 select @relac=count(relationship) from trecruitcanfamilydtls where relationship= @relationship and candidateid=@canid    
    
    
     
    
 if  exists (select relationship from trecruitcanfamilydtls where relationship= @relationship and candidateid=@canid)    
 begin    
      
  UPDATE trecruitcanfamilydtls     
  SET membername = @Name, occupation=@occupation    
  WHERE memberid = @memberid and candidateid=@canid    
  set @status='Data updated successfully'    
 end    
    
 --if  not exists (select relationship from trecruitcanfamilydtls where relationship= @relationship and candidateid=@canid)    
 if ( not exists (select relationship from trecruitcanfamilydtls where relationship= @relationship and candidateid=@canid))  
   or(@relationship='Brother/Sister' or  @relationship='Children')
 begin    
      
  UPDATE trecruitcanfamilydtls     
  SET membername = @Name,relationship= @relationship, occupation=@occupation    
  WHERE memberid = @memberid and candidateid=@canid    
  set @status='Data updated successfully'    
 end    
      
END    
    
 --DELETE    
    IF @Action = 'DELETE'    
 BEGIN    
  DELETE FROM trecruitcanfamilydtls     
  WHERE memberid = @memberid and candidateid=@canid    
  set @status='Data deleted successfully'    
 END    
END
GO



