SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[procinslanguage_sample]    
 @Action VARCHAR(10)    
 ,@languageid int=null    
 ,@language VARCHAR(10) = NULL    
 ,@read VARCHAR(10) = NULL    
 ,@write VARCHAR(10) = NULL    
 ,@speak VARCHAR(10) = NULL    
 ,@username      VARCHAR(100)=null  
 ,@specifyLanguage nvarchar(max)=null  
 ,@status varchar(100) output    
AS    
BEGIN    
 SET NOCOUNT ON;    
    
 DECLARE @canid VARCHAR(200)    
    
 SELECT @canid = [candidateid]     
          FROM   [dbo].[trecruitcandidatesignup]     
          WHERE  [username] = @username    
    
 --SELECT    
    IF @Action = 'SELECT'    
 BEGIN    
  SELECT [languageid],[languagename],[SpecifyLanguage], [lread], [lwrite],[lspeak]     
  FROM [trecruitcanlanguage] where candidateid=@canid    
 END    
    
 --INSERT    
    IF @Action = 'INSERT'    
 BEGIN    
 if @read='No'and @write='No' and @speak='No'    
 begin    
 set @status='Atlist one parameter should be Yes'    
 return    
 end     
 if not exists (select [languagename] from [trecruitcanlanguage] where [languagename]= @language and candidateid=@canid)    
 begin    
  INSERT INTO [trecruitcanlanguage] (candidateid,[languagename],[SpecifyLanguage],[lread],[lwrite],[lspeak])     
  VALUES (@canid,@language,@specifyLanguage, @read,@write,@speak)    
  set @status='Data inserted successfully'    
  end    
    else    
 begin 
    if @language='Other'
	BEGIN
	   if not exists (select SpecifyLanguage from [trecruitcanlanguage] where SpecifyLanguage= @specifyLanguage and candidateid=@canid)
	   BEGIN
	     INSERT INTO [trecruitcanlanguage] (candidateid,[languagename],[SpecifyLanguage],[lread],[lwrite],[lspeak])     
		  VALUES (@canid,@language,@specifyLanguage, @read,@write,@speak)    
		  set @status='Data inserted successfully'  
	   END
	ELSE
	  BEGIN	 
	   set @status='Language already present'
	  END
	   --SELECT SpecifyLanguage FROM [trecruitcanlanguage]
	END
            
 end    
 END    
    
 --UPDATE    
    
    IF @Action = 'UPDATE'    
 BEGIN    
	 if @language='' or @read='' or @write='' or @speak=''    
	 begin    
		 set @status='Atlist one parameter should be Yes'    
		 return    
	 end    
	 if @read='No'and @write='No' and @speak='No'    
	 begin    
		 set @status='Atlist one parameter should be Yes'    
		 return    
	 end    
	 if  exists (select [languagename] from [trecruitcanlanguage] where [languagename]= @language and candidateid=@canid)    
	 begin    
	      if @language='Other'
			BEGIN
			   if not exists (select SpecifyLanguage from [trecruitcanlanguage] where SpecifyLanguage= @specifyLanguage and candidateid=@canid)
				BEGIN
				  UPDATE [trecruitcanlanguage]     
				  SET [languagename]= @language, SpecifyLanguage= @specifyLanguage    
				  WHERE [languageid] = @languageid and candidateid=@canid
				END
			END
		  UPDATE [trecruitcanlanguage]     
		  SET  [lread] = @read,[lwrite]=@write,[lspeak]=@speak    
		  WHERE [languageid] = @languageid and candidateid=@canid    
		  set @status='Data Updated Successfully'    
	  end    
		else    
	 begin     	     
		 UPDATE [trecruitcanlanguage]     
		  SET  [languagename]= @language,[SpecifyLanguage]=@specifyLanguage,[lread] = @read,[lwrite]=@write,[lspeak]=@speak    
		  WHERE [languageid] = @languageid and candidateid=@canid    
	 end    
END    
 --DELETE    
    IF @Action = 'DELETE'    
 BEGIN    
  DELETE FROM [trecruitcanlanguage]     
  WHERE [languageid] = @languageid and candidateid=@canid    
  set @status='Data deleted successfully'    
 END    
END
GO



