 SELECT        a.id,c.eduid, c.eduname, d.bdname, a.degreename,a.SubjectCombination  
 ,a.startingYear, a.yearmonthpassing, a.institute,a.UniversityName, a.marks, c.eduid, d.bdid          
FROM tRecruitEduQualification AS a     
INNER JOIN  trecruiteducation AS c ON a.Educationid = c.eduid     
