   --  SET @status='duplicate'          
   --  SELECT @status           
   --END          
 END          
          
 --UPDATE          
          
    IF @Action = 'UPDATE'          
 BEGIN  
  
  -------------------Saikat Mondal 13/08/2024---------------------------        
       UPDATE tRecruitEduQualification  
      SET   
         [Educationid]=T.Educationid,          
         [boardid]=T.boardid,  
         [degreename] = T.degreename,   
         [SubjectCombination]=T.SubjectCombination,  
         [startingYear]=T.startingYear,  
         [yearmonthpassing]=T.yearmonthpassing,          
         [institute]=T.institute,  
         UniversityName=T.UniversityName,  
         [marks]=T.marks        
      FROM   
     @TRecruitEduQuali T  
     WHERE   
    
   tRecruitEduQualification.candidateid = @canid and  
     tRecruitEduQualification.id=@id;  
      
END          
    IF @Action = 'NO_GAP'          
       BEGIN  
      UPDATE tRecruitEduQualification  
      SET   
         [Educationid]=T.Educationid,          
         [boardid]=T.boardid,  
         [degreename] = T.degreename,   
         [SubjectCombination]=T.SubjectCombination,  
         [startingYear]=T.startingYear,  
         [yearmonthpassing]=T.yearmonthpassing,          
         [institute]=T.institute,  
         UniversityName=T.UniversityName,  
         [marks]=T.marks        
      FROM   
     @TRecruitEduQuali T  
     WHERE    
           tRecruitEduQualification.candidateid = @canid and  
     tRecruitEduQualification.id=@id;  
      
     DELETE FROM [trecruitEduGap]               WHERE  candidateid=@canid    
       END  
 --DELETE   
    IF @Action ='GAP_YEAR'  
 Begin  
    UPDATE tRecruitEduQualification  
      SET   
         [Educationid]=T.Educationid,          
         [boardid]=T.boardid,  
         [degreename] = T.degreename,   
         [SubjectCombination]=T.SubjectCombination,  
         [startingYear]=T.startingYear,  
         [yearmonthpassing]=T.yearmonthpassing,          
         [institute]=T.institute,  
         UniversityName=T.UniversityName,  
         [marks]=T.marks        
      FROM   
     @TRecruitEduQuali T  
     WHERE    
           tRecruitEduQualification.candidateid = @canid and  
     tRecruitEduQualification.id=@id;  
  
     DELETE FROM [trecruitEduGap]               WHERE  candidateid=@canid  
  
     Insert [trecruitEduGap]   
     (candidateid,Educationid,GapReason,createdtime,NumberOfYear,NumberOfMonth)  
     SELECT @canid,[Educationid],[GapReason],GETDATE(),NumberOfYear,NumberOfMonth FROM @TRecruitEduGap  
  
      
 END  
  
    IF @Action = 'DELETE'          
 BEGIN      
  
 DECLARE @educationId VARCHAR(200)        

 select @educationId=Educationid from tRecruitEduQualification
  WHERE id = @id and candidateid=@canid

  DELETE FROM tRecruitEduQualification           
  WHERE id = @id and candidateid=@canid 
  
  DELETE FROM [trecruitEduGap]  WHERE  candidateid=@canid  and Educationid= @educationId 
  
 END  
         
END  

GO



