/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: trecruitcandidatesignup, trecruitProfessionalExpGap */
/****** Object:  StoredProcedure [dbo].[procProfessionalExpGapYearGap_Sample]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[procProfessionalExpGapYearGap_Sample]              
  @Action VARCHAR(100),              
  @id INT = NULL,              
  @username      VARCHAR(100)=null,      
  @employerName  nvarchar(max)=null,      
  @gapReason nvarchar(max)=null,      
  @numberOfYear nvarchar(max)=null,      
  @numberOfMonth nvarchar(max)=null,      
  @numberOfDay nvarchar(max)=null,      
  @status varchar(100)=null output       
AS             
BEGIN       
   DECLARE @canid VARCHAR(200)                      
  SELECT @canid = [candidateid]               
     FROM   [dbo].[trecruitcandidatesignup]               
     WHERE  [username] = @username         
    
IF @Action='Delete_by_Company'      
 BEGIN      
     DELETE FROM [trecruitProfessionalExpGap]               
     WHERE    candidateid= @canid and EmployerName=@employerName      
 END      
    
  IF @Action = 'SELECT'              
 BEGIN         
    --(Cast(A.NumberOfYear as varchar)+' Year '+cast(A.NumberOfMonth as varchar)+' Month')NumberOfGap      
    --,A.NumberOfYear,A.NumberOfMonth,A.NumberOfDay      
   select A.Id,A.EmployerName,A.GapReason,A.NumberOfYear,A.NumberOfMonth,A.NumberOfDay,(Cast(A.NumberOfYear as varchar)+' Year '+cast(A.NumberOfMonth as varchar)+' Month '+cast(A.NumberOfDay as varchar)+' Day')NumberOfGap from  trecruitProfessionalExpGap 
  
    
A      
 Where A.candidateid=@canid       
 End      
 IF @Action = 'UPDATE'              
 BEGIN              
   UPDATE [trecruitProfessionalExpGap]       
       SET      
        GapReason=@gapReason      
      Where candidateid=@canid and  Id=@id      
        
end      
      
 IF @Action = 'DELETE'              
 BEGIN          
  DELETE FROM [trecruitProfessionalExpGap]               
  WHERE id = @id and candidateid=@canid              
 END      
      
    
end      
GO



/* Functional group: 04_CANDIDATE_EAF_AND_DETAILS; referenced grouped tables: Hobbies, trecruitboards, trecruitcandidatesignup, tRecruitEduQualification, tRecruitquaotherdtls */
/****** Object:  StoredProcedure [dbo].[procupdatequaotherdtls_temp]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE procedure [dbo].[procupdatequaotherdtls_temp]    
  @Username varchar(50),    
  @Membership varchar(500),    
  @Otqualification varchar(500),    
  @cmputerProficiency varchar(500),    
  @Othertraining varchar(500),    
  @ExtraCurricular varchar(500),    
  @Hobbies varchar(50),    
  @Action VARCHAR(10),    
  @status varchar(500) output,  
  @euduStatus varchar(500)='0' output  
as    
begin    
declare @canid varchar(10)    
    
SELECT @canid = [candidateid]     
          FROM   [dbo].[trecruitcandidatesignup]     
          WHERE  [username] = @username     
    
  
  If EXISTS( select B.bdname from tRecruitEduQualification AS A
		INNER JOIN [trecruitboards] as B on B.bdid=A.boardid
		where B.bdname<>'Not applicable' and A.candidateid=@canid)    
  BEGIN  
    SET @euduStatus='1'  
  END  
 ELSE  
   BEGIN  
     SET @euduStatus='0'  
 END  
  
     IF @Action = 'UPDATE'    
begin    
update [dbo].[tRecruitquaotherdtls] set      
    
      
 Membership= @Membership ,    
 Otqualification= @Otqualification,     
 cmputerProficiency=@cmputerProficiency ,    
 Othertraining= @Othertraining ,    
 ExtraCurricular= @ExtraCurricular ,    
 Hobbies =@Hobbies     
       
where [candidateid]=@canid    
end    
set @status='Data Updated Successfully'    
end
GO



