/* Functional group: 05_APPLICATION_WORKFLOW_AND_TRACKER; referenced grouped tables: trecruitcanbasicdtls, trecruitmanualtraker */
/****** Object:  StoredProcedure [dbo].[PRC__BACKGROUNDDETAILS]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[PRC__BACKGROUNDDETAILS]  
@backgrounddetails varchar(10),  
@candidateid varchar(50)  
AS  
BEGIN  
  UPDATE  trecruitmanualtraker  
  SET   backgroundcheck=@backgrounddetails   
  where  Referenceno=@candidateid  
  UPDATE  trecruitcanbasicdtls   
  set   backgroundcheck=@backgrounddetails   
  where  registrationnumber=@candidateid  
  
    
  
END
GO



/* Functional group: 05_APPLICATION_WORKFLOW_AND_TRACKER; referenced grouped tables: trecruitcanbasicdtls */
/****** Object:  StoredProcedure [dbo].[PRC_Candidate_Resubmitform]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[PRC_Candidate_Resubmitform]  
   @PersonalDtlsResubmitStatus varchar(100)=Null,              
   @FamilyLanguageDtlsResubmitStatus varchar(100)=Null,              
   @EducationDtlsResubmitStatus varchar(100)=Null,              
   @EmploymentHistoryDtlsResubmitStatus varchar(100)=Null,              
   @AllFormOpenResubmitStatus varchar(100)=Null,   
   @referenceno varchar(max)=null,  
   @Action varchar(max)  
as    
begin  
   if @Action ='INSERT'  
   BEGIN  
     if(@PersonalDtlsResubmitStatus IS NOT NULL              
    OR @FamilyLanguageDtlsResubmitStatus IS NOT NULL              
  OR @EducationDtlsResubmitStatus IS NOT NULL              
  OR @EmploymentHistoryDtlsResubmitStatus IS NOT NULL              
  OR @AllFormOpenResubmitStatus IS NOT NULL)                                     
    Begin              
   UPDATE [dbo].[trecruitcanbasicdtls]                                              
    SET [applicationstatus]='RESUBMIT',              
    PersonalDtlsResubmitStatus=@PersonalDtlsResubmitStatus,              
    LanguageDtlsResubmitStatus=@FamilyLanguageDtlsResubmitStatus,              
    EducationDtlsResubmitStatus=@EducationDtlsResubmitStatus,              
    EmploymentHistoryDtlsResubmitStatus=@EmploymentHistoryDtlsResubmitStatus,              
    AllFormOpenResubmitStatus=@AllFormOpenResubmitStatus              
   WHERE [registrationnumber]= @referenceno                                              
  ----------------Saikat Start Put Resubmit Status----------------   
    End       
   END   
   ELSE IF(@Action ='SELECT')  
   BEGIN  
   Select   
   rs.[applicationstatus],                
     rs.[PersonalDtlsResubmitStatus],            
     rs.[LanguageDtlsResubmitStatus],            
     rs.[EducationDtlsResubmitStatus],            
     rs.[EmploymentHistoryDtlsResubmitStatus],            
     rs.[AllFormOpenResubmitStatus]  
   from [trecruitcanbasicdtls] rs  
   WHERE [registrationnumber]= @referenceno    
   END  
end       
GO



/* Functional group: 05_APPLICATION_WORKFLOW_AND_TRACKER; referenced grouped tables: trecruitcanbasicdtls, trecruitcandidatesignup */
/****** Object:  StoredProcedure [dbo].[PRC_Receruitment_ApplicationFormResubmitted]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[PRC_Receruitment_ApplicationFormResubmitted]         
@username VARCHAR(1000)                        
AS                   
  BEGIN                   
      DECLARE @canid INT                                
      SELECT @canid = [candidateid]                   
      FROM   [dbo].[trecruitcandidatesignup]                   
      WHERE  [username] = @username                   
      
   Update [trecruitcanbasicdtls]   
   set   
   Applicationstatus='SUBMITTED',  
   PersonalDtlsResubmitStatus=NULL   
   ,LanguageDtlsResubmitStatus=NULL  
   ,EducationDtlsResubmitStatus=NULL  
   ,EmploymentHistoryDtlsResubmitStatus=NULL  
   ,AllFormOpenResubmitStatus=NULL  
   WHERE candidateid =@canid  
  END 
GO



