/* Functional group: 05_APPLICATION_WORKFLOW_AND_TRACKER; referenced grouped tables: trecruitdepartment */
/****** Object:  StoredProcedure [dbo].[PRC_Receruitment_Department_Tracker_List]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROC [dbo].[PRC_Receruitment_Department_Tracker_List]                  
    @Year INT,                     -- Mandatory      
    @Month INT = NULL,             -- Optional      
    @Week INT = NULL               -- Optional      
AS                  
BEGIN              
    DECLARE @EndDate DATETIME;      
      
    -- Calculate the end date based on the given year, month, and week      
    IF @Year IS NOT NULL AND @Month IS NOT NULL AND @Week IS NOT NULL      
    BEGIN      
        SET @EndDate = DATEADD(DAY, (@Week * 7) - 1, DATEADD(MONTH, @Month - 1, DATEADD(YEAR, @Year - 1900, 0)));      
    END      
    ELSE IF @Year IS NOT NULL AND @Month IS NOT NULL      
    BEGIN      
        SET @EndDate = EOMONTH(DATEADD(MONTH, @Month - 1, DATEADD(YEAR, @Year - 1900, 0)));      
    END      
    ELSE IF @Year IS NOT NULL      
    BEGIN      
        SET @EndDate = DATEADD(YEAR, @Year - 1900, '1900-12-31');--DATEADD(YEAR, @Year - 1900, '12-31');      
    END;   
    ;WITH CTE AS (                  
        SELECT                   
            ID,                   
            DeptName,                    
            ROW_NUMBER() OVER (PARTITION BY DeptName ORDER BY (SELECT 0)) AS rn,      
            CreatedTime ,  
   ActiveFlag  
        FROM [trecruitdepartment]                  
        UNION                  
        SELECT                   
            '' AS ID,                   
            'OTHER' AS DeptName,                  
            ROW_NUMBER() OVER (PARTITION BY DeptName ORDER BY (SELECT 0)) AS rn,      
            CreatedTime,  
   ActiveFlag  
        FROM [trecruitdepartment]                  
    )                  
    SELECT DISTINCT                   
        CTE.ID,                   
        CTE.DeptName,               
        CTE.CreatedTime                
    FROM CTE                  
    INNER JOIN (                  
        SELECT DISTINCT DeptId                 
        FROM [vw_Recruitment_AllPost]                 
    ) allPost ON allPost.DeptId = CTE.ID                  
    WHERE                   
        CTE.rn = 1                   
        AND CTE.DeptName != ''                   
        AND CTE.DeptName IS NOT NULL                   
        AND CTE.ID != 22      
  AND ActiveFlag !='N'  
        AND ISDATE(CTE.CreatedTime) = 1               -- Ensure it is a valid date      
        AND CONVERT(DATETIME, CTE.CreatedTime, 103) <= @EndDate      
    ORDER BY CTE.ID;                    
END
GO



/* Functional group: 05_APPLICATION_WORKFLOW_AND_TRACKER; referenced grouped tables: trecruittraker */
/****** Object:  StoredProcedure [dbo].[PRC_Save_OtherDetails]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[PRC_Save_OtherDetails]          
(          
    @Action NVARCHAR(30),     
    @Referenceno NVARCHAR(50),
    @DOO Nvarchar(50) = NULL,
    @DOJ Nvarchar(50)= NULL,
    @Empcode NVARCHAR(50) = NULL,
    @Remarks NVARCHAR(MAX) = NULL,
  
  @TimeTaken NVARCHAR(50) = NULL
)          
AS          
BEGIN          
    SET NOCOUNT ON;      

    BEGIN TRY      
	     
IF (NOT EXISTS (SELECT 1 FROM trecruittraker WHERE Referenceno = @Referenceno))        
    BEGIN  
	    DECLARE @Departmentdivision NVARCHAR(MAX),          
            @PostId BIGINT,          
            @Source NVARCHAR(MAX),          
            @Postname NVARCHAR(MAX),          
            @Locid BIGINT,          
            @CandidateID BIGINT,          
            @Candidatename NVARCHAR(MAX);      
      
		SELECT           
			@Departmentdivision = deptdivision,          
			@PostId = postid,          
			@Source = referredus,          
			@Postname = postname,          
			@Locid = locid,          
			@CandidateID = candidateid,          
			@Candidatename = CandidateName          
		FROM vw_recruittracker          
		WHERE registrationnumber = @Referenceno;     


        INSERT INTO trecruittraker (Referenceno, Departmentdivision, locid, candidateid, source, candidatename, postid, Postname)          
        VALUES (@Referenceno, @Departmentdivision, @Locid, @CandidateID, @Source, @Candidatename, @PostId, @Postname);          
    END;    
        ------------------------------------------------------------
        -- UPDATE DOO
        ------------------------------------------------------------
        IF (@Action = 'UPDATE_DOO')
        BEGIN
            UPDATE trecruittraker
            SET DOO = @DOO
            WHERE Referenceno = @Referenceno;
        END

        -----------------------------------------------------------

        -- CLEAR DOO
        ------------------------------------------------------------
        IF (@Action = 'CLEAR_DOO')
        BEGIN
            UPDATE trecruittraker
            SET DOO = NULL
            WHERE Referenceno = @Referenceno;
       




 END

        ------------------------------------------------------------
        -- UPDATE DOJ
        ------------------------------------------------------------
        IF (@Action = 'UPDATE_DOJ')
        BEGIN
            UPDATE trecruittraker
     


       SET DOJ = @DOJ
            WHERE Referenceno = @Referenceno;
        END

        ------------------------------------------------------------
        -- CLEAR DOJ
        ------------------------------------------------------------
        IF (@Action = 'CLEAR_DOJ')
        BEGIN
            UPDATE trecruittraker
            SET DOJ = NULL
            WHERE Referenceno = @Referenceno;
        END

        ------------------------------------------------------------
        -- UPDATE EMP CODE
     


   ------------------------------------------------------------
        IF (@Action = 'UPDATE_EMPCODE')
        BEGIN
            UPDATE trecruittraker
            SET Empcode = @Empcode
            WHERE Referenceno = @Referenceno;
        END

     
-----------------------------------------------------------
        -- UPDATE REMARKS
        ------------------------------------------------------------
        IF (@Action = 'UPDATE_REMARKS')
        BEGIN
            UPDATE trecruittraker
            


SET Remarks = @Remarks
            WHERE Referenceno = @Referenceno;
        END

        ------------------------------------------------------------
        -- UPDATE TIME TAKEN
        ------------------------------------------------------------
      


  IF (@Action = 'UPDATE_TIMETAKEN')
        BEGIN
            UPDATE trecruittraker
            SET timetaken = @TimeTaken
            WHERE Referenceno = @Referenceno;
        END

    END TRY      
    BEGIN CATCH      
        THROW;      
    END CATCH;      
END

GO



