/* Functional group: 05_APPLICATION_WORKFLOW_AND_TRACKER; referenced grouped tables: trecruitcanaddress, trecruitcanappnum, trecruitcanbasicdtls, trecruitcandidatesignup, trecruitmanualtraker, trecruitotherpost, trecruituploadimage, trecruituploadresume */
/****** Object:  StoredProcedure [dbo].[Proc_SAVE_PersonalDetails]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
          
CREATE PROCEDURE [dbo].[Proc_SAVE_PersonalDetails]  
@username      VARCHAR(100)=NULL,     
                                            @rName         VARCHAR(50),     
                                            @rContentType  NVARCHAR(200),     
                                            @rData         VARBINARY(max),     
                                            @iName         VARCHAR(50),     
                                            @iContentType  VARCHAR(50),     
                                            @iData         IMAGE,     
                                            @firstname     VARCHAR(100)=NULL,     
                                            @middlename    VARCHAR(100)=NULL,     
                                            @lastname      VARCHAR(100)=NULL,     
                                            @dateofbirth   DATETIME=NULL,     
                                            @gender        VARCHAR(10)=NULL,     
                                            @maritalstatus VARCHAR(10)=NULL,     
                                            @nationality   VARCHAR(10)=NULL,     
                                            @Religion      VARCHAR(10)=NULL,     
                                            @voterid       VARCHAR(10)=NULL,     
                                            @age           VARCHAR(10)=NULL,     
                                            @countrycode   VARCHAR(10)=NULL,     
                                            @mobile        VARCHAR(50) =NULL,     
                                            @paddresstype  VARCHAR(10)=NULL,     
                                            @paddressline  VARCHAR(max)=NULL,     
                                            @psaddressline VARCHAR(max)=NULL,     
                                            @pvillagecity  VARCHAR(200)=NULL,     
                                            @ppostoffice   VARCHAR(200)=NULL,     
                                            @ppincode      VARCHAR(200)=NULL, 
											@PCountry      INT =NULL,  
                                            @pstate        INT =NULL,     
                                            @pdistrict     INT =NULL,     
                                            @caddresstype  VARCHAR(10) =NULL,     
                                            @caddressline  VARCHAR(max)=NULL,     
                                            @csaddressline VARCHAR(max)=NULL,     
                                            @cvillagecity  VARCHAR(200)=NULL,     
                                            @cpostoffice   VARCHAR(200)=NULL,     
                                            @cpincode      VARCHAR(200)=NULL,  
											@CurCountry    INT =NULL,    
                                            @cstate        INT =NULL,     
                                            @cdistrict     INT =NULL,     
                                            @caddtype      VARCHAR(10),     
                                            @paddtype      VARCHAR(10),     
                                            @status        VARCHAR(200) =NULL output ,    
           @mailid        VARCHAR(200) =NULL,    
           @otpostname    VARCHAR(500) =NULL    
    
AS     
  BEGIN     
      --SET nocount ON;      
      DECLARE @value VARCHAR(200)     
      DECLARE @countcam INT     
      DECLARE @canid VARCHAR(200)     
      DECLARE @canuser INT     
   declare @count int    
   DECLARE @Referenceno VARCHAR(200)     
    
    
      SET @value=Cast(next value FOR seregistrationno AS VARCHAR(30))     
    
      SELECT @canid = [candidateid],@mailid=mailid    
      FROM   [dbo].[trecruitcandidatesignup]     
      WHERE  [username] = @username     
    
   select @count=count(mailid) from [dbo].[trecruitmanualtraker] where mailid=@mailid    
    
    
   select @Referenceno=Referenceno from [dbo].[trecruitmanualtraker] where mailid=@mailid    
    
      --select @canuser=count(username) from [dbo].[trecruitcanappnum]     
      --where username=@username     
      SELECT @countcam = Count(candidateid)     
      FROM   trecruitcanbasicdtls     
      WHERE  candidateid = @canid     
    
    
    
      IF @countcam > 0     
        BEGIN     
            SELECT @status = 'Already Exist'     
    
            RETURN     
        END     
      --else if @canuser>0      
      --begin     
      --  select @status='Already Exist'     
      --  return     
      --  end     
      ELSE IF @iName = ''     
          OR @iContentType = ''     
          OR @iData IS NULL     
        BEGIN     
            SELECT @status = 'Image and Resume Reqiured'     
    
            RETURN     
        END     
      ELSE IF @rName = ''     
          OR @rContentType = ''     
          OR @rData IS NULL     
        BEGIN     
            SELECT @status = 'Image and Resume Reqiured'     
    
            RETURN     
        END     
      ELSE     
        BEGIN     
                 
    
   if @count>0    
    
    
   begin    
    INSERT INTO [dbo].[trecruitcanbasicdtls]     
                        (registrationid,     
                         registrationnumber,     
                         candidateid,     
                         aplicationdate,     
                         firstname,     
                         middlename,     
                         lastname,     
                         dateofbirth,     
                         age,     
                         gender,     
                         maritalstatus,     
                         nationality,     
                         religion,     
                         countrycode,     
                         mobile,     
                         voterid,     
                         applicationstatus,    
       submitstatus,     
                         createdtime)     
            VALUES      (next value FOR seregistrationid,     
                          @Referenceno,     
        --'Candidate00' + @value,    
                         @canid,     
                         '',     
                         @firstname,     
                         @middlename,     
                         @lastname,     
                         @dateofbirth,     
                         @age,     
                         @gender,     
                         @maritalstatus,     
                         @nationality,     
                         @Religion,     
                         @countrycode,     
                         @mobile,     
                         @voterid,     
                         'Edit',    
       'No',     
                         Getdate() )     
    
       delete from [dbo].[trecruitmanualtraker] where mailid=@mailid    
    
   end       
       
        else    
  begin    
            INSERT INTO [dbo].[trecruitcanbasicdtls]     
                        (registrationid,     
                         registrationnumber,     
                         candidateid,     
                         aplicationdate,     
                         firstname,     
                         middlename,     
                         lastname,     
                         dateofbirth,     
                         age,     
                         gender,     
                         maritalstatus,     
                         nationality,     
                         religion,     
                         countrycode,     
                         mobile,     
                         voterid,     
                         applicationstatus,     
                         createdtime)     
            VALUES      (next value FOR seregistrationid,     
                         'Candidate00' + @value,     
                         @canid,     
                         '',     
                         @firstname,     
                         @middlename,     
                         @lastname,     
                         @dateofbirth,     
                         @age,     
                         @gender,     
                         @maritalstatus,     
                         @nationality,     
                         @Religion,     
                         @countrycode,     
                         @mobile,     
                         @voterid,     
                         'Edit',     
                         Getdate() )     
       end    
    
    
IF @paddtype = 'P'     
              BEGIN     
                  INSERT INTO [dbo].[trecruitcanaddress]     
                              (candidateid,     
                               addresstype,     
                               addressline,     
                               saddressline,     
                               villagecity,     
                               postoffice,     
                               pincode,     
                               state,     
                               district,
							   CountryId)     
                  VALUES      (@canid,     
                               'P',     
                               @paddressline,     
                               @psaddressline,     
                               @pvillagecity,     
                               @ppostoffice,     
                               @ppincode,     
                               case when @pstate=0 then 36    
          else @pstate end,     
          case when @pdistrict=0 then 710    
          else @pdistrict end,@PCountry    
                                )     
              END     
    
            IF @caddtype = 'C'     
              BEGIN     
                  INSERT INTO [dbo].[trecruitcanaddress]     
                              (candidateid,     
                               addresstype,     
                               addressline,     
                               saddressline,     
                               villagecity,     
                               postoffice,     
                               pincode,     
                               state,     
                               district,
							   CountryId)     
                  VALUES      (@canid,     
                               'C',     
                               @caddressline,     
                               @csaddressline,     
                               @cvillagecity,     
                               @cpostoffice,     
                               @cpincode,     
                               case when @pstate=0 then 36    
          else @pstate end,     
          case when @pdistrict=0 then 710    
          else @pdistrict end,@CurCountry )     
              END     
-----------------Start save other post-----------------    
     if @otpostname <>''    
           begin    
  Select @otpostname=Replace(@otpostname,'&','and')     
  insert into  [dbo].[trecruitotherpost]    
      ([candidateid]    
      ,[otpostname]          
      ,[createdtime])    
   values    
   (    
   @canid,    
   @otpostname,    
   getdate()    
   )    
   end    
        INSERT INTO trecruituploadimage     
                        (NAME,     
                         contenttype,     
                         data,     
                         candidateid)     
            VALUES      (@iName,     
                         @iContentType,     
                         @iData,     
                         @canid)     
    
            INSERT INTO trecruituploadresume     
                        (NAME,     
                         contenttype,     
                         resumefile,     
                         candidateid)     
            VALUES      (@rName,     
                         @rContentType,     
                         @rData,     
                         @canid)    
      
      
     
  ----------------end save other post---------------------    
            SET @status =' Data Inserted Successfully'     
        END     
  END 
GO



/* Functional group: 05_APPLICATION_WORKFLOW_AND_TRACKER; referenced grouped tables: trecruittraker */
/****** Object:  StoredProcedure [dbo].[proc_UpdateCandidateStatus]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[proc_UpdateCandidateStatus]  
(  
    @RegistrationNo NVARCHAR(50),  
    @StatusId INT  
)  
AS  
  
BEGIN  
    SET NOCOUNT ON;  
   
    DECLARE @Departmentdivision NVARCHAR(MAX),    
            @PostId BIGINT,    
            @Source NVARCHAR(MAX),    
            @Postname NVARCHAR(MAX),    
            @Locid BIGINT,    
            @CandidateID BIGINT,    
            @Candidatename NVARCHAR(MAX);    
  
 SELECT     
        @Departmentdivision = deptdivision,    
        @PostId = postid,    
        @Source = referredus,    
        @Postname = postname,    
        @Locid = locid,    
        @CandidateID = candidateid,    
        @Candidatename = CandidateName    
    FROM vw_recruittracker    
    WHERE registrationnumber = @RegistrationNo;    
    
   
  
  
 --if exists (select MAX(value) from #A where id = 2)  
 --Select * from tRecruitTraker  
 if exists (SELECT 1 FROM dbo.tRecruitTraker D  
    WHERE D.Referenceno = @RegistrationNo)  
 BEGIN  
  UPDATE D  
  SET D.CanNotifyStatusID = @StatusId  
     -- ,D.ModifiedDate = GETDATE()  
  FROM dbo.tRecruitTraker D  
  WHERE D.Referenceno = @RegistrationNo;  
 END  
   ELSE  
     BEGIN  
     INSERT INTO trecruittraker (Referenceno, Departmentdivision, locid, candidateid, source, candidatename, postid, Postname,CanNotifyStatusID)    
        VALUES (@RegistrationNo, @Departmentdivision, @Locid, @CandidateID, @Source, @Candidatename, @PostId, @Postname,@StatusId);    
  END  
      
END;  
GO



/* Functional group: 05_APPLICATION_WORKFLOW_AND_TRACKER; referenced grouped tables: trecruitcanbasicdtls, trecruitmanualtraker, trecruittraker, trecruittrakeruploadfilefinal, trecruittrakeruploadfileone, trecruittrakeruploadfilethree, trecruittrakeruploadfiletwo */
/****** Object:  StoredProcedure [dbo].[procallcandidatestracker]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 CREATE procedure [dbo].[procallcandidatestracker]        
 as       
       
 begin       
 Declare @background varchar(10)      
      
 if(@background=NULL)      
 begin      
 set @background='SELECT'      
 end      
       
      
      
 SELECT         
          rs.[registrationnumber],CASE         
                     WHEN A.backgroundcheck  IS NULL THEN 'SELECT'         
                              
                   END                                               backgroundcheck  ,      
          
                   rs.[aplicationdate],         
                   rs.[username],         
                   rs.[candidateid],         
                   rs.[candidatename],         
                   rs.[resumefile],         
                   rs.[applicationstatus],         
                   rs.[postname],         
                   rs.[postid],         
                   rs.[locid],         
                   rs.[location],         
                   rs.[deptdivision],         
                   rs.[referredus],
				   rs.[ReferredOthertext],
                   rt.[trakerid],         
                   rt.[referenceno],         
                   rt.[departmentdivision],         
                   rt.[departmentdivisonname],         
                   rt.[postid],         
                   rt.[postname],         
                   rt.[locid],         
                   rt.[headq],         
                   rt.[candidateid],         
                   rt.[candidatename],         
                   rt.[source],         
                   CONVERT(VARCHAR(10), rt.[startdate], 103)         AS         
                   [STARTDATE],         
                   rt.[cvselected],         
       'No'[manualupdate],        
                   CONVERT(VARCHAR(10), rt.[roneinterviewdate], 103) AS         
                   [roneinterviewdate],         
                   rt.[roneinterviewernameone],         
                   rt.[roneinterviewernametwo],         
                   rt.[roneselect],  
         CONVERT(VARCHAR(10), rt.[roneinterviewenddate], 103) AS         
                   [roneinterviewenddate],     
                   rt.[rtwointerviewdate],         
                   rt.[rtwointerviewernameone],         
                   rt.[rtwointerviewernametwo],         
                   rt.[rtwoselect],    
       rt.[rtwointerviewenddate],  
                   rt.[rthreeinterviewdate],         
                   rt.[rthreeinterviewernameone],         
                   rt.[rthreeinterviewernametwo],         
                   rt.[rthreeselect],    
       rt.[rthreeinterviewenddate],     
                   rt.[frinterviewdate],         
                   rt.[frinterviewernameone],         
                   rt.[frinterviewernametwo],         
                   rt.[frselect],    
       rt.[Frinterviewenddate],     
                   rt.[doo],         
                   rt.[doj],         
                   rt.[empcode],        
       rt.CompletionStatus,         
       rt.timetaken,        
                   rt.[remarks],                           
                   rt.[createdby],         
                  -- rt.[createdtime],         
                   rt.[modifiedby],         
                   rt.[modifiedtime],         
                   ro.[fileid],         
                   ro.[candidateid],         
                   ro.[fname],         
                   ro.[fcontenttype],         
                   ro.[fresumefile],         
                   CASE         
                     WHEN ro.[fresumefile] IS NULL THEN 'False'         
                     ELSE 'True'         
                   END                                               ronerone,         
                   ro.[sname],         
                   ro.[scontenttype],         
                   ro.[sresumefile],         
                   CASE         
                     WHEN ro.[sresumefile] IS NULL THEN 'False'         
                     ELSE 'True'         
                   END                                       ronertwo,         
                   rtw.[fileid],         
                   rtw.[candidateid],         
                   rtw.[fname],         
                   rtw.[fcontenttype],         
                   rtw.[fresumefile],         
                   CASE         
                     WHEN rtw.[fresumefile] IS NULL THEN 'False'         
 ELSE 'True'         
                   END                                               rtworone,         
                   rtw.[sname],         
                   rtw.[scontenttype],         
      rtw.[sresumefile],         
                   CASE         
                     WHEN rtw.[sresumefile] IS NULL THEN 'False'         
                     ELSE 'True'         
                   END                                               rtwortwo,         
                   rth.[fileid],         
                   rth.[candidateid],         
                   rth.[fname],         
                   rth.[fcontenttype],         
                   rth.[fresumefile],         
                   CASE         
                     WHEN rth.[fresumefile] IS NULL THEN 'False'         
                     ELSE 'True'         
                   END                                               rthworone,         
                   rth.[sname],         
                   rth.[scontenttype],         
                   rth.[sresumefile],         
                   CASE         
                     WHEN rth.[sresumefile] IS NULL THEN 'False'         
                     ELSE 'True'         
                   END                                               rthwortwo,         
                   rf.[fileid],         
                   rf.[candidateid],         
                   rf.[fname],         
                   rf.[fcontenttype],         
                   rf.[fresumefile],         
                   CASE         
                     WHEN rf.[fresumefile] IS NULL THEN 'False'         
                     ELSE 'True'         
                   END                                               rfworone,         
                   rf.[sname],         
                   rf.[scontenttype],         
                   rf.[sresumefile],         
                   CASE         
                     WHEN rf.[sresumefile] IS NULL THEN 'False'         
                     ELSE 'True'         
                   END          
       rfwortwo ,        
       rs.createdtime                                                     
            FROM   [vw_recruittracker] rs         
                   LEFT JOIN [dbo].[trecruittraker] rt         
                          ON rs.[registrationnumber] = rt.referenceno         
                             AND rs.[postname] = rt.[postname]         
                   LEFT JOIN [dbo].[trecruittrakeruploadfileone] ro         
                          ON rs.[postid] = ro.postid         
                             AND rs.locid = ro.locid         
                             AND rs.candidateid = ro.candidateid         
                   LEFT JOIN [dbo].[trecruittrakeruploadfiletwo] rtw         
                          ON rs.[postid] = rtw.postid         
                             AND rs.locid = rtw.locid         
                             AND rs.candidateid = rtw.candidateid         
                   LEFT JOIN [dbo].[trecruittrakeruploadfilethree] rth         
                          ON rs.[postid] = rth.postid         
                             AND rs.locid = rth.locid         
                             AND rs.candidateid = rth.candidateid         
                   LEFT JOIN [dbo].[trecruittrakeruploadfilefinal] rf         
                          ON rs.[postid] = rf.postid         
                             AND rs.locid = rf.locid         
                             AND rs.candidateid = rf.candidateid      
     LEFT JOIN  trecruitcanbasicdtls A      
     ON A.candidateid=rs.candidateid      
        
         --WHERE  rs.[deptname] = @department         
         --                AND rs.[postname] = @postname         
         --               AND rs.[applicationstatus] = @applicationstatus         
       union all        
        SELECT         
           [Referenceno],CASE         
                     WHEN backgroundcheck  IS NULL THEN 'SELECT'         
                              
                   END                                               backgroundcheck  ,      
                   convert(varchar,[createdtime],103)[aplicationdate],         
            ''[username],         
                   [candidateid],         
                   [candidatename],         
                   [cvupload] [resumefile],         
                   [applicationstatus],         
                   [Postname],         
                   [postid],         
                   [locid],         
                   ''[location],         
                   [Departmentdivision],         
                   [source][referredus],
				  '' [ReferredOthertext],
                   ''[trakerid],         
                   ''[referenceno],         
                   ''[departmentdivision],         
                   ''[departmentdivisonname],         
                   ''[postid],         
                   ''[postname],         
                   ''[locid],         
                   [HeadQ],         
                   ''[candidateid],         
                   ''[candidatename],         
                   [source],                           
                   ''[STARTDATE],         
                    [cvselected],        
     [manualupdate],                           
                   ''[roneinterviewdate],         
                   ''[roneinterviewernameone],         
                   ''[roneinterviewernametwo],         
                   ''[roneselect],   
       ''[roneinterviewenddate],  
                   ''[rtwointerviewdate],         
                   ''[rtwointerviewernameone],         
                   ''[rtwointerviewernametwo],         
                   ''[rtwoselect],  
       ''[rtwointerviewenddate],  
                   ''[rthreeinterviewdate],         
                   ''[rthreeinterviewernameone],         
                   ''[rthreeinterviewernametwo],         
                   ''[rthreeselect],  
       ''[rthreeinterviewenddate],  
                   ''[frinterviewdate],         
                   ''[frinterviewernameone],         
                   ''[frinterviewernametwo],         
                   ''[frselect],  
       ''[Frinterviewenddate],  
                   ''[doo],         
                   ''[doj],         
                   ''[empcode],        
       ''CompletionStatus,         
       ''timetaken,        
                   ''[remarks],                           
                   ''[createdby],         
                  -- ''[createdtime],         
                   ''[modifiedby],         
                   ''[modifiedtime],         
                   ''[fileid],         
                   ''[candidateid],         
                   ''[fname],         
                   ''[fcontenttype],         
                   ''[fresumefile],         
                   'False' ronerone,         
                   ''[sname],         
                   ''[scontenttype],         
                   ''[sresumefile],         
                   'False' ronertwo,         
                  ''[fileid],         
                  ''[candidateid],         
                  ''[fname],         
                  ''[fcontenttype],         
                  ''[fresumefile],         
                  'False'rtworone,         
                  ''[sname],         
                  ''[scontenttype],         
                  ''[sresumefile],         
                   'False'rtwortwo,         
                  ''[fileid],         
                  ''[candidateid],         
                  ''[fname],         
                  ''[fcontenttype],         
                  ''[fresumefile],         
          'False'rthworone,         
                  ''[sname],         
                  ''[scontenttype],         
                  ''[sresumefile],         
                  'False'rthwortwo,         
                   ''[fileid],         
                   ''[candidateid],         
                   ''[fname],         
                   ''[fcontenttype],         
                   ''[fresumefile],         
                   'False'rfworone,         
                   ''[sname],         
                   ''[scontenttype],         
                   ''[sresumefile],         
                   'False'rfwortwo,        
       createdtime         
            FROM   [dbo].[trecruitmanualtraker]        
   order by createdtime desc        
           
   end 
GO



