                  INSERT INTO [dbo].[trecruitcanaddress] 
                              (candidateid, 
                               addresstype, 
                               addressline, 
                               saddressline, 
                               villagecity, 
                               postoffice, 
                               pincode, 
                               state, 
                               district) 
                  VALUES      (@canid, 
                               'P', 
                               @paddressline, 
                               @psaddressline, 
                               @pvillagecity, 
                               @ppostoffice, 
                               @ppincode, 
                               case when @pstate=0 then 36
							   else @pstate end, 
							   case when @pdistrict=0 then 710
							   else @pdistrict end
                                ) 
              END 

            IF @caddtype = 'C' 
              BEGIN 
                  INSERT INTO [dbo].[trecruitcanaddress] 
                              (candidateid, 
                               addresstype, 
                               addressline, 
                               saddressline, 
                               villagecity, 
                               postoffice, 
                               pincode, 
                               state, 
                               district) 
                  VALUES      (@canid, 
                               'C', 
                               @caddressline, 
                               @csaddressline, 
                               @cvillagecity, 
                               @cpostoffice, 
                               @cpincode, 
                               case when @pstate=0 then 36
							   else @pstate end, 
							   case when @pdistrict=0 then 710
							   else @pdistrict end ) 
              END 
-----------------Start save other post-----------------
			  if @otpostname <>''
           begin
		Select @otpostname=Replace(@otpostname,'&','and') 
		insert into  [dbo].[trecruitotherpost]
      ([candidateid]
      ,[otpostname]      
      ,[createdtime])
	  values
	  (
	  @canid,
	  @otpostname,
	  getdate()
	  )
	  end
	       INSERT INTO trecruituploadimage 
                        (NAME, 
                         contenttype, 
                         data, 
                         candidateid) 
            VALUES      (@iName, 
                         @iContentType, 
                         @iData, 
                         @canid) 

            INSERT INTO trecruituploadresume 
                        (NAME, 
                         contenttype, 
                         resumefile, 
                         candidateid) 
            VALUES      (@rName, 
                         @rContentType, 
                         @rData, 
                         @canid)
	 
  
 
  ----------------end save other post---------------------
            SET @status =' Data Inserted Successfully' 
        END 
  END 
GO



