GO
SET QUOTED_IDENTIFIER ON
GO
/****** Script for SelectTopNRows command from SSMS  ******/
CREATE procedure [dbo].[proccanresume]
@registrationno varchar(100)
as

begin
declare @candidateid int

select @candidateid=candidateid from [dbo].[trecruitcanbasicdtls]
where registrationnumber=@registrationno


if exists (select candidateid from [dbo].[trecruituploadresume] where candidateid=@candidateid)
begin
SELECT Name,ContentType,[resumefile]
      
  FROM [dbo].[trecruituploadresume] a,[dbo].[trecruitcanbasicdtls] b
  where a.candidateid=b.candidateid
 and b.registrationnumber=@registrationno
 end 

 else

 SELECT [cvname] Name,[cvContentType] ContentType,[cvupload] [resumefile]
      
  FROM [dbo].[trecruitmanualtraker] a
  where [Referenceno]=@registrationno

 end
  
GO



