            FROM   [dbo].[trecruittrakeruploadfileone] 
            WHERE  candidateid = @candidateid 
                   AND postid = @postid 
                   AND locid = @locid 
        END 

      IF @Action = 'Remarks1_R2' 
        BEGIN 
            SELECT [fname], 
                   [fcontenttype], 
                   [fresumefile] 
            FROM   [dbo].[trecruittrakeruploadfiletwo] 
            WHERE  candidateid = @candidateid 
                   AND postid = @postid 
                   AND locid = @locid 
        END 

      IF @Action = 'Remarks2_R2' 
        BEGIN 
            SELECT [sname], 
                   [scontenttype], 
                   [sresumefile] 
            FROM   [dbo].[trecruittrakeruploadfiletwo] 
            WHERE  candidateid = @candidateid 
                   AND postid = @postid 
                   AND locid = @locid 
        END 

      IF @Action = 'Remarks3_R1' 
        BEGIN 
            SELECT [fname], 
                   [fcontenttype], 
                   [fresumefile] 
            FROM   [dbo].[trecruittrakeruploadfilethree] 
            WHERE  candidateid = @candidateid 
                   AND postid = @postid 
                   AND locid = @locid 
        END 

      IF @Action = 'Remarks3_R2' 
        BEGIN 
            SELECT [sname], 
                   [scontenttype], 
                   [sresumefile] 
            FROM   [dbo].[trecruittrakeruploadfilethree] 
            WHERE  candidateid = @candidateid 
                   AND postid = @postid 
                   AND locid = @locid 
        END 

      IF @Action = 'Remarksf_R1' 
        BEGIN 
            SELECT [fname], 
                   [fcontenttype], 
                   [fresumefile] 
            FROM   [dbo].[trecruittrakeruploadfilefinal] 
            WHERE  candidateid = @candidateid 
                   AND postid = @postid 
                   AND locid = @locid 
        END 

      IF @Action = 'Remarksf_R2' 
        BEGIN 
            SELECT [sname], 
                   [scontenttype], 
                   [sresumefile] 
            FROM   [dbo].[trecruittrakeruploadfilefinal] 
            WHERE  candidateid = @candidateid 
                   AND postid = @postid 
                   AND locid = @locid 
        END 
  END 
