/* Functional group: 05_APPLICATION_WORKFLOW_AND_TRACKER; referenced grouped tables: trecruitcanbasicdtls, trecruitcandidatesignup, trecruitotherpost, trecruitpostlocationmap, trecruittraker */
/****** Object:  StoredProcedure [dbo].[procgetapplicationstatus]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[procgetapplicationstatus] 
@username VARCHAR(1000),      
@postid varchar(max)=Null,      
@status   VARCHAR(10)= NULL output ,      
@TypeFresher varchar(max) =null output,      
@TypeExperienced varchar(max)=null output,      
@TypeSalesExperienced varchar(max)=null output      
AS           
  BEGIN           
      DECLARE @canid INT           
      DECLARE @canotid INT           
          
      
 --Saikat       
 select @TypeFresher=[TypeFresher],@TypeExperienced=[TypeExperienced],@TypeSalesExperienced=[TypeSalesExperienced] from [trecruitpostlocationmap] where postid=@postid      
      
      
      
      
      SELECT @canid = [candidateid]           
      FROM   [dbo].[trecruitcandidatesignup]           
      WHERE  [username] = @username           
          
      SELECT @canotid = candidateid           
      FROM   trecruitotherpost           
      WHERE  candidateid = @canid           
          
      IF @canotid IS NULL           
        BEGIN           
            IF NOT EXISTS(SELECT candidateid           
                          FROM   [dbo].[trecruitcanbasicdtls]           
                          WHERE  candidateid = @canid)           
              BEGIN           
                  SET @status=1           
              END           
            ELSE IF EXISTS(SELECT candidateid           
                      FROM   [dbo].[trecruitcanbasicdtls]           
                      WHERE  candidateid = @canid           
                             AND [applicationstatus] not IN ('NEW','SUBMITTED'))           
              BEGIN           
                  SET @status=2           
              END           
            ELSE           
              BEGIN           
                  SELECT CONVERT(VARCHAR(10), [aplicationdate], 103)         AS           
                         [aplicationdate],           
                         [firstname] + ' ' + [middlename] + ' ' + [lastname]           
                         NAME,           
                         position,discrolallow,conflictallow,iqallow,eqallow,docsubmissionallow,bigfiveallow,firoballow,myersbriggsallow,rotterlocusofcontrolallow,personalitystyleinventoryallow          
                  FROM   [dbo].[trecruitcanbasicdtls] bas                                 
    Left		Join [vw_canapppost] po  on  bas.candidateid = po.candidateid          
                  WHERE  bas.candidateid = @canid           
                         AND [applicationstatus] IN ('NEW','SUBMITTED')          
                 
                  SET @status=3           
              END           
        END           
          
      IF @canotid <> ''           
        BEGIN           
            IF NOT EXISTS(SELECT candidateid           
                          FROM   [dbo].[trecruitcanbasicdtls]           
                          WHERE  candidateid = @canid)           
              BEGIN           
                  SET @status=1           
              END           
            ELSE IF EXISTS(SELECT candidateid           
                      FROM   [dbo].[trecruitcanbasicdtls]           
                      WHERE  candidateid = @canid           
                             AND [applicationstatus] not IN ('NEW','SUBMITTED'))           
              BEGIN           
                  SET @status=2           
              END           
            ELSE           
              BEGIN           
                  SELECT CONVERT(VARCHAR(10), [aplicationdate], 103)         AS           
                         [aplicationdate],           
                         [firstname] + ' ' + [middlename] + ' ' + [lastname]           
                         NAME,           
                         otpostname           
                         position,discrolallow,conflictallow,iqallow,eqallow,docsubmissionallow,bigfiveallow,firoballow,myersbriggsallow,rotterlocusofcontrolallow,personalitystyleinventoryallow     
                  FROM   [dbo].[trecruitcanbasicdtls] bas         
      Left Join trecruitotherpost otp     on bas.candidateid = otp.candidateid           
      --left outer join [trecruittraker] tr          
      -- on bas.registrationnumber =tr.referenceno,          
                  WHERE  bas.candidateid = @canid           
                  AND [applicationstatus] IN ('NEW','SUBMITTED')           
                  SET @status=3           
              END           
        END           
  END 
GO



