              BEGIN   
                  SET @status=1   
              END   
            ELSE IF EXISTS(SELECT candidateid   
                      FROM   [dbo].[trecruitcanbasicdtls]   
                      WHERE  candidateid = @canid   
                             AND [applicationstatus] <> 'New')   
              BEGIN   
                  SET @status=2   
              END   
            ELSE   
              BEGIN   
                  SELECT CONVERT(VARCHAR(10), [aplicationdate], 103)         AS   
                         [aplicationdate],   
                         [firstname] + ' ' + [middlename] + ' ' + [lastname]   
