                  FROM   [dbo].[trecruitcanbasicdtls] bas,  
      --left outer join [trecruittraker] tr  
      -- on bas.registrationnumber =tr.referenceno,   
                         trecruitotherpost otp   
                  WHERE  bas.candidateid = @canid   
                         AND [applicationstatus] = 'NEW'   
                         AND bas.candidateid = otp.candidateid   
  
                  SET @status=3   
              END   
        END   
  END   
