/* Functional group: 05_APPLICATION_WORKFLOW_AND_TRACKER; referenced grouped tables: trecruitcanbasicdtls, trecruitcandidatesignup, tRecruitcanotherdtls, trecruituploadresume */
/****** Object:  StoredProcedure [dbo].[prochrappstatus]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[prochrappstatus] @department        VARCHAR(100),     
                                        @postname          VARCHAR(100),     
                                        @applicationstatus VARCHAR(100),     
                                        @status            VARCHAR(100)=NULL     
output     
AS     
  BEGIN     
      IF @department = ''     
          OR @postname = ''     
          OR @applicationstatus = ''     
        BEGIN     
            SET @status='Please Select Data for search'     
    
            RETURN     
        END     
      ELSE     
        BEGIN     
            SELECT bac.[registrationnumber],  
       convert(varchar(10),bac.aplicationdate,103) as aplicationdate,    
                   po.[username],     
                   Upper(bac.[firstname]) + ' ' + Upper(bac.[middlename]) + ' '     
                   + Upper(bac.[lastname]) CandidateName,     
                   rs.resumefile,     
                   bac.[applicationstatus],     
                   po.[postname],     
                   po.deptname ,    
				   ot.referredus    
            FROM   [dbo].[trecruitcanbasicdtls] bac,     
                   [dbo].[vw_apppost] po,     
                   [trecruitcandidatesignup] su,     
                   [dbo].[trecruituploadresume] rs ,    
                   [dbo].[tRecruitcanotherdtls]ot    
            WHERE  su.username = po.username     
                   AND bac.candidateid = su.candidateid     
                   AND rs.candidateid = bac.candidateid     
                   AND bac.[applicationstatus] IN ( 'NEW','SUBMITTED')     
       and bac.candidateid=ot.candidateid    
                   AND po.deptname = @department     
                   AND po.[postname] = @postname     
       order by bac.aplicationdate     
        END                     
  END 
GO



/* Functional group: 05_APPLICATION_WORKFLOW_AND_TRACKER; referenced grouped tables: trecruitcanbasicdtls, trecruitcandidatesignup, tRecruitcanotherdtls, trecruituploadresume */
/****** Object:  StoredProcedure [dbo].[prochrappstatus_Mobile]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
/****** Script for SelectTopNRows command from SSMS  ******/   
-- prochrappstatus_Mobile 'MANAGEMENT INFORMATION SYSTEM', 'SYSTEMS INTERN - MANAGEMENT INFORMATION SYSTEM - KOLKATA', 'New', 1, 7
CREATE PROCEDURE [dbo].[prochrappstatus_Mobile] @department        VARCHAR(100),   
                                        @postname          VARCHAR(100),   
                                        @applicationstatus VARCHAR(100),
										@PageIndex INT = NULL, -- Ensure PageIndex starts at 1  
										@PageSize INT = NULL, -- Default page size
										@status  VARCHAR(100)=NULL,
										@RecordCount INT = NULL OUTPUT  
   
AS   
  BEGIN   
  SET NOCOUNT ON; 

      IF @department = ''   
          OR @postname = ''   
          OR @applicationstatus = ''   
        BEGIN   
            SET @status='Please Select Data for search'   
  
            RETURN   
        END   
      ELSE   
        BEGIN   
		SELECT
			ROW_NUMBER() OVER (ORDER BY bac.[registrationnumber] DESC) AS RowNumber,
            bac.[registrationnumber],   
            
			convert(varchar(10),bac.aplicationdate,103) as aplicationdate,  
                   po.[username],   
                   bac.[firstname] + ' ' + bac.[middlename] + ' '   
                   + bac.[lastname] CandidateName,   
                   --rs.resumefile,   
                   bac.[applicationstatus],   
                   po.[postname],   
                   po.deptname ,  
				   ot.referredus  
		    INTO #Results
            FROM   [dbo].[trecruitcanbasicdtls] bac,   
                   [dbo].[vw_apppost] po,   
                   [trecruitcandidatesignup] su,   
                   [dbo].[trecruituploadresume] rs ,  
                   [dbo].[tRecruitcanotherdtls]ot  
            WHERE  su.username = po.username   
                   AND bac.candidateid = su.candidateid   
                   AND rs.candidateid = bac.candidateid   
                   AND bac.[applicationstatus] IN ( 'NEW' )   
       and bac.candidateid=ot.candidateid  
                   AND po.deptname = @department   
                   AND po.[postname] = @postname   
       order by bac.aplicationdate   

	   -- Get the total record count  
    SELECT @RecordCount = COUNT(*) FROM #Results;  
  
    -- Select paginated results  
    SELECT *  
    FROM #Results  
    WHERE RowNumber BETWEEN ((@PageIndex - 1) * @PageSize + 1) AND (@PageIndex * @PageSize);
  
    DROP TABLE #Results;
        END                   
  END 
GO



/* Functional group: 05_APPLICATION_WORKFLOW_AND_TRACKER; referenced grouped tables: trecruitmanualtraker, trecruittraker, trecruittrakeruploadfilefinal, trecruittrakeruploadfileone, trecruittrakeruploadfilethree, trecruittrakeruploadfiletwo */
/****** Object:  StoredProcedure [dbo].[prochrselecttraker]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

/****** Script for SelectTopNRows command from SSMS  ******/ 
CREATE PROCEDURE [dbo].[prochrselecttraker] @department        VARCHAR(100), 
                                           @postname          VARCHAR(100), 
                                           @applicationstatus VARCHAR(100), 
                                           @status            VARCHAR(100) = 
NULL output 
WITH EXEC AS caller 
AS 
  BEGIN 
      IF @department = '' 
          OR @postname = '' 
          OR @applicationstatus = '' 
        BEGIN 
            SET @status='Please Select Data for search' 

            RETURN 
        END 
      ELSE 
        BEGIN 
            /****** Script for SelectTopNRows command from SSMS  ******/ 
          SELECT 
			       rs.[registrationnumber], 
                   rs.[aplicationdate], 
                   rs.[username], 
                   rs.[candidateid], 
                   rs.[candidatename], 
                   rs.[resumefile], 
                   rs.[applicationstatus], 
                   rs.[postname], 
                   rs.[postid], 
                   rs.[locid], 
                   rs.[location], 
                   rs.[deptdivision], 
                   rs.[referredus], 
                   rt.[trakerid], 
                   rt.[referenceno], 
                   rt.[departmentdivision], 
                   rt.[departmentdivisonname], 
                   rt.[postid], 
                   rt.[postname], 
                   rt.[locid], 
                   rt.[headq], 
                   rt.[candidateid], 
                   rt.[candidatename], 
                   rt.[source], 
                   CONVERT(VARCHAR(10), rt.[startdate], 103)         AS 
                   [STARTDATE], 
                   rt.[cvselected], 
				   'No'[manualupdate],
                   CONVERT(VARCHAR(10), rt.[roneinterviewdate], 103) AS 
                   [roneinterviewdate], 
                   rt.[roneinterviewernameone], 
                   rt.[roneinterviewernametwo], 
                   rt.[roneselect], 
                   rt.[rtwointerviewdate], 
                   rt.[rtwointerviewernameone], 
                   rt.[rtwointerviewernametwo], 
                   rt.[rtwoselect], 
                   rt.[rthreeinterviewdate], 
                   rt.[rthreeinterviewernameone], 
                   rt.[rthreeinterviewernametwo], 
                   rt.[rthreeselect], 
                   rt.[frinterviewdate], 
                   rt.[frinterviewernameone], 
                   rt.[frinterviewernametwo], 
                   rt.[frselect], 
                   rt.[doo], 
                   rt.[doj], 
                   rt.[empcode],
				   rt.CompletionStatus, 
				   rt.timetaken,
                   rt.[remarks],                   
                   rt.[createdby], 
                   rt.[createdtime], 
                   rt.[modifiedby], 
                   rt.[modifiedtime], 
                   ro.[fileid], 
                   ro.[candidateid], 
                   ro.[fname], 
                   ro.[fcontenttype], 
                   ro.[fresumefile], 
                   CASE 
                     WHEN ro.[fresumefile] IS NULL THEN 'False' 
                     ELSE 'True' 
                   END                                               ronerone, 
                   ro.[sname], 
                   ro.[scontenttype], 
                   ro.[sresumefile], 
                   CASE 
                     WHEN ro.[sresumefile] IS NULL THEN 'False' 
                     ELSE 'True' 
                   END                                               ronertwo, 
                   rtw.[fileid], 
                   rtw.[candidateid], 
                   rtw.[fname], 
                   rtw.[fcontenttype], 
                   rtw.[fresumefile], 
                   CASE 
                     WHEN rtw.[fresumefile] IS NULL THEN 'False' 
                     ELSE 'True' 
                   END                                               rtworone, 
                   rtw.[sname], 
                   rtw.[scontenttype], 
                   rtw.[sresumefile], 
                   CASE 
                     WHEN rtw.[sresumefile] IS NULL THEN 'False' 
                     ELSE 'True' 
                   END                                               rtwortwo, 
                   rth.[fileid], 
                   rth.[candidateid], 
                   rth.[fname], 
                   rth.[fcontenttype], 
                   rth.[fresumefile], 
                   CASE 
                     WHEN rth.[fresumefile] IS NULL THEN 'False' 
                     ELSE 'True' 
                   END                                               rthworone, 
                   rth.[sname], 
                   rth.[scontenttype], 
                   rth.[sresumefile], 
                   CASE 
                     WHEN rth.[sresumefile] IS NULL THEN 'False' 
                     ELSE 'True' 
                   END                                               rthwortwo, 
                   rf.[fileid], 
                   rf.[candidateid], 
                   rf.[fname], 
                   rf.[fcontenttype], 
                   rf.[fresumefile], 
                   CASE 
                     WHEN rf.[fresumefile] IS NULL THEN 'False' 
                     ELSE 'True' 
                   END                                               rfworone, 
                   rf.[sname], 
                   rf.[scontenttype], 
                   rf.[sresumefile], 
                   CASE 
                     WHEN rf.[sresumefile] IS NULL THEN 'False' 
                     ELSE 'True' 
                   END                                               rfwortwo 
            FROM   [vw_recruittracker] rs 
                   LEFT JOIN [dbo].[trecruittraker] rt 
                          ON rs.[registrationnumber] = rt.referenceno 
                             AND rs.[postname] = rt.[postname] 
                   LEFT JOIN [dbo].[trecruittrakeruploadfileone] ro 
                          ON rs.[postid] = ro.postid 
                             AND rs.locid = ro.locid 
                             AND rs.candidateid = ro.candidateid 
                   LEFT JOIN [dbo].[trecruittrakeruploadfiletwo] rtw 
                          ON rs.[postid] = rtw.postid 
                             AND rs.locid = rtw.locid 
                             AND rs.candidateid = rtw.candidateid 
                   LEFT JOIN [dbo].[trecruittrakeruploadfilethree] rth 
                          ON rs.[postid] = rth.postid 
                             AND rs.locid = rth.locid 
                             AND rs.candidateid = rth.candidateid 
                   LEFT JOIN [dbo].[trecruittrakeruploadfilefinal] rf 
                          ON rs.[postid] = rf.postid 
                             AND rs.locid = rf.locid 
                             AND rs.candidateid = rf.candidateid 

							  WHERE  rs.[deptname] = @department 
                         AND rs.[postname] = @postname 
                        AND rs.[applicationstatus] = @applicationstatus 
						 union 
