                         [remarks],
						 timetaken) 
            VALUES      ( upper(@Referenceno), 
                          upper(@Departmentdivision), 
                          upper(@Postname), 
                          upper(@HeadQ), 
                          upper(@candidatename), 
                          upper(@source),                           
						  CONVERT(VARCHAR, @STARTDATE, 103), 
						  @cvname,
                          @cvContentType,
                          @cvupload, 
                          @CVSelected,                          
						  CONVERT(VARCHAR, @roneinterviewdate, 103),
                          upper(@roneinterviewernameone), 
						  @roneintervieweroneremarksname,
                          @roneintervieweroneremarkscontenttype,
                          @roneintervieweroneremarks, 
                          upper(@roneinterviewernametwo),
						  @roneinterviewertworemarksname ,
                          @roneinterviewertworemarkscontenttype,
                          @roneinterviewertworemarks, 
                          @roneselect,                         
						  CONVERT(VARCHAR, @rtwointerviewdate, 103), 
                          upper(@rtwointerviewernameone), 
						  @rtwointervieweroneremarksname ,
                          @rtwointervieweroneremarkscontenttype,
                          @rtwointervieweroneremarks, 
                          upper(@rtwointerviewernametwo),
						  @rtwointerviewertworemarksname,
                          @rtwointerviewertworemarkscontenttype,
                          @rtwointerviewertworemarks, 
                          @rtwoselect,                           
						  CONVERT(VARCHAR, @rthreeinterviewdate, 103), 
                          upper(@rthreeinterviewernameone), 
						  @rthreeintervieweroneremarksname,
                          @rthreeintervieweroneremarkscontenttype,
                          @rthreeintervieweroneremarks,
                          upper(@rthreeinterviewernametwo),
                          @rthreeinterviewertworemarksname,
                          @rthreeinterviewertworemarkscontenttype,
                          @rthreeinterviewertworemarks,
                          @rthreeselect,                          
						  CONVERT(VARCHAR, @Frinterviewdate, 103),
                          upper(@Frinterviewernameone), 
						  @rfinalintervieweroneremarksname,
                          @rfinalintervieweroneremarkscontenttype,
                          @rfinalintervieweroneremarks,
                          upper(@Frinterviewernametwo), 
						  @rfinalinterviewertworemarksname,
                          @rfinalinterviewertworemarkscontenttype,
                          @rfinalinterviewertworemarks, 
                          @Frselect,                         
						  CONVERT(VARCHAR, @DOO, 103),                         
						  CONVERT(VARCHAR, @DOJ, 103),
                          upper(@Empcode), 
                          upper(@Remarks),
						  @timetaken ) 
        END 

      IF @trakerid is not null 
        BEGIN 
            UPDATE [dbo].[trecruitmanualtraker] 
            SET    [referenceno] = upper(@Referenceno), 
                   [departmentdivision] = upper(@Departmentdivision), 
                   [postname] = upper(@Postname), 
                   [headq] = upper(@HeadQ), 
                   [candidatename] = upper(@candidatename), 
                   [source] = upper(@source), 
                   [startdate] = CONVERT(VARCHAR, @STARTDATE, 103),
				   cvname=COALESCE(@cvname,cvname),
                   cvContentType=COALESCE(@cvContentType,cvContentType),
                   cvupload = COALESCE(@cvupload, cvupload), 
                   [cvselected] = @CVSelected, 
                   [roneinterviewdate] = CONVERT(VARCHAR, @roneinterviewdate, 103), 
                   [roneinterviewernameone] = upper(@roneinterviewernameone), 
				   roneintervieweroneremarksname=COALESCE(@roneintervieweroneremarksname,roneintervieweroneremarksname),
                   roneintervieweroneremarkscontenttype=COALESCE(@roneintervieweroneremarkscontenttype,roneintervieweroneremarkscontenttype),
                   [roneintervieweroneremarks] = COALESCE( 
                   @roneintervieweroneremarks, 
                                                 roneintervieweroneremarks), 
                   [roneinterviewernametwo] = upper(@roneinterviewernametwo), 
				   roneinterviewertworemarksname=COALESCE(@roneinterviewertworemarksname,roneinterviewertworemarksname),
                   roneinterviewertworemarkscontenttype=COALESCE(@roneinterviewertworemarkscontenttype,roneinterviewertworemarkscontenttype),
                   [roneinterviewertworemarks] = COALESCE( 
                   @roneinterviewertworemarks, 
                                                 [roneinterviewertworemarks]), 
                   [roneselect] = @roneselect, 
                   [rtwointerviewdate] = CONVERT(VARCHAR, @rtwointerviewdate, 103), 
                   [rtwointerviewernameone] = upper(@rtwointerviewernameone), 
				   rtwointervieweroneremarksname=COALESCE(@rtwointervieweroneremarksname,rtwointervieweroneremarksname),
                   rtwointervieweroneremarkscontenttype=COALESCE(@rtwointervieweroneremarkscontenttype,rtwointervieweroneremarkscontenttype),
                   [rtwointervieweroneremarks] = COALESCE( 
                   @rtwointervieweroneremarks, 
                                                 rtwointervieweroneremarks), 
                   [rtwointerviewernametwo] = upper(@rtwointerviewernametwo), 
				   rtwointerviewertworemarksname=COALESCE(@rtwointerviewertworemarksname,rtwointerviewertworemarksname),
                   rtwointerviewertworemarkscontenttype=COALESCE(@rtwointerviewertworemarkscontenttype,rtwointerviewertworemarkscontenttype),
                   [rtwointerviewertworemarks] = COALESCE( 
                   @rtwointerviewertworemarks, 
                                                 rtwointerviewertworemarks), 
                   [rtwoselect] = @rtwoselect, 
                   [rthreeinterviewdate] =CONVERT(VARCHAR, @rthreeinterviewdate, 103), 
                   [rthreeinterviewernameone] = upper(@rthreeinterviewernameone), 
				   rthreeintervieweroneremarksname=COALESCE(@rthreeintervieweroneremarksname,rthreeintervieweroneremarksname),
                   rthreeintervieweroneremarkscontenttype=COALESCE(@rthreeintervieweroneremarkscontenttype,rthreeintervieweroneremarkscontenttype),
                   [rthreeintervieweroneremarks] = COALESCE( 
                   @rthreeintervieweroneremarks 
                                                   , 
                                                   rthreeintervieweroneremarks), 
                   [rthreeinterviewernametwo] = upper(@rthreeinterviewernametwo), 
				   rthreeinterviewertworemarksname=COALESCE(@rthreeinterviewertworemarksname,rthreeinterviewertworemarksname),
                   rthreeinterviewertworemarkscontenttype=COALESCE(@rthreeinterviewertworemarkscontenttype,rthreeinterviewertworemarkscontenttype),
                   [rthreeinterviewertworemarks] = COALESCE( 
                   @rthreeinterviewertworemarks 
                                                   , 
                                                   rthreeinterviewertworemarks), 
                   [rthreeselect] = @rthreeselect, 
                   [frinterviewdate] = CONVERT(VARCHAR, @Frinterviewdate, 103),
                   [frinterviewernameone] = COALESCE(@Frinterviewernameone,Frinterviewernameone),
				   rfinalintervieweroneremarksname=COALESCE(@rfinalintervieweroneremarksname,rfinalintervieweroneremarksname),
                   rfinalintervieweroneremarkscontenttype=COALESCE(@rfinalintervieweroneremarkscontenttype,rfinalintervieweroneremarkscontenttype),
                   [rfinalintervieweroneremarks] = COALESCE( 
                   @rfinalintervieweroneremarks 
                                                   , 
                                                   rfinalintervieweroneremarks), 
                   [frinterviewernametwo] = upper(@Frinterviewernametwo), 
				   rfinalinterviewertworemarksname=COALESCE(@rfinalinterviewertworemarksname,rfinalinterviewertworemarksname),
                   rfinalinterviewertworemarkscontenttype=COALESCE(@rfinalinterviewertworemarkscontenttype,rfinalinterviewertworemarkscontenttype),
                   [rfinalinterviewertworemarks] = COALESCE( 
                   @rfinalinterviewertworemarks 
                                                   , 
                                                   rfinalinterviewertworemarks), 
                   [frselect] = @Frselect, 
                   [doo] = CONVERT(VARCHAR, @DOO, 103),
                   [doj] = CONVERT(VARCHAR, @DOJ, 103), 
                   [empcode] = upper(@Empcode), 
                   [remarks] = upper(@Remarks), 
				   timetaken=@timetaken
            WHERE  trakerid = @trakerid 
        END 
  END
GO



/* Functional group: 05_APPLICATION_WORKFLOW_AND_TRACKER; referenced grouped tables: trecruitcandidatesignup, trecruitmanualtraker */
/****** Object:  StoredProcedure [dbo].[procinsmanualtrackerform]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE procedure [dbo].[procinsmanualtrackerform]
	@Referenceno [varchar](50)= NULL,	
	@DepartmentDivisonname [varchar](50)= NULL,	
	@Postname [varchar](300)= NULL,	
	@HeadQ [varchar](300)= NULL,
	@candidateid [int]= NULL,
	@candidatename [varchar](300)= NULL,
	@source [varchar](500)= NULL,	
	@CVSelected [varchar](50) =NULL,
	@cvname  [varchar](50) =NULL,
    @cvContentType [nvarchar](200) =NULL,
	@cvupload [varbinary](max)= NULL,	
	@mailid varchar(300)=null,
	@Remarks varchar(MAX)=null,
	@status varchar(300)=null output

	AS 
  BEGIN 
     
	  declare @postid int
      declare @locid int
	  declare @Departmentdivision varchar(300)
	  DECLARE @value VARCHAR(200)
	  select
	  @Departmentdivision=divname,
	  @postid = [postid], 
      @locid = [locid] 
	  from [dbo].[vw_totalpost]
	  where  [postname] = @postname
	  SET @value=Cast(next value FOR seregistrationno AS VARCHAR(30))

	 -- if  exists( select mailid from [trecruitmanualtraker] where mailid=@mailid)
	 -- begin
	 -- set @status ='Emailid already exists'
	 -- end
	 -- else if  exists( select mailid from [dbo].[trecruitcandidatesignup] where mailid=@mailid)
  --     begin
	 -- set @status ='Emailid already exists'
	 -- end 



	 --  --IF not exists(Select [referenceno] from [dbo].[trecruitmanualtraker] where [referenceno]=@referenceno)
	 --else 
	 
	 if  @referenceno=''
	

        BEGIN 
		   if  exists( select mailid from [trecruitmanualtraker] where mailid=@mailid)
	  begin
	  set @status ='Emailid already exists'
	  end
	  else if  exists( select mailid from [dbo].[trecruitcandidatesignup] where mailid=@mailid)
       begin
	  set @status ='Emailid already exists'
	  end 
	  else
	  begin
            INSERT INTO [dbo].[trecruitmanualtraker] 
                        ([referenceno],
						 DepartmentDivisonname,						 
                         [departmentdivision], 
						 [postid],
						 [locid],
                         [postname],						  
                         [headq], 
                         [candidatename], 
                         [source],  
						  mailid, 
						 [manualupdate],  
						 Applicationstatus,                    
						 [cvname],
                         [cvContentType],
                         cvupload, 
                         [cvselected],
						 createdtime,
						 Remarks) 
            VALUES      ( 'Candidate00' + @value, 
			              @DepartmentDivisonname,
                          @Departmentdivision,
						  @postid,
						  @locid, 
                          @Postname, 
                          upper(@HeadQ), 
                          upper(@candidatename), 
                          @source,                           
						  @mailid,
						  'Yes',
						  'NEW',
						  @cvname,
                          @cvContentType,
                          @cvupload, 
                          @CVSelected,
						  getdate(),
						  upper(@Remarks)) 
        END 
		end


     else
	  begin
	  if  exists( select mailid from [dbo].[trecruitcandidatesignup] where mailid=@mailid)
       begin
	  set @status ='Emailid already exists'
	  end 
	  else  if exists( select mailid from [trecruitmanualtraker] where mailid=@mailid and [referenceno]<>@referenceno)
		begin

		set @status ='Emailid already exists'
	
         end

	   else --if exists( select mailid from [trecruitmanualtraker] where mailid=@mailid and [referenceno]=@referenceno)
	  
        BEGIN 
            UPDATE [dbo].[trecruitmanualtraker] SET    
			            DepartmentDivisonname =  @DepartmentDivisonname,
                        Departmentdivision    =  @Departmentdivision,
						postid=  @postid,
						locid=  @locid, 
                        Postname=  @Postname, 
                        HeadQ = upper(@HeadQ), 
                        candidatename=  upper(@candidatename), 
                        source=  @source,                           
						mailid= @mailid,
						cvname=COALESCE(@cvname,cvname),
                        cvContentType=COALESCE(@cvContentType,cvContentType),
                        cvupload = COALESCE(@cvupload, cvupload), 
                        CVSelected=  @CVSelected,
						modifiedtime=getdate(),
						Remarks=@Remarks

            WHERE  [referenceno] = @referenceno 

        END 

		
end
end
GO



