/****** Object:  StoredProcedure [dbo].[procselectmanualtracker]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/****** Script for SelectTopNRows command from SSMS  ******/
CREATE procedure [dbo].[procselectmanualtracker]

as
begin
SELECT [trakerid]
      ,[Referenceno]      
      ,[Departmentdivision]      
      ,[Postname]     
      ,[HeadQ]     
      ,[candidatename]
      ,[source]      
	  ,CONVERT(VARCHAR(10), [STARTDATE], 103)[STARTDATE]
      ,[CVSelected]           
	  ,CONVERT(VARCHAR(10), [roneinterviewdate], 103)[roneinterviewdate]
      ,[roneinterviewernameone]      
      ,[roneinterviewernametwo]      
      ,[roneselect]      
	  ,CONVERT(VARCHAR(10), [rtwointerviewdate], 103)[rtwointerviewdate]
      ,[rtwointerviewernameone]      
      ,[rtwointerviewernametwo]      
      ,[rtwoselect]     
	  ,CONVERT(VARCHAR(10), [rthreeinterviewdate], 103)[rthreeinterviewdate]
      ,[rthreeinterviewernameone]     
      ,[rthreeinterviewernametwo]      
      ,[rthreeselect]      
	  ,CONVERT(VARCHAR(10), [Frinterviewdate], 103)[Frinterviewdate]
      ,[Frinterviewernameone]     
      ,[Frinterviewernametwo]     
      ,[Frselect]      
	  ,CONVERT(VARCHAR(10), [DOO], 103)[DOO]      
	  ,CONVERT(VARCHAR(10), [DOJ], 103)[DOJ]
      ,[Empcode]
      ,[Remarks]
	  ,timetaken
      
  FROM [dbo].[trecruitmanualtraker]
  
end
GO



