/* Functional group: 05_APPLICATION_WORKFLOW_AND_TRACKER; referenced grouped tables: test, trecruitcanbasicdtls, trecruitcandidateresgisterdtls, trecruitcandidatesignup, trecruitcanfamilydtls, tRecruitcanlevel, tRecruitcanotherdtls, trecruitcanrelative, trecruitEduBetweenProfessionalExpGap, trecruittraker */
/****** Object:  StoredProcedure [dbo].[procupdateotdtls]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[procupdateotdtls]
@Action VARCHAR(10),
@id INT = NULL,
@considerposition VARCHAR(500) = NULL,
@referredus VARCHAR(500) = NULL,
@engagedbusiness VARCHAR(10) = NULL,
@indicatebusiness VARCHAR(100)=null,
@physicaldisability VARCHAR(10)=null,
@dischargedservice VARCHAR(10)=null,
@convictedcourt VARCHAR(10)=null,
@Timerequire VARCHAR(100)=null,
@agree VARCHAR(10)=null,
@username varchar(100)=null,
@flevel VARCHAR(100)=null,
@slevel VARCHAR(100)=null,
@canlevel VARCHAR(100)=null,
@tlevel VARCHAR(100)=null,
@premenemp varchar(10)=null,
@menrelative varchar(10)=null,

@relativename varchar(100)=null,
@relativedesignation varchar(100)=null,
@relation varchar(100)=null,
@appstatus varchar(100)=null,

@isuanavaliable varchar(10)=null,
@uan nvarchar(Max)=null,
@isesicnoavaliable varchar(10)=null,
@esicno nvarchar(Max)=null,

@reefferdothertext varchar(100) = null,
@aaddherno nvarchar(100) = null,
@professionalExperience nvarchar(max)=null,
@pancardno nvarchar(max)=null,
--Gap Professional Experience between edu gap
@gpaNumberOfDay nvarchar(max)=null,
@gapNumberOfMon nvarchar(max)=null,
@gapNumberOfYear nvarchar(max)=null,
@gapReason nvarchar(max)=null,

@numberOfExperience nvarchar(max)=null,
@numberOfSalesExperience nvarchar(max)=null,

@emergencyContactRelationship nvarchar(50)=null,
@emergencyContactNo nvarchar(10)=null,

@status varchar(100)=null output

AS
BEGIN
SET NOCOUNT ON;
DECLARE @canid VARCHAR(200)
DECLARE @canname VARCHAR(2000)
DECLARE @companyName nvarchar(max)
DECLARE @applyPost nvarchar(max)
select @companyName=CompanyName,@applyPost=Appliedpost from trecruitcandidateresgisterdtls where username=@username


SELECT @canid = [candidateid]
FROM [dbo].[trecruitcandidatesignup]
WHERE [username] = @username


SELECT @canname=[firstname]+' '+[middlename]+' '+[lastname]

FROM [dbo].[trecruitcanbasicdtls] where candidateid=@canid


--SELECT
IF @Action = 'SELECT'
BEGIN
SELECT
[considerposition],
[referredus],
[engagedbusiness],
[indicatebusiness],
premenemp,
menrelative,
c.[Name],
c.[designation],
c.[relation],
[physicaldisability],
[dischargedservice],

[convictedcourt],
[Timerequire],
agree,
[flevel]
,[slevel]
,[canlevel]

,[tlevel]
,[isuanavaliable]
,[uan]
,[isesicnoavaliable]
,[esicno]

,ReferredOthertext
,aadhaarno
,panno
,trim(d.professionalExperience)professionalExperience
,a.NumberOfExperience
,a.NumberOfSalesExperience
,a.EmergencyContactRelationship
,a.EmergencyContactNo
FROM [tRecruitcanotherdtls] a,tRecruitcanlevel b,trecruitcanrelative c ,trecruitcanbasicdtls d,trecruitEduBetweenProfessionalExpGap e where a.candidateid=@canid
and a.candidateid=b.candidateid
and a.candidateid=c.candidateid
and a.candidateid=d.candidateid
END
--select * from trecruitEduBetweenProfessionalExpGap
--(Cast(A.NumberOfYear as varchar)+' Year '+cast(A.NumberOfMonth as varchar)+' Month '+cast(A.NumberOfDay as varchar)+' Day')NumberOfGap

--INSERT
IF @Action = 'INSERT'
BEGIN


--if not exists (select relationship from trecruitcanfamilydtls where relationship= @relationship and candidateid=@canid)
--begin
INSERT INTO tRecruitcanotherdtls (candidateid,[considerposition],
[referredus],[engagedbusiness],[indicatebusiness],[physicaldisability],[dischargedservice],
[convictedcourt],[Timerequire])
VALUES (@canid,@considerposition, @referredus,@engagedbusiness,@indicatebusiness,@physicaldisability,
@dischargedservice,@convictedcourt,@Timerequire)
--end


-- else
--begin
--set @status='duplicate'
--select @status
--end
END


--UPDATE

IF @Action = 'UPDATE'
BEGIN
if (@gapReason IS Not NULL or @gapReason='')
BEGIN
if exists (select top 1 GapReason from trecruitEduBetweenProfessionalExpGap where candidateid=@canid)
begin
Update trecruitEduBetweenProfessionalExpGap
SET GapReason=@gapReason
,NumberOfYear=@gapNumberOfYear
,NumberOfMonth=@gapNumberOfMon
,NumberOfDay=@gpaNumberOfDay
Where candidateid=@canid
end
else
begin
INSERT INTO trecruitEduBetweenProfessionalExpGap (candidateid,GapReason,NumberOfYear,NumberOfMonth,NumberOfDay,createdtime)
VALUES (@canid,@gapReason,@gapNumberOfYear,@gapNumberOfMon,@gpaNumberOfDay,getdate())
end

END
ELSE BEGIN
Delete trecruitEduBetweenProfessionalExpGap Where candidateid=@canid
END

if @engagedbusiness='No'
begin
UPDATE tRecruitcanotherdtls
SET

[considerposition]=@considerposition,

[referredus]=@referredus,
[engagedbusiness]=@engagedbusiness,
[indicatebusiness]='',
premenemp=@premenemp,

menrelative=@menrelative,
[physicaldisability]=@physicaldisability,
[dischargedservice]=@dischargedservice,

[convictedcourt]=@convictedcourt,
[Timerequire]=@Timerequire,
agree='True',
[isuanavaliable]=@isuanavaliable,

[uan]=@uan,
[isesicnoavaliable]=@isesicnoavaliable,
[esicno]=@esicno,
[ReferredOthertext]=@reefferdothertext,
[aadhaarno]=@aaddherno,
[panno]=@pancardno,
[NumberOfExperience]=@numberOfExperience,
[NumberOfSalesExperience]=@numberOfSalesExperience,
[EmergencyContactRelationship]=@emergencyContactRelationship,
[EmergencyContactNo]=@emergencyContactNo
WHERE candidateid=@canid
end
else
begin
UPDATE tRecruitcanotherdtls
SET


[considerposition]=@considerposition,
[referredus]=@referredus,
[engagedbusiness]=@engagedbusiness,

[indicatebusiness]=@indicatebusiness,
premenemp=@premenemp,
menrelative=@menrelative,
[physicaldisability]=@physicaldisability,
[dischargedservice]=@dischargedservice,
[convictedcourt]=@convictedcourt,
[Timerequire]=@Timerequire,

agree='True',
[isuanavaliable]=@isuanavaliable,
[uan]=@uan,
[isesicnoavaliable]=@isesicnoavaliable,
[esicno]=@esicno, [ReferredOthertext]=@reefferdothertext,
[aadhaarno]=@aaddherno,
[panno]=@pancardno,
[NumberOfExperience]=@numberOfExperience,
[NumberOfSalesExperience]=@numberOfSalesExperience ,
[EmergencyContactRelationship]=@emergencyContactRelationship,
[EmergencyContactNo]=@emergencyContactNo
WHERE candidateid=@canid

end


update [tRecruitcanlevel]
set [flevel]=@flevel,
[slevel]=@slevel,
[canlevel]=@canlevel,

[tlevel]=@tlevel
WHERE candidateid=@canid


if @menrelative='No'

begin
update trecruitcanrelative
set [Name]=''
,[designation]=''
,[relation]=''

WHERE candidateid=@canid
end
else
begin
update trecruitcanrelative
set [Name]=@relativename
,[designation]=@relativedesignation
,[relation]=@relation
WHERE candidateid=@canid
end




if @appstatus is not null
begin
DECLARE @currentApplicationstatus nvarchar(Max)

Select top 1 @currentApplicationstatus= applicationstatus from trecruitcanbasicdtls
WHERE candidateid=@canid
--Code For Submit
if( LTRIM(RTRIM(@currentApplicationstatus)) ='RESUBMIT')
Begin
Update [trecruitcanbasicdtls]
set
Applicationstatus='SUBMITTED',
PersonalDtlsResubmitStatus=NULL
,LanguageDtlsResubmitStatus=NULL
,EducationDtlsResubmitStatus=NULL
,EmploymentHistoryDtlsResubmitStatus=NULL
,AllFormOpenResubmitStatus=NULL
,modifiedtime=getdate()
WHERE candidateid =@canid
end
Else
BEGIN
update [dbo].[trecruitcanbasicdtls] set
Applicationstatus= @appstatus,
discrolallow='Yes',
conflictallow='Yes',
eqallow='Yes',
iqallow='Yes',
aplicationdate=getdate(),
professionalExperience=@professionalExperience,
CanNotifyStatus ='On application submission'
WHERE candidateid=@canid
End

Update [trecruittraker]
set CanNotifyStatus='On application submission' where candidateid=@canid

declare @MailId varchar(200)
DECLARE @tableHTML NVARCHAR(MAX);

set @tableHTML='<table style="font-size:20px; font-family:Tahoma">
<tr>
<td>Dear ' + @canname + ',</td>

</tr>
<tr>
<td style="height: 20px;"></td>
</tr>
<tr>
<td>

Thank you for applying for the ' + @applyPost + ' position at ' + @companyName + '.
We have received your application and appreciate your interest in joining our team.
</td>

</tr>
<tr>
<td>
Our recruitment team will review your profile and qualifications. If your application is shortlisted, we will reach out to you to discuss the next steps in the selec
tion process. We appreciate your patience and understanding.
<br/>
Best regards,
</td>
</tr>
<tr>
<td>
Thank you once again for considering '+@companyName+' as your potential employer.

</td>
</tr>
<tr>
<td style="height: 40px;"></td>
</tr>
<tr>

<td>Thanks & Regards,<br/><i>Mendine HR Team</i><br/><i>'+@companyName+'</i></td>
</tr>
<tr>

<td><p><a href="http://recruitment.mendine.co.in ">Click Here for Recruitment Portal</a></p></td>
</tr>
</table>'



SELECT @MailId=[MailId]
FROM [dbo].[trecruitcandidatesignup]
where candidateid=@canid

EXEC msdb.dbo.sp_send_dbmail

@profile_name = 'Mendine_Recruitment_Profile'
,@recipients = @MailId
,@subject = 'Alert For Driscol and Conflict Test'
,@body =
@tableHTML
,@importance ='HIGH'
,@body_format = 'HTML'
end
END

