/****** Object:  StoredProcedure [dbo].[proccanbasicdtlsnew_temp]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[proccanbasicdtlsnew_temp] @username      VARCHAR(100)=NULL,             
                                            @rName         VARCHAR(50),             
                                            @rContentType  NVARCHAR(200),             
                                            @rData         VARBINARY(max),             
                                            @iName         VARCHAR(50),             
                                            @iContentType  VARCHAR(50),             
                                            @iData         IMAGE,             
                                            @firstname     VARCHAR(100)=NULL,             
                                            @middlename    VARCHAR(100)=NULL,             
                                            @lastname      VARCHAR(100)=NULL,             
                                            @dateofbirth   DATETIME=NULL,             
                                            @gender        VARCHAR(10)=NULL,             
                                            @maritalstatus VARCHAR(10)=NULL,             
                                            @nationality   VARCHAR(10)=NULL,             
                                            @Religion      VARCHAR(max)=NULL,             
                                            @voterid       VARCHAR(10)=NULL,             
                                            @age           VARCHAR(10)=NULL,             
                                            @countrycode   VARCHAR(10)=NULL,             
                                            @mobile        VARCHAR(50) =NULL,             
                                            @paddresstype  VARCHAR(10)=NULL,             
                                            @paddressline  VARCHAR(max)=NULL,             
                                            @psaddressline VARCHAR(max)=NULL,             
                                            @pvillagecity  VARCHAR(200)=NULL,             
                                            @ppostoffice   VARCHAR(200)=NULL,             
                                            @ppincode      VARCHAR(200)=NULL,        
           @PCountry      VARCHAR(200)=NULL,        
        
                                            @pstate        INT =NULL,             
                                            @pdistrict     INT =NULL,             
                                            @caddresstype  VARCHAR(10) =NULL,             
                                            @caddressline  VARCHAR(max)=NULL,             
                                            @csaddressline VARCHAR(max)=NULL,             
                                            @cvillagecity  VARCHAR(200)=NULL,             
                                            @cpostoffice   VARCHAR(200)=NULL,             
                                            @cpincode      VARCHAR(200)=NULL,         
           @CurCountry    VARCHAR(200)=NULL,         
        
                                            @cstate        INT =NULL,             
                                            @cdistrict     INT =NULL,             
                                            @caddtype      VARCHAR(10),             
                                            @paddtype      VARCHAR(10),             
                                            @status        VARCHAR(200) =NULL output ,            
           @mailid        VARCHAR(200) =NULL,            
           @otpostname    VARCHAR(500) =NULL,          
     @spousename   VARCHAR(500) =NULL          
            
AS             
  BEGIN             
      --SET nocount ON;              
      DECLARE @value VARCHAR(200)             
      DECLARE @countcam INT             
      DECLARE @canid VARCHAR(200)             
      DECLARE @canuser INT             
   declare @count int            
   DECLARE @Referenceno VARCHAR(200)             
            
            
      SET @value=Cast(next value FOR seregistrationno AS VARCHAR(30))             
            
      SELECT @canid = [candidateid],@mailid=mailid            
      FROM   [dbo].[trecruitcandidatesignup]             
      WHERE  [username] = @username             
            
   select @count=count(mailid) from [dbo].[trecruitmanualtraker] where mailid=@mailid            
            
            
   select @Referenceno=Referenceno from [dbo].[trecruitmanualtraker] where mailid=@mailid            
            
      --select @canuser=count(username) from [dbo].[trecruitcanappnum]             
      --where username=@username             
      SELECT @countcam = Count(candidateid)             
      FROM   trecruitcanbasicdtls             
      WHERE  candidateid = @canid             
            
            
            
      IF @countcam > 0             
        BEGIN             
            SELECT @status = 'Already Exist'             
            
            RETURN             
        END             
      --else if @canuser>0              
      --begin             
      --  select @status='Already Exist'             
      --  return             
      --  end             
      ELSE IF @iName = ''             
          OR @iContentType = ''             
          OR @iData IS NULL             
        BEGIN             
            SELECT @status = 'Image and Resume Reqiured'             
            
            RETURN             
        END             
      ELSE IF @rName = ''             
          OR @rContentType = ''             
          OR @rData IS NULL             
        BEGIN             
            SELECT @status = 'Image and Resume Reqiured'             
            
            RETURN             
        END             
      ELSE             
        BEGIN             
                         
            
   if @count>0            
            
            
   begin            
    INSERT INTO [dbo].[trecruitcanbasicdtls]             
                        (registrationid,             
                         registrationnumber,             
                         candidateid,             
                         aplicationdate,             
                         firstname,             
                         middlename,             
                         lastname,             
                         dateofbirth,             
                         age,             
                         gender,             
                         maritalstatus,             
                         nationality,             
                         religion,             
                         countrycode,             
                         mobile,             
                         voterid,             
                         applicationstatus,            
       submitstatus,             
                         createdtime,          
       SpouseName)             
            VALUES      (next value FOR seregistrationid,             
                         @Referenceno,             
       --'Candidate00' + @value,            
                         @canid,             
                         Getdate(),             
                         trim(@firstname),             
                         trim(@middlename),             
                         trim(@lastname),             
                         @dateofbirth,             
                         @age,             
                         @gender,             
                         @maritalstatus,             
                         @nationality,             
                         @Religion,             
                         @countrycode,             
                         @mobile,             
                         @voterid,             
                         'Edit',            
       'No',             
                         Getdate(),          
       @spousename          
       )             
            
       delete from [dbo].[trecruitmanualtraker] where mailid=@mailid            
  
   end               
               
        else            
  begin            
            INSERT INTO [dbo].[trecruitcanbasicdtls]             
                        (registrationid,             
                         registrationnumber,             
                         candidateid,             
                         aplicationdate,            
                         firstname,             
                         middlename,             
                         lastname,             
                         dateofbirth,             
                         age,             
                         gender,             
                         maritalstatus,             
      nationality,             
                         religion,             
                         countrycode,             
                         mobile,             
                         voterid,             
                         applicationstatus,             
                         createdtime,          
       SpouseName)             
            VALUES      (next value FOR seregistrationid,             
                         'Candidate00' + @value,             
                         @canid,             
                         Getdate(),             
                         trim(@firstname),             
                         trim(@middlename),             
                         trim(@lastname),   
                         @dateofbirth,             
                         @age,             
                         @gender,             
                         @maritalstatus,             
                         @nationality,             
                         @Religion,             
                         @countrycode,             
                         @mobile,             
                         @voterid,             
                         'Edit',             
                         Getdate(),          
       @spousename          
       )             
       end            
            
            
IF @paddtype = 'P'             
              BEGIN             
                  INSERT INTO [dbo].[trecruitcanaddress]             
                              (candidateid,             
                               addresstype,             
                               addressline,             
                               saddressline,             
                               villagecity,             
                               postoffice,             
                               pincode,        
          CountryId,        
                               state,             
                               district)             
                  VALUES      (@canid,             
                               'P',             
                               @paddressline,             
                               @psaddressline,             
                               @pvillagecity,             
                               @ppostoffice,             
                               @ppincode,        
                               @PCountry,          
                               case when @pstate=0 then 36 else @pstate end,             
                              case when @pdistrict=0 then 710            
                              else @pdistrict end            
                                )             
              END                   
            IF @caddtype = 'C'             
              BEGIN             
                  INSERT INTO [dbo].[trecruitcanaddress]             
                              (candidateid,             
                               addresstype,             
                               addressline,             
                               saddressline,             
                               villagecity,             
                               postoffice,             
                               pincode,        
          CountryId,        
     state,             
                               district)             
                  VALUES      (@canid,             
                               'C',             
                               @caddressline,             
                               @csaddressline,             
                               @cvillagecity,             
                               @cpostoffice,             
                               @cpincode,        
          @CurCountry,        
                               case when @cstate=0 then 36 else @cstate end,             
          case when @cdistrict=0 then 710 else @cdistrict end )             
              END             
-----------------Start save other post-----------------            
     if @otpostname <>''            
           begin            
  Select @otpostname=Replace(@otpostname,'&','and')             
  insert into  [dbo].[trecruitotherpost]            
      ([candidateid]            
      ,[otpostname]                  
      ,[createdtime])            
   values            
   (            
   @canid,            
   @otpostname,            
   getdate()            
   )            
   end            
        INSERT INTO trecruituploadimage             
                        (NAME,             
                         contenttype,             
                         data,             
                         candidateid)             
            VALUES      (@iName,             
                         @iContentType,             
                         @iData,             
                         @canid)             
            
            INSERT INTO trecruituploadresume             
                        (NAME,             
          contenttype,             
                         resumefile,             
                         candidateid)             
            VALUES      (@rName,             
                         @rContentType,             
                         @rData,             
                         @canid)            
              
              
             
  ----------------end save other post---------------------            
            SET @status =' Data Inserted Successfully'             
        END             
  END 
GO



/* Functional group: 05_APPLICATION_WORKFLOW_AND_TRACKER; referenced grouped tables: trecruitcanbasicdtls, trecruitcandidatesignup, trecruitotherpost, trecruitpostlocationmap, trecruittraker */
/****** Object:  StoredProcedure [dbo].[procgetapplicationstatus_temp]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[procgetapplicationstatus_temp] @username VARCHAR(1000),  
                                                  @postid varchar(max)=Null,  
                                                 @status   VARCHAR(10)= NULL output ,  
             @TypeFresher varchar(max) =null output,  
            @TypeExperienced varchar(max)=null output,  
            @TypeSalesExperienced varchar(max)=null output  
AS       
  BEGIN       
      DECLARE @canid INT       
      DECLARE @canotid INT       
      
  
 --Saikat   
 select @TypeFresher=[TypeFresher],@TypeExperienced=[TypeExperienced],@TypeSalesExperienced=[TypeSalesExperienced] from [trecruitpostlocationmap] where postid=@postid  
  
  
  
  
      SELECT @canid = [candidateid]       
      FROM   [dbo].[trecruitcandidatesignup]       
      WHERE  [username] = @username       
      
      SELECT @canotid = candidateid       
      FROM   trecruitotherpost       
      WHERE  candidateid = @canid       
      
      IF @canotid IS NULL       
        BEGIN       
            IF NOT EXISTS(SELECT candidateid       
                          FROM   [dbo].[trecruitcanbasicdtls]       
                          WHERE  candidateid = @canid)       
              BEGIN       
                  SET @status=1       
              END       
            ELSE IF EXISTS(SELECT candidateid       
                      FROM   [dbo].[trecruitcanbasicdtls]       
                      WHERE  candidateid = @canid       
                             AND [applicationstatus] <> 'New')       
              BEGIN       
                  SET @status=2       
              END       
            ELSE       
              BEGIN       
                  SELECT CONVERT(VARCHAR(10), [aplicationdate], 103)         AS       
                         [aplicationdate],       
                         [firstname] + ' ' + [middlename] + ' ' + [lastname]       
                         NAME,       
                         position,discrolallow,conflictallow,iqallow,eqallow,docsubmissionallow,bigfiveallow,firoballow,myersbriggsallow,rotterlocusofcontrolallow,personalitystyleinventoryallow      
                  FROM   [dbo].[trecruitcanbasicdtls] bas                             
    Left Join [vw_canapppost] po  on  bas.candidateid = po.candidateid      
                  WHERE  bas.candidateid = @canid       
                         AND [applicationstatus] = 'NEW'       
             
                  SET @status=3       
              END       
        END       
      
      IF @canotid <> ''       
        BEGIN       
            IF NOT EXISTS(SELECT candidateid       
                          FROM   [dbo].[trecruitcanbasicdtls]       
                          WHERE  candidateid = @canid)       
              BEGIN       
                  SET @status=1       
              END       
            ELSE IF EXISTS(SELECT candidateid       
                      FROM   [dbo].[trecruitcanbasicdtls]       
                      WHERE  candidateid = @canid       
                             AND [applicationstatus] <> 'New')       
              BEGIN       
                  SET @status=2       
              END       
            ELSE       
              BEGIN       
                  SELECT CONVERT(VARCHAR(10), [aplicationdate], 103)         AS       
                         [aplicationdate],       
                         [firstname] + ' ' + [middlename] + ' ' + [lastname]       
                         NAME,       
                         otpostname       
                         position,discrolallow,conflictallow,iqallow,eqallow,docsubmissionallow,bigfiveallow,firoballow,myersbriggsallow,rotterlocusofcontrolallow,personalitystyleinventoryallow      
                  FROM   [dbo].[trecruitcanbasicdtls] bas     
      Left Join trecruitotherpost otp     on bas.candidateid = otp.candidateid       
      --left outer join [trecruittraker] tr      
      -- on bas.registrationnumber =tr.referenceno,      
                  WHERE  bas.candidateid = @canid       
                  AND [applicationstatus] = 'NEW'       
                  SET @status=3       
              END       
        END       
  END   
GO



