CREATE PROCEDURE [dbo].[prochrappstatus__temp] 
@department        VARCHAR(100),       
@postname          VARCHAR(100),       
@applicationstatus VARCHAR(100),       
@status            VARCHAR(100)=NULL       
output       
AS       
  BEGIN       
      IF @department = ''       
          OR @postname = ''       
          OR @applicationstatus = ''       
        BEGIN       
            SET @status='Please Select Data for search'       
      
            RETURN       
        END       
      ELSE       
        BEGIN       
            SELECT bac.[registrationnumber],    
       convert(varchar(10),bac.aplicationdate,103) as aplicationdate,      
                   po.[username],       
                   Upper(bac.[firstname]) + ' ' + Upper(bac.[middlename]) + ' '       
                   + Upper(bac.[lastname]) CandidateName,       
                   rs.resumefile,       
                   bac.[applicationstatus],       
                   po.[postname],       
                   po.deptname ,      
       ot.referredus      
            FROM   [dbo].[trecruitcanbasicdtls] bac,       
                   [dbo].[vw_apppost] po,       
                   [trecruitcandidatesignup] su,       
                   [dbo].[trecruituploadresume] rs ,      
                   [dbo].[tRecruitcanotherdtls]ot      
            WHERE  su.username = po.username       
                   AND bac.candidateid = su.candidateid       
                   AND rs.candidateid = bac.candidateid       
                   AND bac.[applicationstatus] IN ( 'NEW','SUBMITTED')       
       and bac.candidateid=ot.candidateid      
                   AND po.deptname = @department       
                   AND po.[postname] = @postname       
       order by bac.aplicationdate       
        END                       
  END   
GO



/* Functional group: 05_APPLICATION_WORKFLOW_AND_TRACKER; referenced grouped tables: Company, trecruitappliedpost, trecruitcanbasicdtls, trecruitcandidatesignup, tRecruitcanotherdtls, trecruituploadresume */
/****** Object:  StoredProcedure [dbo].[prochrappstatus_temp]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--Sp_helptext prochrappstatus_temp
--prochrappstatus_temp 'SALES (CONCORD)','AREA SALES MANAGER - SALES (CONCORD) - KOLKATA','New',NULL,NULL,2,NULL  
CREATE PROCEDURE [dbo].[prochrappstatus_temp]         
    @department        VARCHAR(100),               
    @postname          VARCHAR(100),               
    @applicationstatus VARCHAR(100),        
    @applicationFromDate VARCHAR(100) = NULL,        
    @applicationToDate   VARCHAR(100) = NULL,       
 @CompanyId INT=0,      
  @CandidateType varchar(500)=NULL,    
    @status            VARCHAR(100) = NULL OUTPUT               
AS               
BEGIN               
    -- 1️⃣ Validate Required Fields        
    IF @department = '' OR @postname = '' OR @applicationstatus = ''               
    BEGIN               
        SET @status = 'Please Select Data for search'               
        RETURN               
    END               
        
    -- 2️⃣ Debugging: Print Input Values Before Conversion        
    PRINT 'Received From Date: ' + ISNULL(@applicationFromDate, 'NULL');        
    PRINT 'Received To Date: ' + ISNULL(@applicationToDate, 'NULL');        
        
    -- 3️⃣ Set Date Format to Ensure Proper Parsing        
    SET DATEFORMAT dmy;  -- Ensures SQL reads dates as DD/MM/YYYY        
        
    -- 4️⃣ Declare and Convert Dates        
    DECLARE @fromDate DATE = NULL,         
            @toDate DATE = NULL;        
        
    IF @applicationFromDate IS NOT NULL AND @applicationFromDate <> ''        
    BEGIN        
        SET @fromDate = TRY_CAST(@applicationFromDate AS DATE);        
        IF @fromDate IS NULL        
        BEGIN        
            SET @status = 'Invalid From Date format. Expected format: DD/MM/YYYY';        
            RETURN;        
        END        
    END        
        
    IF @applicationToDate IS NOT NULL AND @applicationToDate <> ''        
    BEGIN        
        SET @toDate = TRY_CAST(@applicationToDate AS DATE);        
        IF @toDate IS NULL        
        BEGIN        
            SET @status = 'Invalid To Date format. Expected format: DD/MM/YYYY';        
            RETURN;        
        END        
    END        
        
        
        
    -- 6️⃣ Run Query        
    SELECT    
   
        bac.[registrationnumber],            
        CONVERT(VARCHAR(10), bac.aplicationdate, 103) AS aplicationdate,              
        po.[username],               
        UPPER(bac.[firstname]) + ' ' + UPPER(bac.[middlename]) + ' ' + UPPER(bac.[lastname]) AS CandidateName,               
        --rs.resumefile,               
        bac.[applicationstatus],               
        po.[postname],               
        po.deptname,     
    
  C.Company,      
   
  ISNULL(bac.professionalExperience,'N/A')professionalExperience,      
        ot.referredus     ,  
   CONVERT(INT, CONVERT(CHAR(8), TRY_CAST(bac.aplicationdate AS DATE), 112)) AS aplicationdate_int  
    FROM           
        [dbo].[trecruitcanbasicdtls] bac       
        LEFT JOIN [trecruitcandidatesignup] su ON bac.candidateid = su.candidateid        
  LEFT JOIN [dbo].[vw_apppost] po ON po.username = su.username          
        LEFT JOIN [dbo].[trecruituploadresume] rs ON rs.candidateid = bac.candidateid              
        LEFT JOIN [dbo].[tRecruitcanotherdtls] ot ON bac.candidateid = ot.candidateid         
  LEFT JOIN trecruitappliedpost CP ON CP.postid=po.postid AND CP.IDCompany IS NOT NULL      
  INNER JOIN Company C ON C.companyPK=CP.IDCompany      
    WHERE          
        bac.[applicationstatus] IN ('NEW', 'SUBMITTED')           
        AND (@fromDate IS NULL OR bac.aplicationdate >= @fromDate)        
        AND (@toDate IS NULL OR bac.aplicationdate <= @toDate)    
  --AND (@CandidateType IS NULL OR bac.professionalExperience = @CandidateType)     
  And(@CandidateType IS NULL     
    OR (bac.professionalExperience = @CandidateType)     
    OR (@CandidateType = 'N/A' AND bac.professionalExperience IS NULL))    
        AND po.deptname = @department               
        AND po.[postname] = @postname       
  AND C.companyPK=@CompanyId    
  ORDER BY   
    CONVERT(INT, CONVERT(CHAR(8), TRY_CAST(bac.aplicationdate AS DATE), 112)) DESC;          
END 
GO



/* Functional group: 05_APPLICATION_WORKFLOW_AND_TRACKER; referenced grouped tables: Company, trecruitappliedpost, trecruitcanbasicdtls, trecruitcandidatesignup, tRecruitcanotherdtls, trecruituploadresume */
/****** Object:  StoredProcedure [dbo].[prochrappstatus_temp_Test]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[prochrappstatus_temp_Test]             
    @department        VARCHAR(100) = NULL,                   
    @postname          VARCHAR(100) = NULL,                   
    @applicationstatus VARCHAR(100) = NULL,            
    @applicationFromDate VARCHAR(100) = NULL,            
    @applicationToDate   VARCHAR(100) = NULL,           
    @CompanyId INT,   -- Mandatory          
    @CandidateType VARCHAR(500) = NULL,        
    @status VARCHAR(100) = NULL OUTPUT                    
AS                    
BEGIN                    
    -- ✅ Validate only CompanyId                    
    IF @CompanyId IS NULL OR @CompanyId = 0  
    BEGIN  
        SET @status = 'Company ID is required.'  
        RETURN  
    END  
  
    -- Debug: Print Input Dates  
    PRINT 'Received From Date: ' + ISNULL(@applicationFromDate, 'NULL');            
    PRINT 'Received To Date: ' + ISNULL(@applicationToDate, 'NULL');            
  
    -- Set Date Format  
    SET DATEFORMAT dmy;  
  
    -- Convert Dates  
    DECLARE @fromDate DATE = NULL,             
            @toDate DATE = NULL;            
  
    IF @applicationFromDate IS NOT NULL AND @applicationFromDate <> ''            
    BEGIN            
        SET @fromDate = TRY_CAST(@applicationFromDate AS DATE);            
        IF @fromDate IS NULL            
        BEGIN            
            SET @status = 'Invalid From Date format. Expected format: DD/MM/YYYY';            
            RETURN;            
        END            
    END            
  
    IF @applicationToDate IS NOT NULL AND @applicationToDate <> ''            
    BEGIN            
        SET @toDate = TRY_CAST(@applicationToDate AS DATE);            
        IF @toDate IS NULL            
        BEGIN            
            SET @status = 'Invalid To Date format. Expected format: DD/MM/YYYY';            
            RETURN;            
        END            
    END            
  
    -- ✅ CTE to return only latest row per registration number  
    ;WITH CandidateData AS (  
        SELECT  
            bac.[registrationnumber],  
            CONVERT(VARCHAR(10), bac.aplicationdate, 103) AS aplicationdate,  
            po.[username],  
            UPPER(bac.[firstname]) + ' ' + UPPER(bac.[middlename]) + ' ' + UPPER(bac.[lastname]) AS CandidateName,  
            bac.[applicationstatus],  
            po.[postname],  
            po.deptname,  
            C.Company,  
            ISNULL(bac.professionalExperience, 'N/A') AS professionalExperience,  
            ot.referredus,  
            CONVERT(INT, CONVERT(CHAR(8), TRY_CAST(bac.aplicationdate AS DATE), 112)) AS aplicationdate_int,  
            ROW_NUMBER() OVER (PARTITION BY bac.registrationnumber ORDER BY bac.aplicationdate DESC) AS rn  
        FROM               
            [dbo].[trecruitcanbasicdtls] bac           
            LEFT JOIN [trecruitcandidatesignup] su ON bac.candidateid = su.candidateid            
            LEFT JOIN [dbo].[vw_apppost] po ON po.username = su.username              
            LEFT JOIN [dbo].[trecruituploadresume] rs ON rs.candidateid = bac.candidateid                  
            LEFT JOIN [dbo].[tRecruitcanotherdtls] ot ON bac.candidateid = ot.candidateid             
            LEFT JOIN trecruitappliedpost CP ON CP.postid = po.postid AND CP.IDCompany IS NOT NULL          
            INNER JOIN Company C ON C.companyPK = CP.IDCompany          
        WHERE              
            bac.[applicationstatus] IN ('NEW', 'SUBMITTED')               
            AND (@fromDate IS NULL OR bac.aplicationdate >= @fromDate)            
            AND (@toDate IS NULL OR bac.aplicationdate <= @toDate)        
            AND (@CandidateType IS NULL         
                OR bac.professionalExperience = @CandidateType         
                OR (@CandidateType = 'N/A' AND bac.professionalExperience IS NULL))        
            AND (@department IS NULL OR @department = '-SELECT-' OR po.deptname = @department)                   
            AND (@postname IS NULL OR @postname = '-SELECT-' OR po.[postname] = @postname)           
            AND (@applicationstatus IS NULL OR @applicationstatus = '-SELECT-' OR bac.[applicationstatus] = @applicationstatus OR bac.[applicationstatus] = 'SUBMITTED')  
            AND C.companyPK = @CompanyId  
    )  
    SELECT   
        registrationnumber,  
        aplicationdate,  
        username,  
        CandidateName,  
        applicationstatus,  
        postname,  
        deptname,  
        Company,  
        professionalExperience,  
        referredus,  
        aplicationdate_int  
    FROM CandidateData  
    WHERE rn = 1  
    ORDER BY aplicationdate_int DESC;  
  
    SET @status = 'Success';  
END  
GO



