 declare @MailId varchar(200)                                
 DECLARE @tableHTML NVARCHAR(MAX);                                     
   set @tableHTML='<table style="font-size:20px; font-family:Tahoma">                                                
    <tr>                                                
     <td>Dear ' + @canname + ',</td>                                                
    </tr>                              
     <tr>                                                
     <td style="height: 20px;"></td>                                
    </tr>                                
    <tr>                                                
     <td>                              
         Thank you for applying for the  ' + @applyPost + ' position at ' + @companyName + '.                               
   We have received your application and appreciate your interest in joining our team.    
     </td>                                                
    </tr>      
 <tr>      
   <td>      
    Our recruitment team will review your profile and qualifications. If your application is shortlisted, we will reach out to you to discuss the next steps in the selection process. We appreciate your patience and understanding.      
    <br/>      
     Best regards,      
   </td>      
 </tr>      
 <tr>      
   <td>      
    Thank you once again for considering '+@companyName+' as your potential employer.      
   </td>      
 </tr>      
    <tr>                                                
     <td style="height: 40px;"></td>                                
    </tr>                                                
    <tr>                                                
     <td>Thanks & Regards,<br/><i>Mendine HR Team</i><br/><i>'+@companyName+'</i></td>                                                
    </tr>                                                
    <tr>                                         
     <td><p><a href="http://recruitment.mendine.co.in">Click Here for Recruitment Portal</a></p></td>                                               
  </tr>                                                
   </table>'     
              
-- SET @tableHTML = '<table style=" font-size:20px; font-family:Tahoma ">                                
                                
--        <tr>                                
                                
--               <td>Dear '+ @canname +'</td>                                
                                
--        </tr>                                
                                
--        <tr>                                
                                
--               <td>  Your Application is partially submitted.In order to complete your submission please give the Driscol and Conflict Test.</td>                                
--  <br/>                                
                                              
                        
                                
--        </tr>                                
-- <tr>                                
--  <td>If you have already given both the tests, then please ignore this mail.</td>                                
                                
-- </tr>             
                                
--        <tr>                                
--    <br/><br/>                                
--               <td>Thanks & Regards <br/><i>Mendine HR Team</i></td>                                
                                
--        </tr>                                
                                
--  <tr>                                
--    <br/>                                 
--<td><p><a href="http://recruitment.mendine.co.in">Click Here for Recruitment Portal</a></p></td>                                
--</tr>                                
                                
--</table>';                                
                              
   SELECT @MailId=[MailId]                                      
  FROM [dbo].[trecruitcandidatesignup]                                
  where candidateid=@canid                                
                                
 EXEC msdb.dbo.sp_send_dbmail                                
    @profile_name = 'Mendine_Recruitment_Profile'                           
   ,@recipients = @MailId                                
   ,@subject = 'Alert For Driscol and Conflict Test'                                
   ,@body = @tableHTML                                
   ,@importance ='HIGH'                                
   ,@body_format = 'HTML'                                
 end                                
 END                                
                                
 --DELETE                                
 --   IF @Action = 'DELETE'                                
 --BEGIN                                
 -- DELETE FROM trecruitcanfamilydtls                                 
 -- WHERE memberid = @memberid and candidateid=@canid                                
 --END                          
 END
GO





