                           AND b.[conquestypeid] = c.[id] 
                           AND a.[candidateid] = d.[candidateid] 
                           AND a.[languageid] = e.[id] 
                           AND a.answer = f.[number]
						   and a.[languageid]=f.[languageid]                            
                           AND [candidateattemexam] = @candidateattemexam
                           AND c.[id] = 3
						   and a.candidateid=@candidateid
end




