--Select  @Escore Escore,
-- @Iscore Iscore,
-- @Sscore Sscore,
-- @Nscore Nscore,
-- @Tscore Tscore,
-- @Fscore Fscore,
-- @Jscore Jscore,
-- @Pscore Pscore
--------E or I------------------------
 if(@Escore > @Iscore )
 begin
  Set @EorI='E'
 end
 else
 begin
   if(@Escore = @Iscore)
   begin
    Set @EorI='I'
   end
   else
   begin 
    Set @EorI='I'
   end
 end
 --------End of E or I------------------------
 --------S or N------------------------
 if(@Sscore > @Nscore )
 begin
  Set @SorN='S'
 end
 else
 begin
   if(@Sscore = @Nscore)
   begin
    Set @SorN='N'
   end
   else
   begin 
    Set @SorN='N'
   end
 end
 --------End of S or N------------------------
 --------T or F------------------------
 if(@Tscore > @Fscore )
 begin
  Set @TorF='T'
 end
 else if(@Tscore = @Fscore)
 begin
  if(@cangender ='Male')
  begin
   Set @TorF='T'
  end
  else
  begin
    Set @TorF='F'
  end
 end
 else
   begin 
    Set @TorF='F'
   end
 
 --------End of T or F------------------------
  --------J or P------------------------
 if(@Jscore > @Pscore )
 begin
  Set @JorP='J'
 end
 else
 begin
   if(@Jscore = @Pscore)
   begin
    Set @JorP='P'
   end
   else
   begin 
    Set @JorP='P'
   end
 end
 --------End of S or N------------------------
 Select @EorI EorI,@SorN SorN,@TorF TorF,@JorP JorP
end
