  --------ADD BY SOUMENDU------------------------                                  
  UPDATE [dbo].[trecruitcanbasicdtls]                                  
  SET  [eqallow]=@eqallow                                   
 WHERE [registrationnumber]=@candidateno                                  
 and ([eqallow] is null or [eqallow]='No')                                  
                                  
 UPDATE [dbo].[trecruitcanbasicdtls]            
