 and ([myersbriggsallow] is null or [myersbriggsallow]='No')                                  
                                  
 UPDATE [dbo].[trecruitcanbasicdtls]               
 SET [rotterlocusofcontrolallow]=@rotterlocusofcontrolallow                                    
