   7. ATS - configuration, scoring, score details, bulk resume ATS, JD matching
   STORED PROCEDURES
---------------------------------------------------------------------------- */

/* ---- PRIMARY / NON-TEMP PROCEDURES ---- */

/* Functional group: 07_ATS; referenced grouped tables: HEAD_ATS_SCORE, tbl_RecruiterInterviewersSchedule, trecruitcanbasicdtls, trecruitpostlocationmap, trecruittraker */
/****** Object:  StoredProcedure [dbo].[GetCustomersPageWisetest_Detail_01_05_2026]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
Create PROCEDURE [dbo].[GetCustomersPageWisetest_Detail_01_05_2026]
(
    @startdate VARCHAR(50) = NULL,
    @enddate   VARCHAR(50) = NULL
)
AS
BEGIN

    SET NOCOUNT ON;

    -----------------------------------------------------------------------
    -- RAW DATA
    -----------------------------------------------------------------------

    WITH RawData
    AS
    (
        SELECT

            A.[registrationnumber],

            A.[aplicationdate],

            A.[createdtime]  AS vw_createdtime,

            A.[modifiedtime] AS vw_modifiedtime,

            ----------------------------------------------------------------
            -- Interview Rounds
            ----------------------------------------------------------------

            CASE
                WHEN EXISTS
                (
                    SELECT 1
                    FROM tbl_RecruiterInterviewersSchedule s
                    WHERE s.CandidateRegistrationNumber = A.registrationnumber
                    AND s.InterviewersRoundNo = 1
                )
                THEN 1 ELSE 0
            END AS InterviewerRound1,

            CASE
                WHEN EXISTS
                (
                    SELECT 1
                    FROM tbl_RecruiterInterviewersSchedule s
                    WHERE s.CandidateRegistrationNumber = A.registrationnumber
                    AND s.InterviewersRoundNo = 2
                )
                THEN 1 ELSE 0
            END AS InterviewerRound2,

            CASE
                WHEN EXISTS
                (
                    SELECT 1
                    FROM tbl_RecruiterInterviewersSchedule s
                    WHERE s.CandidateRegistrationNumber = A.registrationnumber
                    AND s.InterviewersRoundNo = 3
                )
                THEN 1 ELSE 0
            END AS InterviewerRound3,

            CASE
                WHEN EXISTS
                (
                    SELECT 1
                    FROM tbl_RecruiterInterviewersSchedule s
                    WHERE s.CandidateRegistrationNumber = A.registrationnumber
                    AND s.InterviewersRoundNo = 4
                )
                THEN 1 ELSE 0
            END AS InterviewerRound4,

            ----------------------------------------------------------------
            -- Main Data
            ----------------------------------------------------------------

            A.[backgroundcheck],

            D.[CanNotifyStatusID],

            A.[username],

            A.[rscandidateid],

            A.[rscandidatename] AS candidatename,

            A.[applicationstatus],

            CASE
                WHEN A.[applicationstatus] = 'RESUBMIT'
                    THEN 'PENDING'

                WHEN A.[applicationstatus] = 'SUBMITTED'
                    THEN 'SUBMITTED'

                ELSE NULL
            END AS ResubmitStatus,

            A.[rspostname] AS postname,

            A.[rspostid],

            A.[rslocid],

            A.[location],

            A.[CompanyName],

            A.[deptdivision],

            CASE
                WHEN NULLIF
                (
                    LTRIM(RTRIM(UPPER(A.[ReferredOthertext]))),
                    ''
                ) IS NOT NULL

                THEN CONCAT
                (
                    NULLIF
                    (
                        LTRIM
                        (
                            RTRIM
                            (
                                UPPER(ISNULL(A.[referredus],''))
                            )
                        ),
                        ''
                    ),

                    CASE
                        WHEN NULLIF
                        (
                            LTRIM
                            (
                                RTRIM
                                (
                                    UPPER(ISNULL(A.[referredus],''))
                                )
                            ),
                            ''
                        ) = ''

                        THEN ''

                        ELSE ' - '
                    END,

                    UPPER(A.[ReferredOthertext])
                )

                ELSE UPPER(ISNULL(A.[referredus],''))
            END AS referredus_display,

            UPPER(A.[ReferredOthertext]) AS ReferredOthertext,

            ----------------------------------------------------------------
            -- Tracker Details
            ----------------------------------------------------------------

            A.[trakerid],
            A.[referenceno],
            A.[departmentdivision],
            A.[departmentdivisonname],
            A.[rtpostid],
            A.[rtpostname],
            A.[rtlocid],
            A.[headq],
            A.[rtcandidateid],
            A.[rtcandidatename],
            A.[source],
            A.[STARTDATE],
            A.[cvselected],
            A.[manualupdate],

            ----------------------------------------------------------------
            -- Round 1
            ----------------------------------------------------------------

            A.[roneinterviewdate],
            A.[roneinterviewernameone],
            A.[roneinterviewernametwo],
            A.[roneselect],
            A.[roneinterviewenddate],

            ----------------------------------------------------------------
            -- Round 2
            ----------------------------------------------------------------

            A.[rtwointerviewdate],
            A.[rtwointerviewernameone],
            A.[rtwointerviewernametwo],
            A.[rtwoselect],
            A.[rtwointerviewenddate],

            ----------------------------------------------------------------
            -- Round 3
            ----------------------------------------------------------------

            A.[rthreeinterviewdate],
            A.[rthreeinterviewernameone],
            A.[rthreeinterviewernametwo],
            A.[rthreeselect],
            A.[rthreeinterviewenddate],

            ----------------------------------------------------------------
            -- Final Round
            ----------------------------------------------------------------

            A.[frinterviewdate],
            A.[frinterviewernameone],
            A.[frinterviewernametwo],
            A.[frselect],
            A.[Frinterviewenddate],

            ----------------------------------------------------------------
            -- Joining
            ----------------------------------------------------------------

            A.[doo],
            A.[doj],
            A.[empcode],
            A.[completionstatus],
            A.[timetaken],
            A.[remarks],
            A.[createdby],
            A.[modifiedby],

            ----------------------------------------------------------------
            -- File Details
            ----------------------------------------------------------------

            A.[rofileid],
            A.[rocandidateid],
            A.[rofname],
            A.[rofcontenttype],
            A.[ronerone],

            A.[rosname],
            A.[roscontenttype],
            A.[ronertwo],

            A.[rtwfileid],
            A.[rtwcandidateid],
            A.[rtwfname],
            A.[rtwfcontenttype],
            A.[rtworone],

            A.[rtwsname],
            A.[rtwscontenttype],
            A.[rtwortwo],

            A.[rthfileid],
            A.[rthcandidateid],
            A.[rthfname],
            A.[rthfcontenttype],
            A.[rthworone],

            A.[rthsname],
            A.[rthscontenttype],
            A.[rthwortwo],

            A.[fileid],
            A.[rfcandidateid],
            A.[fname],
            A.[fcontenttype],
            A.[rfworone],

            A.[sname],
            A.[scontenttype],
            A.[rfwortwo],

            A.[docsubmissionallow],

            ----------------------------------------------------------------
            -- Candidate Basic
            ----------------------------------------------------------------

            B.candidateid AS candidateid_from_basic,

            ----------------------------------------------------------------
            -- ATS SCORE
            ----------------------------------------------------------------

            HS.TOTAL_SCORE,

            HS.OBTAIN_MARKS,

            HS.[STATUS] AS ATS_STATUS,

            ----------------------------------------------------------------
            -- Tracker Select Status
            ----------------------------------------------------------------

            D.roneselect   AS tracker_roneselect,

            D.rtwoselect   AS tracker_rtwoselect,

            D.rthreeselect AS tracker_rthreeselect,

            D.frselect     AS tracker_frselect,

            ----------------------------------------------------------------
            -- Dedup
            ----------------------------------------------------------------

            ROW_NUMBER() OVER
            (
                PARTITION BY A.registrationnumber
                ORDER BY
                    COALESCE
                    (
                        TRY_CONVERT(DATETIME,A.aplicationdate,103),
                        TRY_CONVERT(DATETIME,A.modifiedtime,120),
                        TRY_CONVERT(DATETIME,A.createdtime,120)
                    ) DESC
            ) AS rn

        --------------------------------------------------------------------
        -- VIEW
        --------------------------------------------------------------------

        FROM dbo.vw_rcalldata A

        LEFT JOIN trecruitpostlocationmap C
            ON A.rspostid = C.postid
            AND A.rslocid = C.locid

        LEFT JOIN [dbo].[trecruittraker] D
            ON A.referenceno = D.Referenceno

        LEFT JOIN dbo.trecruitcanbasicdtls B
            ON A.registrationnumber = B.registrationnumber

        OUTER APPLY
        (
            SELECT TOP 1
                hs.CANDIDATE_ID,
                hs.TOTAL_SCORE,
                hs.OBTAIN_MARKS,
                hs.[STATUS]

            FROM dbo.HEAD_ATS_SCORE hs

            WHERE hs.CANDIDATE_ID = B.candidateid

            ORDER BY hs.TOTAL_SCORE DESC

        ) HS

        WHERE
        (
            @startdate IS NULL
            OR @enddate IS NULL
            OR
            (
                TRY_CONVERT(DATETIME,A.aplicationdate,103)
                BETWEEN TRY_CONVERT(DATETIME,@startdate,103)
                AND TRY_CONVERT(DATETIME,@enddate,103)
            )
        )

        AND A.rspostname NOT LIKE 'ASSOCIATE%'
    ),

    -----------------------------------------------------------------------
    -- DEDUP
    -----------------------------------------------------------------------

    Dedup
    AS
    (
        SELECT *
        FROM RawData
        WHERE rn = 1
    )

    -----------------------------------------------------------------------
    -- FINAL SELECT
    -----------------------------------------------------------------------

    SELECT

        ROW_NUMBER() OVER
        (
            ORDER BY registrationnumber DESC
        ) AS RowNumber,

        *,

        CASE
            WHEN UPPER(ISNULL(tracker_frselect,'')) = 'YES'
                THEN 'Final round selected'

            WHEN UPPER(ISNULL(tracker_rthreeselect,'')) = 'YES'
                THEN 'Third round selected'

            WHEN UPPER(ISNULL(tracker_rtwoselect,'')) = 'YES'
                THEN 'Second round selected'

            WHEN UPPER(ISNULL(tracker_roneselect,'')) = 'YES'
                THEN 'First round selected'

            ELSE ''
        END AS SelectionMessage

    FROM Dedup

END
GO



/* Functional group: 07_ATS; referenced grouped tables: HEAD_ATS_SCORE, tbl_RecruiterInterviewersSchedule, trecruitcanbasicdtls, trecruitpostlocationmap, trecruittraker */
/****** Object:  StoredProcedure [dbo].[GetCustomersPageWisetest_Details]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 CREATE PROCEDURE [dbo].[GetCustomersPageWisetest_Details]                
    @startdate VARCHAR(50) = NULL,                
    @enddate   VARCHAR(50) = NULL                
AS                
BEGIN                
    SET NOCOUNT ON;                
          

    BEGIN TRY

    WITH RawData AS          
    (          
        SELECT          
            A.[registrationnumber],          
            A.[aplicationdate],          
          
            -- normalized times          
            A.[createdtime] AS vw_createdtime,          
            A.[modifiedtime] AS vw_modifiedtime,          
          
            -- interviewer existence flags          
            CASE WHEN EXISTS (          
                SELECT 1 FROM tbl_RecruiterInterviewersSchedule s          
                WHERE s.CandidateRegistrationNumber = A.registrationnumber          
                  AND s.InterviewersRoundNo = 1          
            ) THEN 1 ELSE 0 END AS InterviewerRound1,          
          
            CASE WHEN EXISTS (          
                SELECT 1 FROM tbl_RecruiterInterviewersSchedule s          
                WHERE s.CandidateRegistrationNumber = A.registrationnumber          
                  AND s.InterviewersRoundNo = 2          
            ) THEN 1 ELSE 0 END AS InterviewerRound2,          
          
            CASE WHEN EXISTS (          
                SELECT 1 FROM tbl_RecruiterInterviewersSchedule s          
                WHERE s.CandidateRegistrationNumber = A.registrationnumber          
                  AND s.InterviewersRoundNo = 3          
            ) THEN 1 ELSE 0 END AS InterviewerRound3,          
          
            CASE WHEN EXISTS (          
                SELECT 1 FROM tbl_RecruiterInterviewersSchedule s          
                WHERE s.CandidateRegistrationNumber = A.registrationnumber          
                  AND s.InterviewersRoundNo = 4          
            ) THEN 1 ELSE 0 END AS InterviewerRound4,          
          
            A.[backgroundcheck],          
            D.[CanNotifyStatusID],          
          
            A.[username],          
            A.[rscandidateid],          
            A.[rscandidatename] AS candidatename,          
            A.[applicationstatus],          
                     
            CASE          
                WHEN A.[applicationstatus] = 'RESUBMIT' THEN 'PENDING'          
                WHEN A.[applicationstatus] = 'SUBMITTED' THEN 'SUBMITTED'          
                ELSE NULL          
            END AS ResubmitStatus,          
          
            A.[rspostname] AS postname,          
            A.[rspostid],          
            A.[rslocid],          
            A.[location],        
   A.[CompanyName],        
            A.[deptdivision],          
            --UPPER(A.[referredus]) AS referredus,         
    CASE        
                WHEN NULLIF(LTRIM(RTRIM(UPPER(A.[ReferredOthertext]))),'') IS NOT NULL        
                    THEN CONCAT(        
                        NULLIF(LTRIM(RTRIM(UPPER(ISNULL(A.[referredus],'')))),''),        
                        CASE WHEN NULLIF(LTRIM(RTRIM(UPPER(ISNULL(A.[referredus],'')))),'') = '' THEN '' ELSE ' - ' END,        
                        UPPER(A.[ReferredOthertext])        
                    )        
                ELSE UPPER(ISNULL(A.[referredus],''))        
            END AS referredus_display,        
            UPPER(A.[ReferredOthertext]) AS ReferredOthertext,          
            A.[trakerid],          
            A.[referenceno],          
            A.[departmentdivision],          
            A.[departmentdivisonname],          
            A.[rtpostid],          
            A.[rtpostname],          
            A.[rtlocid],          
            A.[headq],          
            A.[rtcandidateid],          
            A.[rtcandidatename],          
            A.[source],          
            A.[STARTDATE],          
            A.[cvselected],          
            A.[manualupdate],          
          
            -- Round 1          
            A.[roneinterviewdate],          
            A.[roneinterviewernameone],          
            A.[roneinterviewernametwo],          
            A.[roneselect],       
            A.[roneinterviewenddate],          
          
            -- Round 2          
            A.[rtwointerviewdate],          
            A.[rtwointerviewernameone],          
            A.[rtwointerviewernametwo],          
            A.[rtwoselect],          
            A.[rtwointerviewenddate],          
          
            -- Round 3          
            A.[rthreeinterviewdate],          
            A.[rthreeinterviewernameone],          
            A.[rthreeinterviewernametwo],          
            A.[rthreeselect],          
            A.[rthreeinterviewenddate],          
          
            -- Final round          
            A.[frinterviewdate],          
            A.[frinterviewernameone],          
            A.[frinterviewernametwo],          
            A.[frselect],          
            A.[Frinterviewenddate],          
          
            A.[doo],          
            A.[doj],          
            A.[empcode],          
            A.[completionstatus],          
            A.[timetaken],          
            A.[remarks],          
            A.[createdby],          
            A.[modifiedby],          
          
            -- resume/file related          
            A.[rofileid],          
            A.[rocandidateid],          
            A.[rofname],          
            A.[rofcontenttype],          
            A.[ronerone],          
            A.[rosname],          
            A.[roscontenttype],          
            A.[ronertwo],          
          
            A.[rtwfileid],          
            A.[rtwcandidateid],          
            A.[rtwfname],          
            A.[rtwfcontenttype],          
            A.[rtworone],          
            A.[rtwsname],          
            A.[rtwscontenttype],          
            A.[rtwortwo],          
          
            A.[rthfileid],          
            A.[rthcandidateid],          
            A.[rthfname],          
            A.[rthfcontenttype],          
            A.[rthworone],          
            A.[rthsname],          
            A.[rthscontenttype],          
            A.[rthwortwo],          
          
            A.[fileid],          
            A.[rfcandidateid],          
            A.[fname],          
            A.[fcontenttype],          
            A.[rfworone],          
            A.[sname],          
            A.[scontenttype],          
            A.[rfwortwo],          
            A.[docsubmissionallow],          
          
            -- candidate id via trecruitcanbasicdtls (may be NULL)          
            B.candidateid AS candidateid_from_basic,          
          
            -- ATS score columns (via OUTER APPLY):          
            -- will be NULL when there is no match in HEAD_ATS_SCORE          
            HS.TOTAL_SCORE,          
            HS.OBTAIN_MARKS,          
            HS.[STATUS] AS ATS_STATUS,          
          
            -- tracker columns (alias)          
            D.roneselect  AS tracker_roneselect,          
            D.rtwoselect AS tracker_rtwoselect,          
            D.rthreeselect AS tracker_rthreeselect,          
            D.frselect   AS tracker_frselect,          
          
            -- partition row number for dedup (latest by applicationdate/modified/created)          
            ROW_NUMBER() OVER (          
                PARTITION BY A.registrationnumber          
                ORDER BY          
                    COALESCE(          
                        TRY_CONVERT(datetime, A.aplicationdate, 103),          
                        TRY_CONVERT(datetime, A.modifiedtime, 120),          
                        TRY_CONVERT(datetime, A.createdtime, 120)          
                    ) DESC,          
                    A.registrationnumber DESC          
            ) AS rn          
        FROM [dbo].[vw_rcalldata] A          
        LEFT JOIN trecruitpostlocationmap C          
            ON A.rspostid = C.postid          
           AND A.rslocid  = C.locid          
        LEFT JOIN [dbo].[trecruittraker] D          
            ON A.referenceno = D.Referenceno          
          
        -- join to trecruitcanbasicdtls to obtain candidateid (if present)          
        LEFT JOIN dbo.trecruitcanbasicdtls B          
            ON A.registrationnumber = B.registrationnumber          
          
        -- pick at most one HEAD_ATS_SCORE row for the candidate (NULL when none)          
        OUTER APPLY          
        (          
            SELECT TOP (1)          
                hs.CANDIDATE_ID,          
                hs.TOTAL_SCORE,          
                hs.OBTAIN_MARKS,          
     hs.[STATUS]          
            FROM dbo.HEAD_ATS_SCORE hs          
            WHERE hs.CANDIDATE_ID = B.candidateid          
            -- Choose ordering rule: by score (highest) or by timestamp if you want latest.          
            -- Replace ORDER BY with hs.UpdatedOn DESC if you have a date column.          
            ORDER BY hs.TOTAL_SCORE DESC          
        ) HS          
          
        WHERE          
            (          
                @startdate IS NULL          
                OR @enddate IS NULL          
                OR (          
                    TRY_CONVERT(datetime, A.[aplicationdate], 103) IS NOT NULL          
                    AND TRY_CONVERT(datetime, @startdate, 103) IS NOT NULL          
                    AND TRY_CONVERT(datetime, @enddate, 103) IS NOT NULL          
                    AND TRY_CONVERT(datetime, A.[aplicationdate], 103)          
                        BETWEEN TRY_CONVERT(datetime, @startdate, 103)          
                            AND TRY_CONVERT(datetime, @enddate, 103)          
                )          
            )          
          AND A.rspostname NOT LIKE 'ASSOCIATE%'          
    ), -- end RawData          
          
    Dedup AS          
    (          
        -- keep only top row per registrationnumber          
        SELECT *          
        FROM RawData          
        WHERE rn = 1          
    )          
          
    -- final select (adds RowNumber for paging and computes SelectionMessage)          
    SELECT          
        ROW_NUMBER() OVER (ORDER BY registrationnumber DESC) AS RowNumber,          
        registrationnumber,          
        InterviewerRound1,          
        InterviewerRound2,          
        InterviewerRound3,          
        InterviewerRound4,          
        backgroundcheck,          
        CanNotifyStatusID,          
        aplicationdate,          
        username,          
        rscandidateid,          
        candidatename,          
        applicationstatus,          
        ResubmitStatus,          
        postname,          
        rspostid,          
        rslocid,          
        location,          
  CompanyName,        
        deptdivision,          
        referredus_display AS referredus,          
        ReferredOthertext,          
        trakerid,          
        referenceno,          
        departmentdivision,          
        departmentdivisonname,          
        rtpostid,          
        rtpostname,          
        rtlocid,          
        headq,          
        rtcandidateid,          
        rtcandidatename,          
        source,          
        STARTDATE,          
        cvselected,          
        manualupdate,          
          
        roneinterviewdate,          
        roneinterviewernameone,          
        roneinterviewernametwo,          
        roneselect,          
        roneinterviewenddate,          
          
        rtwointerviewdate,          
        rtwointerviewernameone,          
        rtwointerviewernametwo,          
        rtwoselect,          
        rtwointerviewenddate,          
          
        rthreeinterviewdate,          
        rthreeinterviewernameone,          
        rthreeinterviewernametwo,          
        rthreeselect,          
        rthreeinterviewenddate,          
          
        frinterviewdate,          
        frinterviewernameone,          
        frinterviewernametwo,          
        frselect,          
        Frinterviewenddate,          
       --  CONVERT(varchar(10), doo, 103) AS doo,  
        --CONVERT(varchar(10), doj, 103) AS doj,    
       doo,          
        doj,          
        empcode,          
        completionstatus,          
        timetaken,          
        remarks,          
        createdby,          
        modifiedby,                vw_modifiedtime,          
          
        rofileid,          
        rocandidateid,          
        rofname,          
        rofcontenttype,          
        ronerone,          
        rosname,          
        roscontenttype,          
        ronertwo,          
          
        rtwfileid,          
        rtwcandidateid,          
        rtwfname,          
        rtwfcontenttype,          
        rtworone,          
        rtwsname,          
        rtwscontenttype,          
        rtwortwo,          
          
        rthfileid,          
        rthcandidateid,          
        rthfname,          
        rthfcontenttype,          
        rthworone,          
        rthsname,          
        rthscontenttype,          
        rthwortwo,          
          
        fileid,        
        rfcandidateid,          
        fname,          
        fcontenttype,          
        rfworone,          
        sname,          
        scontenttype,          
        rfwortwo,          
          
        vw_createdtime,          
          
        -- document submission flag (as in your original proc)          
        docsubmissionallow,          
          
        -- candidate id (from trecruitcanbasicdtls) — may be NULL          
        candidateid_from_basic,          
          
        -- ATS score columns (may be NULL when no HEAD_ATS_SCORE exists)          
        CASE         
            WHEN TOTAL_SCORE IS NULL AND OBTAIN_MARKS IS NULL THEN ''         
            ELSE CONCAT(        
                    CAST(FLOOR(TRY_CONVERT(decimal(18,4), ISNULL(OBTAIN_MARKS,0))) AS int),        
                    '/',        
                    CAST(FLOOR(TRY_CONVERT(decimal(18,4), ISNULL(TOTAL_SCORE,0))) AS int)        
                 )        
        END AS ATS_TOTAL_SCORE,          
        OBTAIN_MARKS as ATS_OBTAIN_MARKS,          
        ATS_STATUS ,          
          
        tracker_roneselect,          
        tracker_rtwoselect,          
        tracker_rthreeselect,          
        tracker_frselect,          
          
        CASE          
            WHEN UPPER(ISNULL(tracker_frselect, '')) = 'YES' THEN 'Final round selected'          
            WHEN UPPER(ISNULL(tracker_rthreeselect, '')) = 'YES' THEN 'Third round selected'          
            WHEN UPPER(ISNULL(tracker_rtwoselect, '')) = 'YES' THEN 'Second round selected'          
            WHEN UPPER(ISNULL(tracker_roneselect, '')) = 'YES' THEN 'First round selected'          
            ELSE ''          
        END AS SelectionMessage          
          
    FROM Dedup;     
	
	END TRY

    BEGIN CATCH

        EXEC Saas_Usp_InsertErrorLog
            @ErrorSource = 'SP',
            @ErrorMessage = ERROR_MESSAGE,
            @ErrorProcedure = ERROR_PROCEDURE,
			@SpName= "PROC_Company_Saas",
            @ErrorLine = ERROR_LINE,
            @StackTrace = ERROR_MESSAGE,
            @RequestPath = NULL,
			@CreatedBy =NULL,
			@TenantID = '6B1B6590-C5CA-4FD6-A0BB-FEBA6DB8FB14';

        THROW;

    END CATCH
          
END     
GO



