/* Functional group: 07_ATS; referenced grouped tables: trecruitcandidatesignup */
/****** Object:  StoredProcedure [dbo].[PRC_CHECK_BULK_RESUME_CANDIDATE_EXISTS]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
CREATE   PROCEDURE [dbo].[PRC_CHECK_BULK_RESUME_CANDIDATE_EXISTS]  
    @username NVARCHAR(500) = NULL,  
    @mailid NVARCHAR(500) = NULL
AS  
BEGIN  
    SET NOCOUNT ON;  
  
    SELECT TOP 1  
        username,  
        mailid  
    FROM trecruitcandidatesignup  
    WHERE  
        (  
            NULLIF(LTRIM(RTRIM(@username)), '') IS NOT NULL  
            AND username = @username  
        )  
        OR  
        (  
            NULLIF(LTRIM(RTRIM(@mailid)), '') IS NOT NULL  
            AND mailid = @mailid  
        );  
END  
GO



/* Functional group: 07_ATS; referenced grouped tables: Company, HEAD_ATS_SCORE, trecruitappliedpost, trecruitcanbasicdtls, trecruitpostlocation, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[PRC_GET_ATS_RATING]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[PRC_GET_ATS_RATING]                          
    @companyID NVARCHAR(MAX) = NULL,                          
    @depID NVARCHAR(MAX) = NULL,                          
    @postID NVARCHAR(MAX) = NULL,                    
    @status NVARCHAR(MAX) = NULL                    
AS                          
BEGIN                          
    DECLARE @totalCol NVARCHAR(MAX), @sql NVARCHAR(MAX);                          
    
    -- HTML Span wrapping OBTAIN_SCORE    
    SET @totalCol = 'MAX(CASE WHEN OBTAIN_SCORE IS NOT NULL THEN ''<span class="score-cell" data-notes="'' + REPLACE(ISNULL(Remarks, ''''), CHAR(34), '''') + ''">''                 
      + CAST(OBTAIN_SCORE AS VARCHAR) + ''</span>'' ELSE '''' END) AS [OBTAINED MARKS]';                
    
    -- Build dynamic SQL with corrected structure    
    SET @sql = '    
    SELECT                            
        CANDIDATE_ID,                          
        CandidateName AS NAME,                          
        Company COMPANY,                          
        Postname POST,                          
        Location LOCATION,                
        aplicationdate AS [APPLICATION DATE],                     
        ' + @totalCol + ',              
        TOTAL_SCORE AS [TOTAL MARKS],            
        Status AS STATUS,                      
        Status_int,                       
        aplicationdate_int                      
    FROM (    
        SELECT                        
            H.CANDIDATE_ID,                        
            UPPER(bac.firstname) + '' '' + UPPER(bac.middlename) + '' '' + UPPER(bac.lastname) AS CandidateName,                        
            C.Company,                        
            P.Postname,                        
            L.location AS Location,                    
            H.TOTAL_SCORE,              
            H.OBTAIN_MARKS AS OBTAIN_SCORE,                        
            H.REMARKS AS Remarks,                                                        
            CONVERT(VARCHAR(10), bac.aplicationdate, 103) AS aplicationdate,                    
            CONVERT(INT, CONVERT(CHAR(8), TRY_CAST(bac.aplicationdate AS DATE), 112)) AS aplicationdate_int,                  
            H.STATUS AS Status,                    
            CASE WHEN H.STATUS = ''Shortlisted'' THEN 1 ELSE 2 END AS Status_int               
        FROM HEAD_ATS_SCORE H                        
        INNER JOIN trecruitcanbasicdtls bac ON bac.candidateid = H.CANDIDATE_ID                        
        INNER JOIN Company C ON C.companyPK = H.COMPANY_ID                        
        INNER JOIN trecruitappliedpost P ON P.ActualPostID = H.ACTUAL_POST_ID     
            AND P.IDCompany = H.COMPANY_ID     
            AND P.Deptid = H.DEPARTMENT_ID                      
        INNER JOIN trecruitpostlocation L ON L.locid = H.LOCATION_ID                       
        INNER JOIN trecruitpostlocationmap map ON P.postid = map.postid     
            AND map.locid = H.LOCATION_ID     
            AND P.IDCompany = H.COMPANY_ID     
            AND P.Deptid = H.DEPARTMENT_ID                 
        WHERE                          
            (@companyID IS NULL OR C.companyPK IN (SELECT CAST(Name AS INT) FROM dbo.splitstring(@companyID)))                          
            AND (@depID IS NULL OR P.Deptid IN (SELECT CAST(Name AS INT) FROM dbo.splitstring(@depID)))                          
            AND (' +     
                CASE     
                    WHEN @status IS NULL OR @status = 'SELECT STATUS' THEN '1=1'     
                    ELSE 'H.STATUS = ''' + REPLACE(@status, '''', '''''') + ''''     
                END + ')                       
            AND (@postID IS NULL OR P.postid IN (SELECT CAST(Name AS INT) FROM dbo.splitstring(@postID)))     
    ) AS SourceTable                          
    GROUP BY                    
        CANDIDATE_ID, CandidateName, Company, Postname, Location, TOTAL_SCORE, OBTAIN_SCORE, Status, Status_int, aplicationdate, aplicationdate_int                      
    ORDER BY                   
        Status_int, aplicationdate_int DESC;    
    ';          
    
    -- Execute dynamic SQL    
    EXEC sp_executesql                 
        @sql,                     
        N'@companyID NVARCHAR(MAX), @depID NVARCHAR(MAX), @postID NVARCHAR(MAX)',                     
        @companyID = @companyID,                     
        @depID = @depID,                     
        @postID = @postID;                    
END;    
GO



/* Functional group: 07_ATS; referenced grouped tables: DTLS_ATS_SCORE, HEAD_ATS_SCORE, trecruitcanbasicdtls, trecruitcandidateresgisterdtls, trecruitcandidatesignup */
/****** Object:  StoredProcedure [dbo].[PRC_GET_ATS_RATING_BY_CANDIDATE_ID]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--PRC_GET_ATS_RATING_BY_CANDIDATE_ID '11369,11373,11387,11377,11389'
CREATE PROCEDURE [dbo].[PRC_GET_ATS_RATING_BY_CANDIDATE_ID]                              
    @CANDIDATE_ID NVARCHAR(MAX) = NULL                    
AS                              
BEGIN
    -- Convert comma-separated IDs to table
    DECLARE @CandidateTable TABLE (CandidateID INT);
    IF @CANDIDATE_ID IS NOT NULL
    BEGIN
        INSERT INTO @CandidateTable
        SELECT CAST(Name AS INT) 
        FROM dbo.SplitString(@CANDIDATE_ID);
    END

    -- Filtered CRITERIA list
    DECLARE @criteriaList TABLE (CRITERIA NVARCHAR(255));
    INSERT INTO @criteriaList
    SELECT DISTINCT A.CRITERIA
    FROM DTLS_ATS_SCORE A
    INNER JOIN HEAD_ATS_SCORE B ON B.ATS_SCORE_ID = A.ATS_SCORE_ID
    WHERE (@CANDIDATE_ID IS NULL OR B.CANDIDATE_ID IN (SELECT CandidateID FROM @CandidateTable))
    ORDER BY A.CRITERIA;

    DECLARE @colsGrouped NVARCHAR(MAX) = '';
    DECLARE @colsTotal NVARCHAR(MAX) = '';
    DECLARE @colsObtain NVARCHAR(MAX) = '';
    DECLARE @colsNotes NVARCHAR(MAX) = '';
    DECLARE @colsPercent NVARCHAR(MAX) = '';

    -- Build grouped columns      
    SELECT 
        @colsGrouped = STRING_AGG(
            QUOTENAME(CRITERIA + '_Total') + ',' + 
			QUOTENAME(CRITERIA + '_Obtain')+ ',' + 
            QUOTENAME(CRITERIA + '_Percentage') + ',' + 
            QUOTENAME(CRITERIA + '_Notes'),
            
            ','
        )
    FROM @criteriaList;

    -- Build individual column lists
    SELECT 
        @colsTotal = STRING_AGG(QUOTENAME(CRITERIA + '_Total'), ','),
        @colsObtain = STRING_AGG(QUOTENAME(CRITERIA + '_Obtain'), ','),
        @colsPercent = STRING_AGG(QUOTENAME(CRITERIA + '_Percentage'), ','),
        @colsNotes = STRING_AGG(QUOTENAME(CRITERIA + '_Notes'), ',')
    FROM @criteriaList;

    DECLARE @sql NVARCHAR(MAX) = '
    ;WITH BaseData AS (
        SELECT 
            HAS.CANDIDATE_ID, HAS.ACTUAL_POST_ID, HAS.LOCATION_ID, HAS.COMPANY_ID, HAS.DEPARTMENT_ID,
            HAS.TOTAL_SCORE AS ATS_TOTAL_SCORE,
            HAS.OBTAIN_MARKS AS ATS_OBTAIN_SCORE,
            HAS.REMARKS AS ATS_REMARKS,
            HAS.STATUS,
            CAST(
                CASE 
                    WHEN HAS.TOTAL_SCORE = 0 THEN 0
                    ELSE CAST(HAS.OBTAIN_MARKS AS DECIMAL(18,2)) * 100 / HAS.TOTAL_SCORE
                END AS DECIMAL(18,2)
            ) AS ATS_PERCENTAGE,
            DAS.CRITERIA,
            DAS.TOTAL_SCORE AS CRITERIA_TOTAL_SCORE,
            DAS.OBTAIN_SCORE,
            DAS.NOTES,
            CAST(
                CASE 
                    WHEN DAS.TOTAL_SCORE = 0 THEN 0
                    ELSE CAST(DAS.OBTAIN_SCORE AS DECIMAL(18,2)) * 100 / DAS.TOTAL_SCORE
                END AS DECIMAL(18,2)
            ) AS CRITERIA_PERCENTAGE
        FROM HEAD_ATS_SCORE HAS
        INNER JOIN DTLS_ATS_SCORE DAS ON HAS.ATS_SCORE_ID = DAS.ATS_SCORE_ID
        ' + CASE WHEN @CANDIDATE_ID IS NOT NULL THEN '
        WHERE HAS.CANDIDATE_ID IN (
            SELECT CAST(Name AS INT) FROM dbo.SplitString(''' + @CANDIDATE_ID + ''')
        )' ELSE '' END + '
    )

    , PivotTotal AS (
        SELECT * FROM (
            SELECT CANDIDATE_ID, ACTUAL_POST_ID, LOCATION_ID, COMPANY_ID, DEPARTMENT_ID, ATS_TOTAL_SCORE, ATS_OBTAIN_SCORE, ATS_REMARKS, ATS_PERCENTAGE, STATUS,
                   CRITERIA + ''_Total'' AS ColumnHeader, CRITERIA_TOTAL_SCORE AS Value
            FROM BaseData
        ) AS src
        PIVOT (
            MAX(Value) FOR ColumnHeader IN (' + @colsTotal + ')
        ) AS pt
    )

    , PivotObtain AS (
        SELECT * FROM (
            SELECT CANDIDATE_ID, ACTUAL_POST_ID, LOCATION_ID, COMPANY_ID, DEPARTMENT_ID, STATUS,
                   CRITERIA + ''_Obtain'' AS ColumnHeader, OBTAIN_SCORE AS Value
            FROM BaseData
        ) AS src
        PIVOT (
            MAX(Value) FOR ColumnHeader IN (' + @colsObtain + ')
        ) AS po
    )
	 , PivotPercentage AS (
        SELECT * FROM (
            SELECT CANDIDATE_ID, ACTUAL_POST_ID, LOCATION_ID, COMPANY_ID, DEPARTMENT_ID, STATUS,
                   CRITERIA + ''_Percentage'' AS ColumnHeader, CRITERIA_PERCENTAGE AS Value
            FROM BaseData
        ) AS src
        PIVOT (
            MAX(Value) FOR ColumnHeader IN (' + @colsPercent + ')
        ) AS pp
    )
    , PivotNotes AS (
        SELECT * FROM (
            SELECT CANDIDATE_ID, ACTUAL_POST_ID, LOCATION_ID, COMPANY_ID, DEPARTMENT_ID, STATUS,
                   CRITERIA + ''_Notes'' AS ColumnHeader, NOTES AS Value
            FROM BaseData
        ) AS src
        PIVOT (
            MAX(Value) FOR ColumnHeader IN (' + @colsNotes + ')
        ) AS pn
    )

   

    SELECT 
        regis.CompanyName, regis.Appliedpost,
        dbo.Candidate_FullName(basic.firstname, basic.middlename, basic.lastname) AS CandidateName,
        pt.ATS_TOTAL_SCORE, pt.ATS_OBTAIN_SCORE, pt.ATS_PERCENTAGE, pt.ATS_REMARKS, pt.STATUS,
        ' + @colsGrouped + '
    FROM PivotTotal pt
    JOIN PivotObtain po ON pt.CANDIDATE_ID = po.CANDIDATE_ID AND pt.ACTUAL_POST_ID = po.ACTUAL_POST_ID
    JOIN PivotNotes pn ON pt.CANDIDATE_ID = pn.CANDIDATE_ID AND pt.ACTUAL_POST_ID = pn.ACTUAL_POST_ID
    JOIN PivotPercentage pp ON pt.CANDIDATE_ID = pp.CANDIDATE_ID AND pt.ACTUAL_POST_ID = pp.ACTUAL_POST_ID
    JOIN trecruitcanbasicdtls basic ON pt.CANDIDATE_ID = basic.candidateid
    JOIN trecruitcandidatesignup SignUp ON pt.CANDIDATE_ID = SignUp.CandidateID
    JOIN trecruitcandidateresgisterdtls regis ON SignUp.username = regis.username
    ORDER BY pt.CANDIDATE_ID;
    ';

    EXEC sp_executesql @sql;
END
GO



/* Functional group: 07_ATS; referenced grouped tables: DTLS_ATS_SCORE, HEAD_ATS_SCORE, trecruitappliedpost, trecruitcanbasicdtls, trecruitcandidateresgisterdtls, trecruitcandidatesignup */
/****** Object:  StoredProcedure [dbo].[PRC_GET_ATS_RATING_CANDIDATED]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[PRC_GET_ATS_RATING_CANDIDATED]  
    @candidatedID NVARCHAR(MAX)  
AS  
BEGIN  
    SET NOCOUNT ON;  
  
    DECLARE @columnsPercentage NVARCHAR(MAX),  
            @columnsHtml NVARCHAR(MAX),  
            @totalCol NVARCHAR(MAX),  
            @sql NVARCHAR(MAX),  
            @MaxTotalMark DECIMAL(18,2),  
            @ExamAvailable INT = 0;  
  
    -- Validate Input  
    IF @candidatedID IS NULL OR @candidatedID = ''  
    BEGIN  
        RAISERROR('Candidate ID is mandatory.', 16, 1);  
        RETURN;  
    END  
  
    -- Get Exam Status  
    SELECT TOP (1)  
        @ExamAvailable = CASE  
                            WHEN ISNULL(C.ExamTaggingID, 0) = 0 THEN 0  
                            ELSE 1  
                         END  
    FROM trecruitcandidatesignup A  
    INNER JOIN trecruitcandidateresgisterdtls B  
        ON B.UserName = A.UserName  
    INNER JOIN trecruitappliedpost C  
        ON C.PostID = B.IDPost  
    WHERE A.CandidateID = @candidatedID;  
  
    SET @ExamAvailable = ISNULL(@ExamAvailable, 0);  
  
    -- Get Total Marks  
    SELECT TOP 1  
        @MaxTotalMark = H.TOTAL_SCORE  
    FROM HEAD_ATS_SCORE H  
    WHERE H.CANDIDATE_ID = @candidatedID;  
  
    SET @totalCol =  
        'MAX(CAST(ROUND(100.0 * OBTAIN_SCORE / ' +  
        CAST(@MaxTotalMark AS VARCHAR(20)) +  
        ', 1) AS VARCHAR)) AS TOTAL_SCORE';  
  
    -- Percentage Columns  
    SELECT @columnsPercentage =  
        STRING_AGG(  
            'MAX(CASE WHEN Criteria = ''' + CRITERIA +  
            ''' THEN CAST(ROUND(100.0 * Score / RatingMarks, 1) AS VARCHAR) ELSE '''' END) AS [' +  
            CRITERIA + ']',  
            ','  
        )  
    FROM  
    (  
        SELECT DISTINCT  
            D.CRITERIA + ' (' + CAST(D.TOTAL_SCORE AS VARCHAR) + ')' AS CRITERIA  
        FROM HEAD_ATS_SCORE H  
        INNER JOIN DTLS_ATS_SCORE D  
            ON D.ATS_SCORE_ID = H.ATS_SCORE_ID  
        WHERE H.CANDIDATE_ID = @candidatedID  
    ) X;  
  
    -- HTML Columns  
    SELECT @columnsHtml =  
        STRING_AGG(  
            'MAX(CASE WHEN Criteria = ''' + CRITERIA +  
            ''' THEN ''<span class="score-cell" data-notes="'' + REPLACE(ISNULL(Notes, ''''), CHAR(34), '''') + ''">'' + CAST(Score AS VARCHAR) + ''</span>'' ELSE '''' END) AS [' +  
            CRITERIA + ']',  
            ','  
        )  
    FROM  
    (  
        SELECT DISTINCT  
            D.CRITERIA + ' (' + CAST(D.TOTAL_SCORE AS VARCHAR) + ')' AS CRITERIA  
        FROM HEAD_ATS_SCORE H  
        INNER JOIN DTLS_ATS_SCORE D  
            ON D.ATS_SCORE_ID = H.ATS_SCORE_ID  
        WHERE H.CANDIDATE_ID = @candidatedID  
    ) X;  
  
    SET @sql = '  
  
    -- Result Set 1 : ATS Percentages  
    SELECT  
        MAX(CandidateName) AS CANDIDATE_NAME,  
        ' + @totalCol + ',  
        ' + @columnsPercentage + ',  
        MAX(STATUS) AS Status,  
        ' + CAST(@ExamAvailable AS VARCHAR(1)) + ' AS ExamAvailable  
    FROM  
    (  
        SELECT  
            H.CANDIDATE_ID,  
            BAC.firstname + '' '' +  
            ISNULL(BAC.middlename, '''') + '' '' +  
            ISNULL(BAC.lastname, '''') AS CandidateName,  
            D.OBTAIN_SCORE AS Score,  
            D.NOTES,  
            D.TOTAL_SCORE AS RatingMarks,  
            D.CRITERIA + '' ('' + CAST(D.TOTAL_SCORE AS VARCHAR) + '')'' AS Criteria,  
            H.OBTAIN_MARKS AS OBTAIN_SCORE,  
            H.STATUS  
        FROM HEAD_ATS_SCORE H  
        INNER JOIN DTLS_ATS_SCORE D  
            ON D.ATS_SCORE_ID = H.ATS_SCORE_ID  
        INNER JOIN trecruitcanbasicdtls BAC  
            ON BAC.candidateid = H.CANDIDATE_ID  
        WHERE H.CANDIDATE_ID = ''' + @candidatedID + '''  
    ) AS SourceTable  
    GROUP BY CANDIDATE_ID;  
  
    -- Result Set 2 : HTML Notes  
    SELECT  
        CANDIDATE_ID,  
        ' + @columnsHtml + ',  
        MAX(STATUS) AS Status,  
        ' + CAST(@ExamAvailable AS VARCHAR(1)) + ' AS ExamAvailable  
    FROM  
    (  
        SELECT  
            H.CANDIDATE_ID,  
            D.OBTAIN_SCORE AS Score,  
            D.NOTES,  
            D.CRITERIA + '' ('' + CAST(D.TOTAL_SCORE AS VARCHAR) + '')'' AS Criteria,  
            H.STATUS  
        FROM HEAD_ATS_SCORE H  
        INNER JOIN DTLS_ATS_SCORE D  
            ON D.ATS_SCORE_ID = H.ATS_SCORE_ID  
        INNER JOIN trecruitcanbasicdtls BAC  
            ON BAC.candidateid = H.CANDIDATE_ID  
        WHERE H.CANDIDATE_ID = ''' + @candidatedID + '''  
    ) AS SourceTable  
    GROUP BY CANDIDATE_ID;  
    ';  
  
    EXEC sp_executesql @sql;  
END;  
GO



/* Functional group: 07_ATS; referenced grouped tables: ATS_DTLS_RATING, ATS_HEAD_RATING, ATS_RATING_MASTER, Company, DTLS_ATS_SCORE, HEAD_ATS_SCORE, trecruitappliedpost, trecruitcanbasicdtls, trecruitpostlocation, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[PRC_GET_ATS_RATING_NEW]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
CREATE PROCEDURE [dbo].[PRC_GET_ATS_RATING_NEW]        
    @companyID NVARCHAR(MAX) = NULL,        
    @depID NVARCHAR(MAX) = NULL,        
    --@actualPostID NVARCHAR(MAX) = NULL,  
 @postID NVARCHAR(MAX) = NULL,  
    @status NVARCHAR(MAX) = NULL  
AS        
BEGIN        
    DECLARE @totalCol NVARCHAR(MAX), @sql NVARCHAR(MAX);        
        
    -- Build the dynamic total column    
    SELECT @totalCol =     
        'MAX(CASE WHEN TotalMarksHeader IS NOT NULL THEN ''<span class='' + CHAR(34) + ''score-cell'' + CHAR(34) + '' data-notes="'' + REPLACE(ISNULL(Remarks, ''''), CHAR(34), '''') + ''">''    
         + CAST(OBTAIN_SCORE AS VARCHAR) + ''</span>'' ELSE '''' END) AS [' +  
        MAX(HR.ATS_HEAD_RATING_NAME + ' (' + CONVERT(VARCHAR(10), TOTAL_RATING_MARKS) + ')') + ']'  
    FROM ATS_HEAD_RATING HR;    
    
    -- Build final SQL    
    SET @sql = '        
    SELECT         
        CANDIDATE_ID,        
        CandidateName AS NAME,        
        Company COMPANY,        
        Postname POST,        
        Location LOCATION,    
        aplicationdate [APPLICATION DATE],    
        ' + @totalCol + ',        
        Status STATUS,    
        Status_int,     
        aplicationdate_int    
    FROM (        
        SELECT        
            H.CANDIDATE_ID,        
            UPPER(bac.firstname) + '' '' + UPPER(bac.middlename) + '' '' + UPPER(bac.lastname) AS CandidateName,        
            C.Company,        
            P.Postname,        
            L.location,        
            H.TOTAL_SCORE AS OBTAIN_SCORE,        
            H.REMARKS AS Remarks,        
            D.NOTES,        
            ARM.DESCRIPTION + '' ('' + CAST(RATING_MARKS AS VARCHAR(10)) + '')'' AS Criteria,        
            HR.ATS_HEAD_RATING_NAME + '' ('' + CONVERT(VARCHAR(10), TOTAL_RATING_MARKS) + '')'' AS TotalMarksHeader,        
            D.SCORE AS Score,     
            CONVERT(VARCHAR(10), bac.aplicationdate, 103) AS aplicationdate,    
            CONVERT(INT, CONVERT(CHAR(8), TRY_CAST(bac.aplicationdate AS DATE), 112)) AS aplicationdate_int,    
            H.STATUS,    
            (CASE WHEN H.STATUS = ''Shortlisted'' THEN 1 ELSE 2 END) AS Status_int    
        FROM HEAD_ATS_SCORE H        
        INNER JOIN DTLS_ATS_SCORE D ON D.ATS_SCORE_ID = H.ATS_SCORE_ID        
        INNER JOIN ATS_DTLS_RATING DR ON DR.ATS_RATING_MASTER_ID = D.CRITERIA_ID        
        INNER JOIN ATS_HEAD_RATING HR ON HR.ATS_HEAD_RATING_ID = DR.ATS_HEAD_RATING_ID        
        INNER JOIN ATS_RATING_MASTER ARM ON ARM.ATS_RATING_MASTER_ID = DR.ATS_RATING_MASTER_ID        
        INNER JOIN trecruitcanbasicdtls bac ON bac.candidateid = H.CANDIDATE_ID        
        INNER JOIN Company C ON C.companyPK = H.COMPANY_ID        
        INNER JOIN trecruitappliedpost P ON P.ActualPostID = H.ACTUAL_POST_ID And P.IDCompany = H.COMPANY_ID  And P.Deptid = H.DEPARTMENT_ID      
        INNER JOIN trecruitpostlocation L ON L.locid = H.LOCATION_ID       
		INNER JOIN trecruitpostlocationmap map ON P.postid =map.postid and map.locid = H.LOCATION_ID 
        WHERE        
            (@companyID IS NULL OR C.companyPK IN (SELECT CAST(Name AS INT) FROM dbo.splitstring(@companyID)))        
            AND (@depID IS NULL OR P.Deptid IN (SELECT CAST(Name AS INT) FROM dbo.splitstring(@depID)))        
            AND (' +   
                CASE   
                    WHEN @status IS NULL OR @status = 'SELECT STATUS' THEN '1=1'   
                    ELSE 'H.STATUS = ''' + REPLACE(@status, '''', '''''') + ''''   
                END + ')     
   AND (@postID IS NULL OR P.postid IN (        
    SELECT CAST(Name AS INT) FROM dbo.splitstring(@postID)        
   ))           
    ) AS SourceTable        
    GROUP BY         
        CANDIDATE_ID, CandidateName, Company, Postname, Location, Status, Status_int, aplicationdate, aplicationdate_int    
    ORDER BY    
        Status_int, aplicationdate_int;';        
    
    -- Execute the dynamic SQL    
    EXEC sp_executesql @sql,   
        N'@companyID NVARCHAR(MAX), @depID NVARCHAR(MAX), @postID NVARCHAR(MAX)',   
        @companyID = @companyID,   
        @depID = @depID,   
        @postID = @postID;  
END;  
GO



/* Functional group: 07_ATS; referenced grouped tables: HEAD_ATS_SCORE */
/****** Object:  StoredProcedure [dbo].[PRC_GET_ATS_RATING_STATUS_CHANGE]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PRC_GET_ATS_RATING_STATUS_CHANGE]
    @candidateID VARCHAR(MAX)
AS
BEGIN
    -- Declare a variable to hold current status
    DECLARE @currentStatus VARCHAR(100)
    -- Get current status
    SELECT @currentStatus = STATUS 
    FROM HEAD_ATS_SCORE 
    WHERE CANDIDATE_ID = @candidateID

    -- Check and update status
    IF @currentStatus = 'Shortlisted'
    BEGIN
        UPDATE HEAD_ATS_SCORE
        SET STATUS = 'Rejected'
        WHERE CANDIDATE_ID = @candidateID
    END
    ELSE IF @currentStatus = 'Rejected'
    BEGIN
        UPDATE HEAD_ATS_SCORE
        SET STATUS = 'Shortlisted'
        WHERE CANDIDATE_ID = @candidateID
    END
    -- Optional: else do nothing or handle other cases
END
GO



