    SELECT TOP 1  
        BulkResumeAtsScoreLogID,  
        POST_ID,  
        CV_NAME,  
        SAVED_CV_NAME,  
        RESUME_FILE_LOCATION,  
        IMAGE_FILE_LOCATION,  
        FILE_HASH,  
        CANDIDATE_NAME,  
        MAIL_ID,  
        PHONE_NUMBER,  
        COMPANY_ID,  
        DEPARTMENT_ID,  
        ATS_HEAD_RATING_ID,  
        GENERATED_CANDIDATE_ID,  
        EXAM_OBTAINED_SCORE,  
        EXAM_IS_SHORTLISTED,  
        EXAM_RESULT_DATE,  
