/* Functional group: 07_ATS; referenced grouped tables: ATS_RATING_MASTER */
/****** Object:  StoredProcedure [dbo].[PRC_Receruitment_RATING_MASTER]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE Proc [dbo].[PRC_Receruitment_RATING_MASTER]  
@ATS_TYPE_ID varchar(100)=null, 
@description NVARCHAR(MAX)=null,
@ATS_RATING_MASTER_ID varchar(Max)=NULL,
@action nvarchar(100)
As          
Begin
   IF (@action = 'INSERT')              
    BEGIN
        BEGIN TRY                  
            BEGIN TRANSACTION;
			  INSERT INTO ATS_RATING_MASTER    
				 (DESCRIPTION,ATS_TYPE_ID,ACTIVEFLAG)    
                VALUES     
                (    
                    @description,@ATS_TYPE_ID,1    
                );          
		   COMMIT TRANSACTION;                         
			END TRY                  
			BEGIN CATCH                  
				ROLLBACK TRANSACTION;                 
			END CATCH;  
	END
	 ELSE IF (@action = 'SELECT')         
	 BEGIN       
	  Select ATS_RATING_MASTER_ID,DESCRIPTION from ATS_RATING_MASTER where ACTIVEFLAG=1 and ATS_TYPE_ID=@ATS_TYPE_ID
	 END
     ELSE IF (@action = 'SELECT_ByID')
	 BEGIN 
	   Select ATS_RATING_MASTER_ID,DESCRIPTION from ATS_RATING_MASTER where ACTIVEFLAG=1 AND ATS_RATING_MASTER_ID=@ATS_RATING_MASTER_ID
	 END
	  ELSE IF (@action = 'UPDATE')
	 BEGIN 
	    Update ATS_RATING_MASTER set DESCRIPTION=@description  Where  ATS_RATING_MASTER_ID=@ATS_RATING_MASTER_ID
	 END
	 	  ELSE IF (@action = 'DELETE')
	 BEGIN 
		DELETE ATS_RATING_MASTER  Where  ATS_RATING_MASTER_ID=@ATS_RATING_MASTER_ID
	 END
End
GO



/* Functional group: 07_ATS; referenced grouped tables: ATS_DTLS_RATING, ATS_HEAD_RATING, ATS_RATING_MASTER */
/****** Object:  StoredProcedure [dbo].[PRC_Receruitment_TYPE_MASTER]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[PRC_Receruitment_TYPE_MASTER]    
@ATS_HEAD_RATING_ID NVARCHAR(MAX) = NULL,  
@ATS_HEAD_RATING_NAME NVARCHAR(MAX) = NULL,  
@TOTAL_RATING_MARKS NVARCHAR(MAX) = NULL,  
@ATS_TYPE_RATING ATS_DTLS_RATING_TYPE READONLY,  
@ATS_TYPE_STATUS ATS_DTLS_RATING_TYPE READONLY,  
@action NVARCHAR(100)  
AS     
DECLARE @ATS_NEW_HEAD_RATING_ID BIGINT  
BEGIN  
   IF (@action = 'INSERT')                
   BEGIN  
        BEGIN TRY                    
            BEGIN TRANSACTION;  
  
            INSERT INTO ATS_HEAD_RATING   
            (ATS_HEAD_RATING_NAME, TOTAL_RATING_MARKS, ACTIVEFLAG)  
            VALUES (@ATS_HEAD_RATING_NAME, @TOTAL_RATING_MARKS, 1)   
              
            SELECT @ATS_NEW_HEAD_RATING_ID = SCOPE_IDENTITY();  
  
            INSERT INTO ATS_DTLS_RATING   
            (ATS_HEAD_RATING_ID, ATS_RATING_MASTER_ID, RATING_MARKS,DESCRIPTION, ACTIVEFLAG)  
            SELECT @ATS_NEW_HEAD_RATING_ID, ATS_RATING_MASTER_ID, RATING_MARKS,DESCRIPTION, 1   
            FROM @ATS_TYPE_RATING;  
  
            INSERT INTO ATS_DTLS_RATING   
            (ATS_HEAD_RATING_ID, ATS_RATING_MASTER_ID, RATING_MARKS, ACTIVEFLAG)  
            SELECT @ATS_NEW_HEAD_RATING_ID, ATS_RATING_MASTER_ID, RATING_MARKS, 1   
            FROM @ATS_TYPE_STATUS;  
  
            COMMIT TRANSACTION;                           
        END TRY                    
        BEGIN CATCH                    
            ROLLBACK TRANSACTION;                   
        END CATCH;    
   END  
   IF (@action = 'UPDATE')                
   BEGIN  
 BEGIN TRY                    
            BEGIN TRANSACTION;  
  
   Update ATS_HEAD_RATING set TOTAL_RATING_MARKS=@TOTAL_RATING_MARKS WHERE ATS_HEAD_RATING_ID= @ATS_HEAD_RATING_ID  
   DELETE FROM ATS_DTLS_RATING WHERE ATS_HEAD_RATING_ID= @ATS_HEAD_RATING_ID  
  
  
            INSERT INTO ATS_DTLS_RATING   
            (ATS_HEAD_RATING_ID, ATS_RATING_MASTER_ID, RATING_MARKS,DESCRIPTION, ACTIVEFLAG)  
            SELECT @ATS_HEAD_RATING_ID, ATS_RATING_MASTER_ID, RATING_MARKS, DESCRIPTION,1   
            FROM @ATS_TYPE_RATING;  
  
            INSERT INTO ATS_DTLS_RATING   
            (ATS_HEAD_RATING_ID, ATS_RATING_MASTER_ID, RATING_MARKS, ACTIVEFLAG)  
            SELECT @ATS_HEAD_RATING_ID, ATS_RATING_MASTER_ID, RATING_MARKS, 1   
            FROM @ATS_TYPE_STATUS;  
  
            COMMIT TRANSACTION;                           
        END TRY                    
        BEGIN CATCH                    
            ROLLBACK TRANSACTION;                   
        END CATCH;    
   END  
   ELSE IF(@action = 'SELECT')  
   BEGIN  
      SELECT ATS_HEAD_RATING_ID,ATS_HEAD_RATING_NAME,TOTAL_RATING_MARKS FROM ATS_HEAD_RATING WHERE ACTIVEFLAG=1  
   END  
   ELSE IF(@action = 'DELETE')  
   BEGIN  
      DELETE  FROM ATS_HEAD_RATING WHERE ATS_HEAD_RATING_ID = @ATS_HEAD_RATING_ID  
   DELETE FROM ATS_DTLS_RATING WHERE ATS_HEAD_RATING_ID= @ATS_HEAD_RATING_ID  
   END  
   ELSE IF(@action = 'GET_RATING_BY_HEAD_RATING_ID')  
   BEGIN  
    
 SELECT B.ATS_RATING_MASTER_ID,A.RATING_MARKS,A.DESCRIPTION  FROM ATS_DTLS_RATING  A  
  INNER JOIN ATS_RATING_MASTER B ON A.ATS_RATING_MASTER_ID=B.ATS_RATING_MASTER_ID  
  where B.ATS_TYPE_ID = 1  AND A.ATS_HEAD_RATING_ID = @ATS_HEAD_RATING_ID  
  
   END  
   ELSE IF(@action = 'GET_STATUS_BY_HEAD_RATING_ID')  
   BEGIN  
  --SELECT B.ATS_RATING_MASTER_ID,A.RATING_MARKS  FROM ATS_DTLS_RATING  A  
  --INNER JOIN ATS_RATING_MASTER B ON A.ATS_RATING_MASTER_ID=B.ATS_RATING_MASTER_ID  
  --where B.ATS_TYPE_ID = 2 AND A.ATS_HEAD_RATING_ID = @ATS_HEAD_RATING_ID  
  SELECT   
      B.ATS_RATING_MASTER_ID,  
      LEFT(A.RATING_MARKS,   
                PATINDEX('%[0-9]%', A.RATING_MARKS) - 1) AS COMPARISON_OPERATOR,  
    SUBSTRING(A.RATING_MARKS,   
       PATINDEX('%[0-9]%', A.RATING_MARKS),   
       LEN(A.RATING_MARKS)) AS RATING_MARKS  
    FROM ATS_DTLS_RATING A  
    INNER JOIN ATS_RATING_MASTER B   
     ON A.ATS_RATING_MASTER_ID = B.ATS_RATING_MASTER_ID  
    WHERE B.ATS_TYPE_ID = 2   
    AND A.ATS_HEAD_RATING_ID = @ATS_HEAD_RATING_ID  
   END  
END  
GO



/* Functional group: 07_ATS; referenced grouped tables: BulkResumeAtsScoreLog */
/****** Object:  StoredProcedure [dbo].[PRC_SAVE_BULK_RESUME_ATS_SCORE]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[PRC_SAVE_BULK_RESUME_ATS_SCORE]
    @BulkResumeAtsScoreLogID BIGINT = NULL,
    @POST_ID INT,
    @CV_NAME NVARCHAR(500) = NULL,
    @SAVED_CV_NAME NVARCHAR(500) = NULL,
    @RESUME_FILE_LOCATION NVARCHAR(1000) = NULL,
    @IMAGE_FILE_LOCATION NVARCHAR(1000) = NULL,
    @IMAGE_NAME NVARCHAR(500) = NULL,
    @FILE_HASH VARCHAR(64) = NULL,
    @CANDIDATE_NAME NVARCHAR(500) = NULL,
    @MAIL_ID NVARCHAR(500) = NULL,
    @PHONE_NUMBER NVARCHAR(50) = NULL,
    @COMPANY_ID INT = NULL,
    @DEPARTMENT_ID INT = NULL,
    @ATS_HEAD_RATING_ID INT = NULL,
    @GENERATED_CANDIDATE_ID BIGINT = NULL,
    @ATS_STATUS NVARCHAR(100) = NULL,
    @IS_SHORTLISTED BIT = 0,
    @FULL_JSON NVARCHAR(MAX) = NULL,
    @CANDIDATE_JSON NVARCHAR(MAX) = NULL,
    @IS_DUPLICATE BIT = 0,
    @DUPLICATE_OF_LOG_ID BIGINT = NULL
AS
BEGIN
    SET NOCOUNT ON;

    -- If BulkResumeAtsScoreLogID is passed and > 0, update existing record
    IF (@BulkResumeAtsScoreLogID IS NOT NULL AND @BulkResumeAtsScoreLogID > 0 AND EXISTS (SELECT 1 FROM dbo.BulkResumeAtsScoreLog WHERE BulkResumeAtsScoreLogID = @BulkResumeAtsScoreLogID))
    BEGIN
        UPDATE dbo.BulkResumeAtsScoreLog
        SET
            POST_ID = COALESCE(@POST_ID, POST_ID),
            CV_NAME = COALESCE(NULLIF(LTRIM(RTRIM(@CV_NAME)), ''), CV_NAME),
            SAVED_CV_NAME = COALESCE(NULLIF(LTRIM(RTRIM(@SAVED_CV_NAME)), ''), SAVED_CV_NAME),
            RESUME_FILE_LOCATION = COALESCE(NULLIF(LTRIM(RTRIM(@RESUME_FILE_LOCATION)), ''), RESUME_FILE_LOCATION),
            IMAGE_FILE_LOCATION = COALESCE(NULLIF(LTRIM(RTRIM(@IMAGE_FILE_LOCATION)), ''), IMAGE_FILE_LOCATION),
            ImageName = COALESCE(NULLIF(LTRIM(RTRIM(@IMAGE_NAME)), ''), ImageName),
            FILE_HASH = COALESCE(NULLIF(LTRIM(RTRIM(@FILE_HASH)), ''), FILE_HASH),
            CANDIDATE_NAME = COALESCE(NULLIF(LTRIM(RTRIM(@CANDIDATE_NAME)), ''), CANDIDATE_NAME),
            MAIL_ID = COALESCE(NULLIF(LTRIM(RTRIM(@MAIL_ID)), ''), MAIL_ID),
            PHONE_NUMBER = COALESCE(NULLIF(LTRIM(RTRIM(@PHONE_NUMBER)), ''), PHONE_NUMBER),
            COMPANY_ID = COALESCE(@COMPANY_ID, COMPANY_ID),
            DEPARTMENT_ID = COALESCE(@DEPARTMENT_ID, DEPARTMENT_ID),
            ATS_HEAD_RATING_ID = COALESCE(@ATS_HEAD_RATING_ID, ATS_HEAD_RATING_ID),
            GENERATED_CANDIDATE_ID = COALESCE(@GENERATED_CANDIDATE_ID, GENERATED_CANDIDATE_ID),
            ATS_STATUS = COALESCE(NULLIF(LTRIM(RTRIM(@ATS_STATUS)), ''), ATS_STATUS),
            FULL_JSON = COALESCE(NULLIF(LTRIM(RTRIM(@FULL_JSON)), ''), FULL_JSON),
            CANDIDATE_JSON = COALESCE(NULLIF(LTRIM(RTRIM(@CANDIDATE_JSON)), ''), CANDIDATE_JSON)
        WHERE BulkResumeAtsScoreLogID = @BulkResumeAtsScoreLogID;

        SELECT @BulkResumeAtsScoreLogID AS BulkResumeAtsScoreLogID;
        RETURN;
    END

    -- Automatic Race-Condition Protection:
    -- If @IS_DUPLICATE is 0 but an existing log row for the same POST_ID and (FILE_HASH or MAIL_ID) already exists in BulkResumeAtsScoreLog,
    -- automatically treat this incoming row as a Duplicate!
    IF (@IS_DUPLICATE = 0)
    BEGIN
        DECLARE @ExistingLogID BIGINT = NULL;

        -- 1. Check duplicate by FILE_HASH
        IF (@FILE_HASH IS NOT NULL AND LEN(LTRIM(RTRIM(@FILE_HASH))) > 0)
        BEGIN
            SELECT TOP 1 @ExistingLogID = BulkResumeAtsScoreLogID
            FROM dbo.BulkResumeAtsScoreLog WITH (UPDLOCK, HOLDLOCK)
            WHERE POST_ID = @POST_ID
              AND FILE_HASH = LTRIM(RTRIM(@FILE_HASH))
              AND IS_DUPLICATE = 0
            ORDER BY BulkResumeAtsScoreLogID ASC;
        END

        -- 2. Check duplicate by MAIL_ID for the same post
        IF (@ExistingLogID IS NULL AND @MAIL_ID IS NOT NULL AND LEN(LTRIM(RTRIM(@MAIL_ID))) > 0)
        BEGIN
            SELECT TOP 1 @ExistingLogID = BulkResumeAtsScoreLogID
            FROM dbo.BulkResumeAtsScoreLog WITH (UPDLOCK, HOLDLOCK)
            WHERE POST_ID = @POST_ID
              AND LTRIM(RTRIM(MAIL_ID)) = LTRIM(RTRIM(@MAIL_ID))
              AND IS_DUPLICATE = 0
            ORDER BY BulkResumeAtsScoreLogID ASC;
        END

        IF (@ExistingLogID IS NOT NULL)
        BEGIN
            SET @IS_DUPLICATE = 1;
            SET @DUPLICATE_OF_LOG_ID = @ExistingLogID;
            IF (@ATS_STATUS IS NULL OR @ATS_STATUS = '' OR @ATS_STATUS = 'Submitted')
            BEGIN
                SET @ATS_STATUS = 'Duplicate';
            END
        END
    END

    INSERT INTO dbo.BulkResumeAtsScoreLog
    (
        POST_ID,
        CV_NAME,
        SAVED_CV_NAME,
        RESUME_FILE_LOCATION,
        IMAGE_FILE_LOCATION,
        ImageName,
        FILE_HASH,
        CANDIDATE_NAME,
        MAIL_ID,
        PHONE_NUMBER,
        COMPANY_ID,
        DEPARTMENT_ID,
        ATS_HEAD_RATING_ID,
        GENERATED_CANDIDATE_ID,
        ATS_STATUS,
        IS_SHORTLISTED,
        IS_DUPLICATE,
        DUPLICATE_OF_LOG_ID,
        FULL_JSON,
        CANDIDATE_JSON,
        CREATED_DATE
    )
    VALUES
    (
        @POST_ID,
        @CV_NAME,
        @SAVED_CV_NAME,
        @RESUME_FILE_LOCATION,
        @IMAGE_FILE_LOCATION,
        @IMAGE_NAME,
        @FILE_HASH,
        @CANDIDATE_NAME,
        @MAIL_ID,
        @PHONE_NUMBER,
        @COMPANY_ID,
        @DEPARTMENT_ID,
        @ATS_HEAD_RATING_ID,
        @GENERATED_CANDIDATE_ID,
        @ATS_STATUS,
        @IS_SHORTLISTED,
        @IS_DUPLICATE,
        @DUPLICATE_OF_LOG_ID,
        @FULL_JSON,
        @CANDIDATE_JSON,
        GETDATE()
    );

    SELECT CAST(SCOPE_IDENTITY() AS BIGINT) AS BulkResumeAtsScoreLogID;
END
GO



/* Functional group: 07_ATS; referenced grouped tables: BulkResumeAtsScoreLog */
/****** Object:  StoredProcedure [dbo].[PRC_UPDATE_BULK_RESUME_ATS_SCORE]    Script Date: 15-08-2026 12:36:08 ******/
