/* Functional group: 07_ATS; referenced grouped tables: trecruitappliedpost, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[PROC_ATS_IsJDUploaded]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[PROC_ATS_IsJDUploaded]                           
    @CompanyIds NVARCHAR(MAX),   -- Mandatory                   
    @departmentsIds NVARCHAR(MAX)=NULL,                                 
    @postnamesIds NVARCHAR(MAX),                                 
    @status VARCHAR(100) OUTPUT                                  
AS                                  
BEGIN        
    SET NOCOUNT ON;    
    
    IF EXISTS (    
        SELECT 1    
        FROM trecruitpostlocationmap A    
        INNER JOIN trecruitappliedpost B ON A.postid = B.postid    
        WHERE     
            B.IDCompany = @CompanyIds      
            AND  B.Deptid=@departmentsIds      
            AND A.postid = @postnamesIds    
            AND ISNULL(A.JobTitle, '') <> ''    
            AND ISNULL(A.Objectives, '') <> ''    
            AND ISNULL(A.Qualifications, '') <> ''    
            AND ISNULL(A.Jobresponsibility, '') <> ''    
    )    
    BEGIN    
        SET @status = '1';  -- JD is present    
    END    
    ELSE    
    BEGIN    
        SET @status = '0';  -- JD is missing or incomplete    
    END    
 PRINT @status  
  
END    
GO



