/* Functional group: 07_ATS; referenced grouped tables: Company, trecruitappliedpost, trecruitcanbasicdtls, trecruitcandidatesignup, tRecruitcanotherdtls, trecruituploadresume */
/****** Object:  StoredProcedure [dbo].[PROC_ATS_SHOW_SCOREGENERATE]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[PROC_ATS_SHOW_SCOREGENERATE]                         
    @CompanyIds nvarchar(max) = NULL,   -- Mandatory                
    @departments       nvarchar(max) = NULL,                               
    @postnames          nvarchar(max) = NULL,                               
    @applicationstatus VARCHAR(100) = NULL,                        
    @applicationFromDate VARCHAR(100) = NULL,                        
    @applicationToDate   VARCHAR(100) = NULL,                           
    @CandidateType VARCHAR(500) = NULL,          
 @CandidateName VARCHAR(500) = NULL,          
    @status VARCHAR(100) = NULL OUTPUT                                
AS                                
BEGIN                                
    --  Validate only CompanyId                                
    --IF @CompanyId IS NULL OR @CompanyId = 0              
    --BEGIN              
    --    SET @status = 'Company ID is required.'              
    --    RETURN              
    --END              
    -- Debug: Print Input Dates              
              
    PRINT 'Received From Date: ' + ISNULL(@applicationFromDate, 'NULL');                        
    PRINT 'Received To Date: ' + ISNULL(@applicationToDate, 'NULL');                        
              
    -- Set Date Format              
    SET DATEFORMAT dmy;              
              
    -- Convert Dates              
    DECLARE @fromDate DATE = NULL,                         
            @toDate DATE = NULL;                        
              
    IF @applicationFromDate IS NOT NULL AND @applicationFromDate <> ''                        
    BEGIN                        
        SET @fromDate = TRY_CAST(@applicationFromDate AS DATE);                        
        IF @fromDate IS NULL                        
        BEGIN                        
            SET @status = 'Invalid From Date format. Expected format: DD/MM/YYYY';                        
            RETURN;                        
        END                        
    END                        
              
    IF @applicationToDate IS NOT NULL AND @applicationToDate <> ''                        
    BEGIN                        
        SET @toDate = TRY_CAST(@applicationToDate AS DATE);                        
        IF @toDate IS NULL                        
        BEGIN                        
            SET @status = 'Invalid To Date format. Expected format: DD/MM/YYYY';                        
            RETURN;                        
        END                        
    END                        
              
    --  CTE to return only latest row per registration number              
    ;WITH CandidateData AS (              
        SELECT             
           bac.candidateid,    
            bac.[registrationnumber],      
   rs.ConvertToPath,    
            CONVERT(VARCHAR(10), bac.aplicationdate, 103) AS aplicationdate,    
            po.[username],              
            UPPER(bac.[firstname]) + ' ' + UPPER(bac.[middlename]) + ' ' + UPPER(bac.[lastname]) AS CandidateName,              
            bac.[applicationstatus],              
            po.[postname],              
            po.deptname,              
            C.Company,              
            ISNULL(bac.professionalExperience, 'N/A') AS professionalExperience,              
            ot.referredus,              
            CONVERT(INT, CONVERT(CHAR(8), TRY_CAST(bac.aplicationdate AS DATE), 112)) AS aplicationdate_int,              
            ROW_NUMBER() OVER (PARTITION BY bac.registrationnumber ORDER BY bac.aplicationdate DESC) AS rn              
        FROM                           
            [dbo].[trecruitcanbasicdtls] bac                       
            LEFT JOIN [trecruitcandidatesignup] su ON bac.candidateid = su.candidateid                        
            LEFT JOIN [dbo].[vw_apppost] po ON po.username = su.username                          
            LEFT JOIN [dbo].[trecruituploadresume] rs ON rs.candidateid = bac.candidateid                              
            LEFT JOIN [dbo].[tRecruitcanotherdtls] ot ON bac.candidateid = ot.candidateid     
            LEFT JOIN trecruitappliedpost CP ON CP.postid = po.postid AND CP.IDCompany IS NOT NULL                      
            INNER JOIN Company C ON C.companyPK = CP.IDCompany                      
        WHERE                          
            --bac.[applicationstatus] IN ('NEW', 'SUBMITTED')  AND                        
             (@fromDate IS NULL OR bac.aplicationdate >= @fromDate)                        
            AND (@toDate IS NULL OR bac.aplicationdate <= @toDate)                    
            AND (@CandidateType IS NULL                     
                OR bac.professionalExperience = @CandidateType                     
                OR (@CandidateType = 'N/A' AND bac.professionalExperience IS NULL))                    
           -- AND (@department IS NULL OR @department = '-SELECT-' OR po.deptname = @department)               
   AND (@CompanyIds IS NULL OR C.companyPK   IN (SELECT CAST(Name AS INT) AS companuId FROM dbo.splitstring(@CompanyIds)))               
   AND (@departments IS NULL OR po.deptname  IN (SELECT Name AS departId FROM dbo.splitstring(@departments)))               
   AND (@postnames IS NULL OR po.[postname]  IN (SELECT Name AS posyIds FROM dbo.splitstring(@postnames)))              
   AND (@applicationstatus IS NULL OR @applicationstatus = '-SELECT-')            
           -- AND C.companyPK = @CompanyId              
                    
    )              
    SELECT   candidateid,            
        registrationnumber,     
  ConvertToPath,    
        aplicationdate,              
        username,              
        CandidateName,              
        applicationstatus,              
        postname,              
        deptname,              
        Company,              
        professionalExperience,              
        referredus,              
        aplicationdate_int              
    FROM CandidateData              
    WHERE rn = 1              
  AND (@CandidateName  IS NULL OR  CandidateName LIKE '%'+@CandidateName+'%' OR registrationnumber LIKE '%'+@CandidateName+'%' OR aplicationdate LIKE '%'+@CandidateName+'%' )          
    and (applicationstatus='NEW' or applicationstatus='SUBMITTED')
	ORDER BY aplicationdate_int DESC;              
    SET @status = 'Success';              
END      
GO



