/****** Object:  StoredProcedure [dbo].[SP_ATS_GET_RESUME_BYID]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_ATS_GET_RESUME_BYID]          
@username VARCHAR(50)          
AS          
BEGIN          
    SELECT id, R.candidateid AS candidateid,ContentType, resumefile, Name,dbo.Candidate_FullName(TB.firstname,TB.middlename,TB.lastname) AS Candidate_Name FROM trecruituploadresume R  
 INNER JOIN trecruitcandidatesignup C ON C.CandidateID=R.candidateid AND ISNULL(ConvertToPath,0)=0  
 INNER JOIN trecruitcanbasicdtls TB ON TB.candidateid=R.candidateid
 WHERE C.username =@username;          
END  
GO



/* Functional group: 07_ATS; referenced grouped tables: trecruitappliedpost, trecruitcandidateresgisterdtls, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[SP_ATS_GETCANDIDATEDETAIL]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--SP_ATS_GETCANDIDATEDETAIL 30781
CREATE PROC [dbo].[SP_ATS_GETCANDIDATEDETAIL]      
@candidateId INT        
AS        
BEGIN        
            SELECT         
                            ISNULL(P.ActualPostID,0) ActualPostID,         
                            ISNULL(TB.locid,0) locId,     
                            ISNULL(P.DeptId,0) DepartmentId,    
                            ISNULL(P.IDCompany,0) companyId        
                        FROM trecruitpostlocationmap TB            
                        INNER JOIN trecruitappliedpost P ON P.postid = TB.postid          
                        LEFT JOIN trecruitcandidateresgisterdtls TPL ON TPL.IDPost = TB.postid          
                        WHERE TPL.id = @candidateid        
   END
GO



