/* Functional group: 07_ATS; referenced grouped tables: Company, trecruitappliedpost, trecruitdepartment, trecruitpostlocation, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[SP_ATS_GetJobDescriptionByPostId]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
--SP_ATS_GetJobDescriptionByPostId 429  
--SP_ATS_GetJobDescriptionByPostId 619      
CREATE PROC [dbo].[SP_ATS_GetJobDescriptionByPostId]                        
@postId INT                      
AS                      
BEGIN                      
    SET NOCOUNT ON;                    
                    
    SELECT CAST((                  
    SELECT                     
        ISNULL(TPL.JobTitle, '') AS JobTitle,                    
        ISNULL(TPL.Objectives, '') AS Objectives,                    
        ISNULL(TPL.JobDescription, '') AS JobDescription,                    
        ISNULL(TPL.Age, '') AS Age,                    
        ISNULL(TPL.Qualifications, '') AS Qualifications,                    
        ISNULL(TPL.Jobresponsibility, '') AS JobResponsibility,                    
        ISNULL(TPL.Jobnature, '') AS RequiredSkill,                    
        ISNULL(TPL.TechnicalScope, '') AS TechnicalScope,                    
        ISNULL(TPL.Experience, '') AS Experience,                    
        ISNULL(L.location, '') AS Location,         
        ISNULL(TPL.Others,'')AS Others,        
        ISNULL(TPL.Compensate,'')AS Compensate,        
        ISNULL(TPL.AdministrativeScope,'')AS AdministrativeScope,        
        ISNULL(TPL.JobDescriptionFilePath,'') AS FilePath1,                
        -- Replace the relative path with full URL                
        ISNULL(REPLACE(TPL.JobDescriptionFilePath, '~/Register/', 'https://hrms.mendine.co.in/Register/'), '') AS FilePath ,      
        ISNULL(AP.ExamTaggingID,0) AS ExamTaggingID,      
        ISNULL(TPL.ATS_HEAD_RATING_ID,0) AS ATS_HEAD_RATING_ID,    
        ISNULL(C.COMPANY,'') AS COMPANY_NAME,    
        ISNULL(AP.IDCompany,0) AS CompanyID,    
        ISNULL(AP.PostID,0) AS PostID,    
        ISNULL(AP.PostName,'') AS POST,  
        ISNULL(AP.deptid,'') As DEPARTMENT_ID,  
        ISNULL(D.Deptname,'') As DEPARTMENT_NAME  
          
        FROM trecruitpostlocationmap TPL                                          
        INNER JOIN trecruitpostlocation L ON L.locid = TPL.locid        
        INNER JOIN trecruitappliedpost AP ON AP.postid=TPL.postid     
        INNER JOIN Company C ON C.CompanyPK=AP.IDCompany    
        INNER JOIN trecruitdepartment D ON D.id=AP.Deptid  
        WHERE AP.postid = @postId                      
        FOR JSON PATH                   
        ) AS NVARCHAR(MAX)) AS [JobDescription]                  
                  
                  
    END 
GO



/* Functional group: 07_ATS; referenced grouped tables: trecruitappliedpost, trecruitcanbasicdtls, trecruitcandidatesignup, trecruitpostlocation, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[SP_ATS_JOBDESCRIPTION]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[SP_ATS_JOBDESCRIPTION]                 
@candidateId INT              
AS              
BEGIN              
    SET NOCOUNT ON;            
            
    SELECT CAST((          
    SELECT             
        ISNULL(TPL.JobTitle, '') AS JobTitle,            
        ISNULL(TPL.Objectives, '') AS Objectives,            
        ISNULL(TPL.JobDescription, '') AS JobDescription,            
        ISNULL(TPL.Age, '') AS Age,            
        ISNULL(TPL.Qualifications, '') AS Qualifications,            
        ISNULL(TPL.Jobresponsibility, '') AS JobResponsibility,            
        ISNULL(TPL.Jobnature, '') AS RequiredSkill,            
        ISNULL(TPL.TechnicalScope, '') AS TechnicalScope,            
        ISNULL(TPL.Experience, '') AS Experience,            
        ISNULL(L.location, '') AS Location, 
		ISNULL(TPL.Others,'')AS Others,
		ISNULL(TPL.Compensate,'')AS Compensate,
		ISNULL(TPL.AdministrativeScope,'')AS AdministrativeScope,
        ISNULL(TPL.JobDescriptionFilePath,'') AS FilePath1,        
        -- Replace the relative path with full URL        
        ISNULL(REPLACE(TPL.JobDescriptionFilePath, '~/Register/', 'https://hrms.mendine.co.in/Register/'), '') AS FilePath        
    FROM trecruitcanbasicdtls TB              
    LEFT JOIN trecruitcandidatesignup TSU ON TSU.CandidateID = TB.candidateid              
    LEFT JOIN vw_apppost V ON V.username = TSU.username              
    INNER JOIN trecruitappliedpost P ON P.postid = V.postid              
    LEFT JOIN trecruitpostlocationmap TPL ON TPL.postid = P.postid AND TPL.locid = V.locid             
    LEFT JOIN trecruitpostlocation L ON L.locid = V.locid            
    WHERE TB.candidateid = @candidateId              
    FOR JSON PATH           
) AS NVARCHAR(MAX)) AS [JobDescription]          
          
          
END 
GO



/* Functional group: 07_ATS; referenced grouped tables: ATS_DTLS_RATING, ATS_HEAD_RATING, ATS_RATING_MASTER, ATS_TYPE, trecruitappliedpost, trecruitcanbasicdtls, trecruitcandidatesignup, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[SP_ATS_PROMT]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_ATS_PROMT]
   @CandidateId INT
AS
BEGIN
    SET NOCOUNT ON;

    SELECT
      CAST((
        SELECT
          -- 1) Total Score
          ISNULL((
            SELECT TOP 1 H.TOTAL_RATING_MARKS
            FROM trecruitcanbasicdtls TB
            JOIN trecruitcandidatesignup TSU ON TSU.CandidateID = TB.CandidateID
            JOIN vw_apppost V ON V.username = TSU.username
            JOIN trecruitappliedpost P ON P.postid = V.postid
            JOIN trecruitpostlocationmap TPL
              ON TPL.postid = P.postid AND TPL.locid = V.locid
            LEFT JOIN ATS_HEAD_RATING H
              ON H.ATS_HEAD_RATING_ID = TPL.ATS_HEAD_RATING_ID
            WHERE TB.CandidateID = RCB.CandidateID
          ), 0) AS [Total Score],

          -- 2) Breakdown (type ID=1) with true JSON array for Keywords
          CAST((
            SELECT
              R.ATS_RATING_MASTER_ID AS [Id],
              R.DESCRIPTION         AS [Key],
              D.RATING_MARKS        AS [Value],
              -- build the raw CSV->JSON-array string in its own APPLY
              JSON_QUERY('[' + kw.JsonArray + ']') AS Keywords
            FROM trecruitcanbasicdtls TB
            JOIN trecruitcandidatesignup TSU ON TSU.CandidateID = TB.CandidateID
            JOIN vw_apppost V ON V.username = TSU.username
            JOIN trecruitappliedpost P ON P.postid = V.postid
            JOIN trecruitpostlocationmap TPL
              ON TPL.postid = P.postid AND TPL.locid = V.locid
            LEFT JOIN ATS_HEAD_RATING H
              ON H.ATS_HEAD_RATING_ID = TPL.ATS_HEAD_RATING_ID
            LEFT JOIN ATS_DTLS_RATING D
              ON D.ATS_HEAD_RATING_ID = H.ATS_HEAD_RATING_ID
            LEFT JOIN ATS_RATING_MASTER R
              ON R.ATS_RATING_MASTER_ID = D.ATS_RATING_MASTER_ID
            LEFT JOIN ATS_TYPE A
              ON A.ATS_TYPE_ID = R.ATS_TYPE_ID
            CROSS APPLY (
              SELECT  
                STRING_AGG(
                  '"' + LTRIM(RTRIM(s.value)) + '"'
                , ','
                ) AS JsonArray
              FROM STRING_SPLIT(D.DESCRIPTION, ',') AS s
              WHERE LTRIM(RTRIM(s.value)) <> ''
            ) AS kw
            WHERE TB.CandidateID = RCB.CandidateID
              AND A.ATS_TYPE_ID = 1
            FOR JSON PATH
          ) AS VARCHAR(MAX)) AS BreakDownScore,

          -- 3) Result Status (type ID=2), unchanged
          CAST((
            SELECT
              R.ATS_RATING_MASTER_ID AS [Id],
              R.DESCRIPTION         AS [Key],
              D.RATING_MARKS        AS [Value]
            FROM trecruitcanbasicdtls TB
            JOIN trecruitcandidatesignup TSU ON TSU.CandidateID = TB.CandidateID
            JOIN vw_apppost V ON V.username = TSU.username
            JOIN trecruitappliedpost P ON P.postid = V.postid
            JOIN trecruitpostlocationmap TPL
              ON TPL.postid = P.postid AND TPL.locid = V.locid
            LEFT JOIN ATS_HEAD_RATING H
              ON H.ATS_HEAD_RATING_ID = TPL.ATS_HEAD_RATING_ID
            LEFT JOIN ATS_DTLS_RATING D
              ON D.ATS_HEAD_RATING_ID = H.ATS_HEAD_RATING_ID
            LEFT JOIN ATS_RATING_MASTER R
              ON R.ATS_RATING_MASTER_ID = D.ATS_RATING_MASTER_ID
            LEFT JOIN ATS_TYPE A
              ON A.ATS_TYPE_ID = R.ATS_TYPE_ID
            WHERE TB.CandidateID = RCB.CandidateID
              AND A.ATS_TYPE_ID = 2
            FOR JSON PATH
          ) AS VARCHAR(MAX)) AS [Result Status]

        FROM trecruitcanbasicdtls RCB
        WHERE RCB.CandidateID = @CandidateId
        FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
      ) AS VARCHAR(MAX)) AS AtsPrompt;
END
GO



/* Functional group: 07_ATS; referenced grouped tables: ATS_DTLS_RATING, ATS_HEAD_RATING, ATS_RATING_MASTER, ATS_TYPE */
/****** Object:  StoredProcedure [dbo].[SP_ATS_PROMT_BY_HEAD_RATING_ID]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[SP_ATS_PROMT_BY_HEAD_RATING_ID]
    @ATS_HEAD_RATING_ID INT
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        SELECT
            CAST((
                SELECT
                    ISNULL(H.TOTAL_RATING_MARKS, 0) AS [Total Score],

                    CAST((
                        SELECT
                            R.ATS_RATING_MASTER_ID AS [Id],
                            R.DESCRIPTION AS [Key],
                            D.RATING_MARKS AS [Value],
                            JSON_QUERY('[' + ISNULL(kw.JsonArray, '') + ']') AS Keywords
                        FROM ATS_DTLS_RATING D
                        LEFT JOIN ATS_HEAD_RATING H2
                            ON H2.ATS_HEAD_RATING_ID = D.ATS_HEAD_RATING_ID
                        LEFT JOIN ATS_RATING_MASTER R
                            ON R.ATS_RATING_MASTER_ID = D.ATS_RATING_MASTER_ID
                        LEFT JOIN ATS_TYPE A
                            ON A.ATS_TYPE_ID = R.ATS_TYPE_ID
                        OUTER APPLY (
                            SELECT
                                STUFF((
                                    SELECT ',' + '"' + REPLACE(REPLACE(REPLACE(LTRIM(RTRIM(s.value)), '\', '\\'), '"', '\"'), CHAR(10), '') + '"'
                                    FROM STRING_SPLIT(ISNULL(D.DESCRIPTION, ''), ',') AS s
                                    WHERE LTRIM(RTRIM(s.value)) <> ''
                                    FOR XML PATH(''), TYPE
                                ).value('.', 'NVARCHAR(MAX)'), 1, 1, '') AS JsonArray
                        ) AS kw
                        WHERE D.ATS_HEAD_RATING_ID = H.ATS_HEAD_RATING_ID
                          AND A.ATS_TYPE_ID = 1
                        FOR JSON PATH
                    ) AS VARCHAR(MAX)) AS BreakDownScore,

                    CAST((
                        SELECT
                            R.ATS_RATING_MASTER_ID AS [Id],
                            R.DESCRIPTION AS [Key],
                            D.RATING_MARKS AS [Value]
                        FROM ATS_DTLS_RATING D
                        LEFT JOIN ATS_HEAD_RATING H2
                            ON H2.ATS_HEAD_RATING_ID = D.ATS_HEAD_RATING_ID
                        LEFT JOIN ATS_RATING_MASTER R
                            ON R.ATS_RATING_MASTER_ID = D.ATS_RATING_MASTER_ID
                        LEFT JOIN ATS_TYPE A
                            ON A.ATS_TYPE_ID = R.ATS_TYPE_ID
                        WHERE D.ATS_HEAD_RATING_ID = H.ATS_HEAD_RATING_ID
                          AND A.ATS_TYPE_ID = 2
                        FOR JSON PATH
                    ) AS VARCHAR(MAX)) AS [Result Status]
                FROM ATS_HEAD_RATING H
                WHERE H.ATS_HEAD_RATING_ID = @ATS_HEAD_RATING_ID
                FOR JSON PATH, WITHOUT_ARRAY_WRAPPER
            ) AS VARCHAR(MAX)) AS AtsPrompt;
    END TRY
    BEGIN CATCH
        SELECT '{"error": "' + STRING_ESCAPE(ERROR_MESSAGE(), 'json') + '"}' AS AtsPrompt;
    END CATCH
END
GO



/* Functional group: 07_ATS; referenced grouped tables: DTLS_ATS_SCORE, HEAD_ATS_SCORE */
/****** Object:  StoredProcedure [dbo].[SP_ATS_SCOREFORCANDIDATE]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_ATS_SCOREFORCANDIDATE]  
    @CANDIDATE_ID INT,  
    @POST_ID INT,  
    @LOCATION_ID INT,  
    @COMPANY_ID INT,  
    @TOTAL_SCORE INT,  
    @REMARKS NVARCHAR(255),  
    @Breakdown ATS_BreakdownTableType READONLY,
    @Message NVARCHAR(255) OUTPUT  -- New OUTPUT param
AS  
BEGIN  
    SET NOCOUNT ON;  
    BEGIN TRY  
        BEGIN TRANSACTION;  
  
        DECLARE @ATS_SCORE_ID INT;  
  
        INSERT INTO HEAD_ATS_SCORE (CANDIDATE_ID, POST_ID, LOCATION_ID, COMPANY_ID, TOTAL_SCORE, REMARKS)  
        OUTPUT INSERTED.ATS_SCORE_ID  
        VALUES (@CANDIDATE_ID, @POST_ID, @LOCATION_ID, @COMPANY_ID, @TOTAL_SCORE, @REMARKS);  
  
        SET @ATS_SCORE_ID = SCOPE_IDENTITY();  
  
        INSERT INTO DTLS_ATS_SCORE (ATS_SCORE_ID, CRITERIA, SCORE, NOTES)  
        SELECT   
            @ATS_SCORE_ID,  
            Criteria,  
            Score,  
            Notes  
        FROM @Breakdown;  
  
        COMMIT TRANSACTION;  
        SET @Message = 'ATS score inserted successfully';  
    END TRY  
    BEGIN CATCH  
        ROLLBACK TRANSACTION;  
        SET @Message = ERROR_MESSAGE();  
    END CATCH  
END
GO



/* Functional group: 07_ATS; referenced grouped tables: Languages, tbl_All_Countries, temployeehistory_sales, tEmploymentHistory, trecruitcanaddress, trecruitcanbasicdtls, trecruitcanlanguage, tRecruitcanotherdtls, tRecruitEduQualification, trecruitProjectDetails, trecruitstate, trecrutdistrict */
/****** Object:  StoredProcedure [dbo].[SP_ATSCANDIDATEPROFILE]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- SP_ATS_GET_RESUME_BYID 'Sonali'    
    
 --sp_helptext SP_ATSCANDIDATEPROFILE  
--SP_ATSCANDIDATEPROFILE 11393        
        
CREATE PROCEDURE [dbo].[SP_ATSCANDIDATEPROFILE]          
    @CandidateId INT          
AS          
BEGIN          
    SET NOCOUNT ON;          
      
    -- Step 1: CTE for Experience          
    ;WITH ExperienceData AS (          
        SELECT           
            employername,          
            designation,          
            durationform AS DurationFrom,          
            durationto AS DurationTo,          
            grosssalary,          
            AboveFourLakhSalary,          
            areacovered AS LocationCovered          
        FROM temployeehistory_sales          
        WHERE candidateid = @candidateid          
        UNION ALL          
        SELECT           
            employername,          
            designation,          
            durationform,          
            durationto,          
            grosssalary,          
            AboveFourLakhSalary,          
            NULL AS LocationCovered          
        FROM tEmploymentHistory          
        WHERE candidateid = @candidateid          
    )  
      
    -- Step 2: Main query with subqueries fixed          
    SELECT CAST((  
        SELECT    
            RCB.candidateid AS CandidateId,          
              
            -- Permanent Address          
            (          
                SELECT TOP 1          
                    addressline + ',' + saddressline + ',' + villagecity + ',' + postoffice + ',' + pincode + ',' +          
                    S.statename + ',' + D.disname + ',' + C.CountryName          
                FROM trecruitcanaddress A          
                INNER JOIN tbl_All_Countries C ON C.CountryId = A.CountryId          
                INNER JOIN trecruitstate S ON S.stateid = A.state          
                INNER JOIN trecrutdistrict D ON D.disid = A.district          
                WHERE A.candidateid = RCB.candidateid AND A.addresstype = 'P'          
            ) AS [Permanent Address],          
              
            -- Present Address          
            (          
                SELECT TOP 1          
                    addressline + ',' + saddressline + ',' + villagecity + ',' + postoffice + ',' + pincode + ',' +          
                    S.statename + ',' + D.disname + ',' + C.CountryName          
                FROM trecruitcanaddress A          
                INNER JOIN tbl_All_Countries C ON C.CountryId = A.CountryId          
                INNER JOIN trecruitstate S ON S.stateid = A.state          
                INNER JOIN trecrutdistrict D ON D.disid = A.district          
                WHERE A.candidateid = RCB.candidateid AND A.addresstype = 'C'          
            ) AS [Present Address],          
              
            -- Total Experience          
            (          
                SELECT           
                    CASE
					 
                        WHEN RCB.professionalExperience = 'Experienced'           
                            THEN dbo.fn_GetTotalExperienceYears(RCB.candidateid)          
                        WHEN RCB.professionalExperience = 'Experienced(Sales)'           
                            THEN dbo.fn_GetTotalExperienceYears_sales(RCB.candidateid)          
                        ELSE '0'           
                    END          
            ) AS TotalExperience,          
              
            -- Training Program          
            (          
                SELECT TOP 1 RPD.AnyTraining FROM trecruitProjectDetails RPD          
                WHERE RPD.candidateid = RCB.candidateid          
            ) AS Training_Program,          
              
            -- Project Details          
            (          
                SELECT TOP 1 RPD.AnyProject FROM trecruitProjectDetails RPD          
                WHERE RPD.candidateid = RCB.candidateid          
            ) AS Project_Undertaken,          
              
            (          
                SELECT TOP 1 RPD.TenureDissertation FROM trecruitProjectDetails RPD          
                WHERE RPD.candidateid = RCB.candidateid          
            ) AS Duration,          
              
            (          
                SELECT TOP 1 RPD.ProjectDissertation FROM trecruitProjectDetails RPD          
                WHERE RPD.candidateid = RCB.candidateid          
            ) AS Project_Details,          
              
            -- Notice Period                  
            (          
                SELECT TOP 1 RCO.Timerequire FROM tRecruitcanotherdtls RCO          
                WHERE RCO.candidateid = RCB.candidateid          
            ) AS NoticePeriod,          
        
            -- Languages    
            CAST((    
                SELECT    
                    languagename AS LanguageName,    
                    lread AS [Read],    
                    lwrite AS [Write],    
                    lspeak AS [Speak]    
                FROM trecruitcanlanguage    
                WHERE candidateid = RCB.candidateid    
                FOR JSON PATH    
            ) AS NVARCHAR(MAX)) AS Languages,    
  
            -- Education          
            CAST((          
                SELECT           
                    EQ.degreename AS DegreeName,          
                    EQ.startingYear,          
                    EQ.yearmonthpassing,          
                    EQ.institute,          
                    EQ.marks,          
                    EQ.SubjectCombination,          
                    EQ.UniversityName          
                FROM tRecruitEduQualification EQ          
                WHERE EQ.candidateid = RCB.candidateid           
                    AND ISNULL(EQ.degreename, '') NOT IN ('', 'Na', 'NA')          
                GROUP BY EQ.degreename, EQ.startingYear, EQ.yearmonthpassing, EQ.institute, EQ.marks, EQ.SubjectCombination, EQ.UniversityName          
                FOR JSON PATH          
            ) AS NVARCHAR(MAX)) AS Education,          
  
            -- Experience          
            CAST((          
                SELECT * FROM ExperienceData          
                FOR JSON PATH          
            ) AS NVARCHAR(MAX)) AS Experience          
      
        FROM trecruitcanbasicdtls RCB          
        WHERE RCB.candidateid = @candidateid          
        FOR JSON PATH, WITHOUT_ARRAY_WRAPPER    
    ) AS NVARCHAR(MAX)) AS [StudentResume];    
END  

