/* Functional group: 07_ATS; referenced grouped tables: temp_trecruituploadResume, trecruituploadresume */
/****** Object:  StoredProcedure [dbo].[SP_ATSCANDIDATERESUMEFILEPATH_SAVE]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[SP_ATSCANDIDATERESUMEFILEPATH_SAVE]
    @Id INT,
    @CandidateId BIGINT,
    @ResumePath NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;

    BEGIN TRY
        BEGIN TRANSACTION;

        -- Insert into temp_trecruituploadResume
        INSERT INTO temp_trecruituploadResume (Resumeid, candidateid, ResumePath)
        VALUES (@Id, @CandidateId, @ResumePath);

        -- Update trecruituploadresume
        UPDATE trecruituploadresume
        SET ConvertToPath = 1
        WHERE id = @Id;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        ROLLBACK TRANSACTION;

        DECLARE @ErrorMessage NVARCHAR(4000);
        DECLARE @ErrorSeverity INT;
        DECLARE @ErrorState INT;

        SELECT 
            @ErrorMessage = ERROR_MESSAGE(),
            @ErrorSeverity = ERROR_SEVERITY(),
            @ErrorState = ERROR_STATE();

        RAISERROR (@ErrorMessage, @ErrorSeverity, @ErrorState);
    END CATCH
	END
GO



