/* Functional group: 07_ATS; referenced grouped tables: DTLS_ATS_SCORE, HEAD_ATS_SCORE, trecruituploadresume */
/****** Object:  StoredProcedure [dbo].[SP_SAVE_ATS_SCORE]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[SP_SAVE_ATS_SCORE]                
    @CANDIDATE_ID INT,                
    @POST_ID INT,                
    @LOCATION_ID INT,                
    @COMPANY_ID INT,                
    @DEPARTMENT_ID INT,                
    @TOTAL_SCORE DECIMAL(18, 2),
	@OBTAINED_SCORE DECIMAL(18, 2),
    @REMARKS NVARCHAR(MAX),                
    @STATUS NVARCHAR(50),                
    @BREAKDOWN_JSON NVARCHAR(MAX),                
    @DETAILS_JSON NVARCHAR(MAX)                
                    
AS                
BEGIN                
    SET NOCOUNT ON;                
    DECLARE @ATS_SCORE_ID INT;                

    BEGIN TRY                
        BEGIN TRANSACTION;                

        SELECT @ATS_SCORE_ID = ATS_SCORE_ID                
        FROM HEAD_ATS_SCORE                
        WHERE CANDIDATE_ID = @CANDIDATE_ID                
          AND ACTUAL_POST_ID = @POST_ID                
          AND LOCATION_ID = @LOCATION_ID                
          AND COMPANY_ID = @COMPANY_ID                
          AND DEPARTMENT_ID = @DEPARTMENT_ID;                

        IF @ATS_SCORE_ID IS NOT NULL                
        BEGIN                
            UPDATE HEAD_ATS_SCORE                
            SET TOTAL_SCORE = @TOTAL_SCORE,                
                OBTAIN_MARKS = @OBTAINED_SCORE,                
                REMARKS = @REMARKS,                
                STATUS = @STATUS                
            WHERE ATS_SCORE_ID = @ATS_SCORE_ID;                

            DELETE FROM DTLS_ATS_SCORE WHERE ATS_SCORE_ID = @ATS_SCORE_ID;                
        END                
        ELSE                 
        BEGIN                
            INSERT INTO HEAD_ATS_SCORE (                
                CANDIDATE_ID, ACTUAL_POST_ID, LOCATION_ID, COMPANY_ID, DEPARTMENT_ID,                
                TOTAL_SCORE, OBTAIN_MARKS, REMARKS, STATUS                
            )                
            VALUES (                
                @CANDIDATE_ID, @POST_ID, @LOCATION_ID, @COMPANY_ID, @DEPARTMENT_ID,                
                @TOTAL_SCORE, @OBTAINED_SCORE, @REMARKS, @STATUS                
            );                

            SET @ATS_SCORE_ID = SCOPE_IDENTITY();                
        END                

        -- Parse Breakdown
        DECLARE @BreakdownTable TABLE (                
            [Key] NVARCHAR(255),                
            TotalScore DECIMAL(18, 2),                
            ObtainScore DECIMAL(18, 2)                
        );                

        INSERT INTO @BreakdownTable ([Key], TotalScore, ObtainScore)                
        SELECT         
            [Key],         
            TRY_CAST(JSON_VALUE([Value], '$.Total') AS DECIMAL(18, 2)),        
            TRY_CAST(JSON_VALUE([Value], '$.Obtained') AS DECIMAL(18, 2))                
        FROM OPENJSON(@BREAKDOWN_JSON);                

        IF NOT EXISTS (SELECT 1 FROM @BreakdownTable)
            THROW 50002, 'Invalid ATS JSON: Breakdown is empty.', 1;

        -- Parse Details
        DECLARE @DetailsTable TABLE (                
            [Key] NVARCHAR(255),                
            Notes NVARCHAR(MAX),                
            CriteriaId INT                
        );                

        INSERT INTO @DetailsTable ([Key], Notes, CriteriaId)                
        SELECT                 
            [Key],                
            JSON_VALUE([Value], '$.notes'),                
            TRY_CAST(JSON_VALUE([Value], '$.id') AS INT)                
        FROM OPENJSON(@DETAILS_JSON);                

        -- Insert DTLS (STRICT JOIN)
        INSERT INTO DTLS_ATS_SCORE (        
            ATS_SCORE_ID, CRITERIA, TOTAL_SCORE, OBTAIN_SCORE, NOTES, CRITERIA_ID   
        )        
        SELECT        
            @ATS_SCORE_ID,        
            B.[Key],        
            B.TotalScore,        
            B.ObtainScore,        
            D.Notes,        
            D.CriteriaId        
        FROM @BreakdownTable B        
        INNER JOIN @DetailsTable D ON B.[Key] = D.[Key];        

        -- Validate score consistency
        DECLARE @DtlsSum DECIMAL(18,2);

        SELECT @DtlsSum = SUM(OBTAIN_SCORE)
        FROM DTLS_ATS_SCORE
        WHERE ATS_SCORE_ID = @ATS_SCORE_ID;

        IF (@DtlsSum <> @OBTAINED_SCORE)
            THROW 50001, 'ATS score mismatch: HEAD and DTLS totals differ.', 1;

        COMMIT;              

        UPDATE trecruituploadresume 
        SET ConvertToPath = 1 
        WHERE Candidateid = @CANDIDATE_ID;              

    END TRY                
    BEGIN CATCH                
        ROLLBACK;                
        THROW;                
    END CATCH             

    RETURN @ATS_SCORE_ID;        
END
GO



/* Functional group: 07_ATS; referenced grouped tables: HEAD_ATS_SCORE */
/****** Object:  StoredProcedure [dbo].[SP_SAVE_LMS_EXAM_RESULT_ATS_SCORE]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE   PROCEDURE [dbo].[SP_SAVE_LMS_EXAM_RESULT_ATS_SCORE]
    @CANDIDATE_ID INT,
    @POST_ID INT,
    @LOCATION_ID INT,
    @COMPANY_ID INT,
    @DEPARTMENT_ID INT,
    @ExamMarks DECIMAL(18,2),
    @ExamStatus NVARCHAR(50)
AS
BEGIN
    SET NOCOUNT ON;

    /*
     * LMS exam result save/update:
     * This SP only saves LMS exam fields in HEAD_ATS_SCORE.
     * ATS fields like TOTAL_SCORE and OBTAIN_MARKS are preserved.
     */
    DECLARE @ATS_SCORE_ID INT;

    SELECT @ATS_SCORE_ID = ATS_SCORE_ID
    FROM dbo.HEAD_ATS_SCORE
    WHERE CANDIDATE_ID = @CANDIDATE_ID
      AND ACTUAL_POST_ID = @POST_ID
      AND LOCATION_ID = @LOCATION_ID
      AND COMPANY_ID = @COMPANY_ID
      AND DEPARTMENT_ID = @DEPARTMENT_ID;

    IF @ATS_SCORE_ID IS NOT NULL
    BEGIN
        UPDATE dbo.HEAD_ATS_SCORE
        SET
            ExamMarks = @ExamMarks,
            ExamStatus = @ExamStatus
        WHERE ATS_SCORE_ID = @ATS_SCORE_ID;
    END
    ELSE
    BEGIN
        INSERT INTO dbo.HEAD_ATS_SCORE
        (
            CANDIDATE_ID,
            ACTUAL_POST_ID,
            LOCATION_ID,
            COMPANY_ID,
            DEPARTMENT_ID,
            ExamMarks,
            ExamStatus
        )
        VALUES
        (
            @CANDIDATE_ID,
            @POST_ID,
            @LOCATION_ID,
            @COMPANY_ID,
            @DEPARTMENT_ID,
            @ExamMarks,
            @ExamStatus
        );

        SET @ATS_SCORE_ID = SCOPE_IDENTITY();
    END

    SELECT @ATS_SCORE_ID AS ATS_SCORE_ID;
END
GO



