/* Functional group: 07_ATS; referenced grouped tables: HEAD_ATS_SCORE, tbl_RecruiterInterviewersSchedule, trecruitcanbasicdtls, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[GetCustomersPageWisetest]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
CREATE PROCEDURE [dbo].[GetCustomersPageWisetest]  
    @startdate VARCHAR(50) = NULL,  
    @enddate VARCHAR(50) = NULL,  
 @ATSStatus varchar(100)=null  
AS  
BEGIN  
    SET NOCOUNT ON;  
  
    SELECT      
        ROW_NUMBER() OVER (ORDER BY A.[registrationnumber] DESC) AS RowNumber,  
        A.[registrationnumber],   
        CASE WHEN EXISTS (SELECT 1 FROM tbl_RecruiterInterviewersSchedule   
                          WHERE CandidateRegistrationNumber = A.registrationnumber AND InterviewersRoundNo = 1) THEN 1 ELSE 0 END AS InterviewerRound1,  
        CASE WHEN EXISTS (SELECT 1 FROM tbl_RecruiterInterviewersSchedule   
                          WHERE CandidateRegistrationNumber = A.registrationnumber AND InterviewersRoundNo = 2) THEN 1 ELSE 0 END AS InterviewerRound2,  
        CASE WHEN EXISTS (SELECT 1 FROM tbl_RecruiterInterviewersSchedule   
                          WHERE CandidateRegistrationNumber = A.registrationnumber AND InterviewersRoundNo = 3) THEN 1 ELSE 0 END AS InterviewerRound3,  
        CASE WHEN EXISTS (SELECT 1 FROM tbl_RecruiterInterviewersSchedule   
                          WHERE CandidateRegistrationNumber = A.registrationnumber AND InterviewersRoundNo = 4) THEN 1 ELSE 0 END AS InterviewerRound4,  
  
        A.[backgroundcheck],  
        A.[aplicationdate],  
        A.[username],  
        A.[rscandidateid],  
        A.[rscandidatename] AS candidatename,  
        A.[resumefile],  
        A.[applicationstatus],  
        CASE   
            WHEN A.[applicationstatus] = 'RESUBMIT' THEN 'No'           
            WHEN A.[applicationstatus] = 'SUBMITTED' THEN 'Yes'           
            ELSE NULL         
        END AS ResubmitStatus,      
        A.[rspostname] AS postname,  
        A.[rspostid],  
        A.[rslocid],  
        A.[location],  
        A.[deptdivision],  
        UPPER(A.[referredus]) AS referredus,  
        UPPER(A.[ReferredOthertext]) AS ReferredOthertext,  
        A.[trakerid],  
        A.[referenceno],  
        A.[departmentdivision],  
        A.[departmentdivisonname],  
        A.[rtpostid],  
        A.[rtpostname],  
        A.[rtlocid],  
        A.[headq],  
        A.[rtcandidateid],  
        A.[rtcandidatename],  
        A.[source],  
        A.[STARTDATE],  
        A.[cvselected],  
        A.[manualupdate],  
        A.[roneinterviewdate],  
        A.[roneinterviewernameone],  
        A.[roneinterviewernametwo],  
        A.[roneselect],  
        A.[roneinterviewenddate],  
        A.[rtwointerviewdate],  
        A.[rtwointerviewernameone],  
        A.[rtwointerviewernametwo],  
        A.[rtwoselect],  
        A.[rtwointerviewenddate],  
        A.[rthreeinterviewdate],  
        A.[rthreeinterviewernameone],  
        A.[rthreeinterviewernametwo],  
        A.[rthreeselect],  
        A.[rthreeinterviewenddate],  
        A.[frinterviewdate],  
        A.[frinterviewernameone],  
        A.[frinterviewernametwo],  
        A.[frselect],  
        A.[Frinterviewenddate],  
        A.[doo],  
        A.[doj],  
        A.[empcode],  
        A.[completionstatus],  
        A.[timetaken],  
        A.[remarks],  
        A.[createdby],  
        A.[modifiedby],  
        A.[modifiedtime],  
        A.[rofileid],  
        A.[rocandidateid],  
        A.[rofname],  
        A.[rofcontenttype],  
        A.[rofresumefile],  
        A.[ronerone],  
        A.[rosname],  
        A.[roscontenttype],  
        A.[rosresumefile],  
        A.[ronertwo],  
        A.[rtwfileid],  
        A.[rtwcandidateid],  
        A.[rtwfname],  
        A.[rtwfcontenttype],  
        A.[rtwfresumefile],  
        A.[rtworone],  
        A.[rtwsname],  
        A.[rtwscontenttype],  
        A.[rtwsresumefile],  
        A.[rtwortwo],  
        A.[rthfileid],  
        A.[rthcandidateid],  
        A.[rthfname],  
        A.[rthfcontenttype],  
        A.[rthfresumefile],  
        A.[rthworone],  
        A.[rthsname],  
        A.[rthscontenttype],  
        A.[rthsresumefile],  
        A.[rthwortwo],  
        A.[fileid],  
        A.[rfcandidateid],  
        A.[fname],  
        A.[fcontenttype],  
        A.[fresumefile],  
        A.[rfworone],  
        A.[sname],  
        A.[scontenttype],  
        A.[sresumefile],  
        A.[rfwortwo],  
        A.[createdtime],  
        A.[docsubmissionallow],  
  
        -- 🟢 New Column: ATS Status  
        CASE   
   WHEN H.STATUS = 'Shortlisted' THEN 'Shortlisted'  
   WHEN H.STATUS = 'Rejected' THEN 'Rejected'  
   ELSE 'Not Available'  
  END AS ATSStatus  
  
    FROM [dbo].[vw_rcalldata] A  
    LEFT JOIN trecruitpostlocationmap C ON A.rspostid = C.postid AND A.rslocid = C.locid         
    LEFT JOIN trecruitcanbasicdtls B ON A.registrationnumber = B.registrationnumber  
    LEFT JOIN HEAD_ATS_SCORE H ON B.candidateid = H.CANDIDATE_ID  
  
    WHERE CONVERT(DATETIME, CONVERT(VARCHAR, CONVERT(DATETIME, A.[aplicationdate], 103), 101), 111)                                             
          BETWEEN CONVERT(DATETIME, CONVERT(VARCHAR, CONVERT(DATETIME, @startdate, 103), 101), 111)                                              
          AND CONVERT(DATETIME, CONVERT(VARCHAR, CONVERT(DATETIME, @enddate, 103), 101), 111)      
    AND (  
    @ATSStatus = 'ALL LIST'  
    OR (H.STATUS = 'Shortlisted' OR H.STATUS IS NULL)  
   )  
          AND A.rspostname NOT LIKE 'ASSOCIATE%'               
    GROUP BY   
        A.[registrationnumber], A.[backgroundcheck], A.[aplicationdate], A.[username], A.[rscandidateid], A.[rscandidatename],  
        A.[resumefile], A.[applicationstatus], A.[rspostname], A.[rspostid], A.[rslocid], A.[location], A.[deptdivision],  
        A.[referredus], A.[ReferredOthertext], A.[trakerid], A.[referenceno], A.[departmentdivision], A.[departmentdivisonname],  
        A.[rtpostid], A.[rtpostname], A.[rtlocid], A.[headq], A.[rtcandidateid], A.[rtcandidatename], A.[source], A.[STARTDATE],  
        A.[cvselected], A.[manualupdate], A.[roneinterviewdate], A.[roneinterviewernameone], A.[roneinterviewernametwo], A.[roneselect],  
        A.[roneinterviewenddate], A.[rtwointerviewdate], A.[rtwointerviewernameone], A.[rtwointerviewernametwo], A.[rtwoselect],  
        A.[rtwointerviewenddate], A.[rthreeinterviewdate], A.[rthreeinterviewernameone], A.[rthreeinterviewernametwo], A.[rthreeselect],  
        A.[rthreeinterviewenddate], A.[frinterviewdate], A.[frinterviewernameone], A.[frinterviewernameone], A.[frinterviewernameone],A.[frinterviewernametwo],  
        A.[frselect], A.[Frinterviewenddate], A.[doo], A.[doj], A.[empcode], A.[completionstatus], A.[timetaken], A.[remarks],  
        A.[createdby], A.[modifiedby], A.[modifiedtime], A.[rofileid], A.[rocandidateid], A.[rofname], A.[rofcontenttype],  
        A.[rofresumefile], A.[ronerone], A.[rosname], A.[roscontenttype], A.[rosresumefile], A.[ronertwo], A.[rtwfileid],  
        A.[rtwcandidateid], A.[rtwfname], A.[rtwfcontenttype], A.[rtwfresumefile], A.[rtworone], A.[rtwsname], A.[rtwscontenttype],  
        A.[rtwsresumefile], A.[rtwortwo], A.[rthfileid], A.[rthcandidateid], A.[rthfname], A.[rthfcontenttype], A.[rthfresumefile],  
        A.[rthworone], A.[rthsname], A.[rthscontenttype], A.[rthsresumefile], A.[rthwortwo], A.[fileid], A.[rfcandidateid],  
        A.[fname], A.[fcontenttype], A.[fresumefile], A.[rfworone], A.[sname], A.[scontenttype], A.[sresumefile],  
        A.[rfwortwo], A.[createdtime], A.[docsubmissionallow], H.STATUS  
END  
  
  
  
GO



