/* Functional group: 07_ATS; referenced grouped tables: BulkResumeAtsScoreLog, DTLS_ATS_SCORE, HEAD_ATS_SCORE, trecruitappliedpost, trecruitcanbasicdtls, trecruitcandidateresgisterdtls, trecruitcandidatesignup */
/****** Object:  StoredProcedure [dbo].[PRC_GET_ATS_RATING_CANDIDATED_TEST]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[PRC_GET_ATS_RATING_CANDIDATED_TEST]
    @candidatedID NVARCHAR(MAX)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @columnsPercentage NVARCHAR(MAX),
            @columnsHtml NVARCHAR(MAX),
            @totalCol NVARCHAR(MAX),
            @sql NVARCHAR(MAX),
            @MaxTotalMark DECIMAL(18,2),
            @ExamAvailable INT = 0,
            @ExamTaggingID BIGINT = 0;

    IF @candidatedID IS NULL OR @candidatedID = ''
    BEGIN
        RAISERROR('Candidate ID is mandatory.',16,1);
        RETURN;
    END

    ---------------------------------------------------------
    -- Get ExamTaggingID for Normal Candidate
    ---------------------------------------------------------
    SELECT TOP (1)
        @ExamTaggingID = ISNULL(C.ExamTaggingID,0)
    FROM trecruitcandidatesignup A
    INNER JOIN trecruitcandidateresgisterdtls B
        ON B.UserName = A.UserName
    INNER JOIN trecruitappliedpost C
        ON C.PostID = B.IDPost
    WHERE A.CandidateID = @candidatedID;

    ---------------------------------------------------------
    -- ATS Candidate
    ---------------------------------------------------------
    IF ISNULL(@ExamTaggingID,0) = 0
    BEGIN
        SELECT TOP (1)
            @ExamTaggingID = ISNULL(P.ExamTaggingID,0)
        FROM BulkResumeAtsScoreLog BL
        INNER JOIN trecruitappliedpost P
            ON P.PostID = BL.POST_ID
        WHERE BL.CANDIDATE_ID = @candidatedID
        ORDER BY BL.CREATED_DATE DESC;
    END

    SET @ExamAvailable =
        CASE
            WHEN ISNULL(@ExamTaggingID,0) = 0 THEN 0
            ELSE 1
        END;

    ---------------------------------------------------------
    -- Total Marks
    ---------------------------------------------------------
    SELECT TOP 1
        @MaxTotalMark = H.TOTAL_SCORE
    FROM HEAD_ATS_SCORE H
    WHERE H.CANDIDATE_ID = @candidatedID;

    SET @totalCol =
        'MAX(CAST(ROUND(100.0 * OBTAIN_SCORE / ' +
        CAST(@MaxTotalMark AS VARCHAR(20)) +
        ',1) AS VARCHAR)) AS TOTAL_SCORE';

    ---------------------------------------------------------
    -- Percentage Columns
    ---------------------------------------------------------
    SELECT
        @columnsPercentage =
            STRING_AGG(
                'MAX(CASE WHEN Criteria = ''' + CRITERIA +
                ''' THEN CAST(ROUND(100.0 * Score / RatingMarks,1) AS VARCHAR) ELSE '''' END) AS [' +
                CRITERIA + ']',
                ','
            )
    FROM
    (
        SELECT DISTINCT
            D.CRITERIA + ' (' + CAST(D.TOTAL_SCORE AS VARCHAR) + ')' AS CRITERIA
        FROM HEAD_ATS_SCORE H
        INNER JOIN DTLS_ATS_SCORE D
            ON D.ATS_SCORE_ID = H.ATS_SCORE_ID
        WHERE H.CANDIDATE_ID = @candidatedID
    ) X;

    ---------------------------------------------------------
    -- HTML Columns
    ---------------------------------------------------------
    SELECT
        @columnsHtml =
            STRING_AGG(
                'MAX(CASE WHEN Criteria = ''' + CRITERIA +
                ''' THEN ''<span class="score-cell" data-notes="'' +
                REPLACE(ISNULL(Notes, ''''), CHAR(34), '''') +
                ''">'' + CAST(Score AS VARCHAR) +
                ''</span>'' ELSE '''' END) AS [' +
                CRITERIA + ']',
                ','
            )
    FROM
    (
        SELECT DISTINCT
            D.CRITERIA + ' (' + CAST(D.TOTAL_SCORE AS VARCHAR) + ')' AS CRITERIA
        FROM HEAD_ATS_SCORE H
        INNER JOIN DTLS_ATS_SCORE D
            ON D.ATS_SCORE_ID = H.ATS_SCORE_ID
        WHERE H.CANDIDATE_ID = @candidatedID
    ) X;

    ---------------------------------------------------------
    -- Dynamic SQL
    ---------------------------------------------------------
    SET @sql = '

    -- RESULT SET 1
    SELECT
        MAX(CandidateName) AS CANDIDATE_NAME,
        ' + @totalCol + ',
        ' + @columnsPercentage + ',
        MAX(STATUS) AS Status,
        ' + CAST(@ExamAvailable AS VARCHAR(10)) + ' AS ExamAvailable,
        ' + CAST(@ExamTaggingID AS VARCHAR(20)) + ' AS ExamTaggingID
    FROM
    (
        SELECT
            H.CANDIDATE_ID,

            COALESCE(
                NULLIF(
                    LTRIM(RTRIM(
                        ISNULL(BAC.firstname, '''') + '' '' +
                        ISNULL(BAC.middlename, '''') + '' '' +
                        ISNULL(BAC.lastname, '''')
                    )),
                    ''''
                ),
                BL.CANDIDATE_NAME
            ) AS CandidateName,

            D.OBTAIN_SCORE AS Score,
            D.NOTES,
            D.TOTAL_SCORE AS RatingMarks,
            D.CRITERIA + '' ('' + CAST(D.TOTAL_SCORE AS VARCHAR) + '')'' AS Criteria,
            H.OBTAIN_MARKS AS OBTAIN_SCORE,
            H.STATUS

        FROM HEAD_ATS_SCORE H

        INNER JOIN DTLS_ATS_SCORE D
            ON D.ATS_SCORE_ID = H.ATS_SCORE_ID

        LEFT JOIN trecruitcanbasicdtls BAC
            ON BAC.candidateid = H.CANDIDATE_ID

        LEFT JOIN BulkResumeAtsScoreLog BL
            ON BL.CANDIDATE_ID = H.CANDIDATE_ID

        WHERE H.CANDIDATE_ID = ''' + @candidatedID + '''
    ) AS SourceTable
    GROUP BY CANDIDATE_ID;

    -- RESULT SET 2
    SELECT
        CANDIDATE_ID,
        ' + @columnsHtml + ',
        MAX(STATUS) AS Status,
        ' + CAST(@ExamAvailable AS VARCHAR(10)) + ' AS ExamAvailable,
        ' + CAST(@ExamTaggingID AS VARCHAR(20)) + ' AS ExamTaggingID
    FROM
    (
        SELECT
            H.CANDIDATE_ID,
            D.OBTAIN_SCORE AS Score,
            D.NOTES,
            D.CRITERIA + '' ('' + CAST(D.TOTAL_SCORE AS VARCHAR) + '')'' AS Criteria,
            H.STATUS

        FROM HEAD_ATS_SCORE H

        INNER JOIN DTLS_ATS_SCORE D
            ON D.ATS_SCORE_ID = H.ATS_SCORE_ID

        LEFT JOIN trecruitcanbasicdtls BAC
            ON BAC.candidateid = H.CANDIDATE_ID

        LEFT JOIN BulkResumeAtsScoreLog BL
            ON BL.CANDIDATE_ID = H.CANDIDATE_ID

        WHERE H.CANDIDATE_ID = ''' + @candidatedID + '''
    ) AS SourceTable
    GROUP BY CANDIDATE_ID;
    ';

    EXEC sp_executesql @sql;
END
GO



/* Functional group: 07_ATS; referenced grouped tables: BulkResumeAtsScoreLog, Company, HEAD_ATS_SCORE, trecruitappliedpost, trecruitcanbasicdtls, trecruitpostlocation, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[PRC_GET_ATS_RATING_TEST]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[PRC_GET_ATS_RATING_TEST]
    @companyID NVARCHAR(MAX) = NULL,
    @depID NVARCHAR(MAX) = NULL,
    @postID NVARCHAR(MAX) = NULL,
    @status NVARCHAR(MAX) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @totalCol NVARCHAR(MAX),
            @sql NVARCHAR(MAX);

    SET @totalCol =
    'MAX(CASE
        WHEN OBTAIN_SCORE IS NOT NULL THEN
            ''<span class="score-cell" data-notes="'' +
            REPLACE(ISNULL(Remarks, ''''), CHAR(34), '''') +
            ''">'' + CAST(OBTAIN_SCORE AS VARCHAR(50)) +
            ''</span>''
        ELSE ''''
      END) AS [OBTAINED MARKS]';

    SET @sql = '
    SELECT
        CANDIDATE_ID,
        CandidateName AS NAME,
        Company COMPANY,
        Postname POST,
        Location LOCATION,
        aplicationdate AS [APPLICATION DATE],
        ' + @totalCol + ',
        TOTAL_SCORE AS [TOTAL MARKS],
        Status AS STATUS,
        Status_int,
        aplicationdate_int
    FROM
    (
        SELECT
            H.CANDIDATE_ID,

            COALESCE(
                NULLIF(
                    LTRIM(RTRIM(
                        ISNULL(UPPER(bac.firstname), '''') + '' '' +
                        ISNULL(UPPER(bac.middlename), '''') + '' '' +
                        ISNULL(UPPER(bac.lastname), '''')
                    )),
                    ''''
                ),
                UPPER(ISNULL(bl.CANDIDATE_NAME, ''''))
            ) AS CandidateName,

            C.Company,
            P.Postname,
            L.location AS Location,

            H.TOTAL_SCORE,
            H.OBTAIN_MARKS AS OBTAIN_SCORE,
            H.REMARKS AS Remarks,

            CONVERT(VARCHAR(10),
                COALESCE(bac.aplicationdate, bl.CREATED_DATE),
            103) AS aplicationdate,

            CONVERT(INT,
                CONVERT(CHAR(8),
                    TRY_CAST(COALESCE(bac.aplicationdate, bl.CREATED_DATE) AS DATE),
                112)
            ) AS aplicationdate_int,

            H.STATUS AS Status,

            CASE
                WHEN H.STATUS = ''Shortlisted'' THEN 1
                ELSE 2
            END AS Status_int

        FROM HEAD_ATS_SCORE H

        LEFT JOIN trecruitcanbasicdtls bac
            ON bac.candidateid = H.CANDIDATE_ID

        LEFT JOIN BulkResumeAtsScoreLog bl
            ON bl.CANDIDATE_ID = H.CANDIDATE_ID

        INNER JOIN Company C
            ON C.companyPK = H.COMPANY_ID

        INNER JOIN trecruitappliedpost P
            ON P.ActualPostID = H.ACTUAL_POST_ID
            AND P.IDCompany = H.COMPANY_ID
            AND P.Deptid = H.DEPARTMENT_ID

        INNER JOIN trecruitpostlocation L
            ON L.locid = H.LOCATION_ID

        INNER JOIN trecruitpostlocationmap map
            ON P.postid = map.postid
            AND map.locid = H.LOCATION_ID
            AND P.IDCompany = H.COMPANY_ID
            AND P.Deptid = H.DEPARTMENT_ID

        WHERE
            (@companyID IS NULL
                OR C.companyPK IN (
                    SELECT CAST(Name AS INT)
                    FROM dbo.splitstring(@companyID)
                )
            )

            AND (@depID IS NULL
                OR P.Deptid IN (
                    SELECT CAST(Name AS INT)
                    FROM dbo.splitstring(@depID)
                )
            )

            AND (' +
            CASE
                WHEN @status IS NULL OR @status = 'SELECT STATUS'
                    THEN '1 = 1'
                ELSE 'H.STATUS = ''' + REPLACE(@status, '''', '''''') + ''''
            END + ')

            AND (@postID IS NULL
                OR P.postid IN (
                    SELECT CAST(Name AS INT)
                    FROM dbo.splitstring(@postID)
                )
            )
    ) AS SourceTable

    GROUP BY
        CANDIDATE_ID,
        CandidateName,
        Company,
        Postname,
        Location,
        TOTAL_SCORE,
        OBTAIN_SCORE,
        Status,
        Status_int,
        aplicationdate,
        aplicationdate_int

    ORDER BY
        Status_int,
        aplicationdate_int DESC;
    ';

    EXEC sp_executesql
        @sql,
        N'@companyID NVARCHAR(MAX),
          @depID NVARCHAR(MAX),
          @postID NVARCHAR(MAX)',
        @companyID = @companyID,
        @depID = @depID,
        @postID = @postID;
END
GO



