GO
SET QUOTED_IDENTIFIER ON
GO

CREATE   PROCEDURE [dbo].[PRC_SAVE_BULK_RESUME_TEMP_CANDIDATE_DETAILS]
    @CandidateID BIGINT,
    @CandidateFirstName NVARCHAR(MAX) = NULL,
    @CandidateMiddleName NVARCHAR(MAX) = NULL,
    @CandidateLastName NVARCHAR(MAX) = NULL,
    @DateOfBirth NVARCHAR(MAX) = NULL,
    @Address NVARCHAR(MAX) = NULL,
    @CityOrVillage NVARCHAR(MAX) = NULL,
    @PostOffice NVARCHAR(MAX) = NULL,
    @PinCode NVARCHAR(MAX) = NULL,
    @Country NVARCHAR(MAX) = NULL,
    @State NVARCHAR(MAX) = NULL,
    @District NVARCHAR(MAX) = NULL,
    @Email NVARCHAR(MAX) = NULL,
    @Mobile NVARCHAR(MAX) = NULL,
    @AnyProject NVARCHAR(MAX) = NULL,
    @NumberOfCompanyChanges NVARCHAR(MAX) = NULL,
    @ResumeContentType NVARCHAR(MAX) = NULL,
    @ResumeFileName NVARCHAR(MAX) = NULL,
    @ResumeFile VARBINARY(MAX) = NULL,
    @QualificationJison NVARCHAR(MAX) = NULL
AS
BEGIN
    SET NOCOUNT ON;

    IF EXISTS (SELECT 1 FROM dbo.TempCandidateDetails WHERE CandidateID = @CandidateID)
    BEGIN
        DELETE FROM dbo.TempCandidateDetails WHERE CandidateID = @CandidateID;
    END

    INSERT INTO dbo.TempCandidateDetails
    (
        CandidateID,
        CandidateFirstName,
        CandidateMiddleName,
        CandidateLastName,
        DateOfBirth,
        Address,
        CityOrVillage,
        PostOffice,
        PinCode,
        Country,
        State,
        District,
        Email,
        Mobile,
        AnyProject,
        NumberOfCompanyChanges,
        ResumeContentType,
        ResumeFileName,
        Resumefile,
        QualificationJison
    )
    VALUES
    (
        @CandidateID,
        @CandidateFirstName,
        @CandidateMiddleName,
        @CandidateLastName,
        @DateOfBirth,
        @Address,
        @CityOrVillage,
        @PostOffice,
        @PinCode,
        @Country,
        @State,
        @District,
        @Email,
        @Mobile,
        @AnyProject,
        @NumberOfCompanyChanges,
        @ResumeContentType,
        @ResumeFileName,
        @ResumeFile,
        @QualificationJison
    );
END
GO



/* Functional group: 07_ATS; referenced grouped tables: TempCandidateDetails, trecruitcandidatesignup, trecruitcanlanguage, trecruitProjectDetails, trecruituploadresume */
/****** Object:  StoredProcedure [dbo].[PRC_TEMP_CANDIDATE_DETAILS]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[PRC_TEMP_CANDIDATE_DETAILS]           
@username VARCHAR(MAX),          
@CandidateFirstName nvarchar(max)=NULL,                
@CandidateMiddleName nvarchar(max)=NULL,               
 @CandidateLastName nvarchar(max)=NULL,               
 @DateOfBirth nvarchar(max)=NULL,               
 @Address nvarchar(max)=NULL,           
         
 @CityOrVillage nvarchar(max)=null,        
 @PostOffice nvarchar(max)=null,        
        
 @PinCode  nvarchar(max)=NULL,          
 @Country  nvarchar(max)=NULL,          
 @State  nvarchar(max)=NULL,          
 @District  nvarchar(max)=NULL,          
          
 @Email nvarchar(max)=NULL,               
 @Mobile nvarchar(max)=NULL,             
 @AnyProject nvarchar(max)=NULL,          
 @NumberOfCompanyChanges nvarchar(max)=NULL,          
          
 @ResumeData         VARBINARY(max)=null,           
 @ResumeContentType  NVARCHAR(max)=null,                         
 @ResumeName         nvarchar(max)=null,                         
               
  @LanguageKnown nvarchar(max)=null,          
  @Qualification nvarchar(max)=null,          
          
 @Action varchar(max),          
 @status VARCHAR(MAX) = NULL OUTPUT                
AS                
BEGIN                
     DECLARE @CandidateID VARCHAR(200)           
     SELECT @CandidateID = [candidateid]                                                       
          FROM   [dbo].[trecruitcandidatesignup]                                                       
          WHERE  [username] = @username           
          
    BEGIN TRY                
        BEGIN TRANSACTION;                
         if(@Action='INSERT')          
    begin          
          
    if exists(SELECT 1  FROM TempCandidateDetails WHERE CandidateID =@CandidateID)          
    BEGIN           
      DELETE TempCandidateDetails          
      WHERE CandidateID =@CandidateID          
          
      DELETE trecruitcanlanguage          
      WHERE candidateid=@CandidateID          
          
          
      DELETE trecruituploadresume WHERE candidateid=@CandidateID          
        
   DELETE FROM trecruitProjectDetails WHERE CandidateID = @CandidateID;        
        
    END            
         
    INSERT INTO TempCandidateDetails (          
     CandidateID,          
     CandidateFirstName,          
     CandidateMiddleName,          
     CandidateLastName,          
     DateOfBirth,          
     Address,          
     CityOrVillage,         
  PostOffice,        
      PinCode,          
      Country,          
      State,          
      District,          
     Email,          
     Mobile,          
     NumberOfCompanyChanges,          
     ResumeContentType,          
     ResumeFileName,          
     Resumefile,          
     QualificationJison          
    )          
    VALUES (          
     @CandidateID,          
     @CandidateFirstName,          
     @CandidateMiddleName,          
     @CandidateLastName,          
     @DateOfBirth,          
     @Address,          
     @CityOrVillage,         
  @PostOffice,        
     @PinCode,            
     @Country,           
     @State,            
     @District,          
     @Email,          
     @Mobile,            
     @NumberOfCompanyChanges,          
     @ResumeContentType,          
     @ResumeName,          
     @ResumeData,          
     @Qualification          
    );          
          
          
    INSERT INTO trecruitcanlanguage          
(candidateid, languagename, lread, lwrite, lspeak)           
SELECT @CandidateID, rtrim(ltrim(Name)), 'Yes', 'Yes', 'Yes'      
FROM dbo.splitstring(@LanguageKnown)      
WHERE @LanguageKnown IS NOT NULL AND LTRIM(RTRIM(Name)) <> ''       
          
      IF ISJSON(@AnyProject) = 1        
   BEGIN        
   INSERT INTO trecruitProjectDetails (CandidateID, AnyProject)        
   SELECT @CandidateID, value        
   FROM OPENJSON(@AnyProject);        
        
  END        
     
        SET @status=1          
    end          
    else if(@Action='SELECT')          
       begin          
            SELECT          
            CandidateID,          
     CandidateFirstName,          
     CandidateMiddleName,          
     CandidateLastName,          
     DateOfBirth,          
     Address,          
     CityOrVillage,      
  PostOffice,      
     PinCode,          
     Country,          
     State,          
     District,          
     Email,          
     Mobile,          
     AnyProject,          
     NumberOfCompanyChanges,          
     ResumeFileName,          
     ResumeContentType,            
     Resumefile          
  FROM          
     TempCandidateDetails          
     WHERE CandidateID =@CandidateID          
    end          
          else if(@Action='SELECT_QUALIFICATION')          
    begin          
                 
     DECLARE @json NVARCHAR(MAX)          
     SELECT @json = QualificationJison          
     FROM TempCandidateDetails          
     WHERE CandidateID = @CandidateID;          
          
     SELECT 
        EducationName,
        Specialization,
        SubjectCombination,
        '' AS StartingYear,
        '' AS YearOfPassing,
        InstituteName,
        UniversityName,
        PercentageOrDivisionOrDGPA
     FROM OPENJSON(@json)          
     WITH (          
     EducationName NVARCHAR(100),          
     Specialization NVARCHAR(100),          
     SubjectCombination NVARCHAR(100),          
     StartingYear NVARCHAR(20),          
     YearOfPassing NVARCHAR(20),          
     InstituteName NVARCHAR(200),          
     UniversityName NVARCHAR(200),          
     PercentageOrDivisionOrDGPA NVARCHAR(50)          
     );          
    end          
        COMMIT TRANSACTION                
    END TRY                
    BEGIN CATCH                
        ROLLBACK TRANSACTION                
        SET @status = 'An error occurred: ' + ERROR_MESSAGE()                
    END CATCH                
END   
  
 
GO





