      VALUES      ( @candidateid, 
                    @postid, 
                    @postname, 
                    @locid, 
                    @candidateid, 
                    @icndidatename, 
                    @finterviewerid, 
                    @sinterviewerid, 
                    @interviewtime, 
                    @interviewdate, 
                    @interviewmode, 
