                   [modifiedby], 
                   [createddate], 
                   [modifieddate], 
                   [isactive]) 
      VALUES      ( @postid, 
                    @postname, 
                    @locid, 
                    @candidateid, 
                    @icndidatename, 
                    7, 
                    1, 
                    @candidateid, 
                    @finterviewerid, 
                    @sinterviewerid, 
                    @interviewtime, 
                    @interviewdate, 
                    @interviewmode, 
                    1, 
                    @interviewround, 
                    @intlocation, 
                    @username, 
                    @username, 
                    Getdate(), 
                    Getdate(), 
                    1 ) 
  END 
