                             AND allPost.locid IN (SELECT Name FROM dbo.splitstring(@LocationId))          
                        THEN 1 ELSE 0 END          
          
-- For Date                 
       WHEN @Date IS NOT NULL AND @Week IS NULL AND @DeptId IS NULL AND @PostId IS NULL AND @LocationId IS NULL THEN          
     CASE WHEN     
