/* Functional group: 09_OFFER_APPOINTMENT_ONBOARDING; referenced grouped tables: tcandidateappointmentmapping */
/****** Object:  StoredProcedure [dbo].[PRC_SAAS_Sync_Data]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[PRC_SAAS_Sync_Data]    
AS      
BEGIN    

    DECLARE @Total INT = 0      

    SELECT @Total = ISNULL(COUNT(A.CandidateID),0)    
    FROM tcandidateappointmentmapping A    
    WHERE A.DeleteFlag = 'No'       
      AND A.EmpNo IS NOT NULL 
      AND (A.IsMigratedEsspSaas = 0 OR A.IsMigratedEsspSaas IS NULL)
      --AND A.SyncYN = 'N'    
      
    SELECT 
        ROW_NUMBER() OVER (ORDER BY A.CandidateID) AS SRL,    
        A.CandidateID,
        A.EmpNo,
		A.TenantID,
        @Total AS TotalRecords    
    FROM tcandidateappointmentmapping A    
    WHERE A.DeleteFlag = 'No'       
      AND A.EmpNo IS NOT NULL      
      AND (A.IsMigratedEsspSaas = 0 OR A.IsMigratedEsspSaas IS NULL)
    ORDER BY A.CandidateID     

END
GO



/* Functional group: 09_OFFER_APPOINTMENT_ONBOARDING; referenced grouped tables: tcandidateappointmentmapping */
/****** Object:  StoredProcedure [dbo].[PRC_Sync_Data]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
Create Proc [dbo].[PRC_Sync_Data]  
as    
Begin  
  Declare @Total Int=0    
  Select @Total=Isnull(count(A.candidateid),0)  
  from tcandidateappointmentmapping  A  
  where A.deleteflag='No'     
  and  A.empno is not null    
  and  A.SyncYN='N'  
    
  Select Row_Number() Over (Order By A.CandidateId ) SRL,  
    A.CandidateID,A.Empno ,@Total TotalRecords  
  from tcandidateappointmentmapping  A  
  where A.deleteflag='No'     
  and  A.empno is not null    
  and  A.SyncYN='N'  
  Order By A.CandidateId   
End
GO



/* Functional group: 09_OFFER_APPOINTMENT_ONBOARDING; referenced grouped tables: tcandidateappointmentmapping */
