/* Functional group: 09_OFFER_APPOINTMENT_ONBOARDING; referenced grouped tables: tcandidateappointmentmapping, temployeehistory_sales, tEmploymentHistory */
/****** Object:  StoredProcedure [dbo].[proc_GetDocumentPerformanceReview]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[proc_GetDocumentPerformanceReview]            
  @empno int           
AS            
BEGIN      
  

  
 
--Select DISTINCT empno,candidateid from [Recruitment].[dbo].[tcandidateappointmentmapping]  Where empno=100277
Select DISTINCT B.durationform,B.durationto,B.designation,B.grosssalary  
from [tcandidateappointmentmapping] A  
Inner JOIN tEmploymentHistory B on B.candidateid=A.candidateid
Where A.empno=@empno
UNION ALL
Select DISTINCT B.durationform,B.durationto,B.designation,B.grosssalary  
from [tcandidateappointmentmapping] A  
Inner JOIN temployeehistory_sales B on B.candidateid=A.candidateid
Where A.empno=@empno
 END
GO



