/* Functional group: 09_OFFER_APPOINTMENT_ONBOARDING; referenced grouped tables: tcandidateappointmentmapping, tofferlatterdtls, trecruitcanbasicdtls */
/****** Object:  StoredProcedure [dbo].[procappointmentdtls]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[procappointmentdtls]
@action varchar(max),
@candidateid int=null
as
begin
 if(@action = 'AVLOFFER')
 begin
  Select cast( a.candidateid as varchar(10))+'/'+offerdcompanycode candidateid,
  [firstname]+' '+[middlename]+' '+[lastname]+'-'+[offerrefno] avalibleoffer
  from [dbo].[tofferlatterdtls]a,[trecruitcanbasicdtls] b
  where isexpired='No'
  and deleteflag='No'
  and [acceptancestatus]='Accepted'
  and a.candidateid=b.candidateid
  and a.candidateid not in(Select candidateid from tcandidateappointmentmapping where deleteflag='No')
 end
 if(@action ='SELECTOFFERLETTER')
 begin
   Select [offerrefno],
   [postinglocationid],
   convert(varchar,[joiningdate],103)[joiningdate],
   convert(varchar,[aplicationdate],103)[aplicationdate],
   [offerdcompanycode],
   [stipend],
   [trainingallowance],
   [conveyanceallowance],
   [firstname],
   [middlename],
   [lastname],
   convert(varchar,[dateofbirth],103)[dateofbirth],
   [mobile]
   from  [tofferlatterdtls]a ,[trecruitcanbasicdtls] b
   where 
   a.acceptancestatus='Accepted'
   and a.isexpired='No'
   and a.deleteflag='No'
   and a.candidateid=b.candidateid
   and a.candidateid=@candidateid
 end

end
GO



