         values  
         (  
           @candidateid,  
     'MLEXPFIELD',  
           @appointmentrefno,  
           @offerefno,  
     'ML',  
           convert(date,@appiontmentissudate,103),  
           @candidatename,  
           @candidateaddress,  
           @appointpostid,  
     @appointdeptid,  
     @appointdesignationid,  
              @subject,  
           convert(date,@joiningdate,103),  
     @hqallowance,  
     @exstationallowance,  
     @transitallowance,  
     @outstationallowance,  
     @meetingortrainingallowance,  
     @km0to25expences,  
     @km26to75expences,  
     @km76to150expences,  
     @km151to250expences,  
     @km251to500expences,  
     @km500onwardsexpences,  
           @joininglocid,  
           @para1,  
           @para2,  
           @para3,  
           @para4,  
           @para5,  
           @para6,  
           @para7,  
           @para8,  
           @para9,  
           @para10,  
     @para11,  
     @para12,  
     @para13,  
           'No',  
           @username,  
           GETDATE(),  
     @noticeperiod,  
     @undershine  
         )  
    ---inserting salary component----------------------------------  
 If exists(Select top 1 amount from tsalaryofappointmenttime where candidateid=@candidateid )  
 begin  
  delete from tsalaryofappointmenttime where candidateid=@candidateid  
 end  
 insert into tsalaryofappointmenttime  
 (candidateid,salaryhead,amount)  
 values  
 (@candidateid,@basisorstipendsalhead,@basicorstipened),  
 (@candidateid,'HRA',@hra),  
 (@candidateid,'Education Allowance',@eduallowance),  
 (@candidateid,'Books & Periodical Allowance',@booksandperiodicalallowance),  
 (@candidateid,'Medical Allowance',@medicalallowance),  
 (@candidateid,'LTA',@lta),  
 (@candidateid,@attairortrainingallowancesalhead,@attrairtrainingallowance),  
 (@candidateid,@conveyanceorlodgingallowancesalhead,@conveayancelodgingallowance),  
 (@candidateid,'Internet Allowance',@internetallowance),  
 (@candidateid,'Total Allowance',@totalallowance),  
 (@candidateid,'Gross Amount with All Allowance',@grossamount),  
 (@candidateid,'P.F.',@pf),  
 (@candidateid,'E.S.I.C',@esic),  
 (@candidateid,'Prof. Tax',@proftax),  
 (@candidateid,'Total Deduction',@totaldeduction),  
 (@candidateid,'Payable Amount',@payebleamount),  
 (@candidateid,'Final Amount Payable',@finalpayebleamount),  
 (@candidateid,'Exgratia',@exgratia),  
 (@candidateid,'PF Contribution by Employer',@pfcontributionbyemployer),  
 (@candidateid,'ESI Contribution by Employer',@esicontributionbyemployer),  
 (@candidateid,'Gratuity',@graturity),  
 (@candidateid,'Mobile Allowance',@mobileallowance),  
 (@candidateid,'CTC Per Month',@ctcpermonth),  
 (@candidateid,'CTC Per Year',@ctcperyear)  
  
  
  
 ---end of inserting salary component----------------------------  
   
     
 --employee creation-------------------------------------  
  EXEC essp.dbo.procautocreatenewemp  
     @username=@username,  
       
     @empfirstname=@empfirstname,  
  @empmiddlename=@empmiddlename,  
     @emplastname=@emplastname,  
     @empdob=@empdob,  
     @companycode=@companycode,  
     @adharno=@adharno,  
     @emppersonalcontactno=@emppersonalcontactno,  
     @joining=@joining,  
     @empdept=@empdept,  
     @emppost=@emppost,  
     @empdesignation=@empdesignation,  
     @empreporttopost=@empreporttopost,  
     @empreporttoperson=@empreporttoperson,  
     @emppostingstate=@emppostingstate,  
  @empgender=@candidategender,  
  @emppersonalemail=@candidateemail,  
  @outputstatus=@outmsg output,  
     @outputstatuscode=@empcreatestatuscode output,  
  @outcreatedempno=@createdempno output;  
 ----end of employee creation------------------------------  
  if(@empcreatestatuscode=0)  
  begin  
   Set @outmsg='Appoitment and Employee Created Successfully'  
   end  
     
  end  
  else  
  begin  
         Set @outmsg=@dinref  
  end  
      ---inserting mapping details--------  
 insert into tcandidateappointmentmapping  
 ([candidateid],  
     [appointmentlettertype],  
      [deleteflag],  
   [empno],
   SyncYN)  
   values  
   (  
   @candidateid,  
   'MLEXPFIELD',  
   'No',  
   @createdempno ,
   'N'
   )  
  ---end of inserting mapping details--------  
   
   
   end try  
   begin catch  
   Select @errorcode=ERROR_MESSAGE();  
   if(@errorcode = '2627')--- for checking duplicate entry by sql error code  
   begin  
     Select @outmsg='Unsuccessful!! Duplicate Entry'  
   end  
   else  
    begin  
    Set @outmsg='Error Code:'+@errorcode+'. Please Contact With Administrator.'  
   end  
  
 end catch  
    end  
end  
else  
begin  
 if(@countdupadharno >0)  
 begin   
   set @outmsg='Failed!! Duplicate Adhar No,'  
 end  
 else if(@countduppersonalcontactno >0)  
 begin   
   set @outmsg='Failed!! Duplicate Personal Contact No,'  
 end  
else  
 begin   
   set @outmsg=@outmsg+'Failed!! Duplicate Combination Of Firstname Middlename Lastname and Adhar No,'  
 end  
end  
end  
GO



