@km151to250expences varchar(50)=null,  
@km251to500expences varchar(50)=null,  
@km500onwardsexpences varchar(50)=null,  
  
 ------emp creation parameter--------------------------------------  
 @username nvarchar(max),  
 @empfirstname varchar(max),  
 @empmiddlename varchar(max),  
 @emplastname varchar(max),  
 @empdob varchar(50),  
 @adharno varchar(50),  
 @companycode varchar(50),  
 @emppersonalcontactno varchar(50),  
 @joining varchar(50),  
 @empdept int ,  
 @emppost int,  
 @empdesignation int,  
 @emppostingstate int,  
 @empreporttopost int ,  
 @empreporttoperson int,  
 --------salary parameters------------  
@stipend varchar(20) =null,  
@trainingallowance varchar(20) =null,  
  
@internetallowance varchar(20) =null,  
@totalallowance varchar(20) =null,  
@grossamount varchar(20) =null,  
@pf varchar(20) =null,  
@esic varchar(20) =null,  
@proftax varchar(20) =null,  
@totaldeduction varchar(20) =null,  
@payebleamount varchar(20) =null,  
@finalpayebleamount varchar(20) =null,  
@exgratia varchar(20) =null,  
@pfcontributionbyemployer varchar(20) =null,  
@esicontributionbyemployer varchar(20) =null,  
@graturity varchar(20) =null,  
@mobileallowance varchar(20) =null,  
@ctcpermonth varchar(20) =null,  
@ctcperyear varchar(20) =null,  
@outmsg nvarchar(max) output  
as  
Declare @appointmentrefno nvarchar(Max)  
Declare @appiontmentissudate varchar(max)  
Declare @candidatename nvarchar(Max)  
Declare @candidateaddress nvarchar(Max)  
Declare @subject nvarchar(Max)  
Declare @appointdeptname nvarchar(Max)  
Declare @appointdesignationname nvarchar(Max)  
Declare @appointfuturedesignationname nvarchar(Max)  
Declare @appointfuturepostname nvarchar(max)  
Declare @appointfuturedeptname nvarchar(Max)  
Declare @joininghq nvarchar(Max)  
Declare @joiningaddress nvarchar(Max)  
Declare @para1 nvarchar(Max)  
Declare @para2 nvarchar(Max)  
Declare @para3 nvarchar(Max)  
Declare @para4 nvarchar(Max)  
Declare @para5 nvarchar(Max)  
Declare @para6 nvarchar(Max)  
Declare @para7 nvarchar(Max)  
Declare @para8 nvarchar(Max)  
Declare @para9 nvarchar(Max)  
Declare @para10 nvarchar(Max)  
Declare @para11 nvarchar(Max)  
Declare @para12 nvarchar(Max)  
declare @applicationdatevar varchar(max)  
declare @joiningdatevar varchar(max)  
Declare @totalamount int  
Declare @totalamoutinword varchar(Max)  
Declare @undershine nvarchar(max)  
Declare @errorcode nvarchar(max)  
Declare @dintitleanddescription nvarchar(max)  
Declare @candidatenamefordin nvarchar(max)  
declare @dincreatestatus int  
declare @dinref nvarchar(max)  
declare @countdupadharno int=0  
declare @countduppersonalcontactno int=0  
declare @countdupnameadharcombo int=0  
declare @empcreatestatuscode int  
Declare @createdempno int  
declare @candidategender varchar(20)  
declare @candidateemail nvarchar(max)  
Declare @salutations varchar(20)  
begin  
select @countdupadharno=count(empno) from [essp].[dbo].[Empbasic] where [adharno]=@adharno  
select @countduppersonalcontactno=count(empno) from [essp].[dbo].[Empbasic] where [emppersonalcontactno]=@emppersonalcontactno  
select @countdupnameadharcombo=count(empno) from [essp].[dbo].[Empbasic]   
where  
empfirstname=@empfirstname  
and empmiddlename=@empmiddlename  
and emplastname=@emplastname  
and adharno=@adharno  
if (@countdupadharno =0 and @countduppersonalcontactno=0 and @countdupnameadharcombo=0)  
begin  
   if exists(Select candidateid from [tappointmentletterdtlsofmlmtfield] where candidateid=@candidateid and deleteflag='No')  
   begin  
      Set @outmsg='Appointment Leatter Allready exists of this candidate'  
   end  
   else  
    begin  
      begin try  
   Select @candidatenamefordin=firstname+' '+middlename+' '+lastname,@candidategender=gender FROM [dbo].[trecruitcanbasicdtls]  
    where candidateid=@candidateid  
    select @dintitleanddescription='Appointment Letter For '+@candidatenamefordin   
     EXEC essp.dbo.procautodincreate   
  @dinfrom=1,  
  @company='ML',  
  @doctype='L',  
  @dintitle=@dintitleanddescription,  
  @dindescription=@dintitleanddescription,  
  @givento=@candidatenamefordin,  
  @username=@username,  
  @outputstatuscode=@dincreatestatus output,  
  @outputstatus=@dinref output;  
  if(@dincreatestatus =1)  
  begin  
        Select @appiontmentissudate=convert(varchar,getdate(),103)  
           Select @candidatename=firstname+' '+middlename+' '+lastname,  
     @salutations=case gender  
           when 'Male' then 'Mr.'  
        when 'Female' then 'Ms.'  
        else 'other'  
        end  
      FROM [dbo].[trecruitcanbasicdtls]  
           where candidateid=@candidateid  
     Select @candidatename=dbo.InitCap(@candidatename)  
     Select @candidatename=@salutations+' '+@candidatename  
           Select @candidateemail=[MailId] FROM [dbo].[trecruitcandidatesignup] where CandidateID=@candidateid  
           Select @candidateaddress=[addressline]+','+[villagecity]+','+[postoffice]+','+c.[disname]+','+b.[statename]+'-'+[pincode]    
           FROM [dbo].[trecruitcanaddress]a,  
           [dbo].[trecruitstate]b,  
           [dbo].[trecrutdistrict]c  
           where a.candidateid=@candidateid  
           and a.district=c.disid  
           and a.state=b.stateid  
           and [addresstype]='P'  
     Select @candidateaddress=dbo.InitCap(@candidateaddress)  
            Select @subject='Appointment Letter for Management Trainee'  
   --Select @totalamount=cast(@fixedstipend as int) + CAST(@trainingallowance as int)+ CAST(@conveyanceallowance as int)  
   --         Select @totalamoutinword=dbo.[fnNumberToWords](@totalamount)  
            Select @appointdeptname=[Department] FROM [essp].[dbo].[Department] where DepartmentId=@joiningdept  
            Select @appointdeptname=dbo.InitCap(@appointdeptname)  
            Select @appointfuturedeptname=[Department] FROM [essp].[dbo].[Department] where DepartmentId=@futureappointdept  
            Select @appointfuturedeptname=dbo.InitCap(@appointfuturedeptname)  
   --Select @appointdesignationname=[designationname] FROM [essp].[dbo].[Designationmaster] where deleteflag='No' and designationid=@joiningdesignation  
            --Select @appointdesignationname=dbo.InitCap(@appointdesignationname)  
      Select @appointfuturedesignationname=[designationname] FROM [essp].[dbo].[Designationmaster] where deleteflag='No' and designationid=@futureappointdesignation  
            Select @appointfuturedesignationname=dbo.InitCap(@appointfuturedesignationname)  
   Select @appointfuturepostname =[postname] FROM [essp].[dbo].[Postmaster] where deleteflag='No' and postid=@futureappointpost  
            Select @appointfuturepostname=dbo.InitCap(@appointfuturepostname)  
   Select @joininghq=operationalhq,@joiningaddress=address from [essp].[dbo].[temppostinglocation] where deleteflag='No' and id=@joininglocid  
            Select @joininghq=dbo.InitCap(@joininghq)  
   Select @joiningaddress=dbo.InitCap(@joiningaddress)  
      Select @appointmentrefno=@dinref   
   Select @undershine=[undershine] FROM [tundershinemaster] WHERE [companycode] = 'ML' AND lettertype='Appointment Letter' and undershinedid=@undershineid  
           --Select @joiningdatevar=convert(varchar, convert(date,@joiningdate,103),106)  
           --Select @applicationdatevar=convert(varchar, convert(date,@applicationdate,103),106)  
  
           Select @para1='In reference to your Application Dated '+@applicationdate+' and subsequent interviews you had with us and also in reference to our Offer Letter Reference: '+@offerefno+', we are pleased to appoint you as Management Trainee in the
 department '+@appointdeptname+' in our Organization with effect from '+@joiningdate+' to be based at our '+@joininghq+' at '+@joiningaddress+' on the following terms and conditions:'  
  
           Select @para2='1. At the outset, your appointment will be in the Category of Management Trainee for a period of '+@trainingperiod+' with effect from '+@joiningdate+'. '  
             
           Select @para3='2. On Successful completion of your tenure as Management Trainee, you may be considered eligible for Appointment as '+@appointfuturedesignationname+' in our '+@appointfuturedeptname+' under probation in the rank of '+@appointfuturepostname+' for a period of '+@probationperiod+' pending final confirmation in writing – subject to evaluation and review of your satisfactory performance during the tenure of your service as Management Trainee. On contrary, unsatisfactory performance du
ring the tenure as Management Trainee may lead to termination of service without assigning any reason whatsoever.'  
             
           Select @para4='3. Any part of furnished details/documents submitted by you along with your application for employment – if found wrong/incorrect/manipulated at any point of time in course of your employment in our Organisation (MLPPL), shall be
 liable for termination of your employment with immediate effect without assigning any reason to you.'  
             
           Select @para5='4. You will be entitled for remuneration & Allowances as mentioned under Annexure-A & B respectively.'  
             
           Select @para6='5. You will join your duty and discharge such duties and responsibilities as may be assigned to you from time to time and you will not directly or indirectly engage or serve in any capacity whatsoever either full or part time or 
undertake or carry on or be concerned in any business, trade, profession or, concern other than work assigned to you by the Company.'  
             
           Select @para7='6. During the period of your employment with us or thereafter you should always keep secret and confidential and prevent the disclosure or divulgence of all information , knowledge , know-how experience, data, documents, reports,
 statement, records, correspondence, discussion, contracts, manufacturing processes, transactions , affairs , dealings , quotations, finance, accounts etc. of the Company that may pass through you or come through your knowledge.'  
             
           Select @para8='7. The terms and conditions of your appointment will be governed by the rules and regulations of the Company as applicable to other employees of the Company and in force from time to time.'  
             
           Select @para9='8. The Company will be at liberty to dispense with your services without any notice or compensation and without prejudice to any other right or claims to the Company - if any breach occurs on your part at any point of time in cou
rse of your employment to the effect of the terms and conditions contained hereinabove. In the matter of breach of terms of employment, the Company’s decision will be final and shall be binding upon you.'  
             
           Select @para10='9. Resignation – In Case of Resignation, your accounts will be settled only on receipt of Company properties in good condition. The following would be deducted while settling your accounts.'  
             
             
           Select @para11='    If the above terms and conditions are acceptable to you please sign the duplicate copy of this letter as a token of your acceptance and return it to us.'  
             
           Select @para12='I have read and understood the above-mentioned terms and conditions and am in agreement with them'  
  
         insert into tappointmentletterdtlsofmlmtfield  
         (  
           [candidateid]  
      ,[appointmentlettertype]  
      ,[appiontmentrefno]  
      ,[offerrefno]  
      ,[company]  
      ,[appiontmentissuedate]  
      ,[candidatename]  
      ,[candidateaddress]  
      ,[futurepostid]  
      ,[futuredepartmentid]  
      ,[futuredesignationid]  
      ,[subject]  
      ,[joiningdate]  
      ,[trainingperiod]  
      ,[probationperiod]  
      ,[trainingexpence]  
      ,[bagcost]  
      ,[visualaidcost]  
      ,[stationarycost]  
      ,[giftscost]  
      ,[postinglocationid]  
      ,[para1]  
      ,[para2]  
      ,[para3]  
      ,[para4]  
      ,[para5]  
      ,[para6]  
      ,[para7]  
      ,[para8]  
      ,[para9]  
      ,[para10]  
      ,[para11]  
      ,[para12]  
      ,[deleteflag]  
        
      ,[createdby]  
      ,[createdon]  
  
      ,[appointdept]  
      ,[appointdesignation]  
     
   ,[hqallowance]  
      ,[exstationallowance]  
      ,[transitallowance]  
      ,[outstationallowance]  
      ,[meetingortrainingallowance]  
      ,[km0to25expences]  
      ,[km26to75expences]  
      ,[km76to150expences]  
      ,[km151to250expences]  
      ,[km251to500expences]  
      ,[km500onwardsexpences]  
   ,[undershine]        
          
         )  
         values  
         (  
           @candidateid,  
     'MLMTFIELD',  
           @appointmentrefno,  
           @offerefno,  
     'ML',  
           convert(date,@appiontmentissudate,103),  
           @candidatename,  
           @candidateaddress,  
           @futureappointpost,  
     @futureappointdept,  
     @futureappointdesignation,  
              @subject,  
           convert(date,@joiningdate,103),  
     @trainingperiod,  
     @probationperiod,  
     @trainingexpence,  
     @bagcost,  
     @visualaidcost,  
     @stationarycost,  
     @giftscost,  
           @joininglocid,  
           @para1,  
           @para2,  
           @para3,  
           @para4,  
           @para5,  
           @para6,  
           @para7,  
           @para8,  
           @para9,  
           @para10,  
     @para11,  
     @para12,  
           'No',  
           @username,  
           GETDATE(),  
     @joiningdept,  
       
     @totalamount,  
     @hqallowance,  
     @exstationallowance,  
     @transitallowance,  
     @outstationallowance,  
     @meetingortrainingallowance,  
     @km0to25expences,  
     @km26to75expences,  
     @km76to150expences,  
     @km151to250expences,  
     @km251to500expences,  
     @km500onwardsexpences,  
     @undershine  
  
  
         )  
    ---inserting salary component----------------------------------  
 If exists(Select top 1 amount from tsalaryofappointmenttime where candidateid=@candidateid )  
 begin  
  delete from tsalaryofappointmenttime where candidateid=@candidateid  
 end  
 insert into tsalaryofappointmenttime  
 (candidateid,salaryhead,amount)  
 values  
 (@candidateid,'Stipend',@stipend),  
 (@candidateid,'Training Allowance',@trainingallowance),  
 (@candidateid,'Internet Allowance',@internetallowance),  
 (@candidateid,'Total Allowance',@totalallowance),  
 (@candidateid,'Gross Amount with All Allowance',@grossamount),  
 (@candidateid,'P.F.',@pf),  
 (@candidateid,'E.S.I.C',@esic),  
 (@candidateid,'Prof. Tax',@proftax),  
 (@candidateid,'Total Deduction',@totaldeduction),  
 (@candidateid,'Payable Amount',@payebleamount),  
 (@candidateid,'Final Amount Payable',@finalpayebleamount),  
 (@candidateid,'Mobile Allowance',@mobileallowance),  
 (@candidateid,'Exgratia',@exgratia),  
 (@candidateid,'PF Contribution by Employer',@pfcontributionbyemployer),  
 (@candidateid,'ESI Contribution by Employer',@esicontributionbyemployer),  
 (@candidateid,'Gratuity',@graturity),  
 (@candidateid,'CTC Per Month',@ctcpermonth),  
 (@candidateid,'CTC Per Year',@ctcperyear)  
   
  
  
  
 ---end of inserting salary component----------------------------  
   
     
 --employee creation-------------------------------------  
  EXEC essp.dbo.procautocreatenewemp  
     @username=@username,  
       
     @empfirstname=@empfirstname,  
  @empmiddlename=@empmiddlename,  
     @emplastname=@emplastname,  
     @empdob=@empdob,  
     @companycode=@companycode,  
     @adharno=@adharno,  
     @emppersonalcontactno=@emppersonalcontactno,  
     @joining=@joining,  
     @empdept=@empdept,  
     @emppost=@emppost,  
     @empdesignation=@empdesignation,  
     @empreporttopost=@empreporttopost,  
     @empreporttoperson=@empreporttoperson,  
     @emppostingstate=@emppostingstate,  
  @empgender=@candidategender,  
  @emppersonalemail=@candidateemail,  
  @outputstatus=@outmsg output,  
     @outputstatuscode=@empcreatestatuscode output,  
  @outcreatedempno=@createdempno output;  
 ----end of employee creation------------------------------  
  if(@empcreatestatuscode=0)  
  begin  
   ---inserting mapping details--------  
        insert into tcandidateappointmentmapping  
        ([candidateid],  
            [appointmentlettertype],  
             [deleteflag],  
          empno,SyncYN)  
          values  
          (  
          @candidateid,  
          'MLMTFIELD',  
          'No',  
          @createdempno ,'N' 
          )  
         ---end of inserting mapping details--------  
   Set @outmsg='Appoitment and Employee Created Successfully'  
   end  
     
  end  
  else  
  begin  
         Set @outmsg=@dinref  
  end  
      
    
   
   end try  
   begin catch  
   Select @errorcode=ERROR_MESSAGE();  
   if(@errorcode = '2627')--- for checking duplicate entry by sql error code  
   begin  
     Select @outmsg='Unsuccessful!! Duplicate Entry'  
   end  
   else  
    begin  
    Set @outmsg='Error Code:'+@errorcode+'. Please Contact With Administrator.'  
   end  
  
 end catch  
    end  
end  
else  
begin  
 if(@countdupadharno >0)  
 begin   
   set @outmsg='Failed!! Duplicate Adhar No,'  
 end  
 else if(@countduppersonalcontactno >0)  
 begin   
   set @outmsg='Failed!! Duplicate Personal Contact No,'  
 end  
else  
 begin   
   set @outmsg=@outmsg+'Failed!! Duplicate Combination Of Firstname Middlename Lastname and Adhar No,'  
 end  
end  
end  
GO



