CREATE proc [dbo].[proccreatempexpfieldappotment]  
@action varchar(max)=null,  
@candidateid int,  
@offerefno nvarchar(Max)=null,  
@applicationdate varchar(100)=null,  
@joininglocid int=null,  
@appointpostid int=null,  
@appointdesignationid int=null,  
@appointdeptid int=null,  
@joiningdate varchar(200)=null,  
@hqallowance varchar(50)=null,  
@exstationallowance varchar(50)=null,  
@transitallowance varchar(50)=null,  
@outstationallowance varchar(50)=null,  
@meetingortrainingallowance varchar(50)=null,  
@km0to25expences varchar(50)=null,  
@km26to75expences varchar(50)=null,  
@km76to150expences varchar(50)=null,  
@km151to250expences varchar(50)=null,  
@km251to500expences varchar(50)=null,  
@km500onwardsexpences varchar(50)=null,  
@noticeperiod varchar(100)=null,  
@undershineid int=null,  
 ------emp creation parameter--------------------------------------  
 @username nvarchar(max),  
 @empfirstname varchar(max),  
 @empmiddlename varchar(max),  
 @emplastname varchar(max),  
 @empdob varchar(50),  
 @adharno varchar(50),  
 @companycode varchar(50),  
 @emppersonalcontactno varchar(50),  
 @joining varchar(50),  
 @empdept int ,  
 @emppost int,  
 @empdesignation int,  
 @emppostingstate int,  
 @empreporttopost int ,  
 @empreporttoperson int,  
 --------salary parameters------------  
 @basicorstipened varchar(20) =null,  
 @hra varchar(20) =null,  
 @eduallowance varchar(20) =null,  
@booksandperiodicalallowance varchar(20) =null,  
@medicalallowance varchar(20) =null,  
@lta varchar(20) =null,  
@attrairtrainingallowance varchar(20) =null,  
@conveayancelodgingallowance varchar(20) =null,  
@internetallowance varchar(20) =null,  
@totalallowance varchar(20) =null,  
@grossamount varchar(20) =null,  
@pf varchar(20) =null,  
@esic varchar(20) =null,  
@proftax varchar(20) =null,  
@totaldeduction varchar(20) =null,  
@payebleamount varchar(20) =null,  
@finalpayebleamount varchar(20) =null,  
@exgratia varchar(20) =null,  
@pfcontributionbyemployer varchar(20) =null,  
@esicontributionbyemployer varchar(20) =null,  
@graturity varchar(20) =null,  
@mobileallowance varchar(20) =null,  
@ctcpermonth varchar(20) =null,  
@ctcperyear varchar(20) =null,  
  
@basisorstipendsalhead nvarchar(max),  
@attairortrainingallowancesalhead nvarchar(max),  
@conveyanceorlodgingallowancesalhead nvarchar(max),  
@outmsg nvarchar(max) output  
as  
Declare @appointmentrefno nvarchar(Max)  
Declare @appiontmentissudate varchar(max)  
Declare @candidatename nvarchar(Max)  
Declare @candidateaddress nvarchar(Max)  
Declare @subject nvarchar(Max)  
Declare @appointdesignationname nvarchar(Max)  
Declare @appointpostname nvarchar(max)  
Declare @appointdeptname nvarchar(Max)  
Declare @joininghq nvarchar(Max)  
Declare @joiningaddress nvarchar(Max)  
Declare @para1 nvarchar(Max)  
Declare @para2 nvarchar(Max)  
Declare @para3 nvarchar(Max)  
Declare @para4 nvarchar(Max)  
Declare @para5 nvarchar(Max)  
Declare @para6 nvarchar(Max)  
Declare @para7 nvarchar(Max)  
Declare @para8 nvarchar(Max)  
Declare @para9 nvarchar(Max)  
Declare @para10 nvarchar(Max)  
Declare @para11 nvarchar(Max)  
Declare @para12 nvarchar(Max)  
Declare @para13 nvarchar(Max)  
  
Declare @errorcode nvarchar(max)  
Declare @dintitleanddescription nvarchar(max)  
Declare @candidatenamefordin nvarchar(max)  
declare @dincreatestatus int  
declare @dinref nvarchar(max)  
declare @countdupadharno int=0  
declare @countduppersonalcontactno int=0  
declare @countdupnameadharcombo int=0  
declare @empcreatestatuscode int  
Declare @createdempno int  
declare @candidategender varchar(20)  
declare @candidateemail nvarchar(max)  
Declare @applicationdatevar varchar(Max)  
Declare @joiningdatevar varchar(Max)  
Declare @undershine nvarchar(Max)  
declare @salutations varchar(20)  
begin  
select @countdupadharno=count(empno) from [essp].[dbo].[Empbasic] where [adharno]=@adharno  
select @countduppersonalcontactno=count(empno) from [essp].[dbo].[Empbasic] where [emppersonalcontactno]=@emppersonalcontactno  
select @countdupnameadharcombo=count(empno) from [essp].[dbo].[Empbasic]   
where  
empfirstname=@empfirstname  
and empmiddlename=@empmiddlename  
and emplastname=@emplastname  
and adharno=@adharno  
if (@countdupadharno =0 and @countduppersonalcontactno=0 and @countdupnameadharcombo=0)  
begin  
   if exists(Select candidateid from [tcandidateappointmentmapping] where candidateid=@candidateid and deleteflag='No')  
   begin  
      Set @outmsg='Appointment Leatter Allready exists of this candidate'  
   end  
   else  
    begin  
      begin try  
   Select @candidatenamefordin=firstname+' '+middlename+' '+lastname,@candidategender=gender FROM [dbo].[trecruitcanbasicdtls]  
    where candidateid=@candidateid  
    select @dintitleanddescription='Appointment Letter For '+@candidatenamefordin   
     EXEC essp.dbo.procautodincreate   
  @dinfrom=1,  
  @company='MP',  
  @doctype='L',  
  @dintitle=@dintitleanddescription,  
  @dindescription=@dintitleanddescription,  
  @givento=@candidatenamefordin,  
  @username=@username,  
  @outputstatuscode=@dincreatestatus output,  
  @outputstatus=@dinref output;  
  if(@dincreatestatus =1)  
  begin  
        Select @appiontmentissudate=convert(varchar,getdate(),103)  
           Select @candidatename=firstname+' '+middlename+' '+lastname,  
     @salutations=case gender  
           when 'Male' then 'Mr.'  
        when 'Female' then 'Ms.'  
        else 'other'  
        end  
      FROM [dbo].[trecruitcanbasicdtls]  
           where candidateid=@candidateid  
     Select @candidatename=dbo.InitCap(@candidatename)  
     Select @candidatename=@salutations+' '+@candidatename  
           Select @candidateemail=[MailId] FROM [dbo].[trecruitcandidatesignup] where CandidateID=@candidateid  
           Select @candidateaddress=[addressline]+','+[villagecity]+','+[postoffice]+','+c.[disname]+','+b.[statename]+'-'+[pincode]    
           FROM [dbo].[trecruitcanaddress]a,  
           [dbo].[trecruitstate]b,  
           [dbo].[trecrutdistrict]c  
           where a.candidateid=@candidateid  
           and a.district=c.disid  
           and a.state=b.stateid  
           and [addresstype]='P'  
     Select @candidateaddress=dbo.InitCap(@candidateaddress)  
            Select @subject='Appointment Letter'  
            Select @appointdeptname=[Department] FROM [essp].[dbo].[Department] where DepartmentId=@appointdeptid  
   Select @appointdeptname=dbo.InitCap(@appointdeptname)  
            Select @appointdesignationname=[designationname] FROM [essp].[dbo].[Designationmaster] where deleteflag='No' and designationid=@appointdesignationid  
            Select @appointdesignationname=dbo.InitCap(@appointdesignationname)  
   Select @appointpostname =[postname] FROM [essp].[dbo].[Postmaster] where deleteflag='No' and postid=@appointpostid  
   Select @appointpostname=dbo.InitCap(@appointpostname)  
            Select @joininghq=operationalhq,@joiningaddress=address from [essp].[dbo].[temppostinglocation] where deleteflag='No' and id=@joininglocid  
             Select @joininghq=dbo.InitCap(@joininghq)  
   Select @joiningaddress=dbo.InitCap(@joiningaddress)  
   Select @appointmentrefno=@dinref   
   Select @undershine=[undershine] FROM [tundershinemaster] WHERE [companycode] = 'MP' AND lettertype='Appointment Letter' and undershinedid=@undershineid  
            --Select @joiningdatevar=convert(varchar, convert(date,@joiningdate,103),106)  
            --Select @applicationdatevar=convert(varchar, convert(date,@applicationdate,103),106)  
            Select @para1='In reference to your application dated '+@applicationdate+' and subsequent interviews you had with us and also in reference to our Offer Letter Reference: '+@offerefno+', we are pleased to appoint you as '+@appointdesignationname+' in the rank of '+@appointpostname+' in '+@appointdeptname+' in our Company with Head Quarter at '+@joininghq+' with effect from '+@joiningdate+' on the following terms and conditions.'  
  
  
            Select @para2='1. You will be paid Salary and Allowances as per Annexure A & B respectively.'  
              
            Select @para3='2. Your appointment will be on Probation basis for a period of twelve months from the date of your joining and you will continue to be deemed as on probationary service until and unless your service is confirmed in writing. Your
 probationary period may be extended at the discretion of the Management. During the probationary period, your services may be liable for termination any time without notice and without assigning any reason to you. Your service after the expiry of this pr
obation may be confirmed in writing, subject to the evaluation and review of your performance, discipline, reporting and other deliverables pertaining to your Job Responsibilities having been found up to the mark, satisfactory and compliant with as per Co
mpany’s Norms & Policies. Either party may terminate the employment contract by giving '+@noticeperiod+' notice to other or salary in lieu of such notice thereof at any point during the tenure of service.'  
              
            Select @para4='3. You will join your duty and discharge such duties and responsibilities as may be assigned to you and be responsible to achieve the targets and goals assigned from time to time. Your services are liable to be transferred to an
y of our offices within India or you may be deputed to serve in any of our sister concerns with the same benefits and emoluments. You will accept such duties and responsibility as may be assigned to your consequent to such transferor deputation. You will 
be subject to regular evaluations and appraisals to which you have to comply.'  
              
            Select @para5='4. During the period of your employment with us, you will devote all of your time exclusively for the work as may be assigned to you from time to time and you will not directly or indirectly engage or serve in any capacity whats
oever other than the work assigned to you with the Company.'  
              
            Select @para6='5. During the period of your employment with us or thereafter, you shall always keep secret and confidential and prevent the disclosure or divulgence, of all information, knowledge, know- how experience, data, documents, reports
, statements, records, correspondence, discussions, contracts, manufacturing process, transactions, affairs, dealings, quotations, finance, accounts, etc. of the Company that may pass through you or come through your knowledge.'  
              
            Select @para7='6. Your services will be governed by the rules and regulations of the Company as are applicable to the employees of your status and shall remain in force from time to time. However, the Management reserves the rights to modify, 
alter or delete the existing rules or introduce fresh service rules.'  
              
            Select @para8='7. Any part of furnished details/documents submitted by you along with your application for employment – if found wrong/incorrect/manipulated at any point of time in course of your employment in our Organisation (MPPL), shall be
 liable for termination of your employment with immediate effect without assigning any reason to you.'  
              
            Select @para9='8. The continuation of your services is subject to your being found and remaining medically and physically fit.'  
              
            Select @para10='9. The Company will be at liberty to dispense with your services without any notice or compensation and without prejudice to any other right or claims to the company - if any breach occurs on your part at any point of time in c
ourse of your employment to the effect of the terms and conditions contained hereinabove. In the matter of breach of terms of employment, the company’s decision will be final and shall be binding upon you.'  
              
            Select @para11='10. Disputes or litigations if arising out of this employment contract is subject to Kolkata City Court Jurisdiction only.'  
              
            Select @para12='If the above terms and conditions are acceptable to you, please sign the duplicate copy of this appointment letter as a token of your acceptance and return it to us.'  
              
            Select @para13='I have read and understood the above-mentioned terms and conditions and am in agreement with them'  
         insert into tappointmentletterformpexpfield  
         (  
    [candidateid]  
      ,[appointmentlettertype]  
      ,[appiontmentrefno]  
      ,[offerrefno]  
      ,[company]  
      ,[appiontmentissuedate]  
      ,[candidatename]  
      ,[candidateaddress]  
      ,[appointpostid]  
      ,[appointdeptid]  
      ,[appointdesignationid]  
      ,[subject]  
      ,[joiningdate]  
      ,[hqallowance]  
      ,[exstationallowance]  
      ,[transitallowance]  
      ,[outstationallowance]  
   ,[meetingortrainingallowance]  
      ,[km0to25expences]  
      ,[km26to75expences]  
      ,[km76to150expences]  
      ,[km151to250expences]  
      ,[km251to500expences]  
      ,[km500onwardsexpences]  
      ,[postinglocationid]  
      ,[para1]  
      ,[para2]  
      ,[para3]  
      ,[para4]  
      ,[para5]  
      ,[para6]  
      ,[para7]  
      ,[para8]  
      ,[para9]  
      ,[para10]  
      ,[para11]  
      ,[para12]  
      ,[para13]  
   ,[deleteflag]  
      ,[createdby]  
      ,[createdon]  
   ,[noticeperiod]  
   ,[undershine]  
      )  
         values  
         (  
           @candidateid,  
     'MPEXPFIELD',  
           @appointmentrefno,  
           @offerefno,  
     'MP',  
           convert(date,@appiontmentissudate,103),  
           @candidatename,  
           @candidateaddress,  
           @appointpostid,  
     @appointdeptid,  
     @appointdesignationid,  
              @subject,  
           convert(date,@joiningdate,103),  
     @hqallowance,  
     @exstationallowance,  
     @transitallowance,  
     @outstationallowance,  
     @meetingortrainingallowance,  
     @km0to25expences,  
     @km26to75expences,  
     @km76to150expences,  
     @km151to250expences,  
     @km251to500expences,  
     @km500onwardsexpences,  
           @joininglocid,  
           @para1,  
           @para2,  
           @para3,  
           @para4,  
           @para5,  
           @para6,  
           @para7,  
           @para8,  
           @para9,  
           @para10,  
     @para11,  
     @para12,  
     @para13,  
           'No',  
           @username,  
           GETDATE(),  
     @noticeperiod,  
     @undershine  
         )  
    ---inserting salary component----------------------------------  
 If exists(Select top 1 amount from tsalaryofappointmenttime where candidateid=@candidateid )  
 begin  
  delete from tsalaryofappointmenttime where candidateid=@candidateid  
 end  
 insert into tsalaryofappointmenttime  
 (candidateid,salaryhead,amount)  
 values  
 (@candidateid,@basisorstipendsalhead,@basicorstipened),  
 (@candidateid,'HRA',@hra),  
 (@candidateid,'Education Allowance',@eduallowance),  
 (@candidateid,'Books & Periodical Allowance',@booksandperiodicalallowance),  
 (@candidateid,'Medical Allowance',@medicalallowance),  
 (@candidateid,'LTA',@lta),  
 (@candidateid,@attairortrainingallowancesalhead,@attrairtrainingallowance),  
 (@candidateid,@conveyanceorlodgingallowancesalhead,@conveayancelodgingallowance),  
 (@candidateid,'Internet Allowance',@internetallowance),  
 (@candidateid,'Total Allowance',@totalallowance),  
 (@candidateid,'Gross Amount with All Allowance',@grossamount),  
 (@candidateid,'P.F.',@pf),  
 (@candidateid,'E.S.I.C',@esic),  
 (@candidateid,'Prof. Tax',@proftax),  
 (@candidateid,'Total Deduction',@totaldeduction),  
 (@candidateid,'Payable Amount',@payebleamount),  
 (@candidateid,'Final Amount Payable',@finalpayebleamount),  
 (@candidateid,'Exgratia',@exgratia),  
 (@candidateid,'PF Contribution by Employer',@pfcontributionbyemployer),  
 (@candidateid,'ESI Contribution by Employer',@esicontributionbyemployer),  
 (@candidateid,'Gratuity',@graturity),  
 (@candidateid,'Mobile Allowance',@mobileallowance),  
 (@candidateid,'CTC Per Month',@ctcpermonth),  
 (@candidateid,'CTC Per Year',@ctcperyear)  
  
  
  
 ---end of inserting salary component----------------------------  
  
     
 --employee creation-------------------------------------  
  EXEC essp.dbo.procautocreatenewemp  
     @username=@username,  
       
     @empfirstname=@empfirstname,  
  @empmiddlename=@empmiddlename,  
     @emplastname=@emplastname,  
     @empdob=@empdob,  
     @companycode=@companycode,  
     @adharno=@adharno,  
     @emppersonalcontactno=@emppersonalcontactno,  
     @joining=@joining,  
     @empdept=@empdept,  
     @emppost=@emppost,  
     @empdesignation=@empdesignation,  
     @empreporttopost=@empreporttopost,  
     @empreporttoperson=@empreporttoperson,  
     @emppostingstate=@emppostingstate,  
  @empgender=@candidategender,  
  @emppersonalemail=@candidateemail,  
  @outputstatus=@outmsg output,  
     @outputstatuscode=@empcreatestatuscode output,  
  @outcreatedempno=@createdempno output;  
 ----end of employee creation------------------------------  
  if(@empcreatestatuscode=0)  
  begin  
     ---inserting mapping details--------  
          insert into tcandidateappointmentmapping  
          ([candidateid],  
              [appointmentlettertype],  
               [deleteflag],  
      [empno],
	  SyncYN)  
            values  
            (  
            @candidateid,  
            'MPEXPFIELD',  
            'No',  
      @createdempno,
	  'N'
            )  
          ---end of inserting mapping details--------  
   Set @outmsg='Appoitment and Employee Created Successfully'  
   end  
     
  end  
  else  
  begin  
         Set @outmsg=@dinref  
  end  
      
   
   
   end try  
   begin catch  
   Select @errorcode=ERROR_MESSAGE();  
   if(@errorcode = '2627')--- for checking duplicate entry by sql error code  
   begin  
     Select @outmsg='Unsuccessful!! Duplicate Entry'  
   end  
   else  
    begin  
    Set @outmsg='Error Code:'+@errorcode+'. Please Contact With Administrator.'  
   end  
  
 end catch  
    end  
end  
else  
begin  
 if(@countdupadharno >0)  
 begin   
   set @outmsg='Failed!! Duplicate Adhar No,'  
 end  
 else if(@countduppersonalcontactno >0)  
 begin   
   set @outmsg='Failed!! Duplicate Personal Contact No,'  
 end  
else  
 begin   
   set @outmsg=@outmsg+'Failed!! Duplicate Combination Of Firstname Middlename Lastname and Adhar No,'  
 end  
end  
end  
GO



/* Functional group: 09_OFFER_APPOINTMENT_ONBOARDING; referenced grouped tables: Company, tappointmentletterdtlsofmpmt, tcandidateappointmentmapping, trecruitcanaddress, trecruitcanbasicdtls, trecruitcandidatesignup, trecruitstate, trecrutdistrict, tsalaryofappointmenttime, tundershinemaster */
/****** Object:  StoredProcedure [dbo].[proccreatempmtappotment]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[proccreatempmtappotment]    
 @candidateid int,    
 @offerefno nvarchar(max),    
 --@fixedstipend varchar(50),    
 --@traininingallowancnce varchar(50),    
 --@conveyenceallowance varchar(100)=null,    
 @applicationdate varchar(50),    
 @appointdept int,    
 --@appointpost int ,    
 --@appointdesignation int,    
 @joininglocid int,    
 @futureappointdept int,    
 @futureappointdesignation int ,    
 @joiningdate varchar(50),    
 @undershineid int,    
 ------emp creation parameter--------------------------------------    
 @username nvarchar(max),    
 @empfirstname varchar(max),    
 @empmiddlename varchar(max),    
 @emplastname varchar(max),    
 @empdob varchar(50),    
 @adharno varchar(50),    
 @companycode varchar(50),    
 @emppersonalcontactno varchar(50),    
 @joining varchar(50),    
 @empdept int ,    
 @emppost int,    
 @empdesignation int,    
 @emppostingstate int,    
 @empreporttopost int ,    
 @empreporttoperson int,    
 --------salary parameters------------    
 @stipend varchar(20) =null,    
 @trainingallowance varchar(20) =null,    
 @internetallowance varchar(20) =null,    
 @totalallowance varchar(20) =null,    
 @grossamount varchar(20) =null,    
 @pf varchar(20) =null,    
 @esic varchar(20) =null,    
 @proftax varchar(20) =null,    
 @totaldeduction varchar(20) =null,    
 @payebleamount varchar(20) =null,    
 @finalpayebleamount varchar(20) =null,    
 @exgratia varchar(20) =null,    
 @pfcontributionbyemployer varchar(20) =null,    
 @esicontributionbyemployer varchar(20) =null,    
 @graturity varchar(20) =null,    
 @mobileallowance varchar(20) =null,    
 @ctcpermonth varchar(20) =null,    
 @ctcperyear varchar(20) =null,    
    
 @outmsg nvarchar(max) output    
as    
Declare @appointmentrefno nvarchar(Max)    
Declare @appiontmentissudate varchar(max)    
Declare @candidatename nvarchar(Max)    
Declare @candidateaddress nvarchar(Max)    
Declare @subject nvarchar(Max)    
Declare @totalamount int    
Declare @appointpostname nvarchar(Max)    
Declare @appointdeptname nvarchar(Max)    
Declare @appointdesgnationname nvarchar(Max)    
Declare @appointfuturedesignationname nvarchar(Max)    
Declare @appointfuturedeptname nvarchar(Max)    
Declare @joininghq nvarchar(Max)    
Declare @joiningaddress nvarchar(Max)    
Declare @para1 nvarchar(Max)    
Declare @para2 nvarchar(Max)    
Declare @para3 nvarchar(Max)    
Declare @para4 nvarchar(Max)    
Declare @para5 nvarchar(Max)    
Declare @para6 nvarchar(Max)    
Declare @para7 nvarchar(Max)    
Declare @para8 nvarchar(Max)    
Declare @para9 nvarchar(Max)    
Declare @para10 nvarchar(Max)    
Declare @errorcode nvarchar(max)    
Declare @dintitleanddescription nvarchar(max)    
Declare @candidatenamefordin nvarchar(max)    
declare @dincreatestatus int    
declare @dinref nvarchar(max)    
declare @countdupadharno int=0    
declare @countduppersonalcontactno int=0    
declare @countdupnameadharcombo int=0    
declare @empcreatestatuscode int    
declare @createdempno int    
declare @candidategender varchar(20)    
declare @candidateemail nvarchar(max)    
declare @undershine nvarchar(max)    
Declare @joiningdatevar varchar(100)    
Declare @applicationdatevar varchar(100)    
Declare @salutations varchar(20)    
begin    
select @countdupadharno=count(empno) from [essp].[dbo].[Empbasic] where [adharno]=@adharno    
select @countduppersonalcontactno=count(empno) from [essp].[dbo].[Empbasic] where [emppersonalcontactno]=@emppersonalcontactno    
select @countdupnameadharcombo=count(empno) from [essp].[dbo].[Empbasic]     
where    
empfirstname=@empfirstname    
and empmiddlename=@empmiddlename    
and emplastname=@emplastname    
and adharno=@adharno    
if (@countdupadharno =0 and @countduppersonalcontactno=0 and @countdupnameadharcombo=0)    
begin    
   if exists(Select candidateid from [tcandidateappointmentmapping] where candidateid=@candidateid and deleteflag='No')    
   begin    
      Set @outmsg='Appointment Leatter Allready exists of this candidate'    
   end    
   else    
    begin    
      begin try    
   Select @candidatenamefordin=firstname+' '+middlename+' '+lastname,@candidategender=gender FROM [dbo].[trecruitcanbasicdtls]    
    where candidateid=@candidateid    
    select @dintitleanddescription='Appointment Letter For '+@candidatenamefordin     
     EXEC essp.dbo.procautodincreate     
  @dinfrom=1,    
  @company='MP',    
  @doctype='L',    
  @dintitle=@dintitleanddescription,    
  @dindescription=@dintitleanddescription,    
  @givento=@candidatenamefordin,    
  @username=@username,    
  @outputstatuscode=@dincreatestatus output,    
  @outputstatus=@dinref output;    
  if(@dincreatestatus =1)    
  begin    
        Select @appiontmentissudate=convert(varchar,getdate(),103)    
           Select @candidatename=firstname+' '+middlename+' '+lastname,    
     @salutations=case gender    
           when 'Male' then 'Mr.'    
        when 'Female' then 'Ms.'    
        else 'other'    
        end    
      FROM [dbo].[trecruitcanbasicdtls]    
           where candidateid=@candidateid    
     Select @candidatename=dbo.InitCap(@candidatename)    
     Select @candidatename=@salutations+' '+@candidatename    
           Select @candidateemail=[MailId] FROM [dbo].[trecruitcandidatesignup] where CandidateID=@candidateid    
           Select @candidateaddress=[addressline]+','+[villagecity]+','+[postoffice]+','+c.[disname]+','+b.[statename]+'-'+[pincode]      
           FROM [dbo].[trecruitcanaddress]a,    
           [dbo].[trecruitstate]b,    
           [dbo].[trecrutdistrict]c    
           where a.candidateid=@candidateid    
           and a.district=c.disid    
           and a.state=b.stateid    
           and [addresstype]='P'    
     Select @candidateaddress=dbo.InitCap(@candidateaddress)    
            Select @subject='Appointment Letter for Management Trainee'    
            --Select @totalamount=cast(@fixedstipend as int) + CAST(@traininingallowancnce as int)+CAST(@conveyenceallowance as int)    
            Select @appointfuturedeptname=[Department] FROM [essp].[dbo].[Department] where DepartmentId=@futureappointdept    
   Select @appointfuturedeptname=dbo.InitCap(@appointfuturedeptname)    
            Select @appointdeptname=[Department] FROM [essp].[dbo].[Department] where DepartmentId=@appointdept    
   Select @appointdeptname=dbo.InitCap(@appointdeptname)    
            --Select @appointpostname =[postname] FROM [essp].[dbo].[Postmaster] where deleteflag='No' and postid=@appointpost    
            Select @appointfuturedesignationname =[designationname] FROM [essp].[dbo].[Designationmaster] where deleteflag='No' and designationid=@futureappointdesignation    
   Select @appointfuturedesignationname=dbo.InitCap(@appointfuturedesignationname)    
            --Select @appointdesgnationname=[designationname] FROM [essp].[dbo].[Designationmaster] where deleteflag='No' and designationid=@appointdesignation    
            Select @joininghq=operationalhq,@joiningaddress=address from [essp].[dbo].[temppostinglocation] where deleteflag='No' and id=@joininglocid    
             Select @joininghq=dbo.InitCap(@joininghq)    
   Select @joiningaddress=dbo.InitCap(@joiningaddress)    
   Select @appointmentrefno=@dinref    
        --Select @joiningdatevar=convert(varchar, convert(date,@joiningdate,103),106)    
           --Select @applicationdatevar=convert(varchar, convert(date,@applicationdate,103),106)    
    
           Select @para1='In reference to your Application Dated '+@applicationdate+' and subsequent interviews you had with us and also in reference to our Offer Letter Reference : '+@offerefno+' , we are pleased to appoint you as Management Trainee in  
 
the department '+@appointdeptname+' in our Organization with effect from '+@joiningdate+' to be based at our '+@joininghq+' at '+@joiningaddress+' on the following terms and conditions:'    
               
           Select @para2='1. At the outset, your appointment will be in the Category of Management Trainee for a period of 1 year with effect from '+@joiningdate+'.'    
           
           Select @para3='2. On Successful completion of your tenure as Management Trainee, you may be considered eligible for Appointment as a '+@appointfuturedesignationname+' in our '+@appointfuturedeptname+' under probation for a period of One year pe
  
nding final confirmation in writing – subject to evaluation and review of your satisfactory performance during the tenure of your service as Management Trainee. On contrary, unsatisfactory performance during the tenure as Management Trainee may lead to te
  
rmination of service without assigning any reason whatsoever.'    
               
           Select @para4='3. Any part of furnished details/documents submitted by you along with your application for employment – if found wrong/incorrect/manipulated at any point of time in course of your employment in our Organisation (MPPL), shall be 
  
liable for termination of your employment with immediate effect without assigning any reason to you.'    
               
           Select @para5='4. You will be entitled for remuneration as per Annexure A.'    
               
           Select @para6='5. You will join your duty and discharge such duties and responsibilities as may be assigned to you from time to time and you will not directly or indirectly engage or serve in any capacity whatsoever either full or part time or 
  
undertake or carry on or be concerned in any business, trade, profession or, concern other than work assigned to you by the company.'    
               
           Select @para7='6. During the period of your employment with us or thereafter you should always keep secret and confidential and prevent the disclosure or divulgence of all information , knowledge , know-how experience, data, documents, reports,
  
 statement, records, correspondence, discussion, contracts, manufacturing processes, transactions , affairs , dealings , quotations, finance, accounts etc. of the Company that may pass through you or come through your knowledge.'    
               
           Select @para8='7. The terms and conditions of your appointment will be governed by the rules and regulations of the Company as applicable to other employees of the company and in force from time to time.'    
               
           Select @para9='8. The company will be at liberty to dispense with your services without any notice or compensation and without prejudice to any other right or claims to the company - if any breach occurs on your part at any point of time in cou
  
rse of your employment to the effect of the terms and conditions contained hereinabove. In the matter of breach of terms of employment, the company’s decision will be final and shall be binding upon you.'    
               
           Select @para10='         If the above terms and conditions are acceptable to you please sign the duplicate copy of this letter as a token of your acceptance and return it to us.'    
               
           Select @undershine=[undershine] FROM [tundershinemaster] WHERE [companycode] = 'MP' AND lettertype='Appointment Letter' and undershinedid=@undershineid    
            
         insert into tappointmentletterdtlsofmpmt    
         (    
           [candidateid]    
             --,[appointmentlettertypeid]    
    ,appointmentlettertype    
             ,[appiontmentrefno]    
             ,[offerrefno]    
             ,[appiontmentissuedate]    
             ,[candidatename]    
             ,[candidateaddress]    
                
             ,[departmentid]    
             ,[futuredesignationid]    
             ,[futuredeptid]    
    --         ,[fixedstipend]    
    --         ,[trainingallowance]    
    --,[conveyenceallowance]    
    --         ,[totalamount]    
             ,[subject]    
             ,[joiningdate]    
             ,[postinglocationid]    
             ,[para1]    
             ,[para2]    
             ,[para3]    
             ,[para4]    
             ,[para5]    
             ,[para6]    
             ,[para7]    
             ,[para8]    
            ,[para9]    
             ,[para10]    
    ,[undershine]    
             ,[deleteflag]    
             ,[createdby]    
             ,[createdon]    
                 
            
         )    
         values    
         (    
           @candidateid,    
     'MPMTOPERATION',    
           @appointmentrefno,    
           @offerefno,    
           convert(date,@appiontmentissudate,103),    
           @candidatename,    
           @candidateaddress,    
              
           @appointdept,    
           @futureappointdept,    
           @futureappointdesignation,    
     --      @fixedstipend,    
     --      @traininingallowancnce,    
     --@conveyenceallowance,    
     --      @totalamount,    
           @subject,    
           convert(date,@joiningdate,103),    
           @joininglocid,    
           @para1,    
           @para2,    
           @para3,    
           @para4,    
           @para5,    
           @para6,    
           @para7,    
           @para8,    
           @para9,    
           @para10,    
     @undershine,    
           'No',    
           @username,    
           GETDATE()    
         )    
  ---inserting salary component----------------------------------    
 If exists(Select top 1 amount from tsalaryofappointmenttime where candidateid=@candidateid )    
 begin    
  delete from tsalaryofappointmenttime where candidateid=@candidateid    
 end    
 insert into tsalaryofappointmenttime    
 (candidateid,salaryhead,amount)    
 values    
 (@candidateid,'Stipend',@stipend),    
 (@candidateid,'Training Allowance',@trainingallowance),    
 (@candidateid,'Internet Allowance',@internetallowance),    
 (@candidateid,'Total Allowance',@totalallowance),    
 (@candidateid,'Gross Amount with All Allowance',@grossamount),    
 (@candidateid,'P.F.',@pf),    
 (@candidateid,'E.S.I.C',@esic),    
 (@candidateid,'Prof. Tax',@proftax),    
 (@candidateid,'Total Deduction',@totaldeduction),    
 (@candidateid,'Payable Amount',@payebleamount),    
 (@candidateid,'Final Amount Payable',@finalpayebleamount),    
 (@candidateid,'Mobile Allowance',@mobileallowance),    
 (@candidateid,'Exgratia',@exgratia),    
 (@candidateid,'PF Contribution by Employer',@pfcontributionbyemployer),    
 (@candidateid,'ESI Contribution by Employer',@esicontributionbyemployer),    
 (@candidateid,'Gratuity',@graturity),    
 (@candidateid,'CTC Per Month',@ctcpermonth),    
 (@candidateid,'CTC Per Year',@ctcperyear)    
 ---end of inserting salary component----------------------------    
      
 ----employee creation-------------------------------------    
  EXEC essp.dbo.procautocreatenewemp    
     @username=@username,    
         
     @empfirstname=@empfirstname,    
  @empmiddlename=@empmiddlename,    
     @emplastname=@emplastname,    
     @empdob=@empdob,    
     @companycode=@companycode,    
     @adharno=@adharno,    
     @emppersonalcontactno=@emppersonalcontactno,    
     @joining=@joining,    
     @empdept=@empdept,    
     @emppost=@emppost,    
     @empdesignation=@empdesignation,    
     @empreporttopost=@empreporttopost,    
     @empreporttoperson=@empreporttoperson,    
     @emppostingstate=@emppostingstate,    
  @empgender=@candidategender,    
  @emppersonalemail=@candidateemail,    
  @outputstatus=@outmsg output,    
     @outputstatuscode=@empcreatestatuscode output,    
  @outcreatedempno=@createdempno output;    
 ----end of employee creation------------------------------  
 -- PALLAB
  --if(@empcreatestatuscode=0)    
  --begin    
     ---inserting mapping details--------    
          insert into tcandidateappointmentmapping    
          (  
      [candidateid],    
      [appointmentlettertype],    
      [deleteflag],    
      [empno],  
      [SyncYN]  
     )    
           values    
           (    
    @candidateid,    
    'MPMTOPERATION',    
    'No',    
    @createdempno,  
    'N'  
            )    
           ---end of inserting mapping details--------    
   Set @outmsg='Appoitment and Employee Created Successfully'    
   --end    
       
  end    
  else    
  begin    
         Set @outmsg=@dinref    
  end    
        
     
     
   end try    
   begin catch    
   Select @errorcode=ERROR_MESSAGE();    
   if(@errorcode = '2627')--- for checking duplicate entry by sql error code    
   begin    
     Select @outmsg='Unsuccessful!! Duplicate Entry'    
   end    
   else    
    begin    
    Set @outmsg='Error Code:'+@errorcode+'. Please Contact With Administrator.'    
   end    
    
 end catch    
    end    
end    
else    
begin    
 if(@countdupadharno >0)    
 begin     
   set @outmsg='Failed!! Duplicate Adhar No,'    
 end    
 else if(@countduppersonalcontactno >0)    
 begin     
   set @outmsg='Failed!! Duplicate Personal Contact No,'    
 end    
else    
 begin     
   set @outmsg=@outmsg+'Failed!! Duplicate Combination Of Firstname Middlename Lastname and Adhar No,'    
 end    
end    
end 
GO



