SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[procgenerateofferlaettermp]                        
@candiadteid int=null,                        
@refno nvarchar(Max)=null,                      
@ESIC_alert int =null,                    
@jioningdate varchar(100)=null,              
          
@officenameid varchar(max)=null,                        
@username varchar(max)=null,                        
@action varchar(200)=null,                        
@offercompanycode varchar(50)=null,                        
@issalaryattached int =
null,                        
 --------salary parameters------------                        
@basicorstipened varchar(20) =null,                        
@hra varchar(20) =null,                        
@eduallowance varchar(20) =null,                      
  
@booksandperiodicalallowance varchar(20) =null,                        
@medicalallowance varchar(20) =null,                        
@lta varchar(20) =null,                        
@attrairtrainingallowance varchar(20) =null,                        
@conveayancelodgingallowance varchar(20) =null,                        
@internetallowance varchar(20) =null,                        
@totalallowance varchar(20) =null,                        
@grossamount varchar(20) =null,                        
@pf varchar(20) =null,                        
@esic varchar(20) =null,                        
@proftax varchar(20) =null,                        
@totaldeduction varchar(20) =null,                        
@payebleamount varchar(20) =null,                       
 
@finalpayebleamount varchar(20) =null,                        
@exgratia varchar(20) =null,                        
@pfcontributionbyemployer varchar(20) =null,                        
@esicontributionbyemployer varchar(20) =null,                       
 
@graturity varchar(20) =null,                        
@mobileallowance varchar(20) =null,                        
@ctcpermonth varchar(20) =null,                        
@ctcperyear varchar(20) =null,                        
@basisorstipendsalhead nvarchar(max)=null,                        
@attairortrainingallowancesalhead nvarchar(max)=null,                        
@conveyanceorlodgingallowancesalhead nvarchar(max)=null,                        
@candiadtetype varchar(20)=null,                        

@stipend varchar(20)=null,                        
@trainingallowance varchar(20)=null,                        
@conveyanceallowance varchar(20)=null,    
    
@undersignid int=null,                        
@letterFilePath nvarchar(max)=null,    
@letterFileName nvarchar(max)=null,                       
@ContentType nvarchar(max)=null, 
@FileBinary varbinary(max) = null,
@outmessage varchar(Max)=null output                         
as                        
Declare @offerissueddate varchar(100)                     
   
Declare @canaddress nvarchar(max)                       
Declare @canpin varchar(max) =NULL                      
Declare @subject nvarchar(max)                        
Declare @cananme varchar(300)                      
Declare @canfirstname varchar(
300)=NULL                      
Declare @paraone nvarchar(Max)                        
Declare @paratwo nvarchar(max)                        
Declare @parathree nvarchar(max)                        
Declare @parafour nvarchar(max)                        

Declare @parafive nvarchar(max)                        
Declare @listofdocuments nvarchar(max)                        
declare @joinglocation nvarchar(Max)                        
declare @duplicatecandidate int                        
declare @duplicaterefno int                        
Declare @dintitleanddescription nvarchar(max)                        
Declare @candidatenamefordin nvarchar(max)                        
declare @dincreatestatus int                        
declare @dinref nvarchar(max)   
                     
declare @weeklyleave int=0                        
declare @undersign nvarchar(200)                        
declare @salutations varchar(30)            
begin                        
select @duplicatecandidate=count([candidateid])  
from [tofferlatterdtls] where [candidateid]=@candiadteid and [deleteflag]='No'                        
select @duplicaterefno=count([offerrefno])  from [tofferlatterdtls] where [offerrefno]=@refno and [deleteflag]='No'                        
SELECT @weeklyleave = Count(*)                        
  FROM [essp].[dbo].[tleaveweeklyholiday]                        
  WHERE [holiday date]=CONVERT(date,@jioningdate,103)                        
                        
if(@weeklyleave > 0)                        

begin                        
Set @outmessage='Joining Date Can''t Be Weekly Holiday'                        
end                        
else if(@duplicatecandidate >=1)                        
begin            
 Set @outmessage='Offer Letter For This C
andidate Already Exists'                        
end                        
else if(@duplicaterefno >=1)                        
begin                        
   Set @outmessage='Reference Number Already Exists'                        
end               
         
else                        
begin             
            
            
            
-------------------------------ishita-------------------------------------            
            
declare @addressval nvarchar(max)            
 select @addressval = [addressline] from trecruitcanaddress where candidateid=@candiadteid             
            
declare @Space char(1) = ' '            
            
-- Upper case first letter and all others in lower case letters            
select @addressval =
 STUFF(LOWER(@addressval), 1, 1, UPPER(LEFT(@addressval,1)) )            
            
-- search for space character            
declare @i int = CHARINDEX(@Space, @addressval, 1)            
            
while @i > 0            
begin            
 select
 @i = @i + 1            
 -- replace character after space with its upper case letter            
 select @addressval = STUFF(@addressval, @i, 1, UPPER( SUBSTRING(@addressval, @i, 1)) )            
 -- search for next space character            
 select @i = CHARINDEX(@Space, @addressval, @i)            
end            
----------------------------------------------------------state--------------------------------------            
declare @stateval nvarchar(max)            
 select @stateval = b.[statename] from [trecruitstate]b ,trecruitcanaddress a where a.state=b.stateid and a.candidateid=@candiadteid             
            
declare @Space2 char(1) = ' '            
            
-- Upper case first letter and all others in lower case letters        
    
select @stateval = STUFF(LOWER(@stateval), 1, 1, UPPER(LEFT(@stateval,1)) )            
            
-- search for space character            
declare @j int = CHARINDEX(@Space2, @stateval, 1)            
            
while @j > 0            
begin  
          
 select @j = @j + 1            
 -- replace character after space with its upper case letter            
 select @stateval = STUFF(@stateval, @j, 1, UPPER( SUBSTRING(@stateval, @j, 1)) )            
 -- search for next space character          
  
 select @j = CHARINDEX(@Space2, @stateval, @j)            
end            
            
----------------------------------------------------------postoffice-----------------------------            
            
declare @postofcval nvarchar(max)        
    
 select @postofcval = postoffice from trecruitcanaddress where candidateid=@candiadteid            
            
declare @Space3 char(1) = ' '            
            
-- Upper case first letter and all others in lower case letters            
select
 @postofcval = STUFF(LOWER(@postofcval), 1, 1, UPPER(LEFT(@postofcval,1)) )            
            
-- search for space character            
declare @k int = CHARINDEX(@Space3, @postofcval, 1)            
            
while @k > 0            
begin     
       
 select @k = @k + 1            
 -- replace character after space with its upper case letter            
 select @postofcval = STUFF(@postofcval, @k, 1, UPPER( SUBSTRING(@postofcval, @k, 1)) )            
 -- search for next space character       
     
 select @k = CHARINDEX(@Space3, @postofcval, @k)            
end            
            
            
----------------------------------------------------------------------------------------------------------            
                          

                          
  Select @canaddress=@addressval+' , '+UPPER(LEFT([villagecity],1))+LOWER(SUBSTRING([villagecity],2,LEN([villagecity])))+' , '+@postofcval                       
     FROM [trecruitcanaddress]a,                        
     [trecruitstate]b,                        
     [trecrutdistrict]c                        
     where a.district=c.disid                  
     and a.state=b.stateid                        
     and [addresstype]='P'                        
     and candidateid=@candiadteid                        
                        
  --Select @canaddress=dbo.initcap(@canaddress)                      
                        
                      
  Select  @canpin=UPPER(LEFT(c.[disname],1))+LOWER(SUBSTRING(c.[disname],
2,LEN(c.[disname])))+'-'+UPPER(LEFT(a.[pincode],1))+LOWER(SUBSTRING(a.[pincode],2,LEN(a.[pincode])))+' , '+@stateval                  
  FROM   [trecruitcanaddress]a,                      
    [trecruitstate]b,                      
    [trecrutdistrict]c
                      
  Where   a.district=c.disid                      
   and a.state=b.stateid                      
   and [addresstype]='P'                      
   and candidateid=@candiadteid                      
                      
          
            
               
                      
                      
                             
     Select @cananme=UPPER(LEFT(firstname,1))+LOWER(SUBSTRING(firstname,2,LEN(firstname)))+' '+UPPER(LEFT(middlename,1))+LOWER(SUBSTRING(middlename,2,
LEN(middlename)))+' '+UPPER(LEFT(lastname,1))+LOWER(SUBSTRING(lastname,2,LEN(lastname))),                
  
    
      
  @salutations=case gender                        
    when 'Male' then 'Mr.'                        
 when 'Female' then 'Ms.'       
                 
 else 'other'                        
    end                         
    FROM [trecruitcanbasicdtls]                        
     where candidateid=@candiadteid                        
  --Select @cananme=dbo.initcap(@cananme)        
  
   Select  @canfirstname=UPPER(LEFT(firstname,1))+LOWER(SUBSTRING(firstname,2,LEN(firstname)))                      
  FROM   [trecruitcanbasicdtls]                     
   
  where   candidateid=@candiadteid                        
                      
                      
                      
                      
  Select @cananme=@salutations+' '+@cananme                        
     Select @subject='Offer Of Employment'                        
  Select @undersign=[undershine] FROM [tundershinemaster] WHERE   undershinedid=@undersignid                        
    -- Select @joinglocation=[operationalhq] +' at ' + [address] FROM [essp].[dbo].[temppostinglocation] where id=@officenameid                        
  if(@offercompanycode='MP')                        
  begin                        
      Select @candidatenamefordin=firstname+' '+middlename+' '+lastname FROM [trecruitcanbasicdtls]                      
  
         where candidateid=@candiadteid                        
   Select @candidatenamefordin=dbo.initcap(@candidatenamefordin)                        
         select @dintitleanddescription='Offer Letter For '+@candidatenamefordin                   
      
         EXEC essp.dbo.procautodincreate                         
      @dinfrom=1,                        
      @company='MP',                        
      @doctype='L',                        
      @dintitle=@dintitleanddescription,           

      @dindescription=@dintitleanddescription,                        
      @givento=@candidatenamefordin,                        
      @username=@username,                        
      @outputstatuscode=@dincreatestatus output,                       
 
      @outputstatus=@dinref output;                        
         Select @refno=@dinref                        
                            
   Select @paraone='In reference to your application for employment in our Company and the subsequent interview you had with us, we are pleased to offer you an employment in our Company. The Designation and Remuneration Package, as mutually agreed upon,sh
all be communicated to you on your joining with us.'                   
 Select @paratwo='Please note that this is merely an offer letter. The Company’s standard Appointment Letter- containing exhaustive Terms and Conditions of employment, will be issued to you on your joining the Company- which shall be binding on you.'     
 
     
      
        
   
                
  Select @parathree='You are requested to join us by '+@jioningdate+'. In the event of your not joining us within the aforementioned date or not requesting for an extension to that effect, this offer shall stand withdrawn automatically.' 
                 
  
   
   Select @parafour='You are required to submit the following at the time of joining'                        
  Select @parafive='I hereby declare that, I have read and understood the above-mentioned terms and in agreement with th
em and also hereby confirm to accept the offer.'                        
                        
                        
  Insert into [tofferlatterdtls]                        
  (                        
    [candidateid]                       
 ,[offerrefno]                        
      ,[candidatename]                        
      ,[candidateaddress]                        
      ,[offerissueddate]                        
      ,[subject]                        
      ,[postinglocationid]   
                     
      ,[paraone]                        
      ,[paratwo]                        
      ,[parathree]                        
      ,[parafour]                        
      ,[parafive]                        
      ,[offerdcompanycode]                        
      ,[joiningdate]                  
      ,[offerexpirydate]                        
   ,[isexpired]                        
      ,[deleteflag]                        
      ,[createdby]                        
      ,[createdon]                        
   ,[stipend]                        
   ,[trainingallowance]                        
   ,[conveyanceallowance]                        
   ,[undersign]                        
   ,[candidatetype]    
   ,[LetterFilePath]    

   ,[LetterFileName]    
   ,[ContentType]
   ,[FileBinary]
  )                        
  values                        
  (             
  @candiadteid,                        
  @refno,                        
  @cananme,                    
  @canaddress +','+ @canpin,                        
  convert(varchar,getdate(),103),                        
  @subject,                        
  @officenameid,                        
  @paraone,                        
  @paratwo,                        
  @parathree,        
                
  @parafour,                        
  @parafive,                        
  @offercompanycode,                        
  @jioningdate,                        
  @jioningdate,                        
  'No',                        
  'No',      
  @username,                        
  getdate(),                        
  @stipend,                        
  @trainingallowance,                        
  @conveyanceallowance,                        
 @undersign,          
  @candiadtetype,                        
  @letterFilePath,              
   @letterFileName,   
   @ContentType
   ,@FileBinary
  )                        
             
  end                       
                      
  if(@offercompanycode='ML')         
  begin                        
                             
          Select @candidatenamefordin=firstname+' '+middlename+' '+lastname FROM [trecruitcanbasicdtls] where candidateid=@candiadteid               
         
    Select @candidatenamefordin=dbo.initcap(@candidatenamefordin)                        
         select @dintitleanddescription='Offer Letter For '+@candidatenamefordin                         
         EXEC essp.dbo.procautodincreate         
                
      @dinfrom=1,                        
      @company='ML',                        
      @doctype='L',                        
      @dintitle=@dintitleanddescription,                        
      @dindescription=@dintitleanddescription,                        
      @givento=@candidatenamefordin,                        
      @username=@username,                        
      @outputstatuscode=@dincreatestatus output,                        
      @outputstatus=@dinref output;          
         Select @refno=@dinref                        
   Select @paraone='In reference to your application for employment in our Company and the subsequent interview you had with us, we are pleased to offer you employment in our Company. The Designation and Remuneration Package, as mutually agreed upon, shall be communicated to you on your joining with us.'      
         
         Select @paratwo='Please note that this is merely an Offer Letter. The Company’s standard Appoint
ment Letter- containing exhaustive Terms and Conditions of employment, will be issued to you on your joining the Company- which shall be binding upon you.'      
         
         Select @parathree='You are requested to join us by '+@jioningdate+'. In the event of your not joining us on or within the aforementioned date or not requesting for an extension to that effect, this offer shall stand withdrawn automatically.'     
         Select @parafour='You are required to submit the following at the time of joining'                        
         Select @parafive='I hereby declare that, I have read and understood the above-mentioned terms and in agreement with them and also hereby confirm to accept the offer.'                           
  Insert into [tofferlatterdtls]                        
  (                        
    [candidateid]                        
      ,[offerrefno]                        
      ,[candidatename]                      
   ,[canfirstname]                    
      ,[ESIC]                    
      ,[candidateaddress]                      
     ,[canpin] 
                     
      ,[offerissueddate]                        
      ,[subject]                        
      ,[postinglocationid]                        
      ,[paraone]                        
      ,[paratwo]                        
      ,[parathree]                        
      ,[parafour]                        
      ,[parafive]                     
      ,[offerdcompanycode]                        
      ,[joiningdate]                        
      ,[offerexpirydate]                     
   
   ,[isexpired]                        
      ,[deleteflag]                        
      ,[createdby]                        
      ,[createdon]                        
   ,[stipend]                        
   ,[trainingallowance]                    
    
   ,[conveyanceallowance]                        
   ,[undersign]                        
   ,[candidatetype]     
   ,[LetterFilePath]    
   ,[LetterFileName]  
   ,[ContentType]  
  )                        
  values                        
  (           
  @candiadteid,                        
  @refno,                    
  @cananme,                      
  @canfirstname,                     
  @ESIC_alert,                    
  @canaddress,                       
  @canpin,        
              
  convert(varchar,getdate(),103),                        
  @subject,                        
  @officenameid,                        
  @paraone,                        
  @paratwo,            
  @parathree,                        
  @parafour,                        
  @parafive,                        
  @offercompanycode,                        
  @jioningdate,                        
  @jioningdate,                        
  'No',                        
  'No',                        
  @username,                        
  getdate(),                        
  @stipend,                        
  @trainingallowance,                        
  @conveyanceallowance,                        
  @undersign,                        
  @candiadtetype,                        
  @letterFilePath,              
   @letterFileName,  
   @ContentType  
  )                        
  end                       
    ---inserting salary component----------------------------------                        
 if
(@issalaryattached =1)     
 begin                                    
 If exists(Select top 1 amount from tsalaryofoffertime  where candidateid=@candiadteid )                        
 begin                        
  delete from tsalaryofoffertime where candidateid=@candiadteid                        
 end                        
    if(@candiadtetype ='EXP')                        
    begin                        
       insert into tsalaryofoffertime                        
		(candidateid,salaryhead,amount)                        
 values                        
 (@candiadteid,@basisorstipendsalhead,@basicorstipened),                        
 (@candiadteid,'HRA',@hra),                        
 (@candiadteid,'Education Allowance',@eduallowance),                        
 (@candiadteid,'Books & Periodical Allowance',@booksandperiodicalallowance),                        
(@candiadteid,'Medical Allowance',@medicalallowance),                        
 (@candiadteid,'LTA',@lta),                  
 (@candiadteid,@attairortrainingallowancesalhead,@attrairtrainingallowance),                      
 (@candiadteid,@conveyanceorlodgingallowancesalhead,@conveayancelodgingallowance),                        
 (@candiadteid,'Internet Allowance',@internetallowance),                        
 (@candiadteid,'Total Allowance',@totalallowance),                        
 (@candiadteid,'Gross Amount with All Allowance',@grossamount),                        
 (@candiadteid,'P.F.',@pf),                        
 (@candiadteid,'E.S.I.C',@esic),                        
 (@candiadteid,'Prof. Tax',@proftax),                        
 (@candiadteid,'Total Deduction',@totaldeduction),                        
 (@candiadteid,'Payable Amount',@payebleamount),                     
 (@candiadteid,'Final Amount Payable',@finalpayebleamount),                        
 (@candiadteid,'Exgratia',@exgratia),                        
 (@candiadteid,'PF Contribution by Employer',@pfcontributionbyemployer),                        
 (@candiadteid,'ESI Contribution by Employer',@esicontributionbyemployer),                        
 (@candiadteid,'Gratuity',@graturity),                        
 (@candiadteid,'Mobile Allowance',@mobileallowance),                        
 (@candiadteid,'CTC Per Month',@ctcpermonth),                        
 (@candiadteid,'CTC Per Year',@ctcperyear)   
    end                        
 if(@candiadtetype ='MT')                        
    begin                        
       insert into tsalaryofoffertime                        
 (candidateid,salaryhead,amount)                        
 values                        
 (@candiadteid,'Stipend',@stipend),                        
 (@candiadteid,'Training Allowance',@trainingallowance),     
                   
 (@candiadteid,'Internet Allowance',@internetallowance),                        
 (@candiadteid,'Total Allowance',@totalallowance),                        
 (@candiadteid,'Gross Amount with All Allowance',@grossamount),                
        
 (@candiadteid,'P.F.',@pf),                        
 (@candiadteid,'E.S.I.C',@esic),                        
 (@candiadteid,'Prof. Tax',@proftax),                        
 (@candiadteid,'Total Deduction',@totaldeduction),                        

 (@candiadteid,'Payable Amount',@payebleamount),                        
 (@candiadteid,'Final Amount Payable',@finalpayebleamount),                        
 (@candiadteid,'Mobile Allowance',@mobileallowance),                        
 (@candiadteid,'Exgratia',@exgratia),                        
    (@candiadteid,'PF Contribution by Employer',@pfcontributionbyemployer),                        
 (@candiadteid,'ESI Contribution by Employer',@esicontributionbyemployer),                    
 (@candiadteid,'Gratuity',@graturity),                        
    (@candiadteid,'CTC Per Month',@ctcpermonth),                        
 (@candiadteid,'CTC Per Year',@ctcperyear)                        
    end                        
 end                        
          
              
                        
                        
 ---end of inserting salary component----------------------------                 
  Set @outmessage='Offer Letter Successfully Created'                 
end                        
        
                 
                        
  --Select @candiadteid candiadteid,                        
  --@refno refno,                        
  --convert(varchar,getdate(),103) offerissueddate,                        
  --@canaddress canaddress,      
                  
  --@cananme cananme,                        
  --@subject subject,                        
