/* Functional group: 09_OFFER_APPOINTMENT_ONBOARDING; referenced grouped tables: tappointmentletterdtlsofmlexpoperation, tappointmentletterdtlsofmlmtfield, tappointmentletterdtlsofmlmtoperation, tappointmentletterdtlsofmpmt, tappointmentletterdtlsofmpmtfield, tappointmentletterformlexpfield, tappointmentletterformpexp, tappointmentletterformpexpfield, tcandidateappointmentmapping, tofferlatterdtls, trecruitcandidatesignup */
/****** Object:  StoredProcedure [dbo].[procgetcanjoiningstatus]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[procgetcanjoiningstatus]
@username varchar(Max)=null,
@Action varchar(Max)=null,
@offeracceptancestatus varchar(100)=null,
@status int=null output  ,
@compnameout varchar(50)= null output,
@canappoitmenttypeout varchar(50)= null output
as
Declare @countoffer int
Declare @countappiontment int
declare @candidateid int
declare @compname varchar(50)
declare @appointmenttype varchar(50)
begin
SELECT @candidateid = [candidateid] 
      FROM   [dbo].[trecruitcandidatesignup] 
      WHERE  [username] = @username 
	  print @candidateid
	  if(@Action='JOINING' )
	  begin
		  Select @countoffer=count([candidateid])  FROM [dbo].[tofferlatterdtls]
          where [deleteflag]='No'
          and [isexpired]='No'
          and [offernotificationsent]='Yes'
          and [candidateid]=@candidateid
          PRINT @countoffer
          Select @compname=[offerdcompanycode]  FROM [dbo].[tofferlatterdtls]
          where [deleteflag]='No'
          and [isexpired]='No'
          and [offernotificationsent]='Yes'
          and [candidateid]=@candidateid
		  Select @appointmenttype=appointmentlettertype from [tcandidateappointmentmapping]
          where candidateid=@candidateid
		  and deleteflag='No'
		  if(@appointmenttype='MPMTOPERATION')
		  begin
		    Select @countappiontment=count(candidateid) from tappointmentletterdtlsofmpmt 
			where candidateid=@candidateid
			and deleteflag='No'
			and appointmentnotificationsent='Yes'
		  end
		   if(@appointmenttype='MLMTOPERATION')
		  begin
		    Select @countappiontment=count(candidateid) from tappointmentletterdtlsofmlmtoperation 
			where candidateid=@candidateid
			and deleteflag='No'
			and appointmentnotificationsent='Yes'

		  end
		  if(@appointmenttype='MLMTFIELD')
		  begin
		    Select @countappiontment=count(candidateid) from tappointmentletterdtlsofmlmtfield 
			where candidateid=@candidateid
			and deleteflag='No'
			and appointmentnotificationsent='Yes'

		  end
		  if(@appointmenttype='MLEXPFIELD')
		  begin
		    Select @countappiontment=count(candidateid) from tappointmentletterformlexpfield 
			where candidateid=@candidateid
			and deleteflag='No'
			and appointmentnotificationsent='Yes'

		  end
		  if(@appointmenttype='MPEXPOPERATION')
		  begin
		    Select @countappiontment=count(candidateid) from tappointmentletterformpexp 
			where candidateid=@candidateid
			and deleteflag='No'
			and appointmentnotificationsent='Yes'

		  end
		  if(@appointmenttype='MLEXPOPERATION')
		  begin
		    Select @countappiontment=count(candidateid) from tappointmentletterdtlsofmlexpoperation 
			where candidateid=@candidateid
			and deleteflag='No'
			and appointmentnotificationsent='Yes'

		  end
		  if(@appointmenttype='MPMTFIELD')
		  begin
		    Select @countappiontment=count(candidateid) from tappointmentletterdtlsofmpmtfield 
			where candidateid=@candidateid
			and deleteflag='No'
			and appointmentnotificationsent='Yes'

		  end
		  if(@appointmenttype='MPEXPFIELD')
		  begin
		    Select @countappiontment=count(candidateid) from tappointmentletterformpexpfield 
			where candidateid=@candidateid
			and deleteflag='No'
			and appointmentnotificationsent='Yes'

		  end
		  
         
          if @countoffer=1
          begin
  	       set @status=1 ---for showing offer letter tab
		   if @countappiontment=1
            begin
  	          set @status=2 ---for showing appointment letter tab
            end
          end
          
          else
          begin
  	       set @status=0 -- for showing application status tab
          end
          
          Set @compnameout=@compname
		  Set @canappoitmenttypeout=@appointmenttype
	  end
	  if(@Action='OFFER')
	  begin
		Select [acceptancestatus],convert(varchar,[acceptancestatuschangeon],105)acceptancestatuschangeon from [dbo].[tofferlatterdtls]
		where deleteflag='No'
		and [isexpired]='No'
		and candidateid=@candidateid
	  end
	  if(@Action='OFFERACCEPTSTATUS')
	  begin
		Update [dbo].[tofferlatterdtls]
		Set [acceptancestatus]=@offeracceptancestatus,
		[acceptancestatuschangeon]=getdate()
		where deleteflag='No'
		and [isexpired]='No'
		--and [acceptancestatus]<>'No' 
		and candidateid=@candidateid
	  end
	  



end
GO



