CREATE Proc [dbo].[procgetmlmtappointmentsalaydtls]
@basicorstipened varchar(20) =null,
@hra varchar(20) =null,
@eduallowance varchar(20) =null,
@booksandperiodicalallowance varchar(20) =null,
@medicalallowance varchar(20) =null,
@lta varchar(20) =null,
@attrairtrainingallowance varchar(20) =null,
@conveayancelodgingallowance varchar(20) =null,
@internetallowance varchar(20) =null,
@totalallowance varchar(20) =null,
@grossamount varchar(20) =null,
@pf varchar(20) =null,
@esic varchar(20) =null,
@proftax varchar(20) =null,
@totaldeduction varchar(20) =null,
@payebleamount varchar(20) =null,
@finalpayebleamount varchar(20) =null,
@exgratia varchar(20) =null,
@pfcontributionbyemployer varchar(20) =null,
@esicontributionbyemployer varchar(20) =null,
@graturity varchar(20) =null,
@mobileallowance varchar(20) =null,
@ctcpermonth varchar(20) =null,
@ctcperyear varchar(20) =null,

@basisorstipendsalhead nvarchar(max),
@attairortrainingallowancesalhead nvarchar(max),
@conveyanceorlodgingallowancesalhead nvarchar(max)
as
begin
--Create table #tmpsal
--(
--  salhead varchar(200),
--  salamount varchar(20)
--);
--insert into #tmpsal
--(salhead,salamount)
--values
--('Basic',@basicorstipened),
--('HRA',@hra),
--('Education Allowance',@eduallowance),
-- ('Books & Periodical Allowance',@booksandperiodicalallowance),
-- ('Medical Allowance',@medicalallowance),
-- ('LTA',@lta),
-- ('Attire Allowance/Training Allowance',@attrairtrainingallowance),
-- ('Conveyance Allowance/ Lodging Allowance',@conveayancelodgingallowance),
-- ('Internet Allowance',@internetallowance),
-- ('Total Allowance',@totalallowance),
-- ('Gross Amount with All Allowance',@grossamount),
-- ('P.F.',@pf),
-- ('E.S.I.C',@esic),
-- ('Prof. Tax',@proftax),
-- ('Total Deduction',@totaldeduction),
-- ('Payable Amount',@payebleamount),
-- ('Final Amount Payable',@finalpayebleamount),
-- ('Exgratia',@exgratia),
-- ('PF Contribution by Employer',@pfcontributionbyemployer),
-- ('ESI Contribution by Employer',@esicontributionbyemployer),
-- ('Gratuity',@graturity),
-- ('Mobile Allowance',@mobileallowance),
-- ('CTC Per Month',@ctcpermonth),
-- ('CTC Per Year',@ctcperyear)

-- Select salhead,salamount from #tmpsal where salamount <>'0'
-- drop table #tmpsal
Select salhead, salamount from
  (Select @basisorstipendsalhead salhead,@basicorstipened salamount
  UNION ALL SELECT 'HRA',@hra
 UNION ALL SELECT 'Education Allowance',@eduallowance
 UNION ALL SELECT 'Books & Periodical Allowance',@booksandperiodicalallowance
 UNION ALL SELECT 'Medical Allowance',@medicalallowance
 UNION ALL SELECT 'LTA',@lta
 UNION ALL SELECT @attairortrainingallowancesalhead,@attrairtrainingallowance
 UNION ALL SELECT @conveyanceorlodgingallowancesalhead,@conveayancelodgingallowance
 UNION ALL SELECT 'Internet Allowance',@internetallowance
 UNION ALL SELECT 'Total Allowance',@totalallowance
 UNION ALL SELECT 'Gross Amount with All Allowance',@grossamount
 UNION ALL SELECT 'P.F.',@pf
 UNION ALL SELECT 'E.S.I.C',@esic
 UNION ALL SELECT 'Prof. Tax',@proftax
 UNION ALL SELECT 'Total Deduction',@totaldeduction
 UNION ALL SELECT 'Payable Amount',@payebleamount
 UNION ALL SELECT 'Final Amount Payable',@finalpayebleamount
 UNION ALL SELECT 'Exgratia',@exgratia
 UNION ALL SELECT 'PF Contribution by Employer',@pfcontributionbyemployer
 UNION ALL SELECT 'ESI Contribution by Employer',@esicontributionbyemployer
 UNION ALL SELECT 'Gratuity',@graturity
 UNION ALL SELECT 'Mobile Allowance',@mobileallowance
 UNION ALL SELECT 'CTC Per Month',@ctcpermonth
 UNION ALL SELECT 'CTC Per Year',@ctcperyear)a
 where a.salamount <>'0'


end
GO



