GO
create proc [dbo].[procgetmtapoointmentsalarydtls]
@stipend varchar(20) =null,
@trainingallowance varchar(20) =null,

@internetallowance varchar(20) =null,
@totalallowance varchar(20) =null,
@grossamount varchar(20) =null,
@pf varchar(20) =null,
@esic varchar(20) =null,
@proftax varchar(20) =null,
@totaldeduction varchar(20) =null,
@payebleamount varchar(20) =null,
@finalpayebleamount varchar(20) =null,
@exgratia varchar(20) =null,
@pfcontributionbyemployer varchar(20) =null,
@esicontributionbyemployer varchar(20) =null,
@graturity varchar(20) =null,
@mobileallowance varchar(20) =null,
@ctcpermonth varchar(20) =null,
@ctcperyear varchar(20) =null
as
begin
Select salhead, salamount from
       (Select 'Stipend' salhead,@stipend salamount
       UNION ALL SELECT 'Training Allowance',@trainingallowance
       UNION ALL SELECT 'Internet Allowance',@internetallowance
	   UNION ALL SELECT 'Total Allowance',@totalallowance
	   UNION ALL SELECT 'Gross Amount with All Allowance',@grossamount
	   UNION ALL SELECT 'P.F.',@pf
       UNION ALL SELECT 'E.S.I.C',@esic
       UNION ALL SELECT 'Prof. Tax',@proftax
       UNION ALL SELECT 'Total Deduction',@totaldeduction
       UNION ALL SELECT 'Payable Amount',@payebleamount
       UNION ALL SELECT 'Final Amount Payable',@finalpayebleamount
	   UNION ALL SELECT 'Mobile Allowance',@mobileallowance
	   UNION ALL SELECT 'Exgratia',@exgratia
       UNION ALL SELECT 'PF Contribution by Employer',@pfcontributionbyemployer
       UNION ALL SELECT 'ESI Contribution by Employer',@esicontributionbyemployer
	   UNION ALL SELECT 'Gratuity',@graturity
       UNION ALL SELECT 'CTC Per Month',@ctcpermonth
       UNION ALL SELECT 'CTC Per Year',@ctcperyear)a
       where a.salamount <>'0'
end
GO



/* Functional group: 09_OFFER_APPOINTMENT_ONBOARDING; referenced grouped tables: Company, tofferlatterdtls */
/****** Object:  StoredProcedure [dbo].[procgetofferletterfordownload]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[procgetofferletterfordownload]  
@candidateid int=null  
as  
begin  
declare @cantype nvarchar(max)    
declare @Joining nvarchar(max)  
    
select @cantype = candidatetype     
from tofferlatterdtls     
where candidateid=@candidateid      
  
select @Joining = joiningdate     
from tofferlatterdtls     
where candidateid=@candidateid 

Select [candidateid] candiadteid,  
  [offerrefno] refno,  
  [offerissueddate] offerissueddate,  
  [candidateaddress] canaddress,  
  [candidatename] cananme,  
   subject,  
    'This has reference to your application for employment in our Company and the subsequent interview you had with us, we are pleased to offer you an employment in our Company. The Designation and Remuneration Package, as mutually agreed upon, shall be communicated to you on your joining with us.' as   paraone,

   paratwo,  

   'You are requested to join us by ' + @Joining + '.Your acceptance of this offer should reach us per revert mail within 72 hours of date of issuing this letter.'+char(10)+char(10)+'In the event of you’re not joining us within the aforementioned date or not requesting for an extension to that effect, this offer shall stand withdrawn automatically.' as parathree,  

   parafour,  
   parafive,  
   undersign  
  FROM [dbo].[tofferlatterdtls]  
  where candidateid=@candidateid  
  and deleteflag='No'  
end  
GO



