CREATE proc [dbo].[procgetoffertimesalaryatappointment]
@candidateid int,
@candidatetype varchar(20)
as
begin
 if (@candidatetype='EXP')
 begin
 Select * from
 ( Select candidateid,salaryhead basicorstipend,[amount]basicorstipendamount from [tsalaryofoffertime] where (salaryhead='Basic' or salaryhead='Stipend') and candidateid=@candidateid)a,
 
   (Select salaryhead attairortrainingallowance from [tsalaryofoffertime] where (salaryhead='Attire Allowance' or salaryhead='Training Allowance')  and candidateid=@candidateid)b,
   (Select salaryhead conveyanceorlodgingallowance from [tsalaryofoffertime] where (salaryhead='Conveyance Allowance' or salaryhead='Lodging Allowance')  and candidateid=@candidateid)c,
   (Select amount internetallowanceamount from [tsalaryofoffertime] where salaryhead='Internet Allowance'   and candidateid=@candidateid)d,
   (Select amount grossamount from [tsalaryofoffertime] where salaryhead='Gross Amount with All Allowance'   and candidateid=@candidateid)e,
   (Select amount mobileallowanceamount from [tsalaryofoffertime] where salaryhead='Mobile Allowance'   and candidateid=@candidateid)f
 End
 if (@candidatetype='MT')
 begin
 Select * from
 ( Select amount stipendamount from [tsalaryofoffertime] where salaryhead='Stipend' and candidateid=@candidateid)a,
 (Select  amount tallowanceamount from [tsalaryofoffertime] where salaryhead='Training Allowance'   and candidateid=@candidateid)c,
   (Select amount internetallowanceamount from [tsalaryofoffertime] where salaryhead='Internet Allowance'   and candidateid=@candidateid)d,
   (Select amount mobileallowanceamount from [tsalaryofoffertime] where salaryhead='Mobile Allowance'   and candidateid=@candidateid)f
 End
end
GO



