CREATE proc [dbo].[procmlmtoperationappointmentdtls]
@action varchar(max)=null,
@candidateid int,
@offerefno nvarchar(Max)=null,
--@fixedstipend varchar(100)=null,
--@traininingallowancnce varchar(100)=null,
--@conveyenceallowance varchar(100)=null,
@applicationdate varchar(100)=null,
@appointdept int=null,
--@appointpost int=null,
--@appointdesignation int =null,
@joininglocid int=null,
@futureappointdept int=null,
@futureappointdesigantion int=null,
@joiningdate varchar(200)=null,
@undershineid int=null


as
Declare @appointmentrefno nvarchar(Max)
Declare @appiontmentissudate varchar(max)
Declare @candidatename nvarchar(Max)
Declare @candidateaddress nvarchar(Max)
Declare @subject nvarchar(Max)
--Declare @totalamount int
--Declare @appointpostname nvarchar(Max)
Declare @appointdeptname nvarchar(Max)
Declare @appointfuturedesgnationname nvarchar(Max)
--Declare @appointfuturepostname nvarchar(Max)
Declare @appointfuturedeptname nvarchar(Max)
Declare @joininghq nvarchar(Max)
Declare @joiningaddress nvarchar(Max)
Declare @para1 nvarchar(Max)
Declare @para2 nvarchar(Max)
Declare @para3 nvarchar(Max)
Declare @para4 nvarchar(Max)
Declare @para5 nvarchar(Max)
Declare @para6 nvarchar(Max)
Declare @para7 nvarchar(Max)
Declare @para8 nvarchar(Max)
Declare @para9 nvarchar(Max)
Declare @para10 nvarchar(Max)
--Declare @totalamoutinword varchar(Max)
Declare @undershine nvarchar(Max)
declare @salutations varchar(30)
begin
Select @appiontmentissudate=convert(varchar,getdate(),103)
Select @candidatename=firstname+' '+middlename+' '+lastname,
 @salutations=case gender
    when 'Male' then 'Mr.'
	when 'Female' then 'Ms.'
	else 'other'
	end
 FROM [Recruitment].[dbo].[trecruitcanbasicdtls]
where candidateid=@candidateid
Select @candidatename=dbo.InitCap(@candidatename)
Select @candidatename=@salutations+' '+@candidatename
Select @candidateaddress=[addressline]+','+[villagecity]+','+[postoffice]+','+c.[disname]+','+b.[statename]+'-'+[pincode]  
  FROM [Recruitment].[dbo].[trecruitcanaddress]a,
  [Recruitment].[dbo].[trecruitstate]b,
  [Recruitment].[dbo].[trecrutdistrict]c
  where a.candidateid=@candidateid
  and a.district=c.disid
  and a.state=b.stateid
  and [addresstype]='P'

Select @candidateaddress=dbo.InitCap(@candidateaddress)
Select @subject='Appointment Letter for Management Trainee'
--Select @totalamount=cast(@fixedstipend as int) + CAST(@traininingallowancnce as int)+ CAST(@conveyenceallowance as int)
--Select @totalamoutinword=dbo.[fnNumberToWords](@totalamount)
Select @appointfuturedeptname=[Department] FROM [essp].[dbo].[Department] where DepartmentId=@futureappointdept
Select @appointfuturedeptname=dbo.InitCap(@appointfuturedeptname)
Select @appointdeptname=[Department] FROM [essp].[dbo].[Department] where DepartmentId=@appointdept
Select @appointdeptname=dbo.InitCap(@appointdeptname)

Select @appointfuturedesgnationname=[designationname] FROM [essp].[dbo].[Designationmaster] where deleteflag='No' and designationid=@futureappointdesigantion
Select @appointfuturedesgnationname=dbo.InitCap(@appointfuturedesgnationname)
Select @joininghq=operationalhq,@joiningaddress=address from [essp].[dbo].[temppostinglocation] where deleteflag='No' and id=@joininglocid
Select @joininghq=dbo.InitCap(@joininghq)
Select @joiningaddress=dbo.InitCap(@joiningaddress)

Select @appointmentrefno=UPPER(@offerefno)---------------------------------ishita
select @appointmentrefno=dbo.InitCap(@appointmentrefno)----------------ishita
---'xxxx/xxxx/xxx' -------ishita

--Select @joiningdate=convert(varchar, convert(date,@joiningdate,103),106)
--Select @applicationdate=convert(varchar, convert(date,@applicationdate,103),106)

Select @para1='In reference to your Application Dated '+@applicationdate+' and subsequent interviews you had with us and also in reference to our Offer Letter Reference: '+@offerefno+', we are pleased to appoint you as Management Trainee in the department
 '+@appointdeptname+' in our Organization with effect from '+@joiningdate+' to be based at our '+@joininghq+' at '+@joiningaddress+' on the following terms and conditions:'

Select @para2='1.	At the outset, your appointment will be in the Category of Management Trainee for a period of 1 year with effect from '+@joiningdate+'. '

Select @para3='2.	On Successful completion of your tenure as Management Trainee, you may be considered eligible for Appointment as a '+@appointfuturedesgnationname+' in our '+@appointfuturedeptname+' under probation for a period of One year pending final 
confirmation in writing – subject to evaluation and review of your satisfactory performance during the tenure of your service as Management Trainee. On contrary, unsatisfactory performance during the tenure as Management Trainee may lead to termination of
 service without assigning any reason whatsoever.'

Select @para4='3.	Any part of furnished details/documents submitted by you along with your application for employment – if found wrong/incorrect/manipulated at any point of time in course of your employment in our Organisation (MLPPL), shall be liable for
 termination of your employment with immediate effect without assigning any reason to you.'

Select @para5='4. You will be entitled for remuneration as per Annexure A.'

Select @para6='5.	You will join your duty and discharge such duties and responsibilities as may be assigned to you from time to time and you will not directly or indirectly engage or serve in any capacity whatsoever either full or part time or undertake o
r carry on or be concerned in any business, trade, profession or, concern other than work assigned to you by the Company.'

Select @para7='6.	During the period of your employment with us or thereafter you should always keep secret and confidential and prevent the disclosure or divulgence of all information , knowledge , know-how experience, data, documents, reports, statement,
 records, correspondence, discussion, contracts, manufacturing processes, transactions , affairs , dealings , quotations, finance, accounts etc. of the Company that may pass through you or come through your knowledge.'

Select @para8='7.	The terms and conditions of your appointment will be governed by the rules and regulations of the Company as applicable to other employees of the company and in force from time to time.'

Select @para9='8.	The Company will be at liberty to dispense with your services without any notice or compensation and without prejudice to any other right or claims to the Company - if any breach occurs on your part at any point of time in course of your
 employment to the effect of the terms and conditions contained hereinabove. In the matter of breach of terms of employment, the Company’s decision will be final and shall be binding upon you.'

Select @para10='     If the above terms and conditions are acceptable to you please sign the duplicate copy of this letter as a token of your acceptance and return it to us.'

Select @undershine=[undershine] FROM [tundershinemaster] WHERE [companycode] = 'ML' AND lettertype='Appointment Letter' and undershinedid=@undershineid
Select 
UPPER(@appointmentrefno) appointmentrefno,
@appiontmentissudate appiontmentissudate,
@candidatename  candidatename,
@candidateaddress candidateaddress,
@subject subject,
@para1 para1,
@para2 para2,
@para3 para3,
@para4 para4,
@para5 para5,
@para6 para6,
@para7 para7,
@para8 para8,
@para9 para9,
@para10 para10,
--@fixedstipend fixedstipend,
--@traininingallowancnce traininingallowancnce,
--@conveyenceallowance conveyenceallowance,
--@totalamount totalamount,
--@totalamoutinword totalamoutinword,
@undershine undershine

end
GO



