begin                
SELECT @weeklyleave = Count(*)                
  FROM [essp].[dbo].[tleaveweeklyholiday]                
  WHERE [holiday date]=CONVERT(date,@jioningdate,103)                
                  
if(@weeklyleave > 0)                
begin                
   Set @outmsg='Joining Date Can''t Be Weekly Holiday'                
end                
else                
begin                
            
            
            
-------------------------------ishita-------------------------------------            
            
declare @addressval nvarchar(max)            
 select @addressval = [addressline] from trecruitcanaddress where candidateid=@candiadteid             
            
declare @Space char(1) = ' '            
            
-- Upper case first letter and all others in lower case letters            
select @addressval = STUFF(LOWER(@addressval), 1, 1, UPPER(LEFT(@addressval,1)) )            
            
-- search for space character            
declare @i int = CHARINDEX(@Space, @addressval, 1)            
            
while @i > 0            
begin            
 select @i = @i + 1            
 -- replace character after space with its upper case letter            
 select @addressval = STUFF(@addressval, @i, 1, UPPER( SUBSTRING(@addressval, @i, 1)) )            
 -- search for next space character            
 select @i = CHARINDEX(@Space, @addressval, @i)            
end            
----------------------------------------------------------state--------------------------------------            
declare @stateval nvarchar(max)            
 select @stateval = b.[statename] from [trecruitstate]b ,trecruitcanaddress a where a.state=b.stateid and a.candidateid=@candiadteid             
            
declare @Space2 char(1) = ' '            
            
-- Upper case first letter and all others in lower case letters            
select @stateval = STUFF(LOWER(@stateval), 1, 1, UPPER(LEFT(@stateval,1)) )            
            
-- search for space character            
declare @j int = CHARINDEX(@Space2, @stateval, 1)            
            
while @j > 0            
begin            
 select @j = @j + 1            
 -- replace character after space with its upper case letter            
 select @stateval = STUFF(@stateval, @j, 1, UPPER( SUBSTRING(@stateval, @j, 1)) )            
 -- search for next space character            
 select @j = CHARINDEX(@Space2, @stateval, @j)            
end            
            
----------------------------------------------------------postoffice-----------------------------            
            
declare @postofcval nvarchar(max)            
 select @postofcval = postoffice from trecruitcanaddress where candidateid=@candiadteid            
            
declare @Space3 char(1) = ' '            
            
-- Upper case first letter and all others in lower case letters            
select @postofcval = STUFF(LOWER(@postofcval), 1, 1, UPPER(LEFT(@postofcval,1)) )            
            
-- search for space character            
declare @k int = CHARINDEX(@Space3, @postofcval, 1)            
            
while @k > 0            
begin            
 select @k = @k + 1            
 -- replace character after space with its upper case letter            
 select @postofcval = STUFF(@postofcval, @k, 1, UPPER( SUBSTRING(@postofcval, @k, 1)) )            
 -- search for next space character            
 select @k = CHARINDEX(@Space3, @postofcval, @k)            
end            
            
      ----------------------------------------------------------------------------------------------------------            
  Select @canaddress= @addressval+' , '+UPPER(LEFT([villagecity],1))+LOWER(SUBSTRING([villagecity],2,LEN([villagecity])))+' , '+@postofcval             
  FROM [trecruitcanaddress]a,                
  [trecruitstate]b,                
 [trecrutdistrict]c                
  where a.district=c.disid                
  and a.state=b.stateid                
  and [addresstype]='P'                
  and candidateid=@candiadteid                
  --Select @canaddress=dbo.initcap(@canaddress)              
                
  Select  @canpin=UPPER(LEFT(c.[disname],1))+LOWER(SUBSTRING(c.[disname],2,LEN(c.[disname])))+'-'+UPPER(LEFT(a.[pincode],1))+LOWER(SUBSTRING(a.[pincode],2,LEN(a.[pincode])))+' , '+@stateval            
  FROM   [trecruitcanaddress]a,              
    [trecruitstate]b,              
    [trecrutdistrict]c              
  Where   a.district=c.disid              
   and a.state=b.stateid              
   and [addresstype]='P'              
   and candidateid=@candiadteid              
              
              
                
  Select @cananme=UPPER(LEFT(firstname,1))+LOWER(SUBSTRING(firstname,2,LEN(firstname)))+' '+UPPER(LEFT(middlename,1))+LOWER(SUBSTRING(middlename,2,LEN(middlename)))+' '+UPPER(LEFT(lastname,1))+LOWER(SUBSTRING(lastname,2,LEN(lastname))),                
  @salutations=case gender                
    when 'Male' then 'Mr.'                
 when 'Female' then 'Ms.'                
 else 'other'                
   end                 
   FROM [trecruitcanbasicdtls]                
  where candidateid=@candiadteid                
  Select @cananme=dbo.initcap(@cananme)                
  Select @cananme=@salutations+' '+@cananme               
                
  Select  @canfirstname=UPPER(LEFT(firstname,1))+LOWER(SUBSTRING(firstname,2,LEN(firstname)))              
  FROM   [trecruitcanbasicdtls]                
  where   candidateid=@candiadteid                
              
              
  Select @undersign=[undershine] FROM [tundershinemaster] WHERE  lettertype='Appointment Letter' and undershinedid=@undersignid                
  Select @subject='Letter Of Intent'                
 -- Select @joinglocation=[operationalhq] +' at ' + [address] FROM [essp].[dbo].[temppostinglocation] where id=@officenameid                
                
  Select @paraone='This has reference to your application for employment in our Company and the subsequent interview you had with us, we are pleased to offer you an employment in our Company. The Designation and Remuneration Package, as mutually agreed upon, shall be communicated to you on your joining with us.'   
    
  
  Select @paratwo='Please note that this is merely an offer letter. The Company’s standard Appointment Letter, containing exhaustive terms and conditions of employment, will be issued to you on your joining our Company which shall be binding on you.'    
    
      
        
          
            
              
SELECT @parathree = 'You are requested to join us by ' + @jioningdate + '.Your acceptance of this offer should reach us per revert mail within 72 hours of date of issuing this letter.'+char(10)+char(10)+'In the event of you’re not joining us within the aforementioned date or not requesting for an extension to that effect, this offer shall stand withdrawn automatically.'
  
  
     
    
  Select @parafour=+char(10)+'You are required to submit the following at the time of joining'                
  Select @parafive='Please sign the duplicate copy of this Offer letter as a token of your acceptance and return it to us.'                
                
  Select @candiadteid candiadteid,                
  @refno refno,                
  convert(varchar,getdate(),103) offerissueddate,                
  @canaddress canaddress,              
  @canpin canpin,              
  @cananme cananme,               
  @canfirstname canfirstname,              
  @subject subject,                
  @paraone paraone,                
  @paratwo paratwo,                
  @parathree parathree,                
  @parafour parafour,              @parafive parafive,                
  @undersign undersign                
end                
end 
GO



/* Functional group: 09_OFFER_APPOINTMENT_ONBOARDING; referenced grouped tables: Company, trecruitcanaddress, trecruitcanbasicdtls, trecruitstate, trecrutdistrict, tundershinemaster */
/****** Object:  StoredProcedure [dbo].[procselectofferlaettermp]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[procselectofferlaettermp]        
@candiadteid int=null,        
@refno nvarchar(Max)=null,        
@jioningdate varchar(100)=null,        
@officenameid varchar(max)=null,        
@username varchar(max)=null,        
@action varchar(200)=null,        
@undersignid int=null,        
@outmsg varchar(max)=null output        
as        
Declare @offerissueddate varchar(100)        
Declare @canaddress nvarchar(max)        
Declare @subject nvarchar(max)        
Declare @cananme varchar(300)        
Declare @paraone nvarchar(Max)        
Declare @paratwo nvarchar(max)        
Declare @parathree nvarchar(max)        
Declare @parafour nvarchar(max)        
Declare @parafive nvarchar(max)        
Declare @listofdocuments nvarchar(max)        
declare @joinglocation nvarchar(Max)        
declare @weeklyleave int=0        
declare @undersign nvarchar(200)        
declare @salutations varchar(30)        
        
begin        
SELECT @weeklyleave = Count(*)        
  FROM [essp].[dbo].[tleaveweeklyholiday]        
  WHERE [holiday date]=CONVERT(date,@jioningdate,103)        
          
if(@weeklyleave > 0)        
begin        
   Set @outmsg='Joining Date Can''t Be Weekly Holiday'        
end        
else        
begin        
  Select @canaddress=[addressline]+','+[villagecity]+','+[postoffice]+','+c.[disname]+','+b.[statename]+'-'+[pincode]          
  FROM [trecruitcanaddress]a,        
  [trecruitstate]b,        
  [trecrutdistrict]c        
  where a.district=c.disid        
  and a.state=b.stateid        
  and [addresstype]='P'        
  and candidateid=@candiadteid        
          
  Select @canaddress=dbo.initcap(@canaddress)        
        
  Select @cananme=firstname+' '+middlename+' '+lastname,        
   @salutations=case gender        
    when 'Male' then 'Mr.'        
 when 'Female' then 'Ms.'        
 else 'other'        
   end         
   FROM [trecruitcanbasicdtls]        
  where candidateid=@candiadteid        
  Select @cananme=dbo.initcap(@cananme)        
  Select @cananme=@salutations+' '+@cananme        
  Select @undersign=[undershine] FROM [tundershinemaster] WHERE  lettertype='Appointment Letter' and undershinedid=@undersignid        
  Select @subject='Letter Of Intent'        
 -- Select @joinglocation=[operationalhq] +' at ' + [address] FROM [essp].[dbo].[temppostinglocation] where id=@officenameid        
        
  Select @paraone='This has reference to your application for employment in our Company and the subsequent interview you had with us, we are pleased to offer you an employment in our Company. The Designation and Remuneration Package, as mutually agreed upon, shall be communicated to you on your joining with us.' 
  
   Select @paratwo='Please note that this is merely an offer letter. The Company’s standard Appointment Letter, containing exhaustive terms and conditions of employment, will be issued to you on your joining our Company which shall be binding on you.'  
  
    
  SELECT @parathree = 'You are requested to join us by ' + @jioningdate + '.Your acceptance of this offer should reach us per revert mail within 72 hours of date of issuing this letter.'+char(10)+char(10)+'In the event of you’re not joining us within the aforementioned date or not requesting for an extension to that effect, this offer shall stand withdrawn automatically.'
  
   Select @parafour=+char(10)+'You are required to submit the following at the time of joining'         
  Select @parafive='Please sign the duplicate copy of this Offer letter as a token of your acceptance and return it to us.'         
        
  Select @candiadteid candiadteid,        
  @refno refno,        
  convert(varchar,getdate(),103) offerissueddate,        
  @canaddress canaddress,        
  @cananme cananme,        
  @subject subject,        
  @paraone paraone,        
  @paratwo paratwo,        
  @parathree parathree,        
  @parafour parafour,        
  @parafive parafive,        
  @undersign undersign        
        
end        
        
        
        
end 
GO



