	Select @offerrefno=offerrefno from tappointmentletterdtlsofmlexpoperation where candidateid=@candidateid and deleteflag='No'
	Select @offercompanyname='Mendine Lifecare Products Pvt. Ltd.'

 end
 if(@appoitmentlettertype='MPMTFIELD')
