	Select @offerrefno=offerrefno from tappointmentletterdtlsofmpmtfield where candidateid=@candidateid and deleteflag='No'
	 Select @offercompanyname='Mendine Pharmaceuticals Pvt. Ltd.'
 end
 if(@appoitmentlettertype='MPEXPFIELD')
