/* Functional group: 09_OFFER_APPOINTMENT_ONBOARDING; referenced grouped tables: tnotification, tofferlatterdtls, trecruitcanbasicdtls, trecruitcandidatesignup */
/****** Object:  StoredProcedure [dbo].[procviewofferletter]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[procviewofferletter]        
@Action Varchar(Max)=null,        
@candidateid int=null,        
@newjoiningdate varchar(max)=null,        
@username varchar(Max)=null,        
@offerdeletereason varchar(max)=null,        
@message varchar(Max)=null output         
         
as        
begin        
if(@Action='AllSelect')        
begin        
  Select a.candidateid,        
  b.[firstname]+' '+b.[middlename]+' '+b.[lastname] canname,        
  [offerrefno],        
  [offerissueddate], 

       
  [joiningdate],        
  [offerdcompanycode],        
  [isexpired],        
  [offernotificationsent],        
  [acceptancestatus],        
  [LetterFilePath],    
  [LetterFileName],  
  [ContentType],  
  case [acceptancestatus]        
  when 'Accepted' then [acceptancestatus] +' On '+convert(varchar(50),[acceptancestatuschangeon],103)        
  when 'Rejected' then [acceptancestatus] +' On '+convert(varchar(50),[acceptancestatuschangeon],103)        
  else ''        
  end [acceptancestatuswithdate]        
   from[dbo].[tofferlatterdtls]a,[dbo].[trecruitcanbasicdtls]b        
   where a.deleteflag='No'        
   and a.candidateid=b.candidateid        
   order by a.createdon desc        
end        
If(@Action='JoingingExtension')      

  
begin        
declare @isappointgenerated int        
declare @parathree nvarchar(max)        
declare @offerdcompanycode varchar(50)        
Declare @acceptancestatus varchar(50)        
Declare @deletestatus varchar(50)        
Declare @expiredstatus

 varchar(50)        
Select @acceptancestatus=acceptancestatus from tofferlatterdtls where candidateid=@candidateid and deleteflag='No'        
--Select  @isappointgenerated=count(candidateid)from [dbo].[tofferlatterdtls]        
--where deleteflag='No'  

      
--and isappiontmentissued='Yes'        
if(@acceptancestatus='Accept')        
begin        
  Set @message='Cannot Extent As This Offer Is Accepted'        
end        
else        
begin        
 Select @offerdcompanycode=offerdcompanycode from [dbo].[tofferlatterdtls] where candidateid=@candidateid and deleteflag='No'        
 if(@offerdcompanycode='MP')        
 begin        
  Set @parathree='You are requested to join us by '+@newjoiningdate+' in the event of you’re not joining us within the a

forementioned date or not requesting for an extension to that effect, this offer shall stand withdrawn automatically.'        
 end        
 else        
 begin        
     Set @parathree='You are requested to join us by '+@newjoiningdate+' in the event 

of you’re not joining us within the aforementioned date or not requesting for an extension to that effect, this offer shall stand withdrawn automatically.'        
 end        
 Update [dbo].[tofferlatterdtls]        
 set previousjoingdate=joiningdate   

     
 where candidateid=@candidateid        
 and deleteflag='No'        
        
 Update [dbo].[tofferlatterdtls]        
 set joiningdate=@newjoiningdate,        
 offerexpirydate=@newjoiningdate,        
 parathree=@parathree        
 where candidateid=@candidateid        
 and deleteflag='No'        
  Set @message='Joining Date Extension Successfully Done'        
end        
end        
