@offercompanyname='Mendine Erythronate Pvt. Ltd.'   
 set @offercompanynameshortform = 'Team Educyte'
 end 
 Insert into [dbo].[tnotification]        
 (        
    [notificationno]        
      ,[candidateid]        
      ,[notificationcontent]       
 
      ,[deleteflag]        
 
     ,[createdby]        
      ,[createdon]        
 )        
 values        
 (        
 @notificationno,        
 @candidateid,        
 @notificationcontent,        
 'No',        
 @username,        
 getdate()        
        
 )        
 update [dbo].[tofferlatterdtls]        
 set [offernotificationsent]='Yes',        
     [notificationno]=@notificationno        
 where [candidateid]=@candidateid        
 and [deleteflag]='No' and [isexpired]='No'        
        
        
              
       

  
        
 SET @tableHTML = '<table style=" font-size:15px; font-family:Arial">        
        
        <tr>        
        
               <td>Dear '+ @canname +',</td>        
        
        </tr>        
  <tr>        
        
               <td
><b>
Congratulations!</b></td>        
        
