/* Functional group: 10_AUTHENTICATION_AND_SYSTEM_SUPPORT; referenced grouped tables: trecruitcandidatesignup */
/****** Object:  StoredProcedure [dbo].[Procforgotpassword]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:  	<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[Procforgotpassword]
-- Add the parameters for the stored procedure here
@mailid varchar(100),
@password varchar(100),
@cpassword varchar(100)
AS
BEGIN
  -- SET NOCOUNT ON added to prevent extra result sets from
  -- interfering with SELECT statements.
  SET NOCOUNT ON;

  DECLARE @vcount int

  -- Insert statements for procedure here

  IF @MailId NOT LIKE '_%@__%.__%'
  BEGIN
    SELECT
      ' Please give valid mail format'

    RETURN
  END

  SELECT
    @vcount = COUNT(mailid)
  FROM [dbo].[trecruitcandidatesignup]
  WHERE mailid = @mailid

  IF @vcount = 0
  BEGIN
    SELECT
      'Mail_Id Not Exist'

    RETURN
  END

  IF @password <> @cpassword
  BEGIN
    SELECT
      ' Your password and confirmation password do not match.'

    RETURN
  END

  ELSE

    UPDATE [dbo].[trecruitcandidatesignup]
    SET password = @password
    WHERE mailid = @mailid

  SELECT
    ' Your password has changed successfully.'
END
GO



