/* Functional group: 10_AUTHENTICATION_AND_SYSTEM_SUPPORT; referenced grouped tables: trecruitcandidatesignup, trecruitotpverify */
/****** Object:  StoredProcedure [dbo].[procinsertotp]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
    
CREATE PROCEDURE [dbo].[procinsertotp] @mailid   VARCHAR(50),     
                                      @username VARCHAR(50),     
                                      @otp      VARCHAR(10)=NULL,     
                                      @action   VARCHAR(10),     
                                      @status   VARCHAR(50)=NULL output   
            
AS     
  BEGIN     
      IF @action = 'Insert'     
    
        BEGIN     
    
   IF EXISTS(SELECT username,     
                             mailid     
                      FROM   trecruitcandidatesignup     
                      WHERE  username = @username     
                              OR mailid = @mailid)     
              BEGIN     
                  SET @status=1     
    
                  RETURN     
              END     
            ELSE     
              BEGIN     
                  DELETE FROM trecruitotpverify     
                  WHERE  username = @username     
                          OR emailid = @mailid     
    
                  INSERT INTO trecruitotpverify     
                              (username,     
                               emailid,     
                               otp,     
                               otpstatus,   
                               createdtime  
          )     
                  VALUES      ( @username,     
                                @mailid,  
                                @otp,  
                                'N',  
                                Getdate() )     
    
                  SET @status=0     
              END     
        END     
    
      IF @action = 'Verify'     
        BEGIN     
            DECLARE @timediff VARCHAR(20)     
    
            IF EXISTS(SELECT username,     
                             mailid     
                      FROM   trecruitcandidatesignup     
                      WHERE  username = @username     
                              OR mailid = @mailid)     
              BEGIN     
                  SET @status='Username or Mailid already exists'     
    
                  RETURN     
              END     
    
            SELECT @timediff = Datediff(mi, createdtime, Getdate())     
            FROM   trecruitotpverify     
            WHERE  username = @username     
                    OR emailid = @mailid     
    
            IF @timediff > 30     
              BEGIN     
                  SET @status='OTP Expired. Please send the OTP again'     
    
                  RETURN     
              END     
    
            IF EXISTS(SELECT otp     
                      FROM   trecruitotpverify     
                      WHERE  username = @username     
                             AND emailid = @mailid     
                             AND otp = @otp)     
              BEGIN     
                  UPDATE trecruitotpverify     
                  SET    otpstatus = 'Y'     
                  WHERE  username = @username     
                         AND emailid = @mailid     
                         AND otp = @otp  
         
                  SET @status='OTP verified successfully'     
              END     
            ELSE     
              BEGIN     
                  UPDATE trecruitotpverify     
                  SET    otpstatus = 'N'     
                  WHERE  username = @username     
                         AND emailid = @mailid    
         
    
                  SET @status='Please enter the correct OTP'     
              END     
        END     
    
      IF @action = 'Select'     
        BEGIN     
            DECLARE @verifystatus VARCHAR(10)     
    
            IF NOT EXISTS(SELECT username,     
                                 emailid     
                          FROM   trecruitotpverify     
                          WHERE  username = @username     
                                  OR emailid = @mailid)     
              BEGIN     
                  SET @status=1     
    
                  RETURN     
              END     
    
            SELECT @verifystatus = otpstatus     
            FROM   trecruitotpverify    
            WHERE  username = @username     
                    OR emailid = @mailid   
       
    
            IF @verifystatus = 'N'     
              BEGIN     
                  SET @status=2     
              END     
            ELSE     
              BEGIN     
               SET @status=0     
              END     
        END     
  END 
GO



