/* Functional group: 10_AUTHENTICATION_AND_SYSTEM_SUPPORT; referenced grouped tables: trecruitcandidatesignup */
/****** Object:  StoredProcedure [dbo].[SP_GET_USERS_EXISTS]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- =============================================
-- Author:		<Author,,Name>
-- Create date: <Create Date,,>
-- Description:	<Description,,>
-- =============================================
CREATE PROCEDURE [dbo].[SP_GET_USERS_EXISTS] 
	@TenantId UNIQUEIDENTIFIER,
	@ApplicationId UNIQUEIDENTIFIER,
	@Data VARCHAR(50),
	@type VARCHAR(50)
AS
BEGIN
	SET NOCOUNT ON;

	IF(@type = 'UserName')
	BEGIN
		-- Check if username exists
		IF EXISTS (
			SELECT 1 
			FROM trecruitcandidatesignup 
			WHERE UserName = @Data  
		)
		BEGIN
			-- Return suggestion list (hard-coded or generated with variations)
			SELECT TOP 5 
				@Data + CAST(ABS(CHECKSUM(NEWID())) % 1000 AS VARCHAR) AS SuggestedUserName
			FROM sys.objects
		END
		ELSE
		BEGIN
			-- Username is available
			SELECT 'Available' AS Status
		END
	END
	IF(@type = 'Mail')
	BEGIN
		-- Check if username exists
		IF EXISTS (
			SELECT 1 
			FROM trecruitcandidatesignup 
			WHERE MailId = @Data  
		)
		BEGIN
			-- Return suggestion list (hard-coded or generated with variations)
			SELECT 'exists' AS Status
		END
		ELSE
		BEGIN
			-- Username is available
			SELECT 'Available' AS Status
		END
	END
END
GO



