/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: Intern_Candidate_Details, tbl_InternshipDeletedRecords */
/****** Object:  StoredProcedure [dbo].[PRC_Delete_InternTracker]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- PRC_Delete_InternTracker '3464'        
CREATE proc [dbo].[PRC_Delete_InternTracker]        
@TBInternshipDetails Type_Delete_InternshipDtls ReadOnly          
        
as          
begin          
 Declare @Result Varchar(1000)=''                       
 BEGIN TRAN                  
 BEGIN TRY         
Insert Into tbl_InternshipDeletedRecords                  
  ([Candidateid], [CandidateName], [Qualification],[Institution], [Batch], [ContactNo], [JoindAs], [Department], [DateOfJoining], [DateOfCompletion], [DaysCompleted],[ReportingasIntern],Remarks,Empno,Joining ,DesignationName,Empemail,EmpreporttopersonNo,EmpHierarcheName , CurrentStatus,CreatedBy,Createdon)                  
  Select [Candidateid], [CandidateName], [Qualification],[Institution], [Batch], [ContactNo], [JoindAs], [Department], [DateOfJoining],[DateOfCompletion] ,                  
  [DaysCompleted],[ReportingasIntern],Remarks,[Empno],[Joining] ,[DesignationName],[Empemail],[EmpreporttopersonNo],[EmpHierarcheName] , [CurrentStatus],CreatedBy,GETDATE() From @TBInternshipDetails         
        
        
              
        
        
DELETE FROM Intern_Candidate_Details        
WHERE Candidateid IN (SELECT Candidateid FROM @TBInternshipDetails)           
        
COMMIT TRAN                  
 END TRY                  
 Begin CATCH                                             
 ROLLBACK TRAN                                             
  Set @Result=dbo.fnErrors()                                            
 End CATCH                                             
 Select @Result         
 END
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: Intern_Candidate_Details, trecruitappliedpost, trecruitcanbasicdtls, tRecruitEduQualification, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[PRC_Get_DeptWiseCandidate]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- PRC_Get_DeptWiseCandidate '-SELECT-','-SELECT-'           
CREATE proc [dbo].[PRC_Get_DeptWiseCandidate]            
@Dept varchar(100),    
@collegename varchar(max)    
as            
begin            
  Declare @Temp_CanInst_Degree Table                  
  (                  
   Candidateid int,                  
   Gender Varchar(10),                  
   Mobile Varchar(11),                  
   DegreeName  Varchar(Max),                  
   EducationID int,                  
   YearMonthPassing Varchar(25),                  
   Institute Varchar(Max)                   
  )                  
                  
  Declare @Temp_CanDetails Table                  
  (                  
   RegistrationID int,                  
   RegistrationNumber Varchar(100),                  
   Candidateid int,                  
   CandidateName Varchar(Max),                  
   Applicationdate Varchar(11),                  
   DeptName  Varchar(Max),                  
   PostName Varchar(Max) ,                  
   Location Varchar(200)                  
  )                  
                  
  Insert Into @Temp_CanDetails                   
  Select RegistrationID,RegistrationNumber,Candidateid,CandidateName,aplicationdate,DeptName,PostName,Location                   
  From vw_essp_RecruitCanProfile Where postid in(                  
   select postid from trecruitpostlocationmap Where postid IN (Select postid from trecruitappliedpost Where postname like '%INTERN%')                  
  )  OR postname like '%INTERN%'                
                  
                  
  Insert Into @Temp_CanInst_Degree                  
  Select C.candidateid,C.gender,C.mobile,D.degreename,D.Educationid,D.yearmonthpassing,D.institute From                  
  (                  
  Select candidateid,gender,mobile From trecruitcanbasicdtls                   
  ) C                  
  Inner Join                  
  (                  
   Select A.candidateid,A.Educationid,A.degreename,A.yearmonthpassing,A.institute From(                  
   (                  
    Select candidateid,Educationid,degreename,yearmonthpassing,institute From tRecruitEduQualification                   
   ) A                  
   Inner Join                   
   (                  
   Select candidateid,MAX(Educationid) Educationid From tRecruitEduQualification                  
   Group By candidateid                   
   ) B                  
   On A.candidateid = B.candidateid And A.Educationid = B.Educationid                  
  )) D                  
  On C.candidateid = D.candidateid            
            
  Select A.Candidateid,UPPER(B.CandidateName) as  CandidateName        
  --,A.DegreeName Qualification,A.YearMonthPassing Batch,A.Mobile ContactNo,                  
  --'INTERN' JoindAs,B.DeptName Department,null DateOfJoining,null DateOfCompletion,                   
  --Convert(int,0) DaysCompleted                  
  From @Temp_CanInst_Degree    A                  
  INNER Join @Temp_CanDetails    B                  
  On A.Candidateid = B.Candidateid                  
  --AND A.Candidateid NOT IN (                  
  -- Select Candidateid  From Intern_Candidate_Details                  
  --)                
  --AND B.DeptName=@Dept    
  --And A.Institute=@collegename    
  and  B.DeptName= Case When @Dept= '-SELECT-' Then B.DeptName Else @Dept  End               
and  A.Institute= Case When @collegename= '-SELECT-' Then A.Institute Else @collegename  End        
 order by B.CandidateName   asc              
  --select Candidateid,CandidateName from Intern_Candidate_Details where Department=@Dept             
end 
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: Intern_Candidate_Details, tcandidateappointmentmapping, trecruitappliedpost, trecruitcanbasicdtls, tRecruitEduQualification, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[PRC_Get_Intern_Candidate_DepetWise]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 -- PRC_Get_Intern_Candidate_DepetWise '-SELECT-','-SELECT-',2861                              
 CREATE PROC [dbo].[PRC_Get_Intern_Candidate_DepetWise]                              
 @Dept varchar(200),               
 @collegename varchar(max),              
 @CandidateNo bigint,  
 @year varchar(10)      
 AS                                    
 BEGIN                                    
  Declare @Temp_CanInst_Degree Table                                    
  (                                    
   Candidateid int,                                    
   Gender Varchar(10),                                    
   Mobile Varchar(11),                                    
   DegreeName  Varchar(Max),                                    
   EducationID int,                                    
   YearMonthPassing Varchar(25),                                    
   Institute Varchar(Max)                                     
  )                                    
                                    
  Declare @Temp_CanDetails Table                                    
  (                                    
   RegistrationID int,                                    
   RegistrationNumber Varchar(100),                                    
   Candidateid int,                                    
   CandidateName Varchar(Max),                                    
   Applicationdate Varchar(11),                                    
   DeptName  Varchar(Max),                                    
   PostName Varchar(Max) ,                                    
   Location Varchar(200),                
   Empno int,                
   Joining varchar(20),                
   DesignationName nvarchar(max),                
   Empemail nvarchar(max),                
   EmpreporttopersonNo int,                
   EmpHierarcheName varchar(max)                
  )                                    
                                    
  Insert Into @Temp_CanDetails                  
   Select DISTINCT A.RegistrationID,A.RegistrationNumber,A.Candidateid,A.CandidateName,A.aplicationdate,A.DeptName,A.PostName,A.Location , isnull(C.empno,'') as Empno,convert(varchar,C.joining,103) as Joining ,isnull(D.designationname,'') as DesignationName,isnull(C.empemail,'') Empemail , isnull(C.empreporttoperson,'') as  EmpreporttopersonNo , isnull([essp].[dbo].[GetEmpHierarcheName](C.empreporttoperson),'') as EmpHierarcheName                        
  From vw_essp_RecruitCanProfile A                
  LEFT JOIN tcandidateappointmentmapping B ON A.candidateid=B.candidateid                
  LEFT JOIN [essp].[dbo].[Empbasic] C On B.empno=C.empno                
  LEFT JOIN [essp].[dbo].[Designationmaster] D ON C.empdesignation=D.designationid                
  Where A.postid in(                                    
   select postid from trecruitpostlocationmap Where postid IN (Select postid from trecruitappliedpost Where postname like '%INTERN%')                                    
  )  OR postname like '%INTERN%'            
  --Select RegistrationID,RegistrationNumber,Candidateid,CandidateName,aplicationdate,DeptName,PostName,Location                                     
  --From vw_essp_RecruitCanProfile Where postid in(                                    
  -- select postid from trecruitpostlocationmap Where postid IN (Select postid from trecruitappliedpost Where postname like '%INTERN%')                                    
  --)                                    
                                    
                                    
  Insert Into @Temp_CanInst_Degree                                    
  Select C.candidateid,C.gender,C.mobile,D.degreename,D.Educationid,D.yearmonthpassing,D.institute From                                    
  (                                    
  Select candidateid,gender,mobile From trecruitcanbasicdtls                                     
  ) C                                    
  Inner Join                                    
  (                                    
   Select A.candidateid,A.Educationid,A.degreename,A.yearmonthpassing,A.institute From(                                    
   (                      
    Select candidateid,Educationid,degreename,yearmonthpassing,institute From tRecruitEduQualification                                     
   ) A                                    
   Inner Join                                     
   (                                 
   Select candidateid,MAX(Educationid) Educationid From tRecruitEduQualification                         
   Group By candidateid                                     
   ) B                                    
   On A.candidateid = B.candidateid And A.Educationid = B.Educationid                                    
  )) D                                    
  On C.candidateid = D.candidateid                                    
                           
  --Select A.Candidateid,B.CandidateName,A.DegreeName Qualification,A.YearMonthPassing Batch,A.Mobile ContactNo,                                    
  --'INTERN' JoindAs,B.DeptName Department,'' DateOfJoining,'' DateOfCompletion, 0 DaysCompleted                                    
  --From #Temp_CanInst_Degree    A                                    
  --Inner Join #Temp_CanDetails    B                                    
  --On A.Candidateid = B.Candidateid                                    
 --Joining ,DesignationName,Empemail,EmpHierarcheName , CurrentStatus                              
  Select E.Candidateid ,UPPER(E.CandidateName) as CandidateName,UPPER(E.Qualification) as Qualification,UPPER(E.Batch) as Batch,ContactNo,                                    
  E.JoindAs,E.Department,E.DateOfJoining,E.DateOfCompletion,E.DaysCompleted,E.ReportingasIntern,UPPER(E.Remarks) as Remarks ,E.Institution , E.Empno,    
  Case When E.Joining= '&nbsp;' Then '' Else E.Joining  End as Joining,      
   Case When E.DesignationName= '&nbsp;' Then '' Else E.DesignationName  End as DesignationName,      
     Case When E.Empemail= '&nbsp;' Then '' Else E.Empemail  End as Empemail,      
  E.EmpreporttopersonNo,      
      Case When UPPER(E.EmpHierarcheName)= '&nbsp;' Then '' Else UPPER(E.EmpHierarcheName)  End as EmpHierarcheName,      
         Case When UPPER(E.CurrentStatus)= '&nbsp;' Then '' Else UPPER(E.CurrentStatus)  End as CurrentStatus , year(C.Applicationdate) as  Applicationdate               
  From Intern_Candidate_Details E    
  LEFT JOIN @Temp_CanDetails C On E.Candidateid=C.Candidateid               
                
  where  E.Department= Case When @Dept= '-SELECT-' Then E.Department Else @Dept  End                 
   AND  E.Institution= Case When @collegename= '-SELECT-' Then E.Institution Else @collegename  End             
   AND  E.Candidateid= Case When @CandidateNo= '0' Then E.Candidateid Else @CandidateNo  End       
    AND year(C.Applicationdate) = Case When @year= '0' Then  year(C.Applicationdate) Else  @year  End  
  --Department=@Dept                              
  --and Candidateid=@CandidateNo                              
  --and Active=1                          
                                     
  Union                                     
                                    
  Select A.Candidateid,UPPER(B.CandidateName) as CandidateName,UPPER(A.DegreeName) Qualification,UPPER(A.YearMonthPassing) Batch,A.Mobile ContactNo,                                    
  'INTERN' JoindAs,  Case When B.DeptName= '' Then 'OTHER' Else B.DeptName  End as Department,null DateOfJoining,null DateOfCompletion,                                    
  Convert(int,0) DaysCompleted,null ReportingasIntern,null Remarks,Institute , B.Empno,B.Joining,B.DesignationName,B.Empemail,B.EmpreporttopersonNo,B.EmpHierarcheName , null CurrentStatus ,year(B.Applicationdate) as  Applicationdate                                    
  From @Temp_CanInst_Degree    A                                    
  Inner Join @Temp_CanDetails    B                                    
  On A.Candidateid = B.Candidateid                                    
  AND A.Candidateid NOT IN (             
   Select Candidateid  From Intern_Candidate_Details                                    
  )                
   AND   B.DeptName= Case When @Dept= '-SELECT-' Then B.DeptName Else @Dept  End                 
   AND  A.Institute= Case When @collegename= '-SELECT-' Then A.Institute Else @collegename  End            
   AND  B.Candidateid= Case When @CandidateNo= '0' Then B.Candidateid Else @CandidateNo  End     
  AND year(B.Applicationdate) = Case When @year= '0' Then  year(B.Applicationdate) Else  @year  End    
  --AND B.DeptName=@Dept                              
 -- AND B.Candidateid=@CandidateNo                            
         
                             
                              
                              
 END 
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: Intern_Candidate_Details, trecruitappliedpost, trecruitcanbasicdtls, tRecruitEduQualification, trecruitpostlocationmap */
/****** Object:  StoredProcedure [dbo].[PRC_Get_Intern_Candidate_Rec]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
                            
                            
 --Create Table #Temp_CanInst_Degree                            
 --(                            
 -- Candidateid int,                            
 -- Gender Varchar(10),                            
 -- Mobile Varchar(11),                            
 -- DegreeName  Varchar(Max),                            
 -- EducationID int,                            
 -- YearMonthPassing Varchar(25),                            
 -- Institute Varchar(Max)                             
 --)                            
                            
 --Create Table #Temp_CanDetails                            
 --(                            
 -- RegistrationID int,                            
 -- RegistrationNumber Varchar(100),                            
 -- Candidateid int,                            
 -- CandidateName Varchar(Max),                            
 -- Applicationdate Varchar(11),                            
 -- DeptName  Varchar(Max),                            
 -- PostName Varchar(Max) ,                            
 -- Location Varchar(200)                            
 --)                            
                            
 -- PRC_Get_Intern_Candidate_Rec                            
                            
 CREATE PROC [dbo].[PRC_Get_Intern_Candidate_Rec]                            
 AS                            
 BEGIN                            
  --Declare @Temp_CanInst_Degree Table                            
  --(                            
  -- Candidateid int,                            
  -- Gender Varchar(10),                            
  -- Mobile Varchar(11),                            
  -- DegreeName  Varchar(Max),                            
  -- EducationID int,                            
  -- YearMonthPassing Varchar(25),                            
  -- Institute Varchar(Max)                             
  --)                            
                            
  --Declare @Temp_CanDetails Table                            
  --(                            
  -- RegistrationID int,                            
  -- RegistrationNumber Varchar(100),                            
  -- Candidateid int,                            
  -- CandidateName Varchar(Max),                            
  -- Applicationdate Varchar(11),                            
  -- DeptName  Varchar(Max),                            
  -- PostName Varchar(Max) ,                            
  -- Location Varchar(200)                            
  --)                            
                            
  --Insert Into @Temp_CanDetails                             
  --Select RegistrationID,RegistrationNumber,Candidateid,CandidateName,aplicationdate,DeptName,PostName,Location                             
  --From vw_essp_RecruitCanProfile Where postid in(                            
  -- select postid from trecruitpostlocationmap Where postid IN (Select postid from trecruitappliedpost Where postname like '%INTERN%')                            
  --)                            
                            
                            
  --Insert Into @Temp_CanInst_Degree                            
  --Select C.candidateid,C.gender,C.mobile,D.degreename,D.Educationid,D.yearmonthpassing,D.institute From                            
  --(                            
  --Select candidateid,gender,mobile From trecruitcanbasicdtls                             
  --) C                            
  --Inner Join                            
  --(                            
  -- Select A.candidateid,A.Educationid,A.degreename,A.yearmonthpassing,A.institute From(                            
  -- (                            
  --  Select candidateid,Educationid,degreename,yearmonthpassing,institute From tRecruitEduQualification                             
  -- ) A                            
  -- Inner Join                             
  -- (                            
  -- Select candidateid,MAX(Educationid) Educationid From tRecruitEduQualification                      
  -- Group By candidateid                             
  -- ) B                            
  -- On A.candidateid = B.candidateid And A.Educationid = B.Educationid                            
  --)) D                            
  --On C.candidateid = D.candidateid                            
                      
                  
                            
  Select Candidateid ,UPPER(Institution)AS Institution,UPPER(CandidateName) as CandidateName,UPPER(Qualification) as Qualification,UPPER(Batch) as Batch,ContactNo,                            
  JoindAs,UPPER (Department) AS Department,DateOfJoining,DateOfCompletion,DaysCompleted,UPPER(ReportingasIntern) as ReportingasIntern,UPPER(Remarks)  as Remarks,      
  Empno,    
   Case When Joining= '&nbsp;' Then '' Else Joining  End as Joining,      
   Case When DesignationName= '&nbsp;' Then '' Else DesignationName  End as DesignationName,      
     Case When Empemail= '&nbsp;' Then '' Else Empemail  End as Empemail,      
  EmpreporttopersonNo,      
      Case When UPPER(EmpHierarcheName)= '&nbsp;' Then '' Else UPPER(EmpHierarcheName)  End as EmpHierarcheName,      
         Case When UPPER(CurrentStatus)= '&nbsp;' Then '' Else UPPER(CurrentStatus)  End as CurrentStatus      
      
  From Intern_Candidate_Details                
  where Active=1 
  ORDER BY
  CASE 
        WHEN Batch = 'PURSUING' THEN 99999999  -- Assign a high value so it appears first
        ELSE CAST(RIGHT(Batch, 4) AS INT) * 100 + 
             CASE LEFT(Batch, 3)
                WHEN 'JAN' THEN 1
                WHEN 'FEB' THEN 2
                WHEN 'MAR' THEN 3
                WHEN 'APR' THEN 4
                WHEN 'MAY' THEN 5
                WHEN 'JUN' THEN 6
                WHEN 'JUL' THEN 7
                WHEN 'AUG' THEN 8
                WHEN 'SEP' THEN 9
                WHEN 'OCT' THEN 10
                WHEN 'NOV' THEN 11
                WHEN 'DEC' THEN 12
                ELSE 0
             END
    END DESC,CandidateName,Institution asc
                    
-- Joining,DesignationName,Empemail,EmpreporttopersonNo,UPPER(EmpHierarcheName) as EmpHierarcheName, UPPER(CurrentStatus)as CurrentStatus                           
      
                      
                      
 END 
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: Intern_Candidate_Details */
/****** Object:  StoredProcedure [dbo].[PRC_InternShip_Details_Add]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[PRC_InternShip_Details_Add]  
@TBInternshipDetails Type_InternshipDetails_Save ReadOnly    
AS  
BEGIN  
 Declare @Result Varchar(1000)=''       
 BEGIN TRAN  
 BEGIN TRY  
  Truncate Table Intern_Candidate_Details  
  Insert Into Intern_Candidate_Details  
  ([Candidateid], [CandidateName], [Qualification], [Batch], [ContactNo], [JoindAs], [Department], [DateOfJoining], [DateOfCompletion], [DaysCompleted])  
  Select [Candidateid], [CandidateName], [Qualification], [Batch], [ContactNo], [JoindAs], [Department], [DateOfJoining],[DateOfCompletion] ,  
  [DaysCompleted] From @TBInternshipDetails  
 COMMIT TRAN  
 END TRY  
 Begin CATCH                             
 ROLLBACK TRAN                             
  Set @Result=dbo.fnErrors()                            
 End CATCH                             
 Select @Result   
END
GO



