CREATE PROCEDURE [dbo].[Proc_EDUCYE_GetBoardName]

AS    
BEGIN    
    
Select 0 as BoardID, '-SELECT-' as BoardName    
UNION ALL    
select bdid as BoardID, UPPER(bdname) as BoardName from trecruitboards    
where bdid NOT IN (195)  

    
END
