/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_Educyte_TraineeImage */
/****** Object:  StoredProcedure [dbo].[Proc_EDUCYTE_AddImage]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[Proc_EDUCYTE_AddImage]    
@TraineeID nvarchar(max),              
@UserEmail nvarchar(max),    
@ImageFileName nvarchar(max),              
@ImageContentType nvarchar(max),              
@ImageData varbinary(max)=null,                 
@ImagePath nvarchar(max),    
@CreatedBy nvarchar(max),    
@ReportImagePath nvarchar(max),    
@Status NVARCHAR(MAX)=null OUTPUT     
    
AS              
DECLARE @errorcode nvarchar(max)              
BEGIN              
begin Try    
    
    
If not Exists ( Select * from tbl_Educyte_TraineeImage Where UserEmail = @UserEmail)      
Begin       
INSERT INTO tbl_Educyte_TraineeImage (              
TraineeID,              
UserEmail,              
ImageFileName,              
ImageContentType,              
ImageData,              
ImagePath,              
CreatedBy,              
CreatedTime ,  
ReportImagePath  
)              
VALUES (              
@TraineeID,              
@UserEmail,              
@ImageFileName,              
@ImageContentType,              
@ImageData,              
@ImagePath,              
@CreatedBy,              
GETDATE() ,   
@ReportImagePath  
)      
SET @Status = 'Image Inserted Successfully'         
END    
ELSE    
BEGIN    
    
UPDATE tbl_Educyte_TraineeImage        
SET        
    UserEmail = @UserEmail,        
    ImageFileName = @ImageFileName,        
    ImageContentType = @ImageContentType,        
 ImageData = @ImageData,              
    ImagePath = @ImagePath,  
 ReportImagePath = @ReportImagePath  
WHERE UserEmail = @UserEmail     
    
SET @Status = 'Image  Updated Successfully'         
END    
    
end try                          
begin catch                                  
 Select @errorcode=ERROR_NUMBER();                                  
 Set @Status='CREATION FAILD!!.ERROR CODE:'+@errorcode                                  
end catch                   
END 
GO



