/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_Trainee_SignupDtls */
/****** Object:  StoredProcedure [dbo].[Proc_EDUCYTE_AddSignUpDtls]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Proc_EDUCYTE_AddSignUpDtls]  
@UserFullName NVARCHAR(MAX),  
@UserEmail NVARCHAR(MAX),  
@UserPassword NVARCHAR(64),  
@Status NVARCHAR(MAX)=null OUTPUT  
  
AS  
DECLARE @errorcode Nvarchar(max)  
DECLARE @TraineeID Nvarchar(max) 
BEGIN  
begin Try  

SET @TraineeID = UPPER(@UserFullName) +'_' + RIGHT('000' + CAST(ABS(CHECKSUM(NEWID())) % 10000 AS NVARCHAR(4)), 4)



IF Exists (select * from tbl_EDUCYTE_Trainee_SignupDtls Where UserEmail = @UserEmail)  
BEGIN  
  
SET @Status = 'User Alredy Exists'  
END   
ELSE  
BEGIN  
INSERT INTO tbl_EDUCYTE_Trainee_SignupDtls ( 
TraineeID,
UserFullName,  
UserEmail,  
UserPassword,  
UserComapnyName,  
UserPostName,  
CreatedOn  
)  
VALUES (  
@TraineeID,
upper(@UserFullName),  
@UserEmail,  
@UserPassword,  
'MENDINE ERYTHRONET PVT.LTD.',  
'EDUCYTE TRAINEE',  
GETDATE()  
)  
  
SET @Status = 'User Registerd Successfully'  
END  
end try                  
begin catch                  
 Select @errorcode=ERROR_NUMBER();                  
 Set @Status='SIGN UP FAILD!!.ERROR CODE:'+@errorcode                  
end catch   
END
GO



