/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_Trainee_SignupDtls, tbl_EDUCYTE_UploadDocuments */
/****** Object:  StoredProcedure [dbo].[Proc_Educyte_admin_doc_upload]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[Proc_Educyte_admin_doc_upload]  
   @traineeid       NVARCHAR(max),      
                                       @uploadfilename NVARCHAR(max)=null,      
                                       @uploadfiletype NVARCHAR(max)=null,      
                                       @uploadfile     VARBINARY(max)=null,      
                                       @docid          INT=null,  
            @uploadedby varchar(max)=null  
AS      
    DECLARE @username NVARCHAR(max)      
      
  BEGIN  
  
        SELECT @username =  [UserEmail]    
      FROM   [dbo].[tbl_EDUCYTE_Trainee_SignupDtls]      
      WHERE  [TraineeID]  = @traineeid    
  
    IF EXISTS (SELECT 1      
                 FROM   [dbo].[tbl_EDUCYTE_UploadDocuments]      
                 WHERE  TraineeID = @traineeid      
                        AND docid = @docid )      
        BEGIN      
            DELETE FROM [dbo].[tbl_EDUCYTE_UploadDocuments]      
            WHERE  TraineeID = @traineeid      
                   AND docid = @docid      
                   --AND deleteflag = 'Yes'      
      
            INSERT INTO [dbo].[tbl_EDUCYTE_UploadDocuments]      
                        ([TraineeID],     
                         [UserEmail],    
                         [docid],      
                         [uploadedfilename],      
                         [uploadedfiletype],      
                         [uploadedfile],      
                         [deleteflag],      
                         [uploadedby],      
                         [uploadedon],      
                         [varifactionstatus])      
            VALUES      ( @traineeid,     
                          @username,    
                          @docid,      
                          @uploadfilename,      
                          @uploadfiletype,      
                          @uploadfile,      
                          'No',      
                          @uploadedby,      
                          Getdate(),      
                         'Approved' )      
        END      
      ELSE      
        BEGIN      
            INSERT INTO [dbo].[tbl_EDUCYTE_UploadDocuments]      
                        ([TraineeID],      
                        [UserEmail],    
                         [docid],      
                         [uploadedfilename],      
                         [uploadedfiletype],      
                         [uploadedfile],      
                         [deleteflag],      
                         [uploadedby],      
                         [uploadedon],      
                         [varifactionstatus])      
            VALUES      ( @traineeid,     
                          @username,    
                          @docid,      
                          @uploadfilename,      
                          @uploadfiletype,      
                          @uploadfile,      
                          'No',      
                          @uploadedby,      
                          Getdate(),      
        'Approved' )      
        END      
END 
GO



