SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Proc_EDUCYTE_AllDistrict]  
   
AS    
BEGIN     
    
Select 0 as disid , '-SELECT-' as districtname     
UNION ALL    
Select disid,UPPER(disname) as districtname from trecrutdistrict    
where disid NOT IN (719)  and CountryId=101  
  
