/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_ConflictEducyteTraineedtls, tbl_EDUCYTE_Language, tbl_Educyte_PersonalDetails, trecruitconflictansdtls, trecruitconflictquestype, trecruitconflictqusdtls */
/****** Object:  StoredProcedure [dbo].[proc_EDUCYTE_conaccmmodatescore]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[proc_EDUCYTE_conaccmmodatescore]  
@candidateattemexam INT=NULL,   
 @traineeid NVARCHAR(MAX)=NULL    
as  

begin  
   
SELECT   
                           a.questionid,   
                           a.answer  
                    FROM   [dbo].[tbl_EDUCYTE_ConflictEducyteTraineedtls] a,   
                           [dbo].[trecruitconflictqusdtls] b,   
                           [dbo].[trecruitconflictquestype] c,   
                           [dbo].[trecruitconflictansdtls]f,   
                           [dbo].[tbl_Educyte_PersonalDetails] d,   
                           [dbo].[tbl_EDUCYTE_Language]e   
                    WHERE  a.[IDLang] = b.[languageid]  
                           AND a.[questionid] = b.[quesserialno]   
                           AND b.[conquestypeid] = c.[id]   
                          AND a.[TraineeID] = d.[TraineeID]   
                           AND a.[IDLang] = e.[id]   
                           AND a.answer = f.[number]  
         and a.[IDLang]=f.[languageid]                              
                           AND [Traineeattemexam] = @candidateattemexam  
                           AND c.[id] = 3  
         and a.TraineeID=@traineeid   
end  
  
  
  
  
GO



