/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_ConflictEducyteTraineedtls, tbl_EDUCYTE_Conflictexamdtls, tbl_EDUCYTE_Language, tbl_Educyte_PersonalDetails, trecruitconflictansdtls, trecruitconflictquestype, trecruitconflictqusdtls, trecruittraker, trecuitpsycycotesttype */
/****** Object:  StoredProcedure [dbo].[proc_EDUCYTE_conflicthrdtls]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
/****** Script for SelectTopNRows command from SSMS  ******/   
CREATE PROC [dbo].[proc_EDUCYTE_conflicthrdtls] @action             VARCHAR(100)=NULL,   
                                 @phytypeid          INT=NULL,   
                                 @postname           VARCHAR(500)=NULL,   
                                 @deptname           VARCHAR(500)=NULL,   
                                 @Traineeattemexam INT=NULL,   
                                 @traineeid NVARCHAR(max)=NULL,   
                                 @Driscolallow       VARCHAR(200)=NULL,   
                                 @Message            VARCHAR(200)=NULL   
AS   
DECLARE   @useremail NVARCHAR(max)   
    DECLARE @canDriscolallow VARCHAR(200)   
 DECLARE @canconflictallow VARCHAR(200)   
  
  BEGIN   
      SELECT @useremail = UserEmail   
      FROM   [dbo].[tbl_Educyte_PersonalDetails]   
      WHERE  TraineeID = @traineeid   
  
      --IF @action = 'Selecttypewisecandidate'   
      --  BEGIN   
        
  
      --      SELECT [referenceno],   
      --             [candidatename],   
      --             [typename]   
      --      FROM   (SELECT [referenceno],   
      --                     [candidatename],   
      --                     CASE   
      --                       WHEN Driscolallow = 'Completed' THEN 1   
      --                       WHEN Driscolallow = 'Reschedule' THEN 1   
      --                       ELSE Driscolallow   
      --                     END Driscolallow,   
      --                     CASE   
      --                       WHEN conflictallow = 'Completed' THEN 2   
      --                       WHEN conflictallow = 'Reschedule' THEN 2   
      --                       ELSE conflictallow   
      --                     END conflictallow,   
      --                     CASE   
      --                       WHEN iqallow = 'Completed' THEN 3   
      --                       WHEN iqallow = 'Reschedule' THEN 3   
      --                       ELSE iqallow   
      --                     END iqallow,   
      --                     CASE   
      --                       WHEN eqallow = 'Completed' THEN 4   
      --                       WHEN eqallow = 'Reschedule' THEN 4   
      --                       ELSE eqallow   
      --                     END eqallow   
      --              FROM   [dbo].[trecruittraker]   
      --              WHERE  postname = @postname   
      --                     AND departmentdivision = @deptname   
      --                     AND Driscolallow IN ( 'Completed', 'Reschedule' )   
      --                      OR conflictallow IN ( 'Completed', 'Reschedule' )   
      --                      OR iqallow IN ( 'Completed', 'Reschedule' )   
      --                      OR eqallow IN ( 'Completed', 'Reschedule' )) a,   
      --             [dbo].[trecuitpsycycotesttype] b   
      --      WHERE  a.Driscolallow = Cast(b.[id] AS VARCHAR)   
      --             AND b.id = @phytypeid   
      --  END   
  
      --IF @action = 'Selecttypewiseotcandidate'   
      --  BEGIN   
      --      SELECT [referenceno],   
      --             [candidatename],   
      --             [typename]   
      --      FROM   (SELECT [referenceno],   
      --                     [candidatename],   
      --                     CASE   
      --                       WHEN Driscolallow = 'Completed' THEN 1   
      --                       WHEN Driscolallow = 'Reschedule' THEN 1   
      --                       ELSE Driscolallow   
      --                     END Driscolallow,   
      --                     CASE   
      --                       WHEN conflictallow = 'Completed' THEN 2   
      --                       WHEN conflictallow = 'Reschedule' THEN 2   
      --                       ELSE conflictallow   
      --                     END conflictallow,   
      --                     CASE   
      --                       WHEN iqallow = 'Completed' THEN 3   
      --                       WHEN iqallow = 'Reschedule' THEN 3   
      --               ELSE iqallow   
      --                     END iqallow,   
      --                     CASE   
      --                       WHEN eqallow = 'Completed' THEN 4   
      --                       WHEN eqallow = 'Reschedule' THEN 4   
      --                       ELSE eqallow   
      --                     END eqallow   
      --              FROM   [dbo].[trecruittraker]   
      --              WHERE  departmentdivision = ''   
      --                     AND Driscolallow IN ( 'Completed', 'Reschedule' )   
      --                      OR conflictallow IN ( 'Completed', 'Reschedule' )   
      --                      OR iqallow IN ( 'Completed', 'Reschedule' )   
      --                      OR eqallow IN ( 'Completed', 'Reschedule' )) a,   
      --             [dbo].[trecuitpsycycotesttype] b   
      --      WHERE  Driscolallow = Cast([id] AS VARCHAR)   
      --             AND id = @phytypeid   
      --  END   
  
      IF @action = 'Selectquesans'   
        BEGIN   
            SELECT [conquestype],   
                   [quesserialno],   
                   [question],   
                   f.[answer]   
            FROM   [dbo].[tbl_EDUCYTE_ConflictEducyteTraineedtls] a,   
                   [dbo].[trecruitconflictqusdtls] b,   
                   [dbo].[trecruitconflictquestype] c,   
                   [dbo].[trecruitconflictansdtls]f,   
                   [dbo].[tbl_Educyte_PersonalDetails] d,   
                   [dbo].[tbl_EDUCYTE_Language]e   
            WHERE  a.[IDLang] = b.[languageid]   
                   AND a.[questionid] = b.[quesserialno]   
                   AND b.[conquestypeid] = c.[id]   
                   AND a.[TraineeID] = d.[TraineeID]   
                   AND a.[IDLang] = e.[id]   
                   AND a.answer = f.number   
                   AND a.[IDLang] = f.[languageid]   
                   AND a.TraineeID = @traineeid   
                   AND [Traineeattemexam] = @Traineeattemexam   
            ORDER  BY [quesserialno]   
        END   
  
      IF @action = 'Reschedule'   
        BEGIN   
            SELECT @canconflictallow = [conflictallow]   
            FROM   [dbo].[tbl_Educyte_PersonalDetails]  
            WHERE  [TraineeID] = @traineeid   
            GROUP  BY [Driscolallow],   
                      [conflictallow],   
                      [iqallow],   
                      [eqallow]    
  
            IF @canconflictallow = 'Completed'   
              BEGIN   
                  UPDATE [dbo].[tbl_Educyte_PersonalDetails]   
                  SET    [conflictallow] = 'Reschedule'   
                  WHERE  [TraineeID] = @traineeid   
              END   
            ELSE   
              BEGIN   
                  SET @message=1   
              END   
        END   
  
      IF @action = 'SELECTEXAMNO'   
        BEGIN   
            SELECT [attemexam],   
                   CASE   
                     WHEN [attemexam] = 1 THEN Cast('1st Exam' AS VARCHAR)   
                     WHEN [attemexam] = 2 THEN Cast('2nd Exam'AS VARCHAR)   
                     WHEN [attemexam] = 3 THEN Cast('3rd Exam'AS VARCHAR)   
                     ELSE Cast([attemexam]AS VARCHAR) + '' + 'th Exam'   
                   END [attemexamtext]   
            FROM   [dbo].[tbl_EDUCYTE_Conflictexamdtls]   
            WHERE  TraineeID = @traineeid   
                   AND finalsubmit = 'Yes'   
            ORDER  BY [attemexam]   
        END   
  
      IF @action = 'Selecttypewisetotalno'   
        BEGIN   
            SELECT c.[conquestype],   
                   a.questionid,   
                   a.answer,   
                   totscore   
            FROM   [dbo].[tbl_EDUCYTE_ConflictEducyteTraineedtls] a,   
                   [dbo].[trecruitconflictqusdtls] b,   
                   [dbo].[trecruitconflictquestype] c,   
                   [dbo].[trecruitconflictansdtls]f,   
                   [dbo].[tbl_Educyte_PersonalDetails] d,   
                   [dbo].[tbl_EDUCYTE_Language]e,   
                   (SELECT c.[conquestype],   
                           Sum (a.answer)totscore   
 FROM   [dbo].[tbl_EDUCYTE_ConflictEducyteTraineedtls] a,   
                           [dbo].[trecruitconflictqusdtls] b,   
                           [dbo].[trecruitconflictquestype] c,   
                           [dbo].[trecruitconflictansdtls]f,   
                           [dbo].[tbl_Educyte_PersonalDetails] d,   
                           [dbo].[tbl_EDUCYTE_Language]e   
                    WHERE  a.[IDLang] = b.[languageid]   
                           AND a.[questionid] = b.[quesserialno]   
                           AND b.[conquestypeid] = c.[id]   
                           AND a.[TraineeID] = d.[TraineeID]   
                           AND a.[IDlang] = e.[id]   
                           AND a.answer = f.number   
                           AND a.[IDlang] = f.[languageid]   
                           AND a.TraineeID = @traineeid   
                           AND [Traineeattemexam] = @Traineeattemexam   
                    GROUP  BY c.[conquestype]) z   
            WHERE  a.[IDLang] = b.[languageid]   
                   AND a.[questionid] = b.[quesserialno]   
                   AND b.[conquestypeid] = c.[id]   
                   AND a.[TraineeID] = d.[TraineeID]   
                   AND a.[IDLang] = e.[id]   
                   AND a.answer = f.id   
                   AND a.TraineeID = @traineeid   
                   AND [Traineeattemexam] = @Traineeattemexam   
                   AND c.[conquestype] = z.[conquestype]   
            ORDER  BY [conquestype]   
        END        
  
      IF @action = 'Activeinactiveresbutton'   
        BEGIN   
            SELECT   
                   a.[conflictallow]   
             FROM   [dbo].[tbl_Educyte_PersonalDetails] a                   
            WHERE    
                    a.TraineeID = @traineeid   
        END   
  END 
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: Languages, tbl_EDUCYTE_Conflictcanlanguagemap, tbl_EDUCYTE_ConflictEducyteTraineedtls, tbl_EDUCYTE_Conflictexamdtls, tbl_Educyte_PersonalDetails, tbl_EDUCYTE_Trainee_SignupDtls, trecruitconflictansdtls, trecruitconflictquestype, trecruitconflictqusdtls, trecruittraker */
/****** Object:  StoredProcedure [dbo].[proc_EDUCYTE_Conflictmasdtls]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
    
CREATE PROC [dbo].[proc_EDUCYTE_Conflictmasdtls] @action           NVARCHAR(100)=NULL,     
                                      @conquestype      NVARCHAR(100)=NULL,     
                                      @username         NVARCHAR(100)=NULL,     
                                      @activeflag       NVARCHAR(10)=NULL,     
                                      @conquestypeid    INT=NULL,     
                                      @languageid       INT=NULL,     
                                      @question         NVARCHAR(max)=NULL,     
                                      @questiondtlsid   INT=NULL,     
                                      @answer           NVARCHAR(max)=NULL,     
                                      @number           INT=NULL,     
                                      @answerdtlsid     INT=NULL,     
                                      @quesserialnonext INT=NULL,     
                                      @ollanguageid     INT=NULL,     
                                      @olquesserialno   INT=NULL,     
                                      @message          VARCHAR(500)=NULL output     
AS     
    DECLARE @empcode VARCHAR(100)     
    DECLARE @traineeId Nvarchar(max)     
    DECLARE @anslanguageid INT     
    DECLARE @queslanguageid INT     
    DECLARE @countexamques INT     
    DECLARE @countexamattm INT     
    DECLARE @countexamattques INT     
    DECLARE @quesserialno INT     
    DECLARE @maplanid INT     
    DECLARE @countexamattmcan INT     
    DECLARE @findques INT     
    DECLARE @idd INT     
    DECLARE @attemptno INT     
    DECLARE @cattemptno INT     
    DECLARE @atteptestno INT     
    
 BEGIN     
  Begin Tran   
Begin Try   
      --SELECT @empcode = empcode     
      --FROM   essp.dbo.emp     
      --WHERE  empemail = @username     
    
      SELECT @traineeId = TraineeID     
      FROM   [dbo].[tbl_EDUCYTE_Trainee_SignupDtls]     
      WHERE  UserEmail = @username     
    
      SELECT @maplanid = IDLang     
      FROM   [dbo].[tbl_EDUCYTE_Conflictcanlanguagemap] p     
      WHERE  @traineeId = TraineeID     
    
      SELECT @countexamques = Count([question])     
      FROM   [dbo].[trecruitconflictqusdtls]     
      WHERE  [languageid] = @maplanid     
    
      SELECT @quesserialno = Min(quesserialno)     
      FROM   [dbo].[trecruitconflictqusdtls] p     
      WHERE  languageid = @maplanid     
             AND activeflag = 'yes'     
    
      SELECT @findques = Count(questionid)     
      FROM   [dbo].[tbl_EDUCYTE_ConflictEducyteTraineedtls]     
      WHERE  @traineeId = TraineeID     
             AND QuestionId = @questiondtlsid     
             AND [Quesfinalsubmitques] IS NULL     
    
      IF @action = 'Conquestypeinsert'     
        IF EXISTS(SELECT [conquestype]     
                  FROM   [dbo].[trecruitconflictquestype]     
                  WHERE  [conquestype] = @conquestype)     
          BEGIN     
              SET @message='Question Type Already Exists'     
    
              RETURN;     
          END     
        ELSE     
          BEGIN     
              INSERT INTO [dbo].[trecruitconflictquestype]     
                          ([conquestype],     
                           [activeflag],     
                           [createdby],     
                           [createdon],     
                           [updateddby],     
                           [updateddon])     
              VALUES      ( @conquestype,     
                            'Yes',     
                            @empcode,     
                            Getdate(),     
                            @empcode,     
                            Getdate() )     
    
              SET @message='Question Type Successfully Inserted'     
          END     
    
      IF @action = 'Conquestypeupdate'     
        IF EXISTS(SELECT [conquestype]     
                  FROM   [dbo].[trecruitconflictquestype]     
                  WHERE  [conquestype] = @conquestype)     
          BEGIN     
              SET @message='Question Type Already Exists'    
    
              RETURN;     
          END     
        ELSE     
          BEGIN     
              UPDATE [dbo].[trecruitconflictquestype]     
              SET    [conquestype] = @conquestype,     
                     [activeflag] = @activeflag,     
                     [updateddby] = @empcode,     
                     [updateddon] = Getdate()     
              WHERE  id = @conquestypeid     
    
              SET @message='Question Type Successfully Updated'     
          END     
    
      IF @action = 'Conquestypeselect'     
        BEGIN     
            SELECT [id],     
                   [conquestype],     
                   [activeflag]     
            FROM   [dbo].[trecruitconflictquestype]     
        END     
    
      IF @action = 'Conquesinsert'     
        IF EXISTS(SELECT [question]     
                  FROM   [dbo].[trecruitconflictqusdtls]     
                  WHERE  [question] = @question)     
          BEGIN     
              SET @message='Question Details Already Exists'     
    
              RETURN;     
          END     
        ELSE     
          BEGIN     
              SELECT @queslanguageid = Count(languageid)     
              FROM   [dbo].[trecruitconflictqusdtls]     
              WHERE  languageid = @languageid     
    
              INSERT INTO [dbo].[trecruitconflictqusdtls]     
                          (languageid,     
                           [quesserialno],     
                           [question],     
                           [conquestypeid],     
                           [activeflag],     
                           [createdby],     
                           [createdon],     
                           [updateddby],     
                           [updateddon])     
              VALUES      ( @languageid,     
                            @queslanguageid + 1,     
                            @question,     
                            @conquestypeid,     
                            'Yes',     
                            @empcode,     
                            Getdate(),     
                            @empcode,     
                            Getdate() )     
    
              SET @message='Question Details Successfully Inserted'     
          END     
    
      IF @action = 'Conquesupdate'     
        IF EXISTS(SELECT [question]     
                  FROM   [dbo].[trecruitconflictqusdtls]     
                  WHERE  [question] = @question)     
          BEGIN     
              SET @message='Question Details Already Exists'     
    
              RETURN;     
          END     
        ELSE     
          BEGIN     
              UPDATE [dbo].[trecruitconflictqusdtls]     
              SET    languageid = @languageid,     
                     [question] = @question,     
                     [conquestypeid] = @conquestypeid,     
                     [activeflag] = @activeflag,     
                     [updateddby] = @empcode,     
                     [updateddon] = Getdate()     
              WHERE  [id] = @questiondtlsid     
    
              SET @message='Question Details Successfully updated'     
          END     
    
      IF @action = 'Conquesselect'     
        BEGIN     
            SELECT ques.[id],     
                   ques.[languageid],     
                   ques.[quesserialno],     
                   lan.language,     
                   ques.[question],     
                   ques.[conquestypeid],     
                   qty.[conquestype],     
                   ques.[activeflag],     
                   ques.[createdby],     
                   ques.[createdon],     
                   ques.[updateddby],     
                   ques.[updateddon]     
            FROM   [dbo].[trecruitconflictqusdtls] ques,     
                   [dbo].[languages] lan,     
                   [dbo].[trecruitconflictquestype] qty     
            WHERE  ques.[languageid] = lan.[id]     
                   AND lan.[id] = @languageid     
                   AND ques.[conquestypeid] = qty.id     
            ORDER  BY ques.[quesserialno]     
        END     
    
      IF @action = 'Conquesansinsert'     
        IF EXISTS(SELECT [answer]     
                  FROM   [dbo].[trecruitconflictansdtls]     
                  WHERE  [answer] = @answer)     
          BEGIN     
              SET @message='Answer Details Already Exists'     
    
              RETURN;     
          END     
        ELSE     
          BEGIN     
              SELECT @anslanguageid = Count(languageid)     
              FROM   [dbo].[trecruitconflictansdtls]     
              WHERE  languageid = @languageid     
    
              INSERT INTO [dbo].[trecruitconflictansdtls]     
                          (languageid,     
                           [number],     
                           [answer],     
                           [activeflag],     
                           [createdby],     
                           [createdon],     
                           [updateddby],     
                           [updateddon])     
              VALUES      ( @languageid,     
                            @anslanguageid + 1,     
                            @answer,     
                            'Yes',     
                            @empcode,     
                            Getdate(),     
                            @empcode,     
                            Getdate() )     
    
              SET @message='Answer Details Successfully Inserted'     
          END     
    
      IF @action = 'Conquesansupdate'     
        IF EXISTS(SELECT [answer]     
                  FROM   [dbo].[trecruitconflictansdtls]     
                  WHERE  [answer] = @answer)     
          BEGIN     
              SET @message='Answer Details Already Exists'     
    
              RETURN;     
          END     
        ELSE     
          BEGIN     
              UPDATE [dbo].[trecruitconflictansdtls]     
              SET    languageid = @languageid,     
                     --[number] = @number,                      
                     [answer] = @answer,     
                     [activeflag] = @activeflag,     
                     [createdby] = @empcode,     
                     [createdon] = Getdate(),     
                     [updateddby] = @empcode,     
                     [updateddon] = Getdate()     
              WHERE  id = @answerdtlsid     
    
              SET @message='Answer Details Successfully Updated'     
          END     
    
      IF @action = 'Concandidatelanguagemap'     
        BEGIN     
            DELETE FROM [dbo].[tbl_EDUCYTE_Conflictcanlanguagemap]     
            WHERE  TraineeID = @traineeid    
    
            INSERT INTO [dbo].[tbl_EDUCYTE_Conflictcanlanguagemap]     
                        ([TraineeID],  
      [UserEmail],  
                         [IDLang])     
            VALUES      (@traineeid,   
                @username,  
                         @languageid)     
    
   SELECT @maplanid = IDLang     
      FROM   [dbo].[tbl_EDUCYTE_Conflictcanlanguagemap] p     
      WHERE  @traineeId = TraineeID     
    
      SELECT @countexamques = Count([question])     
      FROM   [dbo].[trecruitconflictqusdtls]     
      WHERE  [languageid] = @maplanid     
    
            SELECT @attemptno = Count([attemexam])     
            FROM   [dbo].[tbl_EDUCYTE_Conflictexamdtls]     
            WHERE  [finalsubmit] = 'Yes'     
                   AND @traineeId = TraineeID     
    
            DELETE FROM [dbo].[tbl_EDUCYTE_ConflictEducyteTraineedtls]     
            WHERE  [quesfinalsubmitques] IS NULL     
                   AND @traineeId = TraineeID     
    
            DELETE FROM [dbo].[tbl_EDUCYTE_Conflictexamdtls]     
            WHERE  [Finalsubmit] = 'No'     
                   AND @traineeId = TraineeID     
    
            INSERT INTO [dbo].[tbl_EDUCYTE_Conflictexamdtls]     
                        ([TraineeID],  
       [UserEmail],  
                         [IDLang],     
                         [Totalques],     
                         [Attemques],     
                         [Finalsubmit],    
                         [Attemexam])     
            VALUES      ( @traineeid,  
                  @username,  
                          @languageid,     
                          @countexamques,     
                          null,     
                          'No',     
                          @attemptno + 1 )     
        END     
    
      IF @action = 'Conquesansselect'     
        BEGIN     
            SELECT previousvalue,     
                   previousvalueques,     
                   quesserialno,     
                   question,     
                   nextvalue,     
                   nextvalueques,     
                   noofques     
            FROM   (SELECT Lag(p.quesserialno)     
                             OVER (                                  ORDER BY p.[id]) PreviousValue,     
                           Lag(p.question)     
                             OVER (     
                               ORDER BY p.[id]) PreviousValueques,     
                           p.quesserialno,     
                           p.question,     
                           Lead(p.quesserialno)     
                             OVER (     
                               ORDER BY p.[id]) NextValue,     
                           Lead(p.question)     
                             OVER (     
                               ORDER BY p.[id]) NextValueques,     
                           languageid     
                    FROM   [dbo].[trecruitconflictqusdtls] p     
                    WHERE  languageid = @maplanid     
                           AND activeflag = 'yes')s,     
                   (SELECT languageid,     
                           Count([question])noofques     
                    FROM   [dbo].[trecruitconflictqusdtls]     
                    WHERE  languageid = @maplanid     
                           AND activeflag = 'Yes'     
                    GROUP  BY languageid) p     
            WHERE  quesserialno = @quesserialno     
                   AND p.languageid = s.languageid     
        END     
    
      IF @action = 'Conquesansselectnext'     
        BEGIN     
            SELECT previousvalue,     
                   previousvalueques,     
                   quesserialno,     
                   question,     
                   nextvalue,     
                   nextvalueques,     
                   noofques,     
                   CASE     
                     WHEN x.TraineeID IS NULL THEN '0'     
                     ELSE x.TraineeID     
                   END TraineeID,     
                   CASE     
                     WHEN x.[answer] IS NULL THEN 0     
                     ELSE x.[answer]     
                   END answer,     
                   CASE     
                     WHEN y.[attemques] BETWEEN 1 AND 100 THEN y.[attemques]     
                     ELSE y.[attemques]     
                   END [attemques]     
            FROM   (SELECT Lag(p.quesserialno)     
                             OVER (     
                               ORDER BY p.[id]) PreviousValue,     
                           Lag(p.question)     
                             OVER (     
                               ORDER BY p.[id]) PreviousValueques,     
                           p.quesserialno,     
                           p.question,     
                           Lead(p.quesserialno)     
                             OVER (     
                               ORDER BY p.[id]) NextValue,     
                           Lead(p.question)     
                             OVER (     
                               ORDER BY p.[id]) NextValueques,     
                           languageid     
                    FROM   [dbo].[trecruitconflictqusdtls] p     
                    WHERE  languageid = @maplanid     
                           AND activeflag = 'yes')s     
                   LEFT OUTER JOIN     
                   [dbo].[tbl_EDUCYTE_ConflictEducyteTraineedtls]     
                   x     
                                ON s.languageid = x.[IDLang]     
                                   AND s.quesserialno = x.[questionid]     
                                   AND [quesfinalsubmitques] IS NULL     
                                   AND x.[TraineeID] = @TraineeID,     
                   (SELECT languageid,     
                           Count([question])noofques     
                    FROM   [dbo].[trecruitconflictqusdtls]     
                    WHERE  languageid = @maplanid     
                           AND activeflag = 'Yes'     
                    GROUP  BY languageid) p,     
                   [dbo].[tbl_EDUCYTE_Conflictexamdtls] y     
            WHERE  quesserialno = @quesserialnonext     
                   AND p.languageid = s.languageid     
                   AND s.languageid = y.[IDLang]     
                   AND y.[TraineeID] = @TraineeID     
                   AND [finalsubmit] <> 'Yes'     
        END     
    
      IF @action = 'Conansselect'     
        BEGIN     
            SELECT [number],     
                   [answer],     
                   language     
            FROM   [dbo].[trecruitconflictansdtls] ans,     
                   [dbo].[languages] lan     
            WHERE  ans.[languageid] = lan.[id]     
                   AND lan.[id] = @maplanid     
        END     
    
      IF @action = 'Conolquesansselect'     
        BEGIN     
            SELECT [question]     
            FROM   [dbo].[trecruitconflictqusdtls]     
            WHERE  languageid = @ollanguageid     
                   AND quesserialno = @olquesserialno     
    
            SELECT [number],     
                   [answer]     
            FROM   [dbo].[trecruitconflictansdtls] ans     
            WHERE  ans.[languageid] = @ollanguageid     
        END     
    
      IF @action = 'Conansselecthr'     
        BEGIN     
            SELECT [number],     
                   [answer],     
                   language     
            FROM   [dbo].[trecruitconflictansdtls] ans,     
                   [dbo].[languages] lan     
            WHERE  ans.[languageid] = lan.[id]     
                   AND lan.[id] = @languageid     
        END     
    
      IF @action = 'Concandtlsinsert'     
         AND @findques = 0     
        BEGIN     
            SELECT @countexamattm = [attemexam]     
            FROM   [dbo].[tbl_EDUCYTE_Conflictexamdtls]     
            WHERE  [TraineeID] = @TraineeID     
                   AND finalsubmit <> 'Yes'     
    
            SELECT @countexamattmcan = Count([TraineeID])     
            FROM   [dbo].[tbl_EDUCYTE_Conflictexamdtls]     
            WHERE  [TraineeID] = @TraineeID     
    
            BEGIN     
                INSERT INTO [dbo].[tbl_EDUCYTE_ConflictEducyteTraineedtls]     
                            ([TraineeID],     
        [UserEmail],  
                             [IDLang],     
                             [questionid],     
                             [answer],     
                             Traineeattemexam,     
                             [createdon],     
                             [updatedon])     
                VALUES      ( @TraineeID,   
                  @username,  
                              @maplanid,     
                              @questiondtlsid,     
                              @number,     
                              @countexamattm,     
                              Getdate(),     
                              Getdate() )     
    
                SET @message='Answer Details Successfully Inserted'     
            END     
    
            SELECT @countexamattques = Count([questionid])     
            FROM   [dbo].[tbl_EDUCYTE_ConflictEducyteTraineedtls]     
            WHERE  @traineeId = TraineeID     
                   AND answer <> 0     
                   AND quesfinalsubmitques IS NULL     
    
            IF @countexamattm IS NOT NULL     
              BEGIN     
                  UPDATE [dbo].[tbl_EDUCYTE_Conflictexamdtls]     
                  SET    [attemques] = [totalques] - @countexamattques     
                  WHERE  @traineeId = TraineeID     
                         AND finalsubmit <> 'Yes'     
              END     
        END     
    
      IF @action = 'Concandtlsinsert'     
         AND @findques > 0     
        BEGIN     
            SELECT @countexamattm = [attemexam]     
            FROM   [dbo].[tbl_EDUCYTE_Conflictexamdtls]     
            WHERE  [TraineeID] = @TraineeID     
                   AND finalsubmit <> 'Yes'     
    
            UPDATE [dbo].[tbl_EDUCYTE_ConflictEducyteTraineedtls]     
            SET    [answer] = @number,     
                   [updatedon] = Getdate()     
            WHERE  [TraineeID] = @TraineeID     
                   AND [questionid] = @questiondtlsid     
                   AND [quesfinalsubmitques] IS NULL     
    
            SET @message='Answer Details Successfully Updated'     
    
            SELECT @countexamattques = Count([questionid])     
            FROM   [dbo].[tbl_EDUCYTE_ConflictEducyteTraineedtls]     
            WHERE  @traineeId = TraineeID     
                   AND answer <> 0     
                   AND quesfinalsubmitques IS NULL     
    
            IF @countexamattm IS NOT NULL     
              BEGIN     
         UPDATE [dbo].[tbl_EDUCYTE_Conflictexamdtls]     
                  SET    [attemques] = [totalques] - @countexamattques     
                  WHERE  @traineeId = TraineeID     
                         AND finalsubmit <> 'Yes'     
              END     
        END     
    
      IF @action = 'Finalsubmit'     
        BEGIN     
            UPDATE [dbo].[tbl_EDUCYTE_Conflictexamdtls]     
            SET    [finalsubmit] = 'Yes'     
            WHERE  @traineeId = TraineeID     
    
            --UPDATE [dbo].[trecruittraker]     
            --SET    [conflictallow] = 'Completed'     
            --WHERE  @traineeId = TraineeID     
    
   -----------------------------------------    
   UPDATE [dbo].[tbl_Educyte_PersonalDetails]     
            SET    [conflictallow] = 'Completed'     
            WHERE  @traineeId = TraineeID     
   -------------------------------------------    
    
            UPDATE [dbo].[tbl_EDUCYTE_ConflictEducyteTraineedtls]     
            SET    [quesfinalsubmitques] = 'F'     
            WHERE  @traineeId = TraineeID     
        END     
    
      IF @action = 'Concandtlsselect'     
        BEGIN     
            SELECT disc.[id],     
                   disc.[TraineeID],     
                   disc.[IDLang],     
                   disc.[questionid],     
                   ques.[question],     
                   disc.[answer]     
            FROM   [dbo].[tbl_EDUCYTE_ConflictEducyteTraineedtls] disc,     
                   [dbo].[trecruitconflictqusdtls] ques     
            WHERE  [TraineeID] = @TraineeID     
                   AND [questionid] = @questiondtlsid     
                   AND disc.[questionid] = ques.id     
        END     
    
      IF @action = 'Concandtlsselect'     
        BEGIN     
            IF NOT EXISTS (SELECT TraineeID     
                           FROM     
                   [dbo].[tbl_EDUCYTE_ConflictEducyteTraineedtls]     
                           WHERE  @traineeId = TraineeID)     
              BEGIN     
                  SELECT Min([id]),     
                         [question]     
                  FROM   [dbo].[trecruitconflictqusdtls]     
                  WHERE  [languageid] = @languageid     
                         AND activeflag = 'Yes'     
                  GROUP  BY [languageid],     
                            [question]     
    
                  SELECT [number],     
                         [answer]     
                  FROM   [dbo].[trecruitconflictansdtls]     
                  WHERE  [languageid] = @languageid     
                         AND activeflag = 'Yes'     
              END     
        --SELECT disc.[id],                      
        --       disc.[TraineeID],                      
        --       disc.[languageid],                      
        --       disc.[questionid],                      
     --       ques.[question],                      
        --       disc.[answer]                      
        --FROM   [dbo].[tbl_EDUCYTE_ConflictEducyteTraineedtls] disc,                      
        --       [dbo].[trecruitconflictqusdtls] ques                      
        --WHERE  [TraineeID] = @TraineeID                      
        --       AND [questionid] = @questiondtlsid                      
        --       AND disc.[questionid] = ques.id                      
        END     
    
      IF @action = 'Conansqnoselect'     
        BEGIN     
            SELECT @atteptestno = [attemexam]     
            FROM   [dbo].[tbl_EDUCYTE_Conflictexamdtls]     
            WHERE  [finalsubmit] <> 'Yes'     
                   AND [TraineeID] = @TraineeID     
    
            SELECT [questionid]     
            FROM   [dbo].[tbl_EDUCYTE_ConflictEducyteTraineedtls]     
            WHERE  [answer] > 0     
                   AND [Traineeattemexam] = @atteptestno     
                   AND [TraineeID] = @TraineeID     
        END   
		
 Commit Tran   
 Set @message=''  
End Try   
Begin Catch   
 Rollback Tran   
 Set @message=dbo.fnErrors()  
End Catch   
 Select @message  
  END 
GO



