/****** Object:  StoredProcedure [dbo].[proc_EDUCYTE_discandidatenamepost]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
CREATE proc [dbo].[proc_EDUCYTE_discandidatenamepost]  
   
                                 @traineeId NVARCHAR(max)=NULL
as  
 DECLARE @useremail NVARCHAR(max)      
begin  
  
  SELECT @useremail = UserEmail   
      FROM   [dbo].[tbl_Educyte_PersonalDetails]   
      WHERE  TraineeID = @traineeId   
  
SELECT TraineeiD, (A.FirstName +'' +                
Isnull(A.MiddleName,'') +'' +                
A.LastName) as TraineeName
                   
                      
            FROM   [dbo].[tbl_Educyte_PersonalDetails] A                   
            WHERE   a.TraineeID = @traineeId  
                   
      
       end  
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_Driscoltraineedtls, tbl_EDUCYTE_Language, tbl_Educyte_PersonalDetails, trecruitdiscrolansdtls, trecruitdiscrolquestype, trecruitdiscrolqusdtls */
/****** Object:  StoredProcedure [dbo].[proc_EDUCYTE_disCHAMELEONtotalno]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
                           
       CREATE proc [dbo].[proc_EDUCYTE_disCHAMELEONtotalno]  
       @candidateattemexam INT=NULL,   
@traineeId NVARCHAR(max)=NULL    
       as  
      DECLARE @useremail NVARCHAR(max)   
       begin  
  
        SELECT @useremail = UserEmail   
      FROM   [dbo].[tbl_Educyte_PersonalDetails]   
      WHERE  TraineeID = @traineeId 
  
       SELECT   
                           a.questionid,   
                           a.AnswerID  
                    FROM   [dbo].[tbl_EDUCYTE_Driscoltraineedtls] a,   
                           [dbo].[trecruitdiscrolqusdtls] b,   
                           [dbo].[trecruitdiscrolquestype] c,   
                           [dbo].[trecruitdiscrolansdtls]f,   
                           [dbo].[tbl_Educyte_PersonalDetails] d,   
                           [dbo].[tbl_EDUCYTE_Language] e   
                    WHERE   a.[IDLang] = b.[languageid]   
                           AND a.[questionid] = b.[quesserialno]   
                           AND b.[disquestypeid] = c.[id]   
                          AND a.[TraineeID] = d.[TraineeID]   
                           AND a.[IDLang] = e.[id]   
                           AND a.AnswerID = f.[number] 
        and a.[IDLang]=f.[languageid]                              
                           AND [Traineeattemexam] = @candidateattemexam  
                           AND c.[disquestype] = 'CHAMELEON'   
         and a.TraineeID=@traineeId
  
         end  
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: Languages, tbl_EDUCYTE_DriscolLanguageMap, tbl_EDUCYTE_Driscoltrainee_examdtls, tbl_EDUCYTE_Driscoltraineedtls, tbl_Educyte_PersonalDetails, tbl_EDUCYTE_Trainee_SignupDtls, trecruitdiscrolansdtls, trecruitdiscrolcandidatedtls, trecruitdiscrolquestype, trecruitdiscrolqusdtls, trecruittraker */
/****** Object:  StoredProcedure [dbo].[proc_EDUCYTE_discrolmasdtls]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 -- proc_EDUCYTE_discrolmasdtls 'Disquesansselect' ,'', 'demo@gmail.com',''  
CREATE PROC [dbo].[proc_EDUCYTE_discrolmasdtls] @action           NVARCHAR(100)=NULL,     
                                      @disquestype      NVARCHAR(100)=NULL,     
                                      @username         NVARCHAR(100)=NULL,     
                                      @activeflag       NVARCHAR(10)=NULL,     
                                      @disquestypeid    INT=NULL,     
                                      @languageid       INT=NULL,     
                                      @question         NVARCHAR(max)=NULL,     
                                      @questiondtlsid   INT=NULL,     
                                      @answer           NVARCHAR(max)=NULL,     
                                      @number           INT=NULL,     
                                      @answerdtlsid     INT=NULL,     
                                      @quesserialnonext INT=NULL,     
                                      @ollanguageid     INT=NULL,     
                                      @olquesserialno   INT=NULL,     
                                      @message          VARCHAR(500)=NULL output     
AS     
    DECLARE @empcode VARCHAR(100)     
    DECLARE @traineeID NVARCHAR(MAX)     
    DECLARE @anslanguageid INT     
    DECLARE @queslanguageid INT     
    DECLARE @countexamques INT     
    DECLARE @countexamattm INT     
    DECLARE @countexamattques INT     
    DECLARE @quesserialno INT     
    DECLARE @maplanid INT     
    DECLARE @countexamattmcan INT     
    DECLARE @findques INT     
    DECLARE @idd INT     
    DECLARE @attemptno INT     
    DECLARE @cattemptno INT     
    DECLARE @atteptestno INT     
    
  BEGIN     
      --SELECT @empcode = empcode     
      --FROM   essp.dbo.emp     
      --WHERE  empemail = @username     
    
      SELECT @traineeID = TraineeID     
      FROM   [dbo].[tbl_EDUCYTE_Trainee_SignupDtls]     
      WHERE  [UserEmail] = @username     
    
      SELECT @maplanid = IDLang     
      FROM   [dbo].[tbl_EDUCYTE_DriscolLanguageMap] p     
      WHERE  TraineeID = @traineeID     
    
      SELECT @countexamques = Count([question])     
      FROM   [dbo].[trecruitdiscrolqusdtls]     
      WHERE  [languageid] = @maplanid     
    
      SELECT @quesserialno = Min(quesserialno)     
      FROM   [dbo].[trecruitdiscrolqusdtls] p     
      WHERE  languageid = @maplanid     
             AND activeflag = 'yes'     
    
      SELECT @findques = Count(questionid)     
      FROM   [dbo].[tbl_EDUCYTE_Driscoltraineedtls]     
      WHERE  TraineeID = @traineeID     
             AND questionid = @questiondtlsid     
             AND [Quesfinalsubmit] IS NULL     
    
      IF @action = 'Disquestypeinsert'     
        IF EXISTS(SELECT [disquestype]     
                  FROM   [dbo].[trecruitdiscrolquestype]     
                  WHERE  [disquestype] = @disquestype)     
          BEGIN     
              SET @message='Question Type Already Exists'     
    
              RETURN;     
          END     
        ELSE     
          BEGIN     
              INSERT INTO [dbo].[trecruitdiscrolquestype]     
                          ([disquestype],     
                           [activeflag],     
                           [createdby],     
                           [createdon],     
                           [updateddby],     
                           [updateddon])     
              VALUES      ( @disquestype,     
                            'Yes',     
                            @empcode,     
                            Getdate(),     
                            @empcode,     
                            Getdate() )     
    
              SET @message='Question Type Successfully Inserted'     
          END     
    
      IF @action = 'Disquestypeupdate'     
        IF EXISTS(SELECT [disquestype]     
                  FROM   [dbo].[trecruitdiscrolquestype]     
                  WHERE  [disquestype] = @disquestype)     
          BEGIN     
        SET @message='Question Type Already Exists'     
    
              RETURN;     
          END     
        ELSE     
          BEGIN     
              UPDATE [dbo].[trecruitdiscrolquestype]     
              SET    [disquestype] = @disquestype,     
                     [activeflag] = @activeflag,     
                     [updateddby] = @empcode,     
                     [updateddon] = Getdate()     
              WHERE  id = @disquestypeid     
    
              SET @message='Question Type Successfully Updated'     
          END     
    
      IF @action = 'Disquestypeselect'     
        BEGIN     
            SELECT [id],     
                   [disquestype],     
                   [activeflag]     
            FROM   [dbo].[trecruitdiscrolquestype]     
        END     
    
      IF @action = 'Disquesinsert'     
        IF EXISTS(SELECT [question]     
                  FROM   [dbo].[trecruitdiscrolqusdtls]     
                  WHERE  [question] = @question)     
          BEGIN     
              SET @message='Question Details Already Exists'     
    
              RETURN;     
          END     
        ELSE     
          BEGIN     
              SELECT @queslanguageid = Count(languageid)     
              FROM   [dbo].[trecruitdiscrolqusdtls]     
              WHERE  languageid = @languageid     
    
              INSERT INTO [dbo].[trecruitdiscrolqusdtls]     
                          (languageid,     
                           [quesserialno],     
                           [question],     
                           [disquestypeid],     
                           [activeflag],     
                           [createdby],     
                           [createdon],     
                           [updateddby],     
                           [updateddon])     
              VALUES      ( @languageid,     
                            @queslanguageid + 1,     
                            @question,     
                            @disquestypeid,     
                            'Yes',     
                            @empcode,     
                            Getdate(),     
                            @empcode,     
                            Getdate() )     
    
              SET @message='Question Details Successfully Inserted'     
          END     
    
      IF @action = 'Disquesupdate'     
        IF EXISTS(SELECT [question]     
                  FROM   [dbo].[trecruitdiscrolqusdtls]     
                  WHERE  [question] = @question)     
          BEGIN     
              SET @message='Question Details Already Exists'     
    
              RETURN;     
          END     
        ELSE     
          BEGIN     
              UPDATE [dbo].[trecruitdiscrolqusdtls]     
              SET    languageid = @languageid,     
                     [question] = @question,     
                     [disquestypeid] = @disquestypeid,     
                     [activeflag] = @activeflag,     
                     [updateddby] = @empcode,     
                     [updateddon] = Getdate()     
              WHERE  [id] = @questiondtlsid     
    
              SET @message='Question Details Successfully updated'     
          END     
    
      IF @action = 'Disquesselect'     
        BEGIN     
            SELECT ques.[id],     
                   ques.[languageid],     
                   ques.[quesserialno],     
                   lan.language,     
                   ques.[question],     
                   ques.[disquestypeid],     
                   qty.[disquestype],     
                   ques.[activeflag],     
                   ques.[createdby],     
                   ques.[createdon],     
                   ques.[updateddby],     
                   ques.[updateddon]     
            FROM   [dbo].[trecruitdiscrolqusdtls] ques,     
                   [dbo].[languages] lan,     
                   [dbo].[trecruitdiscrolquestype] qty     
            WHERE  ques.[languageid] = lan.[id]     
                   AND lan.[id] = @languageid     
                   AND ques.[disquestypeid] = qty.id     
            ORDER  BY ques.[quesserialno]     
        END     
    
      IF @action = 'Disquesansinsert'     
        IF EXISTS(SELECT [answer]     
                  FROM   [dbo].[trecruitdiscrolansdtls]     
                  WHERE  [answer] = @answer)     
          BEGIN     
              SET @message='Answer Details Already Exists'     
    
              RETURN;     
          END     
        ELSE     
          BEGIN     
              SELECT @anslanguageid = Count(languageid)     
         FROM   [dbo].[trecruitdiscrolansdtls]     
              WHERE  languageid = @languageid     
    
              INSERT INTO [dbo].[trecruitdiscrolansdtls]     
                          (languageid,     
                           [number],     
                           [answer],     
                           [activeflag],     
                           [createdby],     
                           [createdon],     
                           [updateddby],     
                           [updateddon])     
              VALUES      ( @languageid,     
                            @anslanguageid + 1,     
                            @answer,     
                            'Yes',     
                            @empcode,     
                            Getdate(),     
                            @empcode,     
                            Getdate() )     
    
              SET @message='Answer Details Successfully Inserted'     
          END     
    
      IF @action = 'Disquesansupdate'     
        IF EXISTS(SELECT [answer]     
                  FROM   [dbo].[trecruitdiscrolansdtls]     
                  WHERE  [answer] = @answer)     
          BEGIN     
              SET @message='Answer Details Already Exists'     
    
              RETURN;     
          END     
        ELSE     
          BEGIN     
              UPDATE [dbo].[trecruitdiscrolansdtls]     
              SET    languageid = @languageid,     
                     --[number] = @number,                      
                     [answer] = @answer,     
                     [activeflag] = @activeflag,     
                     [createdby] = @empcode,     
                     [createdon] = Getdate(),     
                     [updateddby] = @empcode,     
                     [updateddon] = Getdate()     
              WHERE  id = @answerdtlsid     
    
              SET @message='Answer Details Successfully Updated'     
          END     
    
      IF @action = 'Discandidatelanguagemap'     
        BEGIN     
            DELETE FROM [dbo].[tbl_EDUCYTE_DriscolLanguageMap]     
            WHERE  [TraineeID] = @traineeID     
    
            INSERT INTO [dbo].[tbl_EDUCYTE_DriscolLanguageMap]     
                        ([TraineeID],   
       [UserEmail],  
                         [IDLang])     
            VALUES      (@traineeID,     
                         @username,  
       @languageid)     
    
   SELECT @maplanid = IDLang     
      FROM   [dbo].[tbl_EDUCYTE_DriscolLanguageMap] p     
      WHERE  TraineeID = @traineeID     
    
      SELECT @countexamques = Count([question])     
      FROM   [dbo].[trecruitdiscrolqusdtls]     
      WHERE  [languageid] = @maplanid     
    
            SELECT @attemptno = Count([attemexam])     
            FROM   [dbo].[tbl_EDUCYTE_Driscoltrainee_examdtls]     
            WHERE  [finalsubmit] = 'Yes'     
                   AND TraineeID = @traineeID     
    
            DELETE FROM [dbo].[tbl_EDUCYTE_Driscoltraineedtls]     
            WHERE  [Quesfinalsubmit] IS NULL     
                   AND TraineeID = @traineeID       
    
            DELETE FROM [dbo].[tbl_EDUCYTE_Driscoltrainee_examdtls]     
            WHERE  [finalsubmit] = 'No'     
                   AND TraineeID = @traineeID     
    
            INSERT INTO [dbo].[tbl_EDUCYTE_Driscoltrainee_examdtls]     
                        ([TraineeID],   
       [UserEmail],   
                         [LanguageId],     
                         [Totalques],     
                         [Attemques],     
                    [Finalsubmit],     
                         [Attemexam])     
            VALUES      ( @traineeID,    
                  @username,  
                          @languageid,     
                          @countexamques,     
                          null,     
                          'No',     
                          @attemptno + 1 )     
        END     
    
      IF @action = 'Disquesansselect'     
        BEGIN     
            SELECT previousvalue,     
                   previousvalueques,     
                   quesserialno,     
                   question,     
                   nextvalue,     
                   nextvalueques,     
                   noofques     
            FROM   (SELECT Lag(p.quesserialno)     
                             OVER (     
      ORDER BY p.[id]) PreviousValue,     
                           Lag(p.question)     
                             OVER (     
                               ORDER BY p.[id]) PreviousValueques,     
                           p.quesserialno,     
                           p.question,     
                           Lead(p.quesserialno)     
                             OVER (     
                               ORDER BY p.[id]) NextValue,     
                           Lead(p.question)     
                             OVER (     
                               ORDER BY p.[id]) NextValueques,     
                           languageid     
                    FROM   [dbo].[trecruitdiscrolqusdtls] p     
                    WHERE  languageid = @maplanid     
                           AND activeflag = 'yes')s,     
                   (SELECT languageid,     
                           Count([question])noofques     
                    FROM   [dbo].[trecruitdiscrolqusdtls]     
                    WHERE  languageid = @maplanid     
                           AND activeflag = 'Yes'     
                    GROUP  BY languageid) p     
            WHERE  quesserialno = @quesserialno     
                   AND p.languageid = s.languageid     
        END     
    
      IF @action = 'Disquesansselectnext'     
        BEGIN     
            SELECT previousvalue,     
                   previousvalueques,     
                   quesserialno,     
                   question,     
                   nextvalue,     
                   nextvalueques,     
                   noofques,     
                   CASE     
                     WHEN x.TraineeID IS NULL THEN '0'     
                     ELSE x.TraineeID     
                   END candidateid,     
                   CASE     
                     WHEN x.[AnswerID] IS NULL THEN 0     
                     ELSE x.[AnswerID]     
                   END answer,     
                   CASE     
                     WHEN y.[attemques] BETWEEN 1 AND 100 THEN y.[attemques]     
                     ELSE y.[attemques]     
                   END [attemques]     
            FROM   (SELECT Lag(p.quesserialno)     
                             OVER (     
                               ORDER BY p.[id]) PreviousValue,     
                           Lag(p.question)     
                             OVER (     
                               ORDER BY p.[id]) PreviousValueques,     
                           p.quesserialno,     
                           p.question,     
                           Lead(p.quesserialno)     
                             OVER (     
                               ORDER BY p.[id]) NextValue,     
                           Lead(p.question)     
                             OVER (     
                               ORDER BY p.[id]) NextValueques,     
                           languageid     
                    FROM   [dbo].[trecruitdiscrolqusdtls] p     
                    WHERE  languageid = @maplanid     
                           AND activeflag = 'yes')s     
                   LEFT OUTER JOIN     
                   [dbo].[tbl_EDUCYTE_Driscoltraineedtls]     
                   x     
                                ON s.languageid = x.[IDLang]     
                                   AND s.quesserialno = x.[questionid]     
                                   AND [Quesfinalsubmit] IS NULL     
                                   AND x.[TraineeID] = @traineeID,     
                   (SELECT languageid,     
                           Count([question])noofques     
                    FROM   [dbo].[trecruitdiscrolqusdtls]     
                    WHERE  languageid = @maplanid     
                           AND activeflag = 'Yes'     
                    GROUP  BY languageid) p,     
                   [dbo].[tbl_EDUCYTE_Driscoltrainee_examdtls] y     
            WHERE  quesserialno = @quesserialnonext     
                   AND p.languageid = s.languageid     
                   AND s.languageid = y.[languageid]     
                   AND y.[TraineeID] = @traineeID     
                   AND [finalsubmit] <> 'Yes'     
        END     
    
      IF @action = 'Disansselect'     
        BEGIN     
            SELECT [number],     
                   [answer],     
                   language     
            FROM   [dbo].[trecruitdiscrolansdtls] ans,     
                   [dbo].[languages] lan     
            WHERE  ans.[languageid] = lan.[id]     
                   AND lan.[id] = @maplanid     
        END     
    
      IF @action = 'Disolquesansselect'     
        BEGIN     
            SELECT [question]     
            FROM   [dbo].[trecruitdiscrolqusdtls]     
            WHERE  languageid = @ollanguageid     
                   AND quesserialno = @olquesserialno     
    
            SELECT [number],     
                   [answer]     
            FROM   [dbo].[trecruitdiscrolansdtls] ans     
            WHERE  ans.[languageid] = @ollanguageid     
        END     
    
      IF @action = 'Disansselecthr'     
        BEGIN     
            SELECT [number],     
                   [answer],     
                   language     
            FROM   [dbo].[trecruitdiscrolansdtls] ans,     
                   [dbo].[languages] lan     
            WHERE  ans.[languageid] = lan.[id]     
                   AND lan.[id] = @languageid     
        END     
    
      IF @action = 'Discandtlsinsert'     
         AND @findques = 0     
        BEGIN     
            SELECT @countexamattm = [attemexam]     
            FROM   [dbo].[tbl_EDUCYTE_Driscoltrainee_examdtls]     
            WHERE  [TraineeID] = @traineeID     
                   AND finalsubmit <> 'Yes'     
    
            SELECT @countexamattmcan = Count([TraineeID])     
            FROM   [dbo].[tbl_EDUCYTE_Driscoltrainee_examdtls]     
            WHERE  [TraineeID] = @traineeID      
    
            BEGIN     
                INSERT INTO [dbo].[tbl_EDUCYTE_Driscoltraineedtls]     
                            ([TraineeID],  
        [UserEmail],  
                             [IDLang],     
                             [QuestionId],     
                             [AnswerID],     
                             Traineeattemexam,     
                             [CreatedTime],     
                             [UpdatedTime])     
                VALUES      ( @traineeID,   
                  @username,  
                              @maplanid,     
                              @questiondtlsid,     
                              @number,     
                              @countexamattm,     
                              Getdate(),     
                              Getdate() )     
    
                SET @message='Answer Details Successfully Inserted'     
            END     
    
            SELECT @countexamattques = Count([QuestionId])     
            FROM   [dbo].[tbl_EDUCYTE_Driscoltraineedtls]     
            WHERE  TraineeID = @traineeID     
                   AND AnswerID <> 0     
                   AND Quesfinalsubmit IS NULL     
    
            IF @countexamattm IS NOT NULL     
              BEGIN     
                  UPDATE [dbo].[tbl_EDUCYTE_Driscoltrainee_examdtls]     
                  SET    [Attemques] = [Totalques] - @countexamattques     
               WHERE  TraineeID = @traineeID     
                         AND finalsubmit <> 'Yes'     
              END     
        END     
    
      IF @action = 'Discandtlsinsert'     
         AND @findques > 0     
        BEGIN     
            SELECT @countexamattm = [attemexam]     
            FROM   [dbo].[tbl_EDUCYTE_Driscoltrainee_examdtls]     
            WHERE  [TraineeID] = @traineeID     
                   AND finalsubmit <> 'Yes'     
    
            UPDATE [dbo].[tbl_EDUCYTE_Driscoltraineedtls]     
            SET    [AnswerID] = @number,     
                   [UpdatedTime] = Getdate()     
            WHERE  [TraineeID] = @traineeID     
                   AND [QuestionId] = @questiondtlsid     
                   AND [Quesfinalsubmit] IS NULL     
    
            SET @message='Answer Details Successfully Updated'     
    
            SELECT @countexamattques = Count([QuestionId])     
            FROM   [dbo].[tbl_EDUCYTE_Driscoltraineedtls]     
            WHERE  TraineeID = @traineeID     
                   AND AnswerID <> 0     
                   AND Quesfinalsubmit IS NULL     
    
            IF @countexamattm IS NOT NULL     
              BEGIN     
                  UPDATE [dbo].[tbl_EDUCYTE_Driscoltrainee_examdtls]     
                  SET    [Attemques] = [Totalques] - @countexamattques     
                  WHERE  TraineeID = @traineeID     
                         AND Finalsubmit <> 'Yes'     
              END     
        END     
    
      IF @action = 'Finalsubmit'     
        BEGIN     
            UPDATE [dbo].[tbl_EDUCYTE_Driscoltrainee_examdtls]     
            SET    [Finalsubmit] = 'Yes'     
            WHERE  TraineeID = @traineeID     
    
            --UPDATE [dbo].[trecruittraker]     
            --SET    [discrolallow] = 'Completed'     
            --WHERE  candidateid = @candidateid     
   -----------------------------------------    
   UPDATE [dbo].[tbl_Educyte_PersonalDetails]     
            SET    [Driscolallow] = 'Completed'     
            WHERE  TraineeID = @traineeID     
   -------------------------------------------    
            UPDATE [dbo].[tbl_EDUCYTE_Driscoltraineedtls]     
            SET    [Quesfinalsubmit] = 'F'     
            WHERE  TraineeID = @traineeID     
        END     
    
      IF @action = 'Discandtlsselect'     
        BEGIN     
            SELECT disc.[id],     
                   disc.[TraineeID],     
                   disc.[IDLang],     
                   disc.[questionid],     
                   ques.[question],     
                   disc.[AnswerId]     
            FROM   [dbo].[tbl_EDUCYTE_Driscoltraineedtls] disc,     
                   [dbo].[trecruitdiscrolqusdtls] ques     
            WHERE  [TraineeID] = @traineeID     
                   AND [questionid] = @questiondtlsid     
                   AND disc.[questionid] = ques.id     
        END     
    
      IF @action = 'Discandtlsselect'     
        BEGIN     
            IF NOT EXISTS (SELECT TraineeID     
                           FROM     
                   [dbo].[tbl_EDUCYTE_Driscoltraineedtls]     
                           WHERE  TraineeID = @traineeID)     
              BEGIN     
                  SELECT Min([id]),     
                         [question]     
                  FROM   [dbo].[trecruitdiscrolqusdtls]     
                  WHERE  [languageid] = @languageid     
                         AND activeflag = 'Yes'     
                  GROUP  BY [languageid],     
                            [question]     
    
                  SELECT [number],     
                         [answer]     
                  FROM   [dbo].[trecruitdiscrolansdtls]     
                  WHERE  [languageid] = @languageid     
                         AND activeflag = 'Yes'     
              END     
        --SELECT disc.[id],                      
        --       disc.[candidateid],                      
        --       disc.[languageid],                      
        --       disc.[questionid],                      
 --       ques.[question],                      
        --       disc.[answer]                      
        --FROM   [dbo].[trecruitdiscrolcandidatedtls] disc,                      
        --       [dbo].[trecruitdiscrolqusdtls] ques                      
        --WHERE  [candidateid] = @candidateid                      
        --       AND [questionid] = @questiondtlsid                      
        --       AND disc.[questionid] = ques.id                      
        END     
    
      IF @action = 'Disansqnoselect'     
        BEGIN     
            SELECT @atteptestno = [attemexam]     
            FROM   [dbo].[tbl_EDUCYTE_Driscoltrainee_examdtls]     
            WHERE  [finalsubmit] <> 'Yes'     
                   AND TraineeID = @traineeID  
    
            SELECT [questionid]     
            FROM   [dbo].[tbl_EDUCYTE_Driscoltraineedtls]     
            WHERE  [AnswerId] > 0     
                   AND [Traineeattemexam] = @atteptestno     
                   AND TraineeID = @traineeID    
        END     
  END 
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_Driscoltraineedtls, tbl_EDUCYTE_Language, tbl_Educyte_PersonalDetails, trecruitdiscrolansdtls, trecruitdiscrolquestype, trecruitdiscrolqusdtls */
/****** Object:  StoredProcedure [dbo].[proc_EDUCYTE_disEAGLEtotalno]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
                             
       CREATE proc [dbo].[proc_EDUCYTE_disEAGLEtotalno]    
       @candidateattemexam INT=NULL,     
                         @traineeId NVARCHAR(max)  
       as    
       DECLARE @useremail NVARCHAR(max)     
    begin    
    
        SELECT @useremail = UserEmail     
      FROM   [dbo].[tbl_Educyte_PersonalDetails]     
      WHERE  TraineeID = @traineeId      
    
       SELECT     
                           a.questionid,     
                           a.AnswerID    
                    FROM   [dbo].[tbl_EDUCYTE_Driscoltraineedtls] a,     
                           [dbo].[trecruitdiscrolqusdtls] b,     
                           [dbo].[trecruitdiscrolquestype] c,     
                           [dbo].[trecruitdiscrolansdtls]f,     
                           [dbo].[tbl_Educyte_PersonalDetails] d,     
                           [dbo].[tbl_EDUCYTE_Language]e     
                    WHERE  a.[IDLang] = b.[languageid]     
                           AND a.[questionid] = b.[quesserialno]     
                           AND b.[disquestypeid] = c.[id]     
                           AND a.[TraineeID] = d.[TraineeID]     
                           AND a.[IDLang] = e.[id]     
                           AND a.AnswerID = f.[number]    
         and a.[IDLang]=f.[languageid]                                
                           AND [Traineeattemexam] = @candidateattemexam    
                           AND c.[disquestype] = 'EAGLE'     
        and a.TraineeID=@traineeId    
    
         end 
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_Conflictexamdtls, tbl_Educyte_PersonalDetails */
/****** Object:  StoredProcedure [dbo].[Proc_EDUCYTE_DisplayConflictcmt]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
CREATE PROCEDURE [dbo].[Proc_EDUCYTE_DisplayConflictcmt]  
@traineeid nvarchar(max) ,      
@examno int  
As        
Begin     
  
  Select B.Comment From tbl_Educyte_PersonalDetails A  
  Inner Join tbl_EDUCYTE_Conflictexamdtls B  
  On A.TraineeID = B.TraineeID  
  Where A.TraineeID = @traineeid  
  And B.attemexam = @examno  
  
        
End
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_Driscoltrainee_examdtls, tbl_Educyte_PersonalDetails */
