SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Proc_EDUCYTE_Displaydiscrolcmt]    
@traineeId NVARCHAR(max) ,        
@examno int    
As          
Begin       
    
  Select B.Comment From tbl_Educyte_PersonalDetails A    
  Inner Join tbl_EDUCYTE_Driscoltrainee_examdtls B    
  On A.TraineeiD = B.TraineeiD    
  Where A.TraineeID = @traineeId    
  And B.attemexam = @examno    
    
          
End
GO



