/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_Iqexamdtls, tbl_Educyte_PersonalDetails */
/****** Object:  StoredProcedure [dbo].[Proc_EDUCYTE_DisplayIqcmt]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
      
    
CREATE PROCEDURE [dbo].[Proc_EDUCYTE_DisplayIqcmt]      
@traineeid nvarchar(max) ,          
@examno int      
As            
Begin         
      
  Select B.Comment From tbl_Educyte_PersonalDetails A      
  Inner Join tbl_EDUCYTE_Iqexamdtls B      
  On A.TraineeID = B.TraineeID      
  Where A.TraineeID = @traineeid      
  And B.attemexam = @examno      
      
            
End
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_Driscoltraineedtls, tbl_EDUCYTE_Language, tbl_Educyte_PersonalDetails, trecruitdiscrolansdtls, trecruitdiscrolquestype, trecruitdiscrolqusdtls */
/****** Object:  StoredProcedure [dbo].[proc_EDUCYTE_disSALMONtotalno]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
                           
       CREATE proc [dbo].[proc_EDUCYTE_disSALMONtotalno]  
       @candidateattemexam INT=NULL,   
@traineeId NVARCHAR(max)=NULL   
       as  
       DECLARE @useremail NVARCHAR(max)   
       begin  
  
  
      SELECT @useremail = UserEmail   
      FROM   [dbo].[tbl_Educyte_PersonalDetails]   
      WHERE  TraineeID = @traineeId   
  
       SELECT   
                           a.questionid,   
                           a.AnswerID  
                    FROM   [dbo].[tbl_EDUCYTE_Driscoltraineedtls] a,   
                           [dbo].[trecruitdiscrolqusdtls] b,   
                           [dbo].[trecruitdiscrolquestype] c,   
                           [dbo].[trecruitdiscrolansdtls]f,   
                           [dbo].[tbl_Educyte_PersonalDetails] d,   
                           [dbo].[tbl_EDUCYTE_Language]e   
                     WHERE  a.[IDLang] = b.[languageid]  
                           AND a.[questionid] = b.[quesserialno]   
                           AND b.[disquestypeid] = c.[id]   
                            AND a.[TraineeID] = d.[TraineeID]   
                           AND a.[IDLang] = e.[id]   
                           AND a.AnswerID = f.[number]  
         and a.[IDLang]=f.[languageid]                              
                           AND [Traineeattemexam] = @candidateattemexam  
                           AND c.[disquestype] = 'SALMON'   
          and a.TraineeID=@traineeId  
  
         end  
GO



