/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_Educyte_TraineeResume */
/****** Object:  StoredProcedure [dbo].[Proc_EDUCYTE_DownloadResumefile]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Proc_EDUCYTE_DownloadResumefile 'ANINDYA BHATTACHARYA_6501'
CREATE Proc [dbo].[Proc_EDUCYTE_DownloadResumefile]  
@traineeid nvarchar(max)   
  
AS  
BEGIN  
DECLARE @ResumeContentType nvarchar(max)

select @ResumeContentType =  ResumeContentType
from tbl_Educyte_TraineeResume  
where TraineeID = @traineeid  

if (@ResumeContentType = '.pdf')
begin  
select TraineeID,ReportresumePath,ResumeFileData as ResumeFileData,ResumeFileName,ResumeContentType from tbl_Educyte_TraineeResume  
where TraineeID = @traineeid  
  
END
ELSE
BEGIN
select TraineeID,ReportresumePath as ReportresumePath,ResumeFileData,ResumeFileName,ResumeContentType from tbl_Educyte_TraineeResume  
where TraineeID = @traineeid
END 
END
GO



