CREATE proc [dbo].[proc_EDUCYTE_downloaduploadeddocuments]  
@username nvarchar(max),  
@docid int  
as  
    DECLARE @traineeid NVARCHAR(max)  
begin  
 
Select @traineeid=TraineeID
from tbl_EDUCYTE_Trainee_SignupDtls 
where UserEmail=@username  
 
 
  
 Select uploadedfilename,  
        uploadedfiletype,  
     uploadedfile  
     from tbl_EDUCYTE_UploadDocuments  
     where TraineeID=@traineeid  
     and docid=@docid  
     and deleteflag='No'  
end
GO



