-- proc_EDUCYTE_driscoldtls 'Selecttypewisecandidate', 2,'EDUCYTETEST_2610'           
/****** Script for SelectTopNRows command from SSMS  ******/             
CREATE PROC  [dbo].[proc_EDUCYTE_driscoldtls] @action             VARCHAR(100)=NULL,             
                                 @phytypeid          INT=NULL,             
                                 @postname           VARCHAR(500)=NULL,             
                                 @deptname           VARCHAR(500)=NULL,             
                                 @Traineeattemexam INT=NULL,            
                                 @traineeId NVARCHAR(MAX)=NULL,             
                                 @Driscolallow       VARCHAR(200)=NULL,             
                                 @Message            VARCHAR(200)=NULL             
AS             
    DECLARE @Useremail Nvarchar(max)             
    DECLARE @canDriscolallow VARCHAR(200)             
            
  BEGIN           
  if(@phytypeid is null or @phytypeid=0)          
  begin          
  set          
  @phytypeid=null          
  end          
  if(@postname is null or @postname='0')          
  begin          
  set          
  @postname=null          
  end          
  if(@traineeId is null or @traineeId='0')          
  begin          
  set          
  @traineeId=null          
  end          
      SELECT @Useremail = UserEmail             
      FROM   [dbo].[tbl_Educyte_PersonalDetails]             
      WHERE  TraineeID = @traineeId             
            
              
            
            
      IF @action = 'Selecttypewisecandidate'             
        BEGIN             
                      
            
        SELECT Distinct [IDTrainee],             
                           [TraineeName],             
                           [typename]             
            FROM   (SELECT c.[TraineeID] as IDTrainee,             
                     (A.FirstName +'' + Isnull(A.MiddleName,'') +'' +   A.LastName) as TraineeName,             
                           CASE             
                             WHEN Driscolallow = 'Completed' THEN 1             
                             WHEN Driscolallow = 'Reschedule' THEN 1             
        WHEN Driscolallow = 'Yes' THEN 10            
                             ELSE Driscolallow             
                           END Driscolallow,             
                           CASE             
                             WHEN conflictallow = 'Completed' THEN 2             
                             WHEN conflictallow = 'Reschedule' THEN 2             
        WHEN conflictallow = 'Yes' THEN 10            
                             ELSE conflictallow             
                           END conflictallow,             
                           CASE             
                             WHEN iqallow = 'Completed' THEN 3             
                             WHEN iqallow = 'Reschedule' THEN 3             
        WHEN iqallow = 'Yes' THEN 10            
                             ELSE iqallow             
                           END iqallow,             
                           CASE             
                             WHEN eqallow = 'Completed' THEN 4             
                             WHEN eqallow = 'Reschedule' THEN 4             
        WHEN eqallow = 'Yes' THEN 10            
                             ELSE eqallow             
                           END eqallow             
      
    
                    FROM   [tbl_Educyte_PersonalDetails] a ,[dbo].[tbl_EDUCYTE_Trainee_SignupDtls] c            
                             
                    WHERE              
       Driscolallow IN ( 'Completed', 'Reschedule' )             
                                        
       and a.TraineeID=c.TraineeID            
      ) a,             
                   [dbo].[trecuitpsycycotesttype] b             
            WHERE  a.Driscolallow = Cast(b.[id] AS VARCHAR)             
                   AND  (@phytypeid is null or b.id = @phytypeid) 
				   AND  (@traineeId is null or a.IDTrainee = @traineeId) 
				   
                
       union            
        SELECT Distinct [IDTrainee],             
                           [TraineeName] ,             
                           [typename]            
            FROM   (SELECT c.[TraineeID] as IDTrainee,             
                     (A.FirstName +'' + Isnull(A.MiddleName,'') +'' +   A.LastName) as TraineeName,              
                           CASE             
                             WHEN Driscolallow = 'Completed' THEN 1             
                             WHEN Driscolallow = 'Reschedule' THEN 1             
        WHEN Driscolallow = 'Yes' THEN 10            
                             ELSE Driscolallow             
                           END Driscolallow,             
                           CASE             
                             WHEN conflictallow = 'Completed' THEN 2             
                             WHEN conflictallow = 'Reschedule' THEN 2             
        WHEN conflictallow = 'Yes' THEN 10            
                             ELSE conflictallow             
                           END conflictallow,             
                           CASE             
                             WHEN iqallow = 'Completed' THEN 3             
                             WHEN iqallow = 'Reschedule' THEN 3             
        WHEN iqallow = 'Yes' THEN 10            
                             ELSE iqallow             
                           END iqallow,             
                           CASE             
                             WHEN eqallow = 'Completed' THEN 4             
                             WHEN eqallow = 'Reschedule' THEN 4             
        WHEN eqallow = 'Yes' THEN 10            
                             ELSE eqallow             
                           END eqallow             
       
    
                    FROM   [tbl_Educyte_PersonalDetails] a,[dbo].[tbl_EDUCYTE_Trainee_SignupDtls] c    
             
            
                    WHERE              
                                       
                             conflictallow IN ( 'Completed', 'Reschedule' )        
                                        
       and a.TraineeID=c.TraineeID            
      ) a,             
                   [dbo].[trecuitpsycycotesttype] b             
            WHERE  a.conflictallow= Cast(b.[id] AS VARCHAR)             
                    AND  (@phytypeid is null or b.id = @phytypeid)   
					  AND  (@traineeId is null or a.IDTrainee = @traineeId) 
     
