      IF @action = 'Selectquesans'             
        BEGIN             
            SELECT [disquestype],             
                   [quesserialno],             
                   [question],             
                   f.[answer]             
            FROM   [tbl_EDUCYTE_Driscoltraineedtls] a,             
                   [dbo].[trecruitdiscrolqusdtls] b,             
                   [dbo].[trecruitdiscrolquestype] c,             
                   [dbo].[trecruitdiscrolansdtls]f,             
                   [dbo].[tbl_Educyte_PersonalDetails] d,             
                   [dbo].[tbl_EDUCYTE_Language]e             
            WHERE  a.[IDLang] = b.[languageid]             
                   AND a.[questionid] = b.[quesserialno]             
                   AND b.[disquestypeid] = c.[id]             
                AND a.[TraineeID] = d.[TraineeID]             
                   AND a.[IDLang] = e.[id]             
                   AND a.AnswerID = f.number             
                   AND a.[IDLang] = f.[languageid]             
                   AND a.TraineeID = @traineeid             
                   AND [traineeattemexam] = @Traineeattemexam             
            ORDER  BY [quesserialno]             
        END             
            
      IF @action = 'Reschedule'             
        BEGIN             
            --SELECT @canDriscolallow = [Driscolallow]             
        --FROM   [Recruitment].[dbo].[trecruittraker]             
            --WHERE  a.TraineeID = @traineeid              
            --GROUP  BY [Driscolallow],             
            --          [conflictallow],             
            --          [iqallow],             
            --          [eqallow]             
            
   SELECT @canDriscolallow = [Driscolallow]             
            FROM   [dbo].[tbl_Educyte_PersonalDetails]            
            WHERE  TraineeID = @traineeid              
            GROUP  BY [Driscolallow],             
                      [conflictallow],             
                      [iqallow],             
                      [eqallow]             
            
                         
            IF @canDriscolallow = 'Completed'             
              BEGIN             
                  UPDATE [tbl_Educyte_PersonalDetails]             
                  SET    [Driscolallow] = 'Reschedule'             
                  WHERE  TraineeID = @traineeid              
              END             
            ELSE             
              BEGIN             
                  SET @message=1             
              END             
        END             
            
      IF @action = 'SELECTEXAMNO'             
    BEGIN             
            SELECT [attemexam],             
                   CASE             
                     WHEN [attemexam] = 1 THEN Cast('1st Exam' AS VARCHAR)             
                     WHEN [attemexam] = 2 THEN Cast('2nd Exam'AS VARCHAR)             
                     WHEN [attemexam] = 3 THEN Cast('3rd Exam'AS VARCHAR)             
                     ELSE Cast([attemexam]AS VARCHAR) + '' + 'th Exam'             
                   END [attemexamtext]             
            FROM   [tbl_EDUCYTE_Driscoltrainee_examdtls]             
            WHERE  TraineeID = @traineeid              
                   AND finalsubmit = 'Yes'             
            ORDER  BY [attemexam]             
        END             
            
      IF @action = 'Selecttypewisetotalno'             
        BEGIN             
            SELECT c.[disquestype],             
                   a.questionid,             
                   a.AnswerID,             
                   totscore             
            FROM   [tbl_EDUCYTE_Driscoltraineedtls] a,             
                   [dbo].[trecruitdiscrolqusdtls] b,             
                   [dbo].[trecruitdiscrolquestype] c,             
                   [dbo].[trecruitdiscrolansdtls]f,             
                   [dbo].[tbl_Educyte_PersonalDetails] d,             
                   [dbo].[languages]e,             
                  (SELECT c.[disquestype],             
                           Sum (a.AnswerID)totscore             
                    FROM   [tbl_EDUCYTE_Driscoltraineedtls] a,             
                           [dbo].[trecruitdiscrolqusdtls] b,             
                           [dbo].[trecruitdiscrolquestype] c,             
                           [dbo].[trecruitdiscrolansdtls]f,             
                           [dbo].[tbl_Educyte_PersonalDetails] d,             
                           [dbo].[tbl_EDUCYTE_Language]e             
                    WHERE  a.[IDLang] = b.[languageid]             
                           AND a.[questionid] = b.[quesserialno]             
                           AND b.[disquestypeid] = c.[id]             
                           AND a.[TraineeID] = d.[TraineeID]             
                           AND a.[IDLang] = e.[id]     
                            AND a.AnswerID = f.[number]            
         and a.[IDLang]=f.[Languageid]               
                           AND a.TraineeID = @traineeid              
                           AND [traineeattemexam] = @Traineeattemexam             
                    GROUP  BY c.[disquestype]) z             
            WHERE  a.[IDLang] = b.[languageid]             
                   AND a.[questionid] = b.[quesserialno]             
                   AND b.[disquestypeid] = c.[id]             
                   AND a.[TraineeID] = d.[TraineeID]             
                   AND a.[IDLang] = e.[id]             
                    AND a.AnswerID = f.[number]            
     and a.[IDLang]=f.[Languageid]               
                   AND a.TraineeID = @traineeid              
                   AND [Traineeattemexam] = @Traineeattemexam             
                   AND c.[disquestype] = z.[disquestype]             
            ORDER  BY [disquestype]             
        END             
            
      IF @action = 'Discrolgraph'             
        BEGIN             
            SELECT ( d.totscore * 1.363636 ) TIGERfinalscore,             
                   ( a.totscore * 2 )        CHAMELEONfinalscore,             
                   ( e.totscore * 2.1428 )   TURTLEfinalscore,             
                   ( b.totscore * 1.363636 ) EAGLEfinalscore,             
                   ( a.totscore * 2 )        SALMONfinalscore             
            FROM   (SELECT c.[disquestype],             
                           a.TraineeID,             
                           Sum (a.AnswerID)totscore             
                    FROM  [tbl_EDUCYTE_Driscoltraineedtls] a,             
                           [dbo].[trecruitdiscrolqusdtls] b,             
                           [dbo].[trecruitdiscrolquestype] c,             
                           [dbo].[trecruitdiscrolansdtls]f,             
                           [dbo].[tbl_Educyte_PersonalDetails] d,             
                           [dbo].[languages]e             
                    WHERE  a.[IDLang] = b.[Languageid]             
                           AND a.[questionid] = b.[quesserialno]             
                           AND b.[disquestypeid] = c.[id]             
                           AND a.[TraineeID] = d.[TraineeID]             
                           AND a.[IDLang] = e.[id]             
                            AND a.AnswerID = f.[number]            
         and a.[IDLang]=f.[languageid]                
                           AND a.TraineeID = @traineeid              
                           AND [Traineeattemexam] = @Traineeattemexam             
                           AND c.[disquestype] = 'CHAMELEON'             
                    GROUP  BY c.[disquestype],             
                              a.TraineeID) a,             
                   (SELECT c.[disquestype],             
                           a.TraineeID,             
                           Sum (a.answerID)totscore             
                    FROM   [tbl_EDUCYTE_Driscoltraineedtls] a,             
                           [dbo].[trecruitdiscrolqusdtls] b,             
                           [dbo].[trecruitdiscrolquestype] c,             
 [dbo].[trecruitdiscrolansdtls]f,             
                           [dbo].[tbl_Educyte_PersonalDetails] d,             
                           [dbo].[tbl_EDUCYTE_Language] e             
                    WHERE  a.[IDLang] = b.[Languageid]             
                           AND a.[questionid] = b.[quesserialno]             
                           AND b.[disquestypeid] = c.[id]             
                           AND a.[TraineeID] = d.[TraineeID]             
                           AND a.[IDLang] = e.[id]             
                            AND a.AnswerID = f.[number]            
         and a.[IDLang]=f.[Languageid]               
                           AND a.TraineeID = @traineeid              
                           AND [Traineeattemexam] = @Traineeattemexam             
                           AND c.[disquestype] = 'EAGLE'             
                    GROUP  BY c.[disquestype],             
                              a.TraineeID) b,             
                   (SELECT c.[disquestype],             
                           a.TraineeID,             
                           Sum (a.AnswerID)totscore             
                    FROM   [tbl_EDUCYTE_Driscoltraineedtls] a,             
                           [dbo].[trecruitdiscrolqusdtls] b,             
                           [dbo].[trecruitdiscrolquestype] c,             
                           [dbo].[trecruitdiscrolansdtls]f,             
                           [dbo].[tbl_Educyte_PersonalDetails] d,             
                           [dbo].[tbl_EDUCYTE_Language] e             
                    WHERE  a.[IDLang] = b.[Languageid]             
                           AND a.[questionid] = b.[quesserialno]             
                           AND b.[disquestypeid] = c.[id]             
                           AND a.[TraineeID] = d.[TraineeID]             
                           AND a.[IDLang] = e.[id]             
                            AND a.AnswerID = f.[number]            
         and a.[IDLang]=f.[languageid]               
                           AND a.TraineeID = @traineeid              
                           AND [Traineeattemexam] = @Traineeattemexam             
                           AND c.[disquestype] = 'SALMON'             
                    GROUP  BY c.[disquestype],             
                              a.TraineeID) c,             
    (SELECT c.[disquestype],             
                           a.TraineeID,             
                           Sum (a.AnswerID)totscore             
                    FROM   [tbl_EDUCYTE_Driscoltraineedtls] a,             
                           [dbo].[trecruitdiscrolqusdtls] b,             
                           [dbo].[trecruitdiscrolquestype] c,             
                           [dbo].[trecruitdiscrolansdtls]f,             
                           [dbo].[tbl_Educyte_PersonalDetails] d,             
                           [dbo].[tbl_EDUCYTE_Language]e             
                    WHERE  a.[IDLang] = b.[Languageid]             
                           AND a.[questionid] = b.[quesserialno]             
                           AND b.[disquestypeid] = c.[id]             
                           AND a.[TraineeID] = d.[TraineeID]             
                           AND a.[IDLang] = e.[id]             
                            AND a.AnswerID = f.[number]            
         and a.[IDLang]=f.[languageid]               
                           AND a.TraineeID = @traineeid              
                           AND [Traineeattemexam] = @Traineeattemexam             
                           AND c.[disquestype] = 'TIGER'             
                    GROUP  BY c.[disquestype],             
                              a.TraineeID) d,             
                   (SELECT c.[disquestype],             
                           a.TraineeID,             
                           Sum (a.AnswerID)totscore             
                    FROM   [tbl_EDUCYTE_Driscoltraineedtls] a,             
                           [dbo].[trecruitdiscrolqusdtls] b,             
                           [dbo].[trecruitdiscrolquestype] c,             
    [dbo].[trecruitdiscrolansdtls]f,             
                           [dbo].[tbl_Educyte_PersonalDetails] d,             
                           [dbo].[tbl_EDUCYTE_Language] e             
                    WHERE  a.[IDLang] = b.[languageid]             
                           AND a.[questionid] = b.[quesserialno]             
                           AND b.[disquestypeid] = c.[id]             
                           AND a.[TraineeID] = d.[TraineeID]             
              AND a.[IDLang] = e.[id]             
                            AND a.AnswerID = f.[number]            
         and a.[IDLang]=f.[languageid]               
                           AND a.TraineeID = @traineeid              
                           AND [Traineeattemexam] = @Traineeattemexam             
                           AND c.[disquestype] = 'TURTLE'             
                    GROUP  BY c.[disquestype],             
                              a.TraineeID) e             
            WHERE  a.TraineeID = b.TraineeID             
                   AND a.TraineeID = c.TraineeID             
                   AND a.TraineeID = d.TraineeID             
                   AND a.TraineeID = e.TraineeID             
        END             
            
      IF @action = 'Activeinactiveresbutton'             
        BEGIN             
            SELECT             
                   a.[Driscolallow]             
            FROM   [dbo].[tbl_Educyte_PersonalDetails] a                            
            WHERE a.TraineeID = @traineeid              
        END             
  END 
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: trecruitdiscrolqusdtls */
