SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Proc_Educyte_DriscoleGetQues]
@LangId INT

AS
BEGIN

Select A.quesserialno as IDques,A.question,A.disquestypeid 
from trecruitdiscrolqusdtls A
Where A.languageid = @LangId
END
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_EmpExperienced, tbl_EDUCYTE_EmpSalesExp, tbl_EDUCYTE_YearlyCTC */
/****** Object:  StoredProcedure [dbo].[Proc_EDUCYTE_EmpExpdtlsforhrms]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Proc_EDUCYTE_EmpExpdtlsforhrms]  
@traineeid  NVARCHAR(MAX) ,   
@action nvarchar(max)   
   
        
AS        
BEGIN        
        
If(@action = 'EmpExpdetails')        
Begin        
        
Select A.ID,A.TraineeID,A.UserEmail,A.EmployerName,A.DurationForm,A.DurationTo,A.Designation,B.YearlyCtc,A.YearlyCtcID as CTCID,A.CreatedBy        
        
from tbl_EDUCYTE_EmpExperienced A        
Left join tbl_EDUCYTE_YearlyCTC B ON A.YearlyCtcID=B.ID        
Where A.TraineeID = @traineeid    
END       
      
IF(@action = 'EmpSalesExpDeatils')      
begin      
Select A.ID,A.TraineeID,A.UserEmail,A.EmployerName,A.Designation,A.DurationForm,A.DurationTo,      
B.YearlyCtc,A.YearlyCTCID ,A.AreaCoveredHQBranch,A.MajorStockists1,A.MajorStockists2,      
A.MajorStockists3,A.StockistLocation1,A.StockistLocation2,A.StockistLocation3,      
A.Stockist1ContactNo,A.Stockist2ContactNo,A.Stockist3ContactNo,      
A.SalesReferenceName,A.SalesReferenceDesignation,A.SalesReferenceContactNo,A.SalesReasonForLeaving,      
A.DrivingLicenseNo,A.CreatedBy      
      
from tbl_EDUCYTE_EmpSalesExp A      
Left join tbl_EDUCYTE_YearlyCTC B ON A.YearlyCTCID=B.ID      
Where A.TraineeID = @traineeid    
      
END       
        
END  
GO



