-- proc_EDUCYTE_EQmasdtls 'EQcandidatelanguagemap' ,'mega.dhar@iecsl.co.in'   
CREATE PROC [dbo].[proc_EDUCYTE_EQmasdtls]      @action           NVARCHAR(100)=NULL,     
                                      @conquestype      NVARCHAR(100)=NULL,     
                                      @username         NVARCHAR(MaX)=NULL,     
                                      @activeflag       NVARCHAR(10)=NULL,     
                                      @conquestypeid    INT=NULL,     
                                      @languageid       INT=NULL,     
                                      @question         NVARCHAR(max)=NULL,     
                                      @questiondtlsid   INT=NULL,     
                                      @answer           NVARCHAR(max)=NULL,     
                                      @number           INT=NULL,     
                                      @answerdtlsid     INT=NULL,     
                                      @quesserialnonext INT=NULL,     
                                      @ollanguageid     INT=NULL,     
                                      @olquesserialno   INT=NULL,     
                                      @message          VARCHAR(500)=NULL output     
AS     
    DECLARE @empcode VARCHAR(100)     
    DECLARE @traineeid  NVARCHAR(MaX)     
    DECLARE @anslanguageid INT     
    DECLARE @queslanguageid INT     
    DECLARE @countexamques INT     
    DECLARE @countexamattm INT     
    DECLARE @countexamattques INT     
    DECLARE @quesserialno INT     
    DECLARE @maplanid INT     
    DECLARE @countexamattmcan INT     
    DECLARE @findques INT     
    DECLARE @idd INT     
    DECLARE @attemptno INT     
    DECLARE @cattemptno INT     
    DECLARE @atteptestno INT     
 DECLARE @quesset INT     
    DECLARE @aquesset INT     
    DECLARE @createdtime DATETIME     
    DECLARE @cancreatedtime DATETIME     
    DECLARE @orquesserialno INT     
    DECLARE @canquesset INT     
 DECLARE @sRanquesserialno int    
 declare @empno int         ---ishita    
    
    
  BEGIN     
    
      set @languageid=5    
   set @maplanid=5    
 set @canquesset = 1
    
    
    
      SELECT @traineeid = TraineeID     
      FROM  [dbo].[tbl_EDUCYTE_Trainee_SignupDtls]     
      WHERE  [UserEmail] = @username     

   SELECT @cancreatedtime = Max([createddate])     
      FROM   [dbo].[tbl_Educyte_eqrandomques] p     
         
     
     SELECT @canquesset = quesset     
      FROM   [dbo].[tbl_Educyte_eqrandomques] p     
      WHERE   createddate = @cancreatedtime  
     
                
    
      IF @canquesset = 1     
        BEGIN     
            SET @aquesset=@canquesset + 1     
        END     
      ELSE IF @canquesset = 2     
       BEGIN     
            SET @aquesset=@canquesset + 1     
      END     
      ELSE IF @canquesset = 3     
       BEGIN     
           SET @aquesset=@canquesset-2     
       END     
    
       
  
      SELECT @countexamques = Count([question])     
      FROM   [dbo].[trecruiteqquesdtls]    
      WHERE  [languageid] = 5     
   AND [queslanset] = @canquesset     
    
   SELECT @countexamattm = [attemexam]     
            FROM   [dbo].[tbl_Educyte_eqexamdtls]     
            WHERE  [TraineeID] = @traineeid     
                   AND finalsubmit <> 'Yes'     
    
      SELECT @quesserialno = Min([ranquesserialno])     
      FROM   [dbo].[trecruiteqquesdtls] p     
      WHERE  languageid = 5                
     AND [queslanset] = @canquesset     
    
    
     SELECT @orquesserialno = [quesserialno]     
      FROM   [dbo].[trecruiteqquesdtls] ans     
      WHERE  [queslanset] = @canquesset     
             AND [ranquesserialno] = @questiondtlsid     
    
      SELECT @findques = Count(questionid)     
      FROM   [dbo].[tbl_Educyte_eqtraineedtls]     
      WHERE  TraineeID = @traineeid     
             AND questionid = @orquesserialno     
             AND [quesfinalsubmitques] IS NULL     
    
    
      IF @action = 'EQcandidatelanguagemap'     
        BEGIN     
            DELETE FROM [dbo].[tbl_Educyte_eqcanlanguagemap]    
            WHERE  TraineeID = @traineeid     
    
            INSERT INTO [dbo].[tbl_Educyte_eqcanlanguagemap]     
                        ([TraineeID],     
      [UserEmail],  
                         [languageid])     
            VALUES      (@traineeid,    
                 @username,  
                         5)     
        INSERT INTO [dbo].[tbl_Educyte_eqrandomques]     
                        (TraineeID,  
      UserEmail,  
      [languageid],     
                         [quesset],     
                         [createddate]     
                         )     
            VALUES      (  
                @traineeid,  
       @username,  
                @languageid,     
                         @aquesset,     
                         Getdate()  )     
    
       SELECT @maplanid = languageid     
            FROM   [dbo].[tbl_Educyte_eqcanlanguagemap] p     
            WHERE  TraineeID = @traineeid     
    
      SELECT @countexamques = Count([question])     
      FROM   [dbo].[trecruiteqquesdtls]     
       WHERE  [languageid] = @maplanid     
        AND [queslanset] = @canquesset     
    
      
    
            SELECT @attemptno = Count([attemexam])     
            FROM  [dbo].[tbl_Educyte_eqexamdtls]     
            WHERE  [finalsubmit] = 'Yes'     
                   AND TraineeID = @traineeid     
    
            DELETE FROM  [dbo].[tbl_Educyte_eqtraineedtls]     
            WHERE  [quesfinalsubmitques] IS NULL     
                   AND TraineeID = @traineeid     
    
            DELETE FROM  [dbo].[tbl_Educyte_eqexamdtls]     
            WHERE  [finalsubmit] = 'No'     
                   AND TraineeID = @traineeid     
    
            INSERT INTO [dbo].[tbl_Educyte_eqexamdtls]     
                        ([TraineeID],  
        UserEmail,  
                         [languageid],     
                         [totalques],     
                         [attemques],     
                         [finalsubmit],     
                         [attemexam])     
            VALUES      ( @traineeid,   
                 @username,  
                          5,     
                          @countexamques,     
                          null,     
                          'No',     
                          @attemptno + 1 )     
        END     
    
      IF @action = 'EQquesansselect'     
        BEGIN     
    
   SELECT @orquesserialno=[quesserialno]          
  FROM [trecruiteqquesdtls]    
  where [Queslanset]=@canquesset and [Ranquesserialno]=@quesserialno    
    
    
             SELECT previousvalue,                       
                   ranquesserialno quesserialno,     
                   question,     
                   nextvalue,                        
                   noofques ,    
       quescount noofoption    
            FROM   (SELECT Lag(p.ranquesserialno)     
                             OVER (     
                               ORDER BY p.[ranquesserialno]) PreviousValue,     
                           Lag(p.question)     
                             OVER (     
                               ORDER BY p.[ranquesserialno]) PreviousValueques,     
                           p.ranquesserialno,     
                           p.question,     
         p.[quesserialno],    
                           Lead(p.ranquesserialno)     
                             OVER (     
                               ORDER BY p.[ranquesserialno]) NextValue,     
                           Lead(p.question)     
                             OVER (     
                               ORDER BY p.[ranquesserialno]) NextValueques,     
                           languageid     
                    FROM   [trecruiteqquesdtls] p     
       WHERE  languageid = 5                              
                           AND [queslanset] = @canquesset)s,     
                   (SELECT languageid,     
                           Count([quesserialno])noofques     
                    FROM   [trecruiteqquesdtls]     
                    WHERE  languageid = 5                                
                           AND [queslanset] = @canquesset    
                    GROUP  BY languageid) p ,(SELECT questionno,count([answerno])quescount    
          
                 FROM  [trecruiteqansmarks]    
                             where questionno=@orquesserialno     
                              group by questionno)w    
            WHERE  ranquesserialno = @quesserialno     
                   AND p.languageid = s.languageid     
        END     
    
      IF @action = 'EQquesansselectnext'     
        BEGIN     
             SELECT @orquesserialno=[quesserialno]    
          
  FROM  [dbo].[trecruiteqquesdtls]    
  where [Queslanset]=@canquesset and [Ranquesserialno]=@quesserialnonext    
    
         
            SELECT previousvalue,     
                        
                   ranquesserialno quesserialno,     
                   question,     
                   nextvalue,     
                       
                   noofques,     
       quescount noofoption,    
                   CASE     
                     WHEN x.TraineeID IS NULL THEN '0'     
                     ELSE x.TraineeID     
                   END             TraineeID,     
                   CASE     
                     WHEN x.[answer] IS NULL THEN 0     
                     ELSE x.[answer]     
                   END             answer,     
                   CASE     
                     WHEN y.[attemques] BETWEEN 1 AND 100 THEN y.[attemques]     
                     ELSE y.[attemques]     
                   END             [attemques]     
            FROM   (SELECT Lag(p.ranquesserialno)     
                             OVER (     
                               ORDER BY p.[ranquesserialno]) PreviousValue,     
                           Lag(p.question)     
                             OVER (     
                               ORDER BY p.[ranquesserialno]) PreviousValueques,     
                           p.ranquesserialno,     
                           p.quesserialno,     
                           p.question,     
                           Lead(p.ranquesserialno)     
                             OVER (     
                               ORDER BY p.[ranquesserialno]) NextValue,     
                           Lead(p.question)     
                             OVER (     
                               ORDER BY p.[ranquesserialno]) NextValueques,     
                           languageid     
                    FROM   [Recruitment].[dbo].[trecruiteqquesdtls] p     
                    WHERE  languageid = 5     
                               
                           AND [queslanset] = @canquesset)s     
                   LEFT OUTER JOIN     
                          [dbo].[tbl_Educyte_eqtraineedtls]     
                   x     
                                ON s.languageid = x.[languageid]     
                                   AND s.quesserialno = x.[questionid]     
                                   AND [quesfinalsubmitques] IS NULL     
                                   AND x.[TraineeID] = @TraineeID,     
                   (SELECT languageid,     
                           count([quesserialno])noofques     
                    FROM    [dbo].[trecruiteqquesdtls]     
                    WHERE  languageid = 5     
                               
                           AND [queslanset] = @canquesset     
                    GROUP  BY languageid) p, (SELECT questionno,count([answerno])quescount    
          
                 FROM     [dbo].[trecruiteqansmarks]    
                             where questionno=@orquesserialno    
                              group by questionno)w,    
                     [dbo].[tbl_Educyte_eqexamdtls] y     
            WHERE  ranquesserialno = @quesserialnonext     
                   AND p.languageid = s.languageid     
                   AND s.languageid = y.[languageid]     
                   AND y.[TraineeID] = @TraineeID     
                   AND [finalsubmit] = 'No'     
        END     
    
      IF @action = 'EQansselect'     
        BEGIN     
    
  SELECT @orquesserialno = [quesserialno]     
            FROM    [dbo].[trecruiteqquesdtls] ans     
            WHERE  [queslanset] = @canquesset     
                   AND [ranquesserialno] = @quesserialnonext     
    
            SELECT [answerno],     
                   [answer],     
                   language     
            FROM   [dbo].[trecruiteqansmarks] ans,     
                   [dbo].[languages] lan, [dbo].[trecruiteqquesdtls] qus     
            WHERE  ans.[languageid] = lan.[id]     
                   AND lan.[id] = 5    
       and ans.[questionno]=qus.[quesserialno]    
       and qus.[quesserialno]=@orquesserialno    
       and [queslanset] = @canquesset    
           
        END     
    
      IF @action = 'EQolquesansselect'     
        BEGIN     
         SELECT @orquesserialno = [quesserialno]     
            FROM   [dbo].[trecruiteqquesdtls] ans     
            WHERE  [queslanset] = @canquesset     
                   AND [ranquesserialno] = @questiondtlsid     
    
            SELECT [question]     
            FROM   [dbo].[trecruiteqquesdtls]     
            WHERE  languageid = 5    
                   AND ranquesserialno = @olquesserialno     
                   AND [queslanset] = @canquesset     
    
            SELECT [answerno],     
                   [answer]     
            FROM   [dbo].[trecruiteqansdtls] ans,    
                   [dbo].[trecruiteqquesdtls] qus     
            WHERE  ans.[languageid] = 5    
   and ans.[questionno]=qus.[quesserialno]    
   and qus.[quesserialno]=@orquesserialno    
        END     
    
   IF @action = 'EQfirstquesansselect'     
        BEGIN     
            
   SELECT @orquesserialno=[quesserialno]          
  FROM   [dbo].[trecruiteqquesdtls]    
  where [Queslanset]=@canquesset and [Ranquesserialno]=@quesserialno    
    
            SELECT [answerno],     
                   [answer]     
            FROM   [dbo].trecruiteqansmarks ans, [dbo].trecruiteqquesdtls  qus     
            WHERE  ans.[languageid] = 5    
   and ans.[questionno]=qus.[quesserialno]    
   and qus.[quesserialno]=@orquesserialno    
   AND [queslanset] = @canquesset     
        END     
         
    
      IF @action = 'EQcandtlsinsert'     
         AND @findques = 0     
        BEGIN     
            SELECT @countexamattm = [attemexam]     
            FROM   [dbo].[tbl_Educyte_eqexamdtls]     
            WHERE  [TraineeID] = @TraineeID     
                   AND finalsubmit <> 'Yes'     
    
            SELECT @countexamattmcan = Count([TraineeID])     
            FROM   [dbo].[tbl_Educyte_eqexamdtls]     
            WHERE  [TraineeID] = @TraineeID     
    
   SELECT @orquesserialno = [quesserialno]     
            FROM   [dbo].[trecruiteqquesdtls] ans     
            WHERE  [queslanset] = @canquesset     
                   AND [ranquesserialno] = @questiondtlsid     
    
           BEGIN     
                INSERT INTO  [dbo].[tbl_Educyte_eqtraineedtls]     
                            ([TraineeID],  
        UserEmail,  
                             exquesset,     
                             [Serialno],    
                             [languageid],     
                             [questionid],     
                             [answer],     
                             Traineeattemexam,     
                             [createdon],     
                             [updatedon])     
                VALUES      ( @TraineeID,    
                  @username,  
                              @canquesset,     
                              @questiondtlsid,    
                              @maplanid,     
                              @orquesserialno,     
                              @number,     
                              @countexamattm,     
                              Getdate(),     
           Getdate() )     
    
           SET @message='Answer Details Successfully Inserted'     
            END     
    
            SELECT @countexamattques = Count([questionid])     
            FROM   [dbo].[tbl_Educyte_eqtraineedtls]     
            WHERE  TraineeID = @traineeid     
                   AND answer <> 0     
                   AND quesfinalsubmitques IS NULL     
    
            IF @countexamattm IS NOT NULL     
              BEGIN     
                  UPDATE  [dbo].[tbl_Educyte_eqexamdtls]     
                  SET    [attemques] = [totalques] - @countexamattques     
                  WHERE  TraineeID = @traineeid     
                         AND finalsubmit = 'No'     
              END     
        END     
    
      IF @action = 'EQcandtlsinsert'     
         AND @findques > 0     
        BEGIN     
            SELECT @countexamattm = [attemexam]     
            FROM   [dbo].[tbl_Educyte_eqexamdtls]     
            WHERE  [TraineeID] = @TraineeID     
                   AND finalsubmit <> 'Yes'     
    
           SELECT @orquesserialno = [quesserialno]     
            FROM   [dbo].[trecruiteqquesdtls] ans     
            WHERE  [queslanset] = @canquesset     
                   AND [ranquesserialno] = @questiondtlsid     
    
            UPDATE  [dbo].[tbl_Educyte_eqtraineedtls]     
            SET    [answer] = @number,     
                   [updatedon] = Getdate()     
            WHERE  [TraineeID] = @TraineeID     
                   AND [questionid] = @orquesserialno      
                   AND [quesfinalsubmitques] IS NULL     
    
            SET @message='Answer Details Successfully Updated'     
    
            SELECT @countexamattques = Count([questionid])     
            FROM  [dbo].[tbl_Educyte_eqtraineedtls]     
            WHERE  TraineeID = @traineeid     
                   AND answer <> 0     
                   AND quesfinalsubmitques IS NULL     
    
            IF @countexamattm IS NOT NULL     
              BEGIN     
                  UPDATE [dbo].[tbl_Educyte_eqexamdtls]     
                  SET    [attemques] = [totalques] - @countexamattques     
                  WHERE  TraineeID = @traineeid     
                         AND finalsubmit = 'No'     
              END     
        END     
    
      IF @action = 'Finalsubmit'     
        BEGIN     
            UPDATE  [dbo].[tbl_Educyte_eqexamdtls]     
            SET    [finalsubmit] = 'Yes'     
            WHERE  TraineeID = @traineeid     
    
            UPDATE [dbo].[tbl_Educyte_PersonalDetails]     
            SET    [eqallow] = 'Completed'     
            WHERE  TraineeID = @traineeid     
    
    
   --UPDATE [essp].[dbo].[temppsychometrictestmapping]     
   --         SET    [EQTest] = 'Completed'         ------ishita    
   --         WHERE  empno = @empno    
    
    
            UPDATE [dbo].[tbl_Educyte_eqtraineedtls]     
            SET    [quesfinalsubmitques] = 'F'     
            WHERE  TraineeID = @traineeid     
        END     
    
      IF @action = 'Eqansqnoselect'     
        BEGIN     
            SELECT @atteptestno = [attemexam]     
            FROM   [dbo].[tbl_Educyte_eqexamdtls]     
            WHERE  [finalsubmit] = 'No'      
                   AND [TraineeID] = @TraineeID     
    
            SELECT [Serialno][questionid]     
            FROM   [dbo].[tbl_Educyte_eqtraineedtls]     
            WHERE  [answer] > 0     
                   AND [traineeattemexam] = @atteptestno     
                   AND [TraineeID] = @TraineeID     
        END     
    
  END 
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_Educyte_PersonalDetails, tbl_EDUCYTE_Trainee_SignupDtls */
/****** Object:  StoredProcedure [dbo].[Proc_EDUCYTE_ForgetPassword]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Proc_EDUCYTE_ForgetPassword 'megadharofficial@gmail.com','Changestatus'    
CREATE PROC [dbo].[Proc_EDUCYTE_ForgetPassword] @username VARCHAR(1000)      
 ,@action VARCHAR(100)      
 ,@status VARCHAR(10) = NULL OUTPUT      
AS      
DECLARE @traineeid Nvarchar(max)     
DECLARE @submitstatus VARCHAR(1000)      
DECLARE @canname Nvarchar(max)     
DECLARE @canpost VARCHAR(Max)  
DECLARE @Password VARCHAR(Max)  
 DECLARE @MailId varchar(200)      
 DECLARE @tableHTML NVARCHAR(MAX)    
BEGIN      
    
    
    
 SELECT @traineeid = [TraineeID]      
 FROM [dbo].[tbl_EDUCYTE_Trainee_SignupDtls]      
 WHERE [UserEmail] = @username  
 
 SELECT @Password = [UserPassword]      
 FROM [dbo].[tbl_EDUCYTE_Trainee_SignupDtls]      
 WHERE [UserEmail] = @username 
      
 SELECT @submitstatus = Applicationsubmit    
 FROM [dbo].[tbl_Educyte_PersonalDetails]      
 WHERE TraineeID = @traineeid      
      
 SELECT @canname= UserFullName     
 FROM [dbo].[tbl_EDUCYTE_Trainee_SignupDtls]      
 WHERE TraineeID = @traineeid     
        
 SELECT @canpost = UserPostName    
 FROM [dbo].[tbl_EDUCYTE_Trainee_SignupDtls]      
 WHERE TraineeID = @traineeid     
    
      

    
      
 IF @action = 'Changestatus'      
 BEGIN      
    
      
SET @tableHTML = '<!DOCTYPE html>
<html>
<head>
  <style>
    table {
      font-size: 20px;
      font-family: Tahoma;
    }
  </style>
</head>
<body>
  <table>      
    <tr>      
      <td>Dear '+ @canname +',</td>      
    </tr>      
    <tr>      
      <td>We received a request to reset your password. Here is your password:</td>      
    </tr>      
    <tr>      
      <td><b>Password:</b>    ' + @Password + '</td>      
    </tr>      
    <tr>      
      <td>If you did not request this change, please ignore this email or contact our support team.</td>      
    </tr>      
    <tr>      
      <td>Thanks & Regards<br/><i>Mendine HR Team</i></td>      
    </tr>      
    <tr>      
      <td><br/><a href="https://educyte.in/Forms/StudentPortal">Click Here to Login to Educyte Portal</a></td>      
    </tr>      
  </table>
</body>
</html>';
     
    
     
   SELECT @MailId=[UserEmail]            
  FROM [dbo].[tbl_EDUCYTE_Trainee_SignupDtls]      
  where TraineeID = @traineeid      

      
 EXEC msdb.dbo.sp_send_dbmail      
    @profile_name = 'Mendine_Recruitment_Profile'      
   ,@recipients = @MailId      
   ,@subject = 'Forget Password'      
   ,@body = @tableHTML      
   ,@importance ='HIGH'      
   ,@body_format = 'HTML'      
      
 END      
END 
GO



