/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_EducationalDeatils, tbl_EDUCYTE_EmpExperienced, tbl_EDUCYTE_EmpSalesExp, tbl_EDUCYTE_FamilyDetails, tbl_EDUCYTE_Gender, tbl_EDUCYTE_GetEmploymentOtherDetails, tbl_EDUCYTE_LanguageDetails, tbl_EDUCYTE_MaritalStatus, tbl_EDUCYTE_Nationality, tbl_EDUCYTE_OtherDetails, tbl_Educyte_PersonalDetails, tbl_EDUCYTE_Reference, tbl_EDUCYTE_ReferredUs, tbl_EDUCYTE_Religion, tbl_Educyte_TraineeImage, tbl_Educyte_TraineeResume, tbl_EDUCYTE_YearlyCTC, trecruitboards, trecruitcountrycode, trecruiteducation */
/****** Object:  StoredProcedure [dbo].[Proc_Educyte_Get_AllDetails]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  -- Proc_Educyte_Get_AllDetails 'demo@gmail.com'          
CREATE PROCEDURE [dbo].[Proc_Educyte_Get_AllDetails]             
@UserEmail Nvarchar(max)              
AS              
BEGIN              
              
Select A.TraineeID,                  
A.UserEmail,                  
A.PostName,                  
(A.FirstName +'' +                  
Isnull(A.MiddleName,'') +'' +                  
A.LastName) as TraineeName,                  
A.CurrentAddressLine1,                  
A.CurrentAddressLine2,                  
A.CurrentCityandVillage,                  
A.CurrentPostOffice,                  
A.CurrentPincode,                  
A.CurrentStateID,                
B.statename as Currentstatename,              
C.disname as Currentdisname,              
A.CurrentDistrictID,                  
A.CurrentandPermanentChecked,                  
A.PermanentAddressLine1,                  
A.PermanentAddressLine2,                  
A.PermanentCityandVillage,                  
A.PermanentPostOffice,                  
A.PermanentPincode,                  
A.PermanentStateID,                  
A.PermanentDistrictID,                
D.statename as Permanentstatename,              
E.disname as Permanentdisname,              
A.CountryCode,               
F.cname,              
A.ModileNo,                  
Convert(varchar,A.DateOfBirth,103) as DateOfBirth,                  
A.Age,                  
A.Gender,              
G.Gender As Gendername,              
A.MaritalStatus  ,               
H.Maritalstatus as  MaritalstatusName,              
A.Nationality,                 
I.NationalityName,              
A.Religion ,                  
J.Religion as ReligionName,              
A.CreatedBy ,            
K.ReportImagePath as ImagePath,            
K.ImageFileName ,          
L.ResumeFileName,          
L.ResumeFilePath ,        
Convert(varchar,A.CreatedTime,103) as applicationdate,        
--M.Fmember,        
--M.Relationship,        
--M.Occupation,        
--N.Language,        
--N.LRead,        
--N.LWrite,        
--N.LSpeak,        
--O.EducationID,P.eduname,O.BoardID,Q.bdname,                
--O.Specialization,O.YearOfPassing,O.InstituteName,O.Marksdivision,        
      
R.Othertrainingattended,        
R.OtherQualification,              
R.ComputerProficiency,        
R.ExtraCurriculamActivites,        
R.SpecialInterest,        
--S.EmployerName,        
--S.DurationForm,        
--S.DurationTo,        
--S.Designation,        
--T.YearlyCtc,        
--S.YearlyCtcID as CTCID,        
--U.EmployerName,        
--U.Designation,        
--U.DurationForm,        
--U.DurationTo,              
--V.YearlyCtc,        
--U.YearlyCTCID ,        
--U.AreaCoveredHQBranch,        
--U.MajorStockists1,        
--U.MajorStockists2,              
--U.MajorStockists3,        
--U.StockistLocation1,        
--U.StockistLocation2,        
--U.StockistLocation3,              
--U.Stockist1ContactNo,        
--U.Stockist2ContactNo,        
--U.Stockist3ContactNo,              
--U.SalesReferenceName,        
--U.SalesReferenceDesignation,        
--U.SalesReferenceContactNo,        
--U.SalesReasonForLeaving,              
--U.DrivingLicenseNo,        
X.Consideryourself,          
X.ReferredID ,          
Y.ReferredName,          
X.SpecifyOthers ,          
X.AadhaarNo ,          
X.PanCardNo ,          
X.Uanno ,          
X.EsicNo,          
X.Engagedbusiness,          
X.Physicaldisability,          
X.Interviewedforemploymentinthiscompany,          
X.Relativesorfriendsalreadyworking ,          
X.DischargedordismissedanyCompany,          
X.ConvictedincourtofLaw,  
X.LinkedinID,    
X.MotherName,    
X.FatherName,    
X.WhatsappContactno,   
X.Timerequiretojoin  ,      
X.Nameofbusniess,      
X.RelativeName,      
X.RelativeDesignation,      
X.Relation,      
X.Designationone,      
X.Designationtwo,      
X.Designationthree,      
X.Designationfour      
--W.Name as Referencename,W.Relation as Referencerelation,W.Address as Referenceaddress,W.MobileNo as Referencemobileno        
  from tbl_Educyte_PersonalDetails A      
LEFT JOIN trecruitstate B ON A.CurrentStateID=B.stateid              
LEFT JOIN trecrutdistrict C ON A.CurrentDistrictID=C.disid              
LEFT JOIN trecruitstate D ON A.PermanentStateID=D.stateid              
LEFT JOIN trecrutdistrict E ON A.PermanentDistrictID=E.disid              
LEFT JOIN trecruitcountrycode F ON A.CountryCode=F.codeid               
LEFT JOIN tbl_EDUCYTE_Gender G ON A.Gender=G.ID              
LEFT JOIN tbl_EDUCYTE_MaritalStatus H ON A.MaritalStatus=H.ID              
LEFT JOIN tbl_EDUCYTE_Nationality I ON A.Nationality=I.ID              
LEFT JOIN tbl_EDUCYTE_Religion J ON A.Religion=J.ID              
LEFT JOIN tbl_Educyte_TraineeImage K ON A.UserEmail = K.UserEmail            
LEFT JOIN tbl_Educyte_TraineeResume L ON A.UserEmail = L.UserEmail         
--LEFT JOIN tbl_EDUCYTE_FamilyDetails M ON A.UserEmail = M.UserEmail        
--LEFT JOIN tbl_EDUCYTE_LanguageDetails N ON A.UserEmail = N.UserEmail        
--LEFT JOIN tbl_EDUCYTE_EducationalDeatils O ON A.UserEmail = O.UserEmail        
--LEFT JOIN trecruiteducation P ON O.EducationID=P.eduid                
--LEFT JOIN trecruitboards Q ON O.BoardID=Q.bdid         
LEFT JOIN tbl_EDUCYTE_OtherDetails R ON A.UserEmail = R.UserEmail        
--LEFT JOIN tbl_EDUCYTE_EmpExperienced S ON  A.UserEmail = S.UserEmail        
--LEFT JOIN tbl_EDUCYTE_YearlyCTC T  ON S.YearlyCtcID=T.ID         
--LEFT JOIN tbl_EDUCYTE_EmpSalesExp U ON A.UserEmail = U.UserEmail        
--LEFT JOIN tbl_EDUCYTE_YearlyCTC V ON U.YearlyCTCID=V.ID          
LEFT JOIN tbl_EDUCYTE_GetEmploymentOtherDetails X ON A.UserEmail = X.UserEmail        
LEFT JOIN tbl_EDUCYTE_ReferredUs Y ON X.ReferredID=Y.ReferredID          
--LEFT JOIN tbl_EDUCYTE_Reference W ON  A.UserEmail = W.UserEmail        
Where A.UserEmail = @UserEmail              
END
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_Driscoltraineedtls, tbl_EDUCYTE_Language, tbl_Educyte_PersonalDetails, tdiscrolscoremappingChameleon, tdiscrolscoremappingEagle, tdiscrolscoremappingSalmon, tdiscrolscoremappingTiger, tdiscrolscoremappingTurtle, trecruitdiscrolansdtls, trecruitdiscrolquestype, trecruitdiscrolqusdtls */
/****** Object:  StoredProcedure [dbo].[proc_EDUCYTE_GET_disreport]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
      
CREATE PROC [dbo].[proc_EDUCYTE_GET_disreport]
 @traineeId NVARCHAR(MAX)=NULL ,   
@candidateattemexam INT=NULL       
                                   
AS       
      DECLARE @Useremail Nvarchar(max)       
    DECLARE @exquesset INT       
      
  BEGIN       
      SELECT @Useremail = UserEmail             
      FROM   [dbo].[tbl_Educyte_PersonalDetails]             
      WHERE  TraineeID = @traineeId          
      
      --SELECT @exquesset = exquesset       
      --FROM   (SELECT DISTINCT ( [exquesset] ) exquesset       
      --        FROM   tbl_EDUCYTE_Driscoltraineedtls       
      --        WHERE  [candidateattemexam] = @candidateattemexam       
      --               AND TraineeID = @TraineeID)a       
      
      SELECT [disquestype],       
             totscore score ,      
    CASE [disquestype]       
                  WHEN 'TIGER' THEN (Select  [scoreinmap] from [dbo].[tdiscrolscoremappingTiger] where [score]=totscore)      
                  WHEN 'CHAMELEON' THEN (Select  [scoreinmap] from [dbo].[tdiscrolscoremappingChameleon] where [score]=totscore)      
                  WHEN 'TURTLE' THEN (Select  [scoreinmap] from [dbo].[tdiscrolscoremappingTurtle] where [score]=totscore)      
                  WHEN 'EAGLE' THEN (Select  [scoreinmap] from [dbo].[tdiscrolscoremappingEagle] where [score]=totscore)      
                  WHEN 'SALMON' THEN (Select  [scoreinmap] from [dbo].[tdiscrolscoremappingSalmon] where [score]=totscore)      
                  ELSE [disquestype]       
                END totscore , Driscolallow      
      FROM   (SELECT c.[disquestype],       
                     (Sum (a.AnswerID))totscore ,d.Driscolallow      
              FROM   [dbo].[tbl_EDUCYTE_Driscoltraineedtls] a,       
                     [dbo].[trecruitdiscrolqusdtls] b,       
                     [dbo].[trecruitdiscrolquestype] c,       
                     [dbo].[trecruitdiscrolansdtls]f,       
                     [dbo].[tbl_Educyte_PersonalDetails] d,       
                     [dbo].[tbl_EDUCYTE_Language]e       
              WHERE  a.[IDLang] = b.[languageid]       
                     AND a.[questionid] = b.[quesserialno]       
                     AND b.[disquestypeid] = c.[id]       
                     AND a.[TraineeID] = d.[TraineeID]       
                     AND a.[IDLang] = e.[id]       
                     AND a.AnswerID = f.[number]       
                     AND a.[IDLang] = f.[languageid]       
                     AND a.TraineeID = @traineeId       
                     AND [Traineeattemexam] = @candidateattemexam       
                     AND c.[disquestype] = 'TIGER'       
                    -- AND b.[queslanset] = @exquesset       
              GROUP  BY c.[disquestype],       
                        a.TraineeID ,    
      d.Driscolallow    
              UNION       
              SELECT c.[disquestype],       
                     ( Sum (a.AnswerID))totscore , d.Driscolallow       
              FROM   [dbo].[tbl_EDUCYTE_Driscoltraineedtls] a,       
                     [dbo].[trecruitdiscrolqusdtls] b,       
                     [dbo].[trecruitdiscrolquestype] c,       
                     [dbo].[trecruitdiscrolansdtls]f,       
                     [dbo].[tbl_Educyte_PersonalDetails] d,       
                     [dbo].[tbl_EDUCYTE_Language]e       
              WHERE  a.[IDLang] = b.[languageid]       
                     AND a.[questionid] = b.[quesserialno]       
                     AND b.[disquestypeid] = c.[id]       
                     AND a.[TraineeID] = d.[TraineeID]       
                     AND a.[IDLang] = e.[id]       
                     AND a.AnswerID = f.[number]       
                     AND a.[IDLang] = f.[languageid]       
                     AND a.TraineeID = @traineeId      
                     AND [traineeattemexam] = @candidateattemexam       
                     AND c.[disquestype] = 'CHAMELEON'       
                    -- AND b.[queslanset] = @exquesset       
              GROUP  BY c.[disquestype],       
                        a.TraineeID ,    
      d.Driscolallow    
              UNION       
              SELECT c.[disquestype],                          ( Sum (a.AnswerID))totscore  ,d.Driscolallow     
              FROM   [dbo].[tbl_EDUCYTE_Driscoltraineedtls] a,       
                     [dbo].[trecruitdiscrolqusdtls] b,       
                     [dbo].[trecruitdiscrolquestype] c,       
              [dbo].[trecruitdiscrolansdtls]f,       
                     [dbo].[tbl_Educyte_PersonalDetails] d,       
                     [dbo].[tbl_EDUCYTE_Language]e       
              WHERE  a.[IDLang] = b.[languageid]       
                     AND a.[questionid] = b.[quesserialno]       
                     AND b.[disquestypeid] = c.[id]       
                     AND a.[TraineeID] = d.[TraineeID]       
                     AND a.[IDLang] = e.[id]       
                     AND a.AnswerID = f.[number]       
                     AND a.[IDLang] = f.[languageid]       
                     AND a.TraineeID = @traineeId     
                     AND [Traineeattemexam] = @candidateattemexam       
                     AND c.[disquestype] = 'TURTLE'       
                    -- AND b.[queslanset] = @exquesset       
              GROUP  BY c.[disquestype],       
                        a.TraineeID ,    
      d.Driscolallow    
              UNION       
              SELECT c.[disquestype],       
                     ( Sum (a.AnswerID))totscore  ,d.Driscolallow     
              FROM   [dbo].[tbl_EDUCYTE_Driscoltraineedtls] a,       
                     [dbo].[trecruitdiscrolqusdtls] b,       
                     [dbo].[trecruitdiscrolquestype] c,       
                     [dbo].[trecruitdiscrolansdtls]f,       
                     [dbo].[tbl_Educyte_PersonalDetails] d,       
                     [dbo].[tbl_EDUCYTE_Language]e       
              WHERE  a.[IDLang] = b.[languageid]       
                     AND a.[questionid] = b.[quesserialno]       
                     AND b.[disquestypeid] = c.[id]       
                     AND a.[TraineeID] = d.[TraineeID]       
                     AND a.[IDLang] = e.[id]       
                     AND a.AnswerID = f.[number]       
                     AND a.[IDLang] = f.[languageid]       
                     AND a.TraineeID = @traineeId     
                     AND [Traineeattemexam] = @candidateattemexam       
                     AND c.[disquestype] = 'EAGLE'       
                    -- AND b.[queslanset] = @exquesset       
              GROUP  BY c.[disquestype],       
                        a.TraineeID ,    
      d.Driscolallow    
              UNION       
              SELECT c.[disquestype],       
                     ( Sum (a.AnswerID))totscore  ,d.Driscolallow     
              FROM   [dbo].[tbl_EDUCYTE_Driscoltraineedtls] a,       
                     [dbo].[trecruitdiscrolqusdtls] b,       
                     [dbo].[trecruitdiscrolquestype] c,       
                     [dbo].[trecruitdiscrolansdtls]f,       
                     [dbo].[tbl_Educyte_PersonalDetails] d,       
                     [dbo].[tbl_EDUCYTE_Language]e       
              WHERE  a.[IDLang] = b.[languageid]       
                     AND a.[questionid] = b.[quesserialno]       
                     AND b.[disquestypeid] = c.[id]       
                     AND a.[TraineeID] = d.[TraineeID]       
                     AND a.[IDLang] = e.[id]       
                     AND a.AnswerID = f.[number]       
                     AND a.[IDLang] = f.[languageid]       
                     AND a.TraineeID = @traineeId         
                     AND [Traineeattemexam] = @candidateattemexam       
                     AND c.[disquestype] = 'SALMON'       
                    -- AND b.[queslanset] = @exquesset       
              GROUP  BY c.[disquestype],       
                        a.TraineeiD , d.Driscolallow)a       
      ORDER  BY CASE [disquestype]       
                  WHEN 'TIGER' THEN '0'       
                WHEN 'CHAMELEON' THEN '1'       
                  WHEN 'TURTLE' THEN '2'       
                  WHEN 'EAGLE' THEN '3'       
                  WHEN 'SALMON' THEN '4'       
                  ELSE [disquestype]       
                END       
  END 
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_EducationalDeatils, tbl_EDUCYTE_FamilyDetails, tbl_EDUCYTE_GetEmploymentOtherDetails, tbl_EDUCYTE_LanguageDetails, tbl_Educyte_PersonalDetails, tbl_EDUCYTE_Reference, tbl_EDUCYTE_Trainee_SignupDtls, tbl_Educyte_TraineeImage, tbl_Educyte_TraineeResume */
/****** Object:  StoredProcedure [dbo].[Proc_EDUCYTE_GetAllDeatils]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Procedure [dbo].[Proc_EDUCYTE_GetAllDeatils]  
@UserEmail Nvarchar(max),  
@Status NVARCHAR(MAX)=null OUTPUT    
  
AS            
DECLARE @errorcode nvarchar(max)            
BEGIN            
begin Try    
  
If not Exists ( Select * from tbl_Educyte_PersonalDetails Where UserEmail = @UserEmail)  
Begin   
  
SET @Status = 'Fill in all personal details correctly. Incomplete entries will block form submission.'      
end   
  
else If not Exists ( Select * from tbl_Educyte_TraineeImage Where UserEmail = @UserEmail)  
Begin   
  
SET @Status = 'Please Upload Image'      
end  
  
else If not Exists ( Select * from tbl_Educyte_TraineeResume Where UserEmail = @UserEmail)  
Begin   
  
SET @Status = 'Please Upload Resume'      
end  
  
else If not Exists ( Select * from tbl_EDUCYTE_FamilyDetails Where UserEmail = @UserEmail)  
Begin   
  
SET @Status = 'Fill in all family details correctly. Incomplete entries will block form submission.'      
end  
else If not Exists ( Select * from tbl_EDUCYTE_LanguageDetails Where UserEmail = @UserEmail)  
Begin   
  
SET @Status = 'Fill in all language details correctly. Incomplete entries will block form submission.'      
end  
  
else If not Exists ( Select * from tbl_EDUCYTE_EducationalDeatils Where UserEmail = @UserEmail)  
Begin   
  
SET @Status = 'Fill in all educational details correctly. Incomplete entries will block form submission.'      
end  
  
else If not Exists ( Select * from tbl_EDUCYTE_GetEmploymentOtherDetails Where UserEmail = @UserEmail)  
Begin   
  
SET @Status = 'Fill in all other details correctly. Incomplete entries will block form submission.'      
end  
  
else If not Exists ( Select * from tbl_EDUCYTE_Reference Where UserEmail = @UserEmail)  
Begin   
  
SET @Status = 'Please Add Reference details correctly. Incomplete entries will block form submission.'      
end  
else
begin 

update tbl_EDUCYTE_Trainee_SignupDtls set FinalSubmission='Final Submission Completed' where UserEmail = @UserEmail

SET @Status = 'All details are correct. Form submitted successfully.'    
end

end try                        
begin catch                                
 Select @errorcode=ERROR_NUMBER();                                
 Set @Status='CREATION FAILD!!.ERROR CODE:'+@errorcode                                
end catch                 
END  
  
  
  
  
  
  
  
  
  
  
  
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_Trainee_SignupDtls, tbl_EDUCYTE_UploadDocuments, tdocumentmaster */
/****** Object:  StoredProcedure [dbo].[proc_EDUCYTE_getbl_EDUCYTE_UploadDocuments]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE proc [dbo].[proc_EDUCYTE_getbl_EDUCYTE_UploadDocuments]  
@username varchar(Max),  
@Action varchar(Max)  
as  
    DECLARE @traineeid NVARCHAR(max)  
begin  
  
   SELECT @traineeid = [TraineeID]  
      FROM   [dbo].[tbl_EDUCYTE_Trainee_SignupDtls]  
      WHERE  [UserEmail] = @username  

 if(@Action ='SecondaryDocSelect')  
 begin  
     Select   
     [TraineeID],  
     a.[docid],  
     b.documentname,  
     [uploadedfilename],  
  a.varifactionstatus  
     from [dbo].[tbl_EDUCYTE_UploadDocuments]a,[dbo].[tdocumentmaster]b  
     where a.deleteflag='No'  
     and [TraineeID]=@traineeid  
     and a.[docid] in(Select [docid] from  [dbo].[tdocumentmaster] where [edulevel]=1 and deleteflag='No')  
     and a.[docid]=b.[docid]  
     and b.deleteflag='No'  
 end  
 if(@Action ='HSecondaryDocSelect')  
 begin  
     Select   
     [TraineeID],  
     a.[docid],  
     b.documentname,  
     [uploadedfilename],  
  a.varifactionstatus  
     from [dbo].[tbl_EDUCYTE_UploadDocuments]a,[dbo].[tdocumentmaster]b  
     where a.deleteflag='No'  
     and [TraineeID]=@traineeid  
     and a.[docid] in(Select [docid] from  [dbo].[tdocumentmaster] where [edulevel]=3 and deleteflag='No')  
     and a.[docid]=b.[docid]  
     and b.deleteflag='No'  
 end  
 if(@Action ='DiplomaDocSelect')  
 begin  
     Select   
     [TraineeID],  
     a.[docid],  
     b.documentname,  
     [uploadedfilename],  
  a.varifactionstatus  
     from [dbo].[tbl_EDUCYTE_UploadDocuments]a,[dbo].[tdocumentmaster]b  
     where a.deleteflag='No'  
     and [TraineeID]=@traineeid  
     and a.[docid] in(Select [docid] from  [dbo].[tdocumentmaster] where [edulevel]=2 and deleteflag='No')  
     and a.[docid]=b.[docid]  
     and b.deleteflag='No'  
 end  
 if(@Action ='GraduationDocSelect')  
 begin  
     Select   
     [TraineeID],  
     a.[docid],  
     b.documentname,  
     [uploadedfilename],  
  a.varifactionstatus  
  
     from [dbo].[tbl_EDUCYTE_UploadDocuments]a,[dbo].[tdocumentmaster]b  
     where a.deleteflag='No'  
     and [TraineeID]=@traineeid  
     and a.[docid] in(Select [docid] from  [dbo].[tdocumentmaster] where [edulevel]=4 and deleteflag='No')  
     and a.[docid]=b.[docid]  
     and b.deleteflag='No'  
 end  
 if(@Action ='PostGraduationDocSelect')  
 begin  
     Select   
     [TraineeID],  
     a.[docid],  
     b.documentname,  
     [uploadedfilename],  
  a.varifactionstatus  
     from [dbo].[tbl_EDUCYTE_UploadDocuments]a,[dbo].[tdocumentmaster]b  
     where a.deleteflag='No'  
     and [TraineeID]=@traineeid  
     and a.[docid] in(Select [docid] from  [dbo].[tdocumentmaster] where [edulevel]=5 and deleteflag='No')  
     and a.[docid]=b.[docid]  
     and b.deleteflag='No'  
 end  
 if(@Action ='OtherDocSelect')  
 begin  
     Select   
     [TraineeID],  
     a.[docid],  
     b.documentname,  
     [uploadedfilename],  
  a.varifactionstatus  
     from [dbo].[tbl_EDUCYTE_UploadDocuments]a,[dbo].[tdocumentmaster]b  
     where a.deleteflag='No'  
     and [TraineeID]=@traineeid  
     and a.[docid] in(Select [docid] from  [dbo].[tdocumentmaster] where documenttype='Other' and deleteflag='No')  
     and a.[docid]=b.[docid]  
     and b.deleteflag='No'  
 end  
   
  
end
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: trecrutdistrict */
