SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Proc_EDUCYTE_GetDistrictName]
@stateid int
AS
BEGIN 

Select 0 as disid , '-SELECT-' as districtname 
UNION ALL
Select disid,UPPER(disname) as districtname from trecrutdistrict
where disid NOT IN (719)
AND stateid = @stateid
END
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_Trainee_SignupDtls, tbl_EDUCYTE_UploadDocuments, tdocumentmaster, trecruitProfileMap */
/****** Object:  StoredProcedure [dbo].[proc_EDUCYTE_GETDocsname]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
    
CREATE proc [dbo].[proc_EDUCYTE_GETDocsname]    
@username nvarchar(Max),      
@Action varchar(Max)      
as      
declare @TraineeID nvarchar(Max)      
begin      
       SELECT @TraineeID = [TraineeID]       
          FROM  [dbo].[tbl_EDUCYTE_Trainee_SignupDtls]       
          WHERE  [UserEmail] = @username       
if(@Action='Secondary')      
begin      
 SELECT       
      docid ,CategoryName as documentname      
      FROM [dbo].[trecruitProfileMap]      
      where Doc='secondary'     
      and docid not in(Select docid FROM [dbo].[tbl_EDUCYTE_UploadDocuments] where TraineeID=@TraineeID and deleteflag='No')      
      and [TypeName]='EDUCATIONAL CERTIFICATE'      
end      
if(@Action='HigherSecondary')      
begin      
 SELECT       
      docid ,CategoryName as documentname      
      FROM [dbo].[trecruitProfileMap]      
      where Doc='highersecondary'  
   and docid not in(Select docid FROM [dbo].[tbl_EDUCYTE_UploadDocuments] where TraineeID=@TraineeID and deleteflag='No')      
     -- and deleteflag='No'      
     and [TypeName]='EDUCATIONAL CERTIFICATE'      
end      
if(@Action='Diploma')      
begin      
 SELECT       
      docid ,CategoryName as documentname      
      FROM [dbo].[trecruitProfileMap]      
      where Doc='diploma'  
   and docid not in(Select docid FROM [dbo].[tbl_EDUCYTE_UploadDocuments] where TraineeID=@TraineeID and deleteflag='No')      
     -- and deleteflag='No'      
     and [TypeName]='EDUCATIONAL CERTIFICATE'      
end      
if(@Action='Graduation')      
begin      
  SELECT       
      docid ,CategoryName as documentname      
      FROM [dbo].[trecruitProfileMap]      
      where Doc='graduation'  
   and docid not in(Select docid FROM [dbo].[tbl_EDUCYTE_UploadDocuments] where TraineeID=@TraineeID and deleteflag='No')      
     -- and deleteflag='No'      
     and [TypeName]='EDUCATIONAL CERTIFICATE'         
end      
if(@Action='PostGraduation')      
begin      
   SELECT       
      docid ,CategoryName as documentname      
      FROM [dbo].[trecruitProfileMap]      
      where Doc='post-graduation'  
   and docid not in(Select docid FROM [dbo].[tbl_EDUCYTE_UploadDocuments] where TraineeID=@TraineeID and deleteflag='No')      
     -- and deleteflag='No'      
     and [TypeName]='EDUCATIONAL CERTIFICATE'   
end      
if(@Action='Phd')      
begin      
 SELECT       
      docid ,documentname      
      FROM [dbo].[tdocumentmaster]      
      where [edulevel]=6      
   and docid not in(Select docid FROM [dbo].[tbl_EDUCYTE_UploadDocuments] where TraineeID=@TraineeID and deleteflag='No')      
      and deleteflag='No'      
      and [documenttype]='Educational'      
end      
if(@Action='OtherDoc')      
begin      
 SELECT       
     docid ,CategoryName as documentname    
      FROM [dbo].[trecruitProfileMap]      
      where docid not in(Select docid FROM [dbo].[tbl_EDUCYTE_UploadDocuments] where TraineeID=@TraineeID and deleteflag='No')      
     -- and deleteflag='No'      
  and TypeName='PERSONAL DETAILS'  
   order by CategoryName      
            
end      
      
      
end
GO



