CREATE PROCEDURE [dbo].[Proc_EDUCYTE_GetEmpReference]    
@UserEmail  NVARCHAR(MAX) ,
@action Nvarchar(max)
  
      
AS      
BEGIN      
      
IF(@action = 'EmpReference')      
BEGIN      
      
Select ID As ReferenceId,TraineeID,UserEmail,Name,Relation,Address,MobileNo,CreatedBy from tbl_EDUCYTE_Reference       
 where UserEmail = @UserEmail   
      
END      
    
IF(@action = 'ReferenceCount')      
BEGIN      
      
Select Count(ID) as CountReference from tbl_EDUCYTE_Reference       
where UserEmail = @UserEmail    
      
