/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_Educyte_PersonalDetails, tbl_EDUCYTE_Trainee_SignupDtls, test */
/****** Object:  StoredProcedure [dbo].[Proc_EDUCYTE_Getsubmitstatus]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Proc_EDUCYTE_Getsubmitstatus 'megadharofficial@gmail.com','Changestatus'    
CREATE PROC [dbo].[Proc_EDUCYTE_Getsubmitstatus] @username VARCHAR(1000)      
 ,@action VARCHAR(100)      
 ,@status VARCHAR(10) = NULL OUTPUT      
AS      
DECLARE @traineeid Nvarchar(max)     
DECLARE @submitstatus VARCHAR(1000)      
DECLARE @canname Nvarchar(max)     
DECLARE @canpost VARCHAR(Max)     
 DECLARE @MailId varchar(200)      
 DECLARE @tableHTML NVARCHAR(MAX)    
BEGIN      
    
    
    
 SELECT @traineeid = [TraineeID]      
 FROM [dbo].[tbl_EDUCYTE_Trainee_SignupDtls]      
 WHERE [UserEmail] = @username      
      
 SELECT @submitstatus = Applicationsubmit    
 FROM [dbo].[tbl_Educyte_PersonalDetails]      
 WHERE TraineeID = @traineeid      
      
 SELECT @canname=[FirstName]+' '+ ISnull([MiddleName],'')+' '+[LastName]      
 FROM [dbo].[tbl_Educyte_PersonalDetails]      
 WHERE TraineeID = @traineeid     
        
 SELECT @canpost = UserPostName    
 FROM [dbo].[tbl_EDUCYTE_Trainee_SignupDtls]      
 WHERE TraineeID = @traineeid     
    
      
 IF @action = 'Select'      
 BEGIN      
  IF @submitstatus = 'No'      
  BEGIN      
   SELECT Applicationsubmit      
   FROM [dbo].[tbl_Educyte_PersonalDetails]      
   WHERE TraineeID = @traineeid      
  END      
  ELSE      
  BEGIN      
   SELECT Applicationsubmit      
   FROM [dbo].[tbl_Educyte_PersonalDetails]      
   WHERE TraineeID = @traineeid      
  END      
 END      
    
    
      
 IF @action = 'Changestatus'      
 BEGIN      
  UPDATE [dbo].[tbl_Educyte_PersonalDetails]      
  SET Applicationsubmit = 'Yes'      
  WHERE TraineeID = @traineeid      
      
  UPDATE [dbo].[tbl_EDUCYTE_Trainee_SignupDtls]      
  SET FinalSubmission = 'Yes'      
  WHERE TraineeID = @traineeid  
  
    UPDATE [dbo].[tbl_Educyte_PersonalDetails]      
  SET docsubmissionallow = 'Yes'      
  WHERE TraineeID = @traineeid  
      
 SET @tableHTML = '<table style="font-size:20px; font-family:Tahoma ">      
      
        <tr>      
      
               <td>Dear '+ @canname +'</td>      
        </tr>      
      
        <tr>      
      
               <td>  This mail is to congratulate you about your successful completion of the Application Process  in Mendine Erythronet Pvt. Ltd.</td>      
  <br/>      
                    
      
      
        </tr>      
 <tr>      
  <td>You have succesfully filled up the Registration form and given both the Psychometric test. Our Recruitment team will shortly get in touch with you.      
</td>      
      
 </tr>      
      
        <tr>      
    <br/><br/>      
               <td>Thanks & Regards <br/><i>Mendine HR Team</i></td>      
      
        </tr>      
<br/>       
<td><p><a href="https://educyte.in/Forms/StudentPortal">Click Here for Educyte Portal</a></p></td>      
</tr>      
      
</table>';      
    
     
   SELECT @MailId=[UserEmail]            
  FROM [dbo].[tbl_EDUCYTE_Trainee_SignupDtls]      
  where TraineeID = @traineeid      
    
      
      
 EXEC msdb.dbo.sp_send_dbmail      
    @profile_name = 'Mendine_Recruitment_Profile'      
   ,@recipients = @MailId      
   ,@subject = 'Application Submitted Successfully'      
   ,@body = @tableHTML      
   ,@importance ='HIGH'      
   ,@body_format = 'HTML'      
      
 END      
END 
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_Educyte_PersonalDetails */
