SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Proc_EDUCYTE_GETTraineeName '29/02/2024' ,'29/03/2024'  
CREATE PROC [dbo].[Proc_EDUCYTE_GETTraineeName]    
  
@startdate nvarchar(max),      
@enddate nvarchar(max)     
AS    
BEGIN    
    
select A.TraineeID,A.FirstName + '' +  isnull(A.MiddleName,'') + ' ' + A.LastName as Traineename from tbl_Educyte_PersonalDetails  A  
  
Where convert(date,A.CreatedTime,103) >= convert(date,@startdate,103) AND                   
convert(date,A.CreatedTime,103) <= convert(date,@enddate,103)  
AND A.Applicationsubmit = 'Yes'
END
GO



