/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_Iqexamdtls, tbl_EDUCYTE_Iqtraineedtls, tbl_Educyte_PersonalDetails, trecruitiqansmarks, trecruittraker */
/****** Object:  StoredProcedure [dbo].[proc_EDUCYTE_iqhrdtls]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
      
          
CREATE procedure [dbo].[proc_EDUCYTE_iqhrdtls]           
@action             VARCHAR(100)=NULL,           
@candidateattemexam INT=NULL,          
@traineeid NVARCHAR(max)=NULL,          
@Message            VARCHAR(200)=NULL           
as          
DECLARE @userEmail NVARCHAR(max)           
DECLARE @iqallow     VARCHAR(200)          
begin          
          
SELECT @userEmail = UserEmail           
      FROM   [dbo].[tbl_Educyte_PersonalDetails]           
      WHERE  TraineeID = @traineeid           
          
IF @action = 'SELECTEXAMNO'           
        BEGIN           
            SELECT [attemexam],           
                   CASE           
                     WHEN [attemexam] = 1 THEN Cast('1st Exam' AS VARCHAR)           
                     WHEN [attemexam] = 2 THEN Cast('2nd Exam'AS VARCHAR)           
                     WHEN [attemexam] = 3 THEN Cast('3rd Exam'AS VARCHAR)           
                     ELSE Cast([attemexam]AS VARCHAR) + '' + 'th Exam'           
                   END [attemexamtext]           
            FROM   [dbo].[tbl_EDUCYTE_Iqexamdtls]           
            WHERE  TraineeID = @traineeid           
                   AND finalsubmit = 'Yes'           
            ORDER  BY [attemexam]           
        END           
          
IF @action = 'IQResult'           
begin          
          
select  b.[firstname]+' '+isnull(b.[middlename],'')+' '+b.[lastname] Empname,          
a.Scoresbetween,a.Rating,Comment          
          
 from          
(SELECT  a.TraineeID, (SELECT Comment from tbl_EDUCYTE_Iqexamdtls where TraineeID=@traineeid and attemexam=@candidateattemexam)Comment,          
    count(a.[Serialno])Scoresbetween,          
     case when count(a.[Serialno]) between 27 and 30 then 'Very highly exceptional'          
  when count(a.[Serialno]) between 24 and 26 then 'High expert'          
  when count(a.[Serialno]) between 21 and 23 then 'Expert'          
  when count(a.[Serialno]) between 19 and 20 then 'Very high average'          
  when count(a.[Serialno]) between 17 and 18 then 'High average'          
  when count(a.[Serialno]) between 13 and 16 then 'Middle average'          
  when count(a.[Serialno]) between 10 and 12 then 'Low average'          
  when count(a.[Serialno]) between 6 and 9 then 'Borderline low'          
  when count(a.[Serialno]) between 3 and 5 then 'Low'          
  when count(a.[Serialno]) between 0 and 2 then 'very low'          
      end Rating          
  FROM [dbo].[tbl_EDUCYTE_Iqtraineedtls] a,          
  [dbo].[trecruitiqansmarks] b          
  where a.TraineeID=@traineeid          
  and a.[questionid]=b.[questionno]          
  and a.[answer]=b.[answerno]          
  and b.[marks]=1          
  and a.[Traineeattemexam]=@candidateattemexam          
  group by a.TraineeID) a,[tbl_Educyte_PersonalDetails] b          
  where  a.TraineeID=b.TraineeID          
           
  end          
          
   IF @action = 'Activeinactiveresbutton'           
        BEGIN           
            SELECT a.FirstName + ' '+ isnull(a.middlename,'') + ''+ a.LastName as empname         
                   ,a.[iqallow]           
            FROM   [dbo].[tbl_Educyte_PersonalDetails] a                           
            WHERE   a.TraineeID = @traineeid           
        END           
          
  IF @action = 'Reschedule'           
        BEGIN           
            --SELECT @candiscrolallow = [discrolallow]           
            --FROM   [dbo].[trecruittraker]           
            --WHERE  [TraineeID] = @traineeid           
            --GROUP  BY [discrolallow],           
            --          [conflictallow],           
            --          [iqallow],           
            --          [eqallow]           
          
   SELECT @iqallow = [iqallow]           
            FROM   [dbo].[tbl_Educyte_PersonalDetails]          
            WHERE  [TraineeID] = @traineeid           
            GROUP  BY [Driscolallow],           
                      [conflictallow],           
                      [iqallow],           
                      [eqallow]           
          
                      
            IF @iqallow = 'Completed'           
              BEGIN           
                  UPDATE [dbo].[tbl_Educyte_PersonalDetails]           
                  SET    [iqallow] = 'Reschedule'           
        WHERE  [TraineeID] = @traineeid           
              END           
            ELSE           
              BEGIN           
                  SET @message=1           
              END           
        END           
          
  end
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: Languages, tbl_EDUCYTE_Iqexamdtls, tbl_EDUCYTE_Iqlanguagemap, tbl_EDUCYTE_Iqrandomques, tbl_EDUCYTE_Iqtraineedtls, tbl_Educyte_PersonalDetails, tbl_EDUCYTE_Trainee_SignupDtls, tempPsychometricTestMapping, trecruitdiscrolcandidatedtls, trecruitdiscrolqusdtls, trecruitiqansmarks, trecruitiqquesdtls, trecruittraker */
/****** Object:  StoredProcedure [dbo].[proc_Educyte_IQmasdtls]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
    
CREATE PROC [dbo].[proc_Educyte_IQmasdtls]      @action           NVARCHAR(100)=NULL,       
                                      @disquestype      NVARCHAR(100)=NULL,       
                                      @username         NVARCHAR(100)=NULL,       
                                      @activeflag       NVARCHAR(10)=NULL,       
                                      @disquestypeid    INT=NULL,       
                                      @languageid       INT=NULL,       
                                      @question         NVARCHAR(max)=NULL,       
                                      @questiondtlsid   INT=NULL,       
                                      @answer           NVARCHAR(max)=NULL,       
                                      @number           INT=NULL,       
                                      @answerdtlsid     INT=NULL,       
                                      @quesserialnonext INT=NULL,       
                                      @ollanguageid     INT=NULL,       
                                      @olquesserialno   INT=NULL,       
                                      @message          VARCHAR(500)=NULL output       
AS       
    DECLARE @empcode VARCHAR(100)       
    DECLARE @traineeid Nvarchar(max)       
    DECLARE @anslanguageid INT       
    DECLARE @queslanguageid INT       
    DECLARE @countexamques INT       
    DECLARE @countexamattm INT       
    DECLARE @countexamattques INT       
    DECLARE @quesserialno INT       
    DECLARE @maplanid INT       
    DECLARE @countexamattmcan INT       
    DECLARE @findques INT       
    DECLARE @idd INT       
    DECLARE @attemptno INT       
    DECLARE @cattemptno INT       
    DECLARE @atteptestno INT       
    DECLARE @quesset INT       
    DECLARE @aquesset INT       
    DECLARE @createdtime DATETIME       
    DECLARE @cancreatedtime DATETIME       
    DECLARE @orquesserialno INT       
    DECLARE @canquesset INT       
 DECLARE @sRanquesserialno int      
 declare @empno int         ---ishita      
      
  BEGIN     
    
  Begin Tran        
      
      
    set @languageid=5      
 set @maplanid=5     
 set @canquesset = 1   
      --SELECT @empcode = empcode       
      --FROM   essp.dbo.emp       
      --WHERE  empemail = @username       
      
   --SELECT @empno = empno       
   --   FROM   [essp].[dbo].[Empbasic]   ------ishita      
   --   WHERE  [empemail] = @username       
   --and empstatus='ACTIVE'      
      
      
      SELECT @traineeid = TraineeID       
      FROM   [dbo].[tbl_EDUCYTE_Trainee_SignupDtls]       
      WHERE  [UserEmail] = @username       
      
      --SELECT @maplanid = languageid       
      --FROM   [Recruitment].[dbo].[tbl_EDUCYTE_Iqlanguagemap] p       
      --WHERE  TraineeID = @traineeid       
      
      --SELECT @createdtime = Max([createddate])       
      --FROM   [Recruitment].[dbo].[tbl_EDUCYTE_Iqrandomques] p       
      --WHERE  languageid = @maplanid       
      
      SELECT @cancreatedtime = Max([Createddate])       
      FROM  [dbo].[tbl_EDUCYTE_Iqrandomques] p       
      
      
      --WHERE  languageid = @maplanid       
             --AND TraineeID = @traineeid       
      
      --SELECT @quesset = quesset       
      --FROM   [Recruitment].[dbo].[tbl_EDUCYTE_Iqrandomques] p       
      --WHERE   createddate = @createdtime       
      
      SELECT @canquesset = Quesset       
      FROM   [dbo].[tbl_EDUCYTE_Iqrandomques] p       
      WHERE   Createddate = @cancreatedtime       
            -- AND TraineeID = @traineeid       
      
       IF @canquesset = 1       
        BEGIN       
            SET @aquesset=@canquesset + 1       
        END       
      ELSE IF @canquesset = 2       
       BEGIN       
            SET @aquesset=@canquesset + 1       
      END       
      ELSE IF @canquesset = 3       
       BEGIN       
           SET @aquesset=@canquesset-2       
       END       
      
       
      
      SELECT @countexamques = Count([quesserialno])       
      FROM   [dbo].[trecruitiqquesdtls]       
      WHERE   [queslanset] = @canquesset       
      
      SELECT @quesserialno = Min([ranquesserialno])       
      FROM   [dbo].[trecruitiqquesdtls] p       
      WHERE  languageid = 5                   
      AND  [queslanset] = @canquesset       
      
      SELECT @countexamattm = [Attemexam]       
   FROM     [dbo].[tbl_EDUCYTE_Iqexamdtls]       
            WHERE  TraineeID = @traineeid       
                   AND finalsubmit <> 'Yes'       
      
      SELECT @orquesserialno = [quesserialno]       
      FROM   [Recruitment].[dbo].[trecruitiqquesdtls] ans       
      WHERE  [queslanset] = @canquesset       
             AND [ranquesserialno] = @questiondtlsid       
      
      SELECT @findques = Count(questionid)       
      FROM   [Recruitment].[dbo].[tbl_EDUCYTE_Iqtraineedtls]       
      WHERE  TraineeID = @traineeid       
             AND questionid = @orquesserialno       
             AND [quesfinalsubmitques] IS NULL       
       
 IF @action = 'iqcandidatelanguagemap'       
        BEGIN       
            DELETE FROM [dbo].[tbl_EDUCYTE_Iqlanguagemap]       
            WHERE  TraineeID = @traineeid     
      
            INSERT INTO [dbo].[tbl_EDUCYTE_Iqlanguagemap]       
                        ([TraineeID],    
       [UserEmail],    
                         [IDLang])       
            VALUES      (@traineeid,     
                 @username,    
                         @languageid )       
      
            INSERT INTO [dbo].[tbl_EDUCYTE_Iqrandomques]       
                        ([IDLang],       
                         [Quesset],       
                         [Createddate],       
                         TraineeID,    
       UserEmail)       
            VALUES      (@languageid,       
                         @aquesset,       
                         Getdate(),       
                         @traineeid,    
       @username)       
      
            SELECT @maplanid = IDLang       
            FROM   [dbo].[tbl_EDUCYTE_Iqlanguagemap] p       
            WHERE  TraineeID = @traineeid       
      
            SELECT @countexamques = Count([quesserialno])       
            FROM   [dbo].[trecruitiqquesdtls]       
            WHERE  [languageid] = @maplanid       
                   AND [queslanset] = @canquesset       
      
            SELECT @attemptno = Count([attemexam])       
            FROM   [dbo].[tbl_EDUCYTE_Iqexamdtls]       
            WHERE  [finalsubmit] = 'Yes'       
                   AND TraineeID = @traineeid       
      
            DELETE FROM [dbo].[tbl_EDUCYTE_Iqtraineedtls]       
            WHERE  [quesfinalsubmitques] IS NULL       
                   AND TraineeID = @traineeid       
      
            DELETE FROM [dbo].[tbl_EDUCYTE_Iqexamdtls]       
            WHERE  [finalsubmit] = 'No'       
                   AND TraineeID = @traineeid       
      
            INSERT INTO [dbo].[tbl_EDUCYTE_Iqexamdtls]       
                        ([TraineeID],     
       [UserEmail],    
                         [IDLang],       
                         [totalques],       
                         [attemques],       
                         [finalsubmit],       
                         [attemexam])       
            VALUES      ( @traineeid,     
                 @username,    
                          @languageid,       
                          @countexamques,       
                          NULL,       
                          'No',       
                          @attemptno + 1 )       
        END       
      
      IF @action = 'IQquesansselect'       
        BEGIN       
      
   SELECT @orquesserialno=[quesserialno]            
  FROM [dbo].[trecruitiqquesdtls]      
  where [Queslanset]=@canquesset and [Ranquesserialno]=@quesserialno      
      
           SELECT previousvalue,                         
                   ranquesserialno quesserialno,       
                   question,       
                   nextvalue,                          
                   noofques ,      
       quescount noofoption      
            FROM   (SELECT Lag(p.ranquesserialno)       
                             OVER (       
                               ORDER BY p.[ranquesserialno]) PreviousValue,       
                           Lag(p.question)       
                             OVER (       
                               ORDER BY p.[ranquesserialno]) PreviousValueques,       
                           p.ranquesserialno,       
                           p.question,       
         p.[quesserialno],      
                           Lead(p.ranquesserialno)       
                             OVER (       
                               ORDER BY p.[ranquesserialno]) NextValue,       
                           Lead(p.question)       
                             OVER (       
                               ORDER BY p.[ranquesserialno]) NextValueques,       
                           languageid       
                    FROM   [dbo].[trecruitiqquesdtls] p       
                    WHERE  languageid = 5                                
                     AND [queslanset] = @canquesset)s,       
                   (SELECT languageid,       
                           Count([quesserialno])noofques       
                    FROM   [dbo].[trecruitiqquesdtls]       
                    WHERE  languageid = 5                                  
                           AND [queslanset] = @canquesset      
                    GROUP  BY languageid) p ,(SELECT questionno,count([answerno])quescount      
            
                 FROM  [dbo].[trecruitiqansmarks]      
                             where questionno=@orquesserialno       
                              group by questionno)w      
            WHERE  ranquesserialno = @quesserialno       
                   AND p.languageid = s.languageid       
             
        END       
      
      IF @action = 'IQquesansselectnext'       
      
   SELECT @orquesserialno=[quesserialno]      
            
  FROM [dbo].[trecruitiqquesdtls]      
  where [Queslanset]=@canquesset and [Ranquesserialno]=@quesserialnonext      
      
        BEGIN       
            SELECT previousvalue,       
                          
                   ranquesserialno quesserialno,       
                   question,       
                   nextvalue,       
                         
                   noofques,       
       quescount noofoption,      
                   CASE       
                     WHEN x.TraineeID IS NULL THEN '0'       
                     ELSE x.TraineeID       
                   END             TraineeID,       
                   CASE       
                     WHEN x.[answer] IS NULL THEN 0       
                     ELSE x.[answer]       
                   END             answer,       
                   CASE       
                     WHEN y.[attemques] BETWEEN 1 AND 100 THEN y.[attemques]       
                     ELSE y.[attemques]       
                   END             [attemques]       
            FROM   (SELECT Lag(p.ranquesserialno)       
                             OVER (       
                               ORDER BY p.[ranquesserialno]) PreviousValue,       
                           Lag(p.question)       
                             OVER (       
                               ORDER BY p.[ranquesserialno]) PreviousValueques,       
                           p.ranquesserialno,       
                           p.quesserialno,       
                           p.question,       
                           Lead(p.ranquesserialno)       
                             OVER (       
                               ORDER BY p.[ranquesserialno]) NextValue,       
                           Lead(p.question)       
                             OVER (       
                               ORDER BY p.[ranquesserialno]) NextValueques,       
                           languageid       
                    FROM   [dbo].[trecruitiqquesdtls] p       
                    WHERE  languageid = 5       
                                 
                           AND [queslanset] = @canquesset)s       
                   LEFT OUTER JOIN       
                                 [dbo].[tbl_EDUCYTE_Iqtraineedtls]       
                   x       
                                ON s.languageid = x.[IDLang]       
                                   AND s.quesserialno = x.[questionid]       
                                   AND [quesfinalsubmitques] IS NULL       
                                   AND x.[TraineeID] = @traineeid,       
                   (SELECT languageid,       
                           count([quesserialno])noofques       
                    FROM   [dbo].[trecruitiqquesdtls]       
                 WHERE  languageid = 5       
                                 
                           AND [queslanset] = @canquesset       
                    GROUP  BY languageid) p, (SELECT questionno,count([answerno])quescount      
            
                 FROM  [dbo].[trecruitiqansmarks]      
                             where questionno=@orquesserialno      
                              group by questionno)w,      
                             [dbo].[tbl_EDUCYTE_Iqexamdtls] y       
            WHERE  ranquesserialno = @quesserialnonext       
                   AND p.languageid = s.languageid       
                   AND s.languageid = y.[IDLang]       
                   AND y.TraineeID = @traineeid     
                   AND [finalsubmit] = 'No'       
            
        END       
      
      IF @action = 'IQansselect'       
        BEGIN       
  SELECT @orquesserialno = [quesserialno]       
            FROM   [dbo].[trecruitiqquesdtls] ans       
            WHERE  [queslanset] = @canquesset       
                   AND [ranquesserialno] = @questiondtlsid       
      
            SELECT [answerno],       
                   [answer],       
                   language       
            FROM   [dbo].[trecruitiqansmarks] ans,       
                   [dbo].[languages] lan ,[dbo].[trecruitiqquesdtls] qus       
            WHERE  ans.[languageid] = lan.[id]       
                   AND lan.[id] = 5      
       and ans.[questionno]=qus.[quesserialno]      
       and qus.[quesserialno]=@orquesserialno      
        END       
      
      IF @action = 'IQolquesansselect'       
        BEGIN       
      SELECT @orquesserialno = [quesserialno]       
            FROM   [dbo].[trecruitiqquesdtls] ans       
            WHERE  [queslanset] = @canquesset       
                   AND [ranquesserialno] = @questiondtlsid       
      
            SELECT [question]       
            FROM   [dbo].[trecruitiqquesdtls]       
            WHERE  languageid = 5      
                   AND ranquesserialno = @olquesserialno       
                   AND [queslanset] = @canquesset       
      
            SELECT [answerno],       
                   [answer],       
                   language       
            FROM   [dbo].[trecruitiqansmarks] ans,       
                   [dbo].[languages] lan ,[dbo].[trecruitiqquesdtls] qus       
            WHERE  ans.[languageid] = lan.[id]       
                   AND lan.[id] = 5      
       and ans.[questionno]=qus.[quesserialno]      
       and qus.[quesserialno]=@orquesserialno      
        END       
            
      IF @action = 'IQcandtlsinsert'       
         AND @findques = 0       
        BEGIN       
            SELECT @countexamattm = [attemexam]       
            FROM   [dbo].[tbl_EDUCYTE_Iqexamdtls]       
            WHERE  TraineeID = @traineeid     
                   AND finalsubmit <> 'Yes'       
      
            SELECT @countexamattmcan = Count([TraineeID])       
            FROM   [dbo].[tbl_EDUCYTE_Iqexamdtls]       
            WHERE  TraineeID = @traineeid     
      
            SELECT @orquesserialno = [quesserialno]       
            FROM   [dbo].[trecruitiqquesdtls] ans       
            WHERE  [queslanset] = @canquesset       
                   AND [ranquesserialno] = @questiondtlsid       
      
            BEGIN       
                INSERT INTO [dbo].[tbl_EDUCYTE_Iqtraineedtls]       
                           ([TraineeID],    
       UserEmail,    
                             exquesset,       
                             [Serialno],      
                             [IDLang],       
                             [questionid],       
                             [answer],       
                             Traineeattemexam,       
                             [createdon],       
                             [updatedon])       
                VALUES      ( @traineeid,      
                  @username,    
                              @canquesset,       
         @questiondtlsid,      
                              @maplanid,       
                              @orquesserialno,       
                              @number,       
                              @countexamattm,       
                        Getdate(),       
                              Getdate() )       
      
                SET @message='Answer Details Successfully Inserted'       
            END       
      
            SELECT @countexamattques = Count([questionid])       
            FROM   [dbo].[tbl_EDUCYTE_Iqtraineedtls]       
      WHERE  TraineeID = @traineeid       
                   AND answer <> 0       
                   AND quesfinalsubmitques IS NULL       
      
            IF @countexamattm IS NOT NULL       
              BEGIN       
                  UPDATE [dbo].[tbl_EDUCYTE_Iqexamdtls]       
                  SET    [attemques] = [totalques] - @countexamattques       
                  WHERE  TraineeID = @traineeid       
                         AND finalsubmit = 'No'       
              END       
        END       
      
      IF @action = 'IQcandtlsinsert'       
         AND @findques > 0       
        BEGIN       
            SELECT @countexamattm = [attemexam]       
            FROM   [dbo].[tbl_EDUCYTE_Iqexamdtls]       
            WHERE  TraineeID = @traineeid     
                   AND finalsubmit = 'No'       
      
            SELECT @orquesserialno = [quesserialno]       
            FROM   [dbo].[trecruitiqquesdtls] ans       
            WHERE  [queslanset] = @canquesset       
                   AND [ranquesserialno] = @questiondtlsid       
      
            UPDATE [dbo].[tbl_EDUCYTE_Iqtraineedtls]       
            SET    [answer] = @number,       
                   [updatedon] = Getdate()       
            WHERE  TraineeID = @traineeid     
                   AND [questionid] = @orquesserialno       
                   AND [quesfinalsubmitques] IS NULL       
      
            SET @message='Answer Details Successfully Updated'       
      
            SELECT @countexamattques = Count([questionid])       
            FROM   [dbo].[tbl_EDUCYTE_Iqtraineedtls]       
            WHERE  TraineeID = @traineeid       
                   AND answer <> 0       
                   AND quesfinalsubmitques IS NULL       
      
            IF @countexamattm IS NOT NULL       
              BEGIN       
                  UPDATE  [dbo].[tbl_EDUCYTE_Iqexamdtls]       
                  SET    [attemques] = [totalques] - @countexamattques       
                  WHERE  TraineeID = @traineeid       
                         AND finalsubmit = 'No'       
              END       
        END       
      
      IF @action = 'Finalsubmit'       
        BEGIN       
      
  INSERT INTO  [dbo].[tbl_EDUCYTE_Iqtraineedtls]       
                            ( TraineeID,      
         UserEmail,    
                             exquesset,       
        [Serialno],      
                             [IDLang],       
                             [questionid],       
                             [answer],      
        createdon,                                   
                             [updatedon],      
        [Traineeattemexam])       
      
        select @TraineeID,     
         @username,    
        [Queslanset],      
        [Ranquesserialno],      
        5,      
        [quesserialno],      
        0,      
        getdate(),      
        getdate(),      
        @countexamattm      
         from  [dbo].[trecruitiqquesdtls]      
        where [Queslanset]=1      
        and [Ranquesserialno] not in (SELECT [Serialno]            
                             FROM  [dbo].[tbl_EDUCYTE_Iqtraineedtls]      
                            where TraineeID =@traineeid)      
        order by [Ranquesserialno]      
      
            UPDATE  [dbo].[tbl_EDUCYTE_Iqexamdtls]       
            SET    [finalsubmit] = 'Yes'       
            WHERE  TraineeID = @traineeid       
      
            --UPDATE [Recruitment].[dbo].[trecruittraker]         
            --SET    [discrolallow] = 'Completed'         
            --WHERE  TraineeID = @traineeid         
            -----------------------------------------        
            UPDATE [dbo].[tbl_Educyte_PersonalDetails]   ----- ishita change      
            SET    [iqallow] = 'Completed'       
            WHERE  TraineeID = @traineeid       
      
   --UPDATE [essp].[dbo].[temppsychometrictestmapping]       
   --         SET    [IQTest] = 'Completed'         ------ishita      
   --         WHERE  empno = @empno      
      
            -------------------------------------------        
            UPDATE [dbo].[tbl_EDUCYTE_Iqtraineedtls]       
            SET    [quesfinalsubmitques] = 'F'       
            WHERE  TraineeID = @traineeid       
        END       
      
      IF @action = 'IQcandtlsselect'       
BEGIN       
   SELECT disc.[id],       
                   disc.[TraineeID],    
        disc.[UserEmail],    
                   disc.[IDLang],       
                   disc.[questionid],       
                   ques.[question],       
                   disc.[answer]       
            FROM   [dbo].[tbl_EDUCYTE_Iqtraineedtls] disc,       
                   [dbo].[trecruitiqquesdtls] ques       
            WHERE  TraineeID = @traineeid     
                   AND [questionid] = @questiondtlsid       
                   AND disc.[questionid] = ques.id       
        END       
      
      IF @action = 'IQcandtlsselect'       
        BEGIN       
            IF NOT EXISTS (SELECT TraineeID       
                           FROM       
                    [dbo].[tbl_EDUCYTE_Iqtraineedtls]       
                           WHERE  TraineeID = @TraineeID)       
              BEGIN       
                  SELECT @sRanquesserialno=Min([Ranquesserialno])      
                  FROM   [dbo].[trecruitiqquesdtls]       
                  WHERE  [languageid] = 5                                
                  and [Queslanset]=@canquesset      
           
      
                  SELECT [number],       
                         [answer]       
                  FROM   [dbo].[trecruitiqansdtls]       
                  WHERE  [languageid] = @languageid       
                         AND activeflag = 'Yes'       
              END       
        --SELECT disc.[id],                          
        --       disc.[TraineeID],                          
        --       disc.[languageid],                          
        --       disc.[questionid],                          
        --       ques.[question],                          
        --       disc.[answer]                          
        --FROM   [Recruitment].[dbo].[trecruitdiscrolcandidatedtls] disc,                          
        --       [dbo].[trecruitdiscrolqusdtls] ques                          
        --WHERE  TraineeID = @traineeid                        
        --       AND [questionid] = @questiondtlsid                          
        --       AND disc.[questionid] = ques.id                          
        END       
      
      IF @action = 'IQansqnoselect'       
        BEGIN       
            SELECT @atteptestno = [attemexam]       
            FROM   [dbo].[tbl_EDUCYTE_Iqexamdtls]       
            WHERE  [finalsubmit] = 'No'       
                   AND TraineeID = @traineeid     
      
            SELECT [Serialno] questionid       
            FROM   [dbo].[tbl_EDUCYTE_Iqtraineedtls]       
            WHERE  [answer] > 0       
                   AND [Traineeattemexam] = @atteptestno       
                   AND TraineeID = @traineeid     
        END       
  Commit Tran  
  END     
      
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_Trainee_SignupDtls */
/****** Object:  StoredProcedure [dbo].[Proc_EDUCYTE_Login]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Proc_EDUCYTE_Login ''
CREATE PROCEDURE [dbo].[Proc_EDUCYTE_Login]        
        
@UserEmail NVARCHAR(MAX),        
@UserPassword NVARCHAR(64),        
@Status NVARCHAR(MAX)=null OUTPUT        
        
AS        
DECLARE @errorcode Nvarchar(max)       
DECLARE @finalstatus Nvarchar(max)

BEGIN        
begin Try     
  
Select @finalstatus= FinalSubmission From  
tbl_EDUCYTE_Trainee_SignupDtls  
Where UserEmail = @UserEmail AND UserPassword = @UserPassword  


        
IF Exists (Select * from tbl_EDUCYTE_Trainee_SignupDtls Where UserEmail = @UserEmail AND UserPassword = @UserPassword )        
BEGIN    
if (@finalstatus = 'Final Submission Completed')  
begin  
  
select A.ID,A.TraineeID,A.UserFullName,A.UserEmail,A.UserComapnyName,A.UserPostName from tbl_EDUCYTE_Trainee_SignupDtls A Where UserEmail = @UserEmail AND UserPassword = @UserPassword        
        
SET @Status = 'Final Submission Completed'    
  
end   

else if (@finalstatus = 'Yes')  
begin  
  
select A.ID,A.TraineeID,A.UserFullName,A.UserEmail,A.UserComapnyName,A.UserPostName from tbl_EDUCYTE_Trainee_SignupDtls A Where UserEmail = @UserEmail AND UserPassword = @UserPassword        
        
SET @Status = 'Application Submitted Successfully'    
  
end 
else   
begin  
        
select A.ID,A.TraineeID,A.UserFullName,A.UserEmail,A.UserComapnyName,A.UserPostName from tbl_EDUCYTE_Trainee_SignupDtls A Where UserEmail = @UserEmail AND UserPassword = @UserPassword        
        
SET @Status = 'Successfully Logged In'        
END  

end  
  
  
ELSE        
BEGIN        
        
SET @Status = 'Log In Failed'        
END        
end try                        
begin catch                        
 Select @errorcode=ERROR_NUMBER();                        
 Set @Status='LOGIN FAILD!!.ERROR CODE:'+@errorcode                        
end catch         
END
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_OtherDetails */
/****** Object:  StoredProcedure [dbo].[Proc_EDUCYTE_OtherDetilsforhrms]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Procedure [dbo].[Proc_EDUCYTE_OtherDetilsforhrms]   
 
@traineeid Nvarchar(max),  
@action  Nvarchar(max)  
  
AS  
BEGIN   
  
      
If(@action = 'OtherDetails')      
begin      
      
select ID as OtherID,TraineeID,UserEmail,MembershipofanyProfession,Othertrainingattended,OtherQualification,  
ComputerProficiency,ExtraCurriculamActivites,SpecialInterest,CreatedBy from tbl_EDUCYTE_OtherDetails       
where  TraineeID = @traineeid    
end       
    
    
If(@action = 'OtherDetailsDelete')      
begin      
      
Delete tbl_EDUCYTE_OtherDetails    
where  TraineeID = @traineeid  
end   
  
END  
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_EducationalDeatils */
/****** Object:  StoredProcedure [dbo].[Proc_Educyte_SaveEducationaldtls]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Proc_Educyte_SaveEducationaldtls]    
@Id int=null,    
@TraineeID NVARCHAR(MAX)=null,    
@UserEmail NVARCHAR(MAX)=null,    
@EducationID Int,
@BoardID Int,
@Specialization Nvarchar(max),
@YearOfPassing Nvarchar(max),
@InstituteName Nvarchar(max),
@Marksdivision Nvarchar(max),
@CreatedBy Nvarchar(max), 
@Status nvarchar(max)=null output    
    
AS    
DECLARE @errorcode nvarchar(max)    
BEGIN    
begin try    
    
If exists (Select * from tbl_EDUCYTE_EducationalDeatils where ID = @Id)    
    
Begin    
    
UPDATE tbl_EDUCYTE_EducationalDeatils SET EducationID=@EducationID,BoardID=@BoardID,    
Specialization=@Specialization,YearOfPassing=@YearOfPassing,InstituteName=@InstituteName,
Marksdivision=@Marksdivision
Where ID = @Id    
    
SET @Status = 'Educational Details Updated Successfully'    
END     
Else    
Begin    
    
Insert into tbl_EDUCYTE_EducationalDeatils (    
TraineeID,    
UserEmail,    
EducationID,    
BoardID,    
Specialization,    
YearOfPassing,
InstituteName,   
Marksdivision,   
CreatedBy,    
CreatedTime    
)    
Values (    
@TraineeID,    
@UserEmail,    
@EducationID,    
@BoardID,    
@Specialization,    
@YearOfPassing, 
@InstituteName,  
@Marksdivision,  
@CreatedBy,    
GETDATE()    
)    
SET @Status = 'Educational Details Saved Successfully'    
    
END    
    
    
    
end try                            
begin catch                            
 Select @errorcode=ERROR_NUMBER();                            
 Set @Status='CREATION FAILD!!.ERROR CODE:'+@errorcode                            
end catch     
    
END
