CREATE PROCEDURE [dbo].[Proc_Educyte_Savefamilydtls]    
@Id int=null,    
@TraineeID NVARCHAR(MAX)=null,    
@UserEmail NVARCHAR(MAX)=null,    
@Fmember NVARCHAR(MAX),    
@Relationship nvarchar(max),    
@Occupation nvarchar(max),    
@CreatedBy nvarchar(max),    
@Status nvarchar(max)=null output    
    
AS    
DECLARE @errorcode nvarchar(max)    
--BEGIN    
--begin try    
    
--If exists (Select * from tbl_EDUCYTE_FamilyDetails where ID = @Id)    
    
--Begin    
    
--UPDATE tbl_EDUCYTE_FamilyDetails SET Fmember=@Fmember,Relationship=@Relationship,    
--Occupation=@Occupation Where ID = @Id    
    
--SET @Status = 'Family Details Updated Successfully'    
--END     
--Else    
--Begin    
    
--Insert into tbl_EDUCYTE_FamilyDetails (    
--TraineeID,    
--UserEmail,    
--Fmember,    
--Relationship,    
--Occupation,    
--CreatedBy,    
--CreatedOn    
--)    
--Values (    
--@TraineeID,    
--@UserEmail,    
--@Fmember,    
--@Relationship,    
--@Occupation,    
--@CreatedBy,    
--GETDATE()    
--)    
--SET @Status = 'Family Details Saved Successfully'    
    
--END    
    
    
    
--end try                            
--begin catch                            
-- Select @errorcode=ERROR_NUMBER();                            
-- Set @Status='CREATION FAILD!!.ERROR CODE:'+@errorcode                            
--end catch     
    
--END  
BEGIN    
begin try    
    
If  not exists(select top 1 * from tbl_EDUCYTE_FamilyDetails where Fmember=@Fmember and Relationship=@Relationship and  TraineeID=@TraineeID)
Begin
		If exists (Select * from tbl_EDUCYTE_FamilyDetails where ID = @Id)        
		Begin    
    
				UPDATE tbl_EDUCYTE_FamilyDetails SET Fmember=@Fmember,Relationship=@Relationship,    
				Occupation=@Occupation Where ID = @Id    
				SET @Status = 'Family Details Updated Successfully'    
		END     
		Else    
		Begin    
    
				Insert into tbl_EDUCYTE_FamilyDetails (    
				TraineeID,    
				UserEmail,    
				Fmember,    
				Relationship,    
				Occupation,    
				CreatedBy,    
				CreatedOn    
				)    
				Values (    
				@TraineeID,    
				@UserEmail,    
				@Fmember,    
				@Relationship,    
				@Occupation,    
				@CreatedBy,    
				GETDATE()    
				)    
				SET @Status = 'Family Details Saved Successfully'    
		END    
 END
	ELSE
    BEGIN
	If exists (Select * from tbl_EDUCYTE_FamilyDetails where ID = @Id AND Occupation <> @Occupation)        
		Begin    
    
				UPDATE tbl_EDUCYTE_FamilyDetails SET Occupation=@Occupation 
				Where ID = @Id    
				SET @Status = 'Family Details Updated Successfully'    
		END   
		ELSE
		 BEGIN 
	       SET @Status = 'Relationship already exists'
		 END
	END
end try                            
begin catch                            
 Select @errorcode=ERROR_NUMBER();                            
 Set @Status='CREATION FAILD!!.ERROR CODE:'+@errorcode                            
end catch     
    
END  

GO



