/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_Educyte_PersonalDetails, tbl_EDUCYTE_Trainee_SignupDtls, tbl_EDUCYTE_UploadDocuments */
/****** Object:  StoredProcedure [dbo].[proc_EDUCYTE_Uploaddocuments]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
  
CREATE PROC [dbo].[proc_EDUCYTE_Uploaddocuments] 
                                       @username       NVARCHAR(max),  
                                       @uploadfilename NVARCHAR(max)=null,  
                                       @uploadfiletype NVARCHAR(max)=null,  
                                       @uploadfile     VARBINARY(max)=null,  
                                       @docid          INT=null,  
                                       @action         VARCHAR(100)  
AS  
    DECLARE @traineeid NVARCHAR(max)  
  
  BEGIN  
      SELECT @traineeid = [TraineeID]  
      FROM   [dbo].[tbl_EDUCYTE_Trainee_SignupDtls]  
      WHERE  [UserEmail] = @username  
  
 IF(@action='UPLOAD')  
 BEGIN  
 IF EXISTS (SELECT 1  
                 FROM   [dbo].[tbl_EDUCYTE_UploadDocuments]  
                 WHERE  TraineeID = @traineeid  
                        AND docid = @docid  
                        AND deleteflag = 'Yes')  
        BEGIN  
            DELETE FROM [dbo].[tbl_EDUCYTE_UploadDocuments]  
            WHERE  TraineeID = @traineeid  
                   AND docid = @docid  
                   AND deleteflag = 'Yes'  
  
            INSERT INTO [dbo].[tbl_EDUCYTE_UploadDocuments]  
                        ([TraineeID], 
						 [UserEmail],
                         [docid],  
                         [uploadedfilename],  
                         [uploadedfiletype],  
                         [uploadedfile],  
                         [deleteflag],  
                         [uploadedby],  
                         [uploadedon],  
       [varifactionstatus])  
            VALUES      ( @traineeid, 
			              @username,
                          @docid,  
                          @uploadfilename,  
                          @uploadfiletype,  
                          @uploadfile,  
                          'No',  
                          @traineeid,  
                          Getdate(),  
        'Pending' )  
        END  
      ELSE  
        BEGIN  
            INSERT INTO [dbo].[tbl_EDUCYTE_UploadDocuments]  
                        ([TraineeID],  
						 [UserEmail],
                         [docid],  
                         [uploadedfilename],  
                         [uploadedfiletype],  
                         [uploadedfile],  
                         [deleteflag],  
                         [uploadedby],  
                         [uploadedon],  
                         [varifactionstatus])  
            VALUES      ( @traineeid, 
			              @username,
                          @docid,  
                          @uploadfilename,  
                          @uploadfiletype,  
                          @uploadfile,  
                          'No',  
                          @traineeid,  
                          Getdate(),  
        'Pending' )  
        END  
 END  
 IF(@action='DELETE')  
 BEGIN  
  UPDATE [dbo].[tbl_EDUCYTE_UploadDocuments]  
  SET deleteflag='Yes'  
  WHERE TraineeID=@traineeid  
  AND docid=@docid  
  AND deleteflag='No'  
 END  
 IF(@action='SUBMIT')  
 begin  
  IF EXISTS (SELECT 1  
                 FROM   [dbo].[tbl_EDUCYTE_UploadDocuments]  
                 WHERE  TraineeID = @traineeid  
                        AND deleteflag = 'No')  
  begin  
  if EXISTS(Select docid from [dbo].[tbl_EDUCYTE_UploadDocuments]  
            where TraineeID = @traineeid  
                        AND deleteflag = 'No'  
      And varifactionstatus='Rejected')  
      begin  
       Select 2 --for doc submission faliure because of rejected doc  
      end  
      else  
      begin  
       Update  [dbo].[tbl_Educyte_PersonalDetails]  
                   set docsubmissionallow='Completed',  
                   docsubmissionon=getdate()  
                where TraineeID=@traineeid  
                          Select 1 --for successful doc submission  
      end  
    
  end  
  else  
  begin  
   Select 0 --for doc submission faliure  
  end  
 end  
 IF(@action='ISALLOW')  
 begin  
  Select docsubmissionallow from [dbo].[tbl_Educyte_PersonalDetails] where TraineeID=@traineeid  
 end  
 IF(@action='STARTUPLOADING')  
 begin  
  UPDATE [dbo].[tbl_Educyte_PersonalDetails]   
  SET docsubmissionallow='Uploading'  
  where TraineeID=@traineeid  
 end  
  
        
  END 
GO



