/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_EducationalDeatils, tbl_EDUCYTE_OtherDetails, trecruitboards, trecruiteducation */
/****** Object:  StoredProcedure [dbo].[Proc_EDUCYTEEducationandOtherdetailsforhrms]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Proc_EDUCYTEEducationandOtherdetailsforhrms 'MAHWASH NAAZ _9496','EducationalDetails'
CREATE PROCEDURE [dbo].[Proc_EDUCYTEEducationandOtherdetailsforhrms]     
@traineeid  NVARCHAR(MAX),      
@action NVARCHAR(MAX)    
     
AS            
BEGIN            
            
If(@action = 'EducationalDetails')            
begin            
            
Select A.ID as EduId, A.TraineeID,A.UserEmail,A.EducationID,B.eduname,A.BoardID,C.bdname,          
A.Specialization,A.YearOfPassing,A.InstituteName,A.Marksdivision,A.CreatedBy           
from tbl_EDUCYTE_EducationalDeatils  A          
LEFT JOIN trecruiteducation B ON A.EducationID=B.eduid          
LEFT JOIN trecruitboards C ON A.BoardID=C.bdid         
where A.TraineeID = @traineeid  
end             
            
If(@action = 'OtherDetails')            
begin            
            
select ID as OtherID,TraineeID,UserEmail,Othertrainingattended,OtherQualification,        
ComputerProficiency,ExtraCurriculamActivites,SpecialInterest,CreatedBy from tbl_EDUCYTE_OtherDetails            
where TraineeID = @traineeid           
end             
            
END 
GO



