GO
 -- Proc_GET_EDUCYTE_ApplicationTracker '29/02/2024' ,'03/03/2024'        
        
CREATE PROC [dbo].[Proc_GET_EDUCYTE_ApplicationTracker]            
@startdate nvarchar(max),            
@enddate nvarchar(max)            
--@traineeid nvarchar(max)            
            
AS            
BEGIN            
            
Select A.TraineeID,                          
A.UserEmail,                          
A.PostName,                          
(A.FirstName +'' +                          
Isnull(A.MiddleName,'') +'' +                          
A.LastName) as TraineeName,                          
A.CurrentAddressLine1,                          
A.CurrentAddressLine2,                          
A.CurrentCityandVillage,                          
A.CurrentPostOffice,                          
A.CurrentPincode,                          
A.CurrentStateID,                        
B.statename as Currentstatename,                      
C.disname as Currentdisname,                      
A.CurrentDistrictID,                          
A.CurrentandPermanentChecked,                          
A.PermanentAddressLine1,                          
A.PermanentAddressLine2,                          
A.PermanentCityandVillage,                          
A.PermanentPostOffice,                          
A.PermanentPincode,                          
A.PermanentStateID,                          
A.PermanentDistrictID,                        
D.statename as Permanentstatename,                      
E.disname as Permanentdisname,                      
A.CountryCode,                       
F.cname,                      
A.ModileNo,                          
Convert(varchar,A.DateOfBirth,103) as DateOfBirth,                          
A.Age,                          
A.Gender,                      
G.Gender As Gendername,                      
A.MaritalStatus  ,                       
H.Maritalstatus as  MaritalstatusName,                      
A.Nationality,                         
I.NationalityName,                      
A.Religion ,                          
J.Religion as ReligionName,                      
A.CreatedBy ,                    
K.ReportImagepath as ImagePath,                    
K.ImageFileName ,                  
L.ResumeFileName,                  
L.ReportresumePath as ResumeFilePath ,    
Convert(varchar,A.CreatedTime,103) as applicationdate,                 
               
R.Othertrainingattended,                
R.OtherQualification,                      
R.ComputerProficiency,                
R.ExtraCurriculamActivites,                
R.SpecialInterest,                
X.Consideryourself,                  
X.ReferredID ,                  
Y.ReferredName,                  
X.SpecifyOthers ,                  
X.AadhaarNo ,                  
X.PanCardNo ,                  
X.Uanno ,                  
X.EsicNo,                  
X.Engagedbusiness,                  
X.Physicaldisability,                  
X.Interviewedforemploymentinthiscompany,                  
X.Relativesorfriendsalreadyworking ,                  
X.DischargedordismissedanyCompany,                  
X.ConvictedincourtofLaw,                  
X.Timerequiretojoin  ,              
X.Nameofbusniess,              
X.RelativeName,              
X.RelativeDesignation,              
X.Relation,              
X.Designationone,              
X.Designationtwo,              
X.Designationthree,              
X.Designationfour         
             
  from tbl_Educyte_PersonalDetails A                      
LEFT JOIN trecruitstate B ON A.CurrentStateID=B.stateid                      
LEFT JOIN trecrutdistrict C ON A.CurrentDistrictID=C.disid                      
LEFT JOIN trecruitstate D ON A.PermanentStateID=D.stateid                      
LEFT JOIN trecrutdistrict E ON A.PermanentDistrictID=E.disid                      
LEFT JOIN trecruitcountrycode F ON A.CountryCode=F.codeid                       
LEFT JOIN tbl_EDUCYTE_Gender G ON A.Gender=G.ID                      
LEFT JOIN tbl_EDUCYTE_MaritalStatus H ON A.MaritalStatus=H.ID                      
LEFT JOIN tbl_EDUCYTE_Nationality I ON A.Nationality=I.ID                      
LEFT JOIN tbl_EDUCYTE_Religion J ON A.Religion=J.ID                      
LEFT JOIN tbl_Educyte_TraineeImage K ON A.UserEmail = K.UserEmail                    
LEFT JOIN tbl_Educyte_TraineeResume L ON A.UserEmail = L.UserEmail                 
              
LEFT JOIN tbl_EDUCYTE_OtherDetails R ON A.UserEmail = R.UserEmail                
                 
LEFT JOIN tbl_EDUCYTE_GetEmploymentOtherDetails X ON A.UserEmail = X.UserEmail                
LEFT JOIN tbl_EDUCYTE_ReferredUs Y ON X.ReferredID=Y.ReferredID                  
               
Where convert(date,A.CreatedTime,103) >= convert(date,@startdate,103) AND                         
convert(date,A.CreatedTime,103) <= convert(date,@enddate,103)             
--AND A.TraineeID = case when @traineeid = '0' then A.TraineeID Else @traineeid End            
AND A.Applicationsubmit ='Yes'            
            
END 
GO



