CREATE PROCEDURE [dbo].[Proc_Get_EDUCYTE_TraineeDetails]
@useremail Nvarchar(max)

AS
BEGIN

SELECT A.TraineeID,A.UserEmail,A.PostName,UPPER(A.[FirstName]+' '+ ISnull(A.[MiddleName],'')+' '+A.[LastName]) as TraineeName , ISnull(Driscolallow,'') as Driscolallow,ISnull(Conflictallow,'') as Conflictallow,
ISnull(Iqallow,'') as Iqallow,ISnull(Eqallow,'') as Eqallow , 'Application Submitted Successfully' as Status,
convert(varchar,A.CreatedTime,103) as CreatedTime
FROM tbl_Educyte_PersonalDetails A
WHERE A.UserEmail = @useremail

END
