--)           
--SELECT candidateid,CandidateName           
--FROM CTE        
       
--order by CandidateName     
   
   
WITH CTE AS (             
   SELECT A.candidateid, dbo.Candidate_FullName(A.[firstname],A.[middlename],A.[lastname]) CandidateName ,  ROW_NUMBER() OVER (PARTITION BY  CandidateName  ORDER BY (SELECT 0)) AS rn             
   FROM  trecruitcanbasicdtls A            
