-- Proc_Getcandidateprofiledata '-SELECT-','-SELECT-','-SELECT-','2025-01-01','2026-10-31','-SELECT-'       
CREATE PROCEDURE [dbo].[Proc_Getcandidateprofiledata]             
@Deptname varchar(max),                 
@postname varchar(max),                 
@candidatename varchar(max),      
@FromDate date=null,                 
@ToDate date=null,      
--@FromDate varchar(100)=null,                 
--@ToDate varchar(100)=null,                 
@Frselected varchar(100)                 
AS                 
BEGIN                 
                 
--set  @postname  = CASE WHEN CHARINDEX('-', @postname) > 0 THEN SUBSTRING(@postname, 1, CHARINDEX('-', @postname) - 1) ELSE @postname END                  
             
--IF (@postname = '-SELECT-' AND @candidatename='-SELECT-')             
--BEGIN             
             
--SELECT              
--candidateid,              
--CandidateName,              
--CASE              
--WHEN deptname = '' THEN 'OTHERS'              
--ELSE deptname               
--END AS deptname,              
--postname  ,             
--aplicationdate,             
--Frselect             
--FROM vw_essp_RecruitCanProfile                  
--WHERE              
----deptname = @Deptname              
--(deptname = CASE WHEN @Deptname = '-SELECT-' THEN deptname ELSE @Deptname END)               
---- Only show data for the specified department             
--AND (postname = CASE WHEN @postname = '-SELECT-' THEN postname ELSE @postname END)                 
--AND (CandidateName = CASE WHEN @candidatename = '-SELECT-' THEN CandidateName ELSE @candidatename END)                
--AND (postname NOT LIKE '%ASSOCIATE%')               
--OR (             
---- Check if @FromDate and @ToDate are empty, if so, ignore date filtering             
--(             
--    @FromDate = '' AND @ToDate = ''              
--    OR              
--    (             
--        convert(date, (convert(varchar, convert(datetime, aplicationdate, 103), 101)), 101)               
--        BETWEEN              
--        convert(date, (convert(varchar, convert(datetime, @FromDate, 103), 101)), 101)              
--        AND              
--        convert(date, (convert(varchar, convert(datetime, @ToDate, 103), 101)), 101)             
--    )             
--)             
--)                   
--AND (ISNULL(Frselect,'') = CASE WHEN @Frselected = '-SELECT-' THEN ISNULL(Frselect,'') ELSE @Frselected END)             
--Order by CandidateName             
--END             
             
--ELSE             
--BEGIN             
             
                  
--SELECT              
--        candidateid,              
--        CandidateName,              
--        CASE              
--            WHEN deptname = '' THEN 'OTHERS'              
--            ELSE deptname               
--        END AS deptname,             
             
              
--        postname  ,             
--  aplicationdate,             
--  Frselect             
--    FROM vw_essp_RecruitCanProfile                  
--    WHERE              
--      --  deptname = @Deptname              
             
--  -- Only show data for the specified department             
--    (deptname = CASE WHEN @Deptname = '-SELECT-' THEN deptname ELSE @Deptname END)               
             
--        AND (postname = CASE WHEN @postname = '-SELECT-' THEN postname ELSE @postname END)                 
--        AND (CandidateName = CASE WHEN @candidatename = '-SELECT-' THEN CandidateName ELSE @candidatename END)                
--        AND (postname NOT LIKE '%ASSOCIATE%')               
--        AND (             
--            -- Check if @FromDate and @ToDate are empty, if so, ignore date filtering             
--            (             
--                @FromDate = '' AND @ToDate = ''              
--                OR              
--                (             
--                    convert(date, (convert(varchar, convert(datetime, aplicationdate, 103), 101)), 101)               
                                 
--BETWEEN              --                    convert(date, (convert(varchar, convert(datetime, @FromDate, 103), 101)), 101)              
--                    AND              
--                    convert(date, (convert(varchar, convert(datetime, @ToDate, 103), 101)), 101)             
--                )             
                   
             
--      )             
--        )                   
--        AND (ISNULL(Frselect,'') = CASE WHEN @Frselected = '-SELECT-' THEN ISNULL(Frselect,'') ELSE @Frselected END)              
--      Order by CandidateName             
--END              
           
           
           
IF (@postname = '-SELECT-' AND @candidatename='-SELECT-')                 
BEGIN                 
Select A.* from                  
(SELECT                  
 convert(varchar(max),p.candidateid) as candidateid,                     
CandidateName,         
registrationnumber,         
CASE                  
WHEN deptname = '' THEN 'OTHERS'                  
ELSE deptname                   
END AS deptname,                  
postname  ,                 
convert(varchar,aplicationdate,103) as aplicationdate,                 
Frselect,  
   s.mailId  as candidateEmail                  
    FROM vw_essp_RecruitCanProfile p  
  
    
INNER JOIN trecruitcandidatesignup s  
    ON s.CandidateID = p.candidateid   
WHERE                   
 (postname NOT LIKE '%ASSOCIATE%')                   
AND (                 
(                 
    (@FromDate = '' AND @ToDate = '')             
            OR              
            (             
                convert(date,CONVERT(datetime, aplicationdate, 103),23)              
                BETWEEN convert(date,CONVERT(datetime, @FromDate, 103),23)          
                AND convert(date,CONVERT(datetime, @ToDate, 103),23)            
            )              
                     
)                
)                       
             
             
UNION              
             
select TraineeID as candidateid,             
UPPER(ISNULL(FirstName,'')+' '+ISNULL(MiddleName,'')+' '+ISNULL(LastName,'')) as CandidateName,         
null as registrationnumber,         
'EDUCYTE' as deptname,             
'EDUCYTE TRAINEE' as postname,             
convert(varchar,CreatedTime,103) as aplicationdate,             
'Yes' as Frselect,  
UserEmail  as candidateEmail             
from tbl_Educyte_PersonalDetails             
where Applicationsubmit='Yes'             
and (                 
 (@FromDate = '' AND @ToDate = '')             
            OR              
            (             
                convert(date,CONVERT(datetime, CreatedTime, 103),23)              
                BETWEEN convert(date,CONVERT(datetime, @FromDate, 103),23)          
                AND convert(date,CONVERT(datetime, @ToDate, 103),23)       
            )    )                
) A             
where (deptname = CASE WHEN @Deptname = '-SELECT-' THEN deptname ELSE @Deptname END)                   
AND (postname = CASE WHEN @postname = '-SELECT-' THEN postname ELSE @postname END)                     
AND (CandidateName = CASE WHEN @candidatename = '-SELECT-' THEN CandidateName ELSE @candidatename END)             
AND (ISNULL(Frselect,'') = CASE WHEN @Frselected = '-SELECT-' THEN ISNULL(Frselect,'') ELSE @Frselected END)                 
ORDER BY CONVERT(date, A.aplicationdate, 103) DESC
END                 
                 
ELSE                 
BEGIN                 
                 
Select A.* from                      
(SELECT                  
        convert(varchar(max),p.candidateid) as candidateid,                  
        CandidateName,          
  registrationnumber,         
        CASE                  
            WHEN deptname = '' THEN 'OTHERS'                  
            ELSE deptname                   
        END AS deptname,                 
                 
                  
        postname  ,                 
  convert(varchar,aplicationdate,103) as aplicationdate,                 
  Frselect,  
   s.mailId  as candidateEmail                  
   FROM vw_essp_RecruitCanProfile p  
  
    
INNER JOIN trecruitcandidatesignup s  
    ON s.CandidateID = p.candidateid  
  
                     
    WHERE                 
         (postname NOT LIKE '%ASSOCIATE%')                   
        AND (                 
            (                 
              (@FromDate = '' AND @ToDate = '')             
            OR              
            (             
                convert(date,CONVERT(datetime, aplicationdate, 103),23)              
                BETWEEN  convert(date,CONVERT(datetime, @FromDate, 103),23)        
                AND convert(date,CONVERT(datetime, @ToDate, 103),23)             
            )             
                 
                      
        )    )                
        --AND (ISNULL(Frselect,'') = CASE WHEN @Frselected = '-SELECT-' THEN ISNULL(Frselect,'') ELSE @Frselected END)                  
             
UNION              
             
select TraineeID as candidateid,             
UPPER(ISNULL(FirstName,'')+' '+ISNULL(MiddleName,'')+' '+ISNULL(LastName,'')) as CandidateName,          
null as registrationnumber,         
'EDUCYTE' as deptname,             
'EDUCYTE TRAINEE' as postname,             
convert(varchar,CreatedTime,103) as aplicationdate,             
'Yes' as Frselect,  
UserEmail  as candidateEmail           
from tbl_Educyte_PersonalDetails             
where Applicationsubmit='Yes'             
and (                 
     (@FromDate = '' AND @ToDate = '')             
            OR              
            (             
                convert(date,CONVERT(datetime, CreatedTime, 103),23)            
                BETWEEN  convert(date,CONVERT(datetime, @FromDate, 103),23)        
                AND convert(date,CONVERT(datetime, @ToDate, 103),23)             
            )             
)                 
) A             
Where (deptname = CASE WHEN @Deptname = '-SELECT-' THEN deptname ELSE @Deptname END)                   
                 
        AND (postname = CASE WHEN @postname = '-SELECT-' THEN postname ELSE @postname END)                     
        AND (CandidateName = CASE WHEN @candidatename = '-SELECT-' THEN CandidateName ELSE @candidatename END)             
   AND (ISNULL(Frselect,'') = CASE WHEN @Frselected = '-SELECT-' THEN ISNULL(Frselect,'') ELSE @Frselected END)                  
ORDER BY CONVERT(date, A.aplicationdate, 103) DESC             
END                  
           
           
END   
  
  
  
  
  
  
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: Intern_Candidate_Details, Misc_InternStatus */
/****** Object:  StoredProcedure [dbo].[Proc_Getcurrentstatus]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Proc_Getcurrentstatus 2990
CREATE PROCEDURE [dbo].[Proc_Getcurrentstatus]     
@candidateid Bigint    
AS    
BEGIN    
  
if exists(select * from Intern_Candidate_Details where Candidateid = @candidateid )  
BEGIN
SELECT A.ID , A.CurrentStatus  
FROM Intern_Candidate_Details B  
JOIN Misc_InternStatus A ON A.CurrentStatus = B.CurrentStatus  
WHERE B.Candidateid = @candidateid  
  
UNION ALL  
  
SELECT A.ID, A.CurrentStatus  
FROM Misc_InternStatus A  
WHERE A.CurrentStatus NOT IN (SELECT CurrentStatus FROM Intern_Candidate_Details WHERE Candidateid = @candidateid)
END
ELSE
BEGIN

SELECT distinct '0'ID, '-SELECT-' CurrentStatus  
UNION ALL
SELECT A.ID, A.CurrentStatus  
FROM Misc_InternStatus A 
END
END   
GO



