/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_Educyte_PersonalDetails, tbl_EDUCYTE_PlacementCompany */
/****** Object:  StoredProcedure [dbo].[sp_FilterPlacementCompanies]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[sp_FilterPlacementCompanies]  
    @StartDate DATE = NULL,  
    @EndDate DATE = NULL  
AS    
BEGIN    
    SET NOCOUNT ON;  
 SELECT  
    placed.CompanyName,  
    placed.HQ,     
    placed.CTC,     
    placed.DOJ,     
    placed.TraineeID,    
    per.FirstName + ' ' + per.LastName AS TraineeName,  
    edu_p.BatchNo,  
    CASE 
        WHEN edu_p.BatchNo LIKE '%Online%' THEN 'Online'
        ELSE edu_p.TrainingCenter 
    END AS TrainingCenter
FROM tbl_EDUCYTE_PlacementCompany placed  
JOIN tbl_Educyte_PersonalDetails per ON placed.TraineeID = per.TraineeID  
LEFT JOIN lms.dbo.VW_Edu_Placement edu_p ON per.UserEmail = edu_p.Email
    WHERE  
        (@StartDate IS NULL OR placed.DOJ >= @StartDate) AND  
        (@EndDate IS NULL OR placed.DOJ <= @EndDate)  
END    
  
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_Educyte_PersonalDetails, tbl_EDUCYTE_PlacementCompany */
/****** Object:  StoredProcedure [dbo].[sp_SearchPlacementCompanies]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[sp_SearchPlacementCompanies]    
    @StartDate DATE = NULL,    
    @EndDate DATE = NULL,    
 @TraineeID VARCHAR(MAX)    
AS      
BEGIN      
    SET NOCOUNT ON;    
 SELECT    
   placed.CompanyName,       
        placed.HQ,       
        placed.CTC,       
        placed.DOJ,       
        placed.TraineeID,      
  per.FirstName +  ' ' + per.LastName as TraineeName,    
  edu_p.BatchNo,    
       edu_p.TrainingCenter    
    
    FROM tbl_EDUCYTE_PlacementCompany placed JOIN tbl_Educyte_PersonalDetails per ON  placed .TraineeID = per.TraineeID    
 left JOIN   lms.dbo.VW_Edu_Placement edu_p on per.UserEmail = edu_p.Email    
    WHERE    
        (@StartDate IS NULL OR placed.DOJ >= @StartDate) AND    
        (@EndDate IS NULL OR placed.DOJ <= @EndDate)    
  AND placed.TraineeID = @TraineeID    
END      
GO



