CREATE PROC [dbo].[PRC_InternShip_Details_saveDemo]              
@TBInternshipDetails Type_Insert_InternshipDtls ReadOnly               
--@Action varchar(30)              
AS                
BEGIN                
 Declare @Result Varchar(1000)=''                     
 BEGIN TRAN                
 BEGIN TRY                
 -- Truncate Table Intern_Candidate_Details                
 if not exists(select [Candidateid] from Intern_Candidate_Details where Candidateid in (select [Candidateid] from @TBInternshipDetails ))              
 begin              
Insert Into Intern_Candidate_Details                
  ([Candidateid], [CandidateName], [Qualification],[Institution], [Batch], [ContactNo], [JoindAs], [Department], [DateOfJoining], [DateOfCompletion], [DaysCompleted],[ReportingasIntern],Remarks,Empno,Joining ,DesignationName,Empemail,EmpreporttopersonNo,EmpHierarcheName , CurrentStatus,Active,[CreatedBy],[CreatedOn])                
  Select [Candidateid], [CandidateName], [Qualification],[Institution], [Batch], [ContactNo], [JoindAs], [Department], [DateOfJoining],[DateOfCompletion] ,                
  [DaysCompleted],[ReportingasIntern],Remarks,[Empno],[Joining] ,[DesignationName],[Empemail],[EmpreporttopersonNo],[EmpHierarcheName] , [CurrentStatus],1,[CreatedBy],GETDATE() From @TBInternshipDetails               
 end              
 else              
 begin              
 Update Intern_Candidate_Details               
 set DateOfJoining=Temp.DateOfJoining,              
  DateOfCompletion=Temp.DateOfCompletion,              
  DaysCompleted=Temp.DaysCompleted,          
  Remarks=Temp.Remarks,     
  CurrentStatus= Temp.CurrentStatus,    
  Active = 1 ,
  ReportingasIntern= Temp.ReportingasIntern

 From @TBInternshipDetails Temp              
 where Intern_Candidate_Details.Candidateid=Temp.Candidateid              
 end              
              
--if(@Action='Insert')              
--begin              
--  Insert Into Intern_Candidate_Details                
--  ([Candidateid], [CandidateName], [Qualification], [Batch], [ContactNo], [JoindAs], [Department], [DateOfJoining], [DateOfCompletion], [DaysCompleted])                
--  Select [Candidateid], [CandidateName], [Qualification], [Batch], [ContactNo], [JoindAs], [Department], [DateOfJoining],[DateOfCompletion] ,                
--  [DaysCompleted] From @TBInternshipDetails               
--  end              
--  if(@Action='Update')              
--  begin              
--  Update Intern_Candidate_Details set               
              
 COMMIT TRAN                
 END TRY                
 Begin CATCH                                           
 ROLLBACK TRAN                                           
  Set @Result=dbo.fnErrors()                                          
 End CATCH                                           
 Select @Result                 
END 
GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: tbl_EDUCYTE_FamilyDetails */
/****** Object:  StoredProcedure [dbo].[Proc_Educyte_Savefamilydtls_temp]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Proc_Educyte_Savefamilydtls_temp]    
@Id int=null,    
@TraineeID NVARCHAR(MAX)=null,    
@UserEmail NVARCHAR(MAX)=null,    
@Fmember NVARCHAR(MAX),    
@Relationship nvarchar(max),    
@Occupation nvarchar(max),    
@CreatedBy nvarchar(max),    
@Status nvarchar(max)=null output    
    
AS    
DECLARE @errorcode nvarchar(max)    
BEGIN    
begin try    
    
If  not exists(select top 1 * from tbl_EDUCYTE_FamilyDetails where Fmember=@Fmember and Relationship=@Relationship and  TraineeID=@TraineeID)
Begin
		If exists (Select * from tbl_EDUCYTE_FamilyDetails where ID = @Id)        
		Begin    
    
				UPDATE tbl_EDUCYTE_FamilyDetails SET Fmember=@Fmember,Relationship=@Relationship,    
				Occupation=@Occupation Where ID = @Id    
				SET @Status = 'Family Details Updated Successfully'    
		END     
		Else    
		Begin    
    
				Insert into tbl_EDUCYTE_FamilyDetails (    
				TraineeID,    
				UserEmail,    
				Fmember,    
				Relationship,    
				Occupation,    
				CreatedBy,    
				CreatedOn    
				)    
				Values (    
				@TraineeID,    
				@UserEmail,    
				@Fmember,    
				@Relationship,    
				@Occupation,    
				@CreatedBy,    
				GETDATE()    
				)    
				SET @Status = 'Family Details Saved Successfully'    
		END    
 END
	ELSE
    BEGIN
	If exists (Select * from tbl_EDUCYTE_FamilyDetails where ID = @Id AND Occupation <> @Occupation)        
		Begin    
    
				UPDATE tbl_EDUCYTE_FamilyDetails SET Occupation=@Occupation 
				Where ID = @Id    
				SET @Status = 'Family Details Updated Successfully'    
		END   
		ELSE
		 BEGIN 
	       SET @Status = 'Relationship already exists'
		 END
	END
end try                            
begin catch                            
 Select @errorcode=ERROR_NUMBER();                            
 Set @Status='CREATION FAILD!!.ERROR CODE:'+@errorcode                            
end catch     
    
END  

GO



/* Functional group: 11_EDUCYTE_AND_INTERNSHIP_SEPARATE_SUBMODULE; referenced grouped tables: Company, tbl_Educyte_PersonalDetails, tbl_EDUCYTE_PlacementCompany, tbl_EDUCYTE_TraineeInterviewdtls */
/****** Object:  StoredProcedure [dbo].[Proc_EDUCYTE_Saveinterviewdtls_Test]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
 
CREATE PROC [dbo].[Proc_EDUCYTE_Saveinterviewdtls_Test]          
    @TraineeID NVARCHAR(MAX),          
    @TraineeName NVARCHAR(MAX),          
    @Source NVARCHAR(MAX),        
    @EQmapping VARCHAR(100),          
    @IQmapping VARCHAR(100),     
    @Driscolmapping VARCHAR(100),    
    @Conflictmapping VARCHAR(100),    
    @Docmapping VARCHAR(100),      
    @Selected VARCHAR(20),     
    @CompanyName VARCHAR(200) = NULL,  
    @HQ VARCHAR(100) = NULL,  
    @CTC VARCHAR(50) = NULL,  
    @DOJ DATE = NULL,  
    @CreatedBy NVARCHAR(MAX),          
    @outputstatus VARCHAR(MAX) = NULL OUTPUT           
AS  
BEGIN  
    DECLARE @PlacementCompanyId INT;  
    DECLARE @errorcode NVARCHAR(MAX);  
  
    BEGIN TRY  
        BEGIN TRANSACTION;  
  
        -- Check if Interview details already exist  
        IF EXISTS (SELECT 1 FROM tbl_EDUCYTE_TraineeInterviewdtls WHERE TraineeID = @TraineeID)  
        BEGIN  
            -- Update Interview Details  
            UPDATE tbl_EDUCYTE_TraineeInterviewdtls          
            SET EQmappling = @EQmapping,        
                IQmappling = @IQmapping,      
                Driscolmapping = @Driscolmapping,    
                Conflictmapping = @Conflictmapping,    
                Docmapping = @Docmapping  
            WHERE TraineeID = @TraineeID;  
        END  
        ELSE  
        BEGIN  
            -- Insert Interview Details  
            INSERT INTO tbl_EDUCYTE_TraineeInterviewdtls (  
                TraineeID, TraineeName, Source,   
                EQmappling, IQmappling, Driscolmapping,   
                Conflictmapping, Docmapping, CreatedBy, CreatedOn  
            )   
            VALUES (  
                @TraineeID, @TraineeName, @Source,   
                @EQmapping, @IQmapping, @Driscolmapping,   
                @Conflictmapping, @Docmapping, @CreatedBy, GETDATE()  
            );  
        END  
  
        -- If selected 'Yes' or 'No', manage placement company details  
        IF @Selected IN ('Yes', 'No')  
        BEGIN  
            IF EXISTS (  
                SELECT 1  
                FROM tbl_EDUCYTE_PlacementCompany pc  
                JOIN tbl_Educyte_PersonalDetails pd ON pc.TraineeID = pd.TraineeID  
                WHERE pd.Selected IS NOT NULL AND pc.TraineeID = @TraineeID  
            )  
            BEGIN  
                -- Update PlacementCompany if record exists  
                UPDATE tbl_EDUCYTE_PlacementCompany  
                SET CompanyName = @CompanyName,   
                    HQ = @HQ,   
                    CTC = @CTC,   
                    DOJ = @DOJ  
                WHERE TraineeID = @TraineeID;  
            END  
            ELSE  
            BEGIN  
                -- Insert PlacementCompany if no record  
                INSERT INTO tbl_EDUCYTE_PlacementCompany (CompanyName, HQ, CTC, DOJ, TraineeID)  
                VALUES (@CompanyName, @HQ, @CTC, @DOJ, @TraineeID);  
                      
                SET @PlacementCompanyId = SCOPE_IDENTITY();  
            END  
  
        
            UPDATE tbl_Educyte_PersonalDetails  
            SET Selected = @Selected  
            WHERE TraineeID = @TraineeID;  
        END  
  
        -- Update Personal Details mapping fields if NULL or 'No'  
        UPDATE tbl_Educyte_PersonalDetails  
        SET   
            Eqallow = CASE WHEN Eqallow IS NULL OR Eqallow = 'No' THEN @EQmapping ELSE Eqallow END,  
            Iqallow = CASE WHEN Iqallow IS NULL OR Iqallow = 'No' THEN @IQmapping ELSE Iqallow END,  
            Driscolallow = CASE WHEN Driscolallow IS NULL OR Driscolallow = 'No' THEN @Driscolmapping ELSE Driscolallow END,  
            Conflictallow = CASE WHEN Conflictallow IS NULL OR Conflictallow = 'No' THEN @Conflictmapping ELSE Conflictallow END,  
            docsubmissionallow = CASE WHEN docsubmissionallow IS NULL OR docsubmissionallow = 'No' THEN @Docmapping ELSE docsubmissionallow END  
        WHERE TraineeID = @TraineeID;  
  
        COMMIT TRANSACTION;  
        SET @outputstatus = 'Interview Details Saved Successfully';  
    END TRY  
    BEGIN CATCH  
        ROLLBACK TRANSACTION;  
        SELECT @errorcode = ERROR_MESSAGE();  
        SET @outputstatus = 'CREATION FAILED!! ERROR: ' + @errorcode;  
    END CATCH  
END  
GO





