/* Functional group: 99_UNRELATED_DEMO_LEGACY; referenced grouped tables: Customers */
/****** Object:  StoredProcedure [dbo].[Customers_CRUD]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [dbo].[Customers_CRUD]
	@Action VARCHAR(10)
	,@CustomerId INT = NULL
	,@Name VARCHAR(100) = NULL
	,@Country VARCHAR(100) = NULL
AS
BEGIN
	SET NOCOUNT ON;

	--SELECT
    IF @Action = 'SELECT'
	BEGIN
		SELECT CustomerId, Name, Country 
		FROM Customers
	END

	--INSERT
    IF @Action = 'INSERT'
	BEGIN
		INSERT INTO Customers (Name, Country) 
		VALUES (@Name, @Country)
	END

	--UPDATE
    IF @Action = 'UPDATE'
	BEGIN
		UPDATE Customers 
		SET Name = @Name, Country = @Country 
		WHERE CustomerId = @CustomerId
	END

	--DELETE
    IF @Action = 'DELETE'
	BEGIN
		DELETE FROM Customers 
		WHERE CustomerId = @CustomerId
	END
END
GO



