/* Functional group: 99_UNRELATED_DEMO_LEGACY; referenced grouped tables: none detected */
/****** Object:  StoredProcedure [dbo].[PorcCustomerstestListSearch]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Proc [dbo].[PorcCustomerstestListSearch]          
@SearchValue Varchar(100),          
@ColumnName Varchar(500),    
@startdate varchar(50),    
@enddate varchar(50)    
As          
Begin          
Declare @SQL Varchar(Max)=''          
    
   Select  A.*          
   from  vw_rcalldata  A          
   WHERE     
   @ColumnName Like @searchvalue +'%' AND    
   convert(datetime,(convert(varchar, convert(datetime, A.aplicationdate, 103), 101)),111)    
   BETWEEN convert(datetime,(convert(varchar, convert(datetime, @startdate, 103), 101)),111) AND     
   convert(datetime,(convert(varchar, convert(datetime, @enddate, 103), 101)),111)    
       
       
      
Exec(@SQL)          
End 
GO



/* Functional group: 99_UNRELATED_DEMO_LEGACY; referenced grouped tables: none detected */
/****** Object:  StoredProcedure [dbo].[Proc_canDeptnamelist]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
-- Proc_canDeptnamelist  '20/07/2023','02/08/2023'          
CREATE PROCEDURE [dbo].[Proc_canDeptnamelist]                
--@Deptname Nvarchar(max),              
@StartDate Varchar(12),              
@EndDate Varchar(12)              
AS                
BEGIN                
select DISTINCT isnull(deptdivision,'')   as deptdivision      
from vw_rcalldata                
where convert(datetime,aplicationdate,103)              
between convert(datetime,@StartDate,103) AND convert(datetime,@EndDate,103) 
ORDER BY deptdivision
--AND              
--deptname like @Deptname+'%'                  
END 
GO



