/****** Object:  StoredProcedure [dbo].[proc_Getcandidatedtls]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROC [dbo].[proc_Getcandidatedtls]    
AS    
BEGIN    
--select candidateid,CandidateName from vw_RecruitCanProfile    
    
--order by CandidateName    
  
WITH CTE AS (    
   SELECT candidateid,CandidateName ,  ROW_NUMBER() OVER (PARTITION BY  CandidateName  ORDER BY (SELECT 0)) AS rn    
   FROM  vw_RecruitCanProfile      
)    
SELECT candidateid,CandidateName    
FROM CTE    
WHERE rn = 1    
    
END
GO



