/* Functional group: 99_UNRELATED_DEMO_LEGACY; referenced grouped tables: swilorder, swilorderparty, swilproductcode */
/****** Object:  StoredProcedure [dbo].[procswillorder]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE PROCEDURE [dbo].[procswillorder] @order  [TYPESWILLORDERS] readonly, 
                                       @Action VARCHAR(100) 
AS 
  BEGIN 
      IF @Action = 'INSERT' 
        BEGIN 
            DELETE FROM swilorder 

            INSERT INTO swilorder 
                        ([orderno], 
                         [dcr date], 
                         [retailer code], 
                         depocode, 
                         [retailer name], 
                         [area name], 
                         [hq], 
                         [user name], 
                         [anm], 
                         [rnm], 
                         [division], 
                         [item name], 
                         [pack size], 
                         [qty], 
                         [rate], 
                         [pob], 
                         [city], 
                         [state], 
                         [zone]) 
            SELECT Row_number() 
                     OVER ( 
                       ORDER BY [retailer name]), 
                   CONVERT(CHAR(10), [dcr date], 126) 
                   [DCR Date], 
                   --     case  
                   --when [Retailer Name] like '%NWLP%' 
                   --then SUBSTRING([Retailer Name], CHARINDEX(('NWLP'), [Retailer Name]), LEN([Retailer Name])) 
                   --when [Retailer Name] like '%HWH%' 
                   --then SUBSTRING([Retailer Name], CHARINDEX(('HWH'), [Retailer Name]), LEN([Retailer Name])) 
                   --when [Retailer Name] like '%DMDM%' 
                   --then SUBSTRING([Retailer Name], CHARINDEX(('DMDM'), [Retailer Name]), LEN([Retailer Name])) 
                   --when [Retailer Name] like '%BHLA%' 
                   --then SUBSTRING([Retailer Name], CHARINDEX(('BHLA'), [Retailer Name]), LEN([Retailer Name])) 
                   --when [Retailer Name] like '%BDWN%' 
                   --then SUBSTRING([Retailer Name], CHARINDEX(('BDWN'), [Retailer Name]), LEN([Retailer Name])) 
                   --when [Retailer Name] like '%MDNP%' 
                   --then SUBSTRING([Retailer Name], CHARINDEX(('MDNP'), [Retailer Name]), LEN([Retailer Name])) 
                   --when [Retailer Name] like '%MLDA%' 
                   --then SUBSTRING([Retailer Name], CHARINDEX(('MLDA'), [Retailer Name]), LEN([Retailer Name])) 
                   --end   
                   [retailer code], 
                   --case  
                   --when [Retailer Name] like '%NWLP%' 
                   --then SUBSTRING(SUBSTRING([Retailer Name], CHARINDEX(('NWLP'), [Retailer Name]), LEN([Retailer Name])),0,charindex('-',SUBSTRING([Retailer Name], CHARINDEX(('NWLP'), [Retailer Name]), LEN([Retailer Name])),0)) 
                   --when [Retailer Name] like '%HWH%' 
                   --then SUBSTRING(SUBSTRING([Retailer Name], CHARINDEX(('HWH'), [Retailer Name]), LEN([Retailer Name])),0,charindex('-',SUBSTRING([Retailer Name], CHARINDEX(('HWH'), [Retailer Name]), LEN([Retailer Name])),0)) 
                   --when [Retailer Name] like '%DMDM%' 
                   --then SUBSTRING(SUBSTRING([Retailer Name], CHARINDEX(('DMDM'), [Retailer Name]), LEN([Retailer Name])),0,charindex('-',SUBSTRING([Retailer Name], CHARINDEX(('DMDM'), [Retailer Name]), LEN([Retailer Name])),0)) 
                   --when [Retailer Name] like '%BHLA%' 
                   --then SUBSTRING(SUBSTRING([Retailer Name], CHARINDEX(('BHLA'), [Retailer Name]), LEN([Retailer Name])),0,charindex('-',SUBSTRING([Retailer Name], CHARINDEX(('BHLA'), [Retailer Name]), LEN([Retailer Name])),0)) 
                   --when [Retailer Name] like '%BDWN%' 
                   --then SUBSTRING(SUBSTRING([Retailer Name], CHARINDEX(('BDWN'), [Retailer Name]), LEN([Retailer Name])),0,charindex('-',SUBSTRING([Retailer Name], CHARINDEX(('BDWN'), [Retailer Name]), LEN([Retailer Name])),0)) 
                   --when [Retailer Name] like '%MDNP%' 
                   --then SUBSTRING(SUBSTRING([Retailer Name], CHARINDEX(('MDNP'), [Retailer Name]), LEN([Retailer Name])),0,charindex('-',SUBSTRING([Retailer Name], CHARINDEX(('MDNP'), [Retailer Name]), LEN([Retailer Name])),0)) 
                   --when [Retailer Name] like '%MLDA%' 
                   --then SUBSTRING(SUBSTRING([Retailer Name], CHARINDEX(('MLDA'), [Retailer Name]), LEN([Retailer Name])),0,charindex('-',SUBSTRING([Retailer Name], CHARINDEX(('MLDA'), [Retailer Name]), LEN([Retailer Name])),0)) 
                   --end  
                   Substring(( [retailer code] ), 0, 
                   Charindex('-', ( [retailer code] 
                                  )) 
                   ) 
                   depocode, 
                   [retailer name], 
                   [area name], 
                   [hq], 
                   [user name], 
                   [anm], 
                   [rnm], 
                   [division], 
                   [item name], 
                   [pack size], 
                   [qty], 
                   [rate], 
                   [pob], 
                   [city], 
                   [state], 
                   [zone] 
            FROM   @order 

            --update  [dbo].swilorder  set [Retailer Code]   
            --=SUBSTRING(([Retailer Code]),0,CHARINDEX('-',([Retailer Code])))++reverse(left(reverse([Retailer Name]), charindex('-', reverse([Retailer Name]))))   
            UPDATE swilorder 
            SET    swilorder.[item code] = [swilproductcode].[code] 
            FROM   [swilorder] 
                   INNER JOIN [swilproductcode] 
                           ON [swilorder].[item name] = 
                              [swilproductcode].[items] 
                              AND swilorder.[pack size] = 
                                  [swilproductcode].[package size] 
          UPDATE swilorder 
            SET    swilorder.[retailer code] = [swilorderparty].[Correct Code] 
            FROM   [swilorder] 
                   INNER JOIN [swilorderparty] 
                           ON [swilorder].[retailer code] = 
                              [swilorderparty].[Salemastroz code] 
                              

