/* Functional group: 99_UNRELATED_DEMO_LEGACY; referenced grouped tables: TestImage */
/****** Object:  StoredProcedure [dbo].[TestImageLoad]    Script Date: 15-08-2026 12:36:08 ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE Procedure [dbo].[TestImageLoad]
	@FileName AS VARCHAR(200)
AS
BEGIN

	DECLARE @SQL VARCHAR(500)

	SET @SQL = 'INSERT INTO TestImage '
				+ 'SELECT CAST(bulkcolumn AS VARBINARY(MAX)) '
				+ ' FROM OPENROWSET( '
				+ '			BULK '
				+ '''' + @FileName + ''''
				+ '			,SINGLE_BLOB '
				+ '	) AS x   '

	EXEC (@SQL)

END
GO


